def _empreinte_build() -> str:
    """Repère du code RÉELLEMENT en cours d'exécution.

    Le fichier sur disque et le processus en mémoire peuvent diverger : copier
    cassandra.py sans redémarrer laisse tourner l'ancienne version, et alors
    toute recherche de défaut porte sur du code qui ne s'exécute pas. On perd
    des heures à ça. Cette empreinte le dit d'un coup d'œil."""
    try:
        import hashlib
        chemin = os.path.abspath(__file__)
        h = hashlib.sha256(open(chemin, "rb").read()).hexdigest()[:8]
        mt = datetime.fromtimestamp(os.path.getmtime(chemin)).strftime("%d/%m %H:%M")
        return "%s · %s" % (h, mt)
    except Exception:
        return "inconnue"
# ── LE PROFIL (L3, gravé D6) ─────────────────────────────────────────────────
# Ce noyau vit ICI, en tête du fichier, parce que le décorateur `profil_mesurer` enveloppe des
# fonctions définies bien plus haut que le reste du moteur d'évolution : un décorateur s'évalue
# à la définition, pas à l'appel. La lecture du profil, les verdicts et les visites restent
# auprès de la porte. `get_db` n'est appelé qu'à l'exécution : l'ordre du fichier ne gêne pas.
# ── L3 : les mesures ─────────────────────────────────────────────────────────
# Gravé D6 (le profil réel : rien n'est chronométré là où le temps de l'humain passe ; le premier
# décorateur va sur l'appel modèle ; priorité = p95 × appels/jour × humain-en-attente ; seuil
# 10 % ET 50 ms sur le p95, n ≥ 30, 7 jours ; le silence est un verdict), t14 (la mesure APRÈS :
# médiane avant sur 7 jours, après sur 24 h, jumelles de non-régression, jamais « neutral »),
# t18 (function_metrics horaire), t40 (le coût par opération logique), D14 (la visite à J+30 :
# chaque pièce vivante re-mesurée contre sa propre hypothèse).

_PROFIL_TAMPON = {}                    # (nom, humain) -> [durées_ms]
_PROFIL_LOCK = threading.Lock()
_PROFIL_DERNIER_VIDAGE = [time.time()]   # jamais 0 : sinon le tout premier appel déclenche un vidage
_PROFIL_PERIODE = 300                  # cinq minutes : une ligne horaire se remplit en douze fois
_EVO_SEUIL_GAIN_PCT = 10               # un gain vaut la peine à 10 % ET 50 ms sur le p95 (D6)
_EVO_SEUIL_GAIN_MS = 50
_EVO_SEUIL_N = 30                      # jamais de verdict sous trente mesures
_EVO_VISITE_JOURS = 30                 # l'anniversaire d'une pièce (D14)


def _profil_noter(nom: str, ms: float, humain: bool = False, erreur: bool = False) -> None:
    """Une durée mesurée. Coût mesuré au débat : 2,1 µs par appel — le tampon est en mémoire,
    l'écriture en base se fait par tranche de cinq minutes (t18 : agrégat horaire)."""
    try:
        with _PROFIL_LOCK:
            d = _PROFIL_TAMPON.setdefault((nom, bool(humain)), {"ms": [], "err": 0})
            d["ms"].append(float(ms))
            if erreur:
                d["err"] += 1
            vider = (time.time() - _PROFIL_DERNIER_VIDAGE[0]) > _PROFIL_PERIODE and _PROFIL_TAMPON
            if vider:
                lot, _PROFIL_DERNIER_VIDAGE[0] = dict(_PROFIL_TAMPON), time.time()
                _PROFIL_TAMPON.clear()
        if vider:
            threading.Thread(target=_profil_vider, args=(lot,), daemon=True, name="profil-vidage").start()
    except Exception:
        pass


_PROFIL_SEAUX = (1, 2, 5, 10, 25, 50, 100, 250, 500, 1000, 2500, 5000, 10000)


def _profil_seaux(valeurs) -> dict:
    """L'histogramme d'un lot de durées, à bornes fixes (ms). La dernière borne, « + », compte ce
    qui dépasse. Sommer les histogrammes de plusieurs heures redonne un quantile de la fenêtre —
    ce qu'un MAX de p95 horaires ne sait pas faire (relevé de Cassandra)."""
    h = {}
    for v in valeurs:
        for b in _PROFIL_SEAUX:
            if v <= b:
                h[str(b)] = h.get(str(b), 0) + 1
                break
        else:
            h["+"] = h.get("+", 0) + 1
    return h


def _profil_quantile_seaux(h: dict, q: float) -> float:
    """Le quantile q d'un histogramme cumulé : la borne du seau où le rang tombe. Conservateur
    (on rend la borne haute du seau), et honnête : la précision est celle des seaux."""
    total = sum(int(v or 0) for v in (h or {}).values())
    if total <= 0:
        return 0.0
    rang, cumul = q * total, 0
    for b in _PROFIL_SEAUX:
        cumul += int(h.get(str(b), 0) or 0)
        if cumul >= rang:
            return float(b)
    return float(_PROFIL_SEAUX[-1]) if not h.get("+") else float(_PROFIL_SEAUX[-1] * 2)


def _profil_seaux_fusion(a: dict, b: dict) -> dict:
    out = dict(a or {})
    for k, v in (b or {}).items():
        out[k] = int(out.get(k, 0) or 0) + int(v or 0)
    return out


def _profil_p(valeurs, q: float) -> float:
    """Le quantile q d'une liste (interpolation basse) : p50 et p95 sans dépendance."""
    if not valeurs:
        return 0.0
    v = sorted(valeurs)
    i = min(len(v) - 1, max(0, int(round(q * (len(v) - 1)))))
    return round(v[i], 3)


def profil_vidage_periodique() -> int:
    """Vide le tampon si la période est passée, sans attendre un appel. Sans cela, sur une
    machine peu sollicitée, les mesures restaient en mémoire et mouraient au redémarrage : le
    vidage était accroché au PROCHAIN appel, qui pouvait ne jamais venir. Appelé par la boucle
    du daemon d'évolution (toutes les minutes). Rend le nombre de fonctions vidées."""
    try:
        with _PROFIL_LOCK:
            if not _PROFIL_TAMPON or (time.time() - _PROFIL_DERNIER_VIDAGE[0]) <= _PROFIL_PERIODE:
                return 0
            lot, _PROFIL_DERNIER_VIDAGE[0] = dict(_PROFIL_TAMPON), time.time()
            _PROFIL_TAMPON.clear()
        _profil_vider(lot)
        return len(lot)
    except Exception:
        return 0


def _profil_vider(lot: dict) -> None:
    """Le tampon devient des lignes horaires de `function_metrics` (t18) : une ligne par
    (heure, fonction), cumulée. Quatre-vingt-dix jours, puis la ligne s'efface."""
    try:
        heure = datetime.now().strftime("%Y-%m-%dT%H")
        conn = get_db()
        try:
            for (nom, humain), d in lot.items():
                ms = d["ms"]
                if not ms:
                    continue
                r = conn.execute("SELECT appels, duree_ms_total, p95_ms, erreurs, seaux FROM function_metrics WHERE heure=? AND fonction=?",
                                 (heure, nom)).fetchone()
                total, n, p95 = sum(ms), len(ms), _profil_p(ms, 0.95)
                seaux = _profil_seaux(ms)
                if r:
                    try:
                        seaux = _profil_seaux_fusion(json.loads(r["seaux"] or "{}"), seaux)
                    except Exception:
                        pass
                    conn.execute("UPDATE function_metrics SET appels=appels+?, duree_ms_total=duree_ms_total+?, "
                                 "p95_ms=MAX(p95_ms,?), erreurs=erreurs+?, humain=?, seaux=? WHERE heure=? AND fonction=?",
                                 (n, total, p95, d["err"], 1 if humain else 0, json.dumps(seaux), heure, nom))
                else:
                    conn.execute("INSERT INTO function_metrics (heure, fonction, appels, duree_ms_total, p50_ms, p95_ms, "
                                 "max_ms, erreurs, humain, seaux) VALUES (?,?,?,?,?,?,?,?,?,?)",
                                 (heure, nom, n, total, _profil_p(ms, 0.5), p95, round(max(ms), 3), d["err"],
                                  1 if humain else 0, json.dumps(seaux)))
            conn.execute("DELETE FROM function_metrics WHERE heure < ?", ((datetime.now() - timedelta(days=90)).strftime("%Y-%m-%dT%H"),))
            conn.commit()
        finally:
            conn.close()
    except Exception as e:
        logging.debug("[PROFIL] vidage : %s", e)


def profil_mesurer(nom: str, humain: bool = False):
    """Le décorateur du profil. `humain` dit si quelqu'un attend derrière (D6 : la priorité est
    p95 × appels × humain-en-attente ; un battement de cœur n'est jamais une cible)."""
    def _deco(fn):
        import functools

        @functools.wraps(fn)
        def _w(*a, **k):
            t0 = time.perf_counter()
            err = False
            try:
                return fn(*a, **k)
            except Exception:
                err = True
                raise
            finally:
                _profil_noter(nom, (time.perf_counter() - t0) * 1000.0, humain, err)
        _w._profile = nom
        return _w
    return _deco


