def _hash_pwd(pwd: str) -> str:
    return hashlib.sha256(pwd.encode()).hexdigest()

def load_users() -> dict:
    """Retourne {email: record}. record = {hash, role, sites}. Fichier absent → {}.
    Compat : une valeur string (ancien format) est lue comme un hash (rôle admin)."""
    try:
        with open(CASSANDRA_USERS_FILE, "r") as f:
            d = json.load(f)
            return d.get("users", d) if isinstance(d, dict) else {}
    except Exception:
        return {}

def save_users(users: dict) -> bool:
    try:
        Path(CASSANDRA_USERS_FILE).parent.mkdir(parents=True, exist_ok=True)
        tmp = CASSANDRA_USERS_FILE + ".tmp"
        with open(tmp, "w") as f:
            json.dump({"users": users}, f, indent=2)
        os.chmod(tmp, 0o600)
        os.replace(tmp, CASSANDRA_USERS_FILE)
        return True
    except Exception as e:
        print(f"[AUTH] Erreur écriture users: {e}")
        return False

# ── Rôles & domaines (RBAC) ────────────────────────────────────────────────────
#   record = {"hash": <sha256>, "role": "admin"|"user", "sites": ["exemple.com", ...]}
#   Rétro-compat : un ancien hash brut (string) est interprété comme un ADMIN.
def _norm_domain(d: str) -> str:
    d = (d or "").strip().lower()
    for p in ("http://", "https://"):
        if d.startswith(p):
            d = d[len(p):]
    d = d.split("/")[0]
    if d.startswith("www."):
        d = d[4:]
    return d

def _user_record(value) -> dict:
    """Normalise une valeur stockée → {hash, role, sites, fp_account}."""
    if isinstance(value, str):
        return {"hash": value, "role": "admin", "sites": [], "fp_account": "",
                "display_name": "", "role_label": "", "contact_email": "", "phone": "", "lang": "fr"}
    if isinstance(value, dict):
        return {"hash": value.get("hash", ""),
                "role": value.get("role", "user"),
                "sites": [_norm_domain(s) for s in (value.get("sites") or []) if s],
                # Compte FastPanel adossé : les sites qu'il possède deviennent
                # ceux de ce compte Cassandra, sans les ressaisir.
                "fp_account": str(value.get("fp_account") or "").strip(),
                # Présentation, pas droits : un nom lisible et une fonction.
                "display_name": str(value.get("display_name") or "").strip(),
                "role_label": str(value.get("role_label") or "").strip(),
                # Coordonnées (maquette du 16-09) : un courriel de contact qui peut différer de
                # l'identifiant, un téléphone, la langue de l'écran et des courriels.
                "contact_email": str(value.get("contact_email") or "").strip(),
                "phone": str(value.get("phone") or "").strip(),
                "lang": (str(value.get("lang") or "fr").strip().lower()[:5] or "fr")}
    return {"hash": "", "role": "user", "sites": [], "fp_account": "",
            "display_name": "", "role_label": "", "contact_email": "", "phone": "", "lang": "fr"}


_PORTRAIT_MIMES = {"image/png": "png", "image/jpeg": "jpg", "image/webp": "webp"}
_PORTRAIT_MAX = 2 * 1024 * 1024
_PORTRAITS_DIR = CASSANDRA_DATA_DIR + "/portraits"


def _portrait_chemin(email: str, ext: str = "") -> str:
    """Le fichier du portrait d'un compte : une empreinte, jamais l'adresse en clair dans un nom."""
    import hashlib as _h
    base = _PORTRAITS_DIR + "/" + _h.sha256((email or "").strip().lower().encode()).hexdigest()[:24]
    if ext:
        return base + "." + ext
    for e in _PORTRAIT_MIMES.values():
        if os.path.isfile(base + "." + e):
            return base + "." + e
    return ""


def me_photo_lire(email: str) -> str:
    """Le portrait posé, en data-URL ; vide s'il n'y en a pas."""
    p = _portrait_chemin(email)
    if not p:
        return ""
    try:
        import base64 as _b
        ext = p.rsplit(".", 1)[-1]
        mime = {v: k for k, v in _PORTRAIT_MIMES.items()}.get(ext, "image/png")
        with open(p, "rb") as f:
            return "data:%s;base64,%s" % (mime, _b.b64encode(f.read()).decode("ascii"))
    except Exception as e:
        logging.info("[PROFIL] portrait illisible : %s", e)
        return ""


def me_photo_poser(email: str, data_url: str) -> dict:
    """Pose le portrait d'un compte depuis une data-URL (png, jpeg ou webp, 2 Mo au plus). Le
    navigateur l'a déjà recadrée en carré ; ici on vérifie le type par les premiers octets, jamais
    par ce que dit l'en-tête, et on écrit le fichier — pas la base."""
    import base64 as _b
    email = (email or "").strip().lower()
    if not email:
        return {"ok": False, "error": "compte requis"}
    s = str(data_url or "")
    if not s.startswith("data:") or ";base64," not in s[:64]:
        return {"ok": False, "error": "image attendue (data-URL)"}
    try:
        brut = _b.b64decode(s.split(";base64,", 1)[1], validate=True)
    except Exception:
        return {"ok": False, "error": "image illisible"}
    if len(brut) > _PORTRAIT_MAX:
        return {"ok": False, "error": "2 Mo au plus"}
    if brut[:8] == b"\x89PNG\r\n\x1a\n":
        ext = "png"
    elif brut[:3] == b"\xff\xd8\xff":
        ext = "jpg"
    elif brut[:4] == b"RIFF" and brut[8:12] == b"WEBP":
        ext = "webp"
    else:
        return {"ok": False, "error": "PNG, JPEG ou WebP seulement"}
    try:
        me_photo_retirer(email)
        p = _portrait_chemin(email, ext)
        os.makedirs(os.path.dirname(p), exist_ok=True)
        tmp = p + ".tmp"
        with open(tmp, "wb") as f:
            f.write(brut)
        os.chmod(tmp, 0o600)
        os.replace(tmp, p)
        return {"ok": True, "octets": len(brut), "format": ext}
    except Exception as e:
        return {"ok": False, "error": "écriture impossible : %s" % e}


def me_photo_retirer(email: str) -> dict:
    p = _portrait_chemin(email)
    if p:
        try:
            os.unlink(p)
        except Exception as e:
            return {"ok": False, "error": str(e)}
    return {"ok": True, "retire": bool(p)}

def get_user_record(email: str) -> dict:
    return _user_record(load_users().get((email or "").strip().lower()))

def user_role(email: str) -> str:
    return get_user_record(email).get("role", "user")

_IS_ADMIN_AVERTI = [False]


def is_admin(email: str) -> bool:
    if not load_users():
        # Avant le setup, l'accès de secours est admin. Un fichier de comptes PRÉSENT mais
        # illisible, ou disparu après le setup, n'est pas « avant le setup » : ce serait une
        # élévation par perte de fichier (fil 29, 20-09). Refus, et une trace, une fois.
        if _needs_setup():
            return True
        if not _IS_ADMIN_AVERTI[0]:
            _IS_ADMIN_AVERTI[0] = True
            try:
                logging.warning("[AUTH] fichier des comptes vide ou illisible alors que le serveur est "
                                "configuré : aucun accès administrateur de secours (%s)", CASSANDRA_USERS_FILE)
            except Exception:
                pass
        return False
    return user_role(email) == "admin"

_FP_COMPTE_SITES = {"t": 0.0, "map": {}}


def fp_comptes_sites(rafraichir: bool = False) -> dict:
    """Compte FastPanel → domaines qu'il possède.

    FastPanel connaît déjà le propriétaire de chaque site (`site.owner_id`).
    Le redemander à l'utilisateur, domaine par domaine, revenait à ressaisir ce
    que le panneau sait — et à se tromper dès qu'un site change de main."""
    if not rafraichir and _FP_COMPTE_SITES["map"] and \
            time.time() - _FP_COMPTE_SITES["t"] < 120:
        return _FP_COMPTE_SITES["map"]
    out = {}
    try:
        for r in _fp_db_query(
                "SELECT lower(p.username), s.domain FROM site s "
                "JOIN panel_account p ON s.owner_id = p.id "
                "WHERE s.domain IS NOT NULL AND s.domain <> ''"):
            if r and r[0]:
                out.setdefault(r[0], []).append(_norm_domain(r[1]))
    except Exception as e:
        # Au démarrage, la base du panneau peut n'être pas encore lisible : on
        # rend le cache précédent plutôt que d'effacer les accès de chacun.
        logging.debug("[FP-LIEN] lecture des propriétaires : %s", e)
        return _FP_COMPTE_SITES["map"]
    for k in out:
        out[k] = sorted(set(out[k]))
    _FP_COMPTE_SITES.update({"t": time.time(), "map": out})
    return out


def user_sites(email: str) -> list:
    """Domaines d'un compte : ceux saisis, plus ceux de son compte FastPanel.

    L'union est calculée à la lecture et non recopiée dans `users.json` : un
    site ajouté dans FastPanel est ainsi visible tout de suite, et un site qui
    change de propriétaire cesse de l'être — une copie aurait dérivé."""
    rec = get_user_record(email)
    sites = set(rec.get("sites", []))
    compte = rec.get("fp_account", "")
    if compte:
        sites.update(fp_comptes_sites().get(compte.lower(), []))
    return sorted(sites)


def user_sites_detail(email: str) -> dict:
    """Même chose, mais en disant d'où vient chaque domaine."""
    rec = get_user_record(email)
    propres = sorted(set(rec.get("sites", [])))
    compte = rec.get("fp_account", "")
    herites = sorted(set(fp_comptes_sites().get(compte.lower(), []))) if compte else []
    return {"explicites": propres, "fp_account": compte,
            "herites": [d for d in herites if d not in propres],
            "tous": sorted(set(propres) | set(herites))}

def set_user_fp_account(email: str, compte: str) -> dict:
    """Adosse un compte Cassandra à un compte FastPanel. Compte vide = détache.

    Le lien donne accès à TOUS les sites que ce compte possède dans le panneau,
    y compris ceux qui y seront ajoutés plus tard. C'est l'intérêt — et la
    raison pour laquelle il n'est pas posé automatiquement."""
    email = (email or "").strip().lower()
    compte = (compte or "").strip()
    users = load_users()
    if email not in users:
        return {"ok": False, "error": "Utilisateur inconnu"}
    if compte:
        if not re.match(r"^[A-Za-z0-9._\-]{1,64}$", compte):
            return {"ok": False, "error": "Nom de compte FastPanel invalide"}
        connus = fp_comptes_sites(rafraichir=True)
        if compte.lower() not in connus:
            # Un compte sans site est légitime ; un compte inexistant, non.
            existe = False
            try:
                existe = bool(_fp_db_query(
                    "SELECT 1 FROM panel_account WHERE lower(username)=? LIMIT 1",
                    (compte.lower(),)))
            except Exception as e:
                logging.info("[FP-LIEN] vérification du compte : %s", e)
            if not existe:
                return {"ok": False, "error": "Compte « %s » inconnu de FastPanel" % compte}
    rec = _user_record(users[email])
    rec["fp_account"] = compte
    users[email] = rec
    if not save_users(users):
        return {"ok": False, "error": "Échec écriture users.json"}
    detail = user_sites_detail(email)
    try:
        log_admin_action("", "user_fp_link", "OK",
                         "user=%s compte=%s sites=%d" % (email, compte or "(aucun)",
                                                         len(detail["herites"])))
    except Exception as e:
        logging.debug("[AUDIT] %s", e)
    return {"ok": True, "username": email, "fp_account": compte,
            "herites": detail["herites"],
            "output": ("Détaché de FastPanel." if not compte else
                       "%s adossé à « %s » : %d site(s) repris."
                       % (email, compte, len(detail["herites"])))}


def fp_liens_suggeres() -> dict:
    """Rapprochements évidents entre comptes Cassandra et comptes FastPanel.

    Deux indices suffisent et se vérifient : une adresse identique des deux
    côtés, ou un compte FastPanel unique qui possède le domaine de l'adresse.
    On PROPOSE — lier donne des accès, ce n'est pas à la machine de le décider."""
    try:
        comptes = _fp_users_riches() or []
    except Exception as e:
        return {"ok": False, "reason": str(e)[:150], "suggestions": []}
    par_mail = {}
    for c in comptes:
        m = str(c.get("email") or c.get("restore_email") or "").strip().lower()
        if m:
            par_mail.setdefault(m, []).append(str(c.get("username") or ""))
    sites = fp_comptes_sites(rafraichir=True)
    out = []
    for email, brut in (load_users() or {}).items():
        rec = _user_record(brut)
        if rec.get("fp_account"):
            continue
        propose, motif = "", ""
        if email in par_mail and len(par_mail[email]) == 1:
            propose, motif = par_mail[email][0], "même adresse de courriel"
        else:
            domaine = email.split("@")[-1] if "@" in email else ""
            porteurs = [c for c, ds in sites.items() if domaine and domaine in ds]
            if domaine and len(porteurs) == 1:
                propose = porteurs[0]
                motif = "seul compte propriétaire de %s" % domaine
        if propose:
            out.append({"user": email, "fp_account": propose, "motif": motif,
                        "sites": sites.get(propose.lower(), [])})
    return {"ok": True, "suggestions": out,
            "comptes": sorted({str(c.get("username") or "") for c in comptes if c.get("username")})}


def user_owns_domain(email: str, domain: str) -> bool:
    if is_admin(email):
        return True
    return _site_est_a_moi(email, domain)


def _site_est_a_moi(email: str, domain: str) -> bool:
    """Le domaine, ou un sous-domaine, d'un site du compte — déclaré ou hérité du panneau.
    SANS passe-droit administrateur : c'est ce qui distingue « mon site » d'un site que
    l'admin peut voir et piloter sans en lire le contenu (fil 29)."""
    miens = {_norm_domain(x) for x in (user_sites(email) or []) if x}
    return _fp_appartient(domain, miens)


# ── Cloisonnement des lectures FastPanel (2026-09-05) ───────────────────────
# Toute session valide lisait /api/fp/users, backups, scans, crons, services,
# summary : la liste des comptes du panneau, les sauvegardes et les tâches de
# TOUT le serveur, servies à un compte qui ne possède qu'un site. Même règle
# que /api/site/availability : l'admin voit tout ; un compte ordinaire ne voit
# que ce qui se rattache à ses sites (`user_sites`), et ce qui n'a pas de site
# (comptes, sauvegardes, analyses, tâches, services, résumé, statistiques du
# serveur, versions PHP installées) lui est REFUSÉ en clair, jamais servi vide.
_FP_GET_FILTREES = {"/api/fp/domains": "domain", "/api/fp/databases": "site",
                    "/api/fp/ftp": "site", "/api/fp/mail": "domain",
                    "/api/fp/dns": "zone", "/api/fp/ssl": ""}


def _fp_appartient(dom: str, miens) -> bool:
    """Le domaine lui-même, ou un sous-domaine d'un domaine du compte."""
    dom = _norm_domain(dom or "")
    if not dom or not miens:
        return False
    if dom in miens:
        return True
    return any(dom.endswith("." + m) for m in miens if m)


def _fp_ligne_du_compte(ligne: dict, cle: str, miens) -> bool:
    """Une ligne de section se rattache-t-elle à un site du compte ?

    Le rattachement se lit dans la colonne nommée ; à défaut, dans ce que la
    ligne porte d'autre (le domaine d'une adresse mail, le nom d'un
    enregistrement DNS, le répertoire d'un compte FTP). Une ligne qui ne se
    rattache à rien n'est PAS montrée : le doute ne joue jamais en faveur de
    la fuite."""
    v = str(ligne.get(cle) or "").strip() if cle else ""
    if _fp_appartient(v, miens):
        return True
    if cle == "domain" and "@" in str(ligne.get("email") or ""):
        return _fp_appartient(str(ligne["email"]).rsplit("@", 1)[1], miens)
    if cle == "zone":
        return _fp_appartient(str(ligne.get("name") or ""), miens)
    if cle == "site":
        rep = str(ligne.get("home_dir") or "")
        return any(("/" + m) in rep for m in miens if m)
    return False


def _fp_section_pour_compte(path: str, lire, user: str):
    """Lecture d'une section FastPanel restreinte aux sites d'un compte.

    Rend (statut HTTP, corps). Le refus est un 403 avec sa raison : un tableau
    vide aurait été lu comme « rien à signaler »."""
    if path not in _FP_GET_FILTREES:
        return 403, {"ok": False,
                     "reason": "Réservé aux administrateurs : cette lecture porte sur tout le serveur"}
    miens = {_norm_domain(x) for x in (user_sites(user) or []) if x}
    if path == "/api/fp/ssl":
        return 200, fp_ssl_overview(filtre_domaines=miens)
    result = lire()
    if not isinstance(result, list):
        return 200, result
    cle = _FP_GET_FILTREES[path]
    return 200, [l for l in result if isinstance(l, dict) and _fp_ligne_du_compte(l, cle, miens)]


def init_users():
    """Au premier démarrage : seed le compte 'admin' (rôle admin) depuis le hash existant."""
    users = load_users()
    if not users:
        admin_hash = get_admin_password_hash()
        if admin_hash:
            save_users({"admin": {"hash": admin_hash, "role": "admin", "sites": []}})
            print("[AUTH] users.json initialisé — compte 'admin' (rôle admin) créé")

def verify_user(username: str, password: str) -> bool:
    """Vérifie identifiant + mot de passe. Compat : si aucun user défini, accepte le hash admin
    (n'importe quel identifiant) pour ne jamais verrouiller l'accès pendant la migration."""
    username = (username or "").strip().lower()
    users = load_users()
    h = _hash_pwd(password)
    if username in users:
        return _user_record(users[username]).get("hash") == h
    if not users:  # aucun compte encore → fallback mot de passe admin
        return h == get_admin_password_hash()
    return False

_MDP_MIN, _MDP_MAX = 9, 20

# Chaque règle : sa clé, ce qu'on en dit à l'écran, et comment on la vérifie.
# La légende vient de cette table — elle ne peut donc pas promettre autre chose
# que ce qui est exigé.
_MDP_REGLES = (
    ("longueur",  "de %d à %d caractères" % (_MDP_MIN, _MDP_MAX),
     lambda p: _MDP_MIN <= len(p) <= _MDP_MAX),
    ("majuscule", "au moins une majuscule",
     lambda p: any(c.isupper() for c in p)),
    ("chiffre",   "au moins un chiffre",
     lambda p: any(c.isdigit() for c in p)),
    ("special",   "au moins un caractère spécial (!?#@…)",
     lambda p: any((not c.isalnum()) and not c.isspace() for c in p)),
)


def mdp_regles() -> list:
    """Ce que l'écran affiche. Pas de fonction ici : elles ne franchissent pas
    le JSON, et la vérification reste au serveur de toute façon."""
    return [{"cle": c, "dit": d} for c, d, _ in _MDP_REGLES]


def mdp_valider(pwd: str) -> dict:
    """Rend ce qui MANQUE, pas seulement un verdict.

    Un « mot de passe invalide » sans dire quoi oblige à deviner : on rend la
    liste des règles non satisfaites, et l'écran les montre une par une.
    """
    p = pwd or ""
    manque = [d for c, d, f in _MDP_REGLES if not f(p)]
    return {"ok": not manque, "manque": manque,
            "error": ("Mot de passe : il manque " + ", ".join(manque)) if manque else ""}


def mdp_legende() -> str:
    return "Il faut " + ", ".join(d for _, d, _ in _MDP_REGLES) + "."


def set_user(username: str, password: str, role: str = None, sites: list = None) -> dict:
    username = (username or "").strip().lower()
    # Un compte Cassandra = un compte Vault → l'identifiant doit être une adresse e-mail.
    if not _EMAIL_RE.match(username):
        return {"ok": False, "error": "Adresse e-mail invalide (ex : prenom@exemple.com)"}
    if len(username) > 120:
        return {"ok": False, "error": "Adresse e-mail trop longue"}
    # LE point de passage : création, réinitialisation par jeton et changement
    # depuis les paramètres appellent tous `set_user`. Vérifier ici, c'est
    # vérifier aux trois endroits sans écrire la règle trois fois.
    _v = mdp_valider(password)
    if not _v["ok"]:
        return {"ok": False, "error": _v["error"], "manque": _v["manque"]}
    users = load_users()
    existing = _user_record(users[username]) if username in users else None
    # Rôle : explicite si fourni ; sinon préserve l'existant ; sinon admin pour le 1er compte, user ensuite.
    if role in ("admin", "user"):
        new_role = role
    elif existing:
        new_role = existing["role"]
    else:
        new_role = "admin" if not users else "user"
    # Domaines : explicites si fournis ; sinon préserve l'existant ; sinon vide.
    if sites is not None:
        new_sites = sorted({_norm_domain(s) for s in sites if s})
    elif existing:
        new_sites = existing["sites"]
    else:
        new_sites = []
    users[username] = {"hash": _hash_pwd(password), "role": new_role, "sites": new_sites,
                       # Le lien FastPanel n'a rien à voir avec le mot de passe :
                       # le perdre à chaque changement retirerait des accès sans
                       # que personne ne comprenne pourquoi.
                       "fp_account": (existing or {}).get("fp_account", "")}
    if not save_users(users):
        return {"ok": False, "error": "Échec écriture users.json"}
    # Son dossier de notes existe dès maintenant. Il se créait auparavant à la
    # première visite : impossible d'y déposer quoi que ce soit d'avance, et un
    # administrateur qui prépare un espace pour quelqu'un n'avait nulle part où
    # le mettre. L'échec ne bloque pas la création du compte — le dossier se
    # recrée tout seul au premier accès.
    try:
        _d = compte_dossier_creer(username)
        if not _d.get("ok"):
            logging.warning("[COMPTES] dossier de %s : %s", username, _d.get("reason"))
    except Exception as _e:
        logging.warning("[COMPTES] dossier de %s : %s", username, _e)
    # Compte Cassandra = compte Vault : provisionne / aligne le coffre natif en arrière-plan.
    try:
        provision_user_vault_async(username, password)
    except Exception:
        pass
    # Nouveau compte → e-mail de bienvenue + lien de mise en place du mot de passe (best-effort).
    if existing is None:
        try:
            threading.Thread(target=send_welcome_email, args=(username, new_role, new_sites),
                             daemon=True).start()
        except Exception:
            pass
    return {"ok": True, "username": username, "role": new_role, "sites": new_sites}

def update_user_access(username: str, role: str = None, sites: list = None) -> dict:
    """Change le rôle et/ou les domaines d'un compte SANS toucher au mot de passe (admin)."""
    username = (username or "").strip().lower()
    users = load_users()
    if username not in users:
        return {"ok": False, "error": "Utilisateur inconnu"}
    rec = _user_record(users[username])
    if role in ("admin", "user"):
        rec["role"] = role
    if sites is not None:
        rec["sites"] = sorted({_norm_domain(s) for s in sites if s})
    # Anti-lock-out : ne pas retirer le dernier admin.
    if rec["role"] != "admin":
        admins = [e for e, v in users.items() if _user_record(v)["role"] == "admin" and e != username]
        if not admins:
            return {"ok": False, "error": "Impossible : ce serait le dernier administrateur"}
    users[username] = rec
    if not save_users(users):
        return {"ok": False, "error": "Échec écriture users.json"}
    return {"ok": True, "username": username, "role": rec["role"], "sites": rec["sites"]}

def delete_user(username: str) -> dict:
    users = load_users()
    if username not in users:
        return {"ok": False, "error": "Utilisateur inconnu"}
    if len(users) <= 1:
        return {"ok": False, "error": "Impossible de supprimer le dernier compte"}
    if _user_record(users[username])["role"] == "admin":
        admins = [e for e, v in users.items() if _user_record(v)["role"] == "admin"]
        if len(admins) <= 1:
            return {"ok": False, "error": "Impossible de supprimer le dernier administrateur"}
    users.pop(username, None)
    save_users(users)
    try:
        n = memoire_purger_compte(username)
        if n:
            logging.info("[MEMOIRE] compte %s supprimé : %d souvenir(s) expiré(s)", username, n)
    except Exception as e:
        logging.warning("[MEMOIRE] purge du compte %s : %s", username, e)
    return {"ok": True}

