def it_modele_creds(email: str):
    """(clé, modèle, URL) pour le modèle EN LIGNE de ce compte, ou None.

    Rend None dès qu'une pièce manque — et **jamais** la clé du serveur. C'est
    le même arbitrage que pour le repli IMAP, fermé en août 2026 : sans
    identifiants propres, on ne se sert pas de ceux de la maison. Sinon
    l'administrateur paierait pour tout le monde, et plusieurs comptes
    partageraient une facturation.
    """
    email = (email or "").strip().lower()
    prov = it_fournisseur_lire(email)
    if not prov or prov == _FOURNISSEUR_LOCAL:
        return None
    modele = it_modele_lire(email)
    if not modele:
        return None
    base = _SECONDARY_PROVIDERS.get(prov)
    if not base:
        return None
    try:
        d = vault_native_get(email, _IT_MODELE_SECRET)
    except Exception as e:
        logging.info("[ITARE] clé du compte illisible : %s", e)
        d = None
    cle = ((d or {}).get("password") or (d or {}).get("value") or "").strip()
    if not cle:
        return None
    return (cle, modele, base)


def it_modele_cle_ecrire(email: str, cle: str) -> dict:
    """Range (ou retire) la clé du compte. Une clé vide n'EFFACE pas."""
    email = (email or "").strip().lower()
    cle = str(cle or "").strip()
    if not email:
        return {"ok": False, "error": "compte requis"}
    if not cle:
        return {"ok": True, "inchange": True}
    try:
        vault_native_set_login(email, _IT_MODELE_SECRET, email, cle, "")
    except Exception as e:
        return {"ok": False, "error": "coffre indisponible : %s" % str(e)[:120]}
    return {"ok": True}


def it_modele_cle_retirer(email: str) -> dict:
    try:
        vault_native_delete((email or "").strip().lower(), _IT_MODELE_SECRET)
    except Exception as e:
        return {"ok": False, "error": str(e)[:140]}
    return {"ok": True}


def _lab_nuage_stream(creds, message: str, contexte: str = "", history=None):
    """Le modèle EN LIGNE d'un compte, par sa propre clé.

    `lab_chat_stream` ne parle qu'à Ollama : sans ce chemin, choisir un modèle
    en ligne n'aurait eu aucun effet — la demande serait partie chez Ollama
    avec un nom qu'il ne connaît pas.
    """
    cle, modele, base = creds
    try:
        from openai import OpenAI as _OAI
    except Exception:
        yield "⚠️ Le client OpenAI n'est pas installé sur cette machine."
        return
    msgs = []
    if contexte:
        msgs.append({"role": "system", "content": contexte})
    for h in (history or []):
        if isinstance(h, dict) and h.get("role") in ("user", "assistant"):
            msgs.append({"role": h["role"], "content": str(h.get("content") or "")})
    msgs.append({"role": "user", "content": message or ""})
    try:
        cl = _OAI(api_key=cle, base_url=base, timeout=120.0)
        flux = cl.chat.completions.create(model=modele, messages=msgs, stream=True)
        for bout in flux:
            try:
                t = (bout.choices[0].delta.content or "")
            except Exception:
                t = ""
            if t:
                yield t
    except Exception as e:
        # On ne dit PAS la clé, ni l'URL : seulement que ça n'a pas répondu.
        yield "\n\n⚠️ Votre modèle en ligne n'a pas répondu (%s)." % type(e).__name__


def it_modele_etat(email: str) -> dict:
    """Ce que la carte affiche. La clé n'en sort JAMAIS — seulement sa présence."""
    email = (email or "").strip().lower()
    prov = it_fournisseur_lire(email)
    a_cle = False
    try:
        d = vault_native_get(email, _IT_MODELE_SECRET)
        a_cle = bool((d or {}).get("password") or (d or {}).get("value"))
    except Exception:
        a_cle = False
    return {"fournisseur": prov, "a_cle": a_cle,
            "fournisseurs": sorted(_SECONDARY_PROVIDERS.keys()),
            # Réglé sur du nuage SANS clé : le compte retombe sur un modèle
            # local sans le savoir. On le dit plutôt que de le laisser croire
            # qu'il est servi par son fournisseur.
            "muet": bool(prov and prov != _FOURNISSEUR_LOCAL and not a_cle)}


def it_modeles_offerts(email: str) -> dict:
    """Ce qu'un compte a le droit de savoir : les NOMS installés et son choix.
    Surtout pas `lab_status()`, qui décrit la machine — RAM, GPU, catalogue."""
    try:
        noms = [m["name"] for m in ollama_list()]
    except Exception:
        noms = []
    # LE VRAI DÉFAUT n'est pas `lab_model` — celui-ci n'est que le modèle LOCAL
    # choisi dans l'atelier, et il ne sert que si on le désigne explicitement.
    # Sans choix, `/api/lab/chat` passe par l'AGENT SECONDAIRE : c'est lui le
    # défaut, et il est souvent distant. Annoncer l'autre, c'était afficher un
    # modèle local à quelqu'un qui parle à un modèle cloud.
    defaut, distant = "", False
    try:
        _c = get_cassandra_config()
        _p = (_c.get("itare_provider") or "").strip()
        _m = (_c.get("itare_model") or "").strip()
        if _p or _m:
            defaut = (_p + (" · " + _m if _m else "")) if _p else _m
            distant = _p not in ("", "ollama")
        else:
            # Pas d'agent secondaire : le modèle local prend le relais.
            defaut = (_c.get("lab_model") or "").strip()
    except Exception:
        defaut = ""
    return {"ok": True, "modeles": noms, "modele": it_modele_lire(email),
            "maison": defaut, "distant": distant}


def it_persona_ecrire(email: str, texte: str) -> dict:
    """Écrit le ton de ce compte. Vide = revenir au ton de l'instance."""
    email = (email or "").strip().lower()
    if not email:
        return {"ok": False, "error": "compte requis"}
    texte = (texte or "").strip()[:_UC_PERSONA_MAX]
    conn = None
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        _ensure_user_prefs_table(conn)
        _uc_migrer(conn)
        conn.execute("INSERT INTO user_prefs (username, persona) VALUES (?,?) "
                     "ON CONFLICT(username) DO UPDATE SET persona=excluded.persona",
                     (email, texte))
        conn.commit()
        return {"ok": True, "persona": texte}
    except Exception as e:
        return {"ok": False, "error": str(e)}
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


# Les genres qu'une personne peut couper. Ce qui n'est PAS ici part toujours :
# la bienvenue et la réinitialisation de mot de passe sont transactionnelles, et
# les couper laisserait quelqu'un dehors sans recours.
_UC_NOTIFS = {
    "recap":  {"n": "Récapitulatif hebdomadaire",
               "d": "Ce que Cassandra a fait de votre semaine, une fois par semaine.",
               "defaut": True},
    "session": {"n": "Connexion inhabituelle",
                "d": "Quand une session s'ouvre depuis internet alors que les "
                     "précédentes venaient du réseau local.",
                "defaut": True},
    "site":   {"n": "Actions sur mes sites",
               "d": "Certificat renouvelé, backend redémarré, site injoignable.",
               "defaut": True},
}


def uc_notifs_lire(email: str) -> dict:
    """L'état de chaque genre pour ce compte, défauts compris. On rend TOUJOURS
    la carte complète : un genre ajouté plus tard apparaît à son défaut, sans
    migration."""
    brut = {}
    try:
        brut = json.loads(_uc_champ_lire(email, "notifs") or "{}")
    except Exception:
        brut = {}
    return {k: (bool(brut[k]) if k in brut else v["defaut"])
            for k, v in _UC_NOTIFS.items()}


def uc_notifs_ecrire(email: str, etats: dict) -> dict:
    email = (email or "").strip().lower()
    if not email:
        return {"ok": False, "error": "compte requis"}
    # Seuls les genres DÉCLARÉS entrent : sinon la colonne accueillerait
    # n'importe quelle clé venue du navigateur.
    cur = uc_notifs_lire(email)
    for k in _UC_NOTIFS:
        if isinstance(etats, dict) and k in etats:
            cur[k] = bool(etats[k])
    conn = None
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        _ensure_user_prefs_table(conn)
        _uc_migrer(conn)
        conn.execute("INSERT INTO user_prefs (username, notifs) VALUES (?,?) "
                     "ON CONFLICT(username) DO UPDATE SET notifs=excluded.notifs",
                     (email, json.dumps(cur)))
        conn.commit()
        return {"ok": True, "notifs": cur}
    except Exception as e:
        return {"ok": False, "error": str(e)}
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


def notify_user_email(email: str, subject: str, title: str, body_html: str,
                      cta_label: str = "", cta_url: str = "", force: bool = False,
                      genre: str = "") -> bool:
    """Envoie un e-mail à un user en respectant ses préférences.

    `force=True` = transactionnel critique, part quoi qu'il arrive. `genre`
    désigne une entrée de `_UC_NOTIFS` : un envoi sans genre reste soumis au
    seul opt-out global, comme avant.
    """
    if force:
        return cassandra_send_mail(email, subject, title, body_html, cta_label, cta_url)
    if not user_email_enabled(email):
        return False
    if genre and genre in _UC_NOTIFS and not uc_notifs_lire(email).get(genre, True):
        return False
    return cassandra_send_mail(email, subject, title, body_html, cta_label, cta_url)

