# ── Récap hebdomadaire (digest des actions de Cassandra) ───────────────────────
_RECAP_LAST = [0.0]

def _recap_due() -> bool:
    """Vrai si le récap hebdo doit partir : >7 j depuis le dernier (persisté en config),
    et on est le jour préféré (par défaut lundi) passé l'heure préférée (par défaut 8 h)."""
    try:
        last = _RECAP_LAST[0] or float(get_cassandra_config().get("mail_recap_last_ts") or 0)
    except Exception:
        last = _RECAP_LAST[0]
    now = time.time()
    if now - last < 7 * 86400 - 3600:   # tolérance d'1 h pour ne pas rater le créneau
        return False
    try:
        cfg = get_cassandra_config()
        want_day = int(cfg.get("mail_recap_day", 0))    # 0 = lundi
        want_hour = int(cfg.get("mail_recap_hour", 8))
    except Exception:
        want_day, want_hour = 0, 8
    n = datetime.now()
    return n.weekday() == want_day and n.hour >= want_hour

def _ts_within_days(ts: str, days: int) -> bool:
    try:
        dt = datetime.strptime((ts or "")[:19], "%Y-%m-%d %H:%M:%S")
        return (_utcnow() - dt).total_seconds() <= days * 86400
    except Exception:
        return False

def _recap_admin_body() -> str:
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        since = (_utcnow() - timedelta(days=7)).strftime("%Y-%m-%d %H:%M:%S")
        def _c(q, *a):
            try:
                return conn.execute(q, a).fetchone()[0]
            except Exception:
                return 0
        ncmd = _c("SELECT COUNT(*) FROM agent_actions WHERE ts >= ?", since)
        nrisk = _c("SELECT COUNT(*) FROM agent_actions WHERE ts >= ? AND is_risky=1", since)
        nnew = _c("SELECT COUNT(*) FROM proactive_findings WHERE first_seen >= ?", since)
        nres = _c("SELECT COUNT(*) FROM proactive_findings WHERE status='resolved' AND last_seen >= ?", since)
        conn.close()
        return ("Sur les 7 derniers jours, Cassandra a veillé sur votre infrastructure :"
                "<ul><li><b>%d</b> actions exécutées (dont %d sensibles, vérifiées sous garde)</li>"
                "<li><b>%d</b> nouveaux signalements proactifs</li>"
                "<li><b>%d</b> problèmes résolus automatiquement</li></ul>"
                "Tout va bien tant que cette liste reste calme. &#127769;" % (ncmd, nrisk, nnew, nres))
    except Exception as e:
        return "Résumé indisponible (%s)." % e

def send_weekly_recaps() -> dict:
    """Envoie le digest hebdo : à chaque user (ses sites) + à l'admin (la flotte)."""
    if not mail_configured():
        return {"ok": False, "reason": "mail non configuré", "sent": 0}
    sent = 0
    base = _app_public_url()
    cta = ("Voir mon espace", base) if base else ("", "")
    users = load_users()
    for email, v in users.items():
        rec = _user_record(v)
        if rec["role"] == "admin":
            continue
        acts = [a for a in get_user_activity(email, 100)
                if a.get("actor") == "cassandra" and _ts_within_days(a.get("ts", ""), 7)]
        if not acts:
            continue
        items = "".join("<li>%s &middot; <span style='color:#9a9ab5'>%s</span></li>"
                        % (_site_action_label(a.get("action", "")), a.get("detail", "")) for a in acts[:20])
        body = ("Voici ce que Cassandra a fait sur vos sites cette semaine :<ul>%s</ul>" % items)
        if notify_user_email(email, "Cassandra · votre semaine", "Votre récap hebdomadaire &#128202;",
                             body, cta[0], cta[1], genre="recap"):
            sent += 1
    admin_body = _recap_admin_body()
    for email, v in users.items():
        if _user_record(v)["role"] != "admin":
            continue
        if notify_user_email(email, "Cassandra · récap de la semaine", "Récap hebdomadaire &#128202;",
                             admin_body, cta[0], cta[1], force=True):
            sent += 1
    _RECAP_LAST[0] = time.time()
    try:
        cfg = get_cassandra_config(); cfg["mail_recap_last_ts"] = _RECAP_LAST[0]; save_cassandra_config(cfg)
    except Exception:
        pass
    return {"ok": True, "sent": sent}


def notify_via_webhook(message: str, severity: str):
    """Envoie un webhook JSON (Slack/Discord/Ntfy/générique)."""
    cfg = load_alert_config().get("webhook", {})
    if not cfg.get("enabled"):
        return
    url = cfg.get("url", "")
    if not url:
        return
    try:
        hostname = _socket_mod.gethostname()
        template = cfg.get("payload_template", '{"text": "[{severity}] {host}: {message}"}')
        payload  = template.format(
            message=message.replace('"', '\"'),
            severity=severity.upper(),
            host=hostname,
            ts=datetime.now().isoformat(),
        ).encode("utf-8")
        headers  = {"Content-Type": "application/json"}
        headers.update(cfg.get("headers", {}) or {})
        req = urllib.request.Request(url, data=payload, headers=headers, method="POST")
        with urllib.request.urlopen(req, timeout=8) as resp:
            _ = resp.read()
        print(f"[ALERT] Webhook envoyé ({severity}): {message[:80]}")
    except Exception as e:
        print(f"[ALERT] Erreur webhook: {e}", file=sys.stderr)


def fire_alert(rule_name: str, level: str, category: str, message: str, channels=None):
    """Une règle de seuil qui se déclenche écrit UNE notification — et c'est la politique du centre qui
    décide de ce qui sort (mail, Telegram, webhook), personne par personne. Les `channels` codés en dur
    par règle ne décident plus rien : ils envoyaient un mail hors sourdine, hors heures calmes et hors
    opt-out, et le centre en envoyait parfois un second (B14). `channels` reste pour les appelants."""
    save_alert(level, category, message)


