# ============================================================
# 4. CACHE
# ============================================================
def get_cached_or_fetch(category: str, fetch_func, ttl: int = 5):
    now = time.time()
    if category in _detailed_cache and now - _detailed_cache_time.get(category, 0) < ttl:
        return _detailed_cache[category]
    data = fetch_func()
    _detailed_cache[category] = data
    _detailed_cache_time[category] = now
    return data


# ============================================================
# 5. DÉTECTION D'INTENTION
# ============================================================
KNOWN_CATEGORIES = ["sites", "remotes", "ssl", "processes", "sessions",
                    "ports", "oom", "failed", "tailscale", "fail2ban",
                    "health", "docker", "smart"]


def detect_intent_categories(user_question: str, expert_mode: bool = False) -> list:
    if expert_mode:
        return KNOWN_CATEGORIES
    cache_key = hashlib.md5(user_question.encode()).hexdigest()
    now = time.time()
    if cache_key in _intent_cache and now - _intent_cache_time.get(cache_key, 0) < _INTENT_CACHE_TTL:
        return _intent_cache[cache_key]
    if not DEEPSEEK_API_KEY:
        return []
    try:
        resp = client.chat.completions.create(
            model=MODEL_NAME,
            messages=[{
                "role": "user",
                "content": f"Question: \"{user_question}\"\n\nParmi ces catégories: {', '.join(KNOWN_CATEGORIES)}\nRetourne UNIQUEMENT un JSON array. Ex: [\"ssl\",\"sites\"]"
            }],
            temperature=0,
            max_tokens=80,
        )
        raw = _extract_msg_text(resp)
        raw = raw.replace("```json", "").replace("```", "").strip()
        cats = json.loads(raw)
        result = [c for c in cats if c in KNOWN_CATEGORIES]
    except Exception:
        result = []
    _intent_cache[cache_key] = result
    _intent_cache_time[cache_key] = now
    return result


# ============================================================
# 6. SOCKET
# ============================================================
def _recv_all(sock):
    chunks = []
    while True:
        chunk = sock.recv(65536)
        if not chunk:
            break
        chunks.append(chunk)
    return b"".join(chunks)


# ── LE GARDE DE RÉENTRANCE ────────────────────────────────────────────────────
#  Deux fonctions de lecture qui s'appellent l'une l'autre font mille niveaux,
#  une socket par niveau, puis un RecursionError que l'except du fond avale —
#  et chaque niveau « réussit » avec des données partielles (l'onglet
#  Automatismes en trente à quatre-vingts secondes, 2026-09-04). Le garde
#  tient la chaîne des lectures en cours dans ce fil : si la fonction appelée
#  y est déjà, il lève AVANT d'ouvrir quoi que ce soit, avec la chaîne entière,
#  et l'écrit en ERROR — un except d'en haut ne pourra pas la rendre muette.
_REENTRANCE = threading.local()


def _garde_reentrance(fn):
    nom = fn.__name__

    def _enrobee(*a, **k):
        chaine = getattr(_REENTRANCE, "chaine", None)
        if chaine is None:
            chaine = _REENTRANCE.chaine = []
        if nom in chaine:
            trajet = " → ".join(chaine + [nom])
            logging.error("[REENTRANCE] cercle de lectures : %s", trajet)
            raise RecursionError("cercle de lectures : " + trajet)
        chaine.append(nom)
        try:
            return fn(*a, **k)
        finally:
            chaine.pop()
    _enrobee.__name__ = nom
    _enrobee.__doc__ = fn.__doc__
    _enrobee.__wrapped__ = fn
    return _enrobee


# La dernière panne du collecteur, pour la DIRE avec les données (2026-09-05).
# Un collecteur tombé rendait None, que chaque lecteur transformait en liste
# vide : « aucun service », « aucune version PHP » — alors que personne
# n'avait répondu. Vidé dès qu'une commande aboutit.
_SOCKET_DERNIERE_ERREUR = {"message": "", "commande": "", "t": 0.0}


def _socket_request(command: str):
    try:
        sock = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
        sock.settimeout(5)
        sock.connect(COLLECTOR_SOCKET)
        sock.send(command.encode())
        sock.shutdown(socket.SHUT_WR)
        response = _recv_all(sock)
        sock.close()
        _SOCKET_DERNIERE_ERREUR.update({"message": "", "commande": "", "t": 0.0})
        return json.loads(response.decode())
    except Exception as e:
        print(f"[SOCKET] Erreur ({command.strip()}): {e}")
        _SOCKET_DERNIERE_ERREUR.update({"message": str(e)[:200], "commande": command.strip(),
                                        "t": time.time()})
        return None


def get_metrics_from_socket():
    return _socket_request("GET_METRICS\n")


def get_dashboard_from_socket():
    return _socket_request("GET_DASHBOARD\n")


def get_entity_from_socket(entity_type):
    return _socket_request(f"GET_ENTITY:{entity_type}\n")


# ── SENSORIUM : pont vers le modèle du monde (vérité-terrain du collector) ──────
def world_model_from_socket(prefix: str = ""):
    cmd = ("GET_WORLD:%s\n" % prefix) if prefix else "GET_WORLD\n"
    return _socket_request(cmd) or []


def world_query_from_socket(term: str):
    return _socket_request("QUERY_WORLD:%s\n" % term) or []


def world_changes_from_socket(since: str = ""):
    cmd = ("GET_CHANGES:%s\n" % since) if since else "GET_CHANGES\n"
    return _socket_request(cmd) or []


def _health_caveat(rows) -> str:
    """Le score de santé est un agrégat : il peut rester à 100 alors que des signaux
    observés sont au rouge. Constaté en production — « santé 100/100 » annoncé dans
    un rapport alors que DEUX machines de la flotte étaient hors ligne dans les mêmes
    données. On accole désormais les contradictions au score pour qu'il ne puisse
    plus être cité seul."""
    warns = [str(r.get("wkey")) for r in rows if r.get("severity") == "warning"]
    if not warns:
        return ""
    return ("\n⚠️ **Le score de santé n'est PAS global** : %d signal(aux) observé(s) le "
            "contredisent (%s). Interdiction de présenter une santé « parfaite » sans "
            "citer ces points." % (len(warns), ", ".join(warns[:6])))


def recall_environment(topic: str = "", limit: int = 16) -> str:
    """LE SENSORIUM EST UN RENVOI (20-09) : un seul rendu d'état, daté, pour l'outil, l'ancrage d'Itare et
    la vigie — celui de la perception de l'îlot, qui lit aussi le `world_model` du collecteur. L'ancien
    bloc livrait l'état sans son âge ni sa validité : exactement ce que la perception a été faite pour
    empêcher. Le garde-fou du score de santé reste accolé ; sans collecteur ni vigie, chaîne vide."""
    try:
        bloc = perception_bloc(topic or "", limite=max(4, int(limit) // 2))
    except Exception:
        return ""
    if not bloc or bloc.startswith("— perception : aucun relevé"):
        return ""
    try:
        rows = _flotte_filtrer_rows(world_model_from_socket() or [])
    except Exception:
        rows = []
    return bloc + _health_caveat(rows)


# ── MODÈLE DE SOI VIVANT : Cassandra se connaît telle qu'elle EST (pas un souvenir gelé) ──
_SELF_MODEL_CACHE = {"ts": 0.0, "data": None}


def get_self_model(force: bool = False) -> dict:
    """Introspection GROUNDED : lit la réalité actuelle de Cassandra (source réel, nombre
    de fonctions, version/sha, évolutions appliquées, santé, mémoire). Mis en cache 5 min
    car parser ~850 Ko de source est coûteux. C'est le miroir qui ne ment pas."""
    now = time.time()
    if (not force) and _SELF_MODEL_CACHE["data"] and (now - _SELF_MODEL_CACHE["ts"] < 300):
        return _SELF_MODEL_CACHE["data"]
    out = {}
    try:
        src = self_read_source("agent") or ""
        out["source_chars"] = len(src)
        out["source_lines"] = src.count("\n") + 1
        try:
            tree = _ast.parse(src)
            out["functions"] = sum(1 for n in _ast.walk(tree)
                                   if isinstance(n, (_ast.FunctionDef, _ast.AsyncFunctionDef)))
            out["classes"] = sum(1 for n in _ast.walk(tree) if isinstance(n, _ast.ClassDef))
        except Exception:
            out["functions"] = src.count("\ndef ") + src.count("    def ")
            out["classes"] = src.count("\nclass ")
        out["sha256"] = _self_sha(src)[:12] if src else ""
    except Exception:
        pass
    try:
        conn = get_db()
        out["evolutions_applied"] = conn.execute(
            "SELECT COUNT(*) FROM evolution_log WHERE status='applied'").fetchone()[0]
        out["evolutions_total"] = conn.execute("SELECT COUNT(*) FROM evolution_log").fetchone()[0]
        last = conn.execute("SELECT ts, description FROM evolution_log WHERE status='applied' "
                            "ORDER BY id DESC LIMIT 4").fetchall()
        out["recent_evolutions"] = [{"ts": (r[0] or "")[:16], "description": r[1]} for r in last]
        try:
            fr = {}
            for v in ("improved", "neutral", "degraded"):
                fr[v] = conn.execute("SELECT COUNT(*) FROM evolution_fitness WHERE verdict=?", (v,)).fetchone()[0]
            out["fitness"] = fr
        except Exception:
            pass
        conn.close()
    except Exception:
        pass
    try:
        h = get_health_score() or {}
        out["health_score"] = h.get("score", 0)
        out["health_status"] = h.get("status", "unknown")
    except Exception:
        pass
    try:
        # V18 : le modèle de soi compte l'îlot (ce que Cassandra sait de la machine), plus
        # l'ancienne table — relevé de Cassandra (#855) : 404 affichés pour 1 actif réel.
        _st = memoire_etat(["partage", "cassandra"]).get("statuts", {})
        out["memories"] = int(_st.get("actif", 0))
        out["memories_contestes"] = int(_st.get("conteste", 0))
        out["memories_quarantaine"] = int(_st.get("quarantaine", 0))
        out["graph_links"] = 0
        out["promoted"] = 0
    except Exception:
        pass
    try:
        # Ce qu'elle a APPRIS, pas seulement ce qu'elle a fait : un nombre d'évolutions ne dit pas
        # si l'une d'elles a servi. Mêmes lectures que l'écran — un seul endroit calcule.
        out["apprentissage"] = evolution_apprentissage()
    except Exception:
        pass
    try:
        out["golden"] = _evo_golden_info()
        out["evolution_paused"] = is_evolution_paused()
        out["semantic"] = bool(globals().get("_EMBED_READY"))
        out["model"] = globals().get("MODEL_NAME", "")
    except Exception:
        pass
    _SELF_MODEL_CACHE["ts"] = now
    _SELF_MODEL_CACHE["data"] = out
    return out


def recall_self(topic: str = "") -> str:
    """Vue introspective formatée — ce que Cassandra peut dire d'elle-même, à jour."""
    m = get_self_model()
    if not m:
        return ""
    lines = ["🪞 **MODÈLE DE SOI (réel, à l'instant)**",
             "  Code : %s caractères · %s lignes · ~%s fonctions · %s classes (sha %s)"
             % (m.get("source_chars", "?"), m.get("source_lines", "?"),
                m.get("functions", "?"), m.get("classes", "?"), m.get("sha256", "?")),
             "  Évolutions : %s appliquées / %s au total"
             % (m.get("evolutions_applied", "?"), m.get("evolutions_total", "?")),
             "  Santé : %s/100 (%s) · Mémoire : %s souvenirs · %s liens · %s promus"
             % (m.get("health_score", "?"), m.get("health_status", "?"),
                m.get("memories", "?"), m.get("graph_links", "?"), m.get("promoted", "?")),
             "  Sémantique : %s · Modèle : %s · Auto-évolution : %s"
             % ("active" if m.get("semantic") else "désactivée", m.get("model", "?"),
                "en pause" if m.get("evolution_paused") else "active")]
    try:
        _ap = evolution_apprentissage_ligne()
        if _ap:
            lines.append("  " + _ap)
    except Exception:
        pass
    if m.get("recent_evolutions"):
        lines.append("  Dernières évolutions : " +
                     " ; ".join((e.get("description") or "")[:55] for e in m["recent_evolutions"][:3]))
    return "\n".join(lines)


def recall_self_brief() -> str:
    """Une ligne d'identité réelle pour le prompt système."""
    m = get_self_model()
    if not m:
        return ""
    ligne = ("🪞 Toi, à l'instant : ~%s caractères de code · ~%s fonctions · %s évolutions appliquées · "
             "%s souvenirs · %s liens associatifs (sha %s)"
             % (m.get("source_chars", "?"), m.get("functions", "?"), m.get("evolutions_applied", "?"),
                m.get("memories", "?"), m.get("graph_links", "?"), m.get("sha256", "?")))
    # Le compte ne dit pas si elles ont servi : sans cette seconde ligne, deux cent trente-et-une
    # pièces jamais mesurées se racontent comme deux cent trente-et-une réussites.
    try:
        appris = evolution_apprentissage_ligne()
    except Exception:
        appris = ""
    return ligne + ("\n" + appris if appris else "")


def recall_environment_brief(max_alerts: int = 6) -> str:
    """Header ultra-court pour le prompt : identité + santé + ce qui mérite l'attention.
    1-2 lignes max → connaissance de l'environnement sans surcharger le prompt."""
    try:
        rows = world_model_from_socket()
    except Exception:
        rows = []
    if not rows:
        return ""
    host = next((r.get("value") for r in rows if r.get("wkey") == "system.hostname"), "?")
    health = next((r.get("value") for r in rows if r.get("wkey") == "health.score"), "?")
    alerts = ["%s=%s" % (r.get("wkey"), r.get("value")) for r in rows if r.get("severity") == "warning"][:max_alerts]
    line = "🛰️ Serveur %s · santé %s" % (host, health)
    if alerts:
        line += " · ⚠️ " + " · ".join(alerts)
    return line + _health_caveat(rows)


# ============================================================
# 7. FILTRAGE
# ============================================================
def filter_recent(data, time_field, max_minutes=5):
    if not data:
        return data
    now = datetime.now()
    filtered = []
    for item in data:
        time_val = item.get(time_field)
        if time_val:
            try:
                if isinstance(time_val, str):
                    time_val = time_val.replace('T', ' ')[:19]
                    dt = datetime.fromisoformat(time_val)
                elif isinstance(time_val, (int, float)):
                    dt = datetime.fromtimestamp(time_val)
                else:
                    filtered.append(item)
                    continue
                if now - dt < timedelta(minutes=max_minutes):
                    filtered.append(item)
            except Exception:
                filtered.append(item)
        else:
            filtered.append(item)
    return filtered


# ============================================================
# 8. DB FALLBACK
# ============================================================
def query_db(sql, params=None):
    if params is None:
        params = []
    try:
        conn = sqlite3.connect(DB_PATH, timeout=3)
        conn.row_factory = sqlite3.Row
        conn.execute("PRAGMA cache_size = 1000")
        cursor = conn.execute(sql, params)
        rows = [dict(row) for row in cursor.fetchall()]
        conn.close()
        return rows
    except Exception as e:
        print(f"[DB] Erreur: {e}")
        return []


def get_metrics_fallback():
    rows = query_db("""SELECT cpu_pct, ram_pct, disk_pct, swap_pct,
               load_1m, load_5m, load_15m,
               ram_total_gb, ram_used_gb,
               disk_total_gb, disk_used_gb, disk_free_gb
        FROM metrics_realtime ORDER BY id DESC LIMIT 1""")
    if rows:
        r = rows[0]
        return {"cpu": r.get("cpu_pct", 0), "ram": r.get("ram_pct", 0),
                "disk": r.get("disk_pct", 0), "swap": r.get("swap_pct", 0),
                "load_1m": r.get("load_1m", 0), "load_5m": r.get("load_5m", 0),
                "load_15m": r.get("load_15m", 0),
                "ram_total_gb": r.get("ram_total_gb", 0), "ram_used_gb": r.get("ram_used_gb", 0),
                "disk_total_gb": r.get("disk_total_gb", 0), "disk_used_gb": r.get("disk_used_gb", 0),
                "disk_free_gb": r.get("disk_free_gb", 0)}
    return {k: 0 for k in ["cpu", "ram", "disk", "swap", "load_1m", "load_5m", "load_15m",
                           "ram_total_gb", "ram_used_gb", "disk_total_gb", "disk_used_gb", "disk_free_gb"]}


