def _model_supports_vision() -> bool:
    """Vérifie si le modèle courant supporte les images."""
    m = MODEL_NAME.lower()
    return any(v in m for v in _VISION_MODELS)

def _vision_memory_context(topic: str, n: int = 3) -> str:
    """Contexte mémoire bref injecté dans l'analyse vision du 2e agent."""
    try:
        txt = (recall_environment(topic or "", limit=n) or "").strip()
        if txt:
            return ("CONTEXTE MÉMOIRE (ce que Cassandra sait déjà — utilise-le pour interpréter "
                    "l'image, mais décris d'abord ce que tu vois) :\n" + txt[:800])
    except Exception:
        pass
    return ""


def _vision_fallback_analyze(image_b64: str, mime: str, filename: str, user_prompt: str) -> str:
    """
    Délègue l'analyse d'une image à l'agent secondaire configurable.
    Appelé quand le modèle principal ne supporte pas les images.
    Retourne une description textuelle à injecter dans le contexte.
    """
    key, model, base_url = _itare_agent_creds()
    if not key:
        return (
            f"[🖼️ Image reçue : {filename}]\n"
            "⚠️ Agent secondaire non configuré — ajoutez un provider "
            "dans Paramètres → Agent secondaire."
        )
    try:
        from openai import OpenAI as _OAI
        vclient = _OAI(api_key=key, base_url=base_url, timeout=30.0)
        prompt  = (user_prompt.strip() + "\n\nDécris cette image en détail.") if user_prompt.strip() \
                  else "Analyse et décris cette image avec précision et exhaustivité."
        # Injection de contexte mémoire : aide le 2e agent à interpréter l'image
        # (capture serveur, graphe, log…) à la lumière de ce que Cassandra sait déjà.
        try:
            _mc = _vision_memory_context(user_prompt or filename, 3)
            if _mc:
                prompt = _mc + "\n\n" + prompt
        except Exception:
            pass
        resp = vclient.chat.completions.create(
            model=model,
            messages=[{
                "role": "user",
                "content": [
                    {"type": "text",      "text": prompt},
                    {"type": "image_url", "image_url": {"url": f"data:{mime};base64,{image_b64}"}}
                ]
            }],
            max_tokens=1500
        )
        desc = _extract_msg_text(resp) or "(aucune description)"
        return f"[🖼️ **Analyse image** via agent vision `{model}`]\n\n{desc}"
    except Exception as e:
        return f"[🖼️ Erreur agent vision `{model}`: {e}]"

# ═══════════════════════════════════════════════════════════════
# DUAL-AGENT — Agent secondaire polyvalent (OpenRouter)
# Feature 1 : Fallback automatique sur erreur du modèle principal
# Feature 2 : Compression de contexte quand la conversation est longue
# Feature 3 : Pré-analyse des requêtes complexes
# ═══════════════════════════════════════════════════════════════
_DUAL_COMPRESSION_THRESHOLD   = 180_000   # ~45k tokens en chars
_DUAL_COMPRESSION_KEEP_RECENT = 8         # messages récents jamais compressés
_DUAL_PREANALYSIS_MIN_CHARS   = 280       # seuil déclenchement pré-analyse
_DUAL_PREANALYSIS_MIN_SCORE   = 3         # score de complexité minimum

# Les fournisseurs de l'agent secondaire : LA MÊME TABLE que le principal (V18 générique).
# Une seconde table divergeait (base DeepSeek sans /v1, « llava » — un modèle de vision — pour
# un agent texte) ; ces deux noms restent pour leurs appelants et dérivent de FOURNISSEURS.
_SECONDARY_PROVIDERS = dict(_PROVIDERS)
_SECONDARY_DEFAULT_MODELS = dict(_DEFAULT_MODELS)
_SECONDARY_DEFAULT_MODELS_ANCIENS = {   # sans usage : gardé une version pour mémoire de la divergence
    "openrouter": "google/gemini-2.0-flash-001",
    "deepseek":   "deepseek-chat",
    "google":     "gemini-2.0-flash",
    "openai":     "gpt-4o-mini",
    "groq":       "llama-3.3-70b-versatile",
    "ollama":     "llava",
}

def _cfg_itare(champ: str, defaut: str = "") -> str:
    """Un réglage d'ITARE CITADELLE, sous son nom neuf ou son nom d'avant.

    L'usager a renommé : `itare_citadelle_*` remplace `itare_*`, parce que
    « agent secondaire » et « vision » désignaient la même configuration sous
    deux noms — dans le même écran de réglages, ce qui garantissait la
    confusion.

    ON LIT LES DEUX. Un renommage sec laisserait muette toute machine déjà
    configurée au redémarrage suivant : elle chercherait une clé qui n'existe
    pas encore chez elle. Le nom neuf prime, l'ancien dépanne, et l'écran de
    réglages écrira désormais le neuf.
    """
    cfg = get_cassandra_config()
    v = str(cfg.get("itare_citadelle_" + champ) or "").strip()
    if v:
        return v
    return str(cfg.get("itare_" + champ) or defaut or "").strip()


def _itare_vision_creds() -> tuple:
    """(clé, modèle, base) du modèle VISION — celui du panel Desk.

    Nouveau réglage : il n'existait pas. Les champs « vision » de l'écran
    étaient peuplés depuis `itare_model`, donc regardaient l'agent secondaire.

    NON RENSEIGNÉ, IL PREND LE MODÈLE LOCAL — pas celui d'Itare Citadelle.
    C'était mon erreur, et l'usager l'a reprise : le Panel Desk réunit
    `itare_user` et Vision, et `itare_user` non réglé prend déjà le local. Les
    faire retomber sur deux défauts différents enverrait chez un fournisseur la
    moitié d'un panel que personne n'a configuré — et l'espace d'un compte
    partirait dehors sans que quiconque l'ait voulu.

    Un Desk que personne n'a réglé reste donc ENTIÈREMENT dans l'instance.
    """
    _lie = modele_role_creds("vision")           # registre de modèles (10-10) : un rôle lié prime
    if _lie:
        return _lie[0], _lie[1], _lie[2]
    cfg = get_cassandra_config()
    prov = str(cfg.get("itare_vision_provider") or "").strip()
    model = str(cfg.get("itare_vision_model") or "").strip()
    key = str(cfg.get("itare_vision_api_key") or "").strip()
    base = str(cfg.get("itare_vision_base_url") or "").strip()
    if not model:
        try:
            loc = [x["name"] for x in (ollama_list() or [])]
        except Exception as e:
            logging.info("[VISION] modèles locaux : %s", e)
            loc = []
        if not loc:
            return "", "", ""
        return ("ollama", loc[0],
                _SECONDARY_PROVIDERS.get("ollama", "http://localhost:11434/v1"))
    if not base:
        base = _SECONDARY_PROVIDERS.get(prov or "openrouter",
                                        _SECONDARY_PROVIDERS["openrouter"])
    if not key:
        key = "ollama" if prov == "ollama" else _cfg_itare("api_key")
    return key, model, base


def itare_user_modele(compte: str = "") -> str:
    """LE MODÈLE D'UN COMPTE, dans le Desk. Vide = le modèle LOCAL.

    L'usager : « si `itare_user` n'est pas configuré sur un compte, par défaut
    c'est le modèle local uniquement ». C'est le bon défaut : un compte qui n'a
    rien réglé ne consomme rien chez un fournisseur, et ne peut pas y envoyer
    ses notes sans l'avoir voulu.
    """
    c = (str(compte) or get_current_user() or "").strip().lower()
    try:
        m = (it_modele_lire(c) or "").strip()
    except Exception:
        m = ""
    if m:
        return m
    try:
        loc = [x["name"] for x in (ollama_list() or [])]
    except Exception:
        loc = []
    return loc[0] if loc else ""


def _itare_agent_creds() -> tuple:
    """
    Retourne (key, model, base_url) pour ITARE CITADELLE — celui qui parle à
    Cassandra. Lit `itare_citadelle_*`, et `itare_*` en repli.
    """
    _lie = modele_role_creds("itare_citadelle")  # registre de modèles (10-10) : un rôle lié prime
    if _lie:
        return _lie[0], _lie[1], _lie[2]
    cfg      = get_cassandra_config()
    # Sans réglage propre, Itare HÉRITE du fournisseur principal (V18 générique) : un inconnu
    # qui n'a qu'une clé, ou qu'un Ollama, a ses deux agents sans rien régler de plus.
    provider = _cfg_itare("provider", "") or MODEL_PROVIDER or "deepseek"
    base_url = _cfg_itare("base_url")
    if not base_url:
        base_url = _SECONDARY_PROVIDERS.get(provider) or (MODEL_BASE_URL if provider == MODEL_PROVIDER else "")
    model = _cfg_itare("model", _SECONDARY_DEFAULT_MODELS.get(provider, "") or (MODEL_NAME if provider == MODEL_PROVIDER else ""))
    key   = _cfg_itare("api_key")
    # Ollama n'a pas besoin de clé réelle
    if not key and provider == "ollama":
        key = "ollama"
    # Si provider principal identique → réutilise sa clé
    if not key and MODEL_PROVIDER == provider:
        key = DEEPSEEK_API_KEY
    # Compat legacy : provider principal openrouter → réutilise
    if not key and MODEL_PROVIDER == "openrouter" and provider == "openrouter":
        key = DEEPSEEK_API_KEY
    return key, model, base_url

_ITARE_AGENT_LAST_ERROR = [""]   # dernière erreur d'appel agent secondaire (diagnostic UI)

def _itare_agent_available() -> bool:
    k, _, base = _itare_agent_creds()
    if k:
        return True
    # sans clé : un serveur local ou personnalisé qui répond suffit (V18 générique)
    return bool(base) and _serveur_modele_repond(base)


_SERVEUR_MODELE_CACHE = {}   # base_url -> (epoch, bool) ; 30 s, un test TCP d'une seconde

def _serveur_modele_repond(base_url: str) -> bool:
    """Un serveur de modèles compatible OpenAI est-il joignable (test TCP, 1 s, cache 30 s) ?
    Sert au parcours sans clé : Ollama en local, ou un serveur personnalisé."""
    import socket
    from urllib.parse import urlparse
    try:
        u = urlparse(base_url or "")
        hote, port = u.hostname, u.port or (443 if u.scheme == "https" else 80)
        if not hote:
            return False
        c = _SERVEUR_MODELE_CACHE.get(base_url)
        if c and time.time() - c[0] < 30:
            return c[1]
        with socket.create_connection((hote, port), timeout=1.0):
            ok = True
    except Exception:
        ok = False
    _SERVEUR_MODELE_CACHE[base_url] = (time.time(), ok)
    return ok


def _agent_ready() -> bool:
    """Le dialogue peut-il fonctionner ? Une clé, OU un fournisseur sans clé (Ollama) ou à clé
    optionnelle (personnalisé) dont le serveur répond. C'est la seule garde à interroger :
    les messages « clé non configurée » ne nomment jamais un fournisseur."""
    if DEEPSEEK_API_KEY:
        return True
    f = _fournisseur(MODEL_PROVIDER)
    if f["cle"] in ("aucune", "optionnelle") and MODEL_BASE_URL:
        return _serveur_modele_repond(MODEL_BASE_URL)
    return False


AGENT_NON_PRET = ("Le dialogue est désactivé : aucune clé API ni modèle local configuré. "
                  "Réglages › Modèle (une clé, un serveur compatible OpenAI, ou Ollama en local).")

_OLLAMA_NUM_CTX_DEFAUT = 8192   # la fenêtre d'un modèle local ; Ollama ouvre à 4 096 sans qu'on le lui dise


def _ollama_num_ctx() -> int:
    """La fenêtre (jetons) donnée à un modèle LOCAL. Elle se paie en mémoire vive — sur une machine
    de 8 Go, Cassandra et le modèle se la partagent : réglable (`ollama_num_ctx`), plancher 2 048."""
    try:
        n = int(get_cassandra_config().get("ollama_num_ctx") or 0)
    except Exception:
        n = 0
    return n if n >= 2048 else _OLLAMA_NUM_CTX_DEFAUT


def _ita_ollama(base_url, provider=None) -> bool:
    """Le modèle appelé est-il un Ollama local ? Son port, ou le fournisseur réglé — celui du modèle
    APPELÉ : le relecteur en ligne ne doit pas prendre le chemin local de l'agent secondaire."""
    prov = _cfg_itare("provider", "") if provider is None else provider
    return ":11434" in str(base_url or "") or prov == "ollama"


# ════════════════════════════════════════════════════════
#  REGISTRE DE MODÈLES (10-10) — un modèle se déclare UNE fois ; les rôles y puisent.
#
#  Quatre rôles saisissaient chacun leur modèle, leur clé et leur serveur de leur côté, et la clé du
#  relecteur dormait EN CLAIR dans config.json. Ici : une table, et les clés dans le coffre de SERVICE
#  (`modele/<id>`), jamais ailleurs. Un rôle LIÉ au registre prime sur son ancien réglage ; non lié, ou
#  coffre muet : l'ancien réglage joue comme avant — rien ne change tant qu'on ne bascule pas.
#  Branchés : Itare Citadelle, Vision, Relecteur de l'évolution. Pas encore : le principal (modèle global
#  chargé au démarrage), Itare des comptes (local par défaut, choix par compte, volontairement), le second
#  avis (rôle neuf, il naît avec Proactivité).
# ════════════════════════════════════════════════════════
_MODELES_ROLES = {"itare_citadelle": "Itare Citadelle", "vision": "Vision", "relecteur": "Relecteur de l'évolution"}
_MODELES_CREDS_CACHE = {}          # id -> (epoch, creds) ; 60 s : le coffre est un aller-retour HTTP
_MODELES_NOM_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9._/:@+-]{0,160}")
_MODELES_COFFRE_AIDE = "le coffre de service est indisponible ou verrouillé : la clé n'a été écrite nulle part (délibéré)"


def _modeles_conn():
    conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
    conn.row_factory = sqlite3.Row
    conn.execute("CREATE TABLE IF NOT EXISTS modeles_registre ("
                 "id TEXT PRIMARY KEY, fournisseur TEXT NOT NULL, nom TEXT NOT NULL, base_url TEXT DEFAULT '', "
                 "a_cle INTEGER DEFAULT 0, ts TEXT DEFAULT (datetime('now','localtime')), ajoute_par TEXT DEFAULT '', "
                 "essai_ts TEXT DEFAULT '', essai_ok INTEGER, essai_s REAL, essai_msg TEXT DEFAULT '')")
    return conn


def _modele_secret_nom(mid: str) -> str:
    return "modele/" + mid


def modele_creds(mid: str):
    """(clé, modèle, base, fournisseur) d'un modèle du registre, ou None. Jamais d'exception : un coffre
    muet rend None, et l'appelant retombe sur l'ancien réglage du rôle."""
    mid = str(mid or "").strip()
    if not mid:
        return None
    c = _MODELES_CREDS_CACHE.get(mid)
    if c and time.time() - c[0] < 60:
        return c[1]
    precedent = c[1] if c else None      # le dernier modèle qui a marché : le coffre peut tousser, l'agent continue
    creds = None
    try:
        conn = _modeles_conn()
        try:
            r = conn.execute("SELECT * FROM modeles_registre WHERE id = ?", (mid,)).fetchone()
        finally:
            conn.close()
        if r:
            prov = r["fournisseur"]
            key = ""
            if r["a_cle"]:
                key = str(vault_get(_modele_secret_nom(mid)) or "").strip()
            elif prov == "ollama":
                key = "ollama"
            else:
                key = "none"            # serveur sans clé : le client exige une valeur non vide
            base = (r["base_url"] or "").strip() or _SECONDARY_PROVIDERS.get(prov, "")
            if key:
                creds = (key, r["nom"], base, prov)
            else:
                logging.warning("[MODÈLES] %s : clé introuvable dans le coffre — repli sur l'ancien réglage", mid)
    except Exception as e:
        logging.warning("[MODÈLES] creds %s : %s", mid, e)
    if creds is None and precedent:
        logging.warning("[MODÈLES] %s : coffre muet, dernier état connu conservé", mid)
        creds = precedent
    _MODELES_CREDS_CACHE[mid] = (time.time(), creds)
    return creds


def modele_role_creds(role: str):
    """Le modèle du registre LIÉ à ce rôle, ou None (rôle non lié, ou modèle illisible)."""
    try:
        mid = str(get_cassandra_config().get("modele_role_" + role) or "").strip()
    except Exception:
        return None
    return modele_creds(mid) if mid else None


def _modeles_roles_lies() -> dict:
    try:
        cfg = get_cassandra_config()
    except Exception:
        return {}
    return {r: str(cfg.get("modele_role_" + r) or "").strip() for r in _MODELES_ROLES
            if str(cfg.get("modele_role_" + r) or "").strip()}


def modeles_lister() -> dict:
    conn = _modeles_conn()
    try:
        rows = [dict(r) for r in conn.execute("SELECT * FROM modeles_registre ORDER BY ts, id")]
    finally:
        conn.close()
    liens = _modeles_roles_lies()
    par_modele = {}
    for role, mid in liens.items():
        par_modele.setdefault(mid, []).append(role)
    for r in rows:
        r["roles"] = par_modele.get(r["id"], [])
        r["en_ligne"] = r["fournisseur"] != "ollama" and not (r["fournisseur"] == "personnalise" and
                                                                 re.match(r"https?://(127\.|localhost|\[::1\])", r["base_url"] or ""))
    try:
        locaux = ollama_list() if ollama_available() else []
    except Exception:
        locaux = []
    cfg = get_cassandra_config()
    en_clair = []
    for role in _MODELES_ROLES:
        leg = _modeles_legacy(cfg, role)
        if leg["cle"] and leg["cle"] != "ollama" and role not in liens:
            en_clair.append({"role": role, "nom": _MODELES_ROLES[role], "migrable": bool(leg["nom"]),
                             "modele": leg["nom"], "fournisseur": leg["prov"]})
    return {"ok": True, "modeles": rows, "roles": liens, "locaux": locaux,
            "ollama": bool(locaux) or ollama_available(), "pull": ollama_pull_status(),
            "fournisseurs": [{"id": k, "nom": v["nom"], "defaut": v["defaut"], "cle": v["cle"],
                              "raisonneur": v["raisonneur"]} for k, v in FOURNISSEURS.items()],
            "roles_branches": list(_MODELES_ROLES), "en_clair": en_clair,
            "coffre": bool(vault_available())}


def modele_ajouter(d: dict, acteur: str = "") -> dict:
    prov = str(d.get("fournisseur") or "").strip()
    if prov not in FOURNISSEURS:
        return {"ok": False, "error": "fournisseur inconnu"}
    nom = str(d.get("nom") or "").strip().rstrip(".,;:!?»« ").strip()
    if not nom:
        return {"ok": False, "error": "nom de modèle requis"}
    if re.match(r"https?://", nom, re.I):
        return {"ok": False, "error": "le modèle est un nom, pas une adresse"}
    if not _MODELES_NOM_RE.fullmatch(nom) or nom.endswith(":"):
        return {"ok": False, "error": "nom de modèle invalide : « %s »" % nom[:80]}
    base = str(d.get("base_url") or "").strip()
    if prov == "personnalise":
        if not base:
            return {"ok": False, "error": "adresse du serveur manquante"}
        if not re.fullmatch(r"https?://[^\s]+", base):
            return {"ok": False, "error": "adresse du serveur invalide"}
    else:
        base = ""                       # l'adresse vient de la table des fournisseurs, une seule fois
    cle = str(d.get("cle") or "").strip()
    besoin = FOURNISSEURS[prov]["cle"]
    if besoin == "requise" and not cle:
        return {"ok": False, "error": "clé manquante"}
    slug = re.sub(r"[^a-z0-9]+", "-", nom.lower()).strip("-")[:28] or "modele"
    mid = "%s-%s" % (slug, secrets.token_hex(2))
    a_cle = 0
    if cle and prov != "ollama":
        r = vault_set(_modele_secret_nom(mid), cle)
        if not r.get("ok"):
            return {"ok": False, "error": _MODELES_COFFRE_AIDE + " (%s)" % str(r.get("error") or "")[:80]}
        a_cle = 1
    conn = _modeles_conn()
    try:
        conn.execute("INSERT INTO modeles_registre (id, fournisseur, nom, base_url, a_cle, ajoute_par) VALUES (?,?,?,?,?,?)",
                     (mid, prov, nom, base, a_cle, acteur or ""))
        conn.commit()
    finally:
        conn.close()
    _MODELES_CREDS_CACHE.pop(mid, None)
    return {"ok": True, "id": mid}


def modele_essayer(mid: str) -> dict:
    creds = modele_creds(mid)
    if not creds:
        return {"ok": False, "error": "modèle introuvable, ou clé illisible dans le coffre"}
    _ITARE_AGENT_LAST_ERROR[0] = ""
    t0 = time.time()
    txt = _itare_agent_text([{"role": "user", "content": "Réponds par le seul mot : prêt."}],
                            max_tokens=300, timeout=60.0, reflexion=False, creds=creds)
    dt = round(time.time() - t0, 1)
    ok = bool((txt or "").strip())
    msg = (txt or "").strip()[:120] if ok else (_ITARE_AGENT_LAST_ERROR[0][:200] or "aucune réponse")
    conn = _modeles_conn()
    try:
        conn.execute("UPDATE modeles_registre SET essai_ts = datetime('now','localtime'), essai_ok = ?, essai_s = ?, essai_msg = ? WHERE id = ?",
                     (1 if ok else 0, dt, msg, mid))
        conn.commit()
    finally:
        conn.close()
    return {"ok": ok, "secondes": dt, "reponse": msg if ok else "", "erreur": "" if ok else msg}


def modele_retirer(mid: str) -> dict:
    mid = str(mid or "").strip()
    lies = [r for r, m in _modeles_roles_lies().items() if m == mid]
    if lies:
        return {"ok": False, "error": "ce modèle sert un rôle (%s) : change le rôle d'abord" %
                ", ".join(_MODELES_ROLES[r] for r in lies)}
    conn = _modeles_conn()
    try:
        row = conn.execute("SELECT a_cle FROM modeles_registre WHERE id = ?", (mid,)).fetchone()
        if not row:
            return {"ok": False, "error": "modèle introuvable"}
        if row["a_cle"]:
            r = vault_delete(_modele_secret_nom(mid))
            if not r.get("ok"):
                return {"ok": False, "error": "la clé n'a pas pu être retirée du coffre : %s" % str(r.get("error") or "")[:80]}
        conn.execute("DELETE FROM modeles_registre WHERE id = ?", (mid,))
        conn.commit()
    finally:
        conn.close()
    _MODELES_CREDS_CACHE.pop(mid, None)
    return {"ok": True}


def modeles_role_set(role: str, mid: str, acteur: str = "") -> dict:
    if role not in _MODELES_ROLES:
        return {"ok": False, "error": "ce rôle n'est pas encore branché au registre"}
    mid = str(mid or "").strip()
    cfg = get_cassandra_config()
    if mid:
        if not modele_creds(mid):
            return {"ok": False, "error": "modèle introuvable, ou clé illisible dans le coffre"}
        cfg["modele_role_" + role] = mid
    else:
        cfg.pop("modele_role_" + role, None)
        # Un rôle dont la clé a été migrée n'a plus de clé dans son ancien réglage : le laisser pointer
        # là donnerait un agent sans clé. Il retombe donc sur son défaut d'avant lui (Itare Citadelle :
        # le fournisseur principal ; Vision : le premier modèle local ; relecteur : l'agent secondaire).
        if cfg.get("modele_migre_" + role):
            for champ in _MODELES_LEGACY[role][2]:
                cfg.pop(champ, None)
            cfg.pop("modele_migre_" + role, None)
    ok = save_cassandra_config(cfg)
    try:
        log_user_activity(acteur, acteur, "modeles_role", "%s -> %s" % (role, mid or "ancien réglage"))
    except Exception:
        pass
    return {"ok": bool(ok)}


_MODELES_LEGACY = {
    # rôle: (préfixes lus dans l'ordre, champs-clés à effacer, champs à effacer au déliement d'un rôle migré)
    "itare_citadelle": (("itare_citadelle_", "itare_"), ("itare_citadelle_api_key", "itare_api_key"),
                        ("itare_citadelle_provider", "itare_citadelle_base_url", "itare_citadelle_model",
                         "itare_provider", "itare_base_url", "itare_model")),
    "vision": (("itare_vision_",), ("itare_vision_api_key",),
               ("itare_vision_provider", "itare_vision_base_url", "itare_vision_model")),
    "relecteur": (("evolution_relecteur_",), ("evolution_relecteur_api_key",),
                  ("evolution_relecteur_provider", "evolution_relecteur_base_url", "evolution_relecteur_model")),
}


def _modeles_legacy(cfg: dict, role: str) -> dict:
    """L'ancien réglage d'un rôle, lu comme le moteur le lit (le nom neuf d'abord, l'ancien en repli)."""
    prefixes, _cles, _tout = _MODELES_LEGACY[role]
    def lire(champ):
        for pre in prefixes:
            v = str(cfg.get(pre + champ) or "").strip()
            if v:
                return v
        return ""
    prov = lire("provider")
    prov = "personnalise" if prov == "custom" else prov
    return {"prov": prov, "nom": lire("model").rstrip(".,;:!?»« ").strip(), "base": lire("base_url"), "cle": lire("api_key")}


def modeles_migrer(role: str, acteur: str = "") -> dict:
    """La clé d'un rôle quitte config.json pour le coffre de service ; le rôle est lié au registre."""
    if role not in _MODELES_ROLES:
        return {"ok": False, "error": "rôle inconnu"}
    cfg = get_cassandra_config()
    leg = _modeles_legacy(cfg, role)
    if not leg["cle"] or leg["cle"] == "ollama":
        return {"ok": False, "error": "rien à migrer : pas de clé en clair pour ce rôle"}
    if not leg["nom"] or not leg["prov"]:
        return {"ok": False, "error": "ce rôle n'a ni fournisseur ni modèle réglés : rien à déclarer"}
    if leg["prov"] not in FOURNISSEURS:
        return {"ok": False, "error": "fournisseur inconnu : %s" % leg["prov"][:40]}
    r = modele_ajouter({"fournisseur": leg["prov"], "nom": leg["nom"], "cle": leg["cle"],
                        "base_url": leg["base"] if leg["prov"] == "personnalise" else ""}, acteur)
    if not r.get("ok"):
        return r
    mid = r["id"]
    relu = modele_creds(mid)
    if not relu or relu[0] != leg["cle"]:
        modele_retirer(mid)
        return {"ok": False, "error": "relecture de la clé dans le coffre impossible : rien n'a été changé"}
    cfg = get_cassandra_config()
    cfg["modele_role_" + role] = mid
    cfg["modele_migre_" + role] = True
    for champ in _MODELES_LEGACY[role][1]:
        cfg.pop(champ, None)
    if not save_cassandra_config(cfg):
        return {"ok": False, "error": "configuration non enregistrée"}
    try:
        log_user_activity(acteur, acteur, "modeles_migrer", "%s -> coffre (%s)" % (role, mid))
    except Exception:
        pass
    return {"ok": True, "id": mid}


def modeles_ollama_supprimer(nom: str) -> dict:
    nom = str(nom or "").strip()
    if not nom:
        return {"ok": False, "error": "modèle requis"}
    conn = _modeles_conn()
    try:
        ids = [r["id"] for r in conn.execute("SELECT id FROM modeles_registre WHERE fournisseur = 'ollama' AND nom = ?", (nom,))]
    finally:
        conn.close()
    lies = _modeles_roles_lies()
    if any(m in ids for m in lies.values()):
        return {"ok": False, "error": "ce modèle sert un rôle : change le rôle d'abord"}
    r = ollama_delete(nom)
    if r.get("ok"):
        for i in ids:
            modele_retirer(i)
    return r


def _evo_relecteur_creds():
    """LE RELECTEUR DE L'ÉVOLUTION, s'il a son réglage propre (`evolution_relecteur_*`) :
    (clé, modèle, base, fournisseur). Sans modèle réglé : None — l'agent secondaire relit, comme
    avant. Un petit modèle local doute de tout et refuse tout (18-09 : 4 refus sur 4) ; ce rôle
    permet d'envoyer la seule relecture vers un modèle en ligne, Itare restant en local."""
    _lie = modele_role_creds("relecteur")        # registre de modèles (10-10) : un rôle lié prime
    if _lie:
        return _lie
    try:
        cfg = get_cassandra_config()
    except Exception:
        return None
    # La ponctuation de fin d'un nom copié d'une phrase (« …:free. ») tombe aussi à la LECTURE : un
    # réglage enregistré avant la vérification de la route ne doit pas faire attendre chaque pièce.
    model = str(cfg.get("evolution_relecteur_model") or "").strip().rstrip(".,;:!?»« ").strip()
    if not model:
        return None
    prov = str(cfg.get("evolution_relecteur_provider") or "openrouter").strip()
    base = str(cfg.get("evolution_relecteur_base_url") or "").strip() or _SECONDARY_PROVIDERS.get(prov, "")
    key = str(cfg.get("evolution_relecteur_api_key") or "").strip()
    if not key and prov == "ollama":
        key = "ollama"
    return (key, model, base, prov)


def _itare_ollama_texte(model, base_url, msgs, max_tokens, temperature, allow_reasoning, timeout, reflexion):
    """L'appel d'un Ollama local par son API NATIVE : la seule qui accepte `think` (couper la
    réflexion) et `num_ctx` (la fenêtre). L'API compatible OpenAI n'accepte ni l'un ni l'autre."""
    base = str(base_url or "").rstrip("/")
    if base.endswith("/v1"):
        base = base[:-3]
    opts = {"num_predict": int(max_tokens), "num_ctx": _ollama_num_ctx()}
    if temperature is not None:
        opts["temperature"] = float(temperature)
    corps = {"model": model, "messages": msgs, "stream": False, "options": opts, "keep_alive": "10m",
             "think": bool(reflexion)}

    def _appel(c):
        req = urllib.request.Request(base + "/api/chat", data=json.dumps(c).encode("utf-8"),
                                     headers={"Content-Type": "application/json"})
        with urllib.request.urlopen(req, timeout=float(timeout)) as r:
            return json.loads(r.read().decode("utf-8", "replace"))
    try:
        j = _appel(corps)
    except urllib.error.HTTPError as e:
        # UN MODÈLE QUI NE SAIT PAS RÉFLÉCHIR refuse le champ `think` : on rejoue sans lui.
        if e.code != 400:
            raise
        corps.pop("think", None)
        j = _appel(corps)
    _ITARE_AGENT_LAST_ERROR[0] = ""
    m = j.get("message") or {}
    txt = (m.get("content") or "").strip()
    fr = str(j.get("done_reason") or "")
    if fr == "length":
        _ITARE_AGENT_LAST_ERROR[0] = ("réponse TRONQUÉE par num_predict=%s (done_reason=length) "
                                      "— augmenter le budget" % max_tokens)
    if not txt:
        rc = (m.get("thinking") or "").strip()
        if rc and allow_reasoning:
            txt = rc
        if not txt:
            _ITARE_AGENT_LAST_ERROR[0] = ("contenu VIDE renvoyé par %s en local (done_reason=%s, réflexion %s)"
                                          % (model, fr, "demandée" if reflexion else "coupée"))
            print(f"[DualAgent] contenu vide (model={model}, local, done_reason={fr}, "
                  f"reflexion={'oui' if reflexion else 'non'})", flush=True)
    return txt


@profil_mesurer("modele.secondaire")
def _itare_agent_text(user_msgs: list, system: str = None, max_tokens: int = 1400,
                     temperature=None, allow_reasoning: bool = True,
                     timeout: float = 75.0, reflexion: bool = False, creds: tuple = None) -> str:
    """
    Appelle l'agent secondaire (Itare) pour une tâche textuelle (non-stream).
    Retourne la réponse en str, ou "" si indisponible/erreur.
    `temperature` optionnelle : permet une passe déterministe (0.0) pour l'auto-revue.
    Si l'endpoint refuse le paramètre, on retombe proprement sur un appel sans température.

    `allow_reasoning=False` INTERDIT le repli sur reasoning_content. Indispensable
    pour la GÉNÉRATION DE CODE : le repli renvoie la prose de réflexion du modèle,
    qui part ensuite dans ast.parse et produit un « unterminated string literal
    (detected at line 1) » — un faux diagnostic de code tronqué. Le repli reste
    utile pour le JSON, dont le parseur tolérant sait extraire l'objet.
    `timeout` : 75 s convient au JSON, pas à plusieurs milliers de tokens de code.

    `reflexion` : pour un Ollama LOCAL, la réflexion d'un modèle raisonneur est COUPÉE par défaut
    (elle comptait dans le budget et vidait la réponse : 58 réponses vides en deux jours, 18-09) ;
    `reflexion=True` la rend. Sans effet sur un fournisseur distant.

    `creds` = (clé, modèle, base, fournisseur) : un AUTRE modèle que l'agent secondaire — le
    relecteur de l'évolution quand il a son réglage propre.
    """
    if creds:
        key, model, base_url, _prov = creds
    else:
        key, model, base_url = _itare_agent_creds()
        _prov = None
    if not key:
        return ""
    msgs = ([{"role": "system", "content": system}] if system else []) + list(user_msgs)
    if _ita_ollama(base_url, _prov) and all(isinstance(x.get("content"), str) for x in msgs):
        try:
            return _itare_ollama_texte(model, base_url, msgs, max_tokens, temperature, allow_reasoning,
                                       timeout, reflexion)
        except Exception as e:
            _ITARE_AGENT_LAST_ERROR[0] = str(e)[:500]
            print(f"[DualAgent] appel local : {e}", flush=True)
            return ""
    try:
        from openai import OpenAI as _OAI
        vc   = _OAI(api_key=key, base_url=base_url, timeout=float(timeout))
        kw = {"model": model, "messages": msgs, "max_tokens": max_tokens}
        if temperature is not None:
            kw["temperature"] = float(temperature)
        _rejoue_vide = False
        while True:
            try:
                resp = vc.chat.completions.create(**kw)
            except Exception:
                kw.pop("temperature", None)   # endpoint qui n'accepte pas le param → repli
                resp = vc.chat.completions.create(**kw)
            _ITARE_AGENT_LAST_ERROR[0] = ""
            _msg = resp.choices[0].message
            _txt = (_msg.content or "").strip()
            _fr = str(getattr(resp.choices[0], "finish_reason", "") or "")
            _rc = (getattr(_msg, "reasoning_content", None) or "").strip()
            # MODÈLE RAISONNEUR : la réflexion a mangé le budget — contenu vide,
            # tout est parti en raisonnement. Un SEUL rejeu, budget élargi, consigne
            # de réponse directe (le même remède que le chemin principal).
            if (not _txt) and _rc and (not _rejoue_vide):
                _rejoue_vide = True
                kw = dict(kw)
                kw["max_tokens"] = max(int(max_tokens) * 3, 3000)
                kw["messages"] = list(kw["messages"]) + [{"role": "user", "content":
                    "(Ta réponse est arrivée vide : ta réflexion a consommé tout le budget. "
                    "Réponds maintenant directement, sans réfléchir longuement.)"}]
                continue
            if _fr == "length":
                # Réponse coupée net : le signaler explicitement plutôt que de laisser
                # l'appelant conclure à un « code invalide ».
                _ITARE_AGENT_LAST_ERROR[0] = ("réponse TRONQUÉE par max_tokens=%s (finish_reason=length) "
                                              "— augmenter le budget" % max_tokens)
            if not _txt:
                if _rc and allow_reasoning:
                    _txt = _rc   # le JSON est souvent dedans — le parseur robuste s'en sort
                if not _txt:
                    _ITARE_AGENT_LAST_ERROR[0] = ("contenu VIDE renvoyé par %s (finish_reason=%s) — modèle "
                                                  "raisonneur qui a tout dépensé en réflexion ? Recommandé : "
                                                  "itare_model=deepseek-chat pour les tâches JSON." % (model, _fr))
                    print(f"[DualAgent] contenu vide (model={model}, finish_reason={_fr}) — "
                          f"essayer itare_model=deepseek-chat", flush=True)
            return _txt
    except Exception as e:
        _ITARE_AGENT_LAST_ERROR[0] = str(e)[:500]
        print(f"[DualAgent] text call error: {e}", flush=True)
        return ""

def _itare_outils_perso() -> list:
    """Les déclarations d'outils de la famille PERSO, telles quelles.

    On les puise dans `CASSANDRA_TOOLS` au lieu de les réécrire : deux
    descriptions du même outil finiraient par diverger, et c'est celle que le
    modèle lit qui serait fausse.
    """
    return [t for t in CASSANDRA_TOOLS
            if (t.get("function") or {}).get("name") in ITARE_OUTILS_PERSO]


def _img_mime_b64(b64: str) -> str:
    """Le type d'une image, lu dans ses premiers octets.

    L'écran n'envoie que le base64 nu — il a coupé le préfixe `data:` — et le
    chemin local en a besoin ainsi. Plutôt que d'ajouter un champ au protocole,
    on relit la signature du fichier : elle est dans les données.
    """
    try:
        tete = base64.b64decode((b64 or "")[:32] + "==", validate=False)[:12]
    except Exception:
        return "image/png"
    # EN HEXADECIMAL, sans echappe. Ecrites `b"PNG"`, ces signatures se
    # font interpreter par le moindre outil qui passe : l'octet brut atterrit
    # dans le fichier, et Python refuse un litteral d'octets non ASCII.
    for magie, mime in (("89504e47", "image/png"),
                        ("ffd8ff", "image/jpeg"),
                        ("47494638", "image/gif")):
        if tete.startswith(bytes.fromhex(magie)):
            return mime
    if tete[:4] == b"RIFF" and tete[8:12] == b"WEBP":
        return "image/webp"
    return "image/png"


class _ItaPanne(str):
    """Un morceau de flux qui n'est PAS une parole d'Itare : une panne. Une chaîne comme une autre
    pour qui l'affiche ; reconnaissable pour qui enregistre — elle ne va jamais dans la réponse,
    et se range sous le rôle `panne`, que les constructeurs de contexte écartent (B20)."""
    pass


# LE CLIENT RECONNAÎT UNE PANNE À CETTE TÊTE : un seul libellé, partagé des deux côtés.
ITA_PANNE_TETE = "⚠️ Panne d'Itare — "


def _ita_base_locale(base_url) -> bool:
    b = str(base_url or "")
    return any(h in b for h in ("127.0.0.1", "localhost", ":11434"))


def _ita_panne_texte(model, base_url, e) -> str:
    """Ce qui s'est passé, et ce qu'on peut y faire. « Request timed out » ne disait ni l'un ni
    l'autre. Le choix du modèle reste à la personne : basculer seul vers un modèle en ligne
    enverrait la conversation hors de la machine."""
    txt = str(e or "")
    if _ita_base_locale(base_url) and ("timed out" in txt.lower() or "timeout" in txt.lower()):
        return (ITA_PANNE_TETE + "le modèle local « %s » n'a pas répondu en 2 minutes. Un modèle qui "
                "réfléchit avant de répondre, sur le processeur de la machine et face à un long "
                "contexte, dépasse ce délai. Un modèle en ligne se choisit dans Mon compte › Mon Itare."
                % (model or "?"))
    return ITA_PANNE_TETE + "%s : %s" % (model or "agent secondaire", txt[:200])


def _msgs_outils_coherents(msgs: list) -> list:
    """Une conversation que l'API accepte : chaque message assistant porteur de `tool_calls` est
    suivi d'une réponse `tool` pour CHACUN de ses identifiants, et aucune réponse `tool` n'est
    orpheline. Sinon DeepSeek rejette tout le tour (« insufficient tool messages following
    tool_calls », journal des agents n°122 : le travail du tour était perdu). Ce qui manque est
    complété par une réponse explicite plutôt que deviné ; ce qui traîne est retiré."""
    out, attendus = [], []
    def _clore():
        for tid in attendus:
            out.append({"role": "tool", "tool_call_id": tid,
                        "content": "⚠️ appel interrompu : aucune réponse n'a été produite."})
        attendus.clear()
    for m in msgs or []:
        role = m.get("role")
        if role == "tool":
            tid = m.get("tool_call_id")
            if tid in attendus:
                attendus.remove(tid)
                out.append(m)
            continue                      # orpheline : retirée
        _clore()
        out.append(m)
        if role == "assistant" and m.get("tool_calls"):
            attendus.extend([tc.get("id") for tc in m["tool_calls"] if isinstance(tc, dict) and tc.get("id")])
    _clore()
    return out


def _itare_agent_stream(messages: list, session_id: str = "", outils: bool = False,
                        citadelle: bool = False, lecture_seule: bool = False):
    """Stream la réponse de l'agent secondaire.

    `outils=True` lui donne accès à VOTRE ESPACE — notes, projets, agenda,
    rappels, contacts, courrier — dans n'importe quel mode. Les appels passent
    par `_handle_tool`, le dispatcher du mode Conscient : mêmes gardes RBAC,
    mêmes mandats, même journal. Une seconde porte aurait voulu dire deux jeux
    de gardes à tenir d'accord, et c'est toujours le second qu'on oublie.
    """
    key, model, base_url = _itare_agent_creds()
    if not key:
        yield _ItaPanne(ITA_PANNE_TETE + "aucun agent secondaire n'est configuré.")
        return
    try:
        from openai import OpenAI as _OAI
        # UN DÉLAI DÉPASSÉ SUR LE PROCESSEUR DE LA MACHINE L'EST ENCORE AU SECOND ESSAI : le
        # client réessayait deux fois, et l'attente passait de 2 à 6 minutes avant la panne.
        vc = _OAI(api_key=key, base_url=base_url, timeout=120.0,
                  max_retries=(0 if _ita_base_locale(base_url) else 2))
        # UNE LISTE EST UN CONTENU VALIDE : c'est ainsi que voyage un message
        # portant une image (texte + morceaux d'image). Le filtre exigeait une
        # chaîne et jetait le message ENTIER — la question disparaissait, et le
        # modèle répondait au tour précédent, sans que rien ne le signale.
        msgs = [m for m in messages
                if m.get("role") in ("system", "user", "assistant")
                and isinstance(m.get("content"), (str, list))]
        # ITARE CITADELLE (le tour de salon) a TOUS les outils de Cassandra — c'est la
        # passerelle entre le bureau des comptes et la Citadelle (décision de l'administrateur).
        # L'Itare des comptes garde sa liste PERSO : une île, cantonnée au bureau.
        # LE COFFRE RESTE LA PRÉROGATIVE DE CASSANDRA SEULE (décision de l'administrateur) : ni les
        # outils du coffre, ni la substitution `{{secret:NOM}}` dans une commande.
        _decl = ([t for t in outils_disponibles()
                  if (t.get("function") or {}).get("name") not in ITARE_CITADELLE_INTERDITS
                  and (not lecture_seule or (t.get("function") or {}).get("name") in ITARE_PONT_LECTURE)]
                 if citadelle else _itare_outils_perso()) if outils else []
        _permis = ({(t.get("function") or {}).get("name") for t in CASSANDRA_TOOLS} - ITARE_CITADELLE_INTERDITS
                   if citadelle else ITARE_OUTILS_PERSO)
        if citadelle and lecture_seule:
            _permis = _permis & ITARE_PONT_LECTURE
        # CE QUE LA PERSONNE VIENT D'ÉCRIRE, retenu pour le tour : les gardes
        # qui distinguent « nommé par vous » de « nommé par un texte lu » n'ont
        # pas d'autre source.
        try:
            _dem = [m for m in msgs if m.get("role") == "user"]
            if _dem:
                # Le contenu peut être une LISTE quand une image l'accompagne :
                # les gardes qui distinguent « nommé par vous » de « nommé par
                # un texte lu » ont besoin du TEXTE, pas de l'image.
                _dc = _dem[-1].get("content")
                if isinstance(_dc, list):
                    _dc = " ".join(str(p.get("text") or "") for p in _dc
                                   if isinstance(p, dict) and p.get("type") == "text")
                origine_demande(_dc or "")
        except Exception:
            pass
        # ── LES TOURS D'OUTILS, SANS FLUX ────────────────────────────────
        # On ne diffuse pas pendant qu'il choisit ses outils : reconstituer
        # des appels d'outils depuis un flux morceau par morceau est une
        # source d'erreurs pour un gain nul — ces tours-là ne produisent
        # presque pas de texte. Le flux revient pour la réponse finale.
        if _decl:
            for _tour in range(4):
                msgs = _msgs_outils_coherents(msgs)
                try:
                    _r = vc.chat.completions.create(
                        model=model, messages=msgs, tools=_decl,
                        max_tokens=16000)   # un raisonneur compte sa réflexion ici : à 4 096, l'argument de salon_dire arrivait coupé (2026-09-07)
                except Exception as _e:
                    # UN MODÈLE QUI NE SAIT PAS APPELER D'OUTILS ne doit pas
                    # faire échouer la conversation : on repart sans eux
                    # plutôt que de rendre une erreur à la place d'une réponse.
                    logging.info("[ITARE/OUTILS] %s ne les accepte pas : %s",
                                 model, _e)
                    _decl = []
                    break
                _choices = getattr(_r, "choices", None) or []
                if not _choices or getattr(_choices[0], "message", None) is None:
                    # LE FOURNISSEUR PEUT RENDRE UNE RÉPONSE SANS `choices`
                    # (API surchargée ou réponse vide) : l'indice sur None
                    # remontait en « Panne » alors que le modèle n'avait rien
                    # produit. On repart sans outils, comme pour un refus.
                    logging.info("[ITARE/OUTILS] %s a rendu une réponse vide (choices=%r)",
                                 model, _choices)
                    _decl = []
                    break
                _m = _choices[0].message
                _tc = getattr(_m, "tool_calls", None)
                if not _tc:
                    # Rien à faire : il a répondu directement. On rend ce
                    # texte-là plutôt que de redemander la même chose.
                    if _m.content:
                        yield _m.content
                        return
                    break
                msgs.append({"role": "assistant", "content": _m.content or "",
                             "tool_calls": [
                                 {"id": c.id, "type": "function",
                                  "function": {"name": c.function.name,
                                               "arguments": c.function.arguments}}
                                 for c in _tc]})
                for c in _tc:
                    try:
                        _args = json.loads(c.function.arguments or "{}")
                    except Exception:
                        _args = {}
                    if not isinstance(_args, dict):
                        _args = {}
                    # LA GARDE EST ICI AUSSI, et pas seulement dans la
                    # déclaration : un modèle peut inventer un nom d'outil.
                    # `_handle_tool` refuserait de toute façon, mais un refus
                    # qui arrive plus tôt se lit mieux.
                    if c.function.name not in _permis:
                        msgs.append({"role": "tool", "tool_call_id": c.id,
                                     "content": "⛔ Cet outil ne fait pas "
                                                "partie de ton espace."})
                        continue
                    if citadelle and "{{secret:" in json.dumps(_args, ensure_ascii=False):
                        msgs.append({"role": "tool", "tool_call_id": c.id,
                                     "content": "⛔ Le coffre est la prérogative de Cassandra seule : "
                                                "aucun {{secret:…}} dans tes commandes. Demande-lui."})
                        continue
                    try:
                        yield from _handle_tool(c.id, c.function.name, _args,
                                                msgs, session_id or "")
                    except Exception as _e:
                        msgs.append({"role": "tool", "tool_call_id": c.id,
                                     "content": "⚠️ %s" % str(_e)[:200]})
        # ── LA RÉPONSE, EN FLUX ──────────────────────────────────────────
        # Les messages d'outil sont retirés ici : certains fournisseurs les
        # refusent sur un appel sans `tools`, et à ce stade leur contenu est
        # déjà dans le fil sous forme de texte.
        # Un message assistant qui a appelé des outils ET écrit du texte gardait ses `tool_calls`
        # alors que les réponses `tool` venaient d'être retirées : DeepSeek refusait le tour
        # entier (n°122). On n'en garde que le texte.
        _fin = [({k: v for k, v in m.items() if k != "tool_calls"} if m.get("role") == "assistant" else m)
                for m in msgs
                if m.get("role") in ("system", "user", "assistant")
                and isinstance(m.get("content"), (str, list)) and m.get("content")]
        stream = vc.chat.completions.create(
            model=model, messages=_fin, max_tokens=16000, stream=True
        )
        for chunk in stream:
            delta = chunk.choices[0].delta.content if chunk.choices else None
            if delta:
                yield delta
    except Exception as e:
        yield _ItaPanne("\n" + _ita_panne_texte(model, base_url, e))


def _extract_msg_text(resp) -> str:
    """Texte utile d'une réponse chat, MODÈLES RAISONNEURS COMPRIS.

    Un raisonneur (deepseek-reasoner, R1, QwQ…) laisse `content` VIDE et place tout
    dans `reasoning_content` — surtout si max_tokens est trop bas : le budget part
    en réflexion et la réponse n'est jamais émise. Lire `content` seul renvoie alors
    "" et, côté vérificateur, transforme chaque appel en refus muet.
    Journalise la cause quand rien n'est exploitable, pour que le diagnostic ne se
    résume pas à un silence."""
    try:
        choice = resp.choices[0]
    except Exception:
        return ""
    msg = getattr(choice, "message", None)
    if msg is None:
        return ""
    txt = (getattr(msg, "content", None) or "").strip()
    if txt:
        return txt
    txt = (getattr(msg, "reasoning_content", None)
           or getattr(msg, "reasoning", None) or "").strip()
    if txt:
        return txt
    fr = str(getattr(choice, "finish_reason", "") or "")
    if fr == "length":
        logging.warning("[LLM] réponse vide : budget max_tokens épuisé en réflexion "
                        "(finish_reason=length) — augmenter max_tokens")
    else:
        logging.warning("[LLM] réponse vide (finish_reason=%s)", fr or "inconnu")
    return ""


_VETOS = (
    (r"of\s*=\s*/dev/(sd|nvme|vd|hd|xvd)", "ecriture directe sur un disque"),
    (r">\s*/dev/(sd|nvme|vd|hd|xvd)", "redirection vers un disque"),
    (r"\bmkfs(\.|\s|$)", "formatage d'un systeme de fichiers"),
    (r"--no-preserve-root", "effacement de la racine"),
    # APRES LA RACINE, IL N'Y A PAS QUE LE VIDE. Le premier jet n'admettait
    # que la fin de ligne, `;` ou `&` : « rm -rf /* » et « rm -rf / # menage »
    # passaient tous deux, et le second est encore plus perfide — le
    # commentaire donne a la ligne un air anodin. Or `--no-preserve-root` ne
    # protege que « / » nu ; « /* » efface /bin, /etc et /usr sans le
    # rencontrer.
    (r"\brm\s+(-[a-zA-Z]*\s+)*-?[a-zA-Z]*[rR][a-zA-Z]*f?[a-zA-Z]*"
     r"\s+/(\*|\s*($|;|&|#|\|))",
     "effacement de la racine"),
    # `sudo` N'EST PAS TOUJOURS SEUL. Le motif attendait l'interprete
    # IMMEDIATEMENT apres : « curl … | sudo -u root sh » cassait la sequence
    # sur `-u` et passait — alors que c'est la forme la plus dangereuse des
    # trois, puisqu'elle nomme explicitement root.
    (r"\b(curl|wget)\b[^|;&]*\|\s*(sudo(\s+[^\s|;&]+)*?\s+)?"
     r"(ba|z|k|da)?sh\b",
     "un script telecharge passe directement dans un interprete"),
    (r"\b(curl|wget)\b[^|;&]*\|\s*(sudo(\s+[^\s|;&]+)*?\s+)?"
     r"(python3?|perl|ruby|node)\b",
     "un script telecharge passe directement dans un interprete"),
    # LA RACINE SYSTEME ELLE-MEME, PAS CE QU'ELLE CONTIENT. Le premier jet
    # mordait sur « chmod -R 750 /opt/cassandra/echanges » : dans
    # l'alternance, le « / » seul acceptait le slash initial de n'importe
    # quel chemin absolu. Un veto qui gene le travail ordinaire est retire
    # dans la semaine, et avec lui la seule barriere qui ne se laisse pas
    # convaincre. La cible doit donc ETRE la racine, pas commencer par
    # elle : « /etc » oui, « /etc/nginx » non — celui-la reste un geste
    # d'administration, et le juge le voit toujours.
    (r"\bchmod\s+(-[a-zA-Z]*\s+)*(-R|--recursive)[^;&|]*\s"
     r"(/|/etc|/usr|/bin|/sbin|/boot|/lib|/lib64|/root|/var)/?(\s|$|;|&|\|)",
     "droits changes recursivement sur une racine du systeme"),
    # « 777 » N'EST QU'UNE DES DEUX ECRITURES. `chmod a+w /etc` fait
    # exactement la meme chose en notation symbolique : le repertoire devient
    # inscriptible par tous, on y remplace `shadow` ou `passwd`, et l'on est
    # root. Ne garder que la forme numerique, c'etait garder la porte et
    # laisser la fenetre.
    (r"\bchmod\s+[^;&|]*\b(777|a\+w|go\+w|o\+w|ugo\+w|g\+w)\b[^;&|]*\s"
     r"(/|/etc|/root|/usr|/bin|/sbin|/boot|/lib|/lib64)/?(\s|$|;|&|\|)",
     "ouverture en ecriture a tous d'une racine du systeme"),
    # PAR LE NOM DU FICHIER, PAS PAR SON CHEMIN. Les deux motifs d'origine
    # exigeaient un chemin absolu : « cd /root/.ssh && echo … >>
    # authorized_keys » ecrivait donc dans la clef d'acces root permanente sans
    # que rien ne morde. Le nom, lui, ne se contourne pas par un `cd` — et
    # aucun fichier legitime ne s'appelle ainsi.
    (r">>?\s*[\"']?[^\s\"';|&]*authorized_keys",
     "pose d'une clef d'acces permanente"),
    (r">>?\s*/etc/(shadow|passwd|sudoers)", "reecriture d'un fichier d'identite"),
    # `reboot` MANQUAIT — et c'est le plus courant des quatre.
    #
    # ON EXIGE QUE CE SOIT UNE COMMANDE, pas le mot. « \breboot\b » aurait
    # mordu sur « cat /var/run/reboot-required » et sur « grep poweroff
    # /var/log/… », c'est-a-dire sur des LECTURES — et un veto qui bloque une
    # lecture est retire dans la semaine. On n'accepte donc le mot qu'en tete
    # de segment, ou derriere `sudo`, `systemctl` ou `loginctl`.
    # Et le chemin absolu ne change rien : `/sbin/reboot` EST `reboot` (le banc
    # de la cage l'a trouvé, sur une entrée de catalogue en argv direct).
    (r"(?:^\s*|[;&|]\s*|\bsudo\s+|\bsystemctl\s+|\bloginctl\s+)"
     r"(?:/[\w./-]*/)?(shutdown|halt|poweroff|reboot)\b",
     "arret ou redemarrage de la machine"),
    (r":\(\)\s*\{\s*:\|:&\s*\}\s*;", "bombe de processus"),
)


def veto_root(cmd: str) -> str:
    """Le motif interdit trouve dans cette commande, ou une chaine vide.

    On ne juge pas l'intention — personne ne le fait plus : on regarde ce que
    la commande FAIT. La cage rendrait ces gestes impossibles de toute façon ;
    le veto sert à les NOMMER au lieu de rendre un « permission denied ».
    """
    t = " " + (cmd or "").replace("\n", " ") + " "
    for motif, quoi in _VETOS:
        try:
            if re.search(motif, t, re.I):
                return quoi
        except re.error:
            continue
    return ""


# ══════════════════════════════════════════════════════════════════════════════
#  ORIGINE D'UN ORDRE — et teinte d'un tour
#
#  Une action sortante (envoyer un mail) n'est pas dangereuse en soi : elle l'est
#  selon CE QUI l'a demandée. On ne cherche donc pas à reconnaître une demande
#  malveillante — exercice que l'attaquant gagne toujours puisqu'il choisit son
#  texte — mais à constater l'origine, qui, elle, ne se falsifie pas depuis le
#  contenu.
#
#  Quatre origines, et une cinquième par défaut :
#    chat      l'utilisateur, dans une session authentifiée
#    regle     une règle de Cassandra (échéance, seuil, veille)
#    horaire   une planification
#    contenu   un mail, une page, un document — n'obtient JAMAIS d'envoi
#    inconnu   personne n'a déclaré : traité comme `contenu`
#
#  TEINTE. Dans un même tour de chat, l'agent peut lire un mail piégé puis agir.
#  L'origine reste « chat » — l'utilisateur a bien demandé quelque chose — mais
#  le tour est TEINTÉ dès qu'un contenu extérieur est entré. Un mandat teinté
#  perd son automatisme et repasse par un accord humain. La lecture ne bloque
#  rien ; elle retire seulement le droit de partir tout seul.
# ══════════════════════════════════════════════════════════════════════════════
_ORIGINES = ("chat", "regle", "horaire", "contenu", "inconnu")
_ORIGINES_SURES = ("chat", "regle", "horaire")
_ORIGINE_CTX = threading.local()

# Outils qui font entrer du texte venu du dehors. Les nommer ici est le seul
# entretien que demande la teinte.
_OUTILS_LECTURE_EXTERNE = {
    "itare_mail_read", "itare_mail_list", "itare_web", "web_search", "navigateur",
    "itare_hybrid", "read_file", "site_logs", "ged_texte",
    # Rédiger « depuis » un courrier, c'est le lire : le brouillon composé d'un message
    # reçu teinte le tour comme la lecture elle-même (B50, tour 23).
    "itare_draft_reply", "itare_draft_compose",
}


class _Origine:
    """Pose une origine pour la durée d'un bloc. Réentrant : un bloc imbriqué
    ne peut que RESTREINDRE, jamais élargir."""

    def __init__(self, origine: str, acteur: str = ""):
        self.origine = origine if origine in _ORIGINES else "inconnu"
        self.acteur = str(acteur or "")[:80]
        self.avant = None

    def __enter__(self):
        self.avant = getattr(_ORIGINE_CTX, "etat", None)
        # Un tour déjà teinté le reste : on n'efface pas une lecture en
        # ouvrant un sous-bloc.
        teinte = list((self.avant or {}).get("teintes") or [])
        _ORIGINE_CTX.etat = {"origine": self.origine, "acteur": self.acteur,
                             "teintes": teinte}
        return self

    def __exit__(self, *a):
        _ORIGINE_CTX.etat = self.avant
        return False


def origine_courante() -> dict:
    """Ce qui a demandé l'action en cours. Rien de déclaré = `inconnu`, et
    `inconnu` vaut `contenu` : le défaut est le refus."""
    e = getattr(_ORIGINE_CTX, "etat", None)
    if not isinstance(e, dict):
        return {"origine": "inconnu", "acteur": "", "teintes": [], "teinte": False}
    return {"origine": e.get("origine") or "inconnu", "acteur": e.get("acteur") or "",
            "teintes": list(e.get("teintes") or []),
            "teinte": bool(e.get("teintes"))}


def origine_demande(texte: str) -> None:
    """Retient CE QUE LA PERSONNE A ÉCRIT dans ce tour.

    Sert aux gardes qui doivent distinguer « la personne l'a nommé » de « un
    texte lu l'a nommé ». Un message piégé n'écrit pas à sa place.
    """
    e = getattr(_ORIGINE_CTX, "etat", None)
    if not isinstance(e, dict):
        _ORIGINE_CTX.etat = e = {"origine": "inconnu", "acteur": "", "teintes": []}
    e["demande"] = str(texte or "")[:4000]


def origine_demande_lire() -> str:
    e = getattr(_ORIGINE_CTX, "etat", None)
    return (e or {}).get("demande", "") if isinstance(e, dict) else ""


def origine_teinter(quoi: str) -> None:
    """Un contenu extérieur vient d'entrer dans le tour."""
    e = getattr(_ORIGINE_CTX, "etat", None)
    if not isinstance(e, dict):
        _ORIGINE_CTX.etat = e = {"origine": "inconnu", "acteur": "", "teintes": []}
    t = e.setdefault("teintes", [])
    q = str(quoi or "")[:60]
    if q and q not in t:
        t.append(q)
        del t[8:]


def origine_lisible(o: dict = None) -> str:
    o = o or origine_courante()
    mots = {"chat": "vous, dans le chat", "regle": "une règle de Cassandra",
            "horaire": "une planification", "contenu": "un contenu lu",
            "inconnu": "origine non déclarée"}
    base = mots.get(o.get("origine"), "origine non déclarée")
    if o.get("acteur"):
        base += " (%s)" % o["acteur"]
    if o.get("teinte"):
        base += " — tour teinté par : " + ", ".join(o.get("teintes") or [])
    return base


# ── Feature 1 : détection des erreurs justifiant un fallback ──
def _is_fallback_worthy(err: Exception) -> bool:
    msg = str(err).lower()
    return any(x in msg for x in [
        "429", "rate limit", "rate_limit",
        "500", "502", "503", "service unavailable", "server error",
        "context length", "maximum context", "too many tokens", "context window",
        "connection", "timeout", "timed out", "read timed out",
    ])

# ── Feature 2 : compression de contexte ────────────────────────
def _maybe_compress_history(history: list) -> tuple:
    """
    Si la somme de chars de l'historique dépasse _DUAL_COMPRESSION_THRESHOLD,
    demande à l'agent secondaire de résumer les anciens messages.
    Retourne (new_history, was_compressed: bool).
    """
    if not _itare_agent_available():
        return history, False
    total = sum(len(str(m.get("content", ""))) for m in history)
    if total <= _DUAL_COMPRESSION_THRESHOLD:
        return history, False

    keep        = _DUAL_COMPRESSION_KEEP_RECENT
    to_compress = history[:-keep] if len(history) > keep else []
    recent      = history[-keep:] if len(history) > keep else history
    if not to_compress:
        return history, False

    conv_text = "\n\n".join(
        f"[{m['role'].upper()}]: {str(m.get('content',''))[:3000]}"
        for m in to_compress
    )
    summary = _itare_agent_text(
        user_msgs=[{"role": "user", "content":
            "Voici un historique entre un utilisateur et Cassandra, une IA sysadmin Linux. "
            "Produis un résumé technique dense en conservant : toutes les commandes exécutées, "
            "fichiers modifiés, erreurs rencontrées, décisions prises, et contexte système "
            "important. Ne perds aucun fait technique.\n\n" + conv_text
        }],
        max_tokens=2000
    )
    if not summary:
        return history, False

    compressed = [{
        "role":    "system",
        "content": (
            f"[📝 HISTORIQUE COMPRESSÉ PAR AGENT SECONDAIRE "
            f"— {len(to_compress)} messages résumés]\n\n{summary}\n\n"
            "[↓ Messages récents non compressés :]"
        )
    }] + list(recent)
    print(f"[DualAgent] Compression: {total} chars → résumé ({len(summary)} chars), {len(recent)} msgs récents conservés")
    return compressed, True

# ── Feature 3 : pré-analyse des requêtes complexes ─────────────
def _complexity_score(msg: str) -> int:
    score = 0
    if len(msg) > 300:               score += 1
    if len(msg) > 700:               score += 1
    if msg.count("?") >= 2:          score += 1
    if len(msg.split("\n")) >= 5:    score += 1
    if len(msg.split()) >= 80:       score += 1
    kw = ["puis", "ensuite", "après", "et aussi", "également", "de plus",
          "premièrement", "deuxièmement", "troisièmement", "d'abord",
          "then", "also", "additionally", "moreover", "furthermore",
          "step", "étape", "first", "second", "third", "en même temps"]
    if any(k in msg.lower() for k in kw): score += 1
    return score

def _maybe_preanalyze(msg: str) -> str:
    """
    Pour les messages complexes, envoie la requête à l'agent secondaire
    pour décomposition. Retourne une annotation à injecter, ou "".
    """
    if not _itare_agent_available():
        return ""
    if len(msg) < _DUAL_PREANALYSIS_MIN_CHARS:
        return ""
    if _complexity_score(msg) < _DUAL_PREANALYSIS_MIN_SCORE:
        return ""
    analysis = _itare_agent_text(
        system=(
            "Tu es un assistant d'analyse de requêtes pour Cassandra, une IA sysadmin Linux. "
            "Décompose les requêtes complexes en étapes ordonnées et concrètes. "
            "Identifie les dépendances, ambiguïtés et risques potentiels. "
            "Réponds en français, de façon concise (150 mots max)."
        ),
        user_msgs=[{"role": "user", "content":
            f"Décompose cette requête en étapes claires et ordonnées :\n\n{msg}"
        }],
        max_tokens=350
    )
    if not analysis:
        return ""
    return f"\n\n[🧠 Pré-analyse (agent secondaire)]\n{analysis}\n[Fin pré-analyse]"

# ── PLUSIEURS PIÈCES JOINTES ────────────────────────────────────────────────
# Vingt fichiers d'un coup, comme les chats publics le permettent. Deux bornes,
# et elles ne disent pas la même chose :
#
#   · `_LAB_DOCS_MAX` — combien de fichiers on lit. Au-delà, on le DIT.
#   · `_LAB_DOCS_BUDGET` — combien de signes ils occupent ENSEMBLE. Chaque
#     fichier est déjà borné par l'extracteur, mais vingt fois cette borne
#     chasseraient du contexte tout le reste : les notes, l'historique, et la
#     question elle-même. Le budget se PARTAGE — deux fichiers ont chacun
#     beaucoup de place, vingt en ont chacun moins, et personne n'est muet.
_LAB_DOCS_MAX = 50
_LAB_DOCS_BUDGET = 400_000
# LE PLANCHER EST UN FILET, PAS UNE PROMESSE. Posé à 20 000, il entrait en
# contradiction avec le budget : cinquante fichiers réclamaient un million de
# signes pour quatre cent mille disponibles, et les trente derniers repartaient
# les mains vides. Il doit rester sous `_LAB_DOCS_BUDGET // _LAB_DOCS_MAX`,
# sinon il ne protège pas les derniers, il les affame.
_LAB_DOCS_PART_MIN = 4_000


def _lab_textes_assembler(items: list):
    """Le texte de plusieurs pièces DÉJÀ LUES, borné, qui DIT ce qu'il a écarté.

    `items` = [{"nom": str, "texte": str, "erreur": str}]. Rend `None` quand
    rien n'est lisible : l'appelant distingue « aucune pièce » de « des pièces
    illisibles », et le second cas se raconte.
    """
    items = [i for i in (items or []) if isinstance(i, dict)]
    if not items:
        return None
    part = max(_LAB_DOCS_PART_MIN, _LAB_DOCS_BUDGET // max(1, len(items)))
    morceaux, reste, refuses = [], _LAB_DOCS_BUDGET, []
    for it in items[:_LAB_DOCS_MAX]:
        nom = str(it.get("nom") or "fichier")
        txt = (it.get("texte") or "").strip()
        if not txt:
            refuses.append("%s : %s" % (nom, it.get("erreur") or "aucun texte"))
            continue
        place = min(part, reste)
        if place <= 0:
            refuses.append("%s (plus de place)" % nom)
            continue
        coupe = bool(it.get("coupe")) or len(txt) > place
        txt = txt[:place]
        reste -= len(txt)
        morceaux.append("[" + nom + "]" + chr(10) + txt
                        + ((chr(10) + "…(tronqué)") if coupe else ""))
    if len(items) > _LAB_DOCS_MAX:
        refuses.append("%d fichier(s) au-delà des %d que je peux lire"
                       % (len(items) - _LAB_DOCS_MAX, _LAB_DOCS_MAX))
    if refuses:
        morceaux.append("(Non lus, et il faut le dire à l'utilisateur s'il "
                        "s'appuie dessus : " + " ; ".join(refuses) + ")")
    return (chr(10) + chr(10)).join(morceaux) or None


def _lab_docs_texte(docs: list):
    """Le chemin DIRECT : des base64 dans la requête, extraits sur-le-champ.

    Il reste pour un onglet resté ouvert avant la mise à jour, et pour les
    envois qui ne passent pas par le dépôt. Le chemin normal est le dépôt.
    """
    items = []
    for d in (docs or []):
        if not isinstance(d, dict) or not d.get("b64"):
            continue
        nom = str(d.get("name") or "fichier")
        try:
            brut = base64.b64decode(str(d.get("b64")), validate=False)
            ex = _extract_text_from_upload(brut, str(d.get("mime") or ""), nom)
        except Exception as e:
            logging.debug("[LAB-DOC] %s : %s", nom, e)
            items.append({"nom": nom, "texte": "", "erreur": "illisible"})
            continue
        items.append({"nom": nom, "texte": ex.get("text") or "",
                      "coupe": bool(ex.get("truncated")),
                      "erreur": ex.get("error") or "aucun texte"})
    return _lab_textes_assembler(items)


# ── LE DÉPÔT, PAR SESSION ────────────────────────────────────────────────────
# En BASE et non en mémoire vive : un redémarrage du service ne doit pas faire
# disparaître ce qu'on vient de déposer, et la conversation d'une session peut
# s'appuyer sur un document reçu vingt messages plus tôt.
_LAB_PIECES_MIGRE = [False]
# LES OCTETS VONT SUR LE DISQUE, à côté de la base. En mémoire ils auraient
# ramené le plafond qu'on venait justement de lever ; en base, ils auraient
# gonflé un fichier qu'on lit à chaque message. Sur le disque, ils ne coûtent
# rien tant qu'on ne les demande pas — et c'est eux qui permettent de verser
# une pièce dans la GED longtemps après l'avoir déposée.
_LAB_PIECES_FICHIERS = os.path.join(os.path.dirname(MEMORY_DB_PATH), "pieces")
# Le dernier ménage périodique, pour ne pas le refaire à chaque tour de veille.
_PIECES_MENAGE_LAST = [0.0]
_LAB_PIECES_TTL_H = 24          # ce qui n'est pas repris en un jour est oublié
_LAB_PIECES_TEXTE_MAX = 4_000_000   # par session, tous fichiers confondus


def _lab_pieces_dir() -> str:
    """La racine des octets, créée à la demande et fermée aux autres comptes
    du système : ce sont les documents de quelqu'un."""
    try:
        os.makedirs(_LAB_PIECES_FICHIERS, mode=0o700, exist_ok=True)
        os.chmod(_LAB_PIECES_FICHIERS, 0o700)
    except Exception as e:
        logging.debug("[PIECES] dossier : %s", e)
    return _LAB_PIECES_FICHIERS


def _lab_piece_ranger(nom: str, octets: bytes) -> str:
    """Range les octets sous un nom TIRÉ AU SORT, et rend le chemin.

    Le nom d'origine ne sert PAS de nom de fichier : une archive peut contenir
    « ../../etc/passwd », et deux pièces peuvent porter le même nom. Le vrai nom
    vit en base, où il ne désigne aucun chemin.
    """
    try:
        d = _lab_pieces_dir()
        p = os.path.join(d, secrets.token_hex(16))
        with open(p, "wb") as f:
            f.write(octets)
        try:
            os.chmod(p, 0o600)
        except Exception:
            pass
        return p
    except Exception as e:
        logging.info("[PIECES] rangement de %s : %s", nom, e)
        return ""


def _lab_piece_effacer(chemin: str):
    """Sans bruit, et sans jamais lever : c'est du ménage, pas une opération."""
    if not chemin:
        return
    try:
        if os.path.realpath(chemin).startswith(
                os.path.realpath(_LAB_PIECES_FICHIERS) + os.sep):
            os.unlink(chemin)
    except Exception:
        pass


def _lab_pieces_migrer(conn):
    conn.execute("CREATE TABLE IF NOT EXISTS lab_pieces ("
                 "id INTEGER PRIMARY KEY AUTOINCREMENT, "
                 "session TEXT, compte TEXT, nom TEXT, mime TEXT, "
                 "octets INTEGER, signes INTEGER, methode TEXT, "
                 "texte TEXT, erreur TEXT, ts TEXT)")
    # LA COLONNE DES OCTETS s'ajoute aux bases déjà en service : sans cet ALTER,
    # une installation existante lèverait sur chaque dépôt.
    try:
        conn.execute("ALTER TABLE lab_pieces ADD COLUMN fichier TEXT")
    except Exception:
        pass
    # D'OÙ VIENT LA PIÈCE : le nom de l'archive, quand elle en sort d'une.
    try:
        conn.execute("ALTER TABLE lab_pieces ADD COLUMN archive TEXT")
    except Exception:
        pass
    for sql in ("CREATE INDEX IF NOT EXISTS ix_lab_pieces_s "
                "ON lab_pieces(session, compte)",):
        try:
            conn.execute(sql)
        except Exception:
            pass
    _LAB_PIECES_MIGRE[0] = True


def _lab_pieces_conn():
    conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
    conn.row_factory = sqlite3.Row
    if not _LAB_PIECES_MIGRE[0]:
        _lab_pieces_migrer(conn)
        conn.commit()
    return conn


def lab_pieces_purger(heures: int = _LAB_PIECES_TTL_H) -> int:
    """Ce qui a dépassé son temps s'en va — la ligne ET ses octets.

    Effacer la ligne sans le fichier remplirait le disque de pièces que plus
    rien ne désigne : une fuite lente, et invisible jusqu'au jour où le disque
    est plein.
    """
    conn = None
    try:
        conn = _lab_pieces_conn()
        vieux = conn.execute(
            "SELECT fichier FROM lab_pieces WHERE ts < datetime('now', ?)",
            ("-%d hours" % max(1, int(heures)),)).fetchall()
        cur = conn.execute(
            "DELETE FROM lab_pieces WHERE ts < datetime('now', ?)",
            ("-%d hours" % max(1, int(heures)),))
        conn.commit()
        for v in vieux:
            _lab_piece_effacer(v["fichier"])
        # LES ORPHELINS : des octets sur le disque que plus AUCUNE ligne ne
        # désigne. Ils naissent d'un arrêt entre l'écriture et l'écriture en
        # base — rare, mais rien ne les emporte jamais, et c'est exactement la
        # fuite lente qu'on ne voit qu'au disque plein.
        #
        # UN DÉLAI DE GRÂCE D'UNE HEURE : un fichier qui vient d'être écrit et
        # dont la transaction n'est pas encore validée ressemble en tout point
        # à un orphelin. L'effacer serait détruire un dépôt en cours.
        try:
            connus = set(x[0] for x in conn.execute(
                "SELECT fichier FROM lab_pieces WHERE fichier IS NOT NULL")
                if x[0])
            limite = time.time() - 3600
            for f in os.listdir(_lab_pieces_dir()):
                p = os.path.join(_LAB_PIECES_FICHIERS, f)
                if p in connus or not os.path.isfile(p):
                    continue
                if os.path.getmtime(p) > limite:
                    continue
                _lab_piece_effacer(p)
        except Exception as e:
            logging.debug("[PIECES] orphelins : %s", e)
        return cur.rowcount or 0
    except Exception as e:
        logging.debug("[PIECES] purge : %s", e)
        return 0
    finally:
        if conn:
            try:
                conn.close()
            except Exception:
                pass


def lab_pieces_bilan() -> dict:
    """Ce que le dossier des pièces occupe, et ce qui y traîne.

    OBSERVATION SEULEMENT — aucun effacement ici. Un détecteur qui range ce
    qu'il mesure ne mesure plus rien : il rendrait toujours « tout va bien »,
    et l'on ne saurait jamais qu'il y avait quelque chose à ranger.
    """
    out = {"ok": True, "octets": 0, "fichiers": 0, "orphelins": 0,
           "orphelins_octets": 0, "lignes": 0, "perimees": 0, "sans_fichier": 0}
    conn = None
    try:
        conn = _lab_pieces_conn()
        r0 = conn.execute(
            "SELECT COUNT(*) n, SUM(CASE WHEN ts < datetime('now', ?) "
            "THEN 1 ELSE 0 END) p FROM lab_pieces",
            ("-%d hours" % _LAB_PIECES_TTL_H,)).fetchone()
        out["lignes"] = int(r0["n"] or 0)
        out["perimees"] = int(r0["p"] or 0)
        connus = set()
        for x in conn.execute("SELECT fichier FROM lab_pieces"):
            if x[0]:
                connus.add(x[0])
            else:
                out["sans_fichier"] += 1
        d = _lab_pieces_dir()
        for f in os.listdir(d):
            p = os.path.join(d, f)
            if not os.path.isfile(p):
                continue
            t = os.path.getsize(p)
            out["fichiers"] += 1
            out["octets"] += t
            if p not in connus:
                out["orphelins"] += 1
                out["orphelins_octets"] += t
        return out
    except Exception as e:
        logging.debug("[PIECES] bilan : %s", e)
        out["ok"] = False
        out["error"] = str(e)[:160]
        return out
    finally:
        if conn:
            try:
                conn.close()
            except Exception:
                pass


def _lab_piece_une(conn, session: str, compte: str, nom: str, mime: str,
                   octets: bytes, archive: str = "") -> dict:
    """Une pièce : son TEXTE pour le modèle, ses OCTETS pour la GED.

    Les deux, parce qu'ils ne servent pas à la même chose : le modèle lit du
    texte, la GED reçoit un fichier. N'en garder qu'un aurait fermé l'autre
    porte.
    """
    try:
        ex = _extract_text_from_upload(octets, str(mime or ""), nom)
    except Exception as e:
        logging.info("[PIECES] lecture de %s : %s", nom, e)
        ex = {"text": "", "error": "lecture impossible", "method": "echec"}
    texte = (ex.get("text") or "").strip()
    erreur = "" if texte else (ex.get("error") or "aucun texte")
    chemin = _lab_piece_ranger(nom, octets)
    cur = conn.execute(
        "INSERT INTO lab_pieces (session, compte, nom, mime, octets, "
        "signes, methode, texte, erreur, ts, fichier, archive) VALUES "
        "(?,?,?,?,?,?,?,?,?, datetime('now'), ?, ?)",
        (session, compte, nom, str(mime or ""), len(octets), len(texte),
         str(ex.get("method") or ""), texte, erreur, chemin, archive))
    return {"id": cur.lastrowid, "nom": nom, "signes": len(texte),
            "octets": len(octets), "methode": str(ex.get("method") or ""),
            "erreur": erreur, "archive": archive, "fichier": bool(chemin)}


def lab_piece_deposer(session: str, compte: str, nom: str, mime: str,
                      b64: str) -> dict:
    """Un fichier monte SEUL, est lu tout de suite, et son texte reste.

    UNE ARCHIVE FAIT PLUSIEURS PIÈCES. La réduire à un seul bloc de texte
    aurait perdu ce qui compte — quel fichier dit quoi — et rendu impossible
    de n'en verser qu'un dans la GED.
    """
    session = str(session or "").strip()
    compte = str(compte or "").strip()
    nom = (str(nom or "fichier").strip() or "fichier")[:200]
    if not session:
        return {"ok": False, "error": "session inconnue"}
    if not b64:
        return {"ok": False, "error": "pièce vide"}
    try:
        brut = base64.b64decode(str(b64), validate=False)
    except Exception:
        return {"ok": False, "error": "contenu illisible (base64)"}
    conn = None
    try:
        conn = _lab_pieces_conn()
        # LES BORNES DE LA SESSION, avant de lire : un fichier lu puis refusé
        # aurait coûté sa lecture pour rien — et lire un PDF scanné coûte
        # plusieurs secondes par page.
        r = conn.execute("SELECT COUNT(*) c, COALESCE(SUM(signes),0) s "
                         "FROM lab_pieces WHERE session=? AND compte=?",
                         (session, compte)).fetchone()
        place = _LAB_DOCS_MAX - int(r["c"])
        if place <= 0:
            return {"ok": False, "error": "%d pièces déjà déposées dans cette "
                                          "session" % _LAB_DOCS_MAX}
        if int(r["s"]) >= _LAB_PIECES_TEXTE_MAX:
            return {"ok": False, "error": "cette session a atteint sa réserve "
                                          "de texte"}
        _ext = nom.rsplit(".", 1)[-1].lower() if "." in nom else ""
        if _est_zip(_ext, mime):
            entrees, ecartes = _zip_entrees(brut)
            if not entrees:
                return {"ok": False, "pieces": [], "ecartes": ecartes,
                        "error": "; ".join(ecartes) or "archive vide"}
            posees = []
            for _n, _o in entrees[:place]:
                posees.append(_lab_piece_une(conn, session, compte, _n, "",
                                             _o, archive=nom))
            if len(entrees) > place:
                ecartes.append("%d fichier(s) au-delà de la place restante "
                               "dans cette session" % (len(entrees) - place))
            conn.commit()
            return {"ok": True, "archive": nom, "pieces": posees,
                    "ecartes": ecartes}
        p = _lab_piece_une(conn, session, compte, nom, mime, brut)
        conn.commit()
        return {"ok": True, "pieces": [p], "ecartes": [], **p}
    except Exception as e:
        logging.info("[PIECES] dépôt de %s : %s", nom, e)
        return {"ok": False, "error": str(e)[:200]}
    finally:
        if conn:
            try:
                conn.close()
            except Exception:
                pass


def lab_pieces_lister(session: str, compte: str) -> dict:
    """Ce que cette session a reçu. Le TEXTE ne sort pas : il peut faire des
    centaines de milliers de signes, et l'écran n'en a pas l'usage.

    Le CHEMIN des octets ne sort pas non plus — un chemin de serveur n'a rien
    à faire dans un navigateur. Seul « versable » en dit ce qu'il faut.
    """
    conn = None
    try:
        conn = _lab_pieces_conn()
        rs = conn.execute(
            "SELECT id, nom, mime, octets, signes, methode, erreur, ts, "
            "archive, fichier FROM lab_pieces WHERE session=? AND compte=? "
            "ORDER BY id", (str(session or ""), str(compte or ""))).fetchall()
        out = []
        for x in rs:
            d = dict(x)
            d["versable"] = bool(d.pop("fichier", ""))
            out.append(d)
        return {"ok": True, "pieces": out}
    except Exception as e:
        return {"ok": False, "error": str(e)[:200], "pieces": []}
    finally:
        if conn:
            try:
                conn.close()
            except Exception:
                pass


def lab_piece_oter(pid, session: str, compte: str) -> dict:
    """Retirer une pièce, et SES OCTETS. Par session ET par compte : un
    identifiant deviné ne doit pas laisser effacer le document d'un autre."""
    conn = None
    try:
        conn = _lab_pieces_conn()
        row = conn.execute("SELECT fichier FROM lab_pieces WHERE id=? AND "
                           "session=? AND compte=?",
                           (int(pid), str(session or ""),
                            str(compte or ""))).fetchone()
        cur = conn.execute("DELETE FROM lab_pieces WHERE id=? AND session=? "
                           "AND compte=?",
                           (int(pid), str(session or ""), str(compte or "")))
        conn.commit()
        if not cur.rowcount:
            return {"ok": False, "error": "pièce introuvable"}
        if row:
            _lab_piece_effacer(row["fichier"])
        return {"ok": True}
    except Exception as e:
        return {"ok": False, "error": str(e)[:200]}
    finally:
        if conn:
            try:
                conn.close()
            except Exception:
                pass


def lab_pieces_octets(ids: list, compte: str) -> list:
    """[(nom, octets)] des pièces DU COMPTE, dans l'ordre demandé.

    Le filtre porte sur le COMPTE et non sur la session : c'est un outil, il
    agit pour quelqu'un, pas depuis un onglet. Les pièces d'un AUTRE compte
    restent hors de portée — c'est la seule frontière qui compte ici.
    """
    ids = [int(i) for i in (ids or []) if str(i).strip().lstrip("-").isdigit()]
    if not ids:
        return []
    conn = None
    try:
        conn = _lab_pieces_conn()
        marques = ",".join("?" for _ in ids)
        rs = conn.execute(
            "SELECT id, nom, fichier FROM lab_pieces WHERE id IN (%s) AND "
            "compte=?" % marques, tuple(ids) + (str(compte or ""),)).fetchall()
        par_id = {int(x["id"]): x for x in rs}
        out = []
        for i in ids:
            x = par_id.get(i)
            if not x or not x["fichier"] or not os.path.isfile(x["fichier"]):
                continue
            try:
                with open(x["fichier"], "rb") as f:
                    out.append((x["nom"], f.read()))
            except Exception as e:
                logging.debug("[PIECES] lecture de %s : %s", x["nom"], e)
        return out
    except Exception as e:
        logging.info("[PIECES] octets : %s", e)
        return []
    finally:
        if conn:
            try:
                conn.close()
            except Exception:
                pass


def lab_piece_vers_ged(pid, session: str, compte: str) -> dict:
    """Verser une pièce de session dans les Documents DU COMPTE.

    C'est le passage du provisoire au durable : la session s'efface au bout
    d'un jour, la GED reste. Le dossier visé est celui du compte — jamais le
    dossier commun, qu'un versement automatique remplirait de documents que
    personne n'a choisi de partager.
    """
    conn = None
    try:
        conn = _lab_pieces_conn()
        row = conn.execute("SELECT nom, fichier FROM lab_pieces WHERE id=? "
                           "AND session=? AND compte=?",
                           (int(pid), str(session or ""),
                            str(compte or ""))).fetchone()
        if not row:
            return {"ok": False, "error": "pièce introuvable"}
        chemin = row["fichier"] or ""
        if not chemin or not os.path.isfile(chemin):
            return {"ok": False, "error": "les octets de cette pièce ne sont "
                                          "plus disponibles"}
        try:
            with open(chemin, "rb") as f:
                octets = f.read()
        except Exception as e:
            return {"ok": False, "error": str(e)[:140]}
    except Exception as e:
        return {"ok": False, "error": str(e)[:200]}
    finally:
        if conn:
            try:
                conn.close()
            except Exception:
                pass
    d = ged_dossier_compte_creer(compte)
    if not d.get("ok"):
        return {"ok": False, "error": d.get("reason") or "dossier du compte "
                                                         "indisponible"}
    return ged_deposer("local:" + d["dossier"], "", row["nom"],
                       base64.b64encode(octets).decode())


def lab_pieces_textes(ids: list, session: str, compte: str):
    """Le texte des pièces DÉSIGNÉES, dans l'ordre demandé.

    LE FILTRE PORTE SUR LA SESSION ET LE COMPTE, pas seulement sur
    l'identifiant : sans lui, un numéro deviné donnerait le document d'un autre.
    """
    ids = [int(i) for i in (ids or []) if str(i).strip().lstrip("-").isdigit()]
    if not ids:
        return None
    conn = None
    try:
        conn = _lab_pieces_conn()
        marques = ",".join("?" for _ in ids)
        rs = conn.execute(
            "SELECT id, nom, texte, erreur FROM lab_pieces "
            "WHERE id IN (%s) AND session=? AND compte=?" % marques,
            tuple(ids) + (str(session or ""), str(compte or ""))).fetchall()
        par_id = {int(r["id"]): r for r in rs}
        items = []
        for i in ids:
            r = par_id.get(i)
            if r is None:
                items.append({"nom": "pièce n° %d" % i, "texte": "",
                              "erreur": "introuvable dans cette session"})
            else:
                items.append({"nom": r["nom"], "texte": r["texte"] or "",
                              "erreur": r["erreur"] or "aucun texte"})
        return _lab_textes_assembler(items)
    except Exception as e:
        logging.info("[PIECES] relecture : %s", e)
        return None
    finally:
        if conn:
            try:
                conn.close()
            except Exception:
                pass


# ── LIRE UN .DOCX, UN .XLSX, ET UN PDF SCANNÉ ───────────────────────────────
# Ce sont des ZIP de XML. On en tire le texte par MOTIFS, pas avec un analyseur
# XML : le fichier vient de l'extérieur, et un analyseur sur une entrée hostile
# est une porte de plus. Un motif ne développe aucune entité.
_OOXML_MAX = 80 * 1024 * 1024      # ce qu'on accepte de décompresser, en tout


def _zip_ouvrir(raw_bytes: bytes, maxi: int = 0):
    """Le contenu d'un ZIP, ou None s'il n'en est pas un.

    Sert aux documents Office — qui sont des ZIP — comme aux archives que l'on
    dépose. `maxi` borne ce qu'on accepte de décompresser EN TOUT.
    """
    maxi = maxi or _OOXML_MAX
    # `io` N'EST PAS UN NOM GLOBAL de ce fichier : sans cet import, l'appel
    # lève un NameError À L'EXÉCUTION, et la compilation ne voit rien.
    import io
    import zipfile
    try:
        z = zipfile.ZipFile(io.BytesIO(raw_bytes))
    except Exception:
        return None
    # UNE BOMBE ZIP se reconnaît avant d'être ouverte : la somme des tailles
    # annoncées suffit. Décompresser d'abord pour mesurer ensuite serait
    # exactement le piège.
    try:
        if sum(i.file_size for i in z.infolist()) > maxi:
            z.close()
            return None
    except Exception:
        z.close()
        return None
    return z


def _xml_texte(xml: str) -> str:
    """Le texte d'un fragment XML : balises retirées, entités rendues."""
    import html as _h
    import re as _re
    # Les fins de paragraphe et les sauts AVANT le retrait des balises, sinon
    # tout le document se recolle en une seule ligne illisible.
    xml = _re.sub(r"<w:tab[^>]*/>", "\t", xml)
    xml = _re.sub(r"<w:br[^>]*/>", "\n", xml)
    xml = _re.sub(r"</w:p>", "\n", xml)
    xml = _re.sub(r"<[^>]+>", "", xml)
    return _h.unescape(xml)


# ── ARCHIVES ────────────────────────────────────────────────────────────────
# Les bornes disent chacune une chose différente, et aucune n'est décorative :
#   · `_ZIP_ENTREES_MAX` — combien de fichiers on sort. Au-delà, on le DIT.
#   · `_ZIP_ENTREE_MAX`  — la taille d'UN fichier extrait, lu en mémoire.
#   · `_ZIP_TOTAL_MAX`   — ce qu'on accepte de décompresser en tout, mesuré
#     AVANT d'ouvrir quoi que ce soit : c'est la parade à la bombe zip.
_ZIP_ENTREES_MAX = 50
_ZIP_ENTREE_MAX = 25 * 1024 * 1024
_ZIP_TOTAL_MAX = 250 * 1024 * 1024
_ZIP_MIMES = ("application/zip", "application/x-zip-compressed",
              "application/x-zip", "multipart/x-zip")


def _est_zip(ext: str, mime: str) -> bool:
    """Une archive ordinaire — PAS un .docx ni un .xlsx, qui en sont aussi."""
    if ext in ("docx", "xlsx", "pptx", "odt", "ods", "odp"):
        return False
    return ext == "zip" or str(mime or "") in _ZIP_MIMES


def _zip_entrees(raw_bytes: bytes) -> tuple:
    """(entrées, écartés). Chaque entrée = (nom, octets), déjà lue.

    Rien n'est écrit sur le disque ici, et aucun nom d'entrée ne sert de
    chemin : la traversée de répertoire n'a pas de prise.
    """
    z = _zip_ouvrir(raw_bytes, _ZIP_TOTAL_MAX)
    if z is None:
        return [], ["archive illisible, ou trop volumineuse une fois décompressée"]
    entrees, ecartes = [], []
    try:
        for info in z.infolist():
            nom = (info.filename or "").replace("\\", "/")
            base = os.path.basename(nom)
            if info.is_dir() or not base or base.startswith("."):
                continue
            # Les métadonnées que macOS glisse dans toute archive : elles
            # doublent la liste et ne contiennent rien de lisible.
            if nom.startswith("__MACOSX/") or base == ".DS_Store":
                continue
            if len(entrees) >= _ZIP_ENTREES_MAX:
                ecartes.append("%s (au-delà de %d fichiers)"
                               % (base, _ZIP_ENTREES_MAX))
                continue
            if info.file_size > _ZIP_ENTREE_MAX:
                ecartes.append("%s (plus de %d Mo)"
                               % (base, _ZIP_ENTREE_MAX // (1024 * 1024)))
                continue
            # UNE ARCHIVE DANS UNE ARCHIVE ne s'ouvre PAS. Descendre serait une
            # récursion sans fond, et la refuser en silence ferait croire que
            # son contenu a été lu.
            if base.lower().endswith(".zip"):
                ecartes.append("%s (archive imbriquée, non ouverte)" % base)
                continue
            try:
                entrees.append((base, z.read(info)))
            except Exception as e:
                ecartes.append("%s (%s)" % (base, str(e)[:60]))
        if not entrees and not ecartes:
            ecartes.append("archive vide")
        return entrees, ecartes
    except Exception as e:
        return entrees, ecartes + [str(e)[:120]]
    finally:
        try:
            z.close()
        except Exception:
            pass


_ZIP_PROFONDEUR = threading.local()   # niveau d'emboîtement des archives en cours de lecture


def _zip_texte(raw_bytes: bytes) -> tuple:
    """(texte, raison) — le chemin DIRECT, qui ne peut pas éclater l'archive.

    Le dépôt, lui, en fait autant de pièces distinctes. Ici on n'a qu'un envoi,
    donc on assemble, en nommant chaque fichier.
    """
    # UNE ARCHIVE DANS L'ARCHIVE, DANS L'ARCHIVE… `_extract_text_from_upload`
    # rappelle cette fonction pour chaque zip trouvé dedans : sans borne, un
    # envoi de mille zips emboîtés recurse jusqu'à la limite. Trois niveaux
    # suffisent à tout ce qu'on reçoit ; au-delà, on le dit au lieu de creuser.
    prof = getattr(_ZIP_PROFONDEUR, "n", 0)
    if prof >= 3:
        return "", "archives emboîtées au-delà de trois niveaux — non lues"
    _ZIP_PROFONDEUR.n = prof + 1
    try:
        entrees, ecartes = _zip_entrees(raw_bytes)
    finally:
        _ZIP_PROFONDEUR.n = prof
    items = []
    for nom, octets in entrees:
        _ZIP_PROFONDEUR.n = prof + 1
        try:
            ex = _extract_text_from_upload(octets, "", nom)
        except Exception as e:
            items.append({"nom": nom, "texte": "", "erreur": str(e)[:80]})
            continue
        finally:
            _ZIP_PROFONDEUR.n = prof
        items.append({"nom": nom, "texte": ex.get("text") or "",
                      "coupe": bool(ex.get("truncated")),
                      "erreur": ex.get("error") or "aucun texte"})
    for e in ecartes:
        items.append({"nom": e, "texte": "", "erreur": "écarté"})
    txt = _lab_textes_assembler(items)
    return (txt or "", "" if txt else "; ".join(ecartes) or "rien de lisible")


def _docx_texte(raw_bytes: bytes) -> tuple:
    """(texte, raison). Le corps du document, ses en-têtes et ses pieds."""
    z = _zip_ouvrir(raw_bytes)
    if z is None:
        return "", "ce .docx n'est pas un document lisible"
    try:
        noms = set(z.namelist())
        if "word/document.xml" not in noms:
            return "", "ce .docx ne contient pas de document"
        morceaux = [_xml_texte(z.read("word/document.xml").decode("utf-8", "replace"))]
        # Les notes de bas de page portent souvent l'essentiel d'un contrat.
        for extra in sorted(n for n in noms
                            if n.startswith("word/footnotes")
                            or n.startswith("word/endnotes")):
            try:
                t = _xml_texte(z.read(extra).decode("utf-8", "replace")).strip()
                if t:
                    morceaux.append("--- notes ---\n" + t)
            except Exception:
                pass
        txt = "\n".join(morceaux).strip()
        return (txt, "" if txt else "document vide")
    except Exception as e:
        return "", str(e)[:200]
    finally:
        try:
            z.close()
        except Exception:
            pass


def _xlsx_texte(raw_bytes: bytes, max_lignes: int = 5000) -> tuple:
    """(texte, raison). Chaque feuille en tableau, colonnes séparées par des
    tabulations — la forme qu'un modèle lit le mieux."""
    import re as _re
    z = _zip_ouvrir(raw_bytes)
    if z is None:
        return "", "ce .xlsx n'est pas un classeur lisible"
    try:
        noms = z.namelist()
        # LA TABLE DES CHAÎNES PARTAGÉES. Sans elle, chaque cellule de texte
        # n'est qu'un NUMÉRO : le tableau arriverait rempli de chiffres.
        partagees = []
        if "xl/sharedStrings.xml" in noms:
            brut = z.read("xl/sharedStrings.xml").decode("utf-8", "replace")
            for si in _re.findall(r"<si>(.*?)</si>", brut, _re.S):
                partagees.append(_xml_texte(si).replace("\n", " ").strip())
        # Le nom des feuilles, dans l'ordre du classeur.
        titres = []
        if "xl/workbook.xml" in noms:
            wb = z.read("xl/workbook.xml").decode("utf-8", "replace")
            titres = [_re.sub(r"&amp;", "&", t)
                      for t in _re.findall(r'<sheet[^>]*name="([^"]*)"', wb)]
        feuilles = sorted(n for n in noms
                          if n.startswith("xl/worksheets/sheet") and n.endswith(".xml"))
        sorties, lignes_vues = [], 0
        for idx, f in enumerate(feuilles):
            titre = titres[idx] if idx < len(titres) else os.path.basename(f)
            xmlf = z.read(f).decode("utf-8", "replace")
            rangs = []
            for row in _re.findall(r"<row[^>]*>(.*?)</row>", xmlf, _re.S):
                if lignes_vues >= max_lignes:
                    rangs.append("…(feuille tronquée)")
                    break
                cellules = []
                for attrs, corps in _re.findall(r"<c([^>]*)>(.*?)</c>", row, _re.S):
                    val = ""
                    typ = _re.search(r'\bt="([^"]+)"', attrs)
                    typ = typ.group(1) if typ else ""
                    if typ == "s":
                        num = _re.search(r"<v>(\d+)</v>", corps)
                        if num:
                            i = int(num.group(1))
                            val = partagees[i] if i < len(partagees) else ""
                    elif typ == "inlineStr":
                        val = _xml_texte(corps).replace("\n", " ").strip()
                    else:
                        num = _re.search(r"<v>(.*?)</v>", corps, _re.S)
                        val = (num.group(1) if num else "").strip()
                    cellules.append(val)
                while cellules and not cellules[-1]:
                    cellules.pop()
                if cellules:
                    rangs.append("\t".join(cellules))
                lignes_vues += 1
            if rangs:
                sorties.append("=== %s ===\n%s" % (titre, "\n".join(rangs)))
        txt = "\n\n".join(sorties).strip()
        return (txt, "" if txt else "classeur vide")
    except Exception as e:
        return "", str(e)[:200]
    finally:
        try:
            z.close()
        except Exception:
            pass


_PDF_OCR_PAGES = 10


def _pdf_ocr_texte(raw_bytes: bytes, max_pages: int = _PDF_OCR_PAGES) -> tuple:
    """(texte, raison). Un PDF scanné est fait d'IMAGES : on les rend, on les lit.

    Coûteux, donc en DERNIER RECOURS seulement — quand l'extraction ordinaire
    n'a rien trouvé. Un PDF de texte n'y passe jamais.
    """
    import glob
    import shutil
    import tempfile
    manque = [o for o in ("pdftoppm", "tesseract") if not shutil.which(o)]
    if manque:
        return "", ("reconnaissance de caractères indisponible : %s manquant "
                    "(paquets poppler-utils et tesseract-ocr)" % ", ".join(manque))
    d = tempfile.mkdtemp(prefix="cass_ocr_")
    try:
        src = os.path.join(d, "src.pdf")
        with open(src, "wb") as f:
            f.write(raw_bytes)
        subprocess.run(["pdftoppm", "-r", "200", "-png", "-f", "1",
                        "-l", str(int(max_pages)), src, os.path.join(d, "p")],
                       capture_output=True, timeout=240)
        pages = sorted(glob.glob(os.path.join(d, "p-*.png")))
        if not pages:
            return "", "le PDF n'a pas pu être rendu en images"
        morceaux = []
        for i, p in enumerate(pages, 1):
            try:
                r = subprocess.run(["tesseract", p, "stdout", "-l", "fra+eng"],
                                   capture_output=True, timeout=90)
                t = r.stdout.decode("utf-8", "replace").strip()
            except Exception:
                t = ""
            if t:
                morceaux.append("--- page %d ---\n%s" % (i, t))
        if not morceaux:
            return "", "aucun texte reconnu dans les images de ce PDF"
        reste = ""
        if len(pages) >= max_pages:
            reste = ("\n\n(seules les %d premières pages ont été lues par "
                     "reconnaissance de caractères)" % max_pages)
        return "\n\n".join(morceaux) + reste, ""
    except Exception as e:
        return "", str(e)[:200]
    finally:
        import shutil as _sh
        _sh.rmtree(d, ignore_errors=True)


def _extract_text_from_upload(raw_bytes: bytes, mime: str, filename: str) -> dict:
    """
    Extrait le texte d'un fichier uploadé.
    Retourne {"text": str, "truncated": bool, "method": str, "error": str|None}
    """
    MAX_CHARS = 120_000  # ~ 30k tokens — contexte étendu
    ext = filename.rsplit(".", 1)[-1].lower() if "." in filename else ""

    # ── Fichiers texte / code ──────────────────────────────────
    TEXT_EXTS = {
        "txt","md","rst","csv","tsv","json","jsonl","yaml","yml",
        "xml","html","htm","css","js","ts","py","sh","bash","zsh",
        "php","rb","go","rs","java","c","cpp","h","hpp","sql","ini",
        "conf","env","log","toml","tf","dockerfile"
    }
    if ext in TEXT_EXTS or mime.startswith("text/"):
        try:
            text = raw_bytes.decode("utf-8", errors="replace")
            truncated = len(text) > MAX_CHARS
            return {"text": text[:MAX_CHARS], "truncated": truncated, "method": "text", "error": None}
        except Exception as e:
            return {"text": "", "truncated": False, "method": "text", "error": str(e)}

    # ── Documents de bureau (OOXML) ───────────────────────────
    # Ils arrivent avec des types MIME à rallonge que tout le monde écrit
    # différemment : c'est l'EXTENSION qui décide, avec le type en secours.
    if ext == "docx" or "wordprocessingml" in mime:
        txt, raison = _docx_texte(raw_bytes)
        if txt:
            return {"text": txt[:MAX_CHARS], "truncated": len(txt) > MAX_CHARS,
                    "method": "docx", "error": None}
        return {"text": "", "truncated": False, "method": "docx_vide",
                "error": raison or "aucun texte dans ce document"}
    if ext == "xlsx" or "spreadsheetml" in mime:
        txt, raison = _xlsx_texte(raw_bytes)
        if txt:
            return {"text": txt[:MAX_CHARS], "truncated": len(txt) > MAX_CHARS,
                    "method": "xlsx", "error": None}
        return {"text": "", "truncated": False, "method": "xlsx_vide",
                "error": raison or "aucune donnée dans ce classeur"}
    # Le format ANCIEN de Word et d'Excel n'est pas un ZIP : le dire tout de
    # suite vaut mieux qu'un « type non supporté » qui ne nomme pas le remède.
    # UNE ARCHIVE, sur le chemin direct : on ne peut pas l'éclater ici — il n'y
    # a qu'un envoi — donc on assemble en nommant chaque fichier. Le DÉPÔT, lui,
    # en fait autant de pièces distinctes.
    if _est_zip(ext, mime):
        txt, raison = _zip_texte(raw_bytes)
        if txt:
            return {"text": txt[:MAX_CHARS], "truncated": len(txt) > MAX_CHARS,
                    "method": "zip", "error": None}
        return {"text": "", "truncated": False, "method": "zip_vide",
                "error": raison or "rien de lisible dans cette archive"}
    if ext in ("doc", "xls"):
        return {"text": "", "truncated": False, "method": "office_ancien",
                "error": "format ancien (.%s) : enregistrez-le en .%sx" % (ext, ext)}

    # ── PDF ───────────────────────────────────────────────────
    if ext == "pdf" or mime == "application/pdf":
        # UN SUCCÈS VIDE EST UN ÉCHEC. `pdftotext` rend 0 sur un PDF scanné et
        # ne trouve rien : on rendait « lu, texte vide », et l'appelant croyait
        # avoir le document. Trois tentatives, de la moins chère à la plus
        # coûteuse, et la dernière rend les pages en images pour les lire.
        import io
        import re as _re
        texte, methode = "", ""

        def _maigre(t):
            return len(_re.sub(r"\s", "", t or "")) < 20

        # 1. pdftotext (poppler) — quasi instantané.
        try:
            _r1 = subprocess.run(["pdftotext", "-", "-"], input=raw_bytes,
                                 capture_output=True, timeout=30)
            if _r1.returncode == 0:
                texte = _r1.stdout.decode("utf-8", errors="replace").strip()
                methode = "pdftotext"
        except Exception:
            pass
        # 2. pypdf — s'il est installé, et si le premier n'a rien donné.
        if _maigre(texte):
            try:
                try:
                    from pypdf import PdfReader
                except ImportError:
                    from PyPDF2 import PdfReader  # type: ignore
                _rd = PdfReader(io.BytesIO(raw_bytes))
                _t2 = "\n".join((p.extract_text() or "") for p in _rd.pages).strip()
                if not _maigre(_t2):
                    texte, methode = _t2, "pypdf"
            except Exception:
                pass
        # 3. LA RECONNAISSANCE DE CARACTÈRES, en dernier recours. Un PDF de
        # texte n'y passe jamais : elle coûte plusieurs secondes par page.
        if _maigre(texte):
            _ocr, _raison = _pdf_ocr_texte(raw_bytes)
            if _ocr:
                return {"text": _ocr[:MAX_CHARS], "truncated": len(_ocr) > MAX_CHARS,
                        "method": "ocr-pdf", "error": None}
            return {"text": "", "truncated": False, "method": "pdf_vide",
                    "error": ("aucun texte extractible de ce PDF"
                              + ((" — " + _raison) if _raison else ""))}
        return {"text": texte[:MAX_CHARS], "truncated": len(texte) > MAX_CHARS,
                "method": methode, "error": None}

    # ── Images ────────────────────────────────────────────────
    if mime.startswith("image/"):
        # On accepte l'image si le modèle principal gère la vision OU si l'agent
        # secondaire (vision/OpenRouter) est configuré : dans les deux cas l'envoi
        # saura router l'image (natif, ou délégation à _vision_fallback_analyze).
        if _model_supports_vision() or _itare_agent_available():
            return {"text": None, "image_b64": base64.b64encode(raw_bytes).decode(),
                    "mime": mime, "truncated": False, "method": "vision", "error": None}
        else:
            # Essai OCR via tesseract
            try:
                import subprocess as _sp, tempfile
                suffix = "." + (ext or "png")
                with tempfile.NamedTemporaryFile(suffix=suffix, delete=False) as tmp:
                    tmp.write(raw_bytes); tmp_path = tmp.name
                result = _sp.run(["tesseract", tmp_path, "stdout", "-l", "fra+eng"],
                                  capture_output=True, timeout=20)
                os.unlink(tmp_path)
                if result.returncode == 0:
                    text = result.stdout.decode("utf-8", errors="replace").strip()
                    return {"text": f"[OCR IMAGE — {filename}]\n{text}" if text else "[Image sans texte détectable]",
                            "truncated": False, "method": "ocr", "error": None}
            except Exception:
                pass
            return {"text": None, "truncated": False, "method": "vision_unsupported",
                    "error": f"Le modèle '{MODEL_NAME}' ne supporte pas les images. Utilisez GPT-4o, Claude 3 ou un modèle vision via OpenRouter."}

    # ── Fallback binaire ──────────────────────────────────────
    return {"text": "", "truncated": False, "method": "unsupported",
            "error": f"Type de fichier non supporté : {mime} (.{ext})"}


def get_server_info():
    """Infos statiques/semi-statiques sur le serveur : OS, kernel, IP, CPU, uptime, disques."""
    import platform, subprocess as sp
    try:
        uname = os.uname()
        kernel  = uname.release
        hostname = uname.nodename
        cpu_cores = os.cpu_count() or 1
        # IP principale
        try:
            ip_raw = sp.check_output(["hostname", "-I"], timeout=2).decode().strip()
            ip = ip_raw.split()[0] if ip_raw else "?"
        except Exception:
            try:
                ip = _socket_mod.gethostbyname(_socket_mod.gethostname())
            except Exception:
                ip = "?"
        # Uptime système (depuis /proc/uptime, pas depuis START_TIME)
        try:
            with open("/proc/uptime") as f:
                uptime_secs = int(float(f.read().split()[0]))
        except Exception:
            uptime_secs = int(time.time() - START_TIME)
        # Nombre de disques physiques
        try:
            disk_count = int(sp.check_output(
                "lsblk -d -n -o TYPE | grep -c disk || echo 0",
                shell=True, timeout=3
            ).decode().strip())
        except Exception:
            disk_count = 0
        # Distro
        try:
            with open("/etc/os-release") as f:
                lines = {}
                for l in f:
                    if "=" in l:
                        k, v = l.strip().split("=", 1)
                        lines[k] = v.strip().strip('"')
            distro = lines.get("PRETTY_NAME") or lines.get("NAME") or platform.system()
        except Exception:
            distro = platform.system()
        try:
            _tz_off = datetime.now().astimezone().utcoffset().total_seconds()
        except Exception:
            _tz_off = 0
        return {
            "hostname":    hostname,
            "os":          distro,
            "kernel":      kernel,
            "ip":          ip,
            "cpu_cores":   cpu_cores,
            "uptime_secs": uptime_secs,
            # Le temps de marche de CASSANDRA, pas de la machine (24-09) : le pied du menu dit « v18 · en ligne depuis »,
            # et affichait les 8 jours d'Orion quelques minutes après un redémarrage du service.
            "cassandra_uptime_secs": int(time.time() - START_TIME),
            "disk_count":  disk_count,
            "server_time":      time.time(),   # epoch serveur (pour l'horloge du header)
            "server_tz_offset": _tz_off,       # décalage UTC serveur (secondes, DST inclus)
        }
    except Exception as e:
        return {"error": str(e)}


def get_rclone_remotes():
    data = get_entity_from_socket("rclone_remotes")
    return data if data else query_db("SELECT name, type, used_gb FROM rclone_remotes")


def get_web_sites():
    data = get_entity_from_socket("web_sites")
    return data if data else query_db("SELECT domain, ssl_enabled, php_version FROM web_sites WHERE status = 'active'")


def _fleet_etats() -> dict:
    """L'état déclaré de chaque machine (réglage `fleet_etats`) :
    attendue (défaut), intermittente, retiree. Noms en minuscules."""
    try:
        d = get_cassandra_config().get("fleet_etats") or {}
        return {str(k).strip().lower(): str(v).strip().lower() for k, v in d.items()} if isinstance(d, dict) else {}
    except Exception:
        return {}


def _fleet_machines() -> list:
    """Les machines de la flotte et leur présence, depuis les DEUX sources qui
    existent : le module multi-serveurs (`fleet_state_seen`, base mémoire) et
    les pairs Tailscale relevés par le collecteur (`tailscale_peers`, base
    principale). Jamais le réseau : un score ne doit pas attendre un NAS."""
    vus = {}
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=5)
        # une trace de plus d'un jour est une disparue (la passe rafraîchit ts à chaque tour) : pas une panne
        recent = (_utcnow() - timedelta(days=1)).strftime("%Y-%m-%d %H:%M:%S")
        for nom, en_ligne in conn.execute("SELECT name, online FROM fleet_state_seen WHERE ts >= ? OR ts IS NULL OR ts = ''", (recent,)):
            if nom:
                vus[str(nom).strip().lower()] = bool(en_ligne)
        conn.close()
    except Exception:
        pass
    try:
        for r in (query_db("SELECT name, online FROM tailscale_peers") or []):
            nom = str((r.get("name") if isinstance(r, dict) else r[0]) or "").strip().lower()
            en_ligne = bool((r.get("online") if isinstance(r, dict) else r[1]))
            if nom and nom not in vus:
                vus[nom] = en_ligne
    except Exception:
        pass
    etats = _fleet_etats()
    return [{"nom": n, "en_ligne": v, "etat": etats.get(n, "attendue")} for n, v in sorted(vus.items())]


def _fleet_penalite() -> tuple:
    """Malus de santé et détail de flotte. Une machine ATTENDUE hors ligne est
    une panne (malus par machine, plafonné) ; une INTERMITTENTE hors ligne est
    dite, pas comptée ; une RETIREE est ignorée. Le défaut ancien : « santé
    100/100 » avec deux machines hors ligne — la pénalité lisait une table
    vide pendant que le rapport lisait Tailscale."""
    machines = _fleet_machines()
    detail = {"en_ligne": [], "hors_ligne": [], "intermittentes_hors_ligne": [], "retirees": []}
    for m in machines:
        if m["etat"] == "retiree":
            detail["retirees"].append(m["nom"])
        elif m["en_ligne"]:
            detail["en_ligne"].append(m["nom"])
        elif m["etat"] == "intermittente":
            detail["intermittentes_hors_ligne"].append(m["nom"])
        else:
            detail["hors_ligne"].append(m["nom"])
    if not detail["hors_ligne"]:
        return 0, detail
    par_machine = max(0, min(int(_mem_cfg("fleet_health_penalty", 12)), 50))
    return min(len(detail["hors_ligne"]) * par_machine, 60), detail


def get_health_score():
    """Score de santé, pénalisé par les machines ATTENDUES hors ligne — et qui
    porte TOUJOURS son détail de flotte : un 100 sans détail ne prouvait rien."""
    base = _get_health_score_local()
    try:
        malus, detail = _fleet_penalite()
    except Exception as e:
        logging.debug("[SANTÉ] pénalité flotte : %s", e)
        return base
    bd = dict(base.get("breakdown") or {})
    bd["flotte"] = dict(detail, malus=-malus)
    try:
        score = max(0.0, float(base.get("score", 0)) - malus)
    except (TypeError, ValueError):
        return dict(base, breakdown=bd, fleet_offline=detail["hors_ligne"])
    statut = base.get("status", "unknown")
    if malus:
        if score < 50:
            statut = "critical"
        elif score < 75 and statut in ("ok", "good", "healthy", "excellent", "unknown"):
            statut = "warning"
    return {"score": round(score, 1), "status": statut, "breakdown": bd,
            "fleet_offline": detail["hors_ligne"]}


def _get_health_score_local():
    """
    FIX CRITIQUE: `data.get("health_score")` est falsy quand score=0 → toujours 0/unknown.
    FIX: utiliser `"health_score" in data` pour tester la présence, pas la valeur.
    FIX: le collector inclut maintenant health_score dans le cache socket (update_cache).
    ROBUSTESSE: ajout de validation de type pour data, rows, row, et gestion d'erreurs supplémentaires.
    """
    data = get_dashboard_from_socket()
    # ROBUSTESSE: vérifier que data est un dict avant d'utiliser 'in'
    if isinstance(data, dict) and "health_score" in data:
        score = data["health_score"]
        # ROBUSTESSE: valider que score est un nombre (int/float) pour éviter des erreurs en aval
        if not isinstance(score, (int, float)):
            score = 0
        return {
            "score":     score,
            "status":    data.get("health_status", "unknown"),
            "breakdown": data.get("breakdown", {}),
        }
    rows = query_db("SELECT score, status, breakdown FROM health_scores ORDER BY id DESC LIMIT 1")
    # ROBUSTESSE: vérifier que rows est une liste non vide avec isinstance et len
    if isinstance(rows, list) and len(rows) > 0:
        row = rows[0]
        # ROBUSTESSE: vérifier que row est un dict avant d'accéder à ses clés
        if isinstance(row, dict):
            import json as _j
            bd = {}
            # ROBUSTESSE: extraire breakdown_string avec fallback sûr
            breakdown_string = row.get("breakdown")
            if isinstance(breakdown_string, str):
                try:
                    bd = _j.loads(breakdown_string)
                    # ROBUSTESSE: s'assurer que le résultat est un dict
                    if not isinstance(bd, dict):
                        bd = {}
                except (json.JSONDecodeError, TypeError, ValueError):
                    bd = {}
            # ROBUSTESSE: valider score et status
            score = row.get("score", 0)
            if not isinstance(score, (int, float)):
                score = 0
            status = row.get("status", "unknown")
            if not isinstance(status, str):
                status = "unknown"
            return {"score": score, "status": status, "breakdown": bd}
    # ROBUSTESSE: retour par défaut garanti avec types corrects
    return {"score": 0, "status": "unknown", "breakdown": {}}


def get_docker_containers():
    data = get_entity_from_socket("docker_containers")
