# ============================================================
# FastPanel2 — Accesseurs DB (via socket ou fallback SQLite)
# ============================================================
# FastPanel peut stocker ses données en MySQL **ou en SQLite**. Sur une
# installation SQLite, tous les champs database_* de parameters.yml sont vides
# et un bloc `sqlite: main:` désigne le fichier. Le code ne tentait que MySQL,
# échouait, et journalisait « database_password manquant ou vide » en boucle :
# utilisateurs, bases et sauvegardes FastPanel restaient donc vides.
_FP_SQLITE_CACHE = []          # [chemin résolu] — résolu une seule fois


def _fp_sqlite_path() -> str:
    """Chemin de la base SQLite de FastPanel, ou '' si l'installation est en MySQL."""
    if _FP_SQLITE_CACHE:
        return _FP_SQLITE_CACHE[0]
    found = ""
    _pat = re.compile(r"^\s*main\s*:\s*['\"]?(\S+\.db)['\"]?\s*$")
    for cfg in ("/usr/local/fastpanel2/app/config/parameters.yml",
                "/usr/local/fastpanel2/app/config/parameters.yaml",
                "/usr/local/fastpanel2/config/database.yml"):
        try:
            for line in Path(cfg).read_text(errors="replace").splitlines():
                m = _pat.match(line)
                if m and os.path.isfile(m.group(1)):
                    found = m.group(1)
                    break
        except Exception:
            continue
        if found:
            break
    if not found and os.path.isfile("/usr/local/fastpanel2/app/db/fastpanel2.db"):
        found = "/usr/local/fastpanel2/app/db/fastpanel2.db"
    _FP_SQLITE_CACHE.append(found)
    return found


def _fp_sqlite_query(sql: str, mapper):
    """Exécute la MÊME requête que la voie MySQL, sur la base SQLite de FastPanel.

    Ouverture en LECTURE SEULE (mode=ro) : on ne doit jamais risquer d'altérer la
    base d'un autre logiciel. Les valeurs sont converties en chaînes et les NULL
    en '' pour reproduire exactement la sortie de `mysql --batch --silent`, dont
    dépendent les mappers existants (ils comparent par ex. `r[3] in ("1","true")`)."""
    path = _fp_sqlite_path()
    if not path:
        return []
    out = []
    rows = None
    # FastPanel 2 tient sa base en mode WAL : une connexion strictement read-only
    # échoue quand le fichier -shm doit être créé. On tente donc mode=ro d'abord
    # (garantie forte), puis une connexion ordinaire en repli — sur laquelle on
    # n'émet QUE des SELECT, ce qui n'altère aucune donnée.
    for _uri, _label in (("file:%s?mode=ro" % path, "ro"), (path, "rw")):
        try:
            con = sqlite3.connect(_uri, uri=_uri.startswith("file:"), timeout=5)
            try:
                rows = con.execute(sql).fetchall()
            finally:
                con.close()
            break
        except Exception as e:
            _m = str(e).lower()
            _acces = any(k in _m for k in ("unable to open", "readonly", "read-only",
                                           "attempt to write", "disk i/o"))
            if _label == "ro" and _acces:
                # Uniquement un refus d'OUVERTURE (typiquement le -shm d'une base
                # WAL). Une erreur SQL, elle, ne se règle pas en rouvrant : on la
                # remonte telle quelle plutôt que de reconnecter pour rien.
                logging.info("[FASTPANEL] ouverture read-only refusée (%s) — "
                             "repli connexion standard, SELECT uniquement", e)
                continue
            if "no such table" in _m or "no such column" in _m:
                # Schéma différent de celui attendu : ce n'est pas une panne, on
                # laisse simplement la main à la source de repli suivante.
                logging.info("[FASTPANEL] schéma inattendu (%s) — repli sur la "
                             "source suivante", e)
            else:
                logging.warning("[FASTPANEL] lecture SQLite impossible (%s) : %s", path, e)
            return []
    if rows is None:
        return []
    for row in rows:
        parts = ["" if v is None else str(v) for v in row]
        try:
            m = mapper(parts)
        except Exception as e:
            logging.warning("[FASTPANEL] mapper SQLite : %s", e)
            continue
        if m is not None:
            out.append(m)
    return out


# ══════════════════════════════════════════════════════════════════════════
# LECTURE DE LA BASE FASTPANEL
# FastPanel tient sa propre base SQLite. Elle contient ce que ni le collecteur
# ni `information_schema` ne savent : le PROPRIÉTAIRE d'une base, ses
# UTILISATEURS MySQL (table de liaison `datbases_users`, la faute de frappe est
# de FastPanel), et surtout `db.site_id` — le rattachement base ↔ site, déjà
# établi par FastPanel. On l'interrogeait à l'aveugle en laissant des colonnes
# vides ; il suffisait de regarder son schéma.
#
# LECTURE SEULE STRICTE : c'est la base d'un autre programme, en service. On
# l'ouvre en `mode=ro` — SQLite refuse alors physiquement toute écriture, y
# compris la création du journal qui suffirait à la verrouiller.
# ══════════════════════════════════════════════════════════════════════════
_FP_DB_PATHS = ("/usr/local/fastpanel2/app/db/fastpanel2.db",
                "/usr/local/fastpanel/app/db/fastpanel.db")
_FP_DB_CACHE = {"path": None, "t": 0.0}


def _fp_db_path() -> str:
    if _FP_DB_CACHE["path"] is not None and time.time() - _FP_DB_CACHE["t"] < 300:
        return _FP_DB_CACHE["path"]
    trouve = ""
    for p in _FP_DB_PATHS:
        if os.path.isfile(p) and os.access(p, os.R_OK):
            trouve = p
            break
    _FP_DB_CACHE.update({"path": trouve, "t": time.time()})
    return trouve


# La dernière raison pour laquelle la base n'a PAS répondu (2026-09-05).
# Toute exception rendait [] en INFO : une base illisible (droits, fichier
# déplacé, verrou) produisait exactement la même page qu'une base vide, et le
# résumé affichait « 0 base, 0 boîte mail » avec la sérénité d'un serveur
# propre. Vidé au premier succès.
_FP_DB_DERNIERE_ERREUR = {"message": "", "t": 0.0}


def _fp_db_query(sql: str, params=()) -> list:
    """Interroge la base FastPanel en lecture seule. [] si indisponible — et
    `_FP_DB_DERNIERE_ERREUR` dit alors pourquoi."""
    chemin = _fp_db_path()
    if not chemin:
        _FP_DB_DERNIERE_ERREUR.update({"message": "base FastPanel introuvable ou illisible (%s)"
                                                  % ", ".join(_FP_DB_PATHS), "t": time.time()})
        return []
    try:
        conn = sqlite3.connect("file:%s?mode=ro" % chemin, uri=True, timeout=5)
        try:
            rows = conn.execute(sql, params).fetchall()
        finally:
            conn.close()
        _FP_DB_DERNIERE_ERREUR.update({"message": "", "t": 0.0})
        return rows
    except Exception as e:
        # Un schéma qui évolue ne doit pas casser une page : on retombe sur les
        # sources précédentes plutôt que de rendre une erreur — mais on garde
        # la raison, pour que la page puisse la dire.
        logging.info("[FP-DB] %s", str(e)[:200])
        _FP_DB_DERNIERE_ERREUR.update({"message": str(e)[:200], "t": time.time()})
        return []


def _fp_db_colonnes(table: str) -> set:
    try:
        return {r[1] for r in _fp_db_query("PRAGMA table_info(%s)" % table)}
    except Exception:
        return set()


def _fp_erreur_source() -> dict:
    """Ce qui n'a PAS pu être lu, à joindre au résultat. {} si tout a répondu.

    Règle du projet : un zéro par absence ne doit pas ressembler à un zéro par
    conformité. Les deux sources qui peuvent se taire sans erreur visible sont
    la base du panneau et le collecteur ; chacune laisse sa dernière panne."""
    out = {}
    m = _FP_DB_DERNIERE_ERREUR.get("message")
    if m:
        out["source_erreur"] = "base FastPanel : %s" % m
        out["source"] = "base illisible"
    s = _SOCKET_DERNIERE_ERREUR.get("message")
    if s:
        out["source_erreur"] = ((out["source_erreur"] + " ; ") if out else "") + "collecteur : %s" % s
        out.setdefault("source", "collecteur tombé")
    return out


def _fp_mysql_direct(sql: str, mapper):
    # PERF: initialisation thread-safe avec double vérification sous verrou
    # Optimisation: remplacer hasattr par getattr avec sentinelle pour réduire les appels
    if not getattr(_fp_mysql_direct, "_initialized", False):
        import threading
        if not getattr(_fp_mysql_direct, "_lock", None):
            _fp_mysql_direct._lock = threading.Lock()
        with _fp_mysql_direct._lock:
            if not getattr(_fp_mysql_direct, "_initialized", False):
                import functools, re, subprocess
                from pathlib import Path

                _fp_mysql_direct._line_pat = re.compile(r"^\s*([^#\s]\S*)\s*:\s*['\"]?(.*?)['\"]?\s*$")
                _fp_mysql_direct._printed = set()
                _fp_mysql_direct._initialized = True

                # PERF: écriture unique avec double-check pour réduire les acquisitions de verrou
                def _write_once(msg):
                    # Vérification rapide sans verrou
                    if msg not in _fp_mysql_direct._printed:
                        with _fp_mysql_direct._lock:
                            if msg not in _fp_mysql_direct._printed:
                                _fp_mysql_direct._printed.add(msg)
                                import sys
                                sys.stderr.write(msg)
                                sys.stderr.flush()
                                return True
                    return False
                _fp_mysql_direct._write_once = _write_once

                @functools.lru_cache(maxsize=1)
                def _load_creds():
                    pat = _fp_mysql_direct._line_pat
                    errors = []  # PERF: collecter les messages pour un seul appel à _write_once
                    for cfg in (
                        "/usr/local/fastpanel2/app/config/parameters.yml",
                        "/usr/local/fastpanel2/app/config/parameters.yaml",
                        "/usr/local/fastpanel2/config/database.yml",
                    ):
                        p = Path(cfg)
                        if not p.is_file():
                            continue
                        try:
                            text = p.read_text(errors="replace")
                            creds = {m.group(1): m.group(2).strip()
                                     for line in text.splitlines()
                                     if (m := pat.match(line))}
                            if creds.get("database_password"):
                                return creds
                            errors.append(f"cassandra: database_password manquant ou vide dans {cfg}")
                        except (IOError, OSError) as e:
                            errors.append(f"cassandra: could not read {cfg}: {e}")
                    if _fp_sqlite_path():
                        # Installation SQLite : l'absence d'identifiants MySQL est
                        # NORMALE, ce n'est pas une anomalie à signaler.
                        return {}
                    if not errors:
                        errors.append("cassandra: database_password not found in config")
                    _fp_mysql_direct._write_once("\n".join(errors) + "\n")
                    return {}
                _fp_mysql_direct._load_creds = _load_creds

                @functools.lru_cache(maxsize=1)
                def _get_mysql_path():
                    import shutil
                    path = shutil.which("mysql")
                    if not path:
                        _fp_mysql_direct._write_once("cassandra: mysql binary not found in PATH\n")
                    return path
                _fp_mysql_direct._get_mysql_path = _get_mysql_path

    # PERF: références locales pour accès rapide
    write_once = _fp_mysql_direct._write_once
    creds = _fp_mysql_direct._load_creds()
    if not creds.get("database_password"):
        # Pas de MySQL configuré → on interroge la base SQLite de FastPanel.
        return _fp_sqlite_query(sql, mapper)

    mysql_path = _fp_mysql_direct._get_mysql_path()
    if not mysql_path:
        return []

    host = creds.get("database_host", "127.0.0.1")
    port = creds.get("database_port", "3306")
    user = creds.get("database_user", "fastpanel")
    db = creds.get("database_name", "fastpanel2")
    if not all([host, port, user, db]):
        write_once("cassandra: paramètres de connexion MySQL invalides (host/port/user/db)\n")
        return []

    cmd = [
        mysql_path,
        f"-h{host}", f"-P{port}", f"-u{user}", db,
        "--batch", "--silent", "--skip-column-names",
        "-e", sql,
    ]
    env = {"MYSQL_PWD": creds["database_password"]}

    try:
        result = subprocess.run(
            cmd, capture_output=True, text=True, errors="replace",
            timeout=10, env=env
        )
    except FileNotFoundError:
        write_once("cassandra: mysql binary not found\n")
        return []
    except subprocess.TimeoutExpired:
        write_once("cassandra: mysql query timed out\n")
        return []
    except Exception as e:
        write_once(f"cassandra: unexpected error running mysql: {e}\n")
        return []

    if result.returncode != 0:
        write_once(f"cassandra: mysql exited with code {result.returncode}: {result.stderr}\n")
        return []

    out = result.stdout
    if not out:
        return []

    # PERF: parsing optimisé – utilisation d'une expression génératrice pour filtrer et mapper en une passe
    skip_prefixes = ('W', 'E', 'w')
    # PERF: remplacer la boucle explicite par une compréhension de liste avec gestion d'exception
    def process_line(line):
        line_stripped = line.rstrip()
        if not line_stripped or line_stripped.startswith(skip_prefixes):
            return None
        parts = line_stripped.split('\t')
        try:
            return mapper(parts)
        except Exception as e:
            write_once(f"cassandra: mapper a levé une exception: {e}\n")
            return None

    # PERF: utilisation de filter et map pour éviter l'accumulation répétée de None
    result_list = [m for m in map(process_line, out.splitlines()) if m is not None]
    return result_list


def _write_once(printed_set, msg, stream):
    """PERF: write msg to stderr only once per unique message to reduce repeated writes."""
    if msg not in printed_set:
        printed_set.add(msg)
        stream.write(msg)
        stream.flush()

def _fp_users_filesystem_fallback():
    """Fallback : liste les users FastPanel depuis /var/www/ et /etc/passwd."""
    import subprocess as _sp
    import os as _os
    import pwd as _pwd

    try:
        excluded = {"html", "phpmyadmin", "webmail"}
        users = []
        dirs = []  # (path, username)

        # PERF: Parcours unique avec os.scandir ; validation immédiate du dossier data
        try:
            with _os.scandir("/var/www") as it:
                for entry in it:
                    if entry.is_dir(follow_symlinks=False):
                        uname = entry.name
                        if uname in excluded:
                            continue
                        data_path = _os.path.join(entry.path, "data")
                        if _os.path.isdir(data_path):
                            dirs.append((entry.path, uname))
                            excluded.add(uname)
        except PermissionError:
            dirs.clear()

        # PERF: Exécution de du en une seule commande et association directe par index (pas de map)
        if dirs:
            paths = [p for p, _ in dirs]
            try:
                du_output = _sp.run(
                    ["du", "-sb"] + paths,
                    capture_output=True, text=True, timeout=10
                ).stdout
            except Exception:
                du_output = ""

            if du_output:
                lines = du_output.splitlines()
                # PERF: Itération parallèle sur dirs et lignes de du (même ordre)
                for (parent, uname), line in zip(dirs, lines):
                    parts = line.split(maxsplit=1)
                    if len(parts) == 2:
                        try:
                            size = int(parts[0])
                        except ValueError:
                            size = 0
                    else:
                        size = 0
                    users.append({
                        "username": uname,
                        "email": "",
                        "status": "active",
                        "disk_quota_gb": 0,
                        "disk_used_gb": round(size / 1073741824, 2),
                        "created_at": "",
                        "last_login": "",
                    })
            else:
                # PERF: Fallback si du échoue — utilise des tailles nulles
                for parent, uname in dirs:
                    users.append({
                        "username": uname,
                        "email": "",
                        "status": "active",
                        "disk_quota_gb": 0,
                        "disk_used_gb": 0,
                        "created_at": "",
                        "last_login": "",
                    })

        # PERF: Utilisation de pwd.getpwall() en fallback uniquement si aucun utilisateur trouvé
        if not users:
            try:
                for pw_entry in _pwd.getpwall():
                    if pw_entry.pw_dir.startswith("/var/www/"):
                        uname = pw_entry.pw_name
                        if uname in excluded:
                            continue
                        excluded.add(uname)
                        users.append({
                            "username": uname,
                            "email": "",
                            "status": "active",
                            "disk_quota_gb": 0,
                            "disk_used_gb": 0,
                            "created_at": "",
                            "last_login": "",
                        })
            except Exception:
                pass

        return users

    except Exception:
        return []

def get_fp_users():
    # La base FastPanel donne ce qu'aucune autre source n'a : rôles, accès SSH,
    # quota réel, et le compte de sites et de bases possédés. La page affichait
    # un « Quota total » sans jamais avoir de quota.
    _riche = _fp_users_riches()
    d = get_entity_from_socket("fastpanel_users")
    if _riche:
        return _fp_enrichir(d or [], _riche, "username")
    if d: return d
    # La table locale fastpanel_users (créée par le collector) ne contient NI
    # created_at NI last_login — voir son CREATE TABLE : id, username, email,
    # disk_quota_gb, disk_used_gb, status, last_check. Les demander provoquait un
    # « no such column: created_at » à chaque appel, le cache SQLite était donc
    # toujours ignoré et on retombait systématiquement sur MySQL (lui-même en
    # échec faute de mot de passe). On sélectionne les colonnes réelles et on
    # complète les deux champs attendus par l'appelant.
    r = query_db("SELECT username,email,status,disk_quota_gb,disk_used_gb,last_check "
                 "FROM fastpanel_users ORDER BY username")
    if r:
        for _u in r:
            _u.setdefault("created_at", "")
            _u.setdefault("last_login", _u.get("last_check", "") or "")
        return r
    # Schéma RÉEL de FastPanel 2 (relevé le 2026-08-05) : les utilisateurs du
    # panel sont dans `panel_account`, PAS dans une table `user` — qui n'existe
    # pas. Correspondances : username (et non login), restore_email (et non
    # email), quota_value (et non disk_quota). Il n'y a NI last_login NI
    # disk_used : ces deux champs sont renvoyés vides plutôt qu'inventés.
    mysql_result = _fp_mysql_direct(
        "SELECT username, "
        "COALESCE(restore_email,''), "
        # `status` : valeurs non documentées, on normalise les formes connues et
        # on laisse passer les autres telles quelles au lieu de les travestir.
        "CASE WHEN CAST(status AS TEXT) IN ('1','active','enabled') THEN 'active' "
        "     WHEN status IS NULL THEN '' ELSE CAST(status AS TEXT) END, "
        "COALESCE(created_at,''), "
        "'', "                              # last_login : absent du schéma
        "COALESCE(quota_value,0), "         # supposé en octets (comme l'API FP2)
        "0 "                                # disk_used : absent du schéma
        "FROM panel_account ORDER BY username",
        lambda r: {
            "username": r[0], "email": r[1] or "",
            "status": r[2] or "active",
            "disk_quota_gb": round(float(r[5]) / 1073741824, 2) if len(r) > 5 and r[5] and r[5] != "0" else 0,
            "disk_used_gb":  round(float(r[6]) / 1073741824, 2) if len(r) > 6 and r[6] and r[6] != "0" else 0,
            "created_at": r[3] or "", "last_login": r[4] or "",
        } if r and r[0] else None
    )
    if mysql_result:
        return mysql_result
    return _fp_users_filesystem_fallback()

import functools as _functools
import os as _os
import re as _re
import subprocess as _sp
import datetime as _dt
from pathlib import Path as _Path

_PERF_RE_SERVER_BLOCK = _re.compile(r"(?i)server\s*\{[^}]*\}", _re.DOTALL)
_PERF_RE_DIRECTIVE = _re.compile(r"^\s*(server_name|root|ssl_certificate)\s+([^\s;]+)", _re.MULTILINE)

# CACHE BORNÉ, PAS PERMANENT (2026-09-05). `lru_cache(maxsize=1)` sans
# argument gardait le premier balayage jusqu'au redémarrage : un site ajouté
# dans le panneau n'apparaissait jamais par cette voie, et un balayage tombé
# sur une erreur restait vide pour toujours. Cinq minutes, même mécanique que
# `_FP_DB_CACHE`. On rend des COPIES : les consommateurs enrichissent les
# dictionnaires en place, et l'enrichissement d'un appel s'imprimait dans
# le cache pour les suivants.
_FP_FALLBACK_CACHE = {"t": 0.0, "val": None}
_FP_FALLBACK_TTL = 300.0


def _fp_domains_fallback():
    if _FP_FALLBACK_CACHE["val"] is not None and \
            time.time() - _FP_FALLBACK_CACHE["t"] < _FP_FALLBACK_TTL:
        return [dict(x) for x in _FP_FALLBACK_CACHE["val"]]
    val = _fp_domains_fallback_calcul() or []
    _FP_FALLBACK_CACHE.update({"t": time.time(), "val": val})
    return [dict(x) for x in val]


# Chaque entrée porte sa `source` (« nginx » ou « arborescence ») et ne
# prétend rien qu'elle n'ait lu : plus de `ssl_days_left: 999` ni de
# `status: active` inventés — 999 jours passaient pour un certificat en pleine
# santé dans tous les compteurs, et « active » pour un constat.
def _fp_domains_fallback_calcul():  # noqa: D401
    """Fallback : détecte les domaines via le filesystem FastPanel2 et nginx."""
    import functools as _functools
    import os as _os
    import subprocess as _sp
    import datetime as _dt
    from pathlib import Path as _Path

    # PERF: cache directory existence checks
    @_functools.lru_cache(maxsize=256)
    def _is_dir(p: str) -> bool:
        return _os.path.isdir(p)

    # PERF: cache certificate parsing (returns days left)
    # None quand le certificat n'a pas pu être lu : « 999 » était une
    # invention que rien ne distinguait d'une vraie échéance lointaine.
    @_functools.lru_cache(maxsize=1024)
    def _ssl_days_from_cert(c: str):
        if not _os.path.isfile(c):
            return None
        try:
            out = _sp.run(
                ["openssl", "x509", "-enddate", "-noout", "-in", c],
                capture_output=True,
                text=True,
                timeout=3,
            ).stdout.strip()
            if not out.startswith("notAfter="):
                return None
            exp = _dt.datetime.strptime(out.split("=", 1)[1], "%b %d %H:%M:%S %Y %Z")
            return max(0, (exp - _utcnow()).days)
        except Exception:
            return None

    @_functools.lru_cache(maxsize=None)
    def _get_ssl_info(c: str):
        return (1, _ssl_days_from_cert(c)) if c else (0, None)

    # `status` vide : ce balayage lit des fichiers, il ne sait pas si le site
    # est actif. `ssl_days_left` None : personne n'a regardé le certificat.
    def _make_entry(domain, user, root, php="", ssl=0, days=None, status="", source="nginx"):
        return {
            "domain": domain,
            "user": user,
            "php_version": php,
            "ssl_enabled": ssl,
            "ssl_days_left": days,
            "document_root": root,
            "status": status,
            "source": source,
        }

    # PERF: extract user from docroot with caching
    def _extract_user_from_docroot(docroot, www_root, cache):
        if docroot in cache:
            return cache[docroot]
        if docroot.startswith(f"{www_root}/"):
            rest = docroot[len(www_root) + 1:]
            slash_idx = rest.find("/")
            user = rest[:slash_idx] if slash_idx != -1 else rest
        else:
            user = ""
        cache[docroot] = user
        return user

    # PERF: scan FastPanel2 directories
    def _scan_fastpanel(www_root, seen, result):
        try:
            for client in _os.scandir(www_root):
                if not client.is_dir():
                    continue
                data_www = _os.path.join(client.path, "data", "www")
                if not _is_dir(data_www):
                    continue
                for entry in _os.scandir(data_www):
                    if not entry.is_dir():
                        continue
                    domain = entry.name
                    if domain in seen:
                        continue
                    seen.add(domain)
                    result.append(_make_entry(domain, client.name, entry.path,
                                              source="arborescence"))
        except Exception:
            pass
        return bool(result)

    # PERF: process a single nginx config file
    def _process_nginx_config(conf_path, www_root, seen, result, root_user_cache, _srv_re, _dir_re):
        try:
            txt = conf_path.read_text(errors="replace")
        except Exception:
            return
        if not txt:
            return
        for blk in _srv_re.finditer(txt):
            dirs = dict(_dir_re.findall(blk.group()))
            raw_name = dirs.get("server_name")
            if not raw_name:
                continue
            domain = raw_name[2:] if raw_name.startswith("*.") else raw_name
            if domain in seen or "localhost" in domain.split("."):
                continue
            docroot = dirs.get("root", "")
            user = _extract_user_from_docroot(docroot, www_root, root_user_cache)
            ssl, days = _get_ssl_info(dirs.get("ssl_certificate", ""))
            seen.add(domain)
            result.append(_make_entry(domain, user, docroot, ssl=ssl, days=days))

    _srv_re = _PERF_RE_SERVER_BLOCK
    _dir_re = _PERF_RE_DIRECTIVE
    www_root = "/var/www"
    seen = set()
    result = []

    # ---------- FastPanel2 ----------
    if _is_dir(www_root):
        if _scan_fastpanel(www_root, seen, result):
            return result

    # ---------- Nginx ----------
    conf_dir = "/etc/nginx/conf.d"
    if not (_is_dir(conf_dir) and _is_dir(www_root)):
        return result

    try:
        conf_paths = list(_Path(conf_dir).glob("*.conf"))
    except Exception:
        return result

    # PERF: cache user extraction per docroot
    root_user_cache = {}

    for conf_path in conf_paths:
        _process_nginx_config(conf_path, www_root, seen, result, root_user_cache, _srv_re, _dir_re)

    return result

def get_fp_domains():
    # TOUTES les sorties passent par l'enrichissement SSL. La version précédente
    # ne l'appliquait qu'aux deux derniers chemins : or la donnée arrive presque
    # toujours par le collecteur, qui rendait la main dès la première ligne. Les
    # certificats réels n'étaient donc jamais croisés, et l'onglet continuait
    # d'afficher « non-SSL / Expiré » sur des domaines parfaitement certifiés.
    d = get_entity_from_socket("fastpanel_domains")
    if d: return _fp_domains_with_ssl(d)
    r = query_db("SELECT domain,user,php_version,ssl_enabled,ssl_days_left,document_root,status FROM fastpanel_domains ORDER BY domain")
    if r: return _fp_domains_with_ssl(r)
    # Schéma RÉEL de FastPanel 2 : les sites web sont dans `site` (colonne
    # `domain`), pas dans la table `domain` — celle-ci porte les zones DNS et
    # était vide. Le certificat se joint par site.certificate_id → certificate.id
    # (il n'existe pas de table `ssl_certificate`), et le propriétaire par
    # site.owner_id → panel_account.id.
    mysql_result = _fp_mysql_direct(
        "SELECT s.domain, "
        "COALESCE(p.username,''), "
        "'', "                              # php_version : absent de `site`
        # SSL actif = un certificat est rattaché au site.
        "CASE WHEN s.certificate_id IS NOT NULL "
        "      AND CAST(s.certificate_id AS TEXT) NOT IN ('','0') THEN '1' ELSE '0' END, "
        "'', "                              # document_root : absent de `site`
        "CASE WHEN CAST(s.status AS TEXT) IN ('1','active','enabled') THEN 'active' "
        "     WHEN s.status IS NULL THEN '' ELSE CAST(s.status AS TEXT) END, "
        # Garde-fou : on ne transmet la date que si elle RESSEMBLE à une date ISO.
        # Sinon le mapper lève sur fromisoformat et la ligne entière serait perdue.
        "CASE WHEN c.expired_at LIKE '____-__-__%' THEN c.expired_at "
        "     WHEN c.expires   LIKE '____-__-__%' THEN c.expires "
        "     ELSE '' END "
        "FROM site s "
        "LEFT JOIN panel_account p ON s.owner_id = p.id "
        "LEFT JOIN certificate c ON s.certificate_id = c.id "
        "ORDER BY s.domain",
        lambda r: {
            "domain": r[0], "user": r[1] or "",
            "php_version": r[2] or "",
            "ssl_enabled": 1 if r[3] in ("1","true","active") else 0,
            "ssl_days_left": (lambda exp: max(0, (
                __import__('datetime').datetime.fromisoformat(exp.replace(" ","T"))
                - __import__('datetime').datetime.now()).days) if exp else 0)(r[6] if len(r) > 6 else ""),
            "document_root": r[4] or "", "status": r[5] or "active",
        } if r and r[0] else None
    )
    if mysql_result:
        # `site` est la source d'autorité pour la LISTE des sites, leur
        # propriétaire et leur certificat — mais elle ne contient ni version PHP
        # ni racine documentaire. Le balayage des confs nginx, lui, lit les vraies
        # directives `root`. On complète donc les champs manquants au lieu de
        # renvoyer des valeurs vides là où l'information existait auparavant.
        try:
            _by_dom = {d.get("domain"): d for d in (_fp_domains_fallback() or [])}
        except Exception as _e:
            logging.info("[FASTPANEL] complément nginx indisponible : %s", _e)
            _by_dom = {}
        for _d in mysql_result:
            _src = _by_dom.get(_d.get("domain")) or {}
            if not _d.get("document_root"):
                _d["document_root"] = _src.get("document_root", "") or ""
            if not _d.get("php_version"):
                _d["php_version"] = _src.get("php_version", "") or ""
        return _fp_domains_with_ssl(mysql_result)
    # Le nom appelé était `_fp_domains_filesystem_fallback`, qui n'existe pas :
    # dès que socket, SQLite et MySQL ne renvoyaient rien, la liste des domaines
    # levait NameError au lieu de retomber sur le balayage des confs nginx.
    return _fp_domains_with_ssl(_fp_domains_fallback())


_SSL_PROBE = {}          # domaine -> (horodatage, jours_restants, expiration)
_SSL_PROBE_TTL = 1800.0
_SSL_PROBE_MAX = 12      # par appel : une liste de domaines ne doit pas devenir un scan


def _ssl_probe(dom: str):
    """Jours restants lus sur le certificat réellement servi, en cache 30 min.

    Dernier recours quand la table du collecteur ne connaît pas le domaine :
    elle peut être vide, périmée, ou nommer les sites autrement. Le certificat
    servi sur le port 443, lui, ne ment pas."""
    now = time.time()
    e = _SSL_PROBE.get(dom)
    if e and now - e[0] < _SSL_PROBE_TTL:
        return e[1], e[2]
    jours, exp = None, ""
    try:
        import ssl as _ssl
        ctx = _ssl.create_default_context()
        with socket.create_connection((dom, 443), timeout=3) as brut:
            with ctx.wrap_socket(brut, server_hostname=dom) as tls:
                cert = tls.getpeercert()
        fin = cert.get("notAfter", "")
        if fin:
            d = datetime.strptime(fin, "%b %d %H:%M:%S %Y %Z")
            jours = (d - datetime.utcnow()).days
            exp = d.strftime("%Y-%m-%d")
    except Exception as ex:
        # Un échec est une information : pas de HTTPS, ou nom non résolu.
        logging.debug("[SSL] sonde %s : %s", dom, ex)
        jours = None
    _SSL_PROBE[dom] = (now, jours, exp)
    return jours, exp


def _ssl_probe_en_cache(dom: str) -> bool:
    e = _SSL_PROBE.get(dom)
    return bool(e) and time.time() - e[0] < _SSL_PROBE_TTL


def _fp_php_normaliser(v) -> str:
    """« 83 » → « 8.3 ». FastPanel range la version PHP d'un backend sous la
    forme compacte (website_backends.handler_version = « 83 », relevé le
    sur le serveur de test) ; l'audit compare à « 8.3 »."""
    s = str(v or "").strip()
    if not s or not any(ch.isdigit() for ch in s):
        return ""
    if s.isdigit() and len(s) >= 2:
        return s[0] + "." + s[1:]
    return s


# Gestionnaires qui servent du PHP : pour eux, une version vide est une
# version NON LUE ; pour un reverse_proxy, c'est un site sans PHP.
_FP_HANDLERS_PHP = ("php", "fpm", "itk", "apache")


def _fp_php_par_site() -> dict:
    """Version PHP de chaque site, lue là où FastPanel la range VRAIMENT.

    La table `site` n'a aucune colonne PHP. La version vit dans
    `website_backends` (frontend_id → site.id ; handler = php_fpm, mpm_itk,
    reverse_proxy… ; handler_version = « 83 »). Le collecteur, lui, écrivait
    dans `php_version` le NOM DU GESTIONNAIRE — « fastuser », « php_fpm »,
    « mpm_itk » — et l'audit PHP y cherchait un « 8.3 » : il ne trouvait
    jamais de version, donc jamais de fin de support (2026-09-05).
    Rend {domaine: {"php": "8.3", "handler": "php_fpm"}} ; {} si la table
    est absente de cette version du panneau."""
    cols = _fp_db_colonnes("website_backends")
    if not {"frontend_id", "handler", "handler_version"} <= cols:
        return {}
    ordre = "ORDER BY COALESCE(b.main,0) DESC, b.id" if "main" in cols else "ORDER BY b.id"
    out = {}
    for r in _fp_db_query(
            "SELECT s.domain, COALESCE(b.handler,''), COALESCE(b.handler_version,'') "
            "FROM website_backends b JOIN site s ON b.frontend_id = s.id " + ordre):
        dom = _norm_domain(str(r[0] or ""))
        if not dom or dom in out:          # le backend principal d'abord, un seul par site
            continue
        out[dom] = {"handler": str(r[1] or ""), "php": _fp_php_normaliser(r[2])}
    return out


_NOM_SITE_VALIDE = re.compile(r"^(?=.{4,253}$)(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+(?:[a-z]{2,63}|xn--[a-z0-9-]{2,59})$")


def _nom_de_site_valide(nom) -> bool:
    """Un nom d'hôte, rien d'autre : ni le « _ » de la page par défaut de nginx, ni une ligne de tirets, ni un
    joker. Deux « sites fantômes » recevaient des alertes de sauvegarde (24-09)."""
    return bool(_NOM_SITE_VALIDE.match(str(nom or "").strip().rstrip(".").lower()))


def _fp_domains_with_ssl(domaines):
    """Complète chaque domaine avec l'état RÉEL de son certificat.

    Deux sources coexistaient sans se parler : `site.certificate_id` dans la base
    de FastPanel, qui dit seulement qu'un certificat a été *rattaché* un jour, et
    la table `ssl_certificates` que le collecteur remplit à partir des
    certificats réellement en place, avec leur date d'expiration. La vue
    n'utilisait que la première : elle affichait « non-SSL » et « Expiré » sur
    des domaines parfaitement certifiés, et les compteurs « SSL actif » et
    « SSL < 30j » restaient à zéro. C'est l'observation qui fait foi.

    On en profite pour joindre `site_stats` : erreurs, code HTTP et poids du
    site sont calculés par FastPanel et n'apparaissaient nulle part."""
    if not domaines:
        return domaines
    # Tous les chemins de get_fp_domains passent ici : c'est ici qu'un nom qui n'est pas un site reste dehors.
    domaines = [d for d in domaines if not isinstance(d, dict) or _nom_de_site_valide(d.get("domain"))]
    try:
        _stats = _fp_site_stats()
        if _stats:
            for _d in domaines:
                if not isinstance(_d, dict):
                    continue
                _s = _stats.get(_norm_domain(str(_d.get("domain") or "")))
                if _s:
                    for _k, _v in _s.items():
                        _d.setdefault(_k, _v)
    except Exception as _e:
        logging.info("[FP] statistiques de site : %s", _e)
    # LA VERSION PHP VIENT DU PANNEAU, PAS DU COLLECTEUR (2026-09-05). Voir
    # `_fp_php_par_site` : le `php_version` du collecteur porte un gestionnaire.
    # On le garde sous `php_handler`, la version prend la place qu'elle aurait
    # dû occuper — ou reste vide, avec sa raison dans `php_source`. Jamais un
    # faux : « fastuser » affiché en pastille « PHP fastuser » pendant des mois.
    try:
        _php = _fp_php_par_site()
    except Exception as _e:
        logging.info("[FP] versions PHP du panneau : %s", _e)
        _php = {}
    for _d in domaines:
        if not isinstance(_d, dict):
            continue
        _brut = str(_d.get("php_version") or "").strip()
        _fiche = _php.get(_norm_domain(str(_d.get("domain") or ""))) or {}
        if _brut and not any(ch.isdigit() for ch in _brut):
            _d["php_handler"] = _brut          # « php_fpm », « mpm_itk », « fastuser »
            _brut = ""
        if _fiche.get("php"):
            _d["php_version"] = _fiche["php"]
            _d["php_source"] = "panneau"
            if _fiche.get("handler"):
                _d["php_handler"] = _fiche["handler"]
        else:
            _d["php_version"] = _brut
            if _brut:
                _d["php_source"] = "collecteur"
            elif _fiche:
                _h = str(_fiche.get("handler") or "")
                _d["php_handler"] = _d.get("php_handler") or _h
                _d["php_source"] = ("panneau : version non lue"
                                    if any(k in _h.lower() for k in _FP_HANDLERS_PHP)
                                    else "panneau : sans PHP (%s)" % (_h or "?"))
    try:
        certs = get_ssl_certificates() or []
    except Exception as e:
        logging.info("[FASTPANEL] certificats indisponibles : %s", e)
        return domaines
    par_dom = {}
    for c in certs:
        d = _norm_domain(c.get("domain", ""))
        if d:
            par_dom[d] = c
    sondes = 0
    for d in domaines:
        dom = _norm_domain(d.get("domain", ""))
        if not dom:
            continue
        c = par_dom.get(dom)
        if not c:
            # Un certificat couvrant `exemple.fr` couvre souvent `www.exemple.fr`
            # et l'inverse : sans ce rapprochement, la moitié des sites paraissent
            # nus alors qu'ils sont servis en HTTPS.
            alt = dom[4:] if dom.startswith("www.") else ("www." + dom)
            c = par_dom.get(alt)
        if c:
            try:
                jours = int(c.get("days_left") or 0)
            except Exception:
                jours = 0
            d["ssl_enabled"] = 1 if jours > 0 else d.get("ssl_enabled", 0)
            d["ssl_days_left"] = jours
            d["ssl_expiry"] = c.get("expiry_date", "") or ""
            d["ssl_source"] = "collecteur"
            continue
        # Inconnu du collecteur : on va voir nous-mêmes, dans la limite d'un
        # petit nombre de sondes NEUVES par appel. Le plafond comptait aussi
        # les réponses déjà en cache : douze domaines sondés au premier appel,
        # et les suivants ne l'étaient JAMAIS — chaque appel repassait par les
        # douze mêmes, servis du cache, et s'arrêtait là (2026-09-05).
        if not _ssl_probe_en_cache(dom):
            if sondes >= _SSL_PROBE_MAX:
                # Personne n'a regardé : à ne pas confondre avec « sans
                # certificat ». `fp_ssl_overview` le classe « inconnu ».
                d.setdefault("ssl_source", "non sondé")
                continue
            sondes += 1
        jours, exp = _ssl_probe(dom)
        if jours is None:
            # La sonde a regardé et n'a rien trouvé : pas de TLS servi ici, ou
            # nom non résolu. C'est un CONSTAT, pas une absence de donnée. On
            # ne l'écrit à la place d'une échéance positive venue du panneau
            # que si celle-ci manque : le panneau peut connaître un certificat
            # qu'il ne sert pas encore.
            d["ssl_probe"] = "échec"
            try:
                _connu = int(d.get("ssl_days_left") or 0)
            except Exception:
                _connu = 0
            if _connu <= 0:
                d["ssl_enabled"] = 0
                d["ssl_days_left"] = 0
                d["ssl_expiry"] = d.get("ssl_expiry", "") or ""
                d["ssl_source"] = "sonde"
            else:
                d.setdefault("ssl_source", "panneau")
            continue
        d["ssl_enabled"] = 1 if jours > 0 else 0
        d["ssl_days_left"] = jours
        d["ssl_expiry"] = exp
        d["ssl_source"] = "sonde"
    return domaines

def get_fp_databases():
    """Bases de données, enrichies depuis la base FastPanel elle-même.

    Le collecteur retombait sur `information_schema`, qui ne connaît que le nom
    et la taille : « User DB » et « Propriétaire » restaient vides à l'écran.
    FastPanel, lui, sait tout — y compris `db.site_id`, le rattachement au site
    qu'on croyait devoir deviner par correspondance de noms."""
    base = (get_entity_from_socket("fastpanel_databases")
            or query_db("SELECT name,db_user,size_mb,db_type,owner "
                        "FROM fastpanel_databases ORDER BY name") or [])
    riche = _fp_databases_riches()
    if not riche:
        return base or _fp_mysql_direct(
            "SELECT d.name, '', COALESCE(d.size,0), COALESCE(d.engine,'mysql'), "
            "COALESCE(p.username,'') "
            "FROM db d LEFT JOIN panel_account p ON d.owner_id = p.id "
            "ORDER BY d.name",
            lambda r: {"name": r[0], "db_user": r[1] or "", "size_mb": float(r[2] or 0),
                       "db_type": r[3] or "mysql", "owner": r[4] or ""} if r and r[0] else None
        )
    # On complète sans écraser : la taille mesurée par le collecteur sur
    # `information_schema` est plus fraîche que celle stockée par FastPanel.
    par_nom = {str(x.get("name") or ""): x for x in base if isinstance(x, dict)}
    for r in riche:
        anc = par_nom.get(r["name"])
        if anc and float(anc.get("size_mb") or 0) > 0:
            r["size_mb"] = anc["size_mb"]
        par_nom.pop(r["name"], None)
    # Une base vue par le collecteur mais absente de FastPanel existe quand même :
    # c'est souvent un reste d'installation, et c'est justement ce qu'on veut voir.
    for reste in par_nom.values():
        reste["hors_panel"] = True
        riche.append(reste)
    riche.sort(key=lambda x: str(x.get("name") or "").lower())
    return riche


def _fp_databases_riches() -> list:
    """Bases + utilisateurs + propriétaire + site, depuis la base FastPanel."""
    cols = _fp_db_colonnes("db")
    if not cols or "name" not in cols:
        return []
    site = ("s.domain" if "site_id" in cols else "''")
    jointure_site = ("LEFT JOIN site s ON d.site_id = s.id" if "site_id" in cols else "")
    rows = _fp_db_query(
        "SELECT d.name, COALESCE(d.engine,'mysql'), COALESCE(d.size,0), "
        "       COALESCE(p.username,''), %s, COALESCE(d.charset,''), "
        "       COALESCE(d.created_at,''), COALESCE(d.dump_at,''), "
        "       COALESCE(d.enabled,1), "
        "       (SELECT GROUP_CONCAT(du.login, ', ') FROM datbases_users lu "
        "        JOIN database_user du ON du.id = lu.user_id "
        "        WHERE lu.database_id = d.id), d.id "
        "FROM db d "
        "LEFT JOIN panel_account p ON d.owner_id = p.id %s "
        "ORDER BY d.name" % (site, jointure_site))
    out = []
    for r in rows:
        if not r or not r[0]:
            continue
        out.append({
            "name": r[0], "db_type": r[1] or "mysql",
            # `db.size` est en octets côté FastPanel ; l'affichage attend des Mo.
            "size_mb": round(float(r[2] or 0) / 1048576.0, 2),
            "owner": r[3] or "", "site": r[4] or "", "charset": r[5] or "",
            "created_at": str(r[6] or "")[:19], "dump_at": str(r[7] or "")[:19],
            "enabled": int(r[8] or 0), "db_user": r[9] or "",
            "id": r[10] if len(r) > 10 else None,   # l'identifiant du panneau : supprimer sans le recopier (20-09)
        })
    return out

def _fp_enrichir(base: list, riche: list, cle: str) -> list:
    """Complète `base` avec `riche`, sans écraser ce qui est déjà renseigné.

    Le collecteur mesure parfois mieux que FastPanel (taille réelle d'une boîte,
    espace disque consommé) ; FastPanel sait ce que le collecteur ignore
    (rattachements, rôles, quotas). Aucune des deux sources n'a raison partout."""
    if not riche:
        return base or []
    par_cle = {}
    for x in (base or []):
        if isinstance(x, dict) and x.get(cle):
            par_cle[str(x[cle]).lower()] = x
    for r in riche:
        anc = par_cle.pop(str(r.get(cle, "")).lower(), None)
        if anc:
            for k, v in anc.items():
                if v not in (None, "", 0) and k not in ("last_check",):
                    r.setdefault(k, v)
                    if r.get(k) in (None, "", 0):
                        r[k] = v
    for reste in par_cle.values():
        reste["hors_panel"] = True
        riche.append(reste)
    return riche


def _fp_users_riches() -> list:
    """Comptes du panneau : rôles, accès SSH, quota, limites — invisibles jusqu'ici."""
    if "username" not in _fp_db_colonnes("panel_account"):
        return []
    lim = _fp_db_colonnes("limits")
    rows = _fp_db_query(
        "SELECT p.username, COALESCE(p.home_dir,''), COALESCE(p.status,''), "
        "       COALESCE(p.roles,''), COALESCE(p.ssh_access,0), "
        "       COALESCE(p.quota_value,0), COALESCE(p.restore_email,''), "
        "       COALESCE(p.created_at,''), "
        "       (SELECT COUNT(*) FROM site s WHERE s.owner_id = p.id), "
        "       (SELECT COUNT(*) FROM db d WHERE d.owner_id = p.id) "
        "FROM panel_account p ORDER BY p.username")
    limites = {}
    if "owner_id" in lim:
        for r in _fp_db_query("SELECT owner_id, COALESCE(sites,0), COALESCE(databases,0) "
                              "FROM limits"):
            limites[r[0]] = (r[1], r[2])
    out = []
    for r in rows:
        if not r or not r[0]:
            continue
        # `quota_value` est en octets ; l'affichage attend des Go.
        quota = round(float(r[5] or 0) / 1073741824.0, 2)
        out.append({
            "username": r[0], "home_dir": r[1], "status": r[2] or "active",
            "roles": r[3], "ssh_access": 1 if str(r[4]) in ("1", "True", "true") else 0,
            "disk_quota_gb": quota if quota > 0 else "",
            "email": r[6], "created_at": str(r[7] or "")[:19],
            "sites_count": r[8], "databases_count": r[9],
        })
    return out


def _fp_ftp_riches() -> list:
    """Comptes FTP, avec le site qu'ils servent — le lien manquait."""
    cols = _fp_db_colonnes("ftp_account")
    if "name" not in cols:
        return []
    site = "COALESCE(s.domain,'')" if "virtualhost_id" in cols else "''"
    join = "LEFT JOIN site s ON f.virtualhost_id = s.id" if "virtualhost_id" in cols else ""
    rows = _fp_db_query(
        "SELECT f.name, COALESCE(f.home_dir,''), "
        "       CASE WHEN CAST(f.enabled AS TEXT) IN ('1','true') THEN 'active' "
        "            ELSE 'suspended' END, "
        "       COALESCE(p.username,''), %s, COALESCE(f.created,'') "
        "FROM ftp_account f LEFT JOIN panel_account p ON f.owner_id = p.id %s "
        "ORDER BY f.name" % (site, join))
    return [{"login": r[0], "home_dir": r[1], "status": r[2], "owner": r[3],
             "site": r[4], "created_at": str(r[5] or "")[:19]}
            for r in rows if r and r[0]]


def _fp_site_stats() -> dict:
    """Statistiques par site : erreurs, code HTTP, poids fichiers et bases.

    FastPanel les calcule et Cassandra ne les montrait nulle part."""
    if "site_id" not in _fp_db_colonnes("site_stats"):
        return {}
    out = {}
    for r in _fp_db_query(
            "SELECT s.domain, COALESCE(t.error_count,0), COALESCE(t.status_code,0), "
            "       COALESCE(t.size,0), COALESCE(t.databases_size,0), "
            "       COALESCE(t.update_state_date,'') "
            "FROM site_stats t JOIN site s ON t.site_id = s.id"):
        if r and r[0]:
            out[_norm_domain(r[0])] = {
                "error_count": r[1], "status_code": r[2],
                "files_mb": round(float(r[3] or 0) / 1048576.0, 1),
                "db_mb": round(float(r[4] or 0) / 1048576.0, 1),
                "stats_at": str(r[5] or "")[:19]}
    return out


def _fp_col(table: str, *candidats) -> str:
    """Première colonne existante parmi les candidates, ou '' littéral en SQL.

    Les noms varient d'une version de FastPanel à l'autre. Interroger une
    colonne absente fait échouer toute la requête et vide la page : mieux vaut
    construire la requête à partir de ce qui existe vraiment."""
    cols = _fp_db_colonnes(table)
    for c in candidats:
        if c in cols:
            return c
    return "''"


def _fp_mail_riches() -> list:
    """Boîtes mail : quota, taille, domaine, propriétaire."""
    cols = _fp_db_colonnes("mailboxes")
    if not cols:
        return []
    adr = _fp_col("mailboxes", "address", "email", "login")
    if adr == "''":
        return []
    quota = _fp_col("mailboxes", "quota")
    taille = _fp_col("mailboxes", "size", "used")
    actif = _fp_col("mailboxes", "enabled", "active")
    dom_id = "domain_id" in cols
    rows = _fp_db_query(
        "SELECT m.%s, COALESCE(%s,0), COALESCE(%s,0), COALESCE(%s,1), %s "
        "FROM mailboxes m %s ORDER BY m.%s"
        % (adr,
           ("m." + quota) if quota != "''" else "0",
           ("m." + taille) if taille != "''" else "0",
           ("m." + actif) if actif != "''" else "1",
           "COALESCE(e.name,'')" if dom_id else "''",
           "LEFT JOIN email_domain e ON m.domain_id = e.id" if dom_id else "",
           adr))
    out = []
    for r in rows:
        if not r or not r[0]:
            continue
        adresse = str(r[0])
        out.append({
            "email": adresse,
            "domain": r[4] or (adresse.split("@")[-1] if "@" in adresse else ""),
            # Quota et taille sont en octets côté FastPanel.
            "quota_mb": round(float(r[1] or 0) / 1048576.0, 1),
            "used_mb": round(float(r[2] or 0) / 1048576.0, 1),
            "status": "active" if str(r[3]) in ("1", "True", "true") else "suspended",
        })
    return out


def _fp_dns_riches() -> list:
    """Enregistrements DNS, avec leur zone."""
    cols = _fp_db_colonnes("record")
    if not cols:
        return []
    nom = _fp_col("record", "name", "host")
    typ = _fp_col("record", "type", "rtype")
    val = _fp_col("record", "value", "content", "data")
    ttl = _fp_col("record", "ttl")
    if "''" in (nom, typ, val):
        return []
    zone = "domain_id" in cols
    rows = _fp_db_query(
        "SELECT %s, r.%s, r.%s, r.%s, COALESCE(%s,0) FROM record r %s ORDER BY 1, r.%s"
        % ("COALESCE(d.name,'')" if zone else "''", nom, typ, val,
           ("r." + ttl) if ttl != "''" else "0",
           "LEFT JOIN domain d ON r.domain_id = d.id" if zone else "", typ))
    return [{"zone": r[0], "name": r[1], "type": r[2], "value": r[3], "ttl": r[4]}
            for r in rows if r and (r[1] or r[3])]


def _fp_backups_riches() -> list:
    """Sauvegardes réellement effectuées : taille, durée, destination.

    La page listait un type et un statut. Ce qui manque quand une sauvegarde
    échoue, c'est sa taille, sa durée et l'endroit où elle est partie."""
    cols = _fp_db_colonnes("backup_copy_v2")
    if "start_at" not in cols:
        return []
    rows = _fp_db_query(
        "SELECT COALESCE(pl.name,''), COALESCE(c.action,''), "
        "       COALESCE(c.total_uploaded,0), COALESCE(c.total_source,0), "
        "       COALESCE(c.start_at,''), COALESCE(c.end_at,''), "
        "       COALESCE(c.total_file_count,0), COALESCE(c.partial,0), "
        "       COALESCE(a.name,''), COALESCE(a.type,''), COALESCE(p.username,''), "
        "       COALESCE(c.copied_user,''), COALESCE(c.dbs,'') "
        "FROM backup_copy_v2 c "
        "LEFT JOIN backup_plan_v2 pl ON c.plan_id = pl.id "
        "LEFT JOIN backup_account a ON pl.account_id = a.id "
        "LEFT JOIN panel_account p ON pl.owner_id = p.id "
        "ORDER BY c.start_at DESC LIMIT 60")
    out = []
    for r in rows:
        if not r:
            continue
        duree = ""
        try:
            if r[4] and r[5]:
                d1 = datetime.strptime(str(r[4])[:19], "%Y-%m-%d %H:%M:%S")
                d2 = datetime.strptime(str(r[5])[:19], "%Y-%m-%d %H:%M:%S")
                m = int((d2 - d1).total_seconds() // 60)
                duree = ("%d min" % m) if m < 120 else ("%d h %02d" % (m // 60, m % 60))
        except Exception:
            duree = ""
        # Une copie sans date de fin n'est pas terminée : ni réussie, ni échouée.
        etat = "success" if r[5] else ("running" if r[4] else "error")
        if str(r[1]).lower() in ("error", "failed"):
            etat = "error"
        # LE MOTEUR V2 COPIE PAR COMPTE (20-09) : `copied_user` dit quel compte cette copie couvre —
        # tous ses sites, et les bases listées dans `dbs`. Le propriétaire du plan est autre chose.
        compte = str(r[11] or "") if len(r) > 11 else ""
        bases = []
        try:
            bases = [str(x.get("name") or "") for x in json.loads(r[12] or "[]") if isinstance(x, dict)] if len(r) > 12 else []
        except Exception:
            bases = []
        out.append({
            "type": ("partielle" if str(r[7]) in ("1", "True", "true") else "complète")
                    + ((" · " + r[0]) if r[0] else ""),
            "status": etat,
            "size_mb": round(float(r[2] or 0) / 1048576.0, 1),
            "source_mb": round(float(r[3] or 0) / 1048576.0, 1),
            "created_at": str(r[4] or "")[:19], "duration": duree,
            "files": r[6], "user": compte or r[10], "compte": compte, "proprietaire": r[10],
            "bases": [b for b in bases if b],
            "destination": ("%s (%s)" % (r[8], r[9])) if r[8] else "",
            "error": "" if etat != "error" else (r[1] or "échec"),
        })
    return out


# ══════════════════════════════════════════════════════════════════════════
# ACTIONS FASTPANEL — pilotage réel par les agents
# JAMAIS d'écriture directe dans `fastpanel2.db` : FastPanel reconstruit l'état
# réel (nginx, MySQL, dovecot) à partir de sa base, par ses propres démons. Une
# base créée en SQLite n'existerait pas dans MySQL, un site n'aurait pas de
# vhost. Tout passe par `mogwai`, qui est son interface officielle.
#
# Registre NOMMÉ, jamais de commande libre : un agent ne compose pas une ligne
# de commande, il choisit une opération dans une liste vérifiée.
# ══════════════════════════════════════════════════════════════════════════
_FP_ID_RE = re.compile(r"^[0-9]{1,10}$")
_FP_NOM_RE = re.compile(r"^[A-Za-z0-9._\-]{1,120}$")

_FP_ACTIONS = {
    # ── lecture ──
    "sites":        {"cmd": ["sites", "list"], "json": True, "modifie": False,
                     "desc": "Liste les sites avec leur backend et leur certificat."},
    "certificats":  {"cmd": ["certificates", "list"], "json": True, "modifie": False,
                     "desc": "Certificats connus du panneau."},
    "limites":      {"cmd": ["limits", "state"], "json": True, "modifie": False,
                     "desc": "État des limites par utilisateur (sites, bases, quotas)."},
    # ── modifiant, non destructeur ──
    "sauvegarde":   {"cmd": ["backup_v2", "run", "--plan=%(id)s"], "arg": "id",
                     "arg_re": _FP_ID_RE, "modifie": True,
                     "desc": "Lance le plan de sauvegarde d'identifiant donné."},
    "analyse_site": {"cmd": ["scan:virtualhost", "--config=%(id)s"], "arg": "id",
                     "arg_re": _FP_ID_RE, "modifie": True,
                     "desc": "Lance l'analyse antivirus d'un site."},
    "dump_site":    {"cmd": ["transfer", "dump_website", "--domain=%(domaine)s"], "arg": "domaine",
                     "modifie": True, "desc": "Produit une archive du site — demande : domaine."},
    "panel_backup": {"cmd": ["panel", "backup"], "modifie": True,
                     "desc": "Sauvegarde la base du panneau lui-même."},
    "ssl_reemettre": {"cmd": ["certificates", "reissue", "--id=%(id)s"], "arg": "id",
                      "arg_re": _FP_ID_RE, "modifie": True,
                      "desc": "Réémet un certificat. Compte dans le quota Let's Encrypt.",
                      "quota_ssl": True},
    "sauvegardes_lister": {"cmd": ["backup", "list"], "json": True, "modifie": False,
                           "desc": "Plans de sauvegarde déclarés, avec leur identifiant."},
    "backends":     {"cmd": ["sites", "backend", "list"], "json": True, "modifie": False,
                     "desc": "Services applicatifs (PHP-FPM, node…) derrière les sites."},
    # Régénère les vignettes que FastPanel fabrique lui-même : c'est la voie la
    # plus propre pour les rafraîchir — aucun moteur de rendu à installer,
    # aucune donnée qui sort du serveur.
    "apercus_refaire": {"cmd": ["sites", "make_screenshot"], "modifie": True,
                        "desc": "Demande à FastPanel de refaire les aperçus de tous les sites."},
    "sessions_purger": {"cmd": ["sites", "session_cleaner"], "modifie": True,
                        "desc": "Supprime les fichiers de session PHP périmés."},
    "fcgid_purger": {"cmd": ["sites", "fcgid_cleaner"], "modifie": True,
                     "desc": "Supprime les fichiers temporaires du gestionnaire FCGI."},
    "ftp_lister":   {"cmd": ["ftp_account", "list"], "json": True, "modifie": False,
                     "desc": "Comptes FTP déclarés dans le panneau."},
    "sftp_lister":  {"cmd": ["sftp_account", "list"], "json": True, "modifie": False,
                     "desc": "Comptes SFTP déclarés dans le panneau."},
    "dns_comptes":  {"cmd": ["dns_accounts", "list"], "json": True, "modifie": False,
                     "desc": "Comptes DNS distants configurés."},
    "licence":      {"cmd": ["licence", "ping-server"], "modifie": False,
                     "desc": "Vérifie la licence FastPanel auprès de son serveur."},
    "firewall_sauver": {"cmd": ["firewall", "save"], "modifie": True,
                        "desc": "Enregistre les règles de pare-feu actuelles."},
    # ── création : réversible, mais lourde de conséquences ──
    "site_creer":   {"cmd": ["sites", "create", "--server-name=%(domaine)s",
                             "--owner=%(proprietaire)s"],
                     "arg": "domaine", "arg2": "proprietaire",
                     "arg_re": _FP_NOM_RE, "modifie": True, "lourd": True,
                     "desc": "Crée un site. Écrit un vhost et recharge nginx."},
    # ── destructif : accord obligatoire, et jamais depuis un agent ──
    "ftp_supprimer": {"cmd": ["ftp_account", "remove", "--id=%(id)s"], "arg": "id",
                      "arg_re": _FP_ID_RE, "modifie": True, "lourd": True,
                      "agent_interdit": True,
                      "desc": "Supprime un compte FTP. Irréversible."},
    "sftp_supprimer": {"cmd": ["sftp_account", "remove", "--id=%(id)s"], "arg": "id",
                       "arg_re": _FP_ID_RE, "modifie": True, "lourd": True,
                       "agent_interdit": True,
                       "desc": "Supprime un compte SFTP. Irréversible."},
    "stats_purger": {"cmd": ["statistic", "clean"], "modifie": True, "lourd": True,
                     "agent_interdit": True,
                     "desc": "Efface TOUTES les statistiques du panneau. Irréversible."},
    "site_supprimer": {"cmd": ["sites", "delete", "--id=%(id)s"], "arg": "id",
                       "arg_re": _FP_ID_RE, "modifie": True, "lourd": True,
                       "agent_interdit": True,
                       "desc": "Supprime un site : vhost, fichiers et configuration. "
                               "Irréversible."},
}

# `firewall restore` existe et n'est PAS dans le registre, délibérément :
# restaurer un jeu de règles peut fermer le port SSH et rendre le serveur
# inaccessible, sans aucun moyen de revenir en arrière à distance. C'est le même
# principe qui interdit d'arrêter sshd depuis l'interface — une action qui peut
# supprimer le seul chemin d'accès ne s'automatise pas.
#
# `ftp_account create` et `sftp_account create` sont absents aussi : ils exigent
# `--password=`. Faire transiter un mot de passe par un registre d'actions, c'est
# l'écrire dans une ligne de commande, dans un journal et dans le contexte d'un
# modèle. Ces créations se font dans le panneau.
_FP_ACTIONS_ECARTEES = {
    "firewall restore": "peut fermer le port SSH et rendre le serveur inaccessible",
    "ftp_account create": "exige un mot de passe en clair sur la ligne de commande",
    "sftp_account create": "exige un mot de passe en clair sur la ligne de commande",
    "chpasswd": "change un mot de passe utilisateur — se fait dans le panneau, "
                "jamais par une ligne de commande journalisée",
    "schema": "modifie le schéma de la base du panneau ; une erreur y casse "
              "FastPanel entier",
}


def fp_actions_list() -> dict:
    return {"ok": True, "actions": [
        {"key": k, "modifies": v["modifie"], "heavy": bool(v.get("lourd")),
         "agent_blocked": bool(v.get("agent_interdit")),
         "desc": v["desc"], "needs_arg": v.get("arg", ""),
         "needs_arg2": v.get("arg2", "")}
        for k, v in sorted(_FP_ACTIONS.items())],
        # Ce qui a été volontairement laissé dehors, et pourquoi. Une capacité
        # absente sans explication passe pour un oubli.
        "excluded": [{"cmd": k, "reason": v} for k, v in sorted(_FP_ACTIONS_ECARTEES.items())]}


def fp_action_run(action: str, arg: str = "", arg2: str = "",
                  confirm: bool = False, acteur: str = "") -> dict:
    """Exécute une opération FastPanel nommée, via mogwai."""
    def _refus(motif, **extra):
        # Un refus se journalise AUSSI. Une tentative repoussée — paramètre
        # douteux, quota atteint, action inconnue — est précisément ce qu'on
        # veut pouvoir relire, surtout quand c'est un agent qui l'a tentée.
        try:
            log_admin_action(acteur or "", "fp_action_%s" % str(action)[:24],
                             "REFUS", "%s | arg=%s" % (motif[:120], str(arg)[:60]))
        except Exception as e:
            logging.debug("[AUDIT] %s", e)
        d = {"ok": False, "reason": motif}
        d.update(extra)
        return d

    spec = _FP_ACTIONS.get((action or "").strip())
    if not spec:
        return _refus("action inconnue (%s)" % ", ".join(sorted(_FP_ACTIONS)))
    if spec.get("agent_interdit") and acteur == "agent":
        # Une suppression définitive se décide devant l'interface, pas dans une
        # conversation : l'agent peut la proposer, il ne peut pas la commettre.
        return _refus("« %s » supprime définitivement des données : cette action "
                      "n'est pas ouverte aux agents. À faire depuis l'onglet "
                      "FastPanel." % action)
    params = {}
    for champ, valeur in (("arg", arg), ("arg2", arg2)):
        nom = spec.get(champ)
        if not nom:
            continue
        v = str(valeur or "").strip()
        # Le paramètre part dans une commande : on refuse tout ce qui n'a pas
        # la forme attendue, plutôt que de tenter de l'échapper.
        if not v or not spec.get("arg_re", _FP_NOM_RE).match(v):
            return _refus("paramètre « %s » manquant ou invalide" % nom)
        params[nom] = v
    if spec["modifie"] and not confirm:
        return {"ok": False, "needs_confirm": True,
                "reason": ("« %s » modifie l'hébergement." % action)
                          + (" Cette opération écrit une configuration et recharge "
                             "des services." if spec.get("lourd") else ""),
                "command": "mogwai " + " ".join(spec["cmd"]) % params
                           if params else "mogwai " + " ".join(spec["cmd"])}
    # Une réémission consomme le quota Let's Encrypt : on le vérifie AVANT.
    if spec.get("quota_ssl"):
        q = ssl_quota_state(str(arg2 or arg or ""))
        if q.get("blocked"):
            return _refus("Quota Let's Encrypt atteint (%d/%d) — déblocage le %s."
                          % (q["used"], q["limit"], q.get("free_at") or "?"))
    cmd = [c % params if "%(" in c else c for c in spec["cmd"]]
    t0 = time.time()
    if spec.get("json"):
        data, err = _mogwai_json(cmd)
        ok = data is not None
        sortie = "" if ok else (err or "")
    else:
        ok, sortie = _mogwai_run(cmd, timeout=300)
        data = None
    duree = int((time.time() - t0) * 1000)
    try:
        log_admin_action(acteur or "", "fp_action_%s" % action[:24],
                         "OK" if ok else "FAIL",
                         "arg=%s arg2=%s (%d ms)" % (arg[:60], arg2[:60], duree))
    except Exception as e:
        logging.debug("[AUDIT] %s", e)
    return {"ok": bool(ok), "action": action, "duration_ms": duree,
            "command": "mogwai " + " ".join(cmd),
            "data": data, "output": str(sortie)[:6000]}


# ══════════════════════════════════════════════════════════════════════════
# API DU PANNEAU (port 5501)
# `mogwai` ne sait pas créer de base de données. L'API, si : `/api/databases`
# et `/api/databases/users` existent. Le service écoute en HTTP simple sur
# 127.0.0.1:5501 — nginx (8888) lui sert de façade publique.
#
# Authentification : JWT. Le binaire expose `jwtFromHeader`, donc un en-tête
# `Authorization: Bearer <jeton>`. Le jeton se crée dans le panneau
# (/api/user/tokens) : révocable, limité, et il ne met jamais le mot de passe
# du compte en jeu.
#
# LE JETON NE SORT JAMAIS : ni dans un journal, ni dans un message d'erreur,
# ni vers le navigateur, ni dans le contexte d'un modèle.
# ══════════════════════════════════════════════════════════════════════════
_FP_API_DEFAUT = "http://127.0.0.1:5501"


def _fp_api_base() -> str:
    """Adresse retenue — la même que celle réellement interrogée."""
    return _fp_api_bases()[0]


# Cette version du panneau n'expose aucun écran de création de jeton : la table
# `api_tokens` existe côté serveur, mais l'interface ne la sert pas. On se
# connecte donc comme un humain — identifiants, puis JWT — sur décision
# explicite de l'utilisateur, faute d'alternative révocable.
#
# Le JWT obtenu vit UNIQUEMENT EN MÉMOIRE : jamais sur disque, jamais dans un
# journal. Le mot de passe est rangé dans /etc/cassandra/config.json, comme les
# autres secrets de l'application, et n'en sort pas.
_FP_JWT = {"token": "", "t": 0.0}
_FP_JWT_TTL = 1800
# Avec ET sans le préfixe `/api` : nginx (8888) le retire probablement avant de
# transmettre à 5501, auquel cas le service attend `/login` et non `/api/login`.
# Quatre 404 sur les seules formes préfixées, c'est exactement cette signature.
_FP_LOGIN_CHEMINS = ("/api/authorization", "/api/login", "/api/v1/login", "/api/auth",
                     "/authorization", "/login", "/v1/login", "/auth")
_FP_LOGIN_TRACE = []       # ce que chaque tentative a réellement renvoyé
# Réponses d'erreur brutes du panneau, dans l'ordre. `detail` finit souvent
# réécrit par nos propres explications, ce qui efface la seule chose qui
# tranche vraiment : le texte du serveur. Ici, rien n'est réécrit.
_FP_API_TRACE = []
# Le coffre EN PREMIER : c'est sa raison d'être. `config.json` ne sert que de
# repli quand le coffre est verrouillé — un secret ne doit pas rendre
# l'application inutilisable si le coffre dort.
_FP_VAULT_USER = "fastpanel/api_user"
_FP_VAULT_MDP = "fastpanel/api_password"
_FP_VAULT_TOKEN = "fastpanel/api_token"


def _fp_identifiants() -> tuple:
    """(identifiant, mot de passe) — coffre d'abord, configuration ensuite."""
    user = mdp = ""
    try:
        if vault_available():
            user = (vault_get(_FP_VAULT_USER) or "").strip()
            mdp = vault_get(_FP_VAULT_MDP) or ""
    except Exception as e:
        logging.debug("[FP-API] coffre : %s", e)
    if user and mdp:
        return user, mdp
    try:
        cfg = get_cassandra_config()
        return (user or str(cfg.get("fp_api_user") or "").strip(),
                mdp or str(cfg.get("fp_api_password") or ""))
    except Exception:
        return user, mdp


def _fp_api_login() -> str:
    """Obtient un JWT par identifiants. Chaîne vide si impossible."""
    if _FP_JWT["token"] and time.time() - _FP_JWT["t"] < _FP_JWT_TTL:
        return _FP_JWT["token"]
    user, mdp = _fp_identifiants()
    if not user or not mdp:
        return ""
    _FP_LOGIN_TRACE.clear()
    for base in _fp_api_bases():
        j = _fp_login_sur(base, user, mdp)
        if j:
            _FP_JWT.update({"token": j, "t": time.time(), "base": base})
            logging.info("[FP-API] session ouverte sur %s", base)
            return j
    logging.info("[FP-API] échecs de connexion : %s", " | ".join(_FP_LOGIN_TRACE))
    return ""


def _fp_api_bases() -> list:
    """Adresses à essayer.

    Si l'URL est renseignée dans les Réglages, c'est LA SEULE utilisée. Une
    adresse choisie explicitement doit être respectée : deviner à côté fait
    parler Cassandra à un autre service que celui voulu, sans le dire. C'est
    exactement ce qui s'est produit avec le 5501 — il accepte une session, donc
    la découverte s'y arrêtait, alors que le panneau répond sur 8888.

    Sans réglage, on essaie le panneau (8888) avant le service interne."""
    choisie = str(_mem_cfg("fp_api_url", "") or "").strip().rstrip("/")
    if choisie:
        return [choisie]
    vues, out = set(), []
    for b in ("https://127.0.0.1:8888", "http://127.0.0.1:8888", _FP_API_DEFAUT):
        if b not in vues:
            vues.add(b)
            out.append(b)
    return out


def _fp_ouvrir(url, donnees, entetes, timeout=10, methode="POST"):
    """Requête HTTP tolérant un certificat auto-signé EN LOCAL uniquement.

    Le panneau se sert un certificat pour son propre nom : vu depuis 127.0.0.1
    il est toujours « invalide ». Ne pas vérifier est acceptable ici — et
    seulement ici — parce que la connexion ne quitte jamais la machine. Sur une
    adresse distante, la vérification reste entière."""
    req = urllib.request.Request(url, data=donnees, headers=entetes, method=methode)
    hote = (urllib.parse.urlparse(url).hostname or "")
    if url.startswith("https://") and hote in ("127.0.0.1", "localhost", "::1"):
        import ssl
        ctx = ssl.create_default_context()
        ctx.check_hostname = False
        ctx.verify_mode = ssl.CERT_NONE
        return urllib.request.urlopen(req, timeout=timeout, context=ctx)
    return urllib.request.urlopen(req, timeout=timeout)


def _fp_login_sur(base: str, user: str, mdp: str) -> str:
    for chemin in _FP_LOGIN_CHEMINS:
        # Deux nommages coexistent selon les versions ; on essaie les deux
        # plutôt que de parier sur l'un d'eux.
        for nom_champ, corps in (("username", {"username": user, "password": mdp}),
                                 ("login", {"login": user, "password": mdp})):
            try:
                with _fp_ouvrir(base + chemin, json.dumps(corps).encode(),
                                {"Content-Type": "application/json",
                                 "Accept": "application/json"}) as r:
                    d = json.loads(r.read(200000).decode("utf-8", "replace") or "{}")
            except urllib.error.HTTPError as e:
                # On garde CE QUI S'EST PASSÉ : sans ça, un échec global ne dit
                # pas si le chemin est inconnu (404) ou les identifiants refusés
                # (401) — deux problèmes très différents.
                _FP_LOGIN_TRACE.append("%s%s [%s] → %s" % (base, chemin, nom_champ, e.code))
                continue
            except Exception as e:
                _FP_LOGIN_TRACE.append("%s%s [%s] → %s" % (base, chemin, nom_champ,
                                                           type(e).__name__))
                continue
            jeton = ""
            piles = [d]
            while piles and not jeton:
                cur = piles.pop()
                if isinstance(cur, dict):
                    for k in ("token", "access_token", "jwt", "accessToken"):
                        v = cur.get(k)
                        if isinstance(v, str) and len(v) > 20:
                            jeton = v
                            break
                    piles.extend(v for v in cur.values() if isinstance(v, (dict, list)))
                elif isinstance(cur, list):
                    piles.extend(v for v in cur if isinstance(v, (dict, list)))
            if jeton:
                return jeton
            # Réponse acceptée mais sans jeton reconnaissable : c'est un cas à
            # part, et le taire ferait croire à un simple échec réseau.
            _FP_LOGIN_TRACE.append("%s%s [%s] → 200 sans jeton (clés : %s)"
                                   % (base, chemin, nom_champ,
                                      ", ".join(list(d)[:6]) if isinstance(d, dict) else "?"))
    return ""


def _fp_api_jeton() -> str:
    """Jeton d'API si l'utilisateur en a un, sinon JWT obtenu par identifiants."""
    try:
        if vault_available():
            t = (vault_get(_FP_VAULT_TOKEN) or "").strip()
            if t:
                return t
    except Exception as e:
        logging.debug("[FP-API] coffre : %s", e)
    try:
        cfg = get_cassandra_config()
        t = str(cfg.get("fp_api_token") or cfg.get("fastpanel_api_token") or "").strip()
        if t:
            return t
    except Exception:
        pass
    return _fp_api_login()


_FP_JETONS = {}            # base → {"token", "t"} : une session par adresse


def _fp_jeton_pour(base: str) -> str:
    """Jeton valable SUR CETTE ADRESSE.

    Un JWT obtenu sur 5501 n'est pas forcément accepté par la façade 8888, et
    surtout les deux ne servent pas forcément la même version de l'API. Pour
    comparer honnêtement deux adresses, il faut une session propre à chacune."""
    e = _FP_JETONS.get(base)
    if e and time.time() - e["t"] < _FP_JWT_TTL:
        return e["token"]
    user, mdp = _fp_identifiants()
    if not user or not mdp:
        return ""
    j = _fp_login_sur(base, user, mdp)
    if j:
        _FP_JETONS[base] = {"token": j, "t": time.time()}
    return j


def _fp_diag_reponse(brut: str) -> str:
    """Explique une réponse qui n'est pas du JSON, ou "" si elle en est.

    Derrière un proxy, un refus ne ressemble plus à un refus d'API : c'est une
    page HTML de Cloudflare ou de nginx. Sans cette lecture, le message affiché
    serait « erreur 403 » — vrai, mais désignant le mauvais coupable."""
    t = (brut or "").lstrip()[:400].lower()
    if not t:
        return ""
    if t.startswith("{") or t.startswith("["):
        return ""
    if "cloudflare" in t or "cf-ray" in t or "just a moment" in t:
        return ("Cloudflare a répondu à la place du panneau : il filtre les "
                "requêtes non-navigateur. Utiliser l'adresse locale, ou écarter "
                "/api de ses protections.")
    if t.startswith("<!doctype") or t.startswith("<html") or "<title" in t:
        return ("le proxy a renvoyé une page HTML, pas la réponse de l'API — "
                "l'URL des Réglages ne mène probablement pas au panneau.")
    return "réponse illisible (ni JSON ni HTML)"


def _fp_corps_forme(corps: dict) -> bytes:
    """Encode un corps en formulaire, comme le ferait un navigateur.

    Go n'accepte que « true »/« false » en minuscules pour un booléen ; le
    `str()` de Python produirait « True » et le champ retomberait à faux."""
    plat = {}
    for k, v in (corps or {}).items():
        if isinstance(v, bool):
            plat[k] = "true" if v else "false"
        elif v is None:
            plat[k] = ""
        else:
            plat[k] = v
    return urllib.parse.urlencode(plat).encode()


def fp_api_call(methode: str, chemin: str, corps=None, timeout: int = 20,
                entetes_sup: dict = None, encodage: str = "json",
                base: str = "") -> dict:
    """Appel de l'API du panneau. Rend {ok, status, data, reason}.

    Deux formes de chemin sont essayées : avec et sans le préfixe `/api`. Selon
    que l'on parle au service (5501) ou à sa façade nginx (8888), le préfixe est
    présent ou retiré — et un 404 sur l'une ne dit rien de l'autre.

    Aucun message d'erreur ne contient l'en-tête d'autorisation : une trace
    d'erreur finit dans un journal, et un journal se lit."""
    if base:
        # Adresse imposée : il lui faut sa propre session, celle d'une autre
        # adresse n'y vaut rien.
        jeton = _fp_jeton_pour(base)
        if not jeton:
            return {"ok": False, "status": 0,
                    "reason": "aucune session ouvrable sur %s" % base}
    else:
        jeton = _fp_api_jeton()
        if not jeton:
            # Dire QUELLE adresse a été essayée : « pas de jeton » laissait
            # croire à des identifiants manquants alors que l'URL pouvait
            # simplement pointer au mauvais endroit.
            return {"ok": False, "status": 0,
                    "reason": "aucune session sur %s — vérifier l'URL et les "
                              "identifiants dans Réglages → Panneau d'hébergement"
                              % _fp_api_base(),
                    "detail": " | ".join(_FP_LOGIN_TRACE[-4:])}
        # On repart de la base qui a ouvert la session : inutile de redécouvrir,
        # et surtout on évite de parler à un autre service que l'authentifié.
        base = _FP_JWT.get("base") or _fp_api_base()
    chemin = "/" + chemin.lstrip("/")
    formes = [chemin, chemin[4:] if chemin.startswith("/api/") else "/api" + chemin]
    entetes = {"Authorization": "Bearer " + jeton, "Accept": "application/json"}
    for k, v in (entetes_sup or {}).items():
        if str(k).lower() != "authorization":   # jamais écrasable de l'extérieur
            entetes[str(k)] = str(v)
    donnees = None
    if corps is not None:
        if encodage == "form":
            donnees = _fp_corps_forme(corps)
            entetes["Content-Type"] = "application/x-www-form-urlencoded"
        else:
            donnees = json.dumps(corps).encode()
            entetes["Content-Type"] = "application/json"
    dernier = {"code": 0, "corps": ""}
    for k, forme in enumerate(formes):
        try:
            with _fp_ouvrir(base + forme, donnees, entetes, timeout,
                            methode.upper()) as r:
                brut = r.read(2000000).decode("utf-8", "replace")
                code = r.getcode()
        except urllib.error.HTTPError as e:
            try:
                dernier = {"code": e.code, "corps": e.read(20000).decode("utf-8", "replace")}
            except Exception:
                dernier = {"code": e.code, "corps": ""}
            if e.code == 404 and k + 1 < len(formes):
                continue                 # l'autre forme a peut-être raison
            motif = {401: "jeton refusé ou expiré",
                     403: "jeton sans les droits requis",
                     404: "point d'entrée inconnu de cette version"}.get(
                         e.code, "erreur %s" % e.code)
            # 800 et non 300 : un refus de validation cite parfois plusieurs
            # champs, et un JSON coupé ne se relit pas — on perdait justement
            # les champs suivants, ceux qui expliquaient le refus.
            brut = dernier["corps"][:800]
            diag = _fp_diag_reponse(brut)
            if diag:
                motif = "%s — %s" % (motif, diag)
            _FP_API_TRACE.append("%s %s [%s] %s → %s" % (
                methode.upper(), forme, encodage, e.code,
                diag or brut or "(corps vide)"))
            del _FP_API_TRACE[:-20]
            return {"ok": False, "status": e.code, "reason": motif,
                    "detail": brut, "brut": brut, "url": base + forme}
        except Exception as e:
            # `e` peut citer l'URL mais jamais les en-têtes : sûr à journaliser.
            return {"ok": False, "status": 0, "reason": str(e)[:200]}
        try:
            data = json.loads(brut) if brut.strip() else {}
        except Exception:
            data = {"raw": brut[:2000]}
        return {"ok": 200 <= code < 300, "status": code, "data": data,
                "url": base + forme}
    return {"ok": False, "status": dernier["code"] or 404,
            "reason": "point d'entrée inconnu sous les deux formes de chemin",
            "detail": dernier["corps"][:300]}


def fp_api_test() -> dict:
    """Vérifie que l'accès fonctionne, sans jamais afficher le secret."""
    _FP_JWT.update({"token": "", "t": 0.0})     # un test force une vraie connexion
    if not _fp_api_jeton():
        # On interroge la MÊME source que la connexion — coffre inclus. Ne
        # regarder que `config.json` faisait annoncer « aucun identifiant »
        # alors qu'ils étaient dans le coffre et qu'ils avaient été essayés :
        # le message accusait une absence au lieu de rapporter un échec.
        user, mdp = _fp_identifiants()
        if not (user and mdp):
            return {"ok": False, "reason": "ni jeton ni identifiants enregistrés",
                    "vault": vault_available()}
        # On ne montre que ce qui apprend quelque chose : une liste de 32 lignes
        # toutes en 404 noie le seul code qui compte.
        parlantes = [t for t in _FP_LOGIN_TRACE if "→ 404" not in t]
        return {"ok": False,
                "reason": ("identifiants présents, mais refusés par tous les points "
                           "d'entrée essayés"
                           if not parlantes else
                           "identifiants présents ; un point d'entrée a répondu autre "
                           "chose qu'un 404 — c'est celui-là qu'il faut suivre"),
                "attempts": parlantes or list(_FP_LOGIN_TRACE)[:8],
                "tested": len(_FP_LOGIN_TRACE),
                "base": _fp_api_base()}
    for chemin in ("/api/account", "/api/databases", "/api/users"):
        r = fp_api_call("GET", chemin, timeout=8)
        if r.get("ok"):
            d = r.get("data")
            n = len(d) if isinstance(d, list) else len((d or {}).get("data") or [])
            # On annonce l'URL qui a RÉPONDU, pas celle demandée : les deux
            # diffèrent quand le préfixe /api est retiré, et c'est justement
            # l'information qu'on cherchait depuis plusieurs essais.
            return {"ok": True, "endpoint": r.get("url") or chemin, "status": r["status"],
                    "detail": "connexion établie sur %s (%s élément(s))"
                              % (r.get("url") or chemin, n)}
        if r.get("status") in (401, 403):
            # Inutile d'essayer les autres : c'est le jeton qui est en cause.
            return {"ok": False, "reason": r["reason"], "status": r["status"]}
    return {"ok": False, "reason": "l'API répond mais aucun point d'entrée connu "
                                   "n'a abouti — version différente ?"}


def fp_db_serveurs() -> list:
    """Les serveurs MySQL déclarés dans le panneau (`/api/databases/servers`)."""
    r = fp_api_call("GET", "/api/databases/servers")
    d = r.get("data") if r.get("ok") else None
    if isinstance(d, dict):
        d = d.get("data")
    return [x for x in (d or []) if isinstance(x, dict)]


def fp_db_utilisateurs(serveur_id="") -> list:
    """Les utilisateurs MySQL connus du panneau, PAR SERVEUR (`/api/databases/servers/{id}/users`) :
    le panneau ne les liste pas ailleurs (20-09 : `/api/databases/users` répond sa page HTML)."""
    sid = str(serveur_id or "").strip()
    if not sid.isdigit():
        srv = fp_db_serveurs()
        sid = str((srv[0] if srv else {}).get("id") or "")
    if not sid.isdigit():
        return []
    r = fp_api_call("GET", "/api/databases/servers/%s/users" % sid)
    d = r.get("data") if r.get("ok") else None
    if isinstance(d, dict):
        d = d.get("data")
    return [{"id": x.get("id"), "login": x.get("login") or "",
             "owner": ((x.get("owner") or {}).get("username") or "")}
            for x in (d or []) if isinstance(x, dict)]


def _fp_comptes_panneau() -> list:
    """Les comptes du panneau, pour choisir le propriétaire d'une base."""
    try:
        return [{"id": r[0], "username": r[1]} for r in _fp_db_query("SELECT id, username FROM panel_account ORDER BY id") if r]
    except Exception:
        return []


def fp_db_creer(nom: str, serveur_id: str = "", confirm: bool = False,
                acteur: str = "", utilisateur_id: str = "", nouvel_utilisateur: str = "",
                proprietaire_id: str = "") -> dict:
    """Crée une base via l'API — ce que `mogwai` ne sait pas faire.

    Le corps est celui du formulaire du panneau (20-09) : serveur, jeu de caractères, compte
    propriétaire et un UTILISATEUR MySQL — existant (`user_id`) ou nouveau (`user {login, password}`,
    créé avec la base). Le mot de passe d'un nouvel utilisateur est généré ici, rendu une seule fois
    à l'écran, jamais journalisé."""
    n = (nom or "").strip()
    if not re.match(r"^[A-Za-z0-9_]{1,64}$", n):
        return {"ok": False, "reason": "nom de base invalide (lettres, chiffres, "
                                       "souligné ; 64 caractères au plus)"}
    uid = str(utilisateur_id or "").strip()
    nu = (nouvel_utilisateur or "").strip()
    if not uid.isdigit() and not nu:
        nu = n[:32]     # par défaut, un utilisateur du nom de la base
    if nu and not re.match(r"^[A-Za-z0-9_]{1,32}$", nu):
        return {"ok": False, "reason": "identifiant d'utilisateur invalide (lettres, chiffres, souligné ; 32 au plus)"}
    srv = fp_db_serveurs()
    sid = str(serveur_id or "").strip()
    if not sid.isdigit():
        sid = str((next((x for x in srv if x.get("use_as_default")), srv[0] if srv else {})).get("id") or "")
    if not sid.isdigit():
        return {"ok": False, "reason": "aucun serveur MySQL déclaré dans le panneau"}
    serveur = next((x for x in srv if str(x.get("id")) == sid), {})
    comptes = _fp_comptes_panneau()
    pid = str(proprietaire_id or "").strip()
    if not pid.isdigit():
        pid = str((comptes[0] if comptes else {}).get("id") or 1)
    proprio = next((c["username"] for c in comptes if str(c["id"]) == pid), pid)
    users = fp_db_utilisateurs(sid)
    if uid.isdigit():
        u = next((x for x in users if str(x.get("id")) == uid), None)
        if not u:
            return {"ok": False, "reason": "utilisateur MySQL inconnu du panneau"}
        login, qui = u["login"], "l'utilisateur existant « %s »" % u["login"]
    else:
        if any(x.get("login") == nu for x in users):
            return {"ok": False, "reason": "l'utilisateur « %s » existe déjà : choisissez-le dans la liste" % nu}
        login, qui = nu, "un nouvel utilisateur « %s » (mot de passe généré, montré une seule fois)" % nu
    if not confirm:
        return {"ok": False, "needs_confirm": True,
                "reason": "Crée la base « %s » (utf8mb4) sur %s, pour le compte %s, avec %s."
                          % (n, serveur.get("name") or "le serveur MySQL", proprio, qui)}
    corps = {"name": n, "server_id": int(sid), "charset": "utf8mb4", "owner_id": int(pid)}
    mdp = ""
    if uid.isdigit():
        corps["user_id"] = int(uid)
    else:
        import secrets as _secrets
        mdp = _secrets.token_urlsafe(18)
        corps["user"] = {"login": nu, "password": mdp, "allow_remote_connection": False}
    r = fp_api_call("POST", "/api/databases", corps)
    try:
        log_admin_action(acteur or "", "fp_db_create", "OK" if r.get("ok") else "FAIL",
                         "base=%s utilisateur=%s status=%s" % (n, login, r.get("status")))
    except Exception as e:
        logging.debug("[AUDIT] %s", e)
    if not r.get("ok"):
        return {"ok": False, "reason": r.get("reason") or "création refusée",
                "detail": str(r.get("detail") or r.get("brut") or "")[:400], "status": r.get("status")}
    d = r.get("data")
    d = d.get("data") if isinstance(d, dict) and isinstance(d.get("data"), dict) else d
    out = {"ok": True, "id": d.get("id") if isinstance(d, dict) else None,
           "output": "Base « %s » créée pour %s, avec l'utilisateur « %s »." % (n, proprio, login)}
    if mdp:
        out["utilisateur"], out["mot_de_passe"] = nu, mdp
    return out


def fp_db_supprimer(base_id: str, confirm: bool = False, acteur: str = "") -> dict:
    """Supprime une base. Destructif et sans retour : jamais depuis un agent."""
    if not str(base_id).isdigit():
        return {"ok": False, "reason": "identifiant de base invalide"}
    if acteur == "agent":
        return {"ok": False, "reason": "la suppression d'une base n'est pas ouverte "
                                       "aux agents — à faire depuis l'onglet FastPanel"}
    if not confirm:
        return {"ok": False, "needs_confirm": True,
                "reason": "SUPPRIME définitivement la base %s et toutes ses données. "
                          "Aucun retour possible sans sauvegarde." % base_id}
    r = fp_api_call("DELETE", "/api/databases/%s" % int(base_id))
    try:
        log_admin_action(acteur or "", "fp_db_delete", "OK" if r.get("ok") else "FAIL",
                         "id=%s status=%s" % (base_id, r.get("status")))
    except Exception as e:
        logging.debug("[AUDIT] %s", e)
    return r


def _fp_query_impl(args: dict) -> tuple:
    """Ce que Cassandra et Itare savent lire de l'hébergement."""
    sujet = str(args.get("sujet", "") or "").strip().lower()
    vues = {
        "sites": lambda: get_fp_domains(),
        "bases": lambda: get_fp_databases(),
        "utilisateurs": lambda: get_fp_users(),
        "mail": lambda: get_fp_mail(),
        "ftp": lambda: get_fp_ftp(),
        "dns": lambda: get_fp_dns(),
        "sauvegardes": lambda: get_fp_backups(),
        "analyses": lambda: get_fp_scans(),
        "services": lambda: get_fp_services(),
        # Ajoutés le 2026-09-05 : quatre lectures que l'onglet avait et que
        # l'agent n'avait pas — il répondait « sujet inconnu » sur les
        # versions PHP, les tâches du panneau, l'état SSL et le résumé.
        "php": lambda: get_fp_php(),
        "crons": lambda: get_fp_crons(),
        "ssl": lambda: fp_ssl_overview(),
        "resume": lambda: get_fp_summary(),
    }
    if sujet not in vues:
        return ({"ok": False}, "Sujet inconnu. Disponibles : %s."
                % ", ".join(sorted(vues)), "#e0564a")
    try:
        rows = vues[sujet]()
    except Exception as e:
        return ({"ok": False}, "Lecture impossible : %s" % e, "#e0564a")
    if isinstance(rows, dict):
        # Une vue d'ensemble (ssl, resume) : un dictionnaire, pas des lignes.
        if rows.get("ok") is False:
            return ({"ok": False, "reason": rows.get("reason", "")},
                    "Lecture impossible : %s" % (rows.get("reason") or "?"), "#e0564a")
        texte = "\n".join("%s=%s" % (k, v) for k, v in rows.items() if k != "ok")
        if rows.get("source_erreur"):
            return ({"ok": False, "reason": rows["source_erreur"], "data": rows},
                    "%s : une source n'a pas répondu (%s)\n%s"
                    % (sujet, rows["source_erreur"], texte), "#e0564a")
        return ({"ok": True, "data": rows}, "%s :\n%s" % (sujet, texte), "#7c5cfc")
    rows = rows or []
    filtre = str(args.get("filtre", "") or "").strip().lower()
    if filtre:
        rows = [r for r in rows if isinstance(r, dict)
                and filtre in " ".join(str(v) for v in r.values()).lower()]
    if not rows:
        # ZÉRO PAR ABSENCE ≠ ZÉRO PAR CONFORMITÉ (2026-09-05). Base illisible
        # ou collecteur tombé : « Aucun élément » était un mensonge, et
        # l'agent concluait « pas de sauvegarde » là où il n'avait rien lu.
        err = _fp_erreur_source() if not filtre else {}
        if err:
            return ({"ok": False, "reason": err["source_erreur"], "rows": []},
                    "Lecture impossible pour « %s » : %s" % (sujet, err["source_erreur"]),
                    "#e0564a")
        return ({"ok": True, "rows": []}, "Aucun élément pour « %s »." % sujet, "#e8c660")
    lignes = []
    for r in rows[:40]:
        if not isinstance(r, dict):
            continue
        lignes.append(" · ".join("%s=%s" % (k, v) for k, v in r.items()
                                 if v not in (None, "", 0) and k != "last_check"))
    return ({"ok": True, "rows": rows},
            "%s (%d) :\n%s" % (sujet, len(rows), "\n".join(lignes)), "#7c5cfc")


def _fp_act_impl(args: dict) -> tuple:
    r = fp_action_run(str(args.get("action", "")), str(args.get("arg", "")),
                      str(args.get("arg2", "")), bool(args.get("confirm")),
                      "agent")
    if r.get("needs_confirm"):
        return (r, "Accord requis : %s\nCommande : %s\nRelance avec confirm=true "
                   "si l'utilisateur approuve." % (r["reason"], r.get("command", "")),
                "#e8c660")
    if not r.get("ok"):
        return (r, "Échec : %s" % (r.get("reason") or r.get("output") or "?"), "#e0564a")
    return (r, "Fait : %s (%d ms)\n%s" % (r["action"], r["duration_ms"],
                                          (r.get("output") or "")[:1500]), "#27c168")


# Valeurs de repli pour les champs que l'API réclame sans qu'on puisse les
# déduire de la configuration existante. Volontairement court : on ne complète
# que ce dont on connaît le sens.
_FP_SCAN_DEFAUTS = {"locale": "en", "email": "", "notify": False}

# Le formulaire de démarrage du panneau ne porte que deux champs, et son code
# en donne les types : `mode` est un Number, `locale` une String limitée à deux
# valeurs (`options:[{value:"ru"},{value:"en"}]`). Rien à inventer ici.
_FP_FORMES = {"locale": ["en", "ru"], "mode": [1, 2, 0, 3]}

# Les trois modes annoncés par les traductions : EXPRESS, NORMAL, PARANOID.
# On vise le normal — celui que le panneau choisit lui-même (`form.mode =
# de.Normal`) — sans connaître encore sa valeur numérique exacte.
_FP_SCAN_MODES = [1, 2, 0, 3]


def _fp_locale() -> str:
    """Langue à annoncer à l'API du panneau (elle en fait un champ obligatoire).

    Le panneau la tire de sa propre session ; nous n'en avons pas, donc on la
    prend de la configuration si elle y est, sinon anglais — c'est la seule
    locale dont on soit certain qu'elle existe dans toutes les installations."""
    return str(_mem_cfg("fp_api_locale", "") or "").strip() or "en"


def _fp_essayer_formes(methode: str, chemin: str, corps: dict, champs: list,
                       entetes_sup: dict = None, encodage: str = "json"):
    """Rejoue l'appel en variant la forme des champs refusés. None si aucun ne passe.

    Un seul champ à la fois : si deux résistent, les combiner ferait exploser
    le nombre de requêtes pour un gain douteux."""
    for champ in champs:
        for valeur in _FP_FORMES.get(champ, []):
            if valeur == corps.get(champ):
                continue
            essai = dict(corps)
            essai[champ] = valeur
            r = fp_api_call(methode, chemin, essai, entetes_sup=entetes_sup,
                            encodage=encodage)
            if r.get("ok"):
                logging.info("[FP-API] %s accepté avec %s=%r (%s)",
                             chemin, champ, valeur, type(valeur).__name__)
                r["via"] = "API (%s=%r)" % (champ, valeur)
                return r
    return None


def _fp_api_insiste(methode: str, chemin: str, corps: dict, source: dict = None,
                    entetes_sup: dict = None, encodage: str = "json") -> dict:
    """Appelle l'API en complétant le corps d'après ses propres reproches.

    Un refus 400 du panneau nomme les champs qui manquent. Plutôt que de
    deviner la forme attendue, on la lui fait dicter : on ajoute ce qu'on sait
    fournir et on réessaie. Trois tours au plus — au-delà, c'est qu'on tourne
    en rond, et `bloque` le dit franchement au lieu de boucler."""
    corps = dict(corps or {})
    for _ in range(3):
        r = fp_api_call(methode, chemin, corps, entetes_sup=entetes_sup,
                        encodage=encodage)
        if r.get("ok") or r.get("status") != 400:
            return r
        manquants = _fp_champs_manquants(r.get("detail"))
        if not manquants:
            return r
        avant = dict(corps)
        for champ in manquants:
            if source and champ in source:
                corps[champ] = source[champ]
            elif champ in _FP_SCAN_DEFAUTS:
                corps[champ] = _FP_SCAN_DEFAUTS[champ]
        if corps == avant:
            # Les champs sont là et l'API les refuse : c'est leur FORME qui ne
            # convient pas, pas leur absence. On décline les types connus.
            r2 = _fp_essayer_formes(methode, chemin, corps, manquants, entetes_sup,
                                    encodage)
            if r2 is not None:
                return r2
            r["bloque"] = manquants
            r["corps"] = corps
            return r
        logging.info("[FP-API] %s %s réclamait %s — corps complété",
                     methode, chemin, ", ".join(manquants))
    return r


def _fp_scan_conf_db(sid) -> dict:
    """Configuration d'analyse lue dans la base du panneau, colonnes comprises.

    Les noms sont ceux de la table — `file_size`, `memory_limit` — et non les
    camelCase du formulaire Angular. C'est la base qui fait foi."""
    cols = _fp_db_colonnes("scan_configuration")
    if "virtualhost_id" not in cols:
        return {}
    noms = [c for c in cols if c]
    lignes = _fp_db_query("SELECT %s FROM scan_configuration WHERE virtualhost_id=? "
                          "ORDER BY id DESC LIMIT 1" % ", ".join('"%s"' % c for c in noms),
                          (sid,))
    if not lignes:
        return {}
    return {n: v for n, v in zip(noms, lignes[0]) if v is not None}


def _fp_scan_corps_depart(sid) -> dict:
    """Corps du démarrage : la configuration du site, puis le mode.

    C'est littéralement ce que fait le panneau — `Object(ie.a)(e.item,
    this.form)` recopie la configuration dans le formulaire avant d'y poser
    `form.mode = Normal`. Envoyer deux champs isolés ne pouvait pas suffire :
    le serveur valide l'objet entier, et signalait le premier trou venu."""
    conf = {}
    r = fp_api_call("GET", "/api/sites/%s/scan/configuration" % sid)
    d = r.get("data") if r.get("ok") else None
    if isinstance(d, dict):
        conf = d.get("data") if isinstance(d.get("data"), dict) else d
    if not isinstance(conf, dict) or not conf:
        conf = _fp_scan_conf_db(sid)
    corps = {k: v for k, v in (conf or {}).items()
             if k not in ("pid", "progress", "lock_flag", "hash", "old_hash")}
    if not str(corps.get("locale") or "").strip():
        corps["locale"] = _fp_locale()
    return corps


def _fp_scan_config_creer_db(sid, domain: str) -> str:
    """Crée une configuration d'analyse en écrivant dans la base du panneau.

    ÉCRITURE DIRECTE — l'exception assumée à la règle « ne jamais écrire dans
    fastpanel2.db ». Elle se justifie ici et nulle part ailleurs :

    - l'API refuse la création pour une raison non documentée, et `mogwai`
      n'expose aucune commande de création : sans cela, Cassandra dépend d'un
      clic humain dans FastPanel pour chaque nouveau site ;
    - `scan_configuration` ne pilote aucun service. Contrairement aux tables des
      sites, des bases ou des boîtes mail, FastPanel n'en régénère ni nginx ni
      MySQL ni dovecot ;
    - la ligne est écrite avec `enabled = 0`, comme celles que le panneau a
      lui-même créées : aucune tâche planifiée n'en découle.

    Rend l'identifiant créé, ou "" si l'écriture échoue."""
    chemin = _fp_db_path()
    if not chemin or not os.access(chemin, os.W_OK):
        return ""
    cols = _fp_db_colonnes("scan_configuration")
    if not cols or "virtualhost_id" not in cols:
        return ""
    # On copie la forme d'une configuration existante plutôt que d'inventer :
    # ses valeurs sont celles que FastPanel juge valides.
    modele = {}
    lignes = _fp_db_query("SELECT %s FROM scan_configuration ORDER BY id LIMIT 1"
                          % ", ".join('"%s"' % c for c in cols))
    if lignes:
        modele = dict(zip(cols, lignes[0]))
    valeurs = {
        "minute": "0", "hour": "3", "day_of_month": "*", "month": "*",
        "day_of_week": "0", "command": "", "enabled": 0, "hash": "",
        "old_hash": "", "action": "", "pid": 0, "lock_flag": 0,
        "virtualhost_id": sid, "excludes": modele.get("excludes") or "",
        "exclude_expressions": modele.get("exclude_expressions")
        or "jpg,png,gif,jpeg,JPG,PNG,GIF,bmp,xml,zip,rar,css,avi,mov",
        "file_size": modele.get("file_size") or 512,
        "mode": modele.get("mode") or _FP_SCAN_MODES[0],
        "memory_limit": modele.get("memory_limit") or 1024,
        "delay": modele.get("delay") or 200, "report_path": "",
        "progress": 0, "email": "", "locale": modele.get("locale") or _fp_locale(),
    }
    utiles = [c for c in cols if c in valeurs]
    try:
        cx = sqlite3.connect(chemin, timeout=10)
        try:
            cur = cx.execute("SELECT COUNT(*) FROM scan_configuration WHERE virtualhost_id=?",
                             (sid,))
            if (cur.fetchone() or [0])[0]:
                return _fp_scan_config_id(sid)     # quelqu'un l'a créée entre-temps
            cx.execute("INSERT INTO scan_configuration (%s) VALUES (%s)"
                       % (", ".join('"%s"' % c for c in utiles),
                          ", ".join("?" * len(utiles))),
                       [valeurs[c] for c in utiles])
            cx.commit()
            cur = cx.execute("SELECT id FROM scan_configuration WHERE virtualhost_id=? "
                             "ORDER BY id DESC LIMIT 1", (sid,))
            cid = str((cur.fetchone() or [""])[0] or "")
        finally:
            cx.close()
    except Exception as e:
        logging.warning("[SCAN] écriture de la configuration refusée : %s", e)
        return ""
    if cid:
        logging.info("[SCAN] configuration %s créée en base pour %s", cid, domain)
        try:
            log_admin_action("", "fp_scan_config_db", "OK",
                             "site=%s config=%s (écriture directe)" % (domain, cid))
        except Exception as e:
            logging.debug("[AUDIT] %s", e)
    return cid


def _fp_scan_config_id(sid) -> str:
    """Identifiant de la configuration d'analyse d'un site, ou "".

    Deux sources, dans cet ordre : la base du panneau (immédiate, sans réseau)
    puis son API — la base peut n'avoir pas encore vu une création toute
    fraîche, et c'est précisément le moment où l'on a besoin de cet identifiant."""
    try:
        if "virtualhost_id" in _fp_db_colonnes("scan_configuration"):
            for r in _fp_db_query("SELECT id FROM scan_configuration "
                                  "WHERE virtualhost_id=? ORDER BY id DESC LIMIT 1",
                                  (sid,)):
                if r and r[0]:
                    return str(r[0])
    except Exception as e:
        logging.debug("[SCAN] lecture config en base : %s", e)
    rep = fp_api_call("GET", "/api/sites/%s/scan/configuration" % sid)
    if rep.get("ok"):
        d = rep.get("data")
        if isinstance(d, dict):
            d = d.get("data") if isinstance(d.get("data"), dict) else d
            if str(d.get("id") or "").isdigit():
                return str(d["id"])
        elif isinstance(d, list) and d and isinstance(d[0], dict):
            if str(d[0].get("id") or "").isdigit():
                return str(d[0]["id"])
    return ""


def _fp_champs_manquants(detail) -> list:
    """Champs réclamés par un refus 400 de l'API.

    Le panneau répond {"errors": {"locale": "locale is a required field"}} :
    plutôt que de deviner la forme du corps attendu, on lit ses reproches."""
    if not detail:
        return []
    try:
        d = json.loads(detail) if isinstance(detail, str) else detail
    except Exception:
        return []
    err = d.get("errors") if isinstance(d, dict) else None
    if not isinstance(err, dict):
        return []
    return [str(k) for k in err.keys() if k][:12]


def fp_scan_targets() -> dict:
    """Sites analysables, avec leur configuration et leur dernier rapport.

    Lancer une analyse demandait `--config=<id>` — un identifiant que personne
    ne connaît par cœur. On le résout ici : l'utilisateur choisit un SITE, la
    machine retrouve l'identifiant."""
    cfgs = {}
    if "virtualhost_id" in _fp_db_colonnes("scan_configuration"):
        for r in _fp_db_query(
                "SELECT c.id, c.virtualhost_id, COALESCE(c.enabled,0), "
                "       COALESCE(c.minute,''), COALESCE(c.hour,''), "
                "       COALESCE(c.day_of_week,''), COALESCE(c.email,'') "
                "FROM scan_configuration c"):
            if r and r[1]:
                cfgs[r[1]] = {"config_id": r[0], "enabled": int(r[2] or 0),
                              "planning": ("%s %s * * %s" % (r[3], r[4], r[5])).strip(),
                              "email": r[6]}
    derniers = {}
    if "virtualhost_id" in _fp_db_colonnes("scan_report"):
        for r in _fp_db_query(
                "SELECT virtualhost_id, MAX(created_at), COUNT(*) "
                "FROM scan_report GROUP BY virtualhost_id"):
            if r and r[0]:
                derniers[r[0]] = {"last": str(r[1] or "")[:19], "count": r[2]}
    sites = _fp_db_query("SELECT id, domain FROM site ORDER BY domain")
    out = []
    for sid, dom in sites:
        if not dom:
            continue
        c = cfgs.get(sid) or {}
        d = derniers.get(sid) or {}
        out.append({"domain": dom, "site_id": sid,
                    "config_id": c.get("config_id"), "enabled": c.get("enabled", 0),
                    "planning": c.get("planning", ""), "email": c.get("email", ""),
                    "last_scan": d.get("last", ""), "reports": d.get("count", 0)})
    sans = [x["domain"] for x in out if not x.get("config_id")]
    return {"ok": True, "sites": out, "unconfigured": sans,
            "reason": "" if out else "aucun site connu du panneau"}


def fp_scan_run(domain: str, confirm: bool = False, acteur: str = "") -> dict:
    """Lance l'analyse d'un site désigné PAR SON NOM.

    `mogwai scan:virtualhost --config=N` d'abord : il fonctionne, il ne dépend
    d'aucun protocole non documenté, et une configuration suffit. L'API du
    panneau vient après — `PUT /api/sites/{id}/scan/start` ne valide pas le
    corps envoyé mais la configuration que le serveur charge pour le site, si
    bien qu'un site sans configuration se voit reprocher un `locale` pourtant
    présent dans la requête. Ce message trompeur a coûté plusieurs jours ; le
    chemin sûr passe donc en premier."""
    dn = _norm_domain(domain)
    cible = next((x for x in fp_scan_targets().get("sites", [])
                  if _norm_domain(x["domain"]) == dn), None)
    if not cible:
        return {"ok": False, "reason": "site « %s » inconnu du panneau" % domain}
    if not confirm:
        return {"ok": False, "needs_confirm": True,
                "reason": "Lance une analyse antivirus sur %s. Elle parcourt tous "
                          "les fichiers du site et peut durer plusieurs minutes."
                          % cible["domain"]}
    sid = cible["site_id"]
    # Le verbe vient du panneau lui-même, pas d'une hypothèse : son JavaScript
    # fait `this.http.put('/api/sites/${id}/scan/start', t)`. C'est un PUT, avec
    # un corps — et l'API dit elle-même ce qu'il doit contenir : un refus 400
    # renvoie {"errors": {"champ": "..."}}. Plutôt que de deviner la forme de
    # `t`, on lit ces reproches et on complète, au plus trois tours.
    # Le corps est celui du formulaire du panneau : `mode` (nombre) et `locale`
    # (chaîne, « en » ou « ru »). Seule la valeur numérique du mode normal nous
    # échappe, d'où l'essai des quelques entiers possibles — le premier accepté
    # est journalisé et retenu pour l'affichage.
    chemin = "/api/sites/%s/scan/start" % sid
    # Trois axes, du plus probable au plus improbable : l'adresse (le panneau
    # est sur 8888, pas sur 5501 — s'y tromper explique un refus constant),
    # l'encodage du corps, puis le mode.
    # La configuration est le prérequis commun aux deux chemins.
    cid = _fp_scan_config_id(sid)
    if not cid:
        c = fp_scan_configure(cible["domain"], confirm=True, acteur=acteur)
        cid = _fp_scan_config_id(sid)
        if not cid:
            logging.info("[SCAN] création par l'API refusée pour %s : %s",
                         cible["domain"], c.get("reason"))
            # L'API refuse et mogwai ne sait pas créer : sans ce recours,
            # chaque nouveau site réclamerait un clic humain dans FastPanel.
            cid = _fp_scan_config_creer_db(sid, cible["domain"])
    if cid:
        # Le chemin qui marche, essayé en premier. `mogwai` ne dit rien quand
        # il réussit — silence et code 0 valent confirmation.
        m = fp_action_run("analyse_site", cid, confirm=True, acteur=acteur)
        if m.get("ok"):
            m["via"] = "mogwai (configuration %s)" % cid
            m["domain"] = cible["domain"]
            try:
                log_admin_action(acteur or "", "fp_scan_start", "OK",
                                 "site=%s via=mogwai config=%s" % (cible["domain"], cid))
            except Exception as e:
                logging.debug("[AUDIT] %s", e)
            return m
        logging.info("[SCAN] mogwai a refusé (config %s) : %s", cid,
                     m.get("output") or m.get("reason"))
    adresses = [""] + [b for b in _fp_api_bases() if b != (_FP_JWT.get("base") or "")]
    # JSON uniquement : envoyé en formulaire, le panneau répond
    # {"error":{"Offset":1}} — l'erreur d'analyse JSON de Go. Il lit donc bien
    # du JSON, et insister en formulaire ne ferait que brouiller la trace.
    fini = False
    for adresse in adresses:
        base_corps = _fp_scan_corps_depart(sid)
        for mode in _FP_SCAN_MODES:
            corps = dict(base_corps)
            corps["mode"] = mode
            r = fp_api_call("PUT", chemin, corps, base=adresse)
            if r.get("ok"):
                logging.info("[SCAN] démarré sur %s, mode=%s, %d champs",
                             adresse or "base authentifiée", mode, len(corps))
                r["via"] = "API (%s, mode=%s)" % (
                    adresse or _FP_JWT.get("base") or "base authentifiée", mode)
                fini = True
                break
            if r.get("status") != 400:
                break                  # 401, 404… : changer de mode n'y fera rien
        if fini:
            break
    # Ce qui suivait ici — chercher `locale` en requête, en en-tête, sous
    # d'autres orthographes — est réfuté : l'étiquette du binaire est bien
    # `json:"locale"`, et le corps la porte. Le champ manquant n'est pas dans
    # notre requête. Garder ces essais reviendrait à conserver des tentatives
    # dont on sait qu'elles ne peuvent pas aboutir.
    if not r.get("ok") and r.get("status") == 404:
        for methode, chemin in (("POST", "/api/sites/%s/scan/start" % sid),
                                ("POST", "/api/sites/%s/scan" % sid)):
            r2 = fp_api_call(methode, chemin, {})
            if r2.get("ok"):
                r = r2
                logging.info("[SCAN] démarrage via %s %s", methode, chemin)
                break
    if not r.get("ok"):
        r["tried"] = r.get("url", "")
    if r.get("ok"):
        try:
            log_admin_action(acteur or "", "fp_scan_start", "OK",
                             "site=%s id=%s" % (cible["domain"], cible["site_id"]))
        except Exception as e:
            logging.debug("[AUDIT] %s", e)
        return {"ok": True, "domain": cible["domain"], "via": r.get("via") or "api",
                "output": "Analyse démarrée sur %s." % cible["domain"]}
    if not cid:
        # Diagnostic honnête : ce n'est pas le démarrage qui bloque, c'est
        # l'absence de configuration. Le dire évite de chercher ailleurs.
        return {"ok": False,
                "reason": "aucune configuration d'analyse pour %s" % cible["domain"],
                "detail": "Ni mogwai ni l'API ne peuvent lancer une analyse sans "
                          "configuration, et sa création a échoué. Créez-la une "
                          "fois depuis FastPanel (Sites → %s → Analyse) : "
                          "Cassandra saura ensuite la relancer seule."
                          % cible["domain"]}
    return {"ok": False,
            "reason": "l'API a refusé le démarrage (%s)" % (r.get("reason") or r.get("status")),
            "detail": "\n".join(x for x in (
                ("URL essayée : %s" % r["tried"]) if r.get("tried") else "",
                ("Sonde voisine : %s" % r["probe"]) if r.get("probe") else "",
                ("Base authentifiée : %s" % (_FP_JWT.get("base") or _fp_api_base())),
                "Corps envoyés : JSON, modes %s"
                % ", ".join(str(m) for m in _FP_SCAN_MODES),
                # Les réponses brutes du serveur, telles quelles. `detail` est
                # réécrit en cours de route par nos propres explications : s'y
                # fier revenait à relire ma prose au lieu de la sienne.
                ("Réponses du panneau :\n  " + "\n  ".join(_FP_API_TRACE[-6:]))
                if _FP_API_TRACE else "",
            ) if x)}


def fp_scan_configure(domain: str, confirm: bool = False, acteur: str = "") -> dict:
    """Crée la configuration d'analyse d'un site, via l'API du panneau."""
    dn = _norm_domain(domain)
    cible = next((x for x in fp_scan_targets().get("sites", [])
                  if _norm_domain(x["domain"]) == dn), None)
    if not cible:
        return {"ok": False, "reason": "site « %s » inconnu du panneau" % domain}
    if cible.get("config_id"):
        return {"ok": True, "deja": True,
                "output": "Une configuration existe déjà pour %s." % cible["domain"]}
    if not confirm:
        return {"ok": False, "needs_confirm": True,
                "reason": "Crée une configuration d'analyse pour %s (hebdomadaire, "
                          "dimanche 3 h)." % cible["domain"]}
    # Noms et valeurs relevés sur les configurations que le panneau a lui-même
    # écrites : `file_size`, `memory_limit` en snake_case — pas les camelCase du
    # formulaire Angular — et ses propres défauts plutôt que des nombres choisis
    # au hasard. Reste le calendrier : une analyse par semaine, la nuit.
    # `enabled` est déclaré `numeric` dans la table, pas booléen : un `true`
    # JSON n'y entre pas, et un corps qui ne se décode pas laisse TOUS les
    # champs vides — le serveur se plaint alors du premier obligatoire venu.
    exts = "jpg,png,gif,jpeg,JPG,PNG,GIF,bmp,xml,zip,rar,css,avi,mov"
    corps = {"enabled": 1, "minute": "0", "hour": "3", "day_of_month": "*",
             "month": "*", "day_of_week": "0", "locale": _fp_locale(),
             "email": "", "mode": _FP_SCAN_MODES[0], "delay": 200, "lock": False,
             "excludes": exts, "exclude_expressions": "",
             "file_size": 512, "memory_limit": 1024,
             # Le gabarit Angular nomme ces champs en camelCase
             # (`["name","fileSize"]`), la table en snake_case. On ne sait pas
             # lequel des deux l'API attend, et les deux peuvent voyager
             # ensemble : Go ignore les clés qu'il ne connaît pas.
             "excludeExtensions": exts, "fileSize": 512, "memoryLimit": 1024,
             "dayOfMonth": "*", "dayOfWeek": "0"}
    # La carte des appels du panneau donne le verbe : `put(.../scan/configuration)`.
    # POST reste en repli — certaines versions acceptent les deux.
    chemin = "/api/sites/%s/scan/configuration" % cible["site_id"]
    for methode in ("PUT", "POST"):
        # POST est tenté même après un 400 : PUT et POST ne veulent pas dire la
        # même chose. Sur un site sans configuration, un PUT met à jour un objet
        # qui n'existe pas — le serveur valide alors un enregistrement vide et
        # se plaint d'un champ que nous avons pourtant envoyé. Sauter POST parce
        # que « 400 est un vrai refus » supprimait la seule voie de création.
        r = _fp_api_insiste(methode, chemin, corps)
        if r.get("ok") or r.get("status") in (401, 403):
            break
    try:
        log_admin_action(acteur or "", "fp_scan_config", "OK" if r.get("ok") else "FAIL",
                         "site=%s status=%s" % (cible["domain"], r.get("status")))
    except Exception as e:
        logging.debug("[AUDIT] %s", e)
    if r.get("ok"):
        return {"ok": True, "output": "Analyse hebdomadaire configurée pour %s "
                                      "(dimanche 3 h)." % cible["domain"]}
    return {"ok": False, "reason": r.get("reason") or "échec",
            "detail": r.get("detail", ""), "status": r.get("status")}


_FP_RAPPORTS_RACINE = "/usr/local/fastpanel2/web/ai-bolit"
_FP_RAPPORT_MAX = 4 * 1024 * 1024      # au-delà, on ne lit que le début


def _fp_rapport_nettoyer(html: str) -> str:
    """Retire d'un rapport tout ce qui pourrait s'exécuter.

    Un rapport ai-bolit CITE le code malveillant qu'il a trouvé : scripts,
    gestionnaires d'événements, balises injectées. Il est affiché en iframe
    `sandbox=""`, ce qui suffit déjà — mais on ne fait pas reposer la sécurité
    sur un seul verrou quand le contenu est, par nature, hostile."""
    h = re.sub(r"(?is)<\s*(script|iframe|object|embed|applet|form|link|meta|base)\b.*?"
               r"(?:</\s*\1\s*>|>)", "", html)
    h = re.sub(r"(?is)<\s*/\s*(script|iframe|object|embed|applet|form)\s*>", "", h)
    h = re.sub(r"(?is)\son[a-z]+\s*=\s*(\"[^\"]*\"|'[^']*'|[^\s>]+)", "", h)
    h = re.sub(r"(?is)(href|src|action|data|formaction)\s*=\s*(\"|')?\s*"
               r"(javascript|vbscript|data)\s*:", r"\1=\2#neutralise:", h)
    return h


def fp_scan_report_lire(chemin: str) -> dict:
    """Contenu d'un rapport d'analyse, résumé et neutralisé.

    Le chemin vient de la base du panneau, donc d'une source de confiance — mais
    il transite par le navigateur, donc on le revérifie : `realpath` doit rester
    sous le répertoire des rapports. Sans ça, `../../etc/shadow` serait lisible
    par quiconque atteint cette route."""
    brut = (chemin or "").strip()
    if not brut:
        return {"ok": False, "reason": "aucun rapport indiqué"}
    racine = os.path.realpath(_FP_RAPPORTS_RACINE)
    # Un chemin relatif (celui des lignes d'analyse : « ai-bolit/… ») se résout sous le répertoire
    # des rapports (20-09) ; le garde-fou ci-dessous vaut pour les deux formes.
    if not brut.startswith("/"):
        _rel = brut[len("ai-bolit/"):] if brut.startswith("ai-bolit/") and os.path.basename(racine) == "ai-bolit" else brut
        brut = os.path.join(racine, _rel)
    reel = os.path.realpath(brut)
    if not (reel == racine or reel.startswith(racine + os.sep)):
        logging.warning("[SCAN] lecture de rapport hors répertoire refusée : %s", brut)
        return {"ok": False, "reason": "ce chemin ne désigne pas un rapport d'analyse"}
    if not os.path.isfile(reel):
        return {"ok": False, "reason": "rapport introuvable — il a pu être purgé",
                "chemin": reel}
    try:
        taille = os.path.getsize(reel)
        with open(reel, "r", encoding="utf-8", errors="replace") as f:
            html = f.read(_FP_RAPPORT_MAX)
    except Exception as e:
        return {"ok": False, "reason": "lecture impossible : %s" % str(e)[:120]}
    return {"ok": True, "chemin": reel, "nom": os.path.basename(reel),
            "taille": taille, "tronque": taille > _FP_RAPPORT_MAX,
            "modifie": time.strftime("%Y-%m-%d %H:%M",
                                     time.localtime(os.path.getmtime(reel))),
            "resume": _fp_rapport_resume(html),
            "html": _fp_rapport_nettoyer(html)}


def _fp_rapport_resume(html: str) -> dict:
    """Ce qu'il faut retenir d'un rapport sans l'ouvrir.

    ai-bolit n'expose pas de format machine : on lit ses compteurs dans le
    texte. Les libellés changent d'une version à l'autre, donc chaque nombre
    absent vaut « inconnu » et non zéro — annoncer « 0 fichier suspect » sur une
    lecture ratée serait pire que de ne rien annoncer."""
    texte = re.sub(r"(?is)<[^>]+>", " ", html)
    texte = re.sub(r"\s+", " ", texte)
    out = {"suspects": None, "malveillants": None, "analyses": None,
           "duree": "", "version": ""}
    motifs = (
        ("malveillants", r"(?:malicious|вредонос\w*|malveillant\w*)\D{0,40}?(\d[\d\s]*)"),
        ("suspects", r"(?:suspicious|подозрит\w*|suspect\w*)\D{0,40}?(\d[\d\s]*)"),
        ("analyses", r"(?:files? (?:scanned|checked)|проверено\w*|fichiers? analys\w*)"
                     r"\D{0,40}?(\d[\d\s]*)"),
    )
    for cle, motif in motifs:
        m = re.search(motif, texte, re.I)
        if m:
            try:
                out[cle] = int(re.sub(r"\s", "", m.group(1)))
            except ValueError:
                pass
    m = re.search(r"AI-?BOLIT[^\d]{0,20}([\d.]+)", texte, re.I)
    if m:
        out["version"] = m.group(1)
    m = re.search(r"(?:scan time|время|dur[ée]e)\D{0,20}([\d:]+\s*\w{0,8})", texte, re.I)
    if m:
        out["duree"] = m.group(1).strip()[:20]
    # Les chemins cités : c'est ce qu'on veut voir en premier quand ça alerte.
    fichiers = re.findall(r"(/(?:var|home|usr|srv)/[\w./\-]{4,120})", texte)
    vus, liste = set(), []
    for f in fichiers:
        if f not in vus and not f.startswith(_FP_RAPPORTS_RACINE):
            vus.add(f)
            liste.append(f)
    out["fichiers"] = liste[:50]
    out["fichiers_total"] = len(vus)
    return out


def fp_scan_rapports() -> dict:
    """Rapports présents sur le disque, du plus récent au plus ancien.

    La table `scan_report` ne voit que ce que le panneau a enregistré ; le
    répertoire, lui, contient tout — y compris les analyses lancées à la main.
    On liste donc les fichiers, et on retrouve le domaine dans leur nom :
    `exemple.org_2026-08-07-13_25_15.html`."""
    racine = _FP_RAPPORTS_RACINE
    if not os.path.isdir(racine):
        return {"ok": False, "reason": "aucun répertoire de rapports (%s)" % racine,
                "rapports": []}
    out = []
    try:
        noms = os.listdir(racine)
    except Exception as e:
        return {"ok": False, "reason": "répertoire illisible : %s" % str(e)[:120],
                "rapports": []}
    for nom in noms:
        if not nom.lower().endswith((".html", ".htm")):
            continue
        chemin = os.path.join(racine, nom)
        try:
            st = os.stat(chemin)
        except Exception:
            continue
        m = re.match(r"(.+?)_(\d{4}-\d{2}-\d{2})-(\d{2})_(\d{2})_(\d{2})\.html?$", nom, re.I)
        out.append({
            "nom": nom, "chemin": chemin, "taille": st.st_size,
            "domain": m.group(1) if m else "",
            "date": ("%s %s:%s:%s" % (m.group(2), m.group(3), m.group(4), m.group(5)))
                    if m else time.strftime("%Y-%m-%d %H:%M:%S",
                                            time.localtime(st.st_mtime)),
            "mtime": st.st_mtime})
    out.sort(key=lambda x: x["mtime"], reverse=True)
    return {"ok": True, "rapports": out[:200], "total": len(out), "racine": racine}


def get_fp_scans() -> list:
    """Analyses antivirus de FastPanel — jamais affichées jusqu'ici.

    FastPanel scanne les sites et range ses rapports dans `scan_report`. Aucune
    page de Cassandra ne les montrait : un site signalé infecté restait invisible."""
    cols = _fp_db_colonnes("scan_report")
    if not cols:
        return []
    rows = _fp_db_query(
        # `r.status` SANS COALESCE (2026-09-05) : `COALESCE(r.status,0)` puis
        # « 0 = propre » transformait un statut jamais écrit (analyse
        # interrompue, rapport incomplet) en site propre. NULL est « inconnu ».
        "SELECT COALESCE(s.domain,''), r.status, COALESCE(r.action,''), "
        "       COALESCE(r.web_path,''), COALESCE(r.path,''), COALESCE(r.created_at,'') "
        "FROM scan_report r LEFT JOIN site s ON r.virtualhost_id = s.id "
        "ORDER BY r.created_at DESC LIMIT 100")
    out = []
    for r in rows:
        if not r:
            continue
        # `status` non documenté : 0 vaut « propre » partout où on l'a observé ;
        # NULL ou vide n'a été observé nulle part, on ne l'interprète pas.
        if r[1] is None or str(r[1]).strip() == "":
            statut = "inconnu"
        elif str(r[1]).strip() == "0":
            statut = "ok"
        else:
            statut = "infecté"
        out.append({"domain": r[0], "status": statut,
                    "action": r[2], "report": r[3] or r[4],
                    "created_at": str(r[5] or "")[:19]})
    return out


def get_fp_mail():
    # ROBUSTESSE: Ajout d'un bloc try/except englobant pour capturer toutes les exceptions
    try:
        _riche = _fp_mail_riches()
        d = get_entity_from_socket("fastpanel_mail_accounts")
        if _riche:
            return _fp_enrichir(d or [], _riche, "email")
        if d: return d
        r = query_db("SELECT email,domain,quota_mb,used_mb,status FROM fastpanel_mail_accounts ORDER BY email")
        if r: return r
        # MySQL direct
        # ROBUSTESSE: Validation du lambda pour éviter les erreurs si r est None ou trop court
        # Schéma réel : mailboxes(login, address, quota, size, enabled, domain_id)
        # jointe à email_domain(name). Les tables `mail_account`/`mail_domain`
        # n'existent pas. Le mapper reconstruit l'adresse avec f"{r[0]}@{r[1]}" :
        # on renvoie donc TOUJOURS la partie locale, même si `login` contient
        # déjà l'adresse complète — sinon on obtiendrait « u@d@d ».
        # NB : unités de `quota` et `size` non documentées, transmises telles
        # quelles (ces tables sont vides ici, impossible de les vérifier).
        result = _fp_mysql_direct(
            "SELECT CASE WHEN instr(COALESCE(m.login,''),'@') > 0 "
            "            THEN substr(m.login, 1, instr(m.login,'@') - 1) "
            "            ELSE COALESCE(m.login,'') END, "
            "COALESCE(e.name,''), COALESCE(m.quota,0), COALESCE(m.size,0), "
            "CASE WHEN CAST(m.enabled AS TEXT) IN ('1','true') THEN 'active' "
            "     WHEN m.enabled IS NULL THEN '' ELSE 'suspended' END "
            # Jointure INTERNE, comme la requête d'origine : une boîte dont le
            # domaine ne résout pas donnerait une adresse malformée « login@ ».
            "FROM mailboxes m JOIN email_domain e ON m.domain_id = e.id "
            "ORDER BY e.name, m.login",
            lambda r: {
                "email": f"{r[0]}@{r[1]}", "domain": r[1],
                "quota_mb": int(r[2] or 0), "used_mb": int(r[3] or 0),
                "status": r[4] or "active",
            } if r and len(r) >= 5 else None  # ROBUSTESSE: Vérifie len(r) >= 5 au lieu de 2
        )
        if result: return result
        # Fallback postfix virtual
        # ROBUSTESSE: Utilisation de pathlib.Path avec gestion d'erreur améliorée
        try:
            accounts, seen = [], set()
            for vf in ["/etc/postfix/virtual", "/etc/postfix/vmailbox"]:
                p = __import__('pathlib').Path(vf)
                if not p.exists(): continue
                # ROBUSTESSE: Lecture avec gestion d'erreur d'encodage et fichier vide
                try:
                    content = p.read_text(errors="replace")
                except (IOError, OSError) as e:
                    # ROBUSTESSE: Log l'erreur mais continue
                    continue
                for line in content.splitlines():
                    line = line.strip()
                    if not line or line.startswith("#") or "@" not in line:
                        continue
                    # ROBUSTESSE: Extraction robuste de l'email (premier champ avant espace)
                    parts = line.split()
                    if not parts:
                        continue
                    email = parts[0]
                    if "@" not in email:
                        continue
                    if email in seen:
                        continue
                    seen.add(email)
                    # ROBUSTESSE: Validation du domaine
                    domain = email.split("@")[1]
                    if not domain:
                        continue
                    accounts.append({"email": email, "domain": domain,
                                     "quota_mb": 0, "used_mb": 0, "status": "active"})
            return accounts
        except Exception as e:
            # ROBUSTESSE: Log l'erreur et retourne liste vide
            return []
    except Exception as e:
        # ROBUSTESSE: Capture toute exception non gérée
        return []

def get_fp_ftp():
    _riche = _fp_ftp_riches()
    d = get_entity_from_socket("fastpanel_ftp_accounts")
    if _riche:
        return _fp_enrichir(d or [], _riche, "login")
    if d: return d
    r = query_db("SELECT login,home_dir,status,owner FROM fastpanel_ftp_accounts ORDER BY login")
    if r: return r
    # Schéma réel : ftp_account(name, home_dir, enabled, owner_id) — pas de
    # colonnes `login`, `status` ni `user_id`, et le propriétaire est un
    # panel_account.
    return _fp_mysql_direct(
        "SELECT f.name, COALESCE(f.home_dir,''), "
        "CASE WHEN CAST(f.enabled AS TEXT) IN ('1','true') THEN 'active' "
        "     WHEN f.enabled IS NULL THEN '' ELSE 'suspended' END, "
        "COALESCE(p.username,'') "
        "FROM ftp_account f LEFT JOIN panel_account p ON f.owner_id = p.id "
        "ORDER BY f.name",
        lambda r: {"login": r[0], "home_dir": r[1] or "", "status": r[2] or "active",
                   "owner": r[3] if len(r) > 3 else ""} if r and r[0] else None
    )

