def get_fp_php():
    d = get_entity_from_socket("fastpanel_php_versions")
    src = "collecteur"
    if not d:
        d = query_db("SELECT version,full_version,path,active FROM fastpanel_php_versions ORDER BY version DESC")
        src = "table locale"
    # D'où vient chaque ligne (2026-09-05). Un tableau vide ne disait pas si le
    # collecteur était tombé ou s'il n'y avait rien : la route ajoute la
    # raison quand c'est vide (`_fp_erreur_source`), les lignes portent leur
    # source quand il y en a. La liste reste une liste : `fp_service_watch`
    # et le résumé la parcourent.
    for x in (d or []):
        if isinstance(x, dict):
            x.setdefault("source", src)
    return d

@_garde_reentrance
def _fp_crons_brut():
    """Les tâches du panneau, telles quelles — socket du collecteur, sinon la base.
    C'est CE QUE `cron_unified_list` doit lire : la version enrichie ci-dessous
    l'appelle, et l'appeler depuis elle refermait un cercle."""
    d = get_entity_from_socket("fastpanel_crons")
    if not d:
        d = query_db("SELECT user,schedule,command,enabled,last_run,last_status "
                     "FROM fastpanel_crons ORDER BY user")
    return d


@_garde_reentrance
def get_fp_crons():
    d = _fp_crons_brut()
    # Les tâches de FastPanel et celles de l'onglet « Tâches planifiées » sont
    # les mêmes lignes de crontab, lues par deux chemins différents. Sans ce
    # rapprochement, la même tâche apparaissait deux fois sans qu'on puisse le
    # savoir — et surveiller l'une n'apprenait rien sur l'autre.
    #
    # LE CERCLE. `cron_unified_list` lisait les tâches du panneau par CETTE
    # fonction, qui l'appelait à son tour pour les rapprocher : mille niveaux,
    # une socket ouverte à chacun, un RecursionError avalé par l'except du
    # dernier — et chaque niveau « réussissait » avec des données partielles.
    # Quatre secondes par appel, plusieurs par route, trois routes par page :
    # l'onglet Automatismes mettait trente à quatre-vingts secondes à s'ouvrir.
    # La liste unifiée lit désormais `_fp_crons_brut` ; le cercle est rompu.
    try:
        connus = {}
        for c in (cron_unified_list() or []):
            cle = (str(c.get("command") or "").strip(),
                   str(c.get("schedule") or "").strip())
            if cle[0]:
                connus[cle] = c
        for c in (d or []):
            if not isinstance(c, dict):
                continue
            m = connus.get((str(c.get("command") or "").strip(),
                            str(c.get("schedule") or "").strip()))
            if m:
                c["cassandra_id"] = m.get("id")
                c["watched"] = bool(m.get("watched") or m.get("critical"))
                c["project"] = m.get("project") or ""
    except Exception as e:
        # WARNING et le TYPE : c'est ici qu'un RecursionError s'est tu en INFO
        # pendant des semaines. Un échec de lecture ne se consigne pas en INFO.
        logging.warning("[FP-CRONS] rapprochement impossible (%s) : %s", type(e).__name__, e)
    return d


def fp_backup_plans() -> dict:
    """Plans de sauvegarde du panneau, avec leur identifiant.

    L'onglet listait des sauvegardes passées sans jamais dire quels plans
    existent : constater qu'il n'y en a aucune ne servait à rien tant qu'on ne
    pouvait pas voir, ni créer, le plan qui les produit."""
    r = fp_api_call("GET", "/api/v2/backup/plans")
    if not r.get("ok"):
        r = fp_api_call("GET", "/api/backup/plans")
    if not r.get("ok"):
        # L'API peut être hors service ; mogwai sait lister, plus lentement.
        m = fp_action_run("sauvegardes_lister", "", confirm=True)
        # fp_action_run rend la clé `data`, jamais `json` : le repli mogwai ne réussissait jamais
        if m.get("ok") and isinstance(m.get("data") if m.get("data") is not None else m.get("json"), list):
            return {"ok": True, "plans": m["json"], "via": "mogwai"}
        return {"ok": False, "reason": r.get("reason") or "plans illisibles",
                "plans": []}
    d = r.get("data")
    if isinstance(d, dict):
        d = d.get("data") if isinstance(d.get("data"), list) else [d]
    return {"ok": True, "plans": [x for x in (d or []) if isinstance(x, dict)],
            "via": "api"}


def fp_backup_stockages() -> dict:
    """Les stockages de sauvegarde déclarés dans le panneau (dossier du serveur, FTP, S3…) : un plan
    écrit DANS l'un d'eux. Sans stockage, aucun plan n'est possible — c'est ce que « Créer un plan »
    ne disait pas (20-09 : un 400 brut sur `account`)."""
    r = fp_api_call("GET", "/api/backups/accounts")
    if not r.get("ok"):
        return {"ok": False, "reason": r.get("reason") or "stockages illisibles", "stockages": []}
    d = r.get("data")
    if isinstance(d, dict):
        d = d.get("data") if isinstance(d.get("data"), list) else [d]
    return {"ok": True, "stockages": [x for x in (d or []) if isinstance(x, dict)]}


def fp_backup_stockage_local_creer(nom: str, chemin: str, confirm: bool = False, acteur: str = "") -> dict:
    """Déclare un stockage LOCAL dans le panneau : un dossier du serveur. Sondé le 20-09 :
    `{name, type: "local", path}` suffit. C'est un filet sur le même disque que les sites, pas une
    copie hors machine — la feuille le dit."""
    n = (nom or "").strip() or "local"
    c = (chemin or "").strip() or "/var/backups/panneau"
    if not re.match(r"^[\w .\-]{2,64}$", n):
        return {"ok": False, "reason": "nom de stockage invalide (2 à 64 caractères)"}
    if not re.match(r"^/[\w./\-]{1,200}$", c) or ".." in c:
        return {"ok": False, "reason": "chemin invalide : un dossier absolu du serveur, sans « .. »"}
    if not confirm:
        return {"ok": False, "needs_confirm": True,
                "reason": "Déclare le stockage « %s » dans le panneau : le dossier %s du serveur. Les sauvegardes "
                          "y seront écrites — sur le même disque que les sites : c'est un filet, pas une copie "
                          "hors machine." % (n, c)}
    r = fp_api_call("POST", "/api/backups/accounts", {"name": n, "type": "local", "path": c})
    try:
        log_admin_action(acteur or "", "fp_backup_storage_create", "OK" if r.get("ok") else "FAIL", "stockage=%s %s" % (n, c))
    except Exception as e:
        logging.debug("[AUDIT] %s", e)
    if not r.get("ok"):
        return {"ok": False, "reason": r.get("reason") or "déclaration refusée",
                "detail": str(r.get("detail") or r.get("brut") or "")[:400]}
    d = r.get("data")
    d = d.get("data") if isinstance(d, dict) and isinstance(d.get("data"), dict) else d
    return {"ok": True, "stockage": d if isinstance(d, dict) else {},
            "output": "Stockage « %s » déclaré : %s." % (n, c)}


_FP_JOURS = {"0": "dimanche", "1": "lundi", "2": "mardi", "3": "mercredi", "4": "jeudi", "5": "vendredi", "6": "samedi"}


def _fp_plan_quand(jours: str, heure: str) -> str:
    j = str(jours or "*")
    return ("chaque jour" if j == "*" else ("chaque " + _FP_JOURS[j] if j in _FP_JOURS else "les jours %s" % j)) + " à %s h" % heure


def fp_backup_plan_creer(nom: str, cible: str = "", jours: str = "*",
                         heure: str = "4", confirm: bool = False,
                         acteur: str = "", stockage: str = "", garder=7) -> dict:
    """Crée un plan de sauvegarde. `confirm` obligatoire : ça écrit du disque.

    Le corps est celui du formulaire du panneau, lu dans son JavaScript le 20-09 (le 400 du panneau
    nommait `account`, `user_id`, les compresseurs et les limites de copies) : un plan écrit dans un
    stockage déclaré, garde N copies pleines et N partielles, et sauvegarde tous les comptes
    (`/full`) — à défaut, le compte propriétaire du stockage."""
    n = (nom or "").strip()
    if not n or not re.match(r"^[\w .\-]{2,64}$", n):
        return {"ok": False, "reason": "nom de plan invalide (2 à 64 caractères)"}
    jours, heure = str(jours or "*"), str(heure or "4")
    try:
        garder = max(1, min(60, int(garder or 7)))
    except (TypeError, ValueError):
        garder = 7
    st = fp_backup_stockages()
    if not st.get("ok"):
        return {"ok": False, "reason": "stockages illisibles : %s" % st.get("reason")}
    comptes = st.get("stockages") or []
    if not comptes:
        return {"ok": False, "needs_storage": True,
                "reason": "Aucun stockage de sauvegarde n'est déclaré dans le panneau : un plan a besoin d'un "
                          "endroit où écrire. Déclarez-en un — un dossier du serveur suffit pour commencer —, "
                          "puis créez le plan."}
    compte = next((c for c in comptes if str(c.get("id")) == str(stockage)), comptes[0]) if stockage else comptes[0]
    if not confirm:
        return {"ok": False, "needs_confirm": True,
                "reason": "Crée le plan « %s » : %s, %s, vers le stockage « %s » (%s) ; %d copies gardées. "
                          "Il consommera de l'espace disque."
                          % (n, cible or "tous les sites et toutes les bases", _fp_plan_quand(jours, heure),
                             compte.get("name") or "?", compte.get("type") or "?", garder)}
    corps = {"name": n, "account": compte.get("id"), "compressor_name": "gzip", "compressor_lvl": "best_speed",
             "full_copy_limit": garder, "partial_copy_limit": garder,
             "minute": "0", "hour": heure, "day_of_month": "*", "month": "*", "day_of_week": jours,
             "exclude_email": False, "exclude_logs": False, "excluded_users": [], "excluded_databases": []}
    # TOUS LES COMPTES d'abord ; sinon le compte qui possède le stockage (un panneau à un seul compte).
    r = fp_api_call("POST", "/api/v2/backup/plans/full", corps)
    via = "tous les comptes"
    if not r.get("ok"):
        corps["user_id"] = compte.get("owner_id") or ((compte.get("owner") or {}).get("id")) or 1
        r = fp_api_call("POST", "/api/v2/backup/plans", corps)
        via = "le compte %s" % (((compte.get("owner") or {}).get("username")) or corps["user_id"])
    try:
        log_admin_action(acteur or "", "fp_backup_plan_create",
                         "OK" if r.get("ok") else "FAIL", "plan=%s stockage=%s" % (n, compte.get("name")))
    except Exception as e:
        logging.debug("[AUDIT] %s", e)
    if not r.get("ok"):
        return {"ok": False, "reason": r.get("reason") or "création refusée",
                "detail": str(r.get("detail") or r.get("brut") or "")[:600]}
    return {"ok": True, "output": "Plan « %s » créé pour %s : %s, %d copies gardées, vers « %s ». Lancez-le "
                                  "depuis la liste ou attendez sa première exécution."
                                  % (n, via, _fp_plan_quand(jours, heure), garder, compte.get("name") or "?")}


_FP_AVATAR_COLS = ("avatar", "photo", "picture", "image", "gravatar", "avatar_url")
_FP_AVATAR_DIRS = ("/usr/local/fastpanel2/web/public/avatar",
                   "/usr/local/fastpanel/web/public/avatar")
# Sans extension aussi : FastPanel range parfois l'image sous le seul
# identifiant du compte, sans suffixe.
_FP_AVATAR_EXT = (".png", ".jpg", ".jpeg", ".webp", ".gif", ".svg", "")


def _fp_avatar_fichier(uid: str, username: str) -> str:
    """Fichier portrait d'un compte, ou "".

    FastPanel ne garde aucune colonne d'avatar : les images sont des fichiers
    dans `web/public/avatar`. Leur nommage n'est pas documenté, donc on liste
    le répertoire et on rapproche par identifiant puis par login, plutôt que de
    parier sur une convention."""
    candidats = [c for c in (str(uid or ""), (username or "").strip()) if c]
    if not candidats:
        return ""
    for racine in _FP_AVATAR_DIRS:
        # `avatar` peut être le fichier lui-même et non un dossier : la commande
        # `find` ne distinguait pas les deux, et supposer un dossier faisait
        # tout échouer en silence.
        if os.path.isfile(racine):
            return racine
        if not os.path.isdir(racine):
            continue
        try:
            noms = sorted(os.listdir(racine))
        except Exception:
            continue
        images = []
        for nom in noms:
            chemin = os.path.join(racine, nom)
            if not os.path.isfile(chemin):
                continue
            base, ext = os.path.splitext(nom)
            if ext.lower() in _FP_AVATAR_EXT:
                images.append((base, chemin))
        for cle in candidats:
            for base, chemin in images:
                if base == cle:
                    return chemin
        # Aucun nom ne correspond : si le panneau n'a qu'UN compte et le dossier
        # qu'UNE image, l'attribution ne prête pas à confusion. Au-delà, on
        # préfère ne rien montrer plutôt que le portrait de quelqu'un d'autre.
        if len(images) == 1 and _fp_comptes_nombre() == 1:
            logging.info("[AVATAR] portrait unique attribué au compte unique")
            return images[0][1]
    return ""


def _fp_comptes_nombre() -> int:
    """Nombre de comptes du panneau. 0 si la base est illisible."""
    try:
        for r in _fp_db_query("SELECT COUNT(*) FROM panel_account"):
            if r:
                return int(r[0] or 0)
    except Exception as e:
        logging.debug("[AVATAR] comptage : %s", e)
    return 0


# Un portrait téléversé depuis un téléphone pèse couramment plusieurs Mo — celui
# de ce serveur fait 4,9 Mo. Une limite à 512 ko le rejetait en silence, ce qui
# donnait « aucun portrait » pour un fichier parfaitement présent. On accepte
# donc large, et on réduit quand on peut : c'est la page qui souffrirait d'un
# data-URI de plusieurs mégaoctets, pas la lecture.
_FP_AVATAR_MAX = 12 * 1024 * 1024
_FP_AVATAR_COTE = 256


def _fp_avatar_data_uri(chemin: str) -> str:
    """Fichier image → data-URI, "" s'il est illisible ou démesuré."""
    try:
        taille = os.path.getsize(chemin)
        if taille > _FP_AVATAR_MAX:
            logging.info("[AVATAR] %s ignoré : %d Mo", chemin, taille // 1048576)
            return ""
        with open(chemin, "rb") as f:
            data = f.read()
    except Exception as e:
        logging.info("[AVATAR] lecture de %s : %s", chemin, e)
        return ""
    ext = os.path.splitext(chemin)[1].lower().lstrip(".") or "png"
    mime = {"jpg": "jpeg", "svg": "svg+xml"}.get(ext, ext)
    if len(data) > 200 * 1024 and ext != "svg":
        reduit = _image_reduire(data, _FP_AVATAR_COTE)
        if reduit:
            data, mime = reduit, "jpeg"
    return "data:image/%s;base64,%s" % (mime, base64.b64encode(data).decode())


def _image_reduire(data: bytes, cote: int):
    """Réduit une image à `cote` pixels de large. None si Pillow est absent.

    Sans Pillow, on renvoie None et l'appelant sert l'original : mieux vaut une
    image lourde qu'aucune image. C'est une optimisation, pas une condition."""
    try:
        from PIL import Image          # optionnel : absent sur bien des serveurs
    except Exception:
        return None
    try:
        import io as _io
        img = Image.open(_io.BytesIO(data))
        img.thumbnail((cote, cote))
        if img.mode not in ("RGB", "L"):
            img = img.convert("RGB")
        sortie = _io.BytesIO()
        img.save(sortie, format="JPEG", quality=82, optimize=True)
        return sortie.getvalue()
    except Exception as e:
        logging.info("[AVATAR] réduction impossible : %s", e)
        return None


def fp_user_avatar(username: str) -> dict:
    """Portrait d'un compte du panneau, si FastPanel en stocke un.

    Toutes les versions n'en gardent pas, et la colonne ne porte pas le même
    nom partout. On cherche ce qui existe plutôt que de supposer un schéma ;
    à défaut, l'appelant se rabattra sur les initiales — une image inventée
    serait pire que pas d'image."""
    u = (username or "").strip()
    if not u:
        return {"ok": False, "reason": "utilisateur requis"}
    cols = _fp_db_colonnes("panel_account")
    # D'abord les fichiers : c'est là que cette version les range, sans rien en
    # dire dans sa base. Chercher une colonne d'abord concluait « pas de
    # portrait » alors que l'image était sur le disque.
    uid = ""
    if "id" in cols:
        for r in _fp_db_query("SELECT id FROM panel_account WHERE username=? LIMIT 1", (u,)):
            if r and r[0] is not None:
                uid = str(r[0])
    chemin = _fp_avatar_fichier(uid, u)
    if chemin:
        uri = _fp_avatar_data_uri(chemin)
        if uri:
            return {"ok": True, "username": u, "url": uri, "source": "fichier",
                    "chemin": chemin}
    dispo = [c for c in _FP_AVATAR_COLS if c in cols]
    if not dispo:
        return {"ok": False, "sans_colonne": True,
                "reason": "aucun portrait dans %s pour ce compte, et cette version "
                          "de FastPanel n'en stocke pas en base"
                          % (_FP_AVATAR_DIRS[0])}
    lignes = _fp_db_query("SELECT %s FROM panel_account WHERE username=? LIMIT 1"
                          % ", ".join('"%s"' % c for c in dispo), (u,))
    if not lignes:
        return {"ok": False, "reason": "compte inconnu du panneau"}
    for valeur in lignes[0]:
        v = str(valeur or "").strip()
        if not v:
            continue
        if v.startswith("data:") or v.startswith("http://") or v.startswith("https://"):
            return {"ok": True, "username": u, "url": v}
        # Chemin de fichier : on le sert en data-URI, comme les vignettes de
        # sites — une balise <img> ne sait pas porter le jeton de session.
        chemin = v if os.path.isabs(v) else os.path.join(
            "/usr/local/fastpanel2/web/public", v.lstrip("/"))
        reel = os.path.realpath(chemin)
        if not reel.startswith("/usr/local/fastpanel"):
            continue
        try:
            if os.path.getsize(reel) > 512 * 1024:
                continue
            with open(reel, "rb") as f:
                data = f.read()
        except Exception:
            continue
        ext = os.path.splitext(reel)[1].lower().lstrip(".") or "png"
        return {"ok": True, "username": u,
                "url": "data:image/%s;base64,%s"
                       % ("jpeg" if ext in ("jpg", "jpeg") else ext,
                          base64.b64encode(data).decode())}
    return {"ok": False, "reason": "aucun portrait enregistré pour ce compte"}


def fp_user_ssh(username: str) -> dict:
    """Clés SSH autorisées d'un compte du panneau.

    Une clé SSH vaut un accès shell : savoir combien il y en a, et lesquelles,
    relève de la même hygiène que surveiller les mots de passe. L'interface n'en
    disait rien."""
    u = (username or "").strip()
    if not u:
        return {"ok": False, "reason": "utilisateur requis"}
    uid = ""
    if "id" in _fp_db_colonnes("panel_account"):
        for r in _fp_db_query("SELECT id FROM panel_account WHERE username=? LIMIT 1", (u,)):
            if r and r[0] is not None:
                uid = str(r[0])
    if not uid:
        return {"ok": False, "reason": "compte inconnu du panneau"}
    r = fp_api_call("GET", "/api/sshd/%s/auth_keys" % uid)
    if not r.get("ok"):
        return {"ok": False, "reason": r.get("reason") or "clés illisibles"}
    d = r.get("data")
    if isinstance(d, dict):
        d = d.get("data") if isinstance(d.get("data"), list) else [d]
    return {"ok": True, "username": u,
            "keys": [x for x in (d or []) if isinstance(x, dict)]}

_SVC_VER_CACHE = {"t": 0.0, "paquets": {}}
# Nom d'unité systemd → paquet Debian, quand les deux diffèrent. Ailleurs, le
# nom du service est aussi celui du paquet et la correspondance suffit.
_SVC_PAQUETS = {
    "mysql": ("mysql-server", "mariadb-server", "default-mysql-server"),
    "mariadb": ("mariadb-server",),
    "named": ("bind9",), "pdns": ("pdns-server",), "powerdns": ("pdns-server",),
    "httpd": ("apache2",), "apache2": ("apache2",),
    "php-fpm": ("php-fpm",), "exim4": ("exim4-daemon-heavy", "exim4"),
    "postgresql": ("postgresql",), "redis-server": ("redis-server",),
    "sshd": ("openssh-server",), "ssh": ("openssh-server",),
    "fastpanel2": ("fastpanel2",), "proftpd": ("proftpd-basic", "proftpd-core"),
    "clamav-daemon": ("clamav-daemon",), "spamassassin": ("spamassassin",),
}


def _svc_versions() -> dict:
    """Version installée de chaque service, depuis le gestionnaire de paquets.

    `systemctl` ne connaît pas les versions et interroger chaque binaire ferait
    autant de processus qu'il y a de services. `dpkg-query` les donne toutes en
    un appel — et c'est la version réellement installée, pas celle qu'un
    binaire veut bien annoncer."""
    if _SVC_VER_CACHE["paquets"] and time.time() - _SVC_VER_CACHE["t"] < 600:
        return _SVC_VER_CACHE["paquets"]
    paquets = {}
    try:
        p = subprocess.run("dpkg-query -W -f='${Package} ${Version}\\n'",
                           shell=True, capture_output=True, text=True, timeout=20)
        for ligne in (p.stdout or "").splitlines():
            bout = ligne.strip().strip("'").split(None, 1)
            if len(bout) == 2:
                # « 1:8.0.43-0ubuntu0.24.04.1 » : l'époque et la révision
                # Debian n'apprennent rien à personne.
                v = re.sub(r"^\d+:", "", bout[1])
                v = re.split(r"[-+~]", v)[0]
                paquets[bout[0]] = v
    except Exception as e:
        logging.info("[SERVICES] versions dpkg : %s", e)
    _SVC_VER_CACHE.update({"t": time.time(), "paquets": paquets})
    return paquets


def _svc_version(nom: str) -> str:
    """Version d'un service, "" si on ne sait pas — jamais une valeur inventée."""
    court = (nom or "").strip().lower().replace(".service", "")
    if not court:
        return ""
    paquets = _svc_versions()
    for cle in (_SVC_PAQUETS.get(court) or ()) + (court,):
        if cle in paquets:
            return paquets[cle]
    # Dernier essai : un paquet dont le nom commence par celui du service
    # (php8.3-fpm pour php-fpm, mariadb-server-10.11 pour mariadb…).
    base = court.split("-")[0]
    proches = sorted(k for k in paquets if k.startswith(base) and len(k) <= len(base) + 12)
    return paquets[proches[0]] if proches else ""


def get_fp_services():
    d = get_entity_from_socket("fastpanel_services")
    src = "collecteur"
    if not d:
        d = query_db("SELECT name,status,version FROM fastpanel_services ORDER BY name")
        src = "table locale"
    # Même raison que get_fp_php (2026-09-05) : « collecteur tombé » et
    # « aucun service » ne doivent pas se ressembler.
    for s in (d or []):
        if isinstance(s, dict):
            s.setdefault("source", src)
    # Le collecteur laisse la version vide : la colonne affichait « – » pour
    # tout le monde. On la complète ici plutôt que d'attendre une refonte du
    # collecteur, et un service sans version reste vide plutôt que faux.
    for s in (d or []):
        if isinstance(s, dict) and not str(s.get("version") or "").strip():
            v = _svc_version(str(s.get("name") or ""))
            if v:
                s["version"] = v
    return d


# ══════════════════════════════════════════════════════════════════════════
# ACTIONS SUR LES SERVICES
# L'onglet ne savait que lire. Constater qu'un service est tombé sans pouvoir
# le relever oblige à ouvrir un terminal à côté — la supervision et l'action
# se séparaient exactement là où elles devraient se rejoindre.
# ══════════════════════════════════════════════════════════════════════════
_SVC_ACTIONS = {
    "status":  ("systemctl status %s --no-pager -l", False),
    "start":   ("systemctl start %s", True),
    "stop":    ("systemctl stop %s", True),
    "restart": ("systemctl restart %s", True),
    "reload":  ("systemctl reload %s", True),
    "enable":  ("systemctl enable %s", True),
    "disable": ("systemctl disable %s", True),
    "logs":    ("journalctl -u %s -n 80 --no-pager", False),
}
# Couper ceux-là, c'est se couper soi-même : Cassandra parle au monde par nginx
# et vit dans son propre service. On les protège d'un arrêt distrait.
_SVC_VITAUX = {"nginx", "ssh", "sshd", "cassandra", "fastpanel2", "systemd-journald"}
_SVC_NOM_RE = re.compile(r"^[A-Za-z0-9@._\-]{1,64}$")


def fp_service_action(name: str, action: str, confirm: bool = False) -> dict:
    """Agit sur un service systemd. `confirm` obligatoire pour tout ce qui modifie."""
    nom = (name or "").strip()
    act = (action or "").strip().lower()
    if not _SVC_NOM_RE.match(nom):
        # Le nom part dans une commande shell : tout ce qui n'est pas un nom
        # d'unité plausible est refusé plutôt qu'échappé.
        return {"ok": False, "reason": "nom de service invalide"}
    if act not in _SVC_ACTIONS:
        return {"ok": False, "reason": "action inconnue (%s)" % ", ".join(sorted(_SVC_ACTIONS))}
    gabarit, modifie = _SVC_ACTIONS[act]
    if modifie and not confirm:
        return {"ok": False, "needs_confirm": True,
                "reason": "« %s » sur %s modifie l'état du serveur." % (act, nom)}
    if modifie and nom.replace(".service", "") in _SVC_VITAUX and act in ("stop", "disable"):
        return {"ok": False, "vital": True,
                "reason": "%s est vital pour l'accès à ce serveur : arrêt refusé depuis "
                          "l'interface. À faire en console, en connaissance de cause." % nom}
    cmd = gabarit % nom
    t0 = time.time()
    try:
        p = subprocess.run(cmd, shell=True, capture_output=True, text=True, timeout=45)
        sortie = ((p.stdout or "") + (p.stderr or "")).strip()[:6000]
        code = p.returncode
    except subprocess.TimeoutExpired:
        return {"ok": False, "reason": "délai dépassé (45 s) — le service ne répond pas"}
    except Exception as e:
        return {"ok": False, "reason": str(e)}
    reussi = code == 0 or act in ("status", "logs")
    if not reussi and modifie:
        # systemctl a échoué : le panneau gère peut-être ce service sous un
        # autre nom d'unité. Les garde-fous ci-dessus ont déjà tranché sur les
        # services vitaux, donc ce second essai ne contourne rien.
        api = fp_service_action_api(nom, act)
        if api.get("ok"):
            api["duration_ms"] = int((time.time() - t0) * 1000)
            api["state"] = fp_service_state(nom)
            api["output"] = "%s\n(systemctl a échoué : %s)" % (
                api.get("output", ""), sortie[:200] or "code %s" % code)
            return api
    etat = fp_service_state(nom) if modifie else {}
    return {"ok": reussi, "action": act, "service": nom,
            "exit_code": code, "output": sortie,
            "duration_ms": int((time.time() - t0) * 1000), "state": etat}


_FP_SVC_API = {"start": "start", "stop": "stop", "restart": "restart",
               "enable": "enable", "disable": "disable"}
_FP_SVC_CACHE = {"t": 0.0, "index": {}}


def _fp_svc_index(brut) -> dict:
    """Index nom → {id, name, state, aliases} des services du panneau, UN PAR
    IDENTIFIANT.

    Le panneau décrit exim sous deux clés (`name` = exim, `service` = exim4) :
    indexer chaque clé faisait apparaître deux services pour le même id 33, et
    l'onglet en comptait un de trop (2026-09-05). Le premier nom fait foi ; les
    autres restent en `aliases` pour que « exim4 » trouve encore sa fiche."""
    index, vus = {}, set()
    for s in (brut or []):
        if not isinstance(s, dict):
            continue
        ident = s.get("id")
        if ident is None or str(ident) in vus:
            continue
        noms = []
        for cle in ("name", "service", "unit", "title"):
            nom = str(s.get(cle) or "").strip()
            court = nom.lower().replace(".service", "")
            if nom and court not in [n.lower().replace(".service", "") for n in noms]:
                noms.append(nom)
        if not noms:
            continue
        cle_idx = noms[0].lower().replace(".service", "")
        if cle_idx in index:
            continue
        vus.add(str(ident))
        index[cle_idx] = {"id": str(ident), "name": noms[0],
                          "state": str(s.get("state") or s.get("status") or ""),
                          "aliases": [n.lower().replace(".service", "") for n in noms[1:]]}
    return index


def fp_services_panneau(rafraichir: bool = False) -> dict:
    """Services tels que FastPanel les connaît, avec leur identifiant.

    `systemctl` voit les unités du système ; le panneau, lui, tient sa propre
    liste avec des identifiants numériques — les seuls que son API accepte. Les
    deux vues ne se recouvrent pas exactement, d'où cet index séparé."""
    if not rafraichir and _FP_SVC_CACHE["index"] and \
            time.time() - _FP_SVC_CACHE["t"] < 120:
        return {"ok": True, "services": _FP_SVC_CACHE["index"], "cache": True}
    r = fp_api_call("GET", "/api/services")
    if not r.get("ok"):
        return {"ok": False, "reason": r.get("reason") or "liste indisponible",
                "services": {}}
    brut = r.get("data")
    if isinstance(brut, dict):
        brut = brut.get("data") if isinstance(brut.get("data"), list) else [brut]
    index = _fp_svc_index(brut)
    _FP_SVC_CACHE.update({"t": time.time(), "index": index})
    return {"ok": True, "services": index}


def fp_service_action_api(name: str, action: str) -> dict:
    """Agit sur un service PAR L'API du panneau plutôt que par systemctl.

    Utile quand `systemctl` échoue ou que l'unité porte un autre nom côté
    système : le panneau sait ce qu'il gère. Il reste second — systemctl est
    direct, et son échec est plus lisible."""
    act = (action or "").strip().lower()
    if act not in _FP_SVC_API:
        return {"ok": False, "reason": "action non exposée par l'API du panneau"}
    court = (name or "").strip().lower().replace(".service", "")
    idx = fp_services_panneau().get("services") or {}
    fiche = idx.get(court)
    if not fiche:
        # « exim4 » n'est plus une clé de l'index (un service par identifiant,
        # 2026-09-05) mais reste un alias de « exim ».
        fiche = next((f for f in idx.values() if court in (f.get("aliases") or [])), None)
    if not fiche:
        return {"ok": False, "reason": "service « %s » inconnu du panneau" % name}
    r = fp_api_call("PUT", "/api/services/%s/%s" % (fiche["id"], _FP_SVC_API[act]), {})
    if not r.get("ok"):
        return {"ok": False, "reason": r.get("reason") or "refus de l'API",
                "detail": r.get("brut", "")}
    _FP_SVC_CACHE["t"] = 0.0            # l'état vient de changer : cache périmé
    return {"ok": True, "action": act, "service": fiche["name"], "via": "api",
            "output": "%s : %s demandé au panneau." % (fiche["name"], act)}


def fp_service_state(name: str) -> dict:
    """État courant d'un service, en trois mots plutôt qu'en pavé de journal."""
    nom = (name or "").strip()
    if not _SVC_NOM_RE.match(nom):
        return {}
    try:
        p = subprocess.run(
            "systemctl show %s --property=ActiveState,SubState,UnitFileState,ExecMainStartTimestamp"
            % nom, shell=True, capture_output=True, text=True, timeout=10)
        d = {}
        for ligne in (p.stdout or "").splitlines():
            if "=" in ligne:
                k, _, v = ligne.partition("=")
                d[k.strip()] = v.strip()
        return {"active": d.get("ActiveState", ""), "sub": d.get("SubState", ""),
                "enabled": d.get("UnitFileState", ""), "since": d.get("ExecMainStartTimestamp", "")}
    except Exception as e:
        logging.info("[SERVICES] état de %s : %s", nom, e)
        return {}


def fp_service_diagnose(name: str) -> dict:
    """Contrôle : état, dernières lignes de journal, et vérification de la
    configuration quand l'outil existe. Réunit ce qu'on irait chercher à la main
    dans trois commandes différentes."""
    nom = (name or "").strip()
    if not _SVC_NOM_RE.match(nom):
        return {"ok": False, "reason": "nom de service invalide"}
    etat = fp_service_state(nom)
    jour = fp_service_action(nom, "logs")
    base = nom.replace(".service", "")
    verif = {}
    controles = {"nginx": "nginx -t", "apache2": "apache2ctl configtest",
                 "httpd": "httpd -t", "postfix": "postfix check",
                 "named": "named-checkconf", "bind9": "named-checkconf",
                 "sshd": "sshd -t", "ssh": "sshd -t"}
    if base in controles:
        try:
            p = subprocess.run(controles[base], shell=True, capture_output=True,
                               text=True, timeout=20)
            verif = {"cmd": controles[base], "exit_code": p.returncode,
                     "output": ((p.stdout or "") + (p.stderr or "")).strip()[:2000]}
        except Exception as e:
            verif = {"cmd": controles[base], "error": str(e)}
    erreurs = [l for l in (jour.get("output", "") or "").splitlines()
               if re.search(r"\b(error|failed|fatal|refused|denied)\b", l, re.I)][-12:]
    return {"ok": True, "service": nom, "state": etat, "config_check": verif,
            "recent_errors": erreurs, "logs": jour.get("output", "")}


# ── SSL : agir, pas seulement constater ────────────────────────────────────
_SSL_DOM_RE = re.compile(r"^[A-Za-z0-9]([A-Za-z0-9\-]{0,61}[A-Za-z0-9])?(\.[A-Za-z0-9\-]{1,63})+$")


def _fp_ssl_jours(d):
    """Jours SSL restants d'un domaine, ou None quand personne ne les a lus."""
    v = d.get("ssl_days_left") if isinstance(d, dict) else None
    try:
        return None if v in (None, "") else int(v)
    except Exception:
        return None


def fp_ssl_overview(filtre_domaines=None) -> dict:
    """État SSL du parc, croisé entre les sites déclarés et les certificats
    réellement observés. Les compteurs de l'onglet en découlent.

    `filtre_domaines` : les domaines d'un compte ordinaire ; None = tout le parc.

    QUATRE ÉTATS, PAS TROIS (2026-09-05). Un domaine à zéro jour était classé
    « sans certificat » même quand personne ne l'avait regardé : inconnu du
    collecteur et au-delà du plafond de sondes, il gardait le zéro de repli de
    sa source, et l'audit affichait « pas de certificat » sur des sites servis
    en HTTPS. « Sans » n'est dit que sur constat de la sonde ; le reste est
    « inconnu », et le compteur le montre à part."""
    try:
        domaines = get_fp_domains() or []
    except Exception as e:
        return {"ok": False, "reason": str(e)}
    domaines = [d for d in domaines if isinstance(d, dict)]
    if filtre_domaines is not None:
        _miens = set(filtre_domaines)
        domaines = [d for d in domaines
                    if _fp_appartient(str(d.get("domain") or ""), _miens)]
    total = len(domaines)
    actifs = [d for d in domaines if (_fp_ssl_jours(d) or 0) > 0]
    proches = [d for d in actifs if _fp_ssl_jours(d) <= 30]
    sans = [d for d in domaines if _fp_ssl_jours(d) is not None
            and _fp_ssl_jours(d) <= 0 and d.get("ssl_source") == "sonde"]
    inconnus = [d for d in domaines if (_fp_ssl_jours(d) or 0) <= 0
                and d.get("ssl_source") != "sonde"]
    return {"ok": True, "total": total, "ssl_active": len(actifs),
            "ssl_soon": len(proches), "ssl_missing": len(sans),
            "ssl_inconnu": len(inconnus),
            "soon": [{"domain": d.get("domain"), "days_left": d.get("ssl_days_left"),
                      "expiry": d.get("ssl_expiry", "")} for d in
                     sorted(proches, key=lambda x: _fp_ssl_jours(x) or 0)],
            "missing": [d.get("domain") for d in sans],
            "inconnu": [d.get("domain") for d in inconnus]}


def _fp_ssl_renouveler_panneau(dom: str, staging: bool = False) -> dict:
    """Renouvelle un certificat Let's Encrypt par l'API du panneau (PUT /certificates/{id}/renew/external), puis PROUVE
    le renouvellement : la date d'émission du certificat doit avoir changé. Sans cette preuve, le geste n'est pas réussi."""
    if staging:
        return {"ok": False, "reason": "le mode essai n'existe pas via le panneau"}
    def _liste():
        r = fp_api_call("GET", "/api/certificates")
        d = r.get("data") if r.get("ok") else None
        d = d.get("data") if isinstance(d, dict) else d
        return d if isinstance(d, list) else None
    items = _liste()
    if items is None:
        return {"ok": False, "reason": "certbot absent et la liste des certificats du panneau est illisible"}
    cert = next((x for x in items if str(x.get("common_name") or "").lower() == dom
                 or dom in str(x.get("alternative_name") or "").lower().replace(",", " ").split()), None)
    if not cert:
        return {"ok": False, "reason": "aucun certificat du panneau pour %s" % dom}
    avant = str(cert.get("issued_at") or "")
    r = fp_api_call("PUT", "/api/certificates/%s/renew/external" % int(cert["id"]), {}, timeout=90)
    if not r.get("ok"):
        return {"ok": False, "reason": "le panneau a refusé le renouvellement : %s" % str(r.get("reason") or r.get("status"))[:160]}
    for _ in range(12):
        time.sleep(5)
        nouv = next((x for x in (_liste() or []) if x.get("id") == cert.get("id")), None) or {}
        if str(nouv.get("issued_at") or "") != avant:
            return {"ok": True, "domain": dom, "output": "renouvelé par le panneau, valable jusqu'au %s" % str(nouv.get("expired_at") or "?")[:10]}
    return {"ok": False, "domain": dom, "reason": "le panneau a accepté la demande mais la date d'émission n'a pas changé après 60 s"}


def fp_ssl_issue(domain: str, confirm: bool = False, staging: bool = False) -> dict:
    """Émet ou renouvelle un certificat Let's Encrypt pour un domaine.

    Sollicite une autorité de certification externe, qui applique des quotas
    stricts : cinq échecs de suite sur un domaine mal configuré le bloquent
    pour une semaine. D'où la confirmation, et le mode « essai » qui vise
    l'environnement de test de Let's Encrypt sans consommer le quota réel."""
    dom = _norm_domain(domain)
    if not _SSL_DOM_RE.match(dom or ""):
        return {"ok": False, "reason": "nom de domaine invalide"}
    if not confirm:
        return {"ok": False, "needs_confirm": True,
                "reason": "Demander un certificat pour %s contacte Let's Encrypt, "
                          "qui limite le nombre de tentatives par domaine." % dom}
    import shutil as _sh
    if not _sh.which("certbot"):
        # Pas de certbot : les certificats sont ceux du panneau (Let's Encrypt émis par FastPanel). On lui demande.
        return _fp_ssl_renouveler_panneau(dom, staging)
    cmd = ("certbot --nginx -d %s -d www.%s --non-interactive --agree-tos "
           "--keep-until-expiring --redirect%s" % (dom, dom, " --staging" if staging else ""))
    try:
        p = subprocess.run(cmd, shell=True, capture_output=True, text=True, timeout=180)
        sortie = ((p.stdout or "") + (p.stderr or "")).strip()[:6000]
    except subprocess.TimeoutExpired:
        return {"ok": False, "reason": "délai dépassé (180 s) — certbot n'a pas rendu la main"}
    except Exception as e:
        return {"ok": False, "reason": str(e)}
    return {"ok": p.returncode == 0, "domain": dom, "staging": bool(staging),
            "exit_code": p.returncode, "output": sortie}


def fp_ssl_check(domain: str) -> dict:
    """Interroge le certificat réellement présenté par le serveur, en direct.

    La base peut affirmer n'importe quoi : seul le certificat servi sur le port
    443 dit ce que voit un visiteur."""
    dom = _norm_domain(domain)
    if not _SSL_DOM_RE.match(dom or ""):
        return {"ok": False, "reason": "nom de domaine invalide"}
    try:
        import ssl as _ssl
        ctx = _ssl.create_default_context()
        with socket.create_connection((dom, 443), timeout=8) as brut:
            with ctx.wrap_socket(brut, server_hostname=dom) as tls:
                cert = tls.getpeercert()
        exp = cert.get("notAfter", "")
        reste = None
        if exp:
            fin = datetime.strptime(exp, "%b %d %H:%M:%S %Y %Z")
            reste = (fin - datetime.utcnow()).days
        emetteur = ""
        for champ in (cert.get("issuer") or ()):
            for k, v in champ:
                if k == "organizationName":
                    emetteur = v
        noms = [v for k, v in (cert.get("subjectAltName") or ()) if k == "DNS"]
        return {"ok": True, "domain": dom, "expires": exp, "days_left": reste,
                "issuer": emetteur, "names": noms}
    except Exception as e:
        # Un échec est une information : pas de HTTPS, mauvais nom, port fermé.
        return {"ok": False, "domain": dom, "reason": str(e)}


def fp_domain_attach(domain: str, project_id="", project_name: str = "",
                     note: str = "", acteur: str = "") -> dict:
    """Rattache un domaine à un projet, et/ou y ajoute une note.

    La fiche disait « Aucun projet ne porte ce domaine » sans offrir de le
    corriger : il fallait quitter l'onglet, retrouver le projet, saisir le
    domaine à la main. Constater un manque et pouvoir le combler au même
    endroit, c'est toute la différence entre une fiche et un tableau de bord."""
    dom = _norm_domain(domain)
    if not dom:
        return {"ok": False, "reason": "domaine requis"}
    pid = str(project_id or "").strip()
    nom = (project_name or "").strip()
    texte = (note or "").strip()
    if not pid and not nom and not texte:
        return {"ok": False, "reason": "rien à faire : ni projet ni note"}
    cible = None
    try:
        projets = pj_projets() or []
    except Exception as e:
        return {"ok": False, "reason": "projets illisibles : %s" % str(e)[:120]}
    if pid:
        cible = next((p for p in projets if str(p.get("id")) == pid), None)
        if not cible:
            return {"ok": False, "reason": "projet %s introuvable" % pid}
    elif nom:
        cible = next((p for p in projets
                      if str(p.get("name", "")).strip().lower() == nom.lower()), None)
    else:
        # Ni identifiant ni nom : la note va au projet qui porte déjà ce domaine.
        cible = next((p for p in projets
                      if _norm_domain(p.get("domain", "")) == dom), None)
        if not cible:
            return {"ok": False, "reason": "aucun projet ne porte %s — choisissez-en "
                                           "un ou donnez un nom pour le créer" % dom}
    try:
        r = pj_projet_save(
            pid=(cible.get("id") if cible else None),
            name=nom or (cible.get("name") if cible else dom),
            domain=dom, append_note=texte or None)
    except Exception as e:
        return {"ok": False, "reason": str(e)[:200]}
    if not r or not r.get("ok"):
        return {"ok": False, "reason": (r or {}).get("reason") or "enregistrement refusé"}
    try:
        log_admin_action(acteur or "", "fp_domain_attach", "OK",
                         "domain=%s projet=%s note=%s"
                         % (dom, r.get("id") or (cible or {}).get("id"), bool(texte)))
    except Exception as e:
        logging.debug("[AUDIT] %s", e)
    cree = not cible
    return {"ok": True, "domain": dom, "project_id": r.get("id") or (cible or {}).get("id"),
            "created": cree,
            "output": ("Projet « %s » créé et rattaché à %s." if cree
                       else "%s rattaché au projet « %s ».")
                      % ((nom or dom, dom) if cree
                         else (dom, nom or (cible or {}).get("name", "")))
                      + (" Note ajoutée." if texte else "")}


def fp_domain_context(domain: str) -> dict:
    """Tout ce que Cassandra sait déjà d'un domaine, réuni.

    L'onglet FastPanel vivait en vase clos : il listait des domaines sans jamais
    dire à quel projet ils appartiennent, qui en répond, quelles tâches sont
    ouvertes dessus ni quelles sauvegardes le couvrent. L'information existait —
    répartie dans quatre écrans qu'il fallait ouvrir un par un."""
    dom = _norm_domain(domain)
    if not dom:
        return {"ok": False, "reason": "domaine requis"}
    ctx = {"ok": True, "domain": dom}
    try:
        ctx["site"] = next((d for d in (get_fp_domains() or [])
                            if _norm_domain(d.get("domain", "")) == dom), {})
    except Exception as e:
        logging.info("[FP-CTX] site : %s", e)
        ctx["site"] = {}
    # Projet portant ce domaine
    projet = None
    try:
        projet = next((p for p in (pj_projets() or [])
                       if _norm_domain(p.get("domain", "")) == dom), None)
    except Exception as e:
        logging.info("[FP-CTX] projet : %s", e)
    ctx["project"] = projet
    # Qui prévenir
    try:
        ctx["contacts"] = contacts_of("domain", dom) or (
            contacts_of("project", str(projet["id"])) if projet else [])
    except Exception as e:
        logging.info("[FP-CTX] contacts : %s", e)
        ctx["contacts"] = []
    # Tâches ouvertes du projet
    try:
        ctx["tasks"] = [t for t in (itare_task_list(project_id=projet["id"]) or [])
                        if not t.get("done")][:10] if projet else []
    except Exception as e:
        logging.info("[FP-CTX] tâches : %s", e)
        ctx["tasks"] = []
    # Tâches planifiées qui mentionnent ce domaine
    try:
        ctx["crons"] = [j for j in (cron_unified_list() or [])
                        if dom in (j.get("command", "") or "").lower()][:10]
    except Exception as e:
        logging.info("[FP-CTX] crons : %s", e)
        ctx["crons"] = []
    # Dernières sauvegardes le concernant — le moteur v2 copie PAR COMPTE (20-09) : les copies du compte
    # propriétaire du site le couvrent ; le nom du domaine reste un repli pour l'ancien moteur.
    try:
        _prop = ""
        for _r in _fp_db_query("SELECT COALESCE(p.username,'') FROM site s LEFT JOIN panel_account p ON s.owner_id = p.id WHERE lower(s.domain) = ?", (dom,)):
            _prop = str((_r or [""])[0] or "").strip().lower()
        ctx["backups"] = [b for b in (get_fp_backups() or [])
                          if (isinstance(b, dict) and _prop and str(b.get("compte") or "").lower() == _prop)
                          or dom in str(b).lower()][:5]
    except Exception as e:
        logging.info("[FP-CTX] sauvegardes : %s", e)
        ctx["backups"] = []
    # Certificat réellement servi
    try:
        ctx["ssl_live"] = fp_ssl_check(dom)
    except Exception as e:
        ctx["ssl_live"] = {"ok": False, "reason": str(e)}
    # Fils de discussion rattachés au projet
    try:
        ctx["mail_threads"] = (mail_project_threads(projet["id"]).get("threads", [])
                               if projet else [])
    except Exception as e:
        logging.info("[FP-CTX] fils : %s", e)
        ctx["mail_threads"] = []
    # La liste des projets sert la saisie assistée du rattachement : proposer
    # les noms existants évite d'en créer un doublon par faute de frappe.
    try:
        ctx["projects_all"] = [{"id": p.get("id"), "name": p.get("name", "")}
                               for p in (pj_projets() or [])
                               if not p.get("archived")][:200]
    except Exception as e:
        logging.info("[FP-CTX] liste projets : %s", e)
        ctx["projects_all"] = []
    return ctx


# ══════════════════════════════════════════════════════════════════════════
# SURVEILLANCE DE L'INFRASTRUCTURE
# Même principe que les tâches planifiées muettes : ce qui ne se produit pas
# ne déclenche rien tout seul. Une sauvegarde qui a cessé de tourner, un service
# vital qui s'est arrêté pendant la nuit, un PHP dont le support est terminé —
# aucun de ces trois faits ne génère d'erreur. Il faut aller les chercher.
# ══════════════════════════════════════════════════════════════════════════

def fp_db_autolink() -> dict:
    """Rattache les bases de données aux projets quand le nom les désigne.

    Une base s'appelle presque toujours d'après le site qu'elle sert
    (`exemple_wp`, `proche_prod`). Quand la racine du domaine du projet
    apparaît dans le nom, l'appariement est sûr ; sinon on ne devine pas."""
    _itare_projects_migrate()
    try:
        bases = get_fp_databases() or []
        projets = [p for p in (pj_projets() or []) if not p.get("archived")]
    except Exception as e:
        return {"ok": False, "reason": str(e), "linked": 0}
    poses = 0
    for b in bases:
        nom = str(b.get("name", "") or "").lower()
        if not nom:
            continue
        for p in projets:
            dom = _norm_domain(p.get("domain") or "")
            racine = dom.split(".")[0] if dom else (p.get("name") or "").strip().lower()
            racine = re.sub(r"[^a-z0-9]", "", racine)
            if len(racine) < 4 or racine not in re.sub(r"[^a-z0-9]", "", nom):
                continue
            r = itare_project_link(p["id"], "database", b.get("name", ""), b.get("name", ""))
            if r.get("ok"):
                poses += 1
            break
    return {"ok": True, "linked": poses, "databases": len(bases)}


_INFRA_SEEN = [False]


def _infra_migrate():
    if _INFRA_SEEN[0]:
        return
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        conn.execute("CREATE TABLE IF NOT EXISTS service_state_seen ("
                     "name TEXT PRIMARY KEY, active TEXT, enabled TEXT, "
                     "ts TEXT DEFAULT (datetime('now')))")
        conn.execute("CREATE TABLE IF NOT EXISTS scan_state_seen ("
                     "domain TEXT PRIMARY KEY, status TEXT, report TEXT, "
                     "scanned_at TEXT, ts TEXT DEFAULT (datetime('now')))")
        conn.execute("CREATE TABLE IF NOT EXISTS user_sites_seen ("
                     "email TEXT PRIMARY KEY, fp_account TEXT, domains TEXT, "
                     "ts TEXT DEFAULT (datetime('now')))")
        conn.commit(); conn.close()
        _INFRA_SEEN[0] = True
    except Exception as e:
        logging.warning("[INFRA] migration : %s", e)


def fp_liens_watch() -> dict:
    """Signale ce qu'un compte adossé vient de gagner ou de perdre comme sites.

    Le rapatriement est déjà automatique — `user_sites()` recalcule l'union à
    chaque lecture. Mais tant que personne n'ouvre « Mes sites », un domaine
    apparu la nuit reste inconnu. Un rapatriement silencieux n'est pas un
    rapatriement : il faut que ça se sache."""
    if not _mem_cfg("fp_link_watch_enabled", True):
        return {"ok": True, "disabled": True, "changed": 0}
    _infra_migrate()
    try:
        comptes = load_users() or {}
    except Exception as e:
        return {"ok": False, "reason": str(e), "changed": 0}
    suivis = {}
    for email in comptes:
        d = user_sites_detail(email)
        if d.get("fp_account"):
            suivis[email] = d
    changements = []
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        connus = {r[0]: (r[1], r[2]) for r in
                  conn.execute("SELECT email, fp_account, domains FROM user_sites_seen")}
        for email, d in suivis.items():
            herites = sorted(d["herites"])
            texte = "\n".join(herites)
            avant = connus.get(email)
            conn.execute("INSERT OR REPLACE INTO user_sites_seen "
                         "(email, fp_account, domains, ts) VALUES (?,?,?,datetime('now'))",
                         (email, d["fp_account"], texte))
            # Premier passage : on enregistre sans alerter, sinon le parc entier
            # serait annoncé comme « nouveau » le jour de la mise en service.
            if avant is None or avant[0] != d["fp_account"]:
                continue
            precedents = set((avant[1] or "").split("\n")) - {""}
            gagnes = [x for x in herites if x not in precedents]
            perdus = [x for x in precedents if x not in herites]
            if gagnes or perdus:
                changements.append({"user": email, "fp_account": d["fp_account"],
                                    "gagnes": gagnes, "perdus": perdus})
        # Un compte détaché ou supprimé ne doit pas laisser sa trace derrière lui.
        for email in list(connus):
            if email not in suivis:
                conn.execute("DELETE FROM user_sites_seen WHERE email=?", (email,))
        conn.commit(); conn.close()
    except Exception as e:
        return {"ok": False, "reason": str(e), "changed": 0}
    alertes = 0
    for c in changements:
        cle = "lien:%s:%s:%s" % (c["user"], ",".join(c["gagnes"]), ",".join(c["perdus"]))
        if _cron_seen(cle):
            continue
        try:
            bouts = []
            if c["gagnes"]:
                bouts.append("%d site(s) repris : %s" % (len(c["gagnes"]),
                                                         ", ".join(c["gagnes"][:6])))
            if c["perdus"]:
                bouts.append("%d site(s) retiré(s) : %s" % (len(c["perdus"]),
                                                            ", ".join(c["perdus"][:6])))
            _itare_proactive_add(
                "Sites de %s mis à jour depuis FastPanel" % c["user"],
                "Le compte « %s » a changé de périmètre. %s"
                % (c["fp_account"], " ; ".join(bouts)),
                source="hebergement", nature="evenement", sujet=str(c["user"]),
                cle="hebergement:perimetre:%s" % c["user"])
            alertes += 1
        except Exception as e:
            logging.info("[FP-LIEN] alerte : %s", e)
    # Rappel des rapprochements évidents non appliqués : proposer une fois vaut
    # mieux que laisser un compte sans ses sites parce que personne n'y a pensé.
    try:
        sug = fp_liens_suggeres().get("suggestions") or []
        if sug and not _cron_seen("lien:suggestions:%d" % len(sug)):
            _itare_proactive_add(
                "%d compte(s) Cassandra pourraient être adossés à FastPanel" % len(sug),
                "; ".join("%s → %s (%s)" % (x["user"], x["fp_account"], x["motif"])
                          for x in sug[:4])
                + ". FastPanel → Utilisateurs → Liens Cassandra.",
                source="hebergement", nature="decision", sujet="liens", cle="hebergement:liens")
            alertes += 1
    except Exception as e:
        logging.info("[FP-LIEN] suggestions : %s", e)
    return {"ok": True, "changed": len(changements), "alerts": alertes,
            "watched": len(suivis)}


def fp_scan_watch() -> dict:
    """Signale un site qui vient de passer d'« ok » à « infecté ».

    La section Analyses n'apprend rien tant qu'on ne l'ouvre pas : un site
    signalé infecté y attendait qu'on vienne le lire. Comme pour les services,
    ce qui compte est la TRANSITION — pas la liste des états, qui ne dit pas
    lesquels sont nouveaux."""
    if not _mem_cfg("scan_watch_enabled", True):
        return {"ok": True, "disabled": True, "changed": 0}
    _infra_migrate()
    try:
        scans = get_fp_scans() or []
    except Exception as e:
        return {"ok": False, "reason": str(e), "changed": 0}
    # Un site peut avoir plusieurs rapports : seul le plus récent fait foi, et
    # `get_fp_scans` les rend déjà du plus récent au plus ancien.
    derniers = {}
    for s in scans:
        d = str(s.get("domain") or "")
        if d and d not in derniers:
            derniers[d] = s
    changements = []
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        connus = {r[0]: (r[1], r[2]) for r in
                  conn.execute("SELECT domain, status, scanned_at FROM scan_state_seen")}
        for dom, s in derniers.items():
            etat = str(s.get("status") or "")
            quand = str(s.get("created_at") or "")
            avant = connus.get(dom)
            conn.execute("INSERT OR REPLACE INTO scan_state_seen "
                         "(domain, status, report, scanned_at, ts) "
                         "VALUES (?,?,?,?,datetime('now'))",
                         (dom, etat, str(s.get("report") or ""), quand))
            # Un site inconnu n'est pas un changement : on l'enregistre sans
            # alerter, sinon la première passe préviendrait pour tout le parc.
            if avant and avant[0] and avant[0] != etat:
                changements.append({"domain": dom, "from": avant[0], "to": etat,
                                    "report": str(s.get("report") or ""),
                                    "at": quand})
        conn.commit(); conn.close()
    except Exception as e:
        return {"ok": False, "reason": str(e), "changed": 0}
    alertes = 0
    for c in changements:
        infecte = c["to"] != "ok"
        cle = "scan:%s:%s>%s:%s" % (c["domain"], c["from"], c["to"], c["at"])
        if _cron_seen(cle):
            continue
        try:
            if infecte:
                _itare_proactive_add(
                    "Site signalé infecté : %s" % c["domain"],
                    "L'analyse du %s a trouvé quelque chose. Rapport : %s"
                    % (c["at"] or "jour même", c["report"] or "voir l'onglet FastPanel"),
                    source="site", nature="etat", niveau="critique", sujet=str(c["domain"]),
                    cle="site:infecte:%s" % c["domain"])
                itare_task_from_source("auto-scan", cle,
                                       "Examiner le rapport d'analyse de %s" % c["domain"])
            else:
                notif_resoudre_cle("site:infecte:%s" % c["domain"], par="rétabli",
                                   detail="l'analyse du %s ne signale plus rien" % c["at"])
            # « De nouveau sain » n'est pas une notification : c'est la FERMETURE de l'état, écrite dans la
            # ligne fermée ; le flux de veille garde la trace.
            _itare_proactive_add("Site de nouveau sain : %s" % c["domain"],
                                     "L'analyse du %s ne signale plus rien." % c["at"],
                                     source="veille", nature="rapport")
            alertes += 1
        except Exception as e:
            logging.info("[INFRA] alerte analyse : %s", e)
    return {"ok": True, "changed": len(changements), "alerts": alertes,
            "watched": len(derniers)}


def fp_service_watch() -> dict:
    """Signale un service qui a CHANGÉ d'état sans qu'on le lui demande.

    Une liste de services arrêtés n'apprend rien : sur ce serveur, dix-neuf le
    sont en permanence et c'est normal. Ce qui compte, c'est la TRANSITION — un
    service actif hier et arrêté ce matin."""
    if not _mem_cfg("service_watch_enabled", True):
        return {"ok": True, "disabled": True, "changed": 0}
    _infra_migrate()
    try:
        services = get_fp_services() or []
    except Exception as e:
        return {"ok": False, "reason": str(e), "changed": 0}
    surveilles = {s for s in _SVC_VITAUX}
    for s in services:
        nom = str(s.get("name", "") or "")
        if nom and str(s.get("status", "")).lower().startswith("activ"):
            surveilles.add(nom)
    changements, alertes = [], 0
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        connus = {r[0]: (r[1], r[2]) for r in
                  conn.execute("SELECT name, active, enabled FROM service_state_seen")}
        for nom in sorted(surveilles):
            etat = fp_service_state(nom)
            if not etat or not etat.get("active"):
                continue
            avant = connus.get(nom)
            conn.execute("INSERT OR REPLACE INTO service_state_seen (name, active, enabled, ts) "
                         "VALUES (?,?,?,datetime('now'))",
                         (nom, etat.get("active", ""), etat.get("enabled", "")))
            if avant and avant[0] and avant[0] != etat.get("active"):
                changements.append({"service": nom, "from": avant[0], "to": etat.get("active")})
        conn.commit(); conn.close()
    except Exception as e:
        return {"ok": False, "reason": str(e), "changed": 0}
    for c in changements:
        tombe = c["to"] != "active"
        cle = "svc:%s:%s>%s" % (c["service"], c["from"], c["to"])
        if _cron_seen(cle):
            continue
        try:
            if tombe:
                _itare_proactive_add(
                    "Service arrêté : %s" % c["service"],
                    "Passé de « %s » à « %s » sans action de votre part." % (c["from"], c["to"]),
                    source="systeme", nature="etat", sujet="service:%s" % c["service"],
                    cle="systeme:service:%s" % c["service"], sonde="service:%s" % c["service"])
            else:
                notif_resoudre_cle("systeme:service:%s" % c["service"], par="rétabli",
                                   detail="le service tourne de nouveau (%s)" % c["to"])
                _itare_proactive_add(
                    "Service redémarré : %s" % c["service"],
                    "Passé de « %s » à « %s » sans action de votre part." % (c["from"], c["to"]),
                    source="veille", nature="rapport")
            alertes += 1
            if tombe:
                itare_task_from_source("auto-service", cle,
                                       "Vérifier le service %s (arrêté seul)" % c["service"])
        except Exception as e:
            logging.info("[INFRA] alerte service : %s", e)
    return {"ok": True, "changed": len(changements), "alerts": alertes,
            "watched": len(surveilles)}


def fp_backup_audit(max_age_days: int = 0) -> dict:
    """Sites dont la sauvegarde manque ou date trop.

    Une sauvegarde périmée est plus dangereuse qu'une sauvegarde absente : elle
    donne l'illusion d'être couvert. On regarde donc la DATE, pas l'existence."""
    seuil = int(max_age_days or _mem_cfg("backup_max_age_days", 7) or 7)
    try:
        domaines = get_fp_domains() or []
        sauvegardes = get_fp_backups() or []
    except Exception as e:
        return {"ok": False, "reason": str(e)}
    limite = (_utcnow() - timedelta(days=seuil)).strftime("%Y-%m-%d")
    # LE PROPRIÉTAIRE VIENT DE LA BASE DU PANNEAU (20-09) : la ligne du collecteur portait un compte
    # vide ou faux (colonnes glissées) ; `site.owner_id → panel_account` fait foi, la ligne est un repli.
    proprietaires = {}
    try:
        for r in _fp_db_query("SELECT s.domain, COALESCE(p.username,'') FROM site s "
                              "LEFT JOIN panel_account p ON s.owner_id = p.id"):
            if r and r[0]:
                proprietaires[_norm_domain(str(r[0]))] = str(r[1] or "").strip().lower()
    except Exception as e:
        logging.debug("[FP-AUDIT] propriétaires : %s", e)
    # UN PROXY INVERSE N'A RIEN À SAUVEGARDER ICI (07-10) : son dossier est vide, le service derrière garde ses
    # données ailleurs. Le dorsal principal du site le dit (website_backends.type = 'reverse_proxy').
    proxys = set()
    try:
        for r in _fp_db_query("SELECT s.domain FROM site s JOIN website_backends b ON b.frontend_id = s.id "
                              "WHERE b.main = 1 AND b.type = 'reverse_proxy'"):
            if r and r[0]:
                proxys.add(_norm_domain(str(r[0])))
    except Exception as e:
        logging.debug("[FP-AUDIT] proxys : %s", e)
    sans, vieilles = [], []
    for d in domaines:
        dom = _norm_domain(d.get("domain", ""))
        if not dom or dom in proxys:
            continue
        # LE MOTEUR V2 COPIE PAR COMPTE (20-09) : une copie du compte propriétaire couvre tous ses sites.
        # Chercher le nom du domaine dans la ligne disait « jamais sauvegardé » juste après une copie
        # complète réussie. Le nom reste un repli pour les lignes de l'ancien moteur (une copie par
        # site) ; une copie en erreur ou en cours ne couvre rien.
        compte = proprietaires.get(dom) or str(d.get("user") or "").strip().lower()
        liees = [b for b in sauvegardes if isinstance(b, dict)
                 and str(b.get("status") or "").lower() not in ("error", "failed", "running")
                 and ((compte and str(b.get("compte") or "").strip().lower() == compte) or dom in str(b).lower())]
        if not liees:
            sans.append(dom)
            continue
        dates = []
        for b in liees:
            for v in (b or {}).values() if isinstance(b, dict) else []:
                m = re.search(r"\d{4}-\d{2}-\d{2}", str(v))
                if m:
                    dates.append(m.group(0))
        recente = max(dates) if dates else ""
        if recente and recente < limite:
            vieilles.append({"domain": dom, "last": recente})
        elif not recente:
            # Des sauvegardes existent mais aucune date exploitable : on le dit
            # plutôt que de les compter comme bonnes.
            vieilles.append({"domain": dom, "last": ""})
    return {"ok": True, "threshold_days": seuil, "missing": sans, "stale": vieilles,
            "total": len(domaines), "proxys": sorted(proxys)}


def fp_backup_pass() -> dict:
    """Publie l'audit des sauvegardes dans le fil, une fois par constat."""
    if not _mem_cfg("backup_watch_enabled", True):
        return {"ok": True, "disabled": True, "reported": 0}
    a = fp_backup_audit()
    if not a.get("ok"):
        return a
    n = 0
    for dom in a.get("missing", []):
        cle = "backup-absent:%s" % dom
        if _cron_seen(cle):
            continue
        qui = _contact_alert_line(dom)
        _itare_proactive_add("Aucune sauvegarde pour %s" % dom,
                             "Aucune copie réussie ne couvre ce site ni son compte.%s"
                             % (("\n" + qui) if qui else ""),
                             source="sauvegarde", nature="etat", sujet=str(dom),
                             cle="sauvegarde:absente:%s" % dom, sonde="backup:%s" % dom)
        itare_task_from_source("auto-backup", cle, "Mettre en place une sauvegarde pour %s" % dom)
        n += 1
    for s in a.get("stale", []):
        cle = "backup-vieux:%s:%s" % (s["domain"], s["last"] or "sans-date")
        if _cron_seen(cle):
            continue
        _itare_proactive_add(
            "Sauvegarde périmée : %s" % s["domain"],
            ("Dernière sauvegarde datée du %s (seuil : %d jours)." % (s["last"], a["threshold_days"]))
            if s["last"] else
            "Des sauvegardes existent mais aucune n'est datée : impossible d'affirmer qu'elles sont à jour.",
            source="sauvegarde", nature="etat", sujet=str(s["domain"]),
            cle="sauvegarde:perimee:%s" % s["domain"], sonde="backup:%s" % s["domain"])
        n += 1
    return {"ok": True, "reported": n, "missing": len(a.get("missing", [])),
            "stale": len(a.get("stale", []))}


def fp_ssl_autorenew_etat() -> dict:
    """Ce que la passe de renouvellement FERAIT, sans rien faire.

    C'est ce que la route /api/fp/audit rend (2026-09-05) : elle appelait la
    passe elle-même, qui lançait certbot sur chaque domaine sous le seuil,
    sans journal — un clic sur « Audit » consommait du quota Let's Encrypt.
    Une route qui s'appelle « audit » n'écrit rien ; la passe reste au cron."""
    seuil = int(_mem_cfg("ssl_autorenew_days", 15) or 15)
    actif = bool(_mem_cfg("ssl_autorenew_enabled", False))
    minuteur = ""
    try:
        p = subprocess.run("systemctl is-active certbot.timer", shell=True,
                           capture_output=True, text=True, timeout=8)
        minuteur = (p.stdout or "").strip()
    except Exception as e:
        logging.debug("[SSL] minuteur certbot : %s", e)
    vue = fp_ssl_overview()
    proches = [d for d in (vue.get("soon") or [])
               if int(d.get("days_left") or 0) <= seuil]
    if not actif:
        note = ("certbot.timer est actif : le renouvellement est déjà pris en charge."
                if minuteur == "active" else
                "Aucun minuteur certbot actif — personne ne renouvelle automatiquement.")
    else:
        note = ("Renouvellement automatique actif : la passe planifiée renouvelle sous "
                "le seuil. Cette vue n'a rien lancé.")
    return {"ok": True, "disabled": not actif, "threshold": seuil,
            "certbot_timer": minuteur, "candidates": [d["domain"] for d in proches],
            "candidates_detail": proches, "note": note}


def fp_ssl_autorenew_pass() -> dict:
    """Renouvelle les certificats sous le seuil — si l'utilisateur l'a demandé.

    Désactivé par défaut, et ce n'est pas de la timidité : certbot installe
    presque toujours son propre minuteur (`certbot.timer`), qui fait déjà ce
    travail. Renouveler une seconde fois depuis ici ne protège de rien et
    consomme le quota de l'autorité de certification. On regarde donc si ce
    minuteur existe, et on le DIT plutôt que de doubler silencieusement."""
    etat = fp_ssl_autorenew_etat()
    proches = etat.pop("candidates_detail", [])
    seuil, minuteur = etat["threshold"], etat["certbot_timer"]
    if etat["disabled"]:
        return etat
    faits, echecs = [], []
    for d in proches:
        # La règle « Hébergement › Renouveler un certificat » (10-10) : palier, fenêtre, disjoncteur.
        # Un renouvellement qui échoue en boucle ronge le quota de l'autorité : le disjoncteur l'arrête.
        _porte = aut_porte("hebergement/renouveler-un-certificat", str(d["domain"]), "Renouveler le certificat de %s" % d["domain"])
        if not _porte.get("ok"):
            continue                       # retenu par la règle : ce n'est pas un échec, c'est dans l'ombre
        r = fp_ssl_issue(d["domain"], confirm=True)
        aut_fin(_porte, bool(r.get("ok")), "%s jours restants" % d.get("days_left"), str(r.get("reason") or "")[:200])
        (faits if r.get("ok") else echecs).append(d["domain"])
        # JOURNAL (2026-09-05) : chaque renouvellement lancé d'ici sollicite
        # une autorité externe, avec quota ; il n'en restait aucune trace.
        try:
            log_admin_action("cron", "fp_ssl_autorenew", "OK" if r.get("ok") else "FAIL",
                             "domain=%s days_left=%s %s"
                             % (d["domain"], d.get("days_left"), (r.get("reason") or "")[:120]))
        except Exception as e:
            logging.debug("[AUDIT] %s", e)
        if not r.get("ok"):
            cle = "ssl-echec:%s:%s" % (d["domain"], d.get("expiry", ""))
            if not _cron_seen(cle):
                _itare_proactive_add(
                    "Renouvellement SSL échoué : %s" % d["domain"],
                    "%s\n%s" % (r.get("reason", "") or "", (r.get("output", "") or "")[:600]),
                    source="certificat", nature="etat", niveau="critique", sujet=str(d["domain"]),
                    cle="certificat:%s" % d["domain"], sonde="ssl:%s" % d["domain"])
    return {"ok": True, "renewed": faits, "failed": echecs, "threshold": seuil,
            "certbot_timer": minuteur}


# Dates de fin de support officielles. Un site sur une version périmée ne casse
# pas : il cesse simplement de recevoir les correctifs de sécurité, ce qui ne
# produit aucun symptôme visible jusqu'au jour où c'est trop tard.
_PHP_EOL = {
    "5.6": "2018-12-31", "7.0": "2019-01-10", "7.1": "2019-12-01", "7.2": "2020-11-30",
    "7.3": "2021-12-06", "7.4": "2022-11-28", "8.0": "2023-11-26", "8.1": "2025-12-31",
    "8.2": "2026-12-31", "8.3": "2027-12-31", "8.4": "2028-12-31",
}


def fp_php_audit() -> dict:
    """Versions de PHP en fin de support, par site."""
    try:
        domaines = get_fp_domains() or []
    except Exception as e:
        return {"ok": False, "reason": str(e)}
    aujourd = _utcnow().strftime("%Y-%m-%d")
    bientot = (_utcnow() + timedelta(days=120)).strftime("%Y-%m-%d")
    finis, proches, inconnus = [], [], []
    for d in domaines:
        brut = str(d.get("php_version", "") or "")
        m = re.search(r"(\d+\.\d+)", brut)
        if not m:
            # Une valeur sans chiffre n'est pas une version : le collecteur y
            # rangeait un gestionnaire (« php_fpm », « mpm_itk », « fastuser »)
            # et l'audit l'exposait comme une version exotique. Depuis le
            # 2026-09-05 la version vient du panneau (`_fp_php_par_site`) ; ce
            # qui reste sans version est dit « non lue », avec sa source.
            if brut or d.get("php_handler"):
                inconnus.append({"domain": d.get("domain"), "php": brut,
                                 "handler": d.get("php_handler", ""),
                                 "source": d.get("php_source") or "version non lue",
                                 "note": "version non lue"})
            continue
        v = m.group(1)
        eol = _PHP_EOL.get(v)
        if not eol:
            continue
        if eol < aujourd:
            finis.append({"domain": d.get("domain"), "php": v, "eol": eol})
        elif eol < bientot:
            proches.append({"domain": d.get("domain"), "php": v, "eol": eol})
    return {"ok": True, "eol": finis, "soon": proches, "unknown": inconnus,
            "source": "website_backends.handler_version (base du panneau)"}


def fp_php_pass() -> dict:
    if not _mem_cfg("php_watch_enabled", True):
        return {"ok": True, "disabled": True, "reported": 0}
    a = fp_php_audit()
    if not a.get("ok"):
        return a
    n = 0
    for x in a.get("eol", []) + a.get("soon", []):
        fini = x["eol"] < _utcnow().strftime("%Y-%m-%d")
        cle = "php:%s:%s" % (x["domain"], x["php"])
        if _cron_seen(cle):
            continue
        qui = _contact_alert_line(x["domain"])
        _itare_proactive_add(
            ("PHP %s en fin de support : %s" if fini else "PHP %s bientôt en fin de support : %s")
            % (x["php"], x["domain"]),
            "Support terminé le %s — plus aucun correctif de sécurité.%s"
            % (x["eol"], ("\n" + qui) if qui else ""),
            source="site", nature="etat", niveau="avoir" if fini else "info", sujet=str(x["domain"]),
            cle="site:php:%s" % x["domain"])
        if fini:
            itare_task_from_source("auto-php", cle,
                                   "Migrer %s vers une version de PHP supportée (actuellement %s)"
                                   % (x["domain"], x["php"]))
        n += 1
    return {"ok": True, "reported": n, "eol": len(a.get("eol", [])),
            "soon": len(a.get("soon", []))}


# ══════════════════════════════════════════════════════════════════════════
# WEBSOCKET DERRIÈRE NGINX
# Le vhost proxifie bien vers Cassandra, mais sans les en-têtes d'upgrade :
# `wss://…/ws` échouait sur NS_ERROR_WEBSOCKET_CONNECTION_REFUSED et le
# navigateur repartait dans une boucle de reconnexion sans fin.
#
# Le piège, c'est la DURABILITÉ : FastPanel régénère ses vhosts dès qu'on
# touche au domaine depuis le panel, et efface tout ce qu'on y a écrit. On
# n'écrit donc qu'UNE ligne dans le vhost — un `include` — et les directives
# vivent dans un fichier hors de l'arborescence FastPanel. Si la ligne
# disparaît, la surveillance la remet.
# ══════════════════════════════════════════════════════════════════════════
_WS_INCLUDE_PATH = "/etc/nginx/cassandra-websocket.conf"
_WS_MAP_PATH = "/etc/nginx/conf.d/cassandra-websocket-map.conf"
_WS_INCLUDE_LINE = "include %s;" % _WS_INCLUDE_PATH
_WS_MARQUEUR = "# cassandra-websocket"

_WS_INCLUDE_BODY = """%s — géré par Cassandra, ne pas éditer à la main.
# Rétabli automatiquement si FastPanel régénère le vhost.
proxy_http_version 1.1;
proxy_set_header Upgrade $http_upgrade;
proxy_set_header Connection $cassandra_conn_upgrade;
# Une WebSocket reste ouverte : sans ça nginx la coupe au bout de 60 s.
proxy_read_timeout 3600s;
proxy_send_timeout 3600s;
""" % _WS_MARQUEUR

# Le nom de variable est préfixé : un `$connection_upgrade` défini ailleurs
# ferait échouer nginx sur un doublon de `map`, et couperait le site entier.
_WS_MAP_BODY = """%s — géré par Cassandra.
# « upgrade » seulement quand le client le demande ; « close » sinon, sous
# peine d'envoyer Connection: upgrade sur des requêtes HTTP ordinaires.
map $http_upgrade $cassandra_conn_upgrade {
    default upgrade;
    ''      close;
}
""" % _WS_MARQUEUR

_NGINX_DIRS = ("/etc/nginx/fastpanel2-available", "/etc/nginx/sites-available",
               "/etc/nginx/conf.d", "/etc/nginx/sites-enabled")


def _ws_upstreams() -> set:
    """Noms des blocs `upstream` qui pointent vers le port de Cassandra.

    FastPanel n'écrit pas `proxy_pass http://127.0.0.1:9000` : il déclare un
    `upstream console.exemple.org1 { server 127.0.0.1:9000; }` et proxifie
    vers ce nom. Chercher le port en toutes lettres dans les `location` ne
    trouvait donc rien, et le WebSocket passait pour non configurable alors
    que le vhost était bien là."""
    serveur = re.compile(r"server\s+(?:127\.0\.0\.1|localhost|0\.0\.0\.0):%d\b" % PORT)
    noms = set()
    for racine in _NGINX_DIRS:
        if not os.path.isdir(racine):
            continue
        for base, _dirs, fichiers in os.walk(racine):
            for f in fichiers:
                if not f.endswith(".conf"):
                    continue
                chemin = os.path.join(base, f)
                try:
                    with open(chemin, "r", errors="replace") as fh:
                        txt = fh.read()
                except Exception:
                    continue
                for m in re.finditer(r"upstream\s+([A-Za-z0-9._\-]+)\s*\{", txt):
                    fin = txt.find("}", m.end())
                    if fin > 0 and serveur.search(txt[m.end():fin]):
                        noms.add(m.group(1))
    return noms


def _ws_motif_proxy():
    """Expression qui reconnaît un `proxy_pass` vers Cassandra, upstream compris."""
    alternatives = [r"(?:127\.0\.0\.1|localhost|0\.0\.0\.0):%d\b" % PORT]
    for nom in sorted(_ws_upstreams()):
        alternatives.append(re.escape(nom) + r"\b")
    return re.compile(r"proxy_pass\s+https?://(?:%s)" % "|".join(alternatives))


def _ws_vhosts() -> list:
    """Fichiers nginx qui proxifient vers le port de Cassandra.

    On ne devine pas le nom du domaine : on cherche la destination réelle.
    Un `proxy_pass` vers notre port, c'est notre vhost, quel qu'il soit — que
    le port soit écrit en clair ou caché derrière un `upstream` nommé."""
    motif = _ws_motif_proxy()
    trouves = []
    for racine in _NGINX_DIRS:
        if not os.path.isdir(racine):
            continue
        for base, _dirs, fichiers in os.walk(racine):
            for f in fichiers:
                if not f.endswith(".conf"):
                    continue
                chemin = os.path.join(base, f)
                # sites-enabled n'est qu'un jeu de liens : on édite la cible.
                if os.path.islink(chemin):
                    continue
                try:
                    with open(chemin, "r", errors="replace") as fh:
                        txt = fh.read()
                except Exception:
                    continue
                if motif.search(txt):
                    trouves.append(chemin)
    return sorted(set(trouves))


def _ws_blocs_proxy(txt: str) -> list:
    """Position d'insertion dans chaque `location` qui proxifie vers nous.

    Renvoie les décalages juste après l'accolade ouvrante. On compte les
    accolades plutôt que d'utiliser une expression régulière : un vhost
    contient des blocs imbriqués, et une regex y aurait pris le mauvais."""
    motif = _ws_motif_proxy()
    positions = []
    for m in re.finditer(r"location\s+[^{]*\{", txt):
        debut = m.end()
        niveau, i = 1, debut
        while i < len(txt) and niveau:
            if txt[i] == "{":
                niveau += 1
            elif txt[i] == "}":
                niveau -= 1
            i += 1
        if motif.search(txt[debut:i]):
            positions.append(debut)
    return positions


def _ws_map_target() -> str:
    """Répertoire réellement inclus en contexte `http`, où poser la carte.

    Supposer `/etc/nginx/conf.d/` est une erreur : certains nginx (dont des
    montages FastPanel) ne l'incluent pas. La carte serait ignorée, la variable
    inconnue, et `nginx -t` refuserait tout. On lit donc les `include` du
    nginx.conf — ceux hors de tout bloc `server` — et on retient le premier
    répertoire qui existe et qu'on peut écrire."""
    try:
        with open("/etc/nginx/nginx.conf", "r", errors="replace") as fh:
            txt = fh.read()
    except Exception:
        return _WS_MAP_PATH
    # On retire les blocs server : un include qui s'y trouve n'est pas en http.
    sans_server = re.sub(r"server\s*\{(?:[^{}]|\{[^{}]*\})*\}", "", txt)
    candidats = []
    for m in re.finditer(r"^\s*include\s+([^;]+);", sans_server, re.M):
        motif = m.group(1).strip().strip('"\'')
        if not motif.endswith(".conf") or "mime" in motif or "fastcgi" in motif:
            continue
        rep = os.path.dirname(motif if motif.startswith("/") else "/etc/nginx/" + motif)
        if os.path.isdir(rep) and os.access(rep, os.W_OK):
            candidats.append(rep)
    for pref in ("/etc/nginx/conf.d",):
        if pref in candidats:
            return os.path.join(pref, os.path.basename(_WS_MAP_PATH))
    if candidats:
        return os.path.join(candidats[0], os.path.basename(_WS_MAP_PATH))
    return _WS_MAP_PATH


def _nginx_test() -> tuple:
    try:
        p = subprocess.run("nginx -t", shell=True, capture_output=True, text=True, timeout=30)
        return p.returncode == 0, ((p.stdout or "") + (p.stderr or "")).strip()[:2000]
    except Exception as e:
        return False, str(e)


def ws_proxy_state() -> dict:
    """Où en est la configuration WebSocket, sans rien modifier."""
    vhosts = _ws_vhosts()
    detail = []
    for chemin in vhosts:
        try:
            with open(chemin, "r", errors="replace") as fh:
                txt = fh.read()
        except Exception as e:
            detail.append({"file": chemin, "lisible": False, "reason": str(e)})
            continue
        blocs = _ws_blocs_proxy(txt)
        # L'include peut être présent mais hors du bloc utile : on vérifie
        # qu'il est bien DANS un location qui proxifie vers nous.
        dedans = 0
        for pos in blocs:
            niveau, i = 1, pos
            while i < len(txt) and niveau:
                if txt[i] == "{":
                    niveau += 1
                elif txt[i] == "}":
                    niveau -= 1
                i += 1
            if _WS_INCLUDE_PATH in txt[pos:i]:
                dedans += 1
        detail.append({"file": chemin, "lisible": True, "blocs": len(blocs),
                       "inclus": dedans, "complet": bool(blocs) and dedans == len(blocs)})
    ok_test, sortie = _nginx_test()
    manquants = [d for d in detail if d.get("lisible") and not d.get("complet")]
    map_path = _ws_map_target()
    return {"ok": True, "port": PORT, "vhosts": detail,
            "include_present": os.path.isfile(_WS_INCLUDE_PATH),
            "map_present": os.path.isfile(map_path),
            "include_path": _WS_INCLUDE_PATH, "map_path": map_path,
            "installe": bool(_mem_cfg("ws_proxy_installed", False)),
            "autorepare": bool(_mem_cfg("ws_proxy_autorepair", True)),
            "nginx_ok": ok_test, "nginx_test": sortie,
            "a_reparer": [d["file"] for d in manquants],
            "conforme": bool(detail) and not manquants
                        and os.path.isfile(_WS_INCLUDE_PATH) and os.path.isfile(map_path),
            "reason": "" if detail else
                      "aucun vhost ne proxifie vers le port %d — nginx n'est peut-être "
                      "pas la porte d'entrée sur cette machine" % PORT}


def ws_proxy_install(confirm: bool = False, auto: bool = False) -> dict:
    """Pose (ou rétablit) la configuration WebSocket.

    Toute écriture est réversible : sauvegarde de chaque vhost avant, `nginx -t`
    après, et restauration intégrale si le test échoue. On ne recharge nginx que
    sur un test vert — une erreur de configuration couperait le site."""
    etat = ws_proxy_state()
    if not etat["vhosts"]:
        return {"ok": False, "reason": etat["reason"]}
    if not confirm and not auto:
        return {"ok": False, "needs_confirm": True,
                "reason": "Modifie la configuration nginx de %d fichier(s) puis recharge "
                          "le service." % len(etat["vhosts"]),
                "fichiers": [d["file"] for d in etat["vhosts"]]}
    horo = datetime.now().strftime("%Y%m%d-%H%M%S")
    sauvegardes, modifies, erreurs = {}, [], []
    try:
        _map = _ws_map_target()
        for chemin, corps in ((_WS_INCLUDE_PATH, _WS_INCLUDE_BODY),
                              (_map, _WS_MAP_BODY)):
            if not os.path.isdir(os.path.dirname(chemin)):
                erreurs.append("%s absent : la carte n'a pas pu être posée"
                               % os.path.dirname(chemin))
                continue
            with open(chemin, "w") as fh:
                fh.write(corps)
        for d in etat["vhosts"]:
            if not d.get("lisible") or d.get("complet"):
                continue
            chemin = d["file"]
            with open(chemin, "r", errors="replace") as fh:
                txt = fh.read()
            sauvegardes[chemin] = txt
            with open(chemin + ".cassandra-" + horo + ".bak", "w") as fh:
                fh.write(txt)
            # On insère depuis la FIN : chaque insertion décale ce qui suit.
            for pos in sorted(_ws_blocs_proxy(txt), reverse=True):
                niveau, i = 1, pos
                while i < len(txt) and niveau:
                    if txt[i] == "{":
                        niveau += 1
                    elif txt[i] == "}":
                        niveau -= 1
                    i += 1
                if _WS_INCLUDE_PATH in txt[pos:i]:
                    continue
                txt = txt[:pos] + "\n        " + _WS_INCLUDE_LINE + txt[pos:]
            with open(chemin, "w") as fh:
                fh.write(txt)
            modifies.append(chemin)
        ok_test, sortie = _nginx_test()
        if not ok_test:
            for chemin, avant in sauvegardes.items():
                with open(chemin, "w") as fh:
                    fh.write(avant)
            logging.error("[WS] nginx -t refuse la configuration, tout est restauré : %s",
                          sortie)
            return {"ok": False, "restaure": True, "reason":
                    "nginx a refusé la configuration — rien n'a été changé.", "nginx": sortie}
        p = subprocess.run("systemctl reload nginx", shell=True,
                           capture_output=True, text=True, timeout=45)
        if p.returncode != 0:
            for chemin, avant in sauvegardes.items():
                with open(chemin, "w") as fh:
                    fh.write(avant)
            subprocess.run("systemctl reload nginx", shell=True, timeout=45)
            return {"ok": False, "restaure": True,
                    "reason": "rechargement nginx impossible : %s"
                              % ((p.stderr or p.stdout or "").strip()[:400])}
    except Exception as e:
        for chemin, avant in sauvegardes.items():
            try:
                with open(chemin, "w") as fh:
                    fh.write(avant)
            except Exception:
                pass
        logging.exception("[WS] installation impossible")
        return {"ok": False, "reason": "%s : %s" % (type(e).__name__, e)}
    cfg = get_cassandra_config()
    cfg["ws_proxy_installed"] = True
    save_cassandra_config(cfg)
    log_admin_action("", "ws_proxy_install", "OK",
                     "%s : %s" % ("rétabli" if auto else "posé", ", ".join(modifies) or "—"))
    return {"ok": True, "modifies": modifies, "auto": auto, "erreurs": erreurs,
            "sauvegarde": ".cassandra-%s.bak" % horo,
            "message": "WebSocket activé sur %d vhost(s)." % len(modifies) if modifies
                       else "Configuration déjà en place."}


def ws_proxy_watch() -> dict:
    """Surveille la dérive et rétablit ce qui a été effacé.

    C'est ici que se joue la durabilité : FastPanel réécrit ses vhosts sans
    prévenir. On ne rétablit QUE ce qui avait déjà été posé une fois avec
    l'accord de l'utilisateur — jamais une première installation en douce."""
    etat = ws_proxy_state()
    if not etat["vhosts"]:
        return {"ok": True, "rien": True, "reason": etat["reason"]}
    if etat["conforme"]:
        return {"ok": True, "conforme": True}
    if not etat["installe"]:
        return {"ok": True, "conforme": False, "attente_accord": True,
                "a_reparer": etat["a_reparer"]}
    if not etat["autorepare"]:
        if not _cron_seen("ws_proxy_drift"):
            itare_task_from_source(
                "infra", "websocket",
                "La configuration WebSocket a été effacée du vhost nginx "
                "(%s). Le terminal et les mises à jour en direct ne fonctionnent plus."
                % ", ".join(etat["a_reparer"]))
        return {"ok": False, "derive": True, "repare": False, "a_reparer": etat["a_reparer"]}
    r = ws_proxy_install(auto=True)
    if r.get("ok"):
        logging.warning("[WS] configuration effacée puis rétablie : %s",
                        ", ".join(r.get("modifies") or []))
    return {"ok": r.get("ok"), "derive": True, "repare": r.get("ok"),
            "modifies": r.get("modifies"), "reason": r.get("reason", "")}


def fp_infra_pass() -> dict:
    """Une passe pour les cinq surveillances. Chacune est isolée : un
    collecteur en panne ne doit pas emporter les quatre autres."""
    res = {}
    for nom, fn in (("services", fp_service_watch), ("backups", fp_backup_pass),
                    ("php", fp_php_pass), ("ssl", fp_ssl_autorenew_pass),
                    ("databases", fp_db_autolink), ("websocket", ws_proxy_watch),
                    ("fleet", fleet_pass), ("sites", site_pass),
                    ("scans", fp_scan_watch), ("liens", fp_liens_watch),
                    ("rotation", aut_rotation_pass)):
        try:
            res[nom] = fn()
        except Exception as e:
            logging.info("[INFRA] %s : %s", nom, e)
            res[nom] = {"ok": False, "reason": str(e)}
    return res


