def validate_session(token: str) -> bool:
    """Valide un jeton de session.

    Trois défauts corrigés ici, qui provoquaient des 502 en rafale :
      · AUCUN DÉLAI d'attente sur la connexion — sous charge, « database is locked »
        remontait jusqu'au serveur HTTP, qui fermait la connexion sans réponse ;
      · l'horodatage `last_used` était réécrit À CHAQUE REQUÊTE, soit une écriture
        par appel d'API (métriques toutes les 3 s, processus, docker…) ;
      · une simple donnée de télémétrie faisait donc échouer l'authentification.
    Désormais : délai d'attente, écriture au plus une fois par minute, et un échec
    de mise à jour n'invalide jamais une session par ailleurs valide."""
    if not token or len(token) != 64:
        return False
    conn = None
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        # L'expiration ne s'appliquait qu'au moment d'une NOUVELLE connexion :
        # entre deux, une session survivait indéfiniment. Elle se vérifie ici,
        # à chaque requête, sur la même durée que la purge.
        row = conn.execute("SELECT token FROM server_sessions WHERE token = ? "
                           "AND created_at > datetime('now', ?)",
                           (token, "-%d hours" % session_ttl_heures())).fetchone()
        if row:
            try:
                # Filtré côté SQL : pas de lecture supplémentaire, et l'écriture
                # n'a lieu que si l'horodatage a plus d'une minute.
                conn.execute(
                    "UPDATE server_sessions SET last_used = CURRENT_TIMESTAMP "
                    "WHERE token = ? AND (last_used IS NULL "
                    "      OR last_used <= datetime('now','-60 seconds'))", (token,))
                conn.commit()
            except Exception as e:
                logging.debug("[SESSION] last_used non mis à jour : %s", e)
        return row is not None
    except Exception as e:
        # Base verrouillée ou illisible : on ne peut PAS conclure que la session
        # est invalide. On refuse prudemment, mais sans faire tomber la requête.
        logging.warning("[SESSION] validation impossible : %s", e)
        return False
    finally:
        if conn:
            try:
                conn.close()
            except Exception:
                pass


def invalidate_session(token: str):
    conn = sqlite3.connect(MEMORY_DB_PATH)
    conn.execute("DELETE FROM server_sessions WHERE token = ?", (token,))
    conn.commit()
    conn.close()


# ── Self-service utilisateur : sessions, bloc-notes ────────────────────────────
def list_user_sessions(username: str, current_token: str = "") -> list:
    """Sessions web actives du user (token masqué, jamais exposé en clair)."""
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH)
        _sessions_migrer(conn)
        rows = conn.execute("SELECT token, created_at, last_used, ip, agent FROM server_sessions "
                            "WHERE username = ? ORDER BY last_used DESC", (username,)).fetchall()
        conn.commit(); conn.close()
        out = []
        for tok, created, last, ip, agent in rows:
            out.append({"id": (tok or "")[-6:], "created": created, "last_used": last,
                        "ip": ip or "", "agent": agent or "",
                        "nature": _ip_nature(ip or ""),
                        "current": (tok == current_token)})
        return out
    except Exception:
        return []


def _ip_nature(ip: str) -> str:
    """« local », « internet » ou « " » — sans jamais interroger personne.

    Une géolocalisation supposerait d'appeler un service extérieur à chaque
    affichage de l'écran, et de lui dire au passage qui se connecte d'où. Ce
    qu'on cherche vraiment, c'est reconnaître une session qui ne vient pas de
    chez soi : la nature de l'adresse suffit à le dire.
    """
    ip = (ip or "").strip()
    if not ip:
        return ""
    if ip in ("127.0.0.1", "::1", "localhost"):
        return "serveur"
    p = ip.split(".")
    try:
        if p[0] == "10" or (p[0] == "192" and p[1] == "168"):
            return "local"
        if p[0] == "172" and 16 <= int(p[1]) <= 31:
            return "local"
    except (IndexError, ValueError):
        pass
    if ip.startswith(("fc", "fd", "fe80")):
        return "local"
    return "internet"


def revoke_session(username: str, court: str) -> dict:
    """Ferme UNE session de ce compte, désignée par les six derniers caractères
    de son jeton — le jeton entier ne sort jamais du serveur.

    Le `username` est celui de la session appelante, jamais un paramètre : sans
    ça, six caractères devinés fermeraient la session de quelqu'un d'autre.
    """
    court = (court or "").strip()
    if not username or len(court) != 6:
        return {"ok": False, "error": "session inconnue"}
    conn = None
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH)
        _sessions_migrer(conn)
        cur = conn.execute("DELETE FROM server_sessions WHERE username = ? "
                           "AND substr(token, -6) = ?", (username, court))
        conn.commit()
        return {"ok": True, "ferme": cur.rowcount}
    except Exception as e:
        return {"ok": False, "error": str(e)}
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


def revoke_other_sessions(username: str, current_token: str) -> int:
    """Déconnecte toutes les AUTRES sessions du user (garde la courante). Retourne le nb révoqué."""
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH)
        # PAS D'EXCEPTION pour les sessions internes du salon : l'agent et l'adresse
        # d'une session viennent de la requête, une session forgée pourrait s'en
        # réclamer (Itare, fil 17 #120). La présence des résidents se refait seule
        # au tour suivant (`_salon_sid_presence`) : la révoquer ne coupe plus rien.
        cur = conn.execute("DELETE FROM server_sessions WHERE username = ? AND token != ?",
                           (username, current_token))
        n = cur.rowcount
        conn.commit(); conn.close()
        return n or 0
    except Exception:
        return 0


def get_user_notes(username: str) -> str:
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        conn.execute("CREATE TABLE IF NOT EXISTS user_notes (username TEXT PRIMARY KEY, "
                     "content TEXT, updated_at TEXT DEFAULT (datetime('now')))")
        row = conn.execute("SELECT content FROM user_notes WHERE username = ?", (username,)).fetchone()
        conn.close()
        return (row[0] or "") if row else ""
    except Exception:
        return ""


def set_user_notes(username: str, content: str) -> bool:
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        conn.execute("CREATE TABLE IF NOT EXISTS user_notes (username TEXT PRIMARY KEY, "
                     "content TEXT, updated_at TEXT DEFAULT (datetime('now')))")
        conn.execute("INSERT INTO user_notes (username, content, updated_at) VALUES (?,?,datetime('now')) "
                     "ON CONFLICT(username) DO UPDATE SET content=excluded.content, updated_at=datetime('now')",
                     (username, (content or "")[:20000]))
        conn.commit(); conn.close()
        return True
    except Exception:
        return False


