def memoire_export(portee: list = None) -> dict:
    """Export JSON par portée avec l'empreinte de l'ensemble trié : le banc de restauration
    compare le nombre de lignes et l'empreinte."""
    rows = memoire_lister(portee, statut="tous", limite=100000)
    rows.sort(key=lambda r: r["id"])
    brut = json.dumps(rows, ensure_ascii=False, sort_keys=True)
    return {"n": len(rows), "sha256": hashlib.sha256(brut.encode("utf-8")).hexdigest(), "souvenirs": rows}


def memoire_journal_lire(portee: list = None, limite: int = 100, verbe: str = None) -> list:
    """Le journal, borné à la portée du lecteur : les gestes sur SES souvenirs, et les refus
    de garde qui le concernent (le propriétaire est dans les détails du refus)."""
    portee = set(portee or memoire_portee())
    conn = _memoire_conn()
    try:
        sql = ("SELECT j.id, j.ts, j.acteur, j.verbe, j.memoire_id, j.details, m.proprietaire, m.cle "
               "FROM memoire_journal j LEFT JOIN memoires m ON m.id = j.memoire_id")
        args = []
        if verbe:
            sql += " WHERE j.verbe = ?"
            args.append(verbe)
        sql += " ORDER BY j.id DESC LIMIT ?"
        args.append(int(limite) * 4)
        out = []
        for r in conn.execute(sql, args):
            prop = r["proprietaire"]
            if prop is None:
                try:
                    prop = (json.loads(r["details"] or "{}") or {}).get("proprietaire")
                except Exception:
                    prop = None
            if prop is not None and prop not in portee:
                continue
            out.append({"id": r["id"], "ts": r["ts"], "acteur": r["acteur"], "verbe": r["verbe"],
                        "memoire_id": r["memoire_id"], "cle": r["cle"], "details": r["details"]})
            if len(out) >= int(limite):
                break
        return out
    finally:
        conn.close()


def save_memory(category: str, key: str, value: str, confidence: float = 1.0, tags: list = None, change_reason: str = "", source: str = None):
    """DOUBLURE V18 : l'ancienne signature, la porte derrière. Les quinze écrivains historiques
    (extraction, vigie, Itare, écran) traversent memoire_ecrire et ses gardes sans le savoir ;
    un refus rend None et se lit au journal. Rend l'id, ou None."""
    r = memoire_ecrire(category, key, value, provenance=source or "infere", confiance=confidence,
                       nature="constat",
                       declencheur=(change_reason or "heritage")[:40])
    if not r.get("ok"):
        logging.info("[MEMOIRE] écriture héritée refusée (%s) : %s %r", r.get("refus"), category, str(key)[:60])
        return None
    return r.get("id")


