_REFLEX_MIGRATED = [False]
_REFLEX_LAST = {}
_REFLEX_CHARGE = [False]

def _reflex_due(key: str, hours: float) -> bool:
    """Un réflexe « dû » toutes les N heures. LE DERNIER PASSAGE SURVIT AU REDÉMARRAGE (20-09) : en
    mémoire seule, chaque redémarrage rejouait toutes les passes « nocturnes » — onze versions d'un
    même souvenir en une journée de déploiements."""
    now = time.time()
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        try:
            conn.execute("CREATE TABLE IF NOT EXISTS reflexes_derniers (cle TEXT PRIMARY KEY, ts REAL NOT NULL)")
            if not _REFLEX_CHARGE[0]:
                for r in conn.execute("SELECT cle, ts FROM reflexes_derniers"):
                    _REFLEX_LAST.setdefault(r[0], float(r[1] or 0))
                _REFLEX_CHARGE[0] = True
            if now - _REFLEX_LAST.get(key, 0) < hours * 3600:
                return False
            _REFLEX_LAST[key] = now
            conn.execute("INSERT OR REPLACE INTO reflexes_derniers (cle, ts) VALUES (?, ?)", (key, now))
            conn.commit()
            return True
        finally:
            conn.close()
    except Exception:
        if now - _REFLEX_LAST.get(key, 0) < hours * 3600:
            return False
        _REFLEX_LAST[key] = now
        return True

def _reflex_migrate() -> None:
    if _REFLEX_MIGRATED[0]:
        return
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        conn.execute("CREATE TABLE IF NOT EXISTS reflective_journal (id INTEGER PRIMARY KEY AUTOINCREMENT, "
                     "ts TEXT DEFAULT (datetime('now')), entry TEXT, mood TEXT)")
        conn.execute("CREATE TABLE IF NOT EXISTS postmortems (id INTEGER PRIMARY KEY AUTOINCREMENT, "
                     "ts TEXT DEFAULT (datetime('now')), title TEXT, summary TEXT, lessons TEXT, status TEXT DEFAULT 'open')")
        conn.execute("CREATE TABLE IF NOT EXISTS open_questions (id INTEGER PRIMARY KEY AUTOINCREMENT, "
                     "ts TEXT DEFAULT (datetime('now')), question TEXT, status TEXT DEFAULT 'open')")
        conn.execute("CREATE TABLE IF NOT EXISTS identity_history (id INTEGER PRIMARY KEY AUTOINCREMENT, "
                     "ts TEXT DEFAULT (datetime('now')), summary TEXT)")
        conn.execute("CREATE TABLE IF NOT EXISTS dialogues (id INTEGER PRIMARY KEY AUTOINCREMENT, "
                     "ts TEXT DEFAULT (datetime('now')), topic TEXT, transcript TEXT, synthesis TEXT)")
        conn.commit(); conn.close()
        _REFLEX_MIGRATED[0] = True
    except Exception as e:
        logging.warning("[REFLEX] migrate: %s" % e)


def _reflex_llm_text(user_msgs: list, system: str = None, max_tokens: int = 400,
                     temperature: float = 0.6) -> str:
    """Tâches NARRATIVES (journal, post-mortem, curiosité, délibération, rêves) : préfère le modèle
    PRINCIPAL (plus capable, meilleur français), repli sur l'agent secondaire. La narration n'est
    pas un travail de sécurité — inutile d'imposer le petit modèle isolé."""
    msgs = []
    if system:
        msgs.append({"role": "system", "content": system})
    msgs.extend(user_msgs)
    if DEEPSEEK_API_KEY:
        try:
            r = client.chat.completions.create(model=MODEL_NAME, messages=msgs,
                                               temperature=temperature, max_tokens=max_tokens)
            out = _extract_msg_text(r)
            if out:
                return out
        except Exception:
            pass
    try:
        return _itare_agent_text(user_msgs, system=system, max_tokens=max_tokens) or ""
    except Exception:
        return ""


def _reflex_llm_available() -> bool:
    return bool(DEEPSEEK_API_KEY) or _itare_agent_available()


def _reflex_parse_json(raw: str):
    if not raw:
        return None
    a, b = raw.find("{"), raw.rfind("}")
    if a != -1 and b > a:
        try:
            return json.loads(raw[a:b + 1])
        except Exception:
            return None
    return None





_BLIND_SPOTS_CACHE = {"data": None, "timestamp": 0}
_CACHE_TTL = 60  # secondes

def blind_spots() -> list:
    """Angles morts : domaines d'échec récurrent (évolutions refusées, alertes non résolues,
    refus du vérificateur, souvenirs douteux par catégorie)."""
    now = time.time()
    # PERF: Vérifie si le cache est encore valide
    if _BLIND_SPOTS_CACHE["data"] is not None and (now - _BLIND_SPOTS_CACHE["timestamp"]) < _CACHE_TTL:
        return _BLIND_SPOTS_CACHE["data"]

    spots = []
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        conn.row_factory = sqlite3.Row
        # PERF: Exécute la migration v2 avant toute requête

        # PERF: Fusionne les trois requêtes en une seule UNION ALL pour réduire les appels execute (3→1)
        # et éviter de parcourir séparément plusieurs curseurs.
        query = """
        SELECT area, count, note FROM (
            SELECT 'évolution: ' || COALESCE(target_file, '?') AS area,
                   COUNT(*) AS count,
                   'patchs annulés/refusés à répétition' AS note
            FROM evolution_log
            WHERE status LIKE '%revert%' OR status LIKE '%reject%'
            GROUP BY target_file
            HAVING count(*) >= 2
            ORDER BY count(*) DESC
            LIMIT 5
        )
        UNION ALL
        SELECT area, count, note FROM (
            SELECT 'proactivité: ' || COALESCE(category, '?') AS area,
                   COUNT(*) AS count,
                   'problèmes ouverts depuis >2 j' AS note
            FROM proactive_findings
            WHERE status IN ('open','investigating') AND first_seen < datetime('now','-2 day')
            GROUP BY category
            ORDER BY count(*) DESC
            LIMIT 5
        )
        """
        for row in conn.execute(query):
            spots.append({
                "area": row["area"],
                "count": row["count"],
                "note": row["note"]
            })
        conn.close()
    except Exception:
        # PERF: En cas d'erreur SQL (table manquante, etc.), on retourne une liste vide
        # plutôt que de laisser le programme planter ; le cache n'est pas mis à jour.
        pass

    # PERF: Met à jour le cache avec le nouveau résultat (même si spots est vide)
    _BLIND_SPOTS_CACHE["data"] = spots
    _BLIND_SPOTS_CACHE["timestamp"] = now
    return spots


def generate_postmortem(title: str, context: str) -> dict:
    """Post-mortem auto : après un incident, Cassandra écrit cause + leçons réutilisables."""
    _reflex_migrate()
    if not _reflex_llm_available():
        return {"ok": False, "reason": "aucun modèle disponible"}
    system = ("Tu ES Cassandra, IA sysadmin. Rédige un POST-MORTEM bref et lucide d'un incident sur TON "
              "serveur, UNIQUEMENT à partir du contexte fourni (n'invente rien). "
              "Format JSON : {\"summary\":\"<2-3 phrases: ce qui s'est passé et pourquoi>\","
              "\"lessons\":\"<1-2 leçons concrètes et réutilisables pour la prochaine fois>\"}")
    raw = _reflex_llm_text([{"role": "user", "content": "INCIDENT : %s\n\nCONTEXTE :\n%s" % (title, context)}],
                           system=system, max_tokens=400)
    d = _reflex_parse_json(raw)
    if not isinstance(d, dict):
        return {"ok": False, "reason": "pas de réponse exploitable"}
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        conn.execute("INSERT INTO postmortems (title, summary, lessons) VALUES (?,?,?)",
                     (str(title)[:160], str(d.get("summary", ""))[:1200], str(d.get("lessons", ""))[:800]))
        conn.commit(); conn.close()
        # La leçon rejoint la mémoire durable.
        try:
            if d.get("lessons"):
                save_memory("leçon", title[:80], str(d.get("lessons"))[:400], confidence=0.85,
                            source="observed", change_reason="post-mortem")
        except Exception:
            pass
    except Exception as e:
        return {"ok": False, "error": str(e)}
    return {"ok": True}



def open_questions_list(limit: int = 30) -> list:
    _reflex_migrate()
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10); conn.row_factory = sqlite3.Row
        rows = [dict(r) for r in conn.execute("SELECT id, ts, question, status FROM open_questions "
                                              "WHERE status='open' ORDER BY id DESC LIMIT ?", (int(limit),))]
        conn.close()
        return rows
    except Exception:
        return []






