# VIE INTÉRIEURE v3 — récit de soi, intentions (cap), lien (modèle de toi),
#   désirs/besoins (drives fonctionnels) et rêves (imagination). Le désir ORIENTE
#   l'apprentissage et la réflexion ; il n'accorde JAMAIS de nouvelle permission.
# ═══════════════════════════════════════════════════════════════════════════════
_INNER_MIGRATED = [False]

def _inner_migrate() -> None:
    if _INNER_MIGRATED[0]:
        return
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        conn.execute("CREATE TABLE IF NOT EXISTS self_narrative (id INTEGER PRIMARY KEY AUTOINCREMENT, "
                     "ts TEXT DEFAULT (datetime('now')), text TEXT)")
        conn.execute("CREATE TABLE IF NOT EXISTS intentions (id INTEGER PRIMARY KEY AUTOINCREMENT, "
                     "ts TEXT DEFAULT (datetime('now')), text TEXT, kind TEXT DEFAULT 'objectif', "
                     "priority TEXT DEFAULT 'medium', status TEXT DEFAULT 'open')")
        conn.execute("CREATE TABLE IF NOT EXISTS bond (key TEXT PRIMARY KEY, value TEXT, "
                     "updated_at TEXT DEFAULT (datetime('now')))")
        conn.execute("CREATE TABLE IF NOT EXISTS drives (id INTEGER PRIMARY KEY AUTOINCREMENT, "
                     "ts TEXT DEFAULT (datetime('now')), label TEXT, intensity INTEGER, source TEXT)")
        conn.execute("CREATE TABLE IF NOT EXISTS dreams (id INTEGER PRIMARY KEY AUTOINCREMENT, "
                     "ts TEXT DEFAULT (datetime('now')), text TEXT, spark TEXT)")
        conn.commit(); conn.close()
        _INNER_MIGRATED[0] = True
    except Exception as e:
        logging.warning("[INNER] migrate: %s" % e)




def intention_add(text: str, kind: str = "objectif", priority: str = "medium") -> dict:
    _inner_migrate()
    text = (text or "").strip()
    if len(text) < 4:
        return {"ok": False, "error": "intention trop courte"}
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        ex = conn.execute("SELECT 1 FROM intentions WHERE status='open' AND text=? LIMIT 1", (text[:300],)).fetchone()
        if not ex:
            conn.execute("INSERT INTO intentions (text, kind, priority) VALUES (?,?,?)", (text[:300], kind, priority))
        conn.commit(); conn.close()
        return {"ok": True}
    except Exception as e:
        return {"ok": False, "error": str(e)}



def bond_get() -> list:
    _inner_migrate()
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10); conn.row_factory = sqlite3.Row
        rows = [dict(r) for r in conn.execute("SELECT key, value, updated_at FROM bond ORDER BY updated_at DESC LIMIT 30")]
        conn.close()
        return rows
    except Exception:
        return []





