# ── HIPPOCAMPE VIVANT : force (décroissance + usage) et renforcement ────────────
def format_memories_for_prompt(query: str = "") -> str:
    """V18 : le bloc mémoire du prompt vient du rappel par règles de l'îlot (noyau, FTS5 sur
    l'actif de la portée, seuil, « je ne sais pas »). Les cités restent dans le fil pour le pied."""
    try:
        return memoire_rappeler(query)["bloc"]
    except Exception as e:
        logging.warning("[MEMOIRE] rappel : %s", e)
        return ""


def _detect_scope_domain(query: str):
    """Repère un domaine géré mentionné dans la question → active la mémoire de ce locataire."""
    try:
        ql = (query or "").lower()
        for d in _all_user_domains():
            if d and d in ql:
                return d
    except Exception:
        pass
    return None


def cognitive_recall(query: str = "", scope_domain: str = None) -> str:
    """LE point de rappel unique du prompt (chat, investigation, vision, délibération). V18 :
    l'îlot seul (la couche réflexive héritée a été retirée avec les phases de sommeil)."""
    parts = []
    try:
        base = format_memories_for_prompt(query)
        if base and base.strip():
            parts.append(base)
    except Exception:
        pass
    return "\n".join(p for p in parts if p and p.strip())


# ══════════════════════════════════════════════════════════════════════════════
#  LA VEILLE MEMOIRE
#
#  Une montee de memoire ne se laisse mesurer qu'AU MOMENT ou elle se produit.
#  Celle de ce matin — 294 Mo au demarrage, 4,43 Go quarante minutes plus tard —
#  n'a laisse aucune trace : le journal de la fenetre porte quelques lignes par
#  minute, et rien qui dise ou sont passes trois gigaoctets.
#
#  On n'ecrit QUE SI QUELQUE CHOSE BOUGE. Un journal qui repete « tout va bien »
#  toutes les cinq minutes ne se lit plus, et c'est alors la ligne qui comptait
#  qu'on saute.
# ══════════════════════════════════════════════════════════════════════════════
_MEM_VEILLE = {"rss": 0, "pic": 0, "depuis": 0.0, "traces": False}
_MEM_SEUIL_MO = 150          # on parle quand ca a bouge d'au moins ceci
_MEM_CYCLE = 300             # cinq minutes


def _mem_rss_mo() -> float:
    """La taille reelle du processus, en mega-octets. 0.0 si illisible."""
    try:
        with open("/proc/self/status") as f:
            for l in f:
                if l.startswith("VmRSS:"):
                    return int(l.split()[1]) / 1024.0
    except Exception:
        pass
    return 0.0


def _mem_gros_objets(n: int = 8) -> str:
    """Les plus gros conteneurs vivants, par nombre d'elements.

    On ne mesure pas leur poids en octets : le parcourir coute cher et fige le
    processus. Le NOMBRE suffit a designer le coupable — un cache qui devrait
    porter cent entrees et en porte cent mille se voit du premier coup d'oeil.
    """
    import gc
    gros = []
    try:
        tous = gc.get_objects()
        # ON S'ECARTE SOI-MEME DE L'INVENTAIRE. `gc.get_objects()` rend la liste
        # de TOUS les objets vivants — plus d'un million ici. Sans ce filtre, la
        # sonde designe son propre outil comme le plus gros conteneur, en tete
        # de liste, a chaque montee. Un instrument qui atteste de lui-meme ne
        # mesure rien.
        #
        # PAR IDENTITE, ET NON PAR LA TAILLE : un seuil se trompe des que la
        # machine grossit, et finirait par masquer une vraie fuite du meme
        # ordre de grandeur.
        moi = {id(tous), id(gros)}
        for o in tous:
            try:
                if id(o) in moi:
                    continue
                if isinstance(o, (dict, list, set)) and len(o) > 500:
                    # CE QU'IL Y A DEDANS, PAS CE QU'IL VAUT. Le TYPE du
                    # premier element designe le coupable ; sa VALEUR n'a
                    # rien a faire dans un journal — ces conteneurs portent
                    # des souvenirs, des messages, parfois des jetons.
                    quoi = ""
                    try:
                        for _e in (o if not isinstance(o, dict) else o.values()):
                            quoi = " de " + type(_e).__name__
                            break
                    except Exception:
                        pass
                    gros.append((len(o), type(o).__name__ + quoi))
            except Exception:
                continue
        del tous
    except Exception:
        return "(inventaire impossible)"
    gros.sort(reverse=True)
    return ", ".join("%s de %d" % (t, c) for c, t in gros[:n]) or "aucun"


def _mem_globales(n: int = 6) -> str:
    """Les conteneurs de ce module qui ont grossi — nommes, eux."""
    out = []
    try:
        for k, v in list(globals().items()):
            if k.startswith("__"):
                continue
            try:
                if isinstance(v, (dict, list, set)) and len(v) > 200:
                    out.append((len(v), k))
            except Exception:
                continue
    except Exception:
        return ""
    out.sort(reverse=True)
    return ", ".join("%s=%d" % (k, c) for c, k in out[:n])


def _mem_traces(n: int = 8) -> str:
    """Les lignes de code qui ont alloue le plus — si la trace est armee."""
    try:
        import tracemalloc
        if not tracemalloc.is_tracing():
            return ""
        stats = tracemalloc.take_snapshot().statistics("lineno")[:n]
        return " | ".join(
            "%s:%s %.1f Mo" % (os.path.basename(s.traceback[0].filename),
                               s.traceback[0].lineno, s.size / 1e6)
            for s in stats)
    except Exception as e:
        return "(traces indisponibles : %s)" % str(e)[:60]


def _mem_veille_boucle() -> None:
    """Le fil de veille. Silencieux tant que rien ne bouge."""
    import threading as _th
    while True:
        try:
            time.sleep(_MEM_CYCLE)
            rss = _mem_rss_mo()
            if not rss:
                continue
            avant = _MEM_VEILLE["rss"] or rss
            _MEM_VEILLE["rss"] = rss
            if rss > _MEM_VEILLE["pic"]:
                _MEM_VEILLE["pic"] = rss
            ecart = rss - avant
            if abs(ecart) < _MEM_SEUIL_MO:
                continue        # rien a dire, on se tait
            msg = ("[MEM] %.0f Mo (%+.0f Mo en %d min) — %d fils — pic %.0f Mo"
                   % (rss, ecart, _MEM_CYCLE // 60, _th.active_count(),
                      _MEM_VEILLE["pic"]))
            if ecart > 0:
                # ON NE DETAILLE QU'A LA MONTEE. C'est le seul moment ou la
                # question « qui a pris cette memoire » a une reponse.
                msg += "\n[MEM]   conteneurs : " + _mem_gros_objets()
                g = _mem_globales()
                if g:
                    msg += "\n[MEM]   globales   : " + g
                t = _mem_traces()
                if t:
                    msg += "\n[MEM]   alloue par : " + t
            logging.warning(msg)
        except Exception as e:
            try:
                logging.info("[MEM] veille : %s" % str(e)[:120])
            except Exception:
                pass
            try:
                time.sleep(_MEM_CYCLE)
            except Exception:
                return


def mem_veille_demarrer() -> dict:
    """Arme la veille, et la trace detaillee si le reglage le demande.

    `tracemalloc` double a peu pres la memoire des traces : on ne soigne pas
    une consommation excessive avec un outil qui consomme. Il reste donc eteint
    par defaut, et s'allume par `memoire_traces` en configuration.
    """
    if _MEM_VEILLE["depuis"]:
        return {"ok": True, "deja": True}
    try:
        if str(get_cassandra_config().get("memoire_traces") or "").strip().lower() \
                in ("1", "true", "oui", "on"):
            import tracemalloc
            # DEUX NIVEAUX DE PILE, PAS SIX. Chaque niveau garde est paye en
            # memoire POUR CHAQUE ALLOCATION VIVANTE — et la lecture, qui
            # regroupe par ligne (`statistics("lineno")`), n'en emploie qu'un.
            # Le second sert a voir l'APPELANT : « une ligne de _query() » ne
            # dit rien sans savoir qui l'a appelee. Au-dela, on paierait un
            # detail qu'on ne lit jamais, sur la machine meme qu'on soulage.
            tracemalloc.start(2)
            _MEM_VEILLE["traces"] = True
    except Exception:
        pass
    _MEM_VEILLE["rss"] = _mem_rss_mo()
    _MEM_VEILLE["pic"] = _MEM_VEILLE["rss"]
    _MEM_VEILLE["depuis"] = time.time()
    t = threading.Thread(target=_mem_veille_boucle, daemon=True,
                         name="veille-memoire")
    t.start()
    logging.info("[MEM] Veille armée — départ à %.0f Mo, seuil %d Mo, "
                 "traces détaillées %s"
                 % (_MEM_VEILLE["rss"], _MEM_SEUIL_MO,
                    "ARMÉES" if _MEM_VEILLE["traces"] else "éteintes"))
    return {"ok": True, "rss": _MEM_VEILLE["rss"], "traces": _MEM_VEILLE["traces"]}


