def _mem_cfg(key, default):
    try:
        v = get_cassandra_config().get(key)
        if v is None:
            return default
        if isinstance(default, bool):
            return bool(v)
        return type(default)(v)
    except Exception:
        return default


# Interrupteurs de surveillance : ils existaient tous dans le code, pilotés par
