def reglages_veille_lire(famille: str = "") -> dict:
    """État des interrupteurs, filtrés par famille si demandé."""
    cfg = get_cassandra_config()
    out = []
    for cle, (defaut, fam, libelle, aide) in _REGLAGES_VEILLE.items():
        if famille and fam != famille:
            continue
        v = cfg.get(cle)
        out.append({"key": cle, "label": libelle, "help": aide, "famille": fam,
                    "value": bool(defaut if v is None else v),
                    "default": defaut, "explicite": v is not None})
    return {"ok": True, "reglages": sorted(out, key=lambda x: x["label"])}


def reglages_veille_ecrire(cle: str, valeur: bool, acteur: str = "") -> dict:
    """Change UN interrupteur. Refuse toute clé hors liste."""
    cle = (cle or "").strip()
    if cle not in _REGLAGES_VEILLE:
        return {"ok": False, "reason": "réglage inconnu ou non modifiable ici"}
    cfg = get_cassandra_config()
    cfg[cle] = bool(valeur)
    if not save_cassandra_config(cfg):
        return {"ok": False, "reason": "échec d'écriture de la configuration"}
    try:
        log_admin_action(acteur or "", "reglage_veille", "OK",
                         "%s=%s" % (cle, bool(valeur)))
    except Exception as e:
        logging.debug("[AUDIT] %s", e)
    return {"ok": True, "key": cle, "value": bool(valeur),
            "output": "%s : %s" % (_REGLAGES_VEILLE[cle][2],
                                   "activé" if valeur else "désactivé")}


def reglages_sante() -> dict:
    """Ce qui est configuré et ce qui ne l'est pas, famille par famille.

    Une pastille par famille : sans elle, il faut ouvrir les six pour découvrir
    qu'il manque une clé d'API. On ne dit JAMAIS la valeur d'un secret — sa
    présence suffit, et l'afficher serait le divulguer."""
    cfg = get_cassandra_config()
    def rempli(*cles):
        return any(str(cfg.get(k) or "").strip() for k in cles)
    fams = {}
    manques = []

    # ── Agents IA
    a = []
    # Noms de clés relevés dans la configuration réelle (`provider`, `model`,
    # `api_key`), pas devinés : une santé qui se trompe de clé annonce un
    # manque là où tout va bien.
    if not rempli("api_key", "itare_api_key"):
        a.append("aucune clé d'API — l'agent ne peut pas répondre")
    if not rempli("model"):
        a.append("modèle par défaut (aucun choix explicite)")
    try:
        _lm = str(cfg.get("lab_model") or "").strip()
        if _lm and ollama_available() and _lm not in {m["name"] for m in ollama_list()}:
            if rempli("itare_citadelle_model", "itare_model"):
                a.append("ancien modèle local courant (%s) absent d'Ollama — sans effet, à oublier" % _lm)
            else:
                a.append("modèle local courant (%s) absent d'Ollama" % _lm)
    except Exception as e:
        logging.debug("[SANTE] ollama : %s", e)
    fams["agents"] = a

    # ── Services tiers
    t = []
    if not mail_configured():
        t.append("courriel non configuré — aucune alerte ne partira")
    if not rempli("fastpanel_url", "fp_api_url"):
        t.append("panneau d'hébergement non renseigné")
    fams["tiers"] = t

    # ── Utilisateurs
    u = []
    try:
        comptes = load_users() or {}
        if not comptes:
            u.append("aucun compte — accès de secours seul")
        sans = [e for e, v in comptes.items()
                if _user_record(v)["role"] != "admin"
                and not _user_record(v)["sites"] and not _user_record(v)["fp_account"]]
        if sans:
            u.append("%d compte(s) sans aucun domaine" % len(sans))
    except Exception as e:
        logging.debug("[SANTE] comptes : %s", e)
    fams["users"] = u

    # ── Compte administrateur
    ad = []
    try:
        if not get_admin_password_hash():
            ad.append("aucun mot de passe administrateur")
    except Exception as e:
        logging.debug("[SANTE] admin : %s", e)
    # ── Surveillances : une veille éteinte est un choix, pas un défaut. On le
    # signale sans le peindre en rouge.
    v = []
    eteintes = [x["label"] for x in reglages_veille_lire("veille")["reglages"]
                if not x["value"]]
    if eteintes:
        v.append("%d surveillance(s) désactivée(s)" % len(eteintes))
    fams["veille"] = v

    # ── Système
    sy = []
    if bool(cfg.get("evolution_paused")):
        sy.append("auto-évolution suspendue")
    # le compte administrateur vit dans Système depuis la maquette du 16-09 : ses manques aussi
    fams["systeme"] = sy + ad
    # À l'écran, « Système » est devenu trois familles selon ce qu'on vient y faire :
    # la maintenance (ce qui tourne, et le mot de passe administrateur qui la garde),
    # les données (ce que la machine garde), les canaux (ce par quoi elle parle).
    fams["maintenance"] = sy + ad
    fams["donnees"] = []
    fams["canaux"] = []

    for f, lst in fams.items():
        manques.extend(lst)
    return {"ok": True,
            "familles": {f: {"alertes": lst, "etat": ("ok" if not lst else
                             ("info" if f in ("veille", "systeme") else "warn"))}
                         for f, lst in fams.items()},
            "total": len(manques)}


