def memory_set_config(params: dict) -> dict:
    allowed = ("memory_decay_halflife_days", "memory_promote_min_strength",
               "memory_archive_min_strength", "memory_dedup_threshold",
               "memory_extract_min_len", "embeddings_enabled", "itare_bash_enabled",
               "itare_review_enabled",
               # ── Itare autonome (tous OFF/safe par défaut) ──
               "itare_autonome_enabled", "itare_initiative_enabled", "itare_initiative_hours",
               "itare_autonome_interval_min",
               "itare_proactive_enabled", "itare_proactive_hours",
               "itare_projet_enabled", "itare_projet_hours",
               "itare_panel_enabled", "itare_panel_models",
               "itare_speculative_enabled", "itare_speculative_min_conf",
               "session_ttl_hours",
               "hybrid_enabled", "hybrid_min_conf", "chatlab_persona", "searxng_url",
               "plex_url", "plex_token",
               "lora_base_model", "lora_rank", "lora_epochs", "lora_lr", "lora_model_name",
               "contact_notes_to_remote", "fastpanel_url",
               # l'adresse de l'API du panneau est LUE par le moteur (fp_api_url) : le bouton l'envoyait,
               # la liste la jetait en silence — un réglage qui mentait (audit du 16-09)
               "fp_api_url", "vault_public_url", "notif_grace_min",
               # le renouvellement SSL automatique se règle depuis Hébergement › Certificats (19-09)
               "ssl_autorenew_enabled", "ssl_autorenew_days")
    cfg = get_cassandra_config()
    changed = {}
    for k in allowed:
        if k in (params or {}):
            # Le jeton Plex : vide veut dire « inchangé » (le champ de l'écran ne
            # le renvoie jamais), un tiret seul l'efface, et il ne ressort jamais
            # dans la réponse.
            if k == "plex_token":
                v = str(params[k] or "").strip()
                if not v:
                    continue
                cfg[k] = "" if v == "-" else v
                changed[k] = "(effacé)" if v == "-" else "(posé)"
                continue
            cfg[k] = params[k]
            changed[k] = params[k]
    if changed:
        try:
            # save_cassandra_config avale ses erreurs : seul son retour dit si le fichier est écrit.
            if not save_cassandra_config(cfg):
                return {"ok": False, "error": "config.json n'a pas pu être écrit"}
        except Exception as e:
            return {"ok": False, "error": str(e)}
    return {"ok": True, "updated": changed, "config": memory_get_config()}


def _tail_log(path: str, lines: int = 200, maxbytes: int = 131072) -> str:
    try:
        with open(path, "rb") as f:
            f.seek(0, 2)
            size = f.tell()
            f.seek(max(0, size - maxbytes))
            data = f.read().decode("utf-8", "replace")
        return "\n".join(data.splitlines()[-int(lines):])
    except Exception as e:
        return "(log indisponible : %s)" % e


def get_logs(source: str = "agent", lines: int = 200) -> dict:
    paths = {"agent": CASSANDRA_LOG_DIR + "/cassandra.log",
             "collector": CASSANDRA_LOG_DIR + "/cassandra-collector.log",
             "admin": globals().get("ADMIN_LOG_FILE", CASSANDRA_LOG_DIR + "/cassandra_admin.log")}
    p = paths.get(source, paths["agent"])
    return {"source": source, "path": p, "content": _tail_log(p, min(int(lines or 200), 1000))}


# ============================================================
# MOTEUR SÉMANTIQUE — embeddings locaux + recherche vectorielle (Phase 2)
# ============================================================
# Stockage illimité, prompt borné : on vectorise chaque mémoire et on récupère par
# similarité de SENS (top-K), pas par mots-clés. Dégradation gracieuse : si le modèle
# d'embeddings n'est pas installé, tout retombe proprement sur FTS5/mots-clés.

_EMBED_MODEL      = None
_EMBED_MODEL_NAME = ""
_EMBED_LOCK       = threading.Lock()
_EMBED_READY      = False
_EMBED_FAILED     = False
_EMBED_DIM        = 1024
# Cache matriciel en RAM pour une recherche vectorielle ULTRA-rapide (numpy),
# reconstruit quand le nb de mémoires change ou après 60s (évite de relire/parser
# les BLOBs + boucle Python à chaque requête → gros gain de perf sans perte de qualité).
_MEM_VEC = {"lock": threading.Lock(), "ids": None, "mat": None, "meta": None, "ts": 0.0, "count": -1}

def _get_embedder():
    """Charge le modèle d'embeddings local une seule fois (singleton).
    Renvoie None si indisponible → l'appelant retombe sur la recherche classique."""
    global _EMBED_MODEL, _EMBED_READY, _EMBED_FAILED, _EMBED_DIM
    if _EMBED_READY:
        return _EMBED_MODEL
    if _EMBED_FAILED:
        return None
    # KILL-SWITCH : le modèle d'embeddings (sentence-transformers + PyTorch, ~2,4 Go en RAM) est
    # DÉSACTIVÉ PAR DÉFAUT. Il ne gouverne PAS la mémoire (l'îlot rappelle par règles et plein texte) :
    # il sert les documents de projet d'Itare et la ressemblance des vœux de l'évolution. Réglage
    # `embeddings_enabled` (20-09) ; l'ancien nom `memory_semantic_enabled` reste lu en repli.
    try:
        if os.environ.get("CASSANDRA_DISABLE_EMBED") == "1" or not embeddings_reglage_actif():
            _EMBED_FAILED = True
            logging.info("[EMBED] Modèle d'embeddings désactivé (réglage embeddings_enabled) — projets et vœux en mots-clés.")
            return None
    except Exception:
        _EMBED_FAILED = True
        return None
    with _EMBED_LOCK:
        if _EMBED_READY:
            return _EMBED_MODEL
        if _EMBED_FAILED:
            return None
        try:
            # Limiter les threads torch : évite que le modèle monopolise tous les CPU
            # et étrangle les autres services (cause de lenteur générale).
            try:
                import torch
                torch.set_num_threads(int(os.environ.get("CASSANDRA_EMBED_THREADS", "2")))
            except Exception:
                pass
            from sentence_transformers import SentenceTransformer
            # Qualité maximale par défaut : modèle multilingue e5-large (1024 dim).
            # Surchargeable via config "memory_embed_model" ou env CASSANDRA_EMBED_MODEL.
            try:
                name = (get_cassandra_config().get("memory_embed_model") or "").strip()
            except Exception:
                name = ""
            name = name or os.environ.get("CASSANDRA_EMBED_MODEL", "intfloat/multilingual-e5-large")
            global _EMBED_MODEL_NAME
            _EMBED_MODEL = SentenceTransformer(name)
            _EMBED_MODEL_NAME = name
            try:
                _EMBED_DIM = int(getattr(_EMBED_MODEL, "get_embedding_dimension", None)
                                 or _EMBED_MODEL.get_sentence_embedding_dimension)()
            except Exception:
                pass
            _EMBED_READY = True
            logging.info("[EMBED] Modèle '%s' chargé (dim=%d, threads limités)" % (name, _EMBED_DIM))
            return _EMBED_MODEL
        except Exception as e:
            _EMBED_FAILED = True
            logging.warning("[EMBED] Embeddings indisponibles (%s) — repli FTS5/mots-clés" % e)
            return None

def embeddings_reglage_actif() -> bool:
    """Le réglage qui autorise le modèle d'embeddings : `embeddings_enabled`, ou l'ancien
    `memory_semantic_enabled` s'il est seul posé (un config.json d'avant continue de marcher)."""
    try:
        cfg = get_cassandra_config()
    except Exception:
        return False
    v = cfg.get("embeddings_enabled")
    if v is None:
        v = cfg.get("memory_semantic_enabled", False)
    return str(v).strip().lower() in ("1", "true", "oui", "on")


def embeddings_available() -> bool:
    return _get_embedder() is not None

# ── CACHE SÉMANTIQUE : les embeddings de REQUÊTE sont recalculés à chaque rappel
#    (e5-large = l'opération coûteuse). Une même requête revient souvent (reconstruction
#    du contexte, recherches répétées). LRU borné en RAM → latence coupée, zéro I/O. ──
_QUERY_EMBED_CACHE = {}
_QUERY_EMBED_ORDER = []
_QUERY_EMBED_CACHE_MAX = 256
_QUERY_EMBED_STATS = {"hits": 0, "misses": 0}


def embed_text(text: str, kind: str = "passage"):
    """Retourne un vecteur normalisé (list[float]) ou None si indisponible.
    kind='query' pour une recherche, 'passage' pour un souvenir stocké.
    Les modèles e5 EXIGENT ces préfixes pour donner leur pleine qualité.
    Les embeddings de requête sont mis en cache (LRU 256) — les passages, non
    (ils ne sont vectorisés qu'une fois à l'écriture)."""
    m = _get_embedder()
    if not m or not text:
        return None
    ck = None
    if kind == "query":
        ck = text[:512]
        hit = _QUERY_EMBED_CACHE.get(ck)
        if hit is not None:
            _QUERY_EMBED_STATS["hits"] += 1
            return hit
    try:
        t = text
        if "e5" in (_EMBED_MODEL_NAME or "").lower():
            t = ("query: " if kind == "query" else "passage: ") + text
        v = m.encode(t, normalize_embeddings=True)
        vec = [float(x) for x in v]
        if ck is not None:
            _QUERY_EMBED_STATS["misses"] += 1
            _QUERY_EMBED_CACHE[ck] = vec
            _QUERY_EMBED_ORDER.append(ck)
            if len(_QUERY_EMBED_ORDER) > _QUERY_EMBED_CACHE_MAX:
                old = _QUERY_EMBED_ORDER.pop(0)
                _QUERY_EMBED_CACHE.pop(old, None)
        return vec
    except Exception as e:
        logging.warning("[EMBED] encode échec: %s" % e)
        return None

def _vec_to_blob(vec):
    if not vec:
        return None
    return struct.pack("%df" % len(vec), *vec)

def _blob_to_vec(blob):
    if not blob:
        return None
    try:
        return list(struct.unpack("%df" % (len(blob) // 4), blob))
    except Exception:
        return None

def _cosine(a, b):
    """Vecteurs normalisés → produit scalaire = similarité cosinus."""
    if not a or not b or len(a) != len(b):
        return -1.0
    return sum(x * y for x, y in zip(a, b))



def start_embeddings_warmup():
    """Le modèle se charge-t-il d'office, ou au premier usage réel ?

    PAR DÉFAUT, AU PREMIER USAGE. Le charger vingt secondes après le démarrage
    immobilisait 2,4 Go que la session n'allait peut-être jamais employer —
    c'est ce qui a fait tomber la machine le 20 août, quand le modèle local
    d'Ollama a réclamé les 2,1 Go qui manquaient.

    Le réglage `memory_embed_prechargement` rétablit l'ancien comportement pour
    qui préfère payer la mémoire d'avance plutôt que d'attendre au premier
    rappel sémantique. Ce n'est pas un détail de goût : sur une machine plus
    large, précharger reste le bon choix.
    """
    # LE PRÉCHARGEMENT NE VECTORISE PLUS RIEN (20-09) : l'index sémantique de l'ancienne table est parti avec
    # elle. Le modèle ne sert plus qu'à la demande (documents de projet d'Itare, ressemblance des vœux de
    # l'évolution) : il se charge au premier usage, sauf si le réglage demande de le tenir chaud.
    def _precharge():
        time.sleep(20)
        _get_embedder()

    try:
        _pre = str(get_cassandra_config().get("memory_embed_prechargement")
                   or "").strip().lower() in ("1", "true", "oui", "on")
    except Exception:
        _pre = False
    if _pre:
        threading.Thread(target=_precharge, daemon=True, name="embeddings-warmup").start()
        logging.info("[EMBED] Préchargement ARMÉ (réglage memory_embed_prechargement) — ~2,4 Go dès le démarrage")
    else:
        logging.info("[EMBED] Chargement au PREMIER USAGE — ~2,4 Go économisés tant que rien ne demande de vecteur")


