def _memoire_sauvegarde_due(age_max_s: int = 24 * 3600) -> bool:
    """Vrai si la sauvegarde la plus récente a plus de `age_max_s` secondes — ou s'il n'y en a aucune."""
    try:
        derniere = max((p.stat().st_mtime for p in Path(MEMORY_BACKUP_DIR).glob("memory_*.db")), default=0.0)
    except Exception:
        derniere = 0.0
    return (time.time() - derniere) > age_max_s


def _memoire_sauvegarde_boucle() -> None:
    """LOT 0 (21-09). `_auto_backup_memory` n'était plus appelée par personne depuis l'îlot mémoire :
    plus aucune sauvegarde automatique depuis le 07/09 (mesuré par Cassandra au débat 2). Un fil de
    fond à cadence propre : une copie dès le démarrage si la dernière a plus d'un jour, puis une par
    jour. La rotation reste celle de `backup_memory_db` (MAX_BACKUPS)."""
    time.sleep(60)
    while True:
        try:
            if _memoire_sauvegarde_due():
                chemin = backup_memory_db()
                logging.info("[MEMORY] sauvegarde quotidienne : %s", chemin or "ÉCHEC")
        except Exception as e:
            logging.warning("[MEMORY] sauvegarde quotidienne : %s", e)
        time.sleep(600)


def _auto_backup_memory():
    global _memory_counter, _memory_last_backup
    _memory_counter += 1
    now = time.time()
    if _memory_counter >= 20 or (now - _memory_last_backup) > 3600:
        _memory_counter = 0
        _memory_last_backup = now
        threading.Thread(target=backup_memory_db, daemon=True).start()

def log_action(session_id: str, command: str, output: str,
               duration_ms: int, is_risky: bool = False, had_diff: bool = False) -> int:
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH)
        conn.execute(
            "INSERT INTO agent_actions (ts,session_id,command,output,duration_ms,is_risky,had_diff) "
            "VALUES (datetime('now'),?,?,?,?,?,?)",
            (session_id, command[:1000], output[:2000], duration_ms,
             1 if is_risky else 0, 1 if had_diff else 0))
        conn.commit()
        rc = conn.execute("SELECT last_insert_rowid()").fetchone()[0]
        conn.close()
        return rc
    except Exception:
        return 0


def get_actions(limit: int = 80) -> list:
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH)
        conn.row_factory = sqlite3.Row
        rows = conn.execute(
            "SELECT id,ts,session_id,command,output,duration_ms,is_risky,had_diff "
            "FROM agent_actions ORDER BY id DESC LIMIT ?", (limit,)).fetchall()
        conn.close()
        return [dict(r) for r in rows]
    except Exception:
        return []


