# ── Migration ────────────────────────────────────────────────────────────────
def _nt_colonnes(conn) -> None:
    """Les colonnes de la refonte, additives — chacune dans son propre essai.

    Pas par `_ALTER_REQUESTS` : ce lot est tout-ou-rien et court au démarrage, quand `notifs` peut ne pas
    exister encore (une base vide de V18). Ici la table est créée juste avant."""
    try:
        cols = {r[1] for r in conn.execute("PRAGMA table_info(notifs)")}
    except Exception:
        return
    for col, sql in (("compte", "compte TEXT DEFAULT ''"),
                     ("nature", "nature TEXT DEFAULT 'evenement'"),
                     ("destinataires", "destinataires TEXT DEFAULT ''"),
                     ("sonde", "sonde TEXT DEFAULT ''"),
                     ("sonde_etat", "sonde_etat TEXT DEFAULT ''"),
                     ("precedente", "precedente INTEGER DEFAULT 0"),
                     ("expire_le", "expire_le TEXT DEFAULT ''"),
                     ("provenance", "provenance TEXT DEFAULT 'interne'")):
        if col in cols:
            continue
        try:
            conn.execute("ALTER TABLE notifs ADD COLUMN " + sql)
        except Exception as e:
            logging.warning("[NOTIF] colonne %s : %s", col, e)


def _nt_migrer_vide(conn) -> None:
    """LA MIGRATION DU VIDE (débat, tour 27). `compte = ''` voulait dire « tout le monde » ; les 182 lignes
    adoptées par le premier admin portaient son nom. Désormais chaque ligne dit À QUI elle s'adresse, et
    `compte` est GELÉ sur '*' — plus jamais lu pour décider. Mesurée : elle ne touche que les lignes sans
    destinataire, donc une seule fois."""
    try:
        n = conn.execute("SELECT COUNT(*) FROM notifs WHERE destinataires IS NULL OR destinataires = ''"
                         ).fetchone()[0]
    except Exception:
        return
    if not n:
        return
    conn.execute("UPDATE notifs SET destinataires = CASE WHEN compte IS NULL OR compte IN ('', '*') "
                 "THEN '[\"admins\"]' ELSE '[\"compte:' || compte || '\"]' END "
                 "WHERE destinataires IS NULL OR destinataires = ''")
    conn.execute("UPDATE notifs SET compte = '*' WHERE compte IS NULL OR compte = ''")
    # Les natures de ce qui existait déjà : les découvertes de la proactivité sont des décisions (fermées
    # par leur passe), les rapports de veille se referment — ils quittent la cloche —, et les écarts de
    # mesure écrits sous deux sources par le même écrivain se referment aussi : la passe suivante les
    # ré-émet sous « mesure », avec un sujet et une sonde.
    conn.execute("UPDATE notifs SET nature = 'decision' WHERE cle LIKE 'pf:%'")
    conn.execute("UPDATE notifs SET nature = 'rapport' WHERE source = 'veille'")
    conn.execute("UPDATE notifs SET resolue = 1, niveau = 'regle', resolue_le = datetime('now'), "
                 "resolue_par = 'refonte : rapport hors cloche' "
                 "WHERE source = 'veille' AND resolue = 0")
    conn.execute("UPDATE notifs SET resolue = 1, niveau = 'regle', resolue_le = datetime('now'), "
                 "resolue_par = 'refonte : ré-émis sous mesure' "
                 "WHERE resolue = 0 AND titre LIKE '%hors de l''ordinaire%'")
    conn.execute("UPDATE notifs SET nature = 'etat' WHERE resolue = 0 AND nature = 'evenement' "
                 "AND source IN ('systeme', 'site', 'certificat', 'sauvegarde', 'automatisme')")
    logging.info("[NOTIF] migration du vide : %d ligne(s) ont reçu un destinataire", n)


def _nt_migrer_sondes(conn) -> None:
    """Les états ouverts d'avant la refonte n'avaient pas de sonde : rien ne pouvait les refermer (id 699,
    « RAM élevée », mesuré après le lot A). Elle se déduit du SUJET — jamais du titre — et seulement pour les
    familles que le moteur de seuils écrit encore sous ce sujet. Idempotente : ne touche que le vide."""
    try:
        rows = conn.execute("SELECT id, source, sujet FROM notifs WHERE resolue = 0 AND nature = 'etat' "
                            "AND (sonde IS NULL OR sonde = '') AND sujet <> ''").fetchall()
    except Exception:
        return
    n = 0
    for nid, source, sujet in rows:
        sujet = str(sujet or "")
        sonde = ""
        if sujet in ("memory", "ram"):
            sonde = "seuil:ram"
        elif sujet == "load" or sujet.startswith("disk"):
            sonde = "seuil:%s" % sujet
        elif sujet.startswith("service:"):
            sonde = sujet
        elif source == "certificat":
            sonde = "ssl:%s" % sujet
        elif source == "site":
            sonde = "site:%s" % sujet
        if sonde:
            conn.execute("UPDATE notifs SET sonde = ? WHERE id = ?", (sonde, nid))
            n += 1
    if n:
        logging.info("[NOTIF] migration des sondes : %d état(s) ouvert(s) ont reçu leur sonde", n)


def _nt_migrate():
    if _NT_MIGRE[0]:
        return
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        conn.execute("CREATE TABLE IF NOT EXISTS notifs ("
                     "id INTEGER PRIMARY KEY AUTOINCREMENT, "
                     "ts TEXT DEFAULT (datetime('now')), maj TEXT DEFAULT (datetime('now')), "
                     "source TEXT DEFAULT 'veille', niveau TEXT DEFAULT 'info', "
                     "titre TEXT DEFAULT '', corps TEXT DEFAULT '', "
                     "cle TEXT DEFAULT '', n INTEGER DEFAULT 1, "
                     "sujet TEXT DEFAULT '', "
                     "lu INTEGER DEFAULT 0, resolue INTEGER DEFAULT 0, "
                     "resolue_le TEXT DEFAULT '', resolue_par TEXT DEFAULT '', "
                     "duree_min INTEGER DEFAULT 0)")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_notifs ON notifs(resolue, id DESC)")
        # Le regroupement est une CONTRAINTE : deux passages de veille simultanés
        # ne doivent pas produire deux lignes pour le même incident.
        conn.execute("CREATE UNIQUE INDEX IF NOT EXISTS idx_notifs_cle ON notifs(cle) "
                     "WHERE cle <> '' AND resolue = 0")
        _nt_colonnes(conn)
        conn.execute("CREATE INDEX IF NOT EXISTS idx_notifs_precedente ON notifs(precedente)")
        # L'ÉTAT PAR PERSONNE : vu, acquitté. Une ligne par (notification, compte) — jamais une par admin à
        # l'écriture, sinon un admin arrivé plus tard ne voit rien (le bug des 182, tour 9).
        conn.execute("CREATE TABLE IF NOT EXISTS notif_dest (notif INTEGER, compte TEXT, "
                     "vu_le TEXT DEFAULT '', acquitte_le TEXT DEFAULT '', PRIMARY KEY (notif, compte))")
        conn.execute("CREATE TABLE IF NOT EXISTS notif_politique (compte TEXT, niveau TEXT, "
                     "canaux TEXT DEFAULT '[]', PRIMARY KEY (compte, niveau))")
        conn.execute("CREATE TABLE IF NOT EXISTS notif_sourdines (id INTEGER PRIMARY KEY AUTOINCREMENT, "
                     "compte TEXT, portee TEXT, cible TEXT, fin TEXT, "
                     "posee_le TEXT DEFAULT (datetime('now')), retenues INTEGER DEFAULT 0)")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_notif_sourdines ON notif_sourdines(compte, fin)")
        conn.execute("CREATE TABLE IF NOT EXISTS notif_retenues (id INTEGER PRIMARY KEY AUTOINCREMENT, "
                     "notif INTEGER, compte TEXT, canal TEXT, raison TEXT, "
                     "retenue_le TEXT DEFAULT (datetime('now')))")
        conn.execute("CREATE TABLE IF NOT EXISTS notif_essais (canal TEXT PRIMARY KEY, ts TEXT, "
                     "ok INTEGER DEFAULT 0, detail TEXT DEFAULT '')")
        # L'ancienne table de réglages par source reste en place, plus lue : elle tombe au nettoyage.
        conn.execute("CREATE TABLE IF NOT EXISTS notif_reglages ("
                     "source TEXT PRIMARY KEY, seuil TEXT DEFAULT 'avoir', "
                     "email INTEGER DEFAULT 0, webhook INTEGER DEFAULT 0, "
                     "sourdine_fin TEXT DEFAULT '', sourdine_depuis TEXT DEFAULT '', "
                     "retenues INTEGER DEFAULT 0)")
        conn.commit()
        _nt_reprendre(conn)
        _nt_migrer_vide(conn)
        _nt_migrer_sondes(conn)
        conn.commit()
        conn.close()
        _NT_MIGRE[0] = True
        _nt_reprendre_ouvertes()
    except Exception as e:
        logging.warning("[NOTIF] migration : %s", e)


def _nt_reprendre_ouvertes() -> None:
    """Appelé après la migration : les découvertes ouvertes avant l'arrivée du
    centre n'avaient jamais notifié, et la pastille du menu comptait une chose que
    la cloche ignorait."""
    try:
        pf_reprendre_ouvertes()
    except Exception as e:
        logging.info("[NOTIF] reprise des découvertes ouvertes : %s", e)


def _nt_reprendre(conn) -> None:
    """Reprend les deux anciennes tables, une seule fois — la marque est dans `cle`.

    Les alertes de seuil deviennent des lignes « systeme » ; le flux de veille, des rapports refermés :
    la déduction par titre n'existe plus, on ne devine pas rétroactivement ce que l'écrivain voulait."""
    try:
        deja = conn.execute("SELECT COUNT(*) FROM notifs WHERE cle LIKE 'repris:%'"
                            ).fetchone()[0]
    except Exception:
        return
    if deja:
        return
    n = 0
    try:
        for r in conn.execute("SELECT id, ts, level, category, message, resolved, resolved_at "
                              "FROM alerts ORDER BY id").fetchall():
            niveau = "critique" if str(r[2]) == "critical" else "avoir"
            conn.execute(
                "INSERT OR IGNORE INTO notifs (ts, maj, source, niveau, titre, corps, cle, "
                "sujet, resolue, resolue_le, resolue_par, nature, destinataires, compte) "
                "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                (r[1], r[1], "systeme", "regle" if r[5] else niveau, str(r[4])[:200], "",
                 "repris:alerte:%s" % r[0], str(r[3] or ""), 1 if r[5] else 0,
                 r[6] or "", "reprise" if r[5] else "", "etat", '["admins"]', _NT_MACHINE))
            n += 1
    except Exception as e:
        logging.info("[NOTIF] reprise des alertes : %s", e)
    try:
        for r in conn.execute("SELECT id, ts, title, body, seen FROM itare_proactive_feed "
                              "ORDER BY id").fetchall():
            conn.execute(
                "INSERT OR IGNORE INTO notifs (ts, maj, source, niveau, titre, corps, cle, "
                "lu, resolue, resolue_le, resolue_par, nature, destinataires, compte) "
                "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                (r[1], r[1], "veille", "regle", str(r[2])[:200], str(r[3] or "")[:1500],
                 "repris:veille:%s" % r[0], 1, 1, r[1], "reprise", "rapport", '["admins"]',
                 _NT_MACHINE))
            n += 1
    except Exception as e:
        logging.info("[NOTIF] reprise du flux de veille : %s", e)
    if n:
        conn.commit()
        logging.info("[NOTIF] %d notification(s) reprises des deux anciennes tables", n)


# ── Les destinataires ─────────────────────────────────────────────────────────
def _nt_dests_normaliser(dest, src: dict = None) -> list:
    """L'INTENTION symbolique, résolue à la lecture : « admins », « compte:<email> », « resident:<nom> ».
    Une adresse nue devient « compte:<adresse> ». Vide = les administrateurs."""
    if dest is None:
        dest = []
    elif isinstance(dest, str):
        dest = [dest]
    out = []
    for d in dest:
        d = str(d or "").strip()
        if not d:
            continue
        dl = d.lower()
        if dl in ("admins", "admin", "administrateurs"):
            d = "admins"
        elif dl.startswith("compte:") or dl.startswith("resident:"):
            d = dl
        elif "@" in d:
            d = "compte:" + dl
        else:
            d = "resident:" + dl
        if d not in out:
            out.append(d)
    if not out:
        out = [str((src or {}).get("dest") or "admins")]
    return out


def _nt_dests_lire(brut) -> list:
    try:
        v = json.loads(brut) if isinstance(brut, str) and brut else (brut or [])
        return [str(x) for x in v] if isinstance(v, list) else ["admins"]
    except Exception:
        return ["admins"]


def _nt_admins() -> list:
    try:
        return sorted(e for e in load_users() if user_role(e) == "admin")
    except Exception:
        return []


def _nt_destinataires_humains(dests) -> list:
    """Les comptes humains visés : « admins » se déplie ICI, à la lecture, jamais à l'écriture."""
    comptes = set()
    for d in dests or []:
        if d == "admins":
            comptes.update(_nt_admins())
        elif d.startswith("compte:") and d[7:]:
            comptes.add(d[7:].lower())
    return sorted(comptes)


def _nt_filtre_dest(compte: str, admin: bool):
    """La condition SQL qui borne la lecture à ce que ce compte a le droit de voir.

    Un agent (compte vide) voit tout. Un admin voit ce qui vise les admins, ce qui le vise, et les lignes
    des résidents (transparence). Un compte ordinaire ne voit que ce qui le vise nommément —
    jamais la machine."""
    if not compte:
        return "", []
    moi = '%"compte:' + compte.lower() + '"%'
    if admin:
        return (" AND (destinataires LIKE '%\"admins\"%' OR destinataires LIKE ? "
                "OR destinataires LIKE '%\"resident:%')", [moi])
    return " AND destinataires LIKE ?", [moi]


def _nt_expiration(nature: str, niveau: str) -> str:
    """Un événement « info » s'efface seul au bout de sept jours ; un état tenace tombe à trente
    (Cassandra, tour 23 : « avoir / critique / décision / état : jamais seuls » était trop absolu)."""
    try:
        if nature == "evenement" and niveau == "info":
            j = int(_mem_cfg("notif_expire_info_j", 7) or 7)
        elif nature == "etat":
            j = int(_mem_cfg("notif_expire_etat_j", 30) or 30)
        else:
            return ""
        return (_utcnow() + timedelta(days=max(1, j))).strftime("%Y-%m-%d %H:%M:%S")
    except Exception:
        return ""


# ── Écriture ────────────────────────────────────────────────────────────────
def notif(titre: str, corps: str = "", source: str = "", niveau: str = "",
          sujet: str = "", cle: str = "", nature: str = "", dest=None, sonde: str = "",
          provenance: str = "interne", **_k) -> dict:
    """Enregistre une notification. Point d'entrée unique — et exigeant.

    PLUS DE DÉDUCTION PAR TITRE (tour 14, B29) : un objet de courrier extérieur qui disait « échec »
    fabriquait une critique « sécurité » armée de « Révoquer les sessions ». La source est déclarée par
    l'écrivain ou l'appel est REFUSÉ, en le disant. Le niveau hors liste retombe sur celui de la source,
    en le disant aussi. Une même `cle` non résolue INCRÉMENTE au lieu d'insérer ; une clé qui rouvre après
    fermeture crée une nouvelle ligne qui pointe la précédente (l'index unique partiel survit)."""
    _nt_migrate()
    src = _NOTIF_SOURCES.get(str(source or ""))
    if not src:
        logging.warning("[NOTIF] écrivain sans source refusé : « %s » (source=%r)", str(titre)[:80], source)
        return {"ok": False, "reason": "source non déclarée"}
    nature = str(nature or src.get("nature") or "evenement")
    if nature not in _NT_NATURES:
        nature = src.get("nature", "evenement")
    if nature == "rapport":
        return {"ok": True, "rapport": True, "source": source}
    if niveau not in _NT_NIVEAUX:
        if niveau:
            logging.warning("[NOTIF] niveau inconnu « %s » pour « %s » : celui de la source (%s)",
                            niveau, str(titre)[:60], src.get("niveau", "avoir"))
        niveau = src.get("niveau", "avoir")
    sujet = str(sujet or "")[:120]
    if not cle:
        if sujet:
            cle = "%s:%s" % (source, sujet)
        else:
            cle = "%s:%s" % (source, re.sub(r"\d+", "#", str(titre))[:60])
            logging.info("[NOTIF] clé fabriquée depuis le titre pour « %s » : aucun geste ne pourra la viser",
                         str(titre)[:60])
    dests = _nt_dests_normaliser(dest, src)
    provenance = "externe" if str(provenance or "") == "externe" else "interne"
    expire = _nt_expiration(nature, niveau)
    groupe, monte, precedente, nid = False, False, 0, 0
    for _essai in range(3):
        try:
            conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
            conn.row_factory = sqlite3.Row
            ouverte = conn.execute("SELECT id, niveau FROM notifs WHERE cle = ? AND resolue = 0",
                                   (cle,)).fetchone()
            if ouverte:
                groupe = True
                nid = int(ouverte["id"])
                monte = _NT_RANG.get(niveau, 9) < _NT_RANG.get(ouverte["niveau"], 9)
                # Un ÉTAT se dit au présent : son titre suit la dernière mesure (10-10 — « Trivy : 11 critiques »
                # restait affiché quand il n'y en avait plus que 8). Un événement garde son premier titre, le ×N compte.
                conn.execute(
                    "UPDATE notifs SET n = n + 1, maj = datetime('now'), corps = ?, niveau = ?, lu = 0, "
                    "titre = CASE WHEN ? = 'etat' AND ? <> '' THEN ? ELSE titre END, "
                    "expire_le = CASE WHEN ? <> '' THEN ? ELSE expire_le END, "
                    "sonde = CASE WHEN ? <> '' THEN ? ELSE sonde END WHERE id = ?",
                    (str(corps or "")[:1500], niveau, nature, str(titre or ""), str(titre or "")[:200],
                     expire, expire, sonde, sonde, nid))
                if monte:
                    # Une montée en gravité efface le « vu » : ce n'est plus la même chose qu'on a lue.
                    conn.execute("UPDATE notif_dest SET vu_le = '', acquitte_le = '' WHERE notif = ?", (nid,))
            else:
                prec = conn.execute("SELECT id FROM notifs WHERE cle = ? AND resolue = 1 "
                                    "ORDER BY id DESC LIMIT 1", (cle,)).fetchone()
                precedente = int(prec["id"]) if prec else 0
                cur = conn.execute(
                    "INSERT INTO notifs (source, niveau, titre, corps, cle, sujet, compte, nature, "
                    "destinataires, sonde, sonde_etat, precedente, expire_le, provenance) "
                    "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                    (source, niveau, str(titre or "")[:200], str(corps or "")[:1500],
                     cle, sujet, _NT_MACHINE, nature, json.dumps(dests, ensure_ascii=False),
                     str(sonde or "")[:120], "", precedente, expire, provenance))
                nid = int(cur.lastrowid)
            # Les résolues se gardent par le TEMPS (90 jours), plus par le compte : 300 lignes ne
            # disaient rien de la durée d'un historique.
            conn.execute("DELETE FROM notifs WHERE resolue = 1 AND resolue_le <> '' "
                         "AND resolue_le < datetime('now', ?)",
                         ("-%d days" % max(7, int(_mem_cfg("notif_retention_j", 90) or 90)),))
            conn.commit(); conn.close()
            break
        except Exception as e:
            try:
                conn.close()
            except Exception:
                pass
            if "locked" in str(e).lower() and _essai < 2:
                time.sleep(2 + 2 * _essai)
                continue
            logging.warning("[NOTIF] écriture : %s", e)
            return {"ok": False, "reason": str(e)}
    ligne = {"id": nid, "source": source, "niveau": niveau, "titre": str(titre or "")[:200],
             "corps": str(corps or "")[:1500], "cle": cle, "sujet": sujet, "nature": nature,
             "destinataires": dests, "provenance": provenance}
    # UN CANAL NE PART QU'À L'OUVERTURE ET À LA MONTÉE EN GRAVITÉ (B12) : un site qui clignote envoyait
    # un mail par passage.
    if not groupe or monte:
        try:
            _nt_canaux(ligne, monte=monte)
        except Exception as e:
            logging.info("[NOTIF] canaux : %s", e)
    _nt_pousser(nid, "maj" if groupe else ("rouvre" if precedente else "ouvre"))
    return {"ok": True, "id": nid, "source": source, "niveau": niveau, "groupe": groupe, "cle": cle,
            "monte": monte, "rouvert": bool(precedente), "nature": nature}


def _nt_pousser(nid: int, op: str) -> None:
    """Pousse la ligne aux écrans qui l'écoutent, si le WebSocket sait à qui parler (étape 3)."""
    try:
        f = globals().get("_ws_pousser_notif")
        if f and nid:
            f(int(nid), op)
    except Exception as e:
        logging.info("[NOTIF] poussée : %s", e)


def notif_resoudre_cle(cle: str, par: str = "auto", detail: str = "", verrou_s: float = 10.0, essais: int = 3) -> int:
    """Ferme une notification dont la cause a disparu.

    Une alerte qui reste active après que le problème s'est réglé apprend à
    ignorer la cloche — c'est le pire état possible pour une alerte.

    UN VERROU N'EST PAS UNE RÉPONSE (15-09) : au démarrage de 04:02, « database is locked » — un seul
    essai, l'échec écrit en INFO, et la connexion laissée OUVERTE quand la requête levait (le close
    n'était atteint qu'en cas de succès). L'alerte restait active sans que personne le sache. Trois
    essais espacés sur un verrou ; la connexion toujours fermée ; l'échec final dit en WARNING."""
    _nt_migrate()
    derniere = None
    for essai in range(max(1, essais)):
        conn = None
        try:
            conn = sqlite3.connect(MEMORY_DB_PATH, timeout=verrou_s)
            # Ce qui va être fermé, pour prévenir l'écran et retirer les messages Telegram. Facultatif : rien de ce qui
            # suit la fermeture ne doit pouvoir l'empêcher.
            try:
                fermees = conn.execute("SELECT id, COALESCE(titre, '') FROM notifs WHERE cle = ? AND resolue = 0", (cle,)).fetchall()
            except Exception:
                fermees = []
            cur = conn.execute(
                "UPDATE notifs SET resolue = 1, niveau = 'regle', resolue_le = datetime('now'), "
                "resolue_par = ?, corps = CASE WHEN ? <> '' THEN ? ELSE corps END, "
                "duree_min = CAST((julianday('now') - julianday(ts)) * 1440 AS INTEGER) "
                "WHERE cle = ? AND resolue = 0", (par, detail, detail, cle))
            conn.commit()
            # 08-10 : fermée ici, l'écran ne le savait qu'au rechargement et Telegram jamais — la notification
            # périmée restait dans la conversation. L'écran est prévenu, le message retiré.
            _apres = globals().get("_nt_apres_fermeture")
            if cur.rowcount and fermees and callable(_apres):
                try:
                    _apres([(r[0], r[1]) for r in fermees])
                except Exception as _e:
                    logging.info("[NOTIF] après fermeture de « %s » : %s", cle, _e)
            return cur.rowcount
        except sqlite3.OperationalError as e:
            derniere = e
            if "locked" not in str(e).lower() and "busy" not in str(e).lower():
                break
            if essai < max(1, essais) - 1:
                time.sleep(min(4.0, 0.5 * (2 ** essai)))
        except Exception as e:
            derniere = e
            break
        finally:
            if conn is not None:
                try:
                    conn.close()
                except Exception:
                    pass
    logging.warning("[NOTIF] résolution impossible pour « %s » (%s) : l'alerte reste active", cle, derniere)
    return 0


def notif_resoudre(nid, par: str = "vous", detail: str = "") -> dict:
    """La fermeture à la main d'un ÉTAT (un événement s'acquitte, une décision se ferme par son geste)."""
    _nt_migrate()
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        cur = conn.execute("UPDATE notifs SET resolue = 1, niveau = 'regle', "
                           "resolue_le = datetime('now'), resolue_par = ?, "
                           "corps = CASE WHEN ? <> '' THEN ? ELSE corps END, "
                           "duree_min = CAST((julianday('now') - julianday(ts)) * 1440 AS INTEGER) "
                           "WHERE id = ? AND resolue = 0", (par, detail, detail, int(nid)))
        conn.commit(); conn.close()
        if cur.rowcount:
            _nt_apres_fermeture([(int(nid), "")])
        return {"ok": True, "fermee": bool(cur.rowcount)}
    except Exception as e:
        return {"ok": False, "reason": str(e)}


def notif_vu(ids, compte: str) -> dict:
    """« Vu » est PAR COMPTE : chacun sa lecture, une table à part (tour 4 c, tour 9)."""
    _nt_migrate()
    compte = (compte or "").strip().lower()
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        if ids:
            liste = [int(i) for i in ids]
        else:
            filtre, args = _nt_filtre_dest(compte, is_admin(compte) if compte else True)
            liste = [r[0] for r in conn.execute("SELECT id FROM notifs WHERE resolue = 0" + filtre, args)]
        for i in liste:
            if compte:
                conn.execute("INSERT INTO notif_dest (notif, compte, vu_le) VALUES (?,?,datetime('now')) "
                             "ON CONFLICT(notif, compte) DO UPDATE SET vu_le = datetime('now')", (i, compte))
            conn.execute("UPDATE notifs SET lu = 1 WHERE id = ?", (i,))   # compat : l'ancienne colonne
        conn.commit(); conn.close()
        return {"ok": True, "vues": len(liste)}
    except Exception as e:
        return {"ok": False, "reason": str(e)}


def notif_acquitter(nid, compte: str) -> dict:
    """Acquitter : j'ai pris connaissance. Un ÉVÉNEMENT se ferme là ; une DÉCISION reste jusqu'au geste ;
    un ÉTAT reste jusqu'à sa sonde — mais plus rien ne me le compte comme « à faire »."""
    _nt_migrate()
    compte = (compte or "").strip().lower()
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10); conn.row_factory = sqlite3.Row
        r = conn.execute("SELECT id, nature FROM notifs WHERE id = ?", (int(nid),)).fetchone()
        if not r:
            conn.close()
            return {"ok": False, "reason": "notification introuvable"}
        if compte:
            conn.execute("INSERT INTO notif_dest (notif, compte, vu_le, acquitte_le) "
                         "VALUES (?,?,datetime('now'),datetime('now')) "
                         "ON CONFLICT(notif, compte) DO UPDATE SET vu_le = datetime('now'), "
                         "acquitte_le = datetime('now')", (int(nid), compte))
        conn.execute("UPDATE notifs SET lu = 1 WHERE id = ?", (int(nid),))
        fermee = False
        if r["nature"] == "evenement":
            cur = conn.execute("UPDATE notifs SET resolue = 1, niveau = 'regle', resolue_le = datetime('now'), "
                               "resolue_par = ?, duree_min = CAST((julianday('now') - julianday(ts)) * 1440 "
                               "AS INTEGER) WHERE id = ? AND resolue = 0", ("acquitté par %s" % (compte or "vous"),
                                                                            int(nid)))
            fermee = bool(cur.rowcount)
        conn.commit(); conn.close()
        _nt_pousser(int(nid), "ferme" if fermee else "maj")
        return {"ok": True, "nature": r["nature"], "fermee": fermee}
    except Exception as e:
        return {"ok": False, "reason": str(e)}


def notif_lues(ids=None) -> dict:
    """Compat : l'ancien « Tout lire » — devient « vu » pour le compte courant."""
    try:
        compte = get_current_user() or ""
    except Exception:
        compte = ""
    return notif_vu(ids, compte)


def notif_supprimer(ids=None, reglees: bool = False) -> dict:
    """Efface pour de bon — et seulement de l'HISTORIQUE. Une ligne ouverte se résout ou s'acquitte,
    elle ne s'efface pas : effacer une panne en cours, c'est se rendre aveugle."""
    _nt_migrate()
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        if reglees:
            cur = conn.execute("DELETE FROM notifs WHERE resolue = 1")
        elif ids:
            cur = conn.execute("DELETE FROM notifs WHERE resolue = 1 AND id IN (%s)"
                               % ",".join("?" * len(ids)), [int(i) for i in ids])
        else:
            conn.close()
            return {"ok": False, "reason": "rien à supprimer"}
        n = cur.rowcount
        conn.execute("DELETE FROM notif_dest WHERE notif NOT IN (SELECT id FROM notifs)")
        conn.commit(); conn.close()
        return {"ok": True, "supprimees": n}
    except Exception as e:
        return {"ok": False, "reason": str(e)}


# ── Lecture ─────────────────────────────────────────────────────────────────
def _nt_aller(src: dict, sujet: str):
    a = list(src.get("aller") or (None, None, None))
    while len(a) < 3:
        a.append(None)
    if a[2] == _NT_SUJET_SPECIAL:
        a[2] = sujet or None
        if not sujet:
            a[1] = None
    return a


def _nt_actions(src: dict, sujet: str) -> list:
    """Les actions qui ont un SENS pour ce sujet — aucune sans sujet (B7)."""
    if not sujet:
        return []
    out = []
    for a in src.get("actions", []):
        if len(a) > 3 and a[3] and not any(sujet.startswith(p) for p in a[3]):
            continue
        out.append({"cle": a[0], "nom": a[1], "quoi": a[2]})
    return out


def _nt_rouvert(conn, nid: int) -> int:
    try:
        return int(conn.execute(
            "WITH RECURSIVE ch(id) AS (SELECT precedente FROM notifs WHERE id = ? "
            "UNION ALL SELECT n.precedente FROM notifs n JOIN ch ON n.id = ch.id WHERE n.precedente > 0) "
            "SELECT COUNT(*) FROM ch WHERE id > 0", (nid,)).fetchone()[0])
    except Exception:
        return 0


def _nt_enrichir(conn, d: dict, compte: str) -> dict:
    src = _NOTIF_SOURCES.get(d.get("source")) or _NOTIF_SOURCES["systeme"]
    sujet = str(d.get("sujet") or "")
    d["source_nom"] = src["nom"]
    d["couleur"] = src["c"]
    d["nature"] = d.get("nature") or src.get("nature", "evenement")
    d["aller"] = _nt_aller(src, sujet)
    d["actions"] = _nt_actions(src, sujet)
    d["destinataires"] = _nt_dests_lire(d.get("destinataires"))
    d["vu"] = bool(d.get("vu_le")) if compte else bool(d.get("lu"))
    d["acquitte"] = bool(d.get("acquitte_le"))
    d["rouvert"] = _nt_rouvert(conn, int(d["id"])) if d.get("precedente") else 0
    d["sonde_vue"] = _NT_SONDE_VUE.get(str(d.get("sonde") or "").split(":", 1)[0], "")
    d.pop("vu_le", None); d.pop("acquitte_le", None)
    return d


def notif_compteurs(compte: str = None, admin: bool = None) -> dict:
    """Des COUNT SQL, jamais un décompte sur les lignes rendues (B16, B21)."""
    _nt_migrate()
    if compte is None:
        try:
            compte = get_current_user() or ""
        except Exception:
            compte = ""
    compte = (compte or "").strip().lower()
    if admin is None:
        admin = True if not compte else is_admin(compte)
    filtre, args = _nt_filtre_dest(compte, admin)
    out = {"a_faire": 0, "en_cours": 0, "critiques": 0, "non_vues": 0, "total": 0, "historique": 0}
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        base = "SELECT COUNT(*) FROM notifs n WHERE resolue = 0" + filtre
        out["total"] = conn.execute(base, args).fetchone()[0]
        out["critiques"] = conn.execute(base + " AND niveau = 'critique'", args).fetchone()[0]
        out["a_faire"] = conn.execute(
            base + " AND (niveau = 'critique' OR nature IN ('decision','evenement'))", args).fetchone()[0]
        out["en_cours"] = conn.execute(
            base + " AND nature = 'etat' AND niveau <> 'critique'", args).fetchone()[0]
        if compte:
            out["non_vues"] = conn.execute(
                base + " AND NOT EXISTS (SELECT 1 FROM notif_dest d WHERE d.notif = n.id AND d.compte = ? "
                "AND d.vu_le <> '')", args + [compte]).fetchone()[0]
        else:
            out["non_vues"] = conn.execute(base + " AND lu = 0", args).fetchone()[0]
        out["historique"] = conn.execute("SELECT COUNT(*) FROM notifs n WHERE resolue = 1" + filtre,
                                         args).fetchone()[0]
        conn.close()
    except Exception as e:
        logging.info("[NOTIF] compteurs : %s", e)
    return out


def notifs(limit: int = 40, tout: bool = False, vue: str = "", compte: str = None, admin: bool = None,
           depuis: int = 0) -> dict:
    """Ce que CE compte a le droit de voir, dans la vue demandée : « a_faire », « en_cours »,
    « historique », ou tout ce qui est ouvert. Le filtre est celui des destinataires — jamais l'écrivain,
    jamais `compte`. Les compteurs viennent de la table entière, pas de la page."""
    _nt_migrate()
    if compte is None:
        try:
            compte = get_current_user() or ""
        except Exception:
            compte = ""
    compte = (compte or "").strip().lower()
    if admin is None:
        admin = True if not compte else is_admin(compte)
    filtre, args = _nt_filtre_dest(compte, admin)
    out = []
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10); conn.row_factory = sqlite3.Row
        if vue == "a_faire":
            ou = " AND n.resolue = 0 AND (n.niveau = 'critique' OR n.nature IN ('decision','evenement'))"
            ordre = "ORDER BY CASE n.niveau WHEN 'critique' THEN 0 WHEN 'avoir' THEN 1 ELSE 2 END, n.id DESC"
        elif vue == "en_cours":
            ou = " AND n.resolue = 0 AND n.nature = 'etat' AND n.niveau <> 'critique'"
            ordre = "ORDER BY n.maj DESC"
        elif vue == "historique":
            ou = " AND n.resolue = 1"
            ordre = "ORDER BY n.resolue_le DESC, n.id DESC"
        else:
            ou = "" if tout else " AND n.resolue = 0"
            ordre = ("ORDER BY CASE n.niveau WHEN 'critique' THEN 0 WHEN 'avoir' THEN 1 WHEN 'info' THEN 2 "
                     "ELSE 3 END, n.id DESC")
        if depuis:
            ou += " AND n.id < %d" % int(depuis)
        q = ("SELECT n.*, d.vu_le AS vu_le, d.acquitte_le AS acquitte_le FROM notifs n "
             "LEFT JOIN notif_dest d ON d.notif = n.id AND d.compte = ? WHERE 1=1 %s%s %s LIMIT ?"
             % (ou, filtre, ordre))
        for r in conn.execute(q, [compte] + list(args) + [int(limit)]).fetchall():
            out.append(_nt_enrichir(conn, dict(r), compte))
        conn.close()
    except Exception as e:
        logging.warning("[NOTIF] lecture : %s", e)
    cpt = notif_compteurs(compte, admin)
    return {"ok": True, "notifs": out, "vue": vue, "compte": compte, "admin": bool(admin),
            "compteurs": cpt, "battement": _nt_battement(),
            "sources": {k: {"nom": v["nom"], "c": v["c"], "nature": v.get("nature", "evenement")}
                        for k, v in _NOTIF_SOURCES.items()},
            "urgence": notif_urgence_etat() if admin else {},
            # compat avec l'écran d'avant, le temps du dépôt suivant
            "actives": cpt["total"], "critiques": cpt["critiques"], "non_lues": cpt["non_vues"]}


def notif_sources_etat() -> list:
    """La table des sources pour l'écran des réglages machine : nature, sonde, cadence, dernier cri."""
    _nt_migrate()
    derniers = {}
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        for r in conn.execute("SELECT source, MAX(ts), COUNT(*), SUM(resolue = 0) FROM notifs GROUP BY source"):
            derniers[r[0]] = {"dernier": r[1], "lignes": r[2], "ouvertes": r[3] or 0}
        conn.close()
    except Exception:
        pass
    out = []
    for k, v in _NOTIF_SOURCES.items():
        sondes = [p for p, s in _NT_SONDES.items() if k in s[2]]
        out.append({"source": k, "nom": v["nom"], "c": v["c"], "nature": v.get("nature", "evenement"),
                    "sondes": sondes,
                    "cadence_s": min([_NT_SONDES[p][1] for p in sondes]) if sondes else 0,
                    "dernier": (derniers.get(k) or {}).get("dernier", ""),
                    "lignes": (derniers.get(k) or {}).get("lignes", 0),
                    "ouvertes": (derniers.get(k) or {}).get("ouvertes", 0),
                    "action": (v.get("actions") or [[None, None]])[0][1] if v.get("actions") else ""})
    return out


# ── Politique, préférences, sourdines ───────────────────────────────────────
def notif_politique(compte: str = "") -> dict:
    """{niveau: [canaux]} pour ce compte : le défaut, puis la machine ('*'), puis la personne."""
    _nt_migrate()
    pol = {k: list(v) for k, v in _NT_POLITIQUE_DEFAUT.items()}
    compte = (compte or "").strip().lower()
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        for qui in ([_NT_MACHINE] + ([compte] if compte and compte != _NT_MACHINE else [])):
            for r in conn.execute("SELECT niveau, canaux FROM notif_politique WHERE compte = ?", (qui,)):
                if r[0] in pol:
                    try:
                        pol[r[0]] = [c for c in json.loads(r[1] or "[]") if c in _NT_CANAUX]
                    except Exception:
                        pass
        conn.close()
    except Exception as e:
        logging.info("[NOTIF] politique : %s", e)
    return pol


def notif_politique_set(compte: str, niveau: str, canaux) -> dict:
    _nt_migrate()
    compte = (compte or "").strip().lower()
    if not compte:
        return {"ok": False, "reason": "compte requis"}
    if niveau not in ("critique", "avoir", "info"):
        return {"ok": False, "reason": "niveau inconnu"}
    canaux = [c for c in (canaux or []) if c in _NT_CANAUX]
    if "cloche" not in canaux:
        canaux.insert(0, "cloche")            # la cloche reçoit TOUJOURS
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        conn.execute("INSERT INTO notif_politique (compte, niveau, canaux) VALUES (?,?,?) "
                     "ON CONFLICT(compte, niveau) DO UPDATE SET canaux = excluded.canaux",
                     (compte, niveau, json.dumps(canaux)))
        conn.commit(); conn.close()
        return {"ok": True, "politique": notif_politique(compte)}
    except Exception as e:
        return {"ok": False, "reason": str(e)}


_NT_PREFS = ("fuseau", "calme_debut", "calme_fin")


def _nt_prefs(compte: str) -> dict:
    """Les préférences de la personne : fuseau (lu du navigateur, jamais deviné), heures calmes."""
    compte = (compte or "").strip().lower()
    out = {"fuseau": "", "calme_debut": "22:00", "calme_fin": "08:00", "calmes": True}
    if not compte:
        return out
    try:
        out["fuseau"] = _uc_champ_lire(compte, "fuseau") or ""
        d = _uc_champ_lire(compte, "calme_debut") or ""
        f = _uc_champ_lire(compte, "calme_fin") or ""
        if d == "off":
            out["calmes"] = False
        elif re.match(r"^\d\d:\d\d$", d):
            out["calme_debut"] = d
        if re.match(r"^\d\d:\d\d$", f):
            out["calme_fin"] = f
    except Exception:
        pass
    return out


def notif_prefs_set(compte: str, d: dict) -> dict:
    compte = (compte or "").strip().lower()
    if not compte:
        return {"ok": False, "reason": "compte requis"}
    d = d or {}
    conn = None
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        _ensure_user_prefs_table(conn)
        _uc_migrer(conn)
        conn.execute("INSERT OR IGNORE INTO user_prefs (username) VALUES (?)", (compte,))
        if "fuseau" in d:
            fz = str(d.get("fuseau") or "")[:64]
            if fz and not _nt_fuseau_valide(fz):
                return {"ok": False, "reason": "fuseau inconnu"}
            conn.execute("UPDATE user_prefs SET fuseau = ? WHERE username = ?", (fz, compte))
        if "calmes" in d and not d.get("calmes"):
            conn.execute("UPDATE user_prefs SET calme_debut = 'off' WHERE username = ?", (compte,))
        else:
            for k in ("calme_debut", "calme_fin"):
                if k in d and re.match(r"^\d\d:\d\d$", str(d.get(k) or "")):
                    conn.execute("UPDATE user_prefs SET %s = ? WHERE username = ?" % k,
                                 (str(d[k])[:5], compte))
            if "calmes" in d and d.get("calmes") and "calme_debut" not in d:
                conn.execute("UPDATE user_prefs SET calme_debut = '22:00' WHERE username = ? "
                             "AND calme_debut = 'off'", (compte,))
        conn.commit()
        return {"ok": True, "prefs": _nt_prefs(compte)}
    except Exception as e:
        return {"ok": False, "reason": str(e)}
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


def _nt_fuseau_valide(nom: str) -> bool:
    try:
        from zoneinfo import ZoneInfo
        ZoneInfo(nom)
        return True
    except Exception:
        return False


def _nt_en_calme(compte: str, quand=None):
    """(en heures calmes ?, fuseau connu ?). Dans le FUSEAU DE LA PERSONNE ; sans fuseau déclaré, UTC —
    et l'écran le dit en toutes lettres (B4) plutôt que de laisser croire à l'heure locale."""
    p = _nt_prefs(compte)
    if not p.get("calmes"):
        return False, bool(p.get("fuseau"))
    quand = quand or datetime.now(timezone.utc)
    connu = False
    try:
        if p.get("fuseau"):
            from zoneinfo import ZoneInfo
            quand = quand.astimezone(ZoneInfo(p["fuseau"]))
            connu = True
    except Exception:
        connu = False
    h = quand.strftime("%H:%M")
    d, f = p["calme_debut"], p["calme_fin"]
    return ((h >= d or h < f) if d > f else (d <= h < f)), connu


def _nt_heures_calmes() -> bool:
    """Compat : les heures calmes de la MACHINE (heure serveur), pour les canaux sans personne (webhook)."""
    if not _mem_cfg("notif_heures_calmes", True):
        return False
    h = datetime.now().strftime("%H:%M")
    d = str(_mem_cfg("notif_calme_debut", "22:00"))
    f = str(_mem_cfg("notif_calme_fin", "08:00"))
    return (h >= d or h < f) if d > f else (d <= h < f)


def notif_sourdines(compte: str) -> list:
    """Les sourdines ACTIVES de ce compte, datées ; les échues sont levées au passage."""
    _nt_migrate()
    compte = (compte or "").strip().lower()
    out = []
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10); conn.row_factory = sqlite3.Row
        conn.execute("DELETE FROM notif_sourdines WHERE fin <> '' AND fin <= datetime('now')")
        for r in conn.execute("SELECT * FROM notif_sourdines WHERE compte = ? ORDER BY fin", (compte,)):
            d = dict(r)
            if d["portee"] == "source":
                d["cible_nom"] = (_NOTIF_SOURCES.get(d["cible"]) or {}).get("nom", d["cible"])
            out.append(d)
        conn.commit(); conn.close()
    except Exception as e:
        logging.info("[NOTIF] sourdines : %s", e)
    return out


def notif_sourdine_poser(compte: str, portee: str, cible: str, heures) -> dict:
    """Deux étages : par NOTIFICATION (« pas avant demain ») ou par SOURCE (N heures). Toujours une date de
    fin (1 h → 30 j) ; 0 heure = lever. La cloche reçoit toujours : seuls les canaux se taisent."""
    _nt_migrate()
    compte = (compte or "").strip().lower()
    portee = "notif" if portee == "notif" else "source"
    cible = str(cible or "")[:160]
    if not compte or not cible:
        return {"ok": False, "reason": "compte et cible requis"}
    if portee == "source" and cible not in _NOTIF_SOURCES:
        return {"ok": False, "reason": "source inconnue"}
    try:
        h = float(heures or 0)
    except Exception:
        h = 0
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        conn.execute("DELETE FROM notif_sourdines WHERE compte = ? AND portee = ? AND cible = ?",
                     (compte, portee, cible))
        fin = ""
        if h > 0:
            fin = (_utcnow() + timedelta(hours=max(1.0, min(24 * 30.0, h)))).strftime("%Y-%m-%d %H:%M:%S")
            conn.execute("INSERT INTO notif_sourdines (compte, portee, cible, fin) VALUES (?,?,?,?)",
                         (compte, portee, cible, fin))
        conn.commit(); conn.close()
        return {"ok": True, "fin": fin, "levee": not fin}
    except Exception as e:
        return {"ok": False, "reason": str(e)}


def _nt_sourdine_active(conn, compte: str, source: str, cle: str):
    r = conn.execute("SELECT id FROM notif_sourdines WHERE compte = ? AND fin > datetime('now') AND "
                     "((portee = 'source' AND cible = ?) OR (portee = 'notif' AND cible = ?)) LIMIT 1",
                     (compte, source, cle)).fetchone()
    return int(r[0]) if r else 0


# ── Canaux ──────────────────────────────────────────────────────────────────
_NT_DEMARRAGE = time.time()


def _nt_grace() -> bool:
    """LA GRÂCE : pendant `notif_grace_min` minutes après le démarrage, aucun canal ne sonne — sinon
    chaque redémarrage réveillerait tout le monde pour des services qui remontent. Le critique passe."""
    try:
        return (time.time() - _NT_DEMARRAGE) < 60.0 * max(0, int(_mem_cfg("notif_grace_min", 5) or 0))
    except Exception:
        return False


def _nt_retenir(conn, nid: int, compte: str, canaux, raison: str) -> None:
    for c in sorted(set(canaux) - {"cloche"}):
        conn.execute("INSERT INTO notif_retenues (notif, compte, canal, raison) VALUES (?,?,?,?)",
                     (int(nid), compte, c, str(raison)[:80]))


def _nt_texte(ligne: dict) -> str:
    return "%s\n\n%s\n\n— %s · %s" % (str(ligne.get("titre") or "")[:200], str(ligne.get("corps") or "")[:1200],
                                       (_NOTIF_SOURCES.get(ligne.get("source")) or {}).get("nom", ""),
                                       str(ligne.get("niveau") or ""))


def _nt_mail(compte: str, ligne: dict) -> bool:
    """Le mail d'UNE personne. Le critique est transactionnel — il part quoi qu'il arrive vers un admin ;
    le reste respecte l'opt-out de la personne (`user_email_enabled`)."""
    nom = (_NOTIF_SOURCES.get(ligne.get("source")) or {}).get("nom", "Cassandra")
    sujet = "[CASSANDRA] %s — %s" % (nom, str(ligne.get("titre") or "")[:90])
    corps_html = "<p>%s</p><p style='color:#666'>%s · %s</p>" % (
        html.escape(str(ligne.get("corps") or ""))[:1500].replace("\n", "<br>"), html.escape(nom),
        html.escape(str(ligne.get("niveau") or "")))
    try:
        if ligne.get("niveau") == "critique":
            ok = bool(cassandra_send_mail(compte, sujet, str(ligne.get("titre") or "")[:200], corps_html,
                                          "", "", _nt_texte(ligne)))
        else:
            ok = bool(notify_user_email(compte, sujet, str(ligne.get("titre") or "")[:200], corps_html))
    except Exception as e:
        logging.warning("[NOTIF] mail à %s : %s", compte, e)
        ok = False
    if not ok:
        logging.info("[NOTIF] mail non parti vers %s (%s)", compte, sujet[:60])
    return ok


def _nt_telegram(compte: str, ligne: dict) -> dict:
    try:
        r = tg_envoyer(compte, _nt_texte(ligne)) or {}
    except Exception as e:
        logging.info("[NOTIF] Telegram vers %s : %s", compte, e)
        return {"ok": False, "error": str(e)}
    # 08-10 : on garde de quoi retirer le message quand la notification se ferme — un « état » réglé
    # ne doit pas rester dans la conversation comme s'il était toujours vrai.
    if r.get("ok") and r.get("message_id") and ligne.get("id"):
        try:
            conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
            try:
                conn.execute("CREATE TABLE IF NOT EXISTS notif_tg (notif INTEGER, compte TEXT, chat_id TEXT, message_id INTEGER, "
                             "ts TEXT DEFAULT (datetime('now')))")
                conn.execute("INSERT INTO notif_tg (notif, compte, chat_id, message_id) VALUES (?,?,?,?)",
                             (int(ligne["id"]), compte, str(r.get("chat_id") or ""), int(r["message_id"])))
                conn.commit()
            finally:
                conn.close()
        except Exception as e:
            logging.info("[NOTIF] trace Telegram : %s", e)
    return r


def _nt_telegram_retirer(nid: int, titre: str = "") -> int:
    """La notification est réglée : ses messages Telegram disparaissent de la conversation. Telegram ne laisse un
    robot supprimer ses messages que 48 h ; au-delà, le message est réécrit « ✅ Résolu »."""
    n = 0
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        try:
            conn.execute("CREATE TABLE IF NOT EXISTS notif_tg (notif INTEGER, compte TEXT, chat_id TEXT, message_id INTEGER, "
                         "ts TEXT DEFAULT (datetime('now')))")
            lignes = conn.execute("SELECT compte, chat_id, message_id FROM notif_tg WHERE notif = ?", (int(nid),)).fetchall()
            for compte, chat, mid in lignes:
                jeton = _tg_jeton(compte) if "_tg_jeton" in globals() else ""
                r = _tg_req(jeton, "deleteMessage", {"chat_id": chat, "message_id": int(mid)})
                if not r.get("ok"):
                    _tg_req(jeton, "editMessageText", {"chat_id": chat, "message_id": int(mid),
                                                       "text": "✅ Résolu — %s" % (titre or "la cause a disparu")[:300]})
                n += 1
            conn.execute("DELETE FROM notif_tg WHERE notif = ?", (int(nid),))
            conn.commit()
        finally:
            conn.close()
    except Exception as e:
        logging.info("[NOTIF] retrait Telegram %s : %s", nid, e)
    return n


def _nt_apres_fermeture(ids_titres) -> None:
    """Ce qui suit la fermeture d'une notification : l'écran le sait tout de suite, Telegram retire le message."""
    for nid, titre in ids_titres:
        try:
            _nt_pousser(int(nid), "ferme")
        except Exception:
            pass
    if ids_titres:
        threading.Thread(target=lambda: [ _nt_telegram_retirer(i, t) for i, t in ids_titres ],
                         daemon=True, name="notif-retrait").start()


def _nt_canaux(ligne: dict, monte: bool = False) -> None:
    """Ce qui SORT de la machine pour cette ligne, personne par personne.

    La politique est PAR PERSONNE × GRAVITÉ ; la cloche reçoit toujours ; les heures calmes sont celles de la
    personne, dans son fuseau ; une sourdine (par source ou par notification) retient et compte ;
    la grâce du démarrage retient tout sauf le critique. Le webhook est un canal de la MACHINE : une fois."""
    niveau = str(ligne.get("niveau") or "")
    if niveau not in ("critique", "avoir", "info"):
        return
    nid = int(ligne.get("id") or 0)
    # La grâce du démarrage tait tout sauf le critique ; le battement la montre (`grace: true`).
    if niveau != "critique" and _nt_grace():
        return
    conn = None
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        pol_machine = notif_politique(_NT_MACHINE)
        if "webhook" in pol_machine.get(niveau, []) and (niveau == "critique" or not _nt_heures_calmes()):
            if "notify_via_webhook" in globals():
                threading.Thread(target=notify_via_webhook,
                                 args=(str(ligne.get("titre") or "")[:200], niveau),
                                 daemon=True, name="notif-webhook").start()
        for compte in _nt_destinataires_humains(ligne.get("destinataires") or ["admins"]):
            canaux = set(notif_politique(compte).get(niveau, [])) - {"cloche"}
            if not canaux:
                continue
            srd = _nt_sourdine_active(conn, compte, str(ligne.get("source") or ""), str(ligne.get("cle") or ""))
            if srd:
                conn.execute("UPDATE notif_sourdines SET retenues = retenues + 1 WHERE id = ?", (srd,))
                _nt_retenir(conn, nid, compte, canaux, "sourdine")
                continue
            calme, _connu = _nt_en_calme(compte)
            if calme and niveau != "critique":
                _nt_retenir(conn, nid, compte, canaux, "heures calmes")
                continue
            if "mail" in canaux:
                threading.Thread(target=_nt_mail, args=(compte, dict(ligne)), daemon=True,
                                 name="notif-mail").start()
            if "telegram" in canaux and "tg_envoyer" in globals():
                threading.Thread(target=_nt_telegram, args=(compte, dict(ligne)), daemon=True,
                                 name="notif-telegram").start()
        conn.commit()
    except Exception as e:
        logging.info("[NOTIF] canaux : %s", e)
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


def _nt_digest_passe() -> int:
    """LE MAIL DU MATIN : ce que les heures calmes ont retenu part en UNE enveloppe par personne, dès
    qu'elle sort de ses heures calmes. Ce qu'une sourdine a retenu ne part pas : c'était le but."""
    _nt_migrate()
    envoyes = 0
    conn = None
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10); conn.row_factory = sqlite3.Row
        conn.execute("DELETE FROM notif_retenues WHERE raison = 'sourdine' "
                     "OR retenue_le < datetime('now', '-3 days')")
        comptes = [r[0] for r in conn.execute("SELECT DISTINCT compte FROM notif_retenues "
                                              "WHERE raison = 'heures calmes'")]
        for compte in comptes:
            calme, _ = _nt_en_calme(compte)
            if calme:
                continue
            lignes = conn.execute(
                "SELECT r.id AS rid, r.canal, n.titre, n.corps, n.source, n.niveau, n.resolue "
                "FROM notif_retenues r JOIN notifs n ON n.id = r.notif "
                "WHERE r.compte = ? AND r.raison = 'heures calmes' ORDER BY n.id", (compte,)).fetchall()
            if not lignes:
                continue
            parts, tg = [], []
            for l in lignes:
                nom = (_NOTIF_SOURCES.get(l["source"]) or {}).get("nom", l["source"])
                etat = " (déjà réglé)" if l["resolue"] else ""
                parts.append("<li><b>%s</b> — %s%s</li>" % (html.escape(nom), html.escape(str(l["titre"])[:160]),
                                                            etat))
                if l["canal"] == "telegram":
                    tg.append("• %s — %s%s" % (nom, str(l["titre"])[:120], etat))
            corps_html = ("<p>Pendant vos heures calmes, Cassandra a retenu %d notification(s) :</p><ul>%s</ul>"
                          % (len(lignes), "".join(parts)))
            try:
                if any(l["canal"] == "mail" for l in lignes):
                    notify_user_email(compte, "[CASSANDRA] Ce que la nuit a retenu (%d)" % len(lignes),
                                      "Ce que la nuit a retenu", corps_html)
                if tg and "tg_envoyer" in globals():
                    tg_envoyer(compte, "Retenu pendant tes heures calmes :\n" + "\n".join(tg[:20]))
                envoyes += 1
            except Exception as e:
                logging.info("[NOTIF] enveloppe du matin vers %s : %s", compte, e)
            conn.execute("DELETE FROM notif_retenues WHERE id IN (%s)"
                         % ",".join(str(int(l["rid"])) for l in lignes))
        conn.commit()
    except Exception as e:
        logging.info("[NOTIF] digest : %s", e)
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass
    return envoyes


def notif_essai(acteur: str = "", canal: str = "cloche") -> dict:
    """L'essai prouve UN canal et écrit son résultat — au lieu d'une notification qui disait
    « résolvez-moi » et passait pour cassée."""
    _nt_migrate()
    acteur = (acteur or "").strip().lower()
    canal = canal if canal in _NT_CANAUX else "cloche"
    ok, detail = False, ""
    try:
        if canal == "cloche":
            r = notif("Essai — cette notification vient des réglages",
                      "Émise par %s pour vérifier que la cloche reçoit. Acquittez-la, elle n'a aucune autre "
                      "raison d'exister." % (acteur or "vous"), source="systeme", niveau="info",
                      nature="evenement", sujet="essai", cle="essai:%s" % (acteur or "machine"),
                      dest=["compte:" + acteur] if acteur else ["admins"])
            ok, detail = bool(r.get("ok")), ("ligne #%s" % r.get("id") if r.get("ok") else str(r.get("reason")))
        elif canal == "mail":
            if not acteur or "@" not in acteur:
                detail = "aucune adresse : le compte n'est pas une adresse"
            else:
                ok = bool(cassandra_send_mail(acteur, "[CASSANDRA] Essai des notifications", "Essai",
                                              "<p>Si vous lisez ceci, le mail part.</p>", "", "",
                                              "Si vous lisez ceci, le mail part."))
                detail = "parti vers %s" % acteur if ok else "refusé : voir Services tiers › E-mail (SMTP)"
        elif canal == "telegram":
            r = tg_envoyer(acteur, "Essai des notifications de Cassandra : si tu lis ceci, Telegram part.")
            ok, detail = bool((r or {}).get("ok")), str((r or {}).get("error") or "parti")
        elif canal == "webhook":
            ok, detail = _nt_webhook_essai()
    except Exception as e:
        ok, detail = False, str(e)[:200]
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        conn.execute("INSERT INTO notif_essais (canal, ts, ok, detail) VALUES (?, datetime('now'), ?, ?) "
                     "ON CONFLICT(canal) DO UPDATE SET ts = excluded.ts, ok = excluded.ok, detail = excluded.detail",
                     (canal, 1 if ok else 0, str(detail)[:200]))
        conn.commit(); conn.close()
    except Exception:
        pass
    return {"ok": ok, "canal": canal, "detail": detail, "essai": True}


def notif_essais() -> dict:
    _nt_migrate()
    out = {}
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10); conn.row_factory = sqlite3.Row
        for r in conn.execute("SELECT * FROM notif_essais"):
            out[r["canal"]] = {"ts": r["ts"], "ok": bool(r["ok"]), "detail": r["detail"]}
        conn.close()
    except Exception:
        pass
    return out


def _nt_webhook_essai():
    cfg = (load_alert_config() or {}).get("webhook", {}) or {}
    if not cfg.get("enabled") or not cfg.get("url"):
        return False, "aucun webhook déclaré"
    try:
        payload = json.dumps({"text": "[ESSAI] Cassandra : le webhook part."}).encode("utf-8")
        headers = {"Content-Type": "application/json"}
        headers.update(cfg.get("headers", {}) or {})
        req = urllib.request.Request(str(cfg["url"]), data=payload, headers=headers, method="POST")
        with urllib.request.urlopen(req, timeout=8) as resp:
            return 200 <= resp.status < 300, "HTTP %s" % resp.status
    except Exception as e:
        return False, str(e)[:160]


def notif_canaux_etat(compte: str = "") -> dict:
    """Ce que chaque canal peut faire, pour l'écran : déclaré ou non, dernier essai."""
    compte = (compte or "").strip().lower()
    cfg = load_alert_config() or {}
    email = cfg.get("email", {}) or {}
    wh = cfg.get("webhook", {}) or {}
    tg = {}
    try:
        tg = tg_etat(compte) if compte else {}
    except Exception:
        tg = {}
    return {"mail": {"declare": bool(email.get("enabled") and email.get("smtp_host")),
                     "hote": str(email.get("smtp_host") or ""), "port": email.get("smtp_port"),
                     "expediteur": str(email.get("from_addr") or ""),
                     "destinataires": email.get("to_addrs") or []},
            "telegram": {"declare": bool(tg.get("ok") and tg.get("actif")),
                         "destinataire": bool(tg.get("destinataire")) if tg else False},
            "webhook": {"declare": bool(wh.get("enabled") and wh.get("url")),
                        "url": str(wh.get("url") or "")[:120]},
            "essais": notif_essais()}


# ── Les sondes et la passe du centre ─────────────────────────────────────────
def _sonde_reboot(arg, row):
    return not os.path.exists("/var/run/reboot-required")


def _sonde_service(arg, row):
    e = fp_service_state(arg) or {}
    if not e:
        return None
    return e.get("active") == "active"


def _sonde_site(arg, row):
    conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
    try:
        r = conn.execute("SELECT up, ts FROM site_status WHERE domain = ? ORDER BY id DESC LIMIT 1",
                         (arg,)).fetchone()
    finally:
        conn.close()
    if not r:
        return None
    return bool(r[0])


def _sonde_lent(arg, row):
    """Rétabli quand les TROIS dernières mesures passent sous le seuil : un pic isolé ne reste pas ouvert, une
    lenteur qui dure ne se ferme pas sur une seule bonne mesure."""
    conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
    try:
        r = conn.execute("SELECT response_ms, up FROM site_status WHERE domain = ? ORDER BY id DESC LIMIT 3",
                         (arg,)).fetchall()
    finally:
        conn.close()
    if len(r) < 3:
        return None
    return all(x[1] and x[0] is not None and int(x[0]) < _SITE_LENT_MS for x in r)


def _sonde_ssl(arg, row):
    r = fp_ssl_check(arg) or {}
    if not r.get("ok") or r.get("days_left") is None:
        return None
    return int(r["days_left"]) > int(_mem_cfg("ssl_seuil_jours", 21) or 21)


def _sonde_mesure(arg, row):
    d = metric_deviations() or {}
    if isinstance(d, dict) and d.get("ok") is False:
        return None
    ecarts = d.get("deviations", []) if isinstance(d, dict) else []
    return arg not in {str(e.get("key")) for e in ecarts}


def _sonde_flotte(arg, row):
    # TAILSCALE D'ABORD (24-09) : pour une machine du registre SSH, la dernière ligne est celle de la sonde SSH ;
    # un poste Windows sans SSH y paraissait « hors ligne » pour toujours alors que Tailscale le voyait actif.
    try:
        _p = (_flotte_tailscale_live() or {}).get(_flotte_nom(arg))
        if isinstance(_p, dict) and "online" in _p:
            return bool(_p["online"])
    except Exception:
        pass
    conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
    try:
        r = conn.execute("SELECT online FROM fleet_status WHERE name = ? ORDER BY id DESC LIMIT 1",
                         (arg,)).fetchone()
    finally:
        conn.close()
    if not r:
        return None
    return bool(r[0])


def _sonde_backup(arg, row):
    a = fp_backup_audit() or {}
    if not a.get("ok"):
        return None
    vieilles = {str(s.get("domain")) for s in (a.get("stale") or [])}
    return arg not in set(a.get("missing") or []) and arg not in vieilles


def _sonde_salon(arg, row):
    fil, _, dernier = str(arg).partition(":")
    conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
    try:
        r = conn.execute("SELECT 1 FROM salon_messages WHERE fil = ? AND humain = 1 AND id > ? LIMIT 1",
                         (int(fil or 0), int(dernier or 0))).fetchone()
    finally:
        conn.close()
    return bool(r)


def _sonde_mandat(arg, row):
    m = _md_get(int(arg))
    if not m:
        return None
    return not (m.get("suspendu") or "")


def _sonde_seuil(arg, row):
    """RAM et charge : rentrées quand la mesure repasse sous le seuil d'avertissement.

    LES VRAIS NOMS (10-10) : get_metrics() rend « ram », « disk », « load_1m » ; la sonde lisait « ram_pct »,
    « disk_pct », « load1 » (les noms de proactive_metrics), ne trouvait rien, se disait muette — et une alerte de
    charge, de mémoire ou de disque ne se refermait JAMAIS seule (« Load Average 9,19 » restait sous une charge à 1,7)."""
    m = get_metrics() or {}
    th = (load_alert_config() or {}).get("thresholds", {}) or {}

    def lire(*noms):
        return next((m[n] for n in noms if m.get(n) is not None), None)
    if arg == "ram":
        v = lire("ram", "ram_pct")
        return None if v is None else float(v) < float(th.get("ram_warning", 85))
    if arg == "load":
        v = lire("load_1m", "load1")
        if v is None:
            return None
        try:
            coeurs = os.cpu_count() or 1
        except Exception:
            coeurs = 1
        return float(v) < float(th.get("load_warning", coeurs * 1.5))
    if arg.startswith("disk"):
        v = lire("disk", "disk_pct")
        return None if v is None else float(v) < float(th.get("disk_warning", 80))
    return None


# préfixe → (fonction, cadence en secondes, sources qui l'emploient). Les cadences sont celles du tour 23 :
# rapides 5 min, services 15 min (13 forks systemctl), mesure 1 h tant que l'habitude est aveugle.
def _sonde_rappel(arg, row):
    """LOT 4 : la ligne d'un rappel se referme seule quand il est fait, vu, reporté ou disparu."""
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10); conn.row_factory = sqlite3.Row
        r = conn.execute("SELECT status, accuse, notified, prealerte FROM itare_reminders WHERE id=?",
                         (int(arg),)).fetchone()
        conn.close()
    except Exception:
        return None
    if not r or str(r["status"] or "") == "done" or (r["accuse"] or ""):
        return True
    if not int(r["notified"] or 0) and not int(r["prealerte"] or 0):
        return True                    # reporté : plus rien n'est signalé
    return False


_NT_SONDES = {
    "reboot":  (_sonde_reboot, 300, ("systeme",)),
    "seuil":   (_sonde_seuil, 300, ("systeme",)),
    "service": (_sonde_service, 900, ("systeme",)),
    "site":    (_sonde_site, 300, ("site",)),
    "lent":    (_sonde_lent, 300, ("site",)),
    "ssl":     (_sonde_ssl, 3600, ("certificat",)),
    "mesure":  (_sonde_mesure, 3600, ("mesure",)),
    "flotte":  (_sonde_flotte, 300, ("flotte",)),
    "backup":  (_sonde_backup, 3600, ("sauvegarde",)),
    "salon":   (_sonde_salon, 300, ("salon",)),
    "mandat":  (_sonde_mandat, 300, ("mandat",)),
    "rappel":  (_sonde_rappel, 60, ("rappel",)),
}
_NT_SONDE_DERNIER = {}
_NT_SONDE_VUE = {}
_NT_PASSE = {"ts": "", "duree_ms": 0, "sondes": 0, "muettes": 0, "fermees": 0, "expirees": 0, "n": 0}
_NT_PASSE_VERROU = threading.Lock()


def _nt_expirer(conn) -> int:
    cur = conn.execute("UPDATE notifs SET resolue = 1, niveau = 'regle', resolue_le = datetime('now'), "
                       "resolue_par = 'expiré', duree_min = CAST((julianday('now') - julianday(ts)) * 1440 "
                       "AS INTEGER) WHERE resolue = 0 AND expire_le <> '' AND expire_le < datetime('now')")
    conn.execute("DELETE FROM notif_dest WHERE notif NOT IN (SELECT id FROM notifs)")
    conn.execute("DELETE FROM notif_retenues WHERE notif NOT IN (SELECT id FROM notifs)")
    return cur.rowcount


def _nt_battement_ecrire(duree_ms: int, jouees: int, muettes: int, fermees: int, expirees: int) -> None:
    """Le battement va dans `pf_scans`, l'anneau qui existe déjà (100 lignes) : une ligne par passe du
    centre, lue au présent par l'état vide de l'écran — jamais comme un événement du Journal."""
    try:
        _pf_scans_migrate()
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        conn.execute("INSERT INTO pf_scans (duree_ms, declencheur, resume, vus, muets, trouves, nouveaux, "
                     "resolus, actions, detail, diff) VALUES (?,?,?,?,?,?,?,?,?,?,?)",
                     (int(duree_ms), "centre",
                      "%d sonde(s) jouée(s), %d muette(s), %d état(s) refermé(s), %d expirée(s)"
                      % (jouees, muettes, fermees, expirees), jouees, muettes, 0, 0, fermees, 0, "[]", "[]"))
        conn.execute("DELETE FROM pf_scans WHERE id NOT IN (SELECT id FROM pf_scans ORDER BY id DESC LIMIT 100)")
        conn.commit(); conn.close()
    except Exception as e:
        logging.info("[NOTIF] battement : %s", e)


def _nt_battement() -> dict:
    d = dict(_NT_PASSE)
    d["grace"] = _nt_grace()
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10); conn.row_factory = sqlite3.Row
        r = conn.execute("SELECT ts, duree_ms, vus, muets, resolus FROM pf_scans WHERE declencheur = 'centre' "
                         "ORDER BY id DESC LIMIT 1").fetchone()
        conn.close()
        if r:
            d["ecrit_le"] = r["ts"]
    except Exception:
        pass
    return d


_NT_PF_SOUS = ("savoir:", "retro:", "prop:", "detecteur:", "escalade:")


def _nt_perimees() -> list:
    """LES DÉCISIONS DONT LA CAUSE EST PARTIE, FERMÉES PAR LA MESURE (24-09). Une décision ne se ferme d'habitude
    que par son geste ; mais une alerte de la veille retombée, une machine revenue, une sauvegarde posée ne
    réclament plus rien — les garder apprend à ne plus regarder la cloche. Rend [(id, titre, raison)].
    Ne ferme que sur une MESURE ; une cause qu'on ne sait pas mesurer reste ouverte."""
    fermees = []
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10); conn.row_factory = sqlite3.Row
        ouvertes = [dict(r) for r in conn.execute(
            "SELECT id, cle, titre, ts FROM notifs WHERE resolue = 0 AND (cle LIKE 'pf:%' OR cle LIKE 'autotache:%' "
            "OR (cle LIKE 'rappel:%' AND cle LIKE '%|%') OR cle LIKE 'pj-invite:%')")]
        vivantes, ids_vivants = set(), set()
        try:
            for r in conn.execute("SELECT id, fkey, category FROM proactive_findings WHERE status != 'resolved'"):
                vivantes.add(str(r["fkey"] or "")); vivantes.add(str(r["category"] or "")); ids_vivants.add(str(r["id"]))
        except Exception:
            conn.close()
            return []          # sans table des anomalies, on ne sait rien : on ne ferme rien
        conn.close()
    except Exception as e:
        logging.info("[NOTIF] périmées : %s", e)
        return []
    audit = None
    for n in ouvertes:
        cle, raison = str(n["cle"] or ""), ""
        try:
            if cle.startswith("pf:"):
                k = cle[3:]
                if k and not k.startswith(_NT_PF_SOUS) and k not in vivantes:
                    raison = "la veille ne la voit plus"
            elif cle.startswith("autotache:auto-finding|"):
                k = cle.split("|", 1)[1]
                if k and k not in vivantes and k not in ids_vivants:
                    raison = "l'anomalie est retombée"
            elif cle.startswith("autotache:auto-backup|backup-absent:"):
                dom = cle.split("backup-absent:", 1)[1]
                if not _nom_de_site_valide(dom):
                    raison = "« %s » n'est pas un site" % dom
                else:
                    if audit is None:
                        audit = fp_backup_audit() or {}
                    if audit.get("ok") and dom in set(audit.get("proxys") or []):
                        raison = "proxy inverse : rien à sauvegarder dans le panneau"
                    elif audit.get("ok") and dom not in set(audit.get("missing") or []):
                        raison = "la sauvegarde existe"
            elif cle.startswith("autotache:auto-fleet|fleet:"):
                nom = cle.split("fleet:", 1)[1].split(":", 1)[0]
                if nom and _sonde_flotte(nom, n) is True:
                    raison = "%s est de nouveau en ligne" % nom
            elif cle.startswith("rappel:") and "|" in cle:
                # L'ANNONCE D'UNE ÉCHÉANCE (07-10) : « rappel:[compte|]task|32|…|J0 ». Close quand la tâche est close,
                # ou le lendemain du jour annoncé — « aujourd'hui » devient faux, la tâche reste dans sa liste.
                p = cle[7:].split("|")
                if p and "@" in p[0]:
                    p = p[1:]
                genre, ident = (p[0] if p else ""), (p[1] if len(p) > 1 else "")
                m = re.search(r"\|J(\d+)$", cle)
                jour = (datetime.strptime(str(n.get("ts") or "")[:10], "%Y-%m-%d")
                        + timedelta(days=int(m.group(1)) if m else 0)).strftime("%Y-%m-%d")
                if genre == "task" and ident.isdigit():
                    cn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
                    try:
                        r = cn.execute("SELECT status FROM itare_tasks WHERE id=?", (int(ident),)).fetchone()
                    finally:
                        cn.close()
                    if not r:
                        raison = "la tâche n'existe plus"
                    elif str(r[0] or "") in _ITARE_TASK_FERMES:
                        raison = "la tâche est close"
                if not raison and datetime.now().strftime("%Y-%m-%d") > jour:
                    raison = "le jour annoncé est passé"
            elif cle.startswith("pj-invite:"):
                # L'INVITATION (07-10) : close dès qu'elle a sa réponse — acceptée, refusée ou retirée.
                p = cle.split(":", 2)
                if len(p) == 3 and p[1].isdigit():
                    cn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
                    try:
                        r = cn.execute("SELECT 1 FROM pj_membres WHERE project_id=? AND lower(compte)=lower(?) "
                                       "AND etat='invite'", (int(p[1]), p[2])).fetchone()
                    finally:
                        cn.close()
                    if not r:
                        raison = "l'invitation a eu sa réponse"
        except Exception as e:
            logging.info("[NOTIF] périmée %s : %s", cle, e)
            continue
        if raison and notif_resoudre_cle(cle, par="sonde", detail="refermé : %s (mesure)" % raison):
            fermees.append((int(n["id"]), str(n["titre"] or ""), raison))
            try:
                _nt_pousser(int(n["id"]), "ferme")
            except Exception:
                pass
    return fermees


def _nt_passe(force: bool = False) -> dict:
    """LA PASSE DU CENTRE : elle rejoue les sondes des états ouverts, indépendamment des détecteurs qui les
    ont ouverts (tour 7) — un détecteur muet ouvrait et ne fermait jamais. Budget par sonde ; une sonde
    lente ou qui lève est dite MUETTE, visiblement, et ne bloque pas les autres ; jamais muette pendant la
    grâce. Elle expire ce qui doit expirer, envoie l'enveloppe du matin, et écrit son battement."""
    if not _NT_PASSE_VERROU.acquire(blocking=False):
        return dict(_NT_PASSE)
    t0 = time.time()
    jouees = muettes = fermees = expirees = 0
    try:
        _nt_migrate()
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10); conn.row_factory = sqlite3.Row
        rows = [dict(r) for r in conn.execute(
            # TOUTE LIGNE QUI PORTE UNE SONDE EST REJOUÉE (07-10), quelle que soit sa nature : un événement « site
            # lent » ou une décision « relance l'unité » sondés restaient ouverts — seuls les états l'étaient.
            "SELECT id, cle, sonde, source, niveau, titre FROM notifs WHERE resolue = 0 "
            "AND COALESCE(sonde, '') <> ''")]
        expirees = _nt_expirer(conn)
        conn.commit(); conn.close()
        maintenant = time.time()
        par_prefixe = {}
        for r in rows:
            par_prefixe.setdefault(str(r["sonde"]).split(":", 1)[0], []).append(r)
        for prefixe, lst in par_prefixe.items():
            spec = _NT_SONDES.get(prefixe)
            if not spec:
                continue
            fn, cadence, _srcs = spec
            if not force and maintenant - _NT_SONDE_DERNIER.get(prefixe, 0) < cadence:
                continue
            _NT_SONDE_DERNIER[prefixe] = maintenant
            for r in lst:
                arg = str(r["sonde"]).split(":", 1)[1] if ":" in str(r["sonde"]) else ""
                t1 = time.time()
                try:
                    res = fn(arg, r)
                except Exception as e:
                    logging.info("[NOTIF] sonde %s (%s) : %s", prefixe, arg, e)
                    res = None
                lente = (time.time() - t1) > _NT_SONDE_BUDGET_S
                jouees += 1
                etat = "ok"
                if res is None or lente:
                    etat = "muette"
                    if not _nt_grace():
                        muettes += 1
                elif res is True:
                    hh = datetime.now().strftime("%H:%M")
                    if notif_resoudre_cle(r["cle"], par="sonde", detail="refermé seul à %s (mesure)" % hh):
                        fermees += 1
                        _nt_pousser(int(r["id"]), "ferme")
                    continue
                try:
                    c2 = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
                    c2.execute("UPDATE notifs SET sonde_etat = ? WHERE id = ?", (etat, int(r["id"])))
                    c2.commit(); c2.close()
                except Exception:
                    pass
            _NT_SONDE_VUE[prefixe] = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        try:
            _nt_digest_passe()
        except Exception as e:
            logging.info("[NOTIF] digest : %s", e)
        try:
            _bj_passe()                # LOT 4 : Aujourd'hui, par compte, gardé et poussé
        except Exception as e:
            logging.info("[BUREAU] passe : %s", e)
        try:
            fermees += len(_nt_perimees())     # les décisions dont la mesure dit la cause partie (24-09)
        except Exception as e:
            logging.info("[NOTIF] périmées : %s", e)
    except Exception as e:
        logging.warning("[NOTIF] passe : %s", e)
    finally:
        duree = int((time.time() - t0) * 1000)
        _NT_PASSE.update({"ts": datetime.now().strftime("%Y-%m-%d %H:%M:%S"), "duree_ms": duree,
                          "sondes": jouees, "muettes": muettes, "fermees": fermees, "expirees": expirees,
                          "n": _NT_PASSE.get("n", 0) + 1})
        if force or _NT_PASSE["n"] % 5 == 1:
            _nt_battement_ecrire(duree, jouees, muettes, fermees, expirees)
        _NT_PASSE_VERROU.release()
    return dict(_NT_PASSE)


_NT_BOUCLE_LANCEE = [False]


def _nt_boucle():
    time.sleep(25)
    while True:
        try:
            _nt_passe()
        except Exception as e:
            logging.warning("[NOTIF] boucle : %s", e)
        time.sleep(max(30, int(_mem_cfg("notif_passe_s", 60) or 60)))


_CONFIG_ORPHELINES = ("imap_host", "imap_port", "imap_ssl", "imap_user", "imap_password",
                      "caldav_url", "caldav_user", "caldav_password")


def _config_purger_orphelines() -> list:
    """Les identifiants IMAP et CalDAV de la machine ne se lisent plus (le repli sur config.json est fermé
    depuis août ; la boîte et l'agenda sont ceux de la personne, dans son coffre). Un mot de passe en clair
    que plus rien ne lit est un secret orphelin (B5, tour 2) : on l'enlève, et on le dit."""
    try:
        cfg = get_cassandra_config() or {}
        otees = [k for k in _CONFIG_ORPHELINES if k in cfg]
        if not otees:
            return []
        for k in otees:
            cfg.pop(k, None)
        if save_cassandra_config(cfg):
            logging.info("[CONFIG] clés orphelines retirées de config.json : %s", ", ".join(otees))
            return otees
    except Exception as e:
        logging.info("[CONFIG] purge des clés orphelines : %s", e)
    return []


def _nt_demarrer() -> None:
    if _NT_BOUCLE_LANCEE[0]:
        return
    _NT_BOUCLE_LANCEE[0] = True
    threading.Thread(target=_nt_boucle, daemon=True, name="notif-passe").start()


# ══════════════════════════════════════════════════════════════════════════════
#  GESTES D'URGENCE
#
#  Cinq actions rangées dans la cloche, parce que c'est le seul endroit présent
#  sur tous les écrans, et parce qu'on les cherche exactement au moment où l'on
#  n'a pas le temps de chercher.
#
#  AUCUNE n'est un outil d'agent. Elles exigent une session humaine
#  authentifiée, et le confinement exige en plus un mot tapé.
#
#  Le danger du confinement n'est pas de couper trop : c'est de SE couper
#  soi-même. Deux garde-fous, non négociables :
#    · l'adresse de la session en cours reste autorisée, et sa joignabilité est
#      revérifiée après chaque étape — un échec défait tout ;
#    · une échéance, pas une intention : sans confirmation, le confinement se
#      lève seul. Dans le pire des cas, la machine rouvre la porte.
# ══════════════════════════════════════════════════════════════════════════════
_URG_NIVEAUX = (1, 2, 3)
_URG_FLAG = CASSANDRA_DATA_DIR + "/confinement.json"


def _urg_cfg(k, d=None):
    return _mem_cfg(k, d)


def _urg_set(k, v) -> None:
    try:
        c = get_cassandra_config()
        c[k] = v
        save_cassandra_config(c)
    except Exception as e:
        logging.warning("[URGENCE] écriture de la configuration : %s", e)


# ── Geler l'autonomie ───────────────────────────────────────────────────────
def notif_geler(actif: bool = None, acteur: str = "") -> dict:
    """Cassandra continue de SURVEILLER, elle n'AGIT plus.

    C'est le geste à faire quand on soupçonne un agent d'être manipulé : il
    voit encore, il ne touche plus. La veille, les mesures et les notifications
    continuent — ce sont elles qui diront si la situation empire."""
    if actif is None:
        return {"ok": True, "actif": bool(_urg_cfg("autonomie_gelee", False))}
    _urg_set("autonomie_gelee", bool(actif))
    if actif:
        notif("Autonomie gelée", "Cassandra surveille mais n'agit plus : évolution, "
              "auto-remédiation, mandats et tâches planifiées sont suspendus. "
              "Gelée par %s." % (acteur or "vous"),
              source="securite", niveau="avoir", nature="etat", sujet="urgence:gel", cle="urgence:gel")
    else:
        notif_resoudre_cle("urgence:gel", par=acteur or "vous",
                           detail="autonomie rendue")
    try:
        log_user_activity(acteur, acteur, "autonomie_gel", "gelée" if actif else "rendue")
    except Exception:
        pass
    return {"ok": True, "actif": bool(actif)}


def autonomie_gelee() -> bool:
    return bool(_urg_cfg("autonomie_gelee", False))


# ── Couper les envois ───────────────────────────────────────────────────────
def notif_envois(actif: bool = None, acteur: str = "") -> dict:
    """Suspend tous les mandats d'un coup.

    Conséquence à dire, pas à découvrir : vos propres alertes par e-mail
    s'arrêtent aussi. Elles s'accumulent dans la cloche."""
    if actif is None:
        return {"ok": True, "coupes": bool(_urg_cfg("envois_coupes", False))}
    _urg_set("envois_coupes", bool(actif))
    n = 0
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        if actif:
            cur = conn.execute("UPDATE mandats SET suspendu='coupure d''urgence' "
                               "WHERE suspendu = ''")
        else:
            cur = conn.execute("UPDATE mandats SET suspendu='' "
                               "WHERE suspendu = 'coupure d''urgence'")
        n = cur.rowcount
        conn.commit(); conn.close()
    except Exception as e:
        logging.info("[URGENCE] mandats : %s", e)
    try:
        log_user_activity(acteur, acteur, "envois_coupes", "%s (%d mandat(s))" % ("coupés" if actif else "rouverts", n))
    except Exception:
        pass
    if actif:
        notif("Envois coupés", "%d mandat(s) suspendu(s). Rien ne sort plus par e-mail — "
              "y compris les alertes que vous vous envoyez : elles s'accumulent ici."
              % n, source="mandat", niveau="avoir", nature="etat", sujet="urgence:envois", cle="urgence:envois")
    else:
        notif_resoudre_cle("urgence:envois", par=acteur or "vous",
                           detail="%d mandat(s) rouvert(s)" % n)
    return {"ok": True, "coupes": bool(actif), "mandats": n}


# ── Confinement ─────────────────────────────────────────────────────────────
def _urg_sh(cmd: str, timeout: int = 20) -> tuple:
    try:
        p = subprocess.run(cmd, shell=True, capture_output=True, text=True, timeout=timeout)
        return p.returncode == 0, ((p.stdout or "") + (p.stderr or "")).strip()[:400]
    except Exception as e:
        return False, str(e)[:200]


def _urg_joignable(ip: str) -> bool:
    """Le port 22 répond-il encore depuis la machine, pour cette adresse ?

    On ne peut pas tester depuis l'extérieur ; on vérifie au moins que la règle
    de pare-feu qui protège l'adresse est bien en place et que sshd tourne."""
    if not ip:
        return False
    ok_svc, _ = _urg_sh("systemctl is-active ssh sshd 2>/dev/null | grep -q '^active'")
    if not ok_svc:
        return False
    ok_fw, sortie = _urg_sh("command -v ufw >/dev/null 2>&1 && ufw status | grep -F %s"
                            % _sh_quote(ip))
    # Sans ufw, on ne peut rien affirmer : on ne bloque pas pour autant, mais
    # les étapes qui ferment des ports ne seront pas franchies.
    return ok_fw or "ufw" not in sortie


def _urg_etapes(niveau: int, ip: str) -> list:
    """Les gestes, dans l'ordre, du moins au plus coupant.

    Chacun porte son défaire : le retour n'est pas une reconstruction, c'est la
    liste lue à l'envers."""
    e = [
        ("sessions", "Révoquer les autres sessions", None, None),
        ("gel", "Geler l'autonomie de Cassandra", None, None),
        ("ssh_mdp", "Désactiver le mot de passe sur SSH",
         "sed -i 's/^#\\?PasswordAuthentication.*/PasswordAuthentication no/' "
         "/etc/ssh/sshd_config && systemctl reload ssh 2>/dev/null || "
         "systemctl reload sshd",
         "sed -i 's/^PasswordAuthentication no/#PasswordAuthentication yes/' "
         "/etc/ssh/sshd_config && systemctl reload ssh 2>/dev/null || "
         "systemctl reload sshd"),
    ]
    if niveau >= 2:
        e += [
            ("envois", "Couper tous les envois", None, None),
            ("ufw_moi", "Autoriser votre adresse avant tout le reste",
             "ufw allow from %s to any port 22 comment cassandra-confinement" % ip,
             "ufw delete allow from %s to any port 22" % ip),
            ("ufw_ssh", "Fermer SSH au reste du monde",
             "ufw delete allow 22/tcp 2>/dev/null; ufw deny 22/tcp",
             "ufw delete deny 22/tcp; ufw allow 22/tcp"),
        ]
    if niveau >= 3:
        e += [
            ("ufw_defaut", "Pare-feu en refus par défaut",
             "ufw default deny incoming", "ufw default allow incoming"),
            ("services", "Arrêter les services non essentiels",
             "systemctl stop docker 2>/dev/null; true",
             "systemctl start docker 2>/dev/null; true"),
        ]
    return e


def confinement_etat() -> dict:
    try:
        if not os.path.exists(_URG_FLAG):
            return {"ok": True, "actif": False}
        with open(_URG_FLAG, encoding="utf-8") as f:
            d = json.load(f)
        if str(d.get("fin", "")) <= _utcnow().strftime("%Y-%m-%d %H:%M"):
            # Échu : la machine rouvre la porte toute seule. C'est ce qui rend
            # le geste sûr.
            confinement_lever(acteur="échéance")
            return {"ok": True, "actif": False, "leve_auto": True}
        return {"ok": True, "actif": True, "niveau": d.get("niveau"),
                "fin": d.get("fin"), "ip": d.get("ip"), "par": d.get("par"), "motif": d.get("motif", ""),
                "faites": d.get("faites", []), "confirme": bool(d.get("confirme"))}
    except Exception as e:
        return {"ok": True, "actif": False, "reason": str(e)}


def confiner(niveau: int, ip: str, minutes: int = 30, mot: str = "",
             acteur: str = "", motif: str = "") -> dict:
    """Applique le confinement, étape par étape, en vérifiant entre chacune.
    Une crise déclenchée à la main se JUSTIFIE : le motif (10 caractères au moins) est gardé et consigné."""
    if str(mot or "").strip().upper() != "CONFINER":
        return {"ok": False, "reason": "confirmation attendue : tapez CONFINER"}
    motif = " ".join(str(motif or "").split())[:400]
    if len(motif) < 10:
        return {"ok": False, "reason": "justification attendue : dis pourquoi tu estimes le serveur compromis (10 caractères au moins)"}
    try:
        niveau = int(niveau)
    except Exception:
        niveau = 0
    if niveau not in _URG_NIVEAUX:
        return {"ok": False, "reason": "niveau inconnu (1, 2 ou 3)"}
    ip = str(ip or "").strip()
    if not re.match(r"^[0-9a-fA-F:.]{3,45}$", ip):
        return {"ok": False, "reason": "adresse de votre session illisible — refus "
                                       "prudent : sans elle, vous vous coupez vous-même"}
    if confinement_etat().get("actif"):
        return {"ok": False, "reason": "déjà confiné"}
    fin = (_utcnow() + timedelta(minutes=max(5, min(240, int(minutes or 30))))
           ).strftime("%Y-%m-%d %H:%M")
    faites, echec = [], ""
    for cle, libelle, cmd, _defaire in _urg_etapes(niveau, ip):
        try:
            if cle == "sessions":
                notif_urgence_sessions(acteur)
            elif cle == "gel":
                notif_geler(True, acteur)
            elif cle == "envois":
                notif_envois(True, acteur)
            else:
                ok, sortie = _urg_sh(cmd, timeout=30)
                if not ok:
                    echec = "%s : %s" % (libelle, sortie)
                    break
            faites.append(cle)
        except Exception as ex:
            echec = "%s : %s" % (libelle, ex)
            break
        # Le contrôle qui compte : après chaque étape, est-ce qu'on se joint
        # encore ? Un « non » défait tout, plutôt que de continuer à fermer.
        if cle.startswith("ufw") and not _urg_joignable(ip):
            echec = "après « %s », votre adresse ne semble plus joignable" % libelle
            break
    if echec:
        _urg_defaire(faites, niveau, ip)
        notif("Confinement abandonné", "Rien n'a été laissé en place. %s" % echec,
              source="securite", niveau="critique", cle="urgence:confinement-echec")
        return {"ok": False, "reason": echec, "defait": faites}
    try:
        os.makedirs(os.path.dirname(_URG_FLAG), exist_ok=True)
        with open(_URG_FLAG, "w", encoding="utf-8") as f:
            json.dump({"niveau": niveau, "fin": fin, "ip": ip, "par": acteur, "motif": motif,
                       "faites": faites, "confirme": False}, f)
    except Exception as e:
        logging.warning("[URGENCE] sentinelle : %s", e)
    notif("Serveur confiné — niveau %d" % niveau,
          "Par %s, depuis %s. Motif : %s. %d geste(s) appliqué(s). Retour automatique le %s si "
          "vous ne confirmez pas." % (acteur or "vous", ip, motif, len(faites), fin),
          source="securite", niveau="critique", cle="urgence:confinement")
    try:
        log_user_activity(acteur, acteur, "confinement", "niveau %d depuis %s — motif : %s" % (niveau, ip, motif))
    except Exception:
        pass
    return {"ok": True, "niveau": niveau, "fin": fin, "faites": faites, "ip": ip}


def _urg_defaire(faites: list, niveau: int, ip: str) -> list:
    """Défait dans l'ordre inverse. Le retour n'est pas une reconstruction."""
    refaits = []
    for cle, libelle, _cmd, defaire in reversed(_urg_etapes(niveau, ip)):
        if cle not in faites:
            continue
        try:
            if cle == "gel":
                notif_geler(False, "confinement levé")
            elif cle == "envois":
                notif_envois(False, "confinement levé")
            elif cle == "sessions":
                pass                    # une session révoquée ne se rend pas
            elif defaire:
                _urg_sh(defaire, timeout=30)
            refaits.append(cle)
        except Exception as e:
            logging.warning("[URGENCE] défaire %s : %s", cle, e)
    return refaits


# ── La crise déclenchée par Cassandra ───────────────────────────────────────────────────────────────────────
# Deux cas, décidés par Drisse (10-10) : le serveur est PARALYSÉ (la moitié ou plus des services critiques, ou des sites,
# en panne depuis plus de 5 minutes) ou il subit une ATTAQUE MAJEURE (un afflux d'adresses nouvelles d'un coup).
# Le premier palier est volontairement mince : les envois sont coupés et tout geste autonome est retenu — sauf les
# bannissements, qui sont la défense. Elle ne ferme ni accès ni clé. Se lève d'un geste, ou le dit quand c'est calme.
_CRISE_FLAG = CASSANDRA_DATA_DIR + "/crise_auto.json"
_CRISE_CLE = "crise/passer-en-lecture-seule"
_CRISE_VU = {"paralysie": None, "calme": None, "refus": 0.0, "cache": (0.0, None)}
_CRISE_DEFENSIFS = ("securite.bannir",)


def crise_auto_etat() -> dict:
    t, v = _CRISE_VU["cache"]
    if time.time() - t < 5 and v is not None:
        return v
    d = {"actif": False}
    try:
        if os.path.exists(_CRISE_FLAG):
            with open(_CRISE_FLAG, encoding="utf-8") as f:
                d = dict(json.load(f), actif=True)
    except Exception:
        d = {"actif": False}
    _CRISE_VU["cache"] = (time.time(), d)
    return d


def crise_lecture_seule(action_kind: str = "") -> bool:
    """Vrai quand une crise automatique est en cours ET que ce geste n'est pas défensif."""
    return bool(crise_auto_etat().get("actif")) and str(action_kind or "") not in _CRISE_DEFENSIFS


def _crise_mesurer() -> dict:
    """Les deux mesures, sans rien modifier. Une mesure qui échoue ne déclenche jamais rien : on ne crie pas au feu sur un doute."""
    res = {"paralysie": False, "attaque": False, "detail": []}
    part = float(_mem_cfg("crise_part_paralysie", 0.5) or 0.5)
    # 1. les services critiques : ceux qui existent sur cette machine, et eux seuls
    noms = [x.strip() for x in str(_mem_cfg("crise_services_critiques",
            "nginx,mysql,php8.2-fpm,fastpanel2,cassandra-vault,ssh,tailscaled") or "").split(",") if x.strip()]
    connus, tombes = 0, []
    for n in noms:
        try:
            st = fp_service_state(n)
        except Exception:
            continue
        if not st or not st.get("enabled") or st.get("enabled") in ("disabled", "masked", "not-found"):
            continue
        connus += 1
        if st.get("active") != "active":
            tombes.append(n)
    if connus >= 4 and len(tombes) / float(connus) >= part:
        res["paralysie"] = True
        res["detail"].append("%d services critiques sur %d à l'arrêt (%s)" % (len(tombes), connus, ", ".join(tombes)))
    # 2. les sites : un échantillon, sondé en parallèle
    try:
        doms = [str(d.get("domain") or "") for d in (get_fp_domains() or []) if isinstance(d, dict) and d.get("domain")][:12]
    except Exception:
        doms = []
    if len(doms) >= 2:
        from concurrent.futures import ThreadPoolExecutor
        try:
            with ThreadPoolExecutor(max_workers=6) as ex:
                rep = list(ex.map(lambda d: bool((_http_probe(d) or {}).get("ok")), doms))
            bas = [d for d, ok in zip(doms, rep) if not ok]
            if len(bas) / float(len(doms)) >= part:
                res["paralysie"] = True
                res["detail"].append("%d sites sur %d ne répondent plus" % (len(bas), len(doms)))
        except Exception as e:
            logging.info("[CRISE] sondes de sites : %s", e)
    # 3. l'attaque : des adresses NOUVELLES d'un coup, très au-dessus de l'ordinaire (≈ 25 adresses par 6 h sur Orion)
    try:
        import shutil
        if shutil.which("cscli"):
            fen = max(2, int(_mem_cfg("crise_attaque_fenetre_min", 10) or 10))
            seuil = int(_mem_cfg("crise_attaque_adresses", 40) or 40)
            ok, brut = _sec_cscli(["alerts", "list", "--since", "%dm" % fen, "--limit", "0", "-o", "json"])
            if ok:
                adr = set()
                for a in (json.loads(brut or "null") or []):
                    v = str(((a.get("source") or {}).get("value")) or "")
                    if v and not _sec_de_confiance(v):
                        adr.add(v)
                if len(adr) >= seuil:
                    res["attaque"] = True
                    res["detail"].append("%d adresses différentes repoussées en %d minutes (seuil %d)" % (len(adr), fen, seuil))
    except Exception as e:
        logging.info("[CRISE] mesure de l'attaque : %s", e)
    return res


def crise_auto_lever(acteur: str = "", motif: str = "") -> dict:
    if not crise_auto_etat().get("actif"):
        return {"ok": False, "reason": "aucune crise automatique en cours"}
    try:
        os.remove(_CRISE_FLAG)
    except Exception:
        pass
    _CRISE_VU["cache"] = (0.0, None)
    try:
        notif_envois(False, acteur or "vous")
    except Exception as e:
        logging.warning("[CRISE] réouverture des envois : %s", e)
    try:
        notif_resoudre_cle("crise:auto", par=acteur or "vous", detail="crise levée")
        log_user_activity(acteur, acteur, "crise_levee", " ".join(str(motif or "").split())[:200] or "levée")
    except Exception:
        pass
    return {"ok": True}


def crise_veille() -> dict:
    """Appelée chaque minute. Déclenche la crise si une mesure tient assez longtemps, et DIT quand tout est redevenu calme."""
    if not _mem_cfg("crise_auto_enabled", True):
        return {"ok": True, "disabled": True}
    now = time.time()
    m = _crise_mesurer()
    etat = crise_auto_etat()
    duree = max(60, int(_mem_cfg("crise_duree_s", 300) or 300))
    if etat.get("actif"):
        if m["paralysie"] or m["attaque"]:
            _CRISE_VU["calme"] = None
        else:
            _CRISE_VU["calme"] = _CRISE_VU["calme"] or now
            if now - _CRISE_VU["calme"] >= 900 and not etat.get("calme_dit"):
                try:
                    notif("La situation est revenue à la normale", "Depuis 15 minutes, plus de service critique à l'arrêt ni d'afflux d'adresses. "
                          "La crise reste en place tant que tu ne l'as pas levée (Sécurité › Confiner Cassandra › Lever la crise).",
                          source="securite", niveau="avoir", cle="crise:retour")
                    d = dict(etat); d.pop("actif", None); d["calme_dit"] = True
                    with open(_CRISE_FLAG, "w", encoding="utf-8") as f:
                        json.dump(d, f)
                    _CRISE_VU["cache"] = (0.0, None)
                except Exception as e:
                    logging.info("[CRISE] avis de retour au calme : %s", e)
        return {"ok": True, "en_cours": True}
    # la paralysie doit TENIR plus de cinq minutes ; l'attaque est déjà mesurée sur une fenêtre
    if m["paralysie"]:
        _CRISE_VU["paralysie"] = _CRISE_VU["paralysie"] or now
    else:
        _CRISE_VU["paralysie"] = None
    tient = bool(_CRISE_VU["paralysie"] and now - _CRISE_VU["paralysie"] >= duree)
    if not (tient or m["attaque"]):
        return {"ok": True, "calme": True}
    if now - _CRISE_VU["refus"] < 900:
        return {"ok": True, "retenue": True}           # déjà retenue par une règle il y a moins de 15 minutes
    raison = " · ".join(m["detail"]) or "mesure inconnue"
    porte = aut_porte(_CRISE_CLE, "crise", "Crise : %s" % raison)
    if not porte.get("ok"):
        _CRISE_VU["refus"] = now
        try:
            notif("Crise détectée, non déclenchée", "%s. Retenue par la règle (%s). Tu peux la déclencher toi-même dans Sécurité › Confiner Cassandra."
                  % (raison, porte.get("motif", "?")), source="securite", niveau="critique", cle="crise:retenue")
        except Exception:
            pass
        return {"ok": True, "retenue": True}
    ok_envois = True
    try:
        notif_envois(True, "cassandra")
    except Exception as e:
        ok_envois = False
        logging.warning("[CRISE] coupure des envois : %s", e)
    try:
        os.makedirs(os.path.dirname(_CRISE_FLAG), exist_ok=True)
        with open(_CRISE_FLAG, "w", encoding="utf-8") as f:
            json.dump({"depuis": now, "raison": raison, "par": "cassandra",
                       "types": [k for k in ("paralysie", "attaque") if m[k]], "envois": ok_envois}, f)
    except Exception as e:
        logging.warning("[CRISE] drapeau : %s", e)
        aut_fin(porte, False, raison, "drapeau non écrit : %s" % str(e)[:80])
        return {"ok": False, "reason": str(e)}
    _CRISE_VU["cache"] = (0.0, None)
    _CRISE_VU["paralysie"] = None
    aut_fin(porte, True, raison, "envois coupés, gestes autonomes retenus (sauf les bannissements)")
    try:
        notif("Crise déclenchée par Cassandra", "%s. Les envois sont coupés et ses gestes autonomes sont retenus, sauf les bannissements. "
              "Elle ne ferme aucun accès. Lève la crise quand c'est réglé : Sécurité › Confiner Cassandra." % raison,
              source="securite", niveau="critique", nature="etat", sujet="crise", cle="crise:auto")
    except Exception as e:
        logging.warning("[CRISE] notification : %s", e)
    return {"ok": True, "declenchee": True, "raison": raison}


_CRISE_BOUCLE = [False]


def _crise_boucle():
    time.sleep(60)
    while True:
        try:
            crise_veille()
        except Exception as e:
            logging.warning("[CRISE] veille : %s", e)
        time.sleep(60)


def _crise_demarrer() -> None:
    if _CRISE_BOUCLE[0]:
        return
    _CRISE_BOUCLE[0] = True
    threading.Thread(target=_crise_boucle, daemon=True, name="crise-veille").start()


def confinement_lever(acteur: str = "") -> dict:
    e = None
    try:
        if os.path.exists(_URG_FLAG):
            with open(_URG_FLAG, encoding="utf-8") as f:
                e = json.load(f)
    except Exception:
        e = None
    if not e:
        return {"ok": False, "reason": "aucun confinement en cours"}
    refaits = _urg_defaire(e.get("faites", []), int(e.get("niveau", 1)), e.get("ip", ""))
    try:
        os.remove(_URG_FLAG)
    except Exception:
        pass
    notif_resoudre_cle("urgence:confinement", par=acteur or "vous",
                       detail="%d geste(s) défait(s)" % len(refaits))
    return {"ok": True, "defaits": refaits}


def confinement_confirmer(minutes: int = 240, acteur: str = "") -> dict:
    """Repousse l'échéance : vous êtes toujours là, le confinement peut durer."""
    try:
        with open(_URG_FLAG, encoding="utf-8") as f:
            e = json.load(f)
    except Exception:
        return {"ok": False, "reason": "aucun confinement en cours"}
    e["confirme"] = True
    e["fin"] = (_utcnow() + timedelta(minutes=max(5, min(1440, int(minutes or 240))))
                ).strftime("%Y-%m-%d %H:%M")
    try:
        with open(_URG_FLAG, "w", encoding="utf-8") as f:
            json.dump(e, f)
    except Exception as ex:
        return {"ok": False, "reason": str(ex)}
    return {"ok": True, "fin": e["fin"]}


def notif_urgence_sessions(acteur: str = "", jeton: str = "") -> dict:
    try:
        n = revoke_other_sessions(acteur, jeton)
        try:
            log_user_activity(acteur, acteur, "sessions_revoquees", "%d session(s)" % n)
        except Exception:
            pass
        return {"ok": True, "revoquees": n}
    except Exception as e:
        return {"ok": False, "reason": str(e)}


def _nt_urgence_usages() -> dict:
    """Combien de fois chaque geste a servi, et quand — lu dans `user_activity` (B28 : envois et
    sessions ne laissaient aucune trace ; le confinement n'a jamais tourné)."""
    out = {}
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        for k in ("autonomie_gel", "envois_coupes", "sessions_revoquees", "confinement"):
            r = conn.execute("SELECT COUNT(*), MAX(ts) FROM user_activity WHERE action = ?", (k,)).fetchone()
            out[k] = {"n": int(r[0] or 0), "dernier": r[1] or ""}
        conn.close()
    except Exception:
        pass
    return out


def notif_urgence_etat() -> dict:
    c = confinement_etat()
    return {"gel": autonomie_gelee(),
            "envois_coupes": bool(_urg_cfg("envois_coupes", False)),
            "confine": bool(c.get("actif")), "confinement": c, "crise": crise_auto_etat(),
            "usages": _nt_urgence_usages()}


# ── Les actions proposées par une notification ──────────────────────────────
def notif_agir(nid, action: str, acteur: str = "", jeton: str = "", confirme: bool = False) -> dict:
    """Exécute l'action d'une notification.

    Le registre est PAR SOURCE, mais le geste vise le SUJET de la ligne : sans sujet, aucun geste n'a de
    cible et l'action est refusée (six boutons sans cible mesurés au tour 24). « Envoyer » un mandat ne
    traite plus « les dix premiers en attente » (B9) mais l'envoi de la ligne. Une ligne dont le titre vient
    du dehors (`provenance = externe`) n'agit qu'avec `confirme` — l'écran l'a demandé, en citant le texte."""
    _nt_migrate()
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10); conn.row_factory = sqlite3.Row
        r = conn.execute("SELECT * FROM notifs WHERE id=?", (int(nid),)).fetchone()
        conn.close()
    except Exception as e:
        return {"ok": False, "reason": str(e)}
    if not r:
        return {"ok": False, "reason": "notification introuvable"}
    n = dict(r)
    src = _NOTIF_SOURCES.get(n["source"]) or {}
    sujet = str(n.get("sujet") or "")
    permises = {a["cle"] for a in _nt_actions(src, sujet)}
    if action not in permises:
        if action in [a[0] for a in src.get("actions", [])] and not sujet:
            return {"ok": False, "reason": "cette notification n'a pas de sujet : le geste n'aurait pas de cible"}
        return {"ok": False, "reason": "cette action n'appartient pas à cette notification"}
    if str(n.get("provenance") or "") == "externe" and not confirme:
        return {"ok": False, "reason": "ce signalement vient d'un texte extérieur : confirmez avant d'agir",
                "confirmer": True}
    try:
        if action == "sessions":
            return notif_urgence_sessions(acteur, jeton)
        if action == "geler":
            return notif_geler(True, acteur)
        if action == "ssl_renouveler":
            return fp_ssl_issue(sujet, confirm=True)
        if action == "ssl_test":
            return fp_ssl_issue(sujet, confirm=True, staging=True)
        if action == "nginx":
            return fp_service_action("nginx", "restart", confirm=True)
        if action == "php":
            return fp_service_action("php-fpm", "restart", confirm=True)
        if action == "sauv_relancer":
            pid = sujet.split(":", 1)[1] if sujet.startswith("plan:") else sujet
            for p in (sauv_plans(inclure_fp=False).get("plans") or []):
                if str(p.get("id")) == pid:
                    return sauv_plan_run(p["id"], blanc=False, confirm=True, acteur=acteur)
            return {"ok": False, "reason": "plan introuvable depuis cette notification"}
        if action == "sauv_verifier":
            h = (sauv_historique(limit=1).get("copies") or [])
            if not h:
                return {"ok": False, "reason": "aucune copie à vérifier"}
            return sauv_verifier(h[0]["id"])
        if action in ("cron_run", "cron_essai"):
            ref = sujet.split(":", 1)[1] if sujet.startswith("cron:") else sujet
            return cron_run_now(ref=ref, essai=(action == "cron_essai"), declencheur="notification")
        if action in ("mandat_ok", "mandat_non"):
            if not sujet.startswith("envoi:"):
                return {"ok": False, "reason": "cette notification ne désigne pas un envoi"}
            eid = sujet.split(":", 1)[1]
            att = [e for e in (mandat_envois("attente").get("envois") or []) if str(e.get("id")) == eid]
            if not att:
                return {"ok": False, "reason": "cet envoi n'attend plus"}
            r2 = (mandat_envoyer(att[0]["id"], confirm=True, acteur=acteur) if action == "mandat_ok"
                  else mandat_annuler(att[0]["id"], acteur=acteur))
            if r2.get("ok"):
                notif_resoudre(int(nid), par=acteur or "vous", detail="envoi %s" % ("posté" if action == "mandat_ok" else "refusé"))
            return r2
        if action == "corbeille":
            return ged_corbeille_vider(confirm=True, acteur=acteur)
        if action == "journaux":
            ok, sortie = _urg_sh("journalctl --vacuum-time=7d", timeout=120)
            return {"ok": ok, "detail": sortie}
        if action == "rappel_vu":
            return notif_acquitter(int(nid), acteur)
        if action == "autotache_tache":
            _k, _r = (sujet.split("|", 1) + [""])[:2]
            t = itare_task_from_source(_k, _r, str(n.get("titre") or ""), force=True, manuel=True)
            if t.get("ok"):
                notif_resoudre_cle(str(n.get("cle") or ""), par=acteur or "geste",
                                   detail="tâche #%s créée" % t.get("task_id"))
            return t
        if action == "autotache_ignorer":
            return {"ok": bool(notif_resoudre_cle(str(n.get("cle") or ""), par=acteur or "geste",
                                                  detail="sans suite"))}
        if action in ("disque_voir", "mesure_voir", "flotte_fiche", "salon_fil"):
            # Ces gestes OUVRENT un écran : la cible est rendue, l'écran la suit (B6 : l'aller n'était
            # jamais consommé).
            return {"ok": True, "aller": _nt_aller(src, sujet)}
        if action in ("pf_faire", "pf_pourquoi", "pf_plus_tard"):
            # `sujet` porte la clé de la découverte ; sans elle on ne saurait pas
            # quoi traiter, et le bouton serait décoratif.
            cx = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
            row = cx.execute("SELECT id FROM proactive_findings WHERE fkey=? "
                             "OR category=? ORDER BY id DESC LIMIT 1",
                             (sujet, sujet)).fetchone()
            cx.close()
            if not row:
                return {"ok": False, "reason": "découverte introuvable — elle a peut-être "
                                               "déjà été résolue"}
            if action == "pf_faire":
                return proactive_act(row[0], acteur=acteur)
            if action == "pf_pourquoi":
                return proactive_investigate(row[0])
            return proactive_snooze(row[0], hours=168)
    except Exception as e:
        return {"ok": False, "reason": str(e)}
    return {"ok": False, "reason": "action non implémentée"}


def notif_webhook_set(d: dict) -> dict:
    """Le webhook de la MACHINE, écrit dans alerts.yml — il n'avait aucun écran, aucune route (tour 8)."""
    d = d or {}
    url = str(d.get("url") or "").strip()
    if url and not url.startswith(("http://", "https://")):
        return {"ok": False, "reason": "l'adresse doit commencer par http:// ou https://"}
    headers = d.get("headers") if isinstance(d.get("headers"), dict) else {}
    cfg = {"enabled": bool(d.get("enabled")) and bool(url), "url": url,
           "payload_template": str(d.get("payload_template") or "").strip(),
           "headers": {str(k)[:60]: str(v)[:200] for k, v in headers.items()}}
    ok = _write_alerts_yaml(webhook_cfg=cfg)
    return {"ok": bool(ok), "reason": "" if ok else getattr(_write_alerts_yaml, "raison", "écriture impossible")}


def notif_route(path: str, data: dict, compte: str, admin: bool, sid: str = ""):
    """Les routes du centre. Rend (réponse, statut) ou None si la route n'est pas la sienne.

    L'appelant a posé le compte sur le fil : ici on ne lit que ce qu'on reçoit. Les gestes de la PERSONNE
    (lire, vu, acquitter, sourdine, politique, préférences) sont ouverts à tout compte ; ce qui touche la
    machine ou une ligne d'un autre (résoudre, supprimer, agir, essai, sources, webhook) reste admin."""
    d = data or {}
    compte = (compte or "").strip().lower()
    if path == "/api/notifs":
        return notifs(int(d.get("limit", 40) or 40), tout=bool(d.get("tout")), vue=str(d.get("vue") or ""),
                      compte=compte, admin=admin, depuis=int(d.get("depuis") or 0)), 200
    if path == "/api/notif/compteurs":
        return {"ok": True, "compteurs": notif_compteurs(compte, admin), "battement": _nt_battement()}, 200
    if path in ("/api/notif/vu", "/api/notif/lues"):
        return notif_vu(d.get("ids"), compte), 200
    if path == "/api/notif/acquitter":
        r = notif_acquitter(d.get("id"), compte)
        return r, (200 if r.get("ok") else 400)
    if path == "/api/notif/sourdine":
        r = notif_sourdine_poser(compte, str(d.get("portee") or "source"), str(d.get("cible") or ""),
                                 d.get("heures", 0))
        return r, (200 if r.get("ok") else 400)
    if path == "/api/notif/sourdines":
        return {"ok": True, "sourdines": notif_sourdines(compte)}, 200
    if path == "/api/notif/politique":
        if d.get("set"):
            qui = _NT_MACHINE if d.get("machine") else compte
            if qui == _NT_MACHINE and not admin:
                return {"ok": False, "reason": "réservé à un administrateur"}, 403
            r = notif_politique_set(qui, str(d.get("niveau") or ""), d.get("canaux") or [])
            return r, (200 if r.get("ok") else 400)
        return {"ok": True, "moi": notif_politique(compte), "machine": notif_politique(_NT_MACHINE),
                "defaut": _NT_POLITIQUE_DEFAUT, "prefs": _nt_prefs(compte),
                "canaux": notif_canaux_etat(compte), "sourdines": notif_sourdines(compte),
                "grace_min": _mem_cfg("notif_grace_min", 5), "admin": bool(admin)}, 200
    if path == "/api/notif/prefs":
        r = notif_prefs_set(compte, d)
        return r, (200 if r.get("ok") else 400)
    # ── au-delà : la machine, ou la ligne d'un autre — administrateur seulement ──
    if not admin:
        return {"error": "Action non autorisée pour ton rôle"}, 403
    if path == "/api/notif/resoudre":
        r = notif_resoudre(d.get("id"), par=compte or "vous", detail=str(d.get("detail") or ""))
        return r, (200 if r.get("ok") else 400)
    if path == "/api/notif/supprimer":
        r = notif_supprimer(d.get("ids"), reglees=bool(d.get("reglees")))
        return r, (200 if r.get("ok") else 400)
    if path == "/api/notif/agir":
        r = notif_agir(d.get("id"), str(d.get("action") or ""), acteur=compte, jeton=sid,
                       confirme=bool(d.get("confirme")))
        return r, (200 if r.get("ok") else 400)
    if path == "/api/notif/essai":
        return notif_essai(compte, str(d.get("canal") or "cloche")), 200
    if path == "/api/notif/sources":
        return {"ok": True, "sources": notif_sources_etat(),
                "sondes": {k: {"cadence_s": v[1], "sources": list(v[2]), "vue": _NT_SONDE_VUE.get(k, "")}
                           for k, v in _NT_SONDES.items()},
                "passe": _nt_battement()}, 200
    if path == "/api/notif/passe":
        return {"ok": True, "passe": _nt_passe(force=True)}, 200
    if path == "/api/notif/webhook":
        if d.get("set"):
            r = notif_webhook_set(d)
            return r, (200 if r.get("ok") else 400)
        cfg = (load_alert_config() or {}).get("webhook", {}) or {}
        return {"ok": True, "webhook": {"enabled": bool(cfg.get("enabled")), "url": str(cfg.get("url") or ""),
                                        "payload_template": str(cfg.get("payload_template") or ""),
                                        "headers": cfg.get("headers") or {}}}, 200
    return None


