_alert_thread_started = False
_alerts_lock = threading.Lock()


def save_alert(level: str, category: str, message: str):
    """Le moteur de seuils parle au centre, et à lui seul (B8, B13).

    La catégorie dit la SOURCE — un certificat n'est pas un disque — et la SONDE qui refermera l'état
    quand la mesure rentre. La charge se tait pendant la grâce du démarrage : trois « load critical » sur
    quatre tombaient dans les onze minutes d'un redémarrage, le temps du préchargement des embeddings."""
    cat = str(category or "")
    niveau = "critique" if level == "critical" else "avoir"
    if cat == "load" and _nt_grace():
        logging.info("[NOTIF] alerte retenue : démarrage (%s)", cat)
        return
    if cat.startswith("ssl_"):
        source, sujet, sonde = "certificat", cat[4:], "ssl:%s" % cat[4:]
    elif cat.startswith("svc_"):
        source, sujet, sonde = "systeme", "service:%s" % cat[4:], "service:%s" % cat[4:]
    elif cat.startswith("disk"):
        source, sujet, sonde = "systeme", cat, "seuil:%s" % cat
    elif cat == "memory":
        source, sujet, sonde = "systeme", "ram", "seuil:ram"
    elif cat == "load":
        source, sujet, sonde = "systeme", "load", "seuil:load"
    else:
        source, sujet, sonde = "systeme", cat, ""
    try:
        notif(message, "", source=source, niveau=niveau, nature="etat", sujet=sujet,
              cle="%s:%s" % (source, sujet), sonde=sonde)
    except Exception as e:
        logging.info("[NOTIF] relais des seuils : %s", e)


def get_alerts(include_resolved: bool = False, limit: int = 50) -> list:
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH)
        conn.row_factory = sqlite3.Row
        q = "SELECT * FROM alerts ORDER BY id DESC LIMIT ?" if include_resolved else \
            "SELECT * FROM alerts WHERE resolved=0 ORDER BY id DESC LIMIT ?"
        rows = conn.execute(q, (limit,)).fetchall()
        conn.close()
        return [dict(r) for r in rows]
    except Exception:
        return []


def resolve_alert(alert_id: int):
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH)
        conn.execute("UPDATE alerts SET resolved=1,resolved_at=datetime('now') WHERE id=?", (alert_id,))
        conn.commit()
        conn.close()
    except Exception:
        pass


def _monitoring_loop():
    import os
    import shutil as _sh
    import subprocess
    import time
    import logging
    _log = logging.getLogger(__name__)

    # PERF: Use a local cache with maxsize to avoid repetitive attribute lookups
    from functools import lru_cache

    # PERF: Replace manual alert cache with bounded LRU cache to limit memory usage
    @lru_cache(maxsize=128)
    def _cached_fire_alert(alert_type, severity, source, message, channels_tuple=()):
        channels = list(channels_tuple)
        try:
            fire_alert(alert_type, severity, source, message, channels)
            _log.debug("Alert fired: %s %s %s", alert_type, source, message)
        except Exception as exc:
            _log.error("Failed to fire alert %s: %s", alert_type, exc)

    cfg = load_alert_config()
    rules = cfg.get("rules", []) if cfg else []
    _rules_map = {r["name"]: r for r in rules if isinstance(r, dict) and "name" in r}

    # Les canaux par règle ont disparu avec le lot A : la politique du centre décide, par personne.

    _meminfo_path = "/proc/meminfo"
    _mounts = ["/", "/var", "/home", "/tmp", "/var/www"]
    # ROBUSTESSE: deduplicate and ensure absolute paths
    _mounts = list(dict.fromkeys(os.path.abspath(m) for m in _mounts if isinstance(m, str) and m))
    # PERF: Pre-validate mounts existence and readability once
    _valid_mounts = [
        m for m in _mounts
        if os.path.isdir(m) and os.access(m, os.R_OK)
    ]
    _services = ["nginx","apache2","mysql","mariadb","postfix","sshd",
                 "php8.1-fpm","php8.2-fpm","php8.3-fpm","fastpanel2"]
    _services = list(dict.fromkeys(s for s in _services if isinstance(s, str) and s))
    _th = cfg.get("thresholds") or {}

    def _thv(k, default):
        try:
            val = float(_th.get(k, default))
            if k in ("disk_critical", "disk_warning", "ram_critical", "ram_warning"):
                return max(0.0, min(100.0, val))
            if k in ("load_critical", "load_warning"):
                return max(0.0, val)
            return val
        except (TypeError, ValueError):
            return float(default)

    _disk_critical = _thv("disk_critical", 90)
    _disk_warning  = _thv("disk_warning", 80)
    _ram_critical  = _thv("ram_critical", 95)
    _ram_warning   = _thv("ram_warning", 88)
    _load_critical = _thv("load_critical", 3.0)
    _load_warning  = _thv("load_warning", 2.0)
    _ssl_critical_days = 3
    _ssl_warning_days = 14
    _ncpu = max(1, os.cpu_count() or 1)

    # PERF: Check systemctl availability once and store path string
    _systemctl_path = None
    try:
        proc = subprocess.run(["which", "systemctl"], capture_output=True, text=True, timeout=2)
        if proc.returncode == 0:
            _systemctl_path = proc.stdout.strip()
    except Exception:
        _systemctl_path = None
    _has_systemctl = _systemctl_path is not None

    # PERF: Cache threshold values in a dict for quick lookup
    _thresholds = {
        "disk_critical": _disk_critical,
        "disk_warning": _disk_warning,
        "ram_critical": _ram_critical,
        "ram_warning": _ram_warning,
        "load_critical": _load_critical,
        "load_warning": _load_warning,
    }

    # PERF: Helper function to read file content with timeout and caching (avoids repeated os.path.exists)
    def _read_file(path):
        try:
            with open(path) as f:
                return f.read()
        except (IOError, OSError):
            return None

    while True:
        try:
            time.sleep(60)
            # Clear the LRU cache to reset alerts each iteration
            _cached_fire_alert.cache_clear()

            # ---- rappels ----
            # La minute est la granularité de l'écran : une pré-alerte « dans
            # 30 min » posée à une cadence de cinq minutes arriverait à cinq
            # minutes près, ce qui ne se voit pas mais s'accumule. La passe est
            # idempotente : les drapeaux en base empêchent le double envoi.
            # LOT 4 : `rap_tick` a sa propre passe (`_rap_boucle`), elle ne tombe plus avec celle-ci.

            # ---- disk ----
            for m in _valid_mounts:
                try:
                    u = _sh.disk_usage(m)
                    if u.total <= 0:
                        _log.warning("Disk %s total size is zero or negative, skipping", m)
                        continue
                    pct = u.used / u.total * 100
                    if pct < _thresholds["disk_warning"]:
                        notif_resoudre_cle("systeme:disk_%s" % m, par="rentré dans l'ordre",
                                           detail="disque %s repassé à %.0f %%" % (m, pct))
                    if pct >= _thresholds["disk_critical"]:
                        _cached_fire_alert("disk_critical","critical",f"disk_{m}",
                            f"Disque {m} : {pct:.0f}% utilisé")
                    elif pct >= _thresholds["disk_warning"]:
                        _cached_fire_alert("disk_warning","warning",f"disk_{m}",
                            f"Disque {m} : {pct:.0f}% utilisé")
                except (PermissionError, OSError) as exc:
                    _log.warning("Disk check failed for %s: %s", m, exc)
                except Exception as exc:
                    _log.error("Unexpected error checking disk %s: %s", m, exc)

            # ---- RAM ----
            mi_text = _read_file(_meminfo_path)
            if mi_text is not None:
                try:
                    mi = {}
                    for line in mi_text.splitlines():
                        if ":" not in line:
                            continue
                        k, v = line.split(":", 1)
                        try:
                            mi[k.strip()] = int(v.strip().split()[0])
                        except (ValueError, IndexError):
                            pass
                    total = mi.get("MemTotal", 1)
                    avail = mi.get("MemAvailable")
                    if avail is None:
                        free = mi.get("MemFree", 0)
                        buffers = mi.get("Buffers", 0)
                        cached = mi.get("Cached", 0)
                        avail = free + buffers + cached
                    if total <= 0:
                        raise ValueError("MemTotal is zero or negative")
                    pct = (total - avail) / total * 100
                    if pct >= _thresholds["ram_critical"]:
                        _cached_fire_alert("ram_critical","critical","memory",
                            f"RAM critique : {pct:.0f}% utilisée")
                    elif pct >= _thresholds["ram_warning"]:
                        _cached_fire_alert("ram_warning","warning","memory",
                            f"RAM élevée : {pct:.0f}% utilisée")
                except Exception as exc:
                    _log.error("RAM check failed: %s", exc)
            else:
                _log.error("RAM check: %s not found or unreadable", _meminfo_path)

            # ---- load ----
            # PERF: Use os.getloadavg() instead of reading /proc/loadavg
            try:
                la1, la5, la15 = os.getloadavg()
                lpc = la1 / _ncpu
                if lpc >= _thresholds["load_critical"]:
                    _cached_fire_alert("load_critical","critical","load",
                        f"Load Average critique : {la1:.2f} ({_ncpu} CPUs, {lpc:.1f}/core)")
                elif lpc >= _thresholds["load_warning"]:
                    _cached_fire_alert("load_warning","warning","load",
                        f"Load Average élevé : {la1:.2f} ({lpc:.1f}/core)")
            except OSError as exc:
                _log.error("Load check (getloadavg) failed: %s", exc)

            # ---- services ----
            if not _has_systemctl:
                _log.warning("systemctl not available, skipping service checks")
            elif not _services:
                _log.warning("No services configured, skipping service checks")
            else:
                try:
                    proc = subprocess.run(["systemctl", "is-active"] + _services,
                                         capture_output=True, text=True, timeout=10, check=False)
                    lines = [l.strip() for l in proc.stdout.strip().split('\n') if l.strip()]
                    if len(lines) != len(_services):
                        _log.warning("systemctl returned %d lines, expected %d – skipping",
                                     len(lines), len(_services))
                    else:
                        for svc, state in zip(_services, lines):
                            if state not in ("active","activating","","inactive"):
                                _cached_fire_alert(f"svc_{svc}","critical",f"svc_{svc}",
                                    f"Service {svc} : {state}")
                    if proc.returncode != 0 and not lines:
                        _log.warning("systemctl is-active returned %d (no output)", proc.returncode)
                except subprocess.TimeoutExpired:
                    _log.warning("Service checks timeout")
                except Exception as exc:
                    _log.error("Service checks error: %s", exc)

            # ---- SSL ----
            try:
                try:
                    ssl_rows = query_db("SELECT domain, days_left FROM ssl_certificates ORDER BY days_left ASC LIMIT 20")
                except Exception as exc:
                    _log.error("SSL query_db failed: %s", exc)
                    ssl_rows = []
                if not isinstance(ssl_rows, list):
                    ssl_rows = []
                for row in ssl_rows:
                    if not isinstance(row, dict):
                        _log.warning("SSL query returned non-dict row: %s", row)
                        continue
                    days = row.get("days_left", 999)
                    dom = row.get("domain", "?")
                    if not isinstance(days, (int, float)):
                        try:
                            days = int(days) if days is not None else 999
                        except (ValueError, TypeError):
                            days = 999
                    if days <= _ssl_critical_days:
                        _cached_fire_alert(f"ssl_critical_{dom}","critical",f"ssl_{dom}",
                            f"SSL '{dom}' expire dans {days} jours !")
                    elif days <= _ssl_warning_days:
                        _cached_fire_alert(f"ssl_warning_{dom}","warning",f"ssl_{dom}",
                            f"SSL '{dom}' expire dans {days} jours")
            except Exception as exc:
                _log.error("SSL check failed: %s", exc)

        except KeyboardInterrupt:
            _log.info("Monitoring loop interrupted by user")
            break
        except Exception as exc:
            _log.exception("Unexpected error in monitoring loop: %s", exc)


def start_monitoring():
    global _alert_thread_started
    if not _alert_thread_started:
        _alert_thread_started = True
        threading.Thread(target=_monitoring_loop, daemon=True, name="monitoring-loop").start()
        threading.Thread(target=_plex_veille_boucle, daemon=True, name="plex-veille").start()
        # L'ECOUTEUR d'Itare demarre AVEC la surveillance : sans cela, il
        # faudrait rouvrir un ecran apres chaque redemarrage pour qu'elle
        # reponde de nouveau. Il se tait tout seul tant qu'aucun compte ne lui
        # est relie — la fonction le verifie a chaque tour.
        try:
            if "ita_ecoute_demarrer" in globals():
                ita_ecoute_demarrer()
        except Exception as e:
            logging.info("[ITA] demarrage de l ecoute : %s", e)


