_OLLAMA_PULL = {"model": "", "status": "", "percent": 0, "running": False, "error": ""}
_OLLAMA_PULL_LOCK = threading.Lock()


def _ollama_base() -> str:
    try:
        u = (get_cassandra_config().get("ollama_base") or "http://127.0.0.1:11434").strip()
    except Exception:
        u = "http://127.0.0.1:11434"
    return u.rstrip("/")


def _lab_resources() -> dict:
    m = {}
    try:
        m = get_metrics() or {}
    except Exception:
        m = {}
    total = float(m.get("ram_total_gb", 0) or 0)
    used = float(m.get("ram_used_gb", 0) or 0)
    return {"ram_total_gb": round(total, 1), "ram_used_gb": round(used, 1),
            "ram_free_gb": round(max(0.0, total - used), 1),
            "cpu_cores": (os.cpu_count() or 1),
            "disk_free_gb": round(float(m.get("disk_free_gb", 0) or 0), 1)}


def _lab_fit(ram_needed: float, res: dict) -> str:
    """🟢 confortable / 🟠 juste / 🔴 trop lourd, selon la RAM TOTALE du serveur."""
    total = res.get("ram_total_gb", 0)
    if total >= ram_needed * 1.5:
        return "ok"
    if total >= ram_needed:
        return "tight"
    return "heavy"


def ollama_available() -> bool:
    try:
        with _ull.urlopen(_ollama_base() + "/api/tags", timeout=3) as r:
            return r.status == 200
    except Exception:
        return False


def ollama_list() -> list:
    try:
        with _ull.urlopen(_ollama_base() + "/api/tags", timeout=5) as r:
            d = json.loads(r.read().decode("utf-8", "replace"))
        return [{"name": x.get("name"), "size_gb": round((x.get("size", 0) or 0) / 1e9, 1)}
                for x in (d.get("models") or [])]
    except Exception:
        return []


def ollama_pull_async(model: str) -> dict:
    model = (model or "").strip()
    if not model:
        return {"ok": False, "error": "modèle requis"}
    # Un nom saisi à la main (champ « Un autre modèle d'Ollama ») : le format d'un nom Ollama, rien d'autre.
    if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._/-]{0,100}(?::[A-Za-z0-9._-]{1,60})?", model):
        return {"ok": False, "error": "nom de modèle invalide : « %s »" % model[:80]}
    with _OLLAMA_PULL_LOCK:
        if _OLLAMA_PULL["running"]:
            return {"ok": False, "error": "un téléchargement est déjà en cours (%s)" % _OLLAMA_PULL["model"]}
        _OLLAMA_PULL.update({"model": model, "status": "démarrage…", "percent": 0, "running": True, "error": ""})

    def _run():
        try:
            data = json.dumps({"name": model, "stream": True}).encode()
            req = _ull.Request(_ollama_base() + "/api/pull", data=data,
                               headers={"Content-Type": "application/json"})
            with _ull.urlopen(req, timeout=3600) as r:
                for raw in r:
                    raw = raw.strip()
                    if not raw:
                        continue
                    try:
                        j = json.loads(raw.decode("utf-8", "replace"))
                    except Exception:
                        continue
                    tot, comp = j.get("total"), j.get("completed")
                    pct = int(comp / tot * 100) if (tot and comp) else None
                    with _OLLAMA_PULL_LOCK:
                        _OLLAMA_PULL["status"] = j.get("status", "") or _OLLAMA_PULL["status"]
                        if pct is not None:
                            _OLLAMA_PULL["percent"] = pct
                        if j.get("error"):
                            _OLLAMA_PULL["error"] = j["error"]
            with _OLLAMA_PULL_LOCK:
                if not _OLLAMA_PULL["error"]:
                    _OLLAMA_PULL["status"] = "terminé"; _OLLAMA_PULL["percent"] = 100
        except Exception as e:
            with _OLLAMA_PULL_LOCK:
                _OLLAMA_PULL["error"] = str(e); _OLLAMA_PULL["status"] = "erreur"
        finally:
            with _OLLAMA_PULL_LOCK:
                _OLLAMA_PULL["running"] = False
    threading.Thread(target=_run, daemon=True, name="ollama-pull").start()
    return {"ok": True}


def ollama_pull_status() -> dict:
    with _OLLAMA_PULL_LOCK:
        return dict(_OLLAMA_PULL)


def ollama_delete(model: str) -> dict:
    try:
        req = _ull.Request(_ollama_base() + "/api/delete",
                           data=json.dumps({"name": (model or "").strip()}).encode(),
                           method="DELETE", headers={"Content-Type": "application/json"})
        _ull.urlopen(req, timeout=15)
        return {"ok": True}
    except Exception as e:
        return {"ok": False, "error": str(e)}


# ══════════════════════════════════════════════════════════════════════════════
#  CE QU'ITARE A SOUS LES YEUX
#
#  Le contexte d'une conversation était invisible : on ne savait pas ce qu'il
#  regardait. Il devient une LISTE que l'on compose. Ce qui n'y est pas n'existe
#  pas pour lui, et ce qui y est se cite.
#
#  Registre déclaratif, comme `_METRICS` ou `_PJ_PREUVES` : chaque nature de
#  source apporte un inventaire et une lecture. Les deux sont bornés — une
#  conversation ne doit pas avaler un disque.
# ══════════════════════════════════════════════════════════════════════════════
_LAB_SRC_MAX = 4000        # par source
_LAB_CTX_MAX = 14000       # tout le contexte réuni


def _lab_coupe(t, n=_LAB_SRC_MAX):
    t = str(t or "")
    return t if len(t) <= n else t[:n] + "\n…(tronqué)"


