    # distingue une note commune d'une note à soi au moment de la brancher.
    return [{"ref": n.get("name", ""),
             "titre": ("🌐 " if n.get("public") else "") + n.get("name", ""),
             "public": bool(n.get("public")),
             "detail": "%s · %s" % ("commune" if n.get("public") else "à moi",
                                   n.get("mtime", ""))}
            for n in (itare_note_list() or [])][:80]


