def _lab_src_projet_lire(ref):
    c = pj_contexte(ref)
    if not c.get("ok"):
        return None
    p = c["projet"]
    L = ["Projet : %s (%s)" % (p["name"], p.get("status", ""))]
    if p.get("objectif"):
        L.append("Objectif : " + p["objectif"])
    if c["perimetre_out"]:
        L.append("Hors périmètre : " + " ; ".join(c["perimetre_out"]))
    if c["reussite"]:
        L.append("Réussite si : " + " ; ".join(c["reussite"]))
    ouv = [t for t in c["taches"] if t.get("status") != "fait"]
    if ouv:
        L.append("Tâches ouvertes :\n" + "\n".join(
            "- [%s] %s" % (t.get("status", ""), t.get("text", "")) for t in ouv[:30]))
    dec = [d for d in c["decisions"] if d.get("etat") != "ouverte"]
    if dec:
        L.append("Décisions prises :\n" + "\n".join(
            "- %s → %s" % (d["question"], d.get("reponse", "")) for d in dec[:15]))
    ouvd = [d for d in c["decisions"] if d.get("etat") == "ouverte"]
    if ouvd:
        L.append("Décisions NON tranchées :\n" + "\n".join(
            "- " + d["question"] for d in ouvd[:10]))
    if c["journal"]:
        L.append("Journal récent :\n" + "\n".join(
            "- %s %s : %s" % (str(j.get("ts", ""))[:10], j.get("titre", ""),
                              (j.get("texte", "") or "")[:160]) for j in c["journal"][:8]))
    return {"titre": p["name"], "texte": "\n\n".join(L)}


# Les sources de la GED qui ne sont pas des DOSSIERS de documents : deux vues
# sur les mêmes fichiers, et ce que la personne a jeté.
_LAB_GED_HORS = ("recents", "doublons", "corbeille")
_LAB_GED_PROF = 3          # jusqu'où on descend dans les sous-dossiers
_LAB_GED_DOSS = 12         # dossiers ouverts par source, au plus
_LAB_GED_MAX = 120         # pièces retenues, toutes sources confondues
# Un ESPACE DISTANT se liste par le réseau (rclone) : une descente récursive y
# prend des dizaines de secondes par dossier, et l'inventaire se fait à CHAQUE
# message. Il reste attachable à la main depuis le sélecteur de sources de la
# page — c'est l'inventaire automatique qui n'y va pas.
_LAB_GED_LENT = ("remote:",)
# Le temps TOTAL accordé à l'inventaire. Au-delà, on rend ce qu'on a : un
# catalogue partiel vaut mieux qu'une réponse qui ne vient jamais.
_LAB_GED_SEC = 6.0


def _lab_src_doc_lister():
    """Les pièces de la GED.

    On NE rattrape pas l'échec de l'inventaire : le registre le rapporte, et
    une nature muette vaut mieux qu'une nature qui prétend n'avoir rien. Une
    racine isolée qui tombe est en revanche tolérée — sauf si elles tombent
    toutes, auquel cas il n'y a plus rien à taire."""
    out, echecs, vues = [], [], 0
    # L'inventaire tourne a CHAQUE message : sans horloge, une source lente le
    # fait durer indefiniment, et sur Telegram la reponse ne vient jamais.
    _t0, manque_temps = time.monotonic(), False
    # `ged_sources` rend un DICTIONNAIRE — {"ok":…, "groupes":[{"g":…,"l":[…]}]} —
    # et non une liste. Le trancher levait « KeyError: slice(None, 6, None) », donc
    # la GED entière était déclarée illisible : ni dans le sélecteur de sources de
    # la page, ni dans ce qu'Itare connaît. La clé d'une source est `id`.
    srcs = []
    for _g in ((ged_sources() or {}).get("groupes") or []):
        for _s in (_g.get("l") or []):
            if isinstance(_s, dict):
                srcs.append(_s)
    for sr in srcs[:8]:
        cle = sr.get("id") or sr.get("cle") or sr.get("source") or ""
        # « Récents » et « Doublons » sont des VUES sur les mêmes fichiers : les
        # parcourir les ferait apparaître deux fois. La corbeille contient ce
        # que la personne a jeté — le proposer comme document serait un
        # contresens.
        if not cle or cle in _LAB_GED_HORS:
            continue
        if any(cle.startswith(x) for x in _LAB_GED_LENT):
            continue
        if time.monotonic() - _t0 > _LAB_GED_SEC:
            manque_temps = True
            break
        vues += 1
        nsrc = sr.get("nm") or sr.get("nom") or cle
        # ON DESCEND DANS LES DOSSIERS. Seule la racine était listée, et ses
        # DOSSIERS y figuraient comme s'ils étaient des pièces : les ouvrir ne
        # rendait rien — un dossier n'a pas de texte — et tout ce qu'ils
        # contiennent restait invisible. C'est une exploration en largeur,
        # bornée en profondeur ET en nombre de dossiers ouverts : un arbre
        # profond ferait autrement des centaines d'appels par message.
        pile, ouverts = [("", 0)], 0
        while (pile and len(out) < _LAB_GED_MAX and ouverts < _LAB_GED_DOSS
               and time.monotonic() - _t0 <= _LAB_GED_SEC):
            ch, prof = pile.pop(0)
            ouverts += 1
            try:
                d = ged_lister(cle, ch)
            except Exception as e:
                # Seule la RACINE compte comme une source en panne : un
                # sous-dossier illisible n'invalide pas les autres.
                if not ch:
                    echecs.append("%s : %s" % (cle, str(e)[:70]))
                continue
            for f in (d.get("fichiers") or d.get("items") or []):
                nom = f.get("nom") or f.get("name") or ""
                if not nom:
                    continue
                chemin = (f.get("chemin") or f.get("path")
                          or ((ch + "/") if ch else "") + nom)
                if f.get("dossier"):
                    if prof < _LAB_GED_PROF:
                        pile.append((chemin, prof + 1))
                    continue        # un DOSSIER n'est pas une pièce
                if len(out) >= _LAB_GED_MAX:
                    break
                out.append({"ref": "%s|%s" % (cle, chemin),
                            "titre": nom,
                            # Le nom lisible d'une source est `nm` ; `nom`
                            # n'existe pas, et le détail affichait la clé
                            # technique. Le dossier s'y ajoute : deux fichiers
                            # de même nom dans deux dossiers seraient sinon
                            # impossibles à distinguer.
                            "detail": nsrc + ((" · " + ch) if ch else "")})
    if manque_temps and not out:
        raise RuntimeError("inventaire trop long — aucune source n'a pu être lue")
    if vues and len(echecs) == vues:
        raise RuntimeError("aucune racine lisible — " + " ; ".join(echecs))
    return out[:_LAB_GED_MAX]


def _lab_src_doc_lire(ref):
    # Laisser lever : un document illisible doit ressortir dans « manques », pas
    # entrer dans le contexte sous forme de parenthèse.
    src, _, chemin = str(ref).partition("|")
    r = ged_texte(source=src, chemin=chemin)
    if not r.get("ok"):
        return None
    return {"titre": chemin.split("/")[-1], "texte": r.get("texte") or r.get("text") or ""}


