def itare_reminders_due_summary() -> str:
    """Rappels échus (due_at <= maintenant) + à venir sous 24 h, pour la continuité Chatlab."""
    import datetime as _dt
    now = _dt.datetime.now()
    soon = now + _dt.timedelta(hours=24)
    echus, avenir = [], []
    for r in itare_reminder_list(include_done=False):
        da = r.get("due_at")
        if not da:
            continue
        try:
            d = _dt.datetime.strptime(da, "%Y-%m-%d %H:%M")
        except Exception:
            continue
        if d <= now:
            echus.append(r["text"])
        elif d <= soon:
            avenir.append("%s (%s)" % (r["text"], da[11:]))
    out = []
    if echus:
        out.append("ÉCHUS : " + " ; ".join(echus[:6]))
    if avenir:
        out.append("aujourd'hui : " + " ; ".join(avenir[:6]))
    return "\n".join(out)


# ── VEILLE PROACTIVE D'ITARE (Phase 4 : boucle orientée TOI) ─────────────────────
# Périodiquement (via la boucle autonome, opt-in), Itare regarde tes projets actifs +
# tes rappels, fait éventuellement une veille web, et te rédige un petit point. Rangé
# dans un fil dédié (itare_proactive_feed), lu par Proactivité → Cette nuit et
# repris dans le centre de notifications sous la source « veille ».
_ITARE_PROAC_MIGRATED = [False]

def _itare_proactive_migrate():
    if _ITARE_PROAC_MIGRATED[0]:
        return
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        conn.execute("CREATE TABLE IF NOT EXISTS itare_proactive_feed ("
                     "id INTEGER PRIMARY KEY AUTOINCREMENT, ts TEXT DEFAULT (datetime('now')), "
                     "title TEXT, body TEXT, seen INTEGER DEFAULT 0)")
        conn.commit(); conn.close()
        _ITARE_PROAC_MIGRATED[0] = True
    except Exception:
        pass

def _itare_proactive_add(title, body, source: str = "", niveau: str = "",
                         sujet: str = "", nature: str = "", cle: str = "", dest=None,
                         sonde: str = "", provenance: str = "interne"):
    """Le relais de la veille : le flux (`itare_proactive_feed`, lu par le Journal, la courbe « Veille
    publiée » et le rêve croisé) reçoit TOUT ; la cloche ne reçoit que ce qui a une SOURCE déclarée et
    n'est pas un rapport. Trente-cinq appelants n'en déclaraient aucune : la source se devinait au titre
    (B29, B32). Ils la déclarent tous désormais, et un appel qui l'oublie est refusé, en le disant."""
    _itare_proactive_migrate()
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        conn.execute("INSERT INTO itare_proactive_feed (title, body) VALUES (?,?)", (title, body))
        conn.execute("DELETE FROM itare_proactive_feed WHERE id NOT IN "
                     "(SELECT id FROM itare_proactive_feed ORDER BY id DESC LIMIT 50)")
        conn.commit(); conn.close()
    except Exception:
        pass
    if nature == "rapport" or (not nature and source == "veille"):
        return
    try:
        notif(title, body, source=source, niveau=niveau, sujet=sujet, nature=nature, cle=cle, dest=dest,
              sonde=sonde, provenance=provenance)
    except Exception as e:
        logging.info("[NOTIF] relais de la veille : %s", e)

def itare_proactive_list(limit=30) -> list:
    _itare_proactive_migrate()
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10); conn.row_factory = sqlite3.Row
        rows = conn.execute("SELECT id, ts, title, body, seen FROM itare_proactive_feed "
                            "ORDER BY id DESC LIMIT ?", (int(limit),)).fetchall()
        conn.close()
        return [dict(r) for r in rows]
    except Exception:
        return []

