def mail_link_project(project_id, thread_key: str, label: str = "") -> dict:
    """Rattache un FIL à un projet — pas un message. Rattacher message par
    message obligerait à refaire le geste à chaque réponse."""
    if not (thread_key or "").strip():
        return {"ok": False, "reason": "fil non identifié"}
    return itare_project_link(project_id, "mail", thread_key.strip(), (label or "")[:200])


def mail_unlink_project(project_id, thread_key: str) -> dict:
    return itare_project_unlink(project_id, "mail", (thread_key or "").strip())


def mail_project_threads(project_id) -> dict:
    """Fils rattachés à un projet, avec leur dernier message."""
    _mail_cache_migrate()
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10); conn.row_factory = sqlite3.Row
        refs = [r["ref"] for r in conn.execute(
            "SELECT ref FROM itare_project_links WHERE project_id=? AND kind='mail'",
            (int(project_id),))]
        out = []
        for ref in refs:
            r = conn.execute(
                "SELECT folder, uid, from_name, from_addr, subject, date_raw, date_iso, seen "
                "FROM mail_cache WHERE account=? AND thread_key=? ORDER BY date_iso DESC LIMIT 1",
                (_mail_account(), ref)).fetchone()
            n = conn.execute("SELECT COUNT(*) FROM mail_cache WHERE account=? AND thread_key=?",
                             (_mail_account(), ref)).fetchone()[0]
            if r:
                out.append(dict(r, thread_key=ref, count=n))
            else:
                out.append({"thread_key": ref, "subject": "(fil non encore chargé)", "count": 0})
        conn.close()
        return {"ok": True, "threads": out}
    except Exception as e:
        return {"ok": False, "reason": str(e)}


def mail_tech_pass(limit: int = 60) -> dict:
    """Route les messages techniques vers le fil proactif.

    Ils restent dans la boîte : on ne déplace rien sans consigne. Mais ils
    cessent d'être un courrier à lire pour devenir un signal de supervision,
    au même endroit que les autres."""
    if not _mem_cfg("mail_tech_routing", True):
        return {"ok": True, "disabled": True, "routed": 0}
    _mail_links_migrate()
    lst = itare_mail_list(limit=limit)
    if not lst.get("ok"):
        return {"ok": False, "reason": lst.get("reason"), "routed": 0}
    routes = 0
    for m in lst.get("messages", []):
        motif = mail_is_technical(m)
        if not motif:
            continue
        cle = "tech:%s:%s" % (_mail_account(), m.get("uid"))
        try:
            conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
            _iso_migrer(conn)
            deja = conn.execute("SELECT 1 FROM mail_seen_tech WHERE key=?", (cle,)).fetchone()
            if not deja:
                conn.execute("INSERT OR IGNORE INTO mail_seen_tech (key, compte) VALUES (?,?)",
                             (cle, _iso_compte(None, "filtre technique")))
                conn.commit()
            conn.close()
        except Exception as e:
            logging.warning("[MAIL] mémoire des mails techniques : %s", e)
            deja = True
        if deja:
            continue
        try:
            _boite = ""
            try:
                _boite = _mail_account() or ""
            except Exception:
                _boite = ""
            _itare_proactive_add(
                "Message de supervision : %s" % (m.get("subject") or "(sans objet)")[:120],
                "De %s · %s\nDétecté comme technique (%s). Le message reste dans la boîte."
                % (m.get("from") or "?", m.get("date") or "", motif),
                source="courrier", nature="evenement", niveau="info",
                sujet="uid:%s" % m.get("uid"), cle="courrier:supervision:%s" % cle,
                provenance="externe", dest=(["compte:" + _boite] if "@" in _boite else None))
            routes += 1
        except Exception as e:
            logging.info("[MAIL] fil proactif : %s", e)
    return {"ok": True, "routed": routes, "scanned": len(lst.get("messages", []))}


# ── Carnet d'adresses ───────────────────────────────────────────────────────
# Le carnet déduit répond à « qui m'écrit », pas à « comment joindre cette
# personne ». Une vraie fiche porte un téléphone, une société, plusieurs
# adresses. Deux tables donc : l'identité (saisie, durable) d'un côté, les
# statistiques d'échange (recalculées) de l'autre — sans quoi chaque
# synchronisation écraserait ce qui a été tapé à la main.
_CONTACTS_MIGRATED = [False]


def _contacts_migrate():
    if _CONTACTS_MIGRATED[0]:
        return
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        conn.execute("CREATE TABLE IF NOT EXISTS contacts ("
                     "id INTEGER PRIMARY KEY AUTOINCREMENT, account TEXT, "
                     "display_name TEXT DEFAULT '', company TEXT DEFAULT '', "
                     "job_title TEXT DEFAULT '', phone TEXT DEFAULT '', mobile TEXT DEFAULT '', "
                     "address TEXT DEFAULT '', website TEXT DEFAULT '', notes TEXT DEFAULT '', "
                     "tags TEXT DEFAULT '', favorite INTEGER DEFAULT 0, "
                     "source TEXT DEFAULT 'manuel', "
                     "created_at TEXT DEFAULT (datetime('now')), "
                     "updated_at TEXT DEFAULT (datetime('now')))")
        conn.execute("CREATE TABLE IF NOT EXISTS contact_emails ("
                     "contact_id INTEGER, addr TEXT, is_primary INTEGER DEFAULT 0, "
                     "PRIMARY KEY (contact_id, addr))")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_contact_emails_addr ON contact_emails(addr)")
        # ── LES DOSSIERS ──────────────────────────────────────────────────
        # `parent_id` permet un niveau d'imbrication — « Clients » puis
        # « Chantiers en cours ». Le compte est porté ici aussi : deux
        # personnes n'ont pas le même classement.
        conn.execute("CREATE TABLE IF NOT EXISTS contact_dossiers ("
                     "id INTEGER PRIMARY KEY AUTOINCREMENT, compte TEXT DEFAULT '', "
                     "nom TEXT DEFAULT '', parent_id INTEGER DEFAULT 0, "
                     "cree_le TEXT DEFAULT (datetime('now')))")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_contact_dossiers_compte "
                     "ON contact_dossiers(compte)")
        # ── LES PAIRES ÉCARTÉES ───────────────────────────────────────────
        # « Ce n'est pas la même personne » est un geste à part entière, et il
        # doit se retenir : sans cette table, les mêmes faux doublons
        # remontent chaque semaine et on cesse de regarder la pastille.
        # La clé est la paire TRIÉE : écarter (3,7) écarte aussi (7,3).
        conn.execute("CREATE TABLE IF NOT EXISTS contact_pas_doublons ("
                     "compte TEXT DEFAULT '', a INTEGER, b INTEGER, "
                     "ecarte_le TEXT DEFAULT (datetime('now')), "
                     "PRIMARY KEY (compte, a, b))")
        # `account` est la BOÎTE d'où le correspondant a été déduit, pas le
        # propriétaire de la fiche. Les confondre partitionnait le carnet sur
        # `_mail_account()`, qui rend « ? » pour tout compte sans IMAP : ces
        # comptes-là partageaient alors un seul et même carnet.
        for _col in ("compte TEXT DEFAULT ''", "photo TEXT DEFAULT ''",
                     "vault_ref TEXT DEFAULT ''",
                     # ── LE DOSSIER ────────────────────────────────────────
                     # Appartenance UNIQUE : c'est ce qui distingue un dossier
                     # d'une étiquette. 0 = « Sans dossier », jamais NULL —
                     # une comparaison avec NULL est fausse même contre NULL,
                     # et le filtre laisserait passer les orphelins.
                     "dossier_id INTEGER DEFAULT 0",
                     # ── L'ANNIVERSAIRE ────────────────────────────────────
                     # Texte, pas date : « 12/03 » sans année est courant, et
                     # une date SQL exigerait d'en inventer une.
                     "anniversaire TEXT DEFAULT ''",
                     # ── ARCHIVÉ ───────────────────────────────────────────
                     # Rangé hors des listes, retrouvable pour toujours. Ce
                     # n'est PAS la corbeille : un fournisseur qu'on ne voit
                     # plus, mais dont la facture d'il y a deux ans compte.
                     "archive INTEGER DEFAULT 0",
                     # ── LA CORBEILLE ──────────────────────────────────────
                     # `contact_delete` et `contact_merge` faisaient un DELETE
                     # sec : rien n'était récupérable, y compris la fiche
                     # absorbée par une fusion. C'est ce qui rendait la
                     # détection de doublons intimidante.
                     "supprime_at TEXT DEFAULT ''",
                     # Ce qui a absorbé cette fiche, pour savoir quoi défaire.
                     "fusion_vers INTEGER DEFAULT 0",
                     # La provenance de la PHOTO, pour qu'un favicon ne prenne
                     # jamais la place d'un vrai portrait.
                     "photo_src TEXT DEFAULT ''"):
            try:
                conn.execute("ALTER TABLE contacts ADD COLUMN " + _col)
            except Exception:
                pass
        # LES INDEX APRÈS, ET CHACUN POUR SOI. Un index posé sur une colonne
        # que l'ALTER n'a pas réussi à créer lève — et cette exception-là
        # emportait TOUTE la migration, y compris les deux tables qui la
        # suivaient. Résultat : ni dossiers ni corbeille, et un écran qui
        # affiche des zéros sans rien dire.
        for _idx in ("CREATE INDEX IF NOT EXISTS idx_contacts_compte ON contacts(compte)",
                     "CREATE INDEX IF NOT EXISTS idx_contacts_dossier ON contacts(dossier_id)"):
            try:
                conn.execute(_idx)
            except Exception as _e:
                logging.info("[CONTACTS] index : %s", _e)
        # LOT 6 : les compteurs du courrier vivent sur l'adresse — `mail_contacts` est fondue ici.
        for _col in ("sent INTEGER DEFAULT 0", "received INTEGER DEFAULT 0", "last_seen TEXT DEFAULT ''"):
            try:
                conn.execute("ALTER TABLE contact_emails ADD COLUMN " + _col)
            except Exception:
                pass
        _portraits_migrer(conn)           # LOT 6 : la table des portraits existe dès le carnet
        conn.commit(); conn.close()
        _CONTACTS_MIGRATED[0] = True
    except Exception as e:
        logging.warning("[CONTACTS] migration : %s", e)


# ── Confidentialité ─────────────────────────────────────────────────────────
# Une fiche contact décrit un TIERS. Ses coordonnées directes ne doivent pas
# sortir de la machine : c'est la SORTIE qui pose problème, pas la lecture par
# un modèle. Un modèle exécuté localement ne transmet rien à personne — la
# donnée reste sur le serveur, exactement comme dans la base. L'expurgation ne
# s'applique donc qu'aux fournisseurs distants, où le contexte part chez un
# tiers. Vers l'extérieur, l'agent désigne les gens par leur identifiant et
# c'est le serveur qui résout l'adresse au moment d'envoyer.
_CONTACT_PRIVATE = ("emails", "addr", "phone", "mobile", "address")
_LOCAL_PROVIDERS = ("ollama", "local", "llamacpp", "lmstudio", "vllm", "textgen")
_LOCAL_HOSTS = ("localhost", "127.0.0.1", "0.0.0.0", "::1", "host.docker.internal")


def _is_local_endpoint(provider: str, base_url: str) -> bool:
    """Vrai si l'inférence a lieu sur cette machine (ou sur le réseau local).

    On regarde l'URL autant que le nom du fournisseur : « ollama » peut pointer
    vers une machine distante, et un fournisseur inconnu peut très bien tourner
    en local. C'est la destination réelle du contexte qui décide."""
    p = (provider or "").strip().lower()
    u = (base_url or "").strip().lower()
    hote = ""
    try:
        hote = urllib.parse.urlparse(u if "://" in u else "http://" + u).hostname or ""
    except Exception:
        hote = ""
    if hote:
        if hote in _LOCAL_HOSTS or hote.endswith(".local"):
            return True
        if re.match(r"^(10\.|127\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.)", hote):
            return True
        return False                     # une URL distante prime sur le nom
    return p in _LOCAL_PROVIDERS


def contact_agent_is_local(agent: str = "itare") -> bool:
    try:
        if (agent or "").lower() == "cassandra":
            prov, _m, url = _load_runtime_cfg()
        else:
            _k, _m, url = _itare_agent_creds()
            prov = (get_cassandra_config().get("itare_provider", "") or "").strip()
        return _is_local_endpoint(prov, url)
    except Exception as e:
        # Dans le doute, on protège : mieux vaut une fiche expurgée à tort
        # qu'un numéro de téléphone envoyé chez un tiers.
        logging.info("[CONTACTS] localité du modèle indéterminée : %s", e)
        return False


def contact_notes_go_remote() -> bool:
    """Les notes accompagnent-elles la fiche vers un modèle distant ?

    Réglage volontaire, pas un oubli : les coordonnées sont des données de
    contact, les notes sont du CONTEXTE (« rappeler avant 10 h », « passer par
    son associé »). C'est ce contexte qui rend une réponse utile, et c'est aussi
    ce qui peut être sensible. Le choix appartient donc à l'utilisateur."""
    try:
        return bool(_mem_cfg("contact_notes_to_remote", True))
    except Exception:
        return True


def contact_public(c: dict, agent: str = "itare", force_redact=None) -> dict:
    """Vue destinée à un modèle. Complète si l'inférence est locale, expurgée
    sinon — avec la présence des coordonnées toujours signalée, pour qu'un agent
    puisse dire « je peux lui écrire » sans voir l'adresse."""
    if not isinstance(c, dict):
        return {}
    expurger = (not contact_agent_is_local(agent)) if force_redact is None else bool(force_redact)
    prives = list(_CONTACT_PRIVATE)
    if expurger and not contact_notes_go_remote():
        prives.append("notes")
    out = {k: v for k, v in c.items() if not (expurger and k in prives)}
    out["has_email"] = bool(c.get("emails"))
    out["has_phone"] = bool(c.get("phone") or c.get("mobile"))
    out["has_address"] = bool(c.get("address"))
    out["has_notes"] = bool(c.get("notes"))
    out["redacted"] = expurger
    out["notes_sent"] = bool(expurger and contact_notes_go_remote()) or not expurger
    return out


def contacts_public(liste, agent: str = "itare") -> list:
    local = contact_agent_is_local(agent)
    return [contact_public(c, agent, force_redact=not local) for c in (liste or [])]


def contact_privacy_state(agent: str = "itare") -> dict:
    """Ce qui part réellement vers le modèle, en clair, pour l'afficher."""
    local = contact_agent_is_local(agent)
    notes = local or contact_notes_go_remote()
    return {"ok": True, "local": local, "notes_to_remote": contact_notes_go_remote(),
            "coordinates_sent": local, "notes_sent": notes,
            "summary": ("Modèle local : tout reste sur ce serveur." if local else
                        ("Modèle distant : coordonnées jamais transmises, "
                         + ("notes transmises." if notes else "notes non transmises.")))}


def contact_primary_addr(cid) -> str:
    """Adresse principale d'une fiche. Réservé aux chemins SERVEUR (envoi,
    ouverture d'un brouillon) : ne jamais faire remonter ce retour vers un modèle."""
    _contacts_migrate()
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        r = conn.execute("SELECT addr FROM contact_emails WHERE contact_id=? "
                         "ORDER BY is_primary DESC, addr LIMIT 1", (int(cid),)).fetchone()
        conn.close()
        return r[0] if r else ""
    except Exception as e:
        logging.info("[CONTACTS] adresse principale : %s", e)
        return ""


def _contact_addr_owner(conn, addr: str):
    """Contact déjà propriétaire de cette adresse, ou None."""
    r = conn.execute("SELECT contact_id FROM contact_emails WHERE addr=?",
                     ((addr or "").strip().lower(),)).fetchone()
    return r[0] if r else None


# ── Liens d'un contact ──────────────────────────────────────────────────────
# Un lien sans rôle donne un nom ; un lien avec rôle dit qui appeler. C'est
# toute la différence entre « Marie est liée à proche.fr » et « Marie est le
# contact technique de proche.fr », la seule information utile quand un
# certificat expire dans neuf jours.
# `reminder` était absent : un contact pouvait être lié à un événement d'agenda
# mais pas à un rappel. Le stockage, les routes et la lecture inverse
# (`contacts_of("reminder", id)`) sont génériques et déjà écrits — il ne
# manquait que la permission. `document` n'y est PAS, et c'est voulu : ce
# lien-là vit dans `ged_liens`, du côté du document, et en tenir une seconde
# copie ici les ferait diverger au premier détachement fait d'un seul côté.
_CONTACT_LINK_KINDS = ("project", "domain", "server", "note", "event", "task",
                       "url", "reminder")
# L'ordre EST une priorité d'appel, pas un classement alphabétique : quand un
# certificat expire à minuit, on joint le contact technique, puis le
# propriétaire — la facturation ne sert à rien à cet instant.
_CONTACT_ROLES = ("technique", "propriétaire", "hébergeur", "registrar", "client",
                  "prestataire", "facturation", "autre")
_CONTACT_LINKS_MIGRATED = [False]


def _contact_links_migrate():
    if _CONTACT_LINKS_MIGRATED[0]:
        return
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        conn.execute("CREATE TABLE IF NOT EXISTS contact_links ("
                     "contact_id INTEGER, kind TEXT, ref TEXT, role TEXT DEFAULT 'autre', "
                     "label TEXT DEFAULT '', created_at TEXT DEFAULT (datetime('now')), "
                     "PRIMARY KEY (contact_id, kind, ref))")
        # `auto` distingue un lien DÉDUIT d'un lien décidé. Sans cette marque,
        # une passe automatique écraserait le rôle corrigé à la main, et rien à
        # l'écran ne dirait si « technique » a été constaté ou supposé.
        try:
            conn.execute("ALTER TABLE contact_links ADD COLUMN auto INTEGER DEFAULT 0")
        except Exception:
            pass
        conn.execute("CREATE INDEX IF NOT EXISTS idx_contact_links_ref ON contact_links(kind, ref)")
        conn.commit(); conn.close()
        _CONTACT_LINKS_MIGRATED[0] = True
    except Exception as e:
        logging.warning("[CONTACTS] migration des liens : %s", e)


def contact_link(contact_id, kind, ref, role="autre", label="", auto=False) -> dict:
    """Rattache un contact. `auto=True` marque une déduction : elle ne remplace
    jamais un lien posé à la main, et une modification humaine la reclasse
    définitivement en lien décidé."""
    _contact_links_migrate()
    kind = (kind or "").strip().lower()
    role = (role or "autre").strip().lower()
    ref = str(ref or "").strip()
    if kind not in _CONTACT_LINK_KINDS:
        return {"ok": False, "reason": "type inconnu (%s)" % ", ".join(_CONTACT_LINK_KINDS)}
    if role not in _CONTACT_ROLES:
        return {"ok": False, "reason": "rôle inconnu (%s)" % ", ".join(_CONTACT_ROLES)}
    if not ref:
        return {"ok": False, "reason": "référence requise"}
    if kind == "domain":
        ref = _norm_domain(ref)
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        exist = conn.execute("SELECT auto FROM contact_links WHERE contact_id=? AND kind=? "
                             "AND ref=?", (int(contact_id), kind, ref)).fetchone()
        if exist and auto:
            conn.close()
            # Déjà là. Si c'était un choix humain, on n'y touche surtout pas.
            return {"ok": True, "unchanged": True}
        conn.execute("INSERT OR REPLACE INTO contact_links (contact_id, kind, ref, role, label, auto) "
                     "VALUES (?,?,?,?,?,?)",
                     (int(contact_id), kind, ref, role, (label or "")[:200], 1 if auto else 0))
        conn.commit(); conn.close()
        return {"ok": True, "auto": bool(auto)}
    except Exception as e:
        return {"ok": False, "reason": str(e)}


def contact_unlink(contact_id, kind, ref) -> dict:
    _contact_links_migrate()
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        conn.execute("DELETE FROM contact_links WHERE contact_id=? AND kind=? AND ref=?",
                     (int(contact_id), (kind or "").strip().lower(), str(ref or "").strip()))
        conn.commit(); conn.close()
        return {"ok": True}
    except Exception as e:
        return {"ok": False, "reason": str(e)}


def contact_links_of(contact_id) -> list:
    """Liens d'un contact, avec le libellé lisible de la cible."""
    _contact_links_migrate()
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10); conn.row_factory = sqlite3.Row
        rows = [dict(r) for r in conn.execute(
            "SELECT kind, ref, role, label, auto FROM contact_links WHERE contact_id=? "
            "ORDER BY kind, role", (int(contact_id),))]
        for l in rows:
            # LE LIBELLÉ EST UN CONFORT, LE LIEN EST LA DONNÉE. Cette lecture
            # était sous le `except` qui enveloppe toute la fonction : une
            # table des projets absente ne faisait pas disparaître le nom du
            # projet, elle faisait disparaître TOUS les rattachements du
            # contact — et ça se lit comme « rien n'a été enregistré ».
            if l["kind"] == "project" and not l["label"]:
                try:
                    p = conn.execute("SELECT name FROM itare_projects WHERE id=?",
                                     (l["ref"],)).fetchone()
                except Exception:
                    p = None
                l["label"] = p[0] if p else l["ref"]
            elif not l["label"]:
                l["label"] = l["ref"]
        conn.close()
        return rows
    except Exception as e:
        logging.info("[CONTACTS] liens : %s", e)
        return []


def contacts_of(kind: str, ref: str) -> list:
    """Contacts rattachés à une cible (domaine, projet, serveur…), avec leur rôle."""
    _contact_links_migrate()
    _contacts_migrate()
    ref = _norm_domain(ref) if kind == "domain" else str(ref or "").strip()
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10); conn.row_factory = sqlite3.Row
        _iso_migrer(conn)
        # LE SENS INVERSE OUVRAIT LE CARNET DES AUTRES. Cette requête rend
        # `c.*` — la fiche entière : nom, adresses, téléphone, adresse postale,
        # notes. Sans condition de compte, il suffisait de demander « qui est
        # rattaché au domaine untel » pour recevoir les fiches de quelqu'un
        # d'autre, et la route est ouverte aux comptes ordinaires.
        #
        # `_iso_ou` rend une condition VIDE pour un agent : Itare et Cassandra
        # continuent de tout voir, ce qui est justement leur rôle quand il faut
        # décider qui prévenir.
        _c, _a = _iso_ou("c")
        rows = conn.execute(
            "SELECT l.role, c.* FROM contact_links l JOIN contacts c ON c.id = l.contact_id "
            "WHERE l.kind=? AND l.ref=?" + _c,
            [(kind or "").strip().lower(), ref] + list(_a)).fetchall()
        out = [_contact_row(conn, r) for r in rows]
        for o, r in zip(out, rows):
            o["role"] = r["role"]
        conn.close()
        # Ordre d'appel : le contact technique avant le facturation, toujours.
        out.sort(key=lambda c: _CONTACT_ROLES.index(c.get("role", "autre"))
                 if c.get("role") in _CONTACT_ROLES else 99)
        return out
    except Exception as e:
        logging.info("[CONTACTS] contacts de %s/%s : %s", kind, ref, e)
        return []


# Fournisseurs dont le métier détermine le rôle sans ambiguïté. C'est le seul
# cas où deviner un rôle est légitime : une adresse chez un bureau
# d'enregistrement n'est pas « peut-être » le registrar.
_PROVIDER_ROLES = {
    "ovh.net": "hébergeur", "ovh.com": "hébergeur", "ovhcloud.com": "hébergeur",
    "hetzner.com": "hébergeur", "hetzner.de": "hébergeur", "scaleway.com": "hébergeur",
    "online.net": "hébergeur", "ionos.fr": "hébergeur", "ionos.com": "hébergeur",
    "o2switch.fr": "hébergeur", "infomaniak.com": "hébergeur", "digitalocean.com": "hébergeur",
    "linode.com": "hébergeur", "vultr.com": "hébergeur", "cloudflare.com": "hébergeur",
    "gandi.net": "registrar", "namecheap.com": "registrar", "godaddy.com": "registrar",
    "name.com": "registrar", "afnic.fr": "registrar", "eurodns.com": "registrar",
}


def _addr_domain(addr: str) -> str:
    return (addr or "").split("@")[-1].strip().lower()


def _domain_role(addr: str) -> str:
    """Rôle déductible de l'adresse, ou "" si rien de sûr."""
    d = _addr_domain(addr)
    if d in _PROVIDER_ROLES:
        return _PROVIDER_ROLES[d]
    for prov, role in _PROVIDER_ROLES.items():
        if d.endswith("." + prov):
            return role
    return ""


def _domains_match(a: str, b: str) -> bool:
    """Même domaine, ou sous-domaine de l'autre. `mail.proche.fr` et `proche.fr`
    désignent la même maison ; `proche.fr` et `proche-immo.fr`, non."""
    a, b = _norm_domain(a), _norm_domain(b)
    if not a or not b:
        return False
    return a == b or a.endswith("." + b) or b.endswith("." + a)


def contact_autolink_pass(limit: int = 400) -> dict:
    """Rattache ce qui est certain, PROPOSE ce qui ne l'est pas.

    Un rattachement faux est pire qu'aucun : il fera écrire « à prévenir :
    Untel (technique) » à quelqu'un qui n'a jamais eu ce rôle, et vous ne le
    découvrirez qu'au moment où ça compte. On n'écrit donc que sur deux
    certitudes — le domaine coïncide, ou la personne participe à un fil déjà
    rattaché — et toujours avec le rôle neutre « autre », sauf quand le métier
    du fournisseur le détermine."""
    if not _mem_cfg("contact_autolink_enabled", True):
        return {"ok": True, "disabled": True, "linked": 0, "proposed": 0}
    _contact_links_migrate()
    _mail_cache_migrate()
    poses, roles, proposes = 0, 0, 0
    try:
        projets = [p for p in (pj_projets() or []) if not p.get("archived")]
        fiches = contact_list(limit=limit).get("contacts", [])
    except Exception as e:
        return {"ok": False, "reason": str(e), "linked": 0, "proposed": 0}

    deja = set()
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        deja = {(r[0], r[1], r[2]) for r in conn.execute(
            "SELECT contact_id, kind, ref FROM contact_links")}
        conn.close()
    except Exception as e:
        logging.info("[AUTOLIEN] liens existants : %s", e)

    # ── 1. Domaine identique : appariement sûr, rôle neutre ──
    for p in projets:
        dom = _norm_domain(p.get("domain") or "")
        if not dom:
            continue
        for c in fiches:
            for a in (c.get("emails") or []):
                if not _domains_match(_addr_domain(a), dom):
                    continue
                if (c["id"], "project", str(p["id"])) in deja:
                    break
                r = contact_link(c["id"], "project", str(p["id"]), "autre",
                                 label=p.get("name", ""), auto=True)
                if r.get("ok") and not r.get("unchanged"):
                    poses += 1
                    deja.add((c["id"], "project", str(p["id"])))
                break

    # ── 2. Rôle déduit du métier du fournisseur ──
    for c in fiches:
        role = ""
        for a in (c.get("emails") or []):
            role = _domain_role(a)
            if role:
                break
        if not role:
            continue
        try:
            conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
            # On ne requalifie QUE des liens déduits restés neutres.
            cur = conn.execute("UPDATE contact_links SET role=? WHERE contact_id=? "
                               "AND auto=1 AND role='autre'", (role, c["id"]))
            roles += cur.rowcount or 0
            conn.commit(); conn.close()
        except Exception as e:
            logging.info("[AUTOLIEN] rôle fournisseur : %s", e)

    # ── 3. Participants d'un fil déjà rattaché à un projet ──
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10); conn.row_factory = sqlite3.Row
        fils = conn.execute("SELECT project_id, ref FROM itare_project_links "
                            "WHERE kind='mail'").fetchall()
        for f in fils:
            adrs = {r[0] for r in conn.execute(
                "SELECT DISTINCT from_addr FROM mail_cache WHERE account=? AND thread_key=? "
                "AND from_addr<>''", (_mail_account(), f["ref"]))}
            for a in adrs:
                cid = _contact_addr_owner(conn, a)
                if not cid or (cid, "project", str(f["project_id"])) in deja:
                    continue
                r = contact_link(cid, "project", str(f["project_id"]), "autre", auto=True)
                if r.get("ok") and not r.get("unchanged"):
                    poses += 1
                    deja.add((cid, "project", str(f["project_id"])))
        conn.close()
    except Exception as e:
        logging.info("[AUTOLIEN] fils rattachés : %s", e)

    # ── 4. Cas ressemblants : proposés, jamais écrits ──
    # Le nom de la société ou du domaine évoque le projet sans coïncider. C'est
    # exactement le genre de rapprochement qu'un humain fait d'un coup d'œil et
    # qu'une machine ne doit pas trancher seule.
    for p in projets:
        nom = (p.get("name") or "").strip().lower()
        dom = _norm_domain(p.get("domain") or "")
        racine = (dom.split(".")[0] if dom else nom).strip()
        if len(racine) < 4:
            continue
        pressentis = []
        for c in fiches:
            if (c["id"], "project", str(p["id"])) in deja:
                continue
            societe = (c.get("company") or "").strip().lower()
            adrs = " ".join(c.get("emails") or [])
            if (racine in societe) or (nom and nom in societe) or \
               (racine in _addr_domain(adrs) and not _domains_match(_addr_domain(adrs), dom)):
                pressentis.append(c)
        if not pressentis:
            continue
        cle = "autolien:%s:%s" % (p["id"], ",".join(str(c["id"]) for c in sorted(
            pressentis, key=lambda x: x["id"])))
        if _cron_seen(cle):
            continue
        proposes += len(pressentis)
        try:
            _itare_proactive_add(
                "%d contact(s) semblent liés au projet « %s »" % (len(pressentis), p.get("name")),
                "Rapprochement probable, non appliqué :\n%s\n\n"
                "Ouvre la fiche du contact pour confirmer le rattachement et son rôle."
                % "\n".join("· %s%s" % (c.get("display_name") or "?",
                                        (" — %s" % c["company"]) if c.get("company") else "")
                            for c in pressentis[:8]),
                source="projet", nature="decision", sujet="projet:%s" % p.get("id"),
                cle="projet:contacts:%s" % p.get("id"))
        except Exception as e:
            logging.info("[AUTOLIEN] proposition : %s", e)

    return {"ok": True, "linked": poses, "roles": roles, "proposed": proposes}


# ══════════════════════════════════════════════════════════════════════════════
#  LES DOSSIERS DU CARNET
#
#  Appartenance UNIQUE : une fiche est dans un dossier, ou dans aucun. C'est ce
#  qui distingue un dossier d'une étiquette, et c'est aussi son coût — pour un
#  client qui est aussi un ami, il faut trancher. En échange, on sait toujours
#  où quelqu'un se trouve.
#
#  Deux sorties, pas une : ARCHIVÉ range hors des listes en gardant la fiche
#  pour toujours ; la CORBEILLE la supprime, récupérable trente jours.
#  Confondre les deux, c'est soit détruire ce qu'on voulait ranger, soit garder
#  pour toujours ce qu'on voulait jeter.
# ══════════════════════════════════════════════════════════════════════════════

# Au-delà, une fiche de la corbeille est vraiment effacée. Trente jours, c'est
# le délai d'une erreur qu'on remarque : au retour de vacances, la fiche est
# encore là.
_CT_CORBEILLE_JOURS = 30
_CT_DOSSIER_MAX = 60          # profondeur d'un nom, pas de l'arbre


def contact_dossiers() -> dict:
    """Les dossiers du compte, avec le nombre de fiches VIVANTES dans chacun.

    Les comptes ne portent ni les archivées ni celles de la corbeille : un
    dossier annoncé « 12 » qui n'en montre que 9 est un dossier auquel on
    cesse de croire.
    """
    _contacts_migrate()
    conn = None
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        conn.row_factory = sqlite3.Row
        _iso_migrer(conn)
        _c, _a = _iso_ou()
        rows = conn.execute(
            "SELECT id, nom, parent_id FROM contact_dossiers WHERE 1=1" + _c +
            " ORDER BY parent_id, lower(nom)", list(_a)).fetchall()
        vif = " AND COALESCE(supprime_at,'')='' AND COALESCE(archive,0)=0"
        n = {}
        for x in conn.execute(
                "SELECT COALESCE(dossier_id,0) d, COUNT(*) n FROM contacts "
                "WHERE 1=1" + _c + vif + " GROUP BY 1", list(_a)):
            n[int(x["d"] or 0)] = x["n"]
        tout = conn.execute("SELECT COUNT(*) FROM contacts WHERE 1=1" + _c + vif,
                            list(_a)).fetchone()[0]
        arch = conn.execute("SELECT COUNT(*) FROM contacts WHERE 1=1" + _c +
                            " AND COALESCE(supprime_at,'')='' AND COALESCE(archive,0)=1",
                            list(_a)).fetchone()[0]
        pou = conn.execute("SELECT COUNT(*) FROM contacts WHERE 1=1" + _c +
                           " AND COALESCE(supprime_at,'')<>''", list(_a)).fetchone()[0]
    except Exception as e:
        return {"ok": False, "reason": str(e)[:160]}
    finally:
        if conn:
            try:
                conn.close()
            except Exception:
                pass
    return {"ok": True,
            "dossiers": [{"id": x["id"], "nom": x["nom"],
                          "parent_id": x["parent_id"] or 0,
                          "n": n.get(int(x["id"]), 0)} for x in rows],
            "tout": tout, "sans": n.get(0, 0), "archives": arch, "corbeille": pou}


def contact_dossier_save(nom: str, did=None, parent_id=0) -> dict:
    """Crée ou renomme un dossier. Un seul niveau d'imbrication."""
    _contacts_migrate()
    nom = str(nom or "").strip()[:_CT_DOSSIER_MAX]
    if not nom:
        return {"ok": False, "reason": "un dossier a besoin d'un nom"}
    compte = get_current_user() or ""
    conn = None
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        _iso_migrer(conn)
        _c, _a = _iso_ou()
        # UN SEUL NIVEAU. Un dossier rangé sous un sous-dossier donnerait un
        # arbre qu'aucun écran de cette largeur ne sait montrer.
        pid = int(parent_id or 0)
        if pid:
            p = conn.execute("SELECT parent_id FROM contact_dossiers WHERE id=?" + _c,
                             [pid] + list(_a)).fetchone()
            if not p:
                return {"ok": False, "reason": "dossier parent introuvable"}
            if p[0]:
                return {"ok": False, "reason": "un sous-dossier ne peut pas en contenir"}
        if did:
            if not conn.execute("SELECT id FROM contact_dossiers WHERE id=?" + _c,
                                [int(did)] + list(_a)).fetchone():
                return {"ok": False, "reason": "dossier introuvable"}
            conn.execute("UPDATE contact_dossiers SET nom=?, parent_id=? WHERE id=?",
                         (nom, pid, int(did)))
            _id = int(did)
        else:
            cur = conn.execute("INSERT INTO contact_dossiers (compte, nom, parent_id) "
                               "VALUES (?,?,?)", (compte, nom, pid))
            _id = cur.lastrowid
        conn.commit()
    except Exception as e:
        return {"ok": False, "reason": str(e)[:160]}
    finally:
        if conn:
            try:
                conn.close()
            except Exception:
                pass
    return {"ok": True, "id": _id, "nom": nom}


def contact_dossier_delete(did) -> dict:
    """Supprime un dossier. SES FICHES NE SONT PAS SUPPRIMÉES.

    Elles retournent dans « Sans dossier », et ses sous-dossiers remontent à la
    racine. Un dossier qui emporte son contenu est un piège : on le supprime
    pour ranger, pas pour détruire.
    """
    _contacts_migrate()
    conn = None
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        _iso_migrer(conn)
        _c, _a = _iso_ou()
        if not conn.execute("SELECT id FROM contact_dossiers WHERE id=?" + _c,
                            [int(did)] + list(_a)).fetchone():
            return {"ok": False, "reason": "dossier introuvable"}
        sous = [x[0] for x in conn.execute(
            "SELECT id FROM contact_dossiers WHERE parent_id=?", (int(did),))]
        # SEULES LES FICHES DE CE DOSSIER-LÀ sont libérées. Les sous-dossiers
        # survivent — ils remontent à la racine —, donc leurs fiches restent
        # chez eux. Les libérer aussi vidait un dossier qu'on n'avait pas
        # demandé de vider, et qui s'affichait ensuite à zéro sans raison.
        n = conn.execute("UPDATE contacts SET dossier_id=0 WHERE dossier_id=?",
                         (int(did),)).rowcount
        conn.execute("UPDATE contact_dossiers SET parent_id=0 WHERE parent_id=?",
                     (int(did),))
        conn.execute("DELETE FROM contact_dossiers WHERE id=?", (int(did),))
        conn.commit()
    except Exception as e:
        return {"ok": False, "reason": str(e)[:160]}
    finally:
        if conn:
            try:
                conn.close()
            except Exception:
                pass
    return {"ok": True, "liberees": max(0, n), "sous_dossiers": len(sous)}


def _ct_ids(ids) -> list:
    """Une liste d'identifiants, nettoyée. Bornée : une action de masse sur
    mille fiches par accident vaut mieux refusée."""
    out = []
    for x in (ids if isinstance(ids, (list, tuple)) else [ids]):
        try:
            v = int(x)
        except Exception:
            continue
        if v > 0 and v not in out:
            out.append(v)
    return out[:500]


def _ct_maj_lot(ids, sets: str, args: list) -> dict:
    """Applique une mise à jour au LOT, sans jamais sortir du compte."""
    lot = _ct_ids(ids)
    if not lot:
        return {"ok": False, "reason": "aucune fiche désignée"}
    _contacts_migrate()
    conn = None
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        _iso_migrer(conn)
        _c, _a = _iso_ou()
        marks = ",".join("?" * len(lot))
        n = conn.execute("UPDATE contacts SET %s, updated_at=datetime('now') "
                         "WHERE id IN (%s)%s" % (sets, marks, _c),
                         list(args) + lot + list(_a)).rowcount
        conn.commit()
    except Exception as e:
        return {"ok": False, "reason": str(e)[:160]}
    finally:
        if conn:
            try:
                conn.close()
            except Exception:
                pass
    return {"ok": True, "touchees": max(0, n), "demandees": len(lot)}


def contact_deplacer(ids, dossier_id) -> dict:
    """Déplace des fiches vers un dossier. 0 = « Sans dossier »."""
    did = int(dossier_id or 0)
    if did:
        _contacts_migrate()
        conn = None
        try:
            conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
            _iso_migrer(conn)
            _c, _a = _iso_ou()
            if not conn.execute("SELECT id FROM contact_dossiers WHERE id=?" + _c,
                                [did] + list(_a)).fetchone():
                return {"ok": False, "reason": "dossier introuvable"}
        except Exception as e:
            return {"ok": False, "reason": str(e)[:160]}
        finally:
            if conn:
                try:
                    conn.close()
                except Exception:
                    pass
    return _ct_maj_lot(ids, "dossier_id=?", [did])


def contact_archiver(ids, archive=True) -> dict:
    """Range ou sort de l'archive. La fiche reste entière, avec ses liens."""
    return _ct_maj_lot(ids, "archive=?", [1 if archive else 0])


def contact_corbeille(ids, fusion_vers=0) -> dict:
    """Met des fiches à la corbeille. RIEN N'EST EFFACÉ : ni les adresses, ni
    les liens. C'est ce qui permet de restaurer une fiche là où elle était, et
    non dans un carnet vide."""
    return _ct_maj_lot(ids, "supprime_at=datetime('now'), fusion_vers=?",
                       [int(fusion_vers or 0)])


def contact_restaurer(ids) -> dict:
    """Sort de la corbeille. Le dossier d'origine est retrouvé tel quel."""
    return _ct_maj_lot(ids, "supprime_at='', fusion_vers=0", [])


def contact_corbeille_lister() -> dict:
    """Ce qui attend dans la corbeille, et depuis combien de jours."""
    _contacts_migrate()
    conn = None
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        conn.row_factory = sqlite3.Row
        _iso_migrer(conn)
        _c, _a = _iso_ou()
        rows = conn.execute(
            "SELECT id, display_name, company, supprime_at, fusion_vers, dossier_id "
            "FROM contacts WHERE COALESCE(supprime_at,'')<>''" + _c +
            " ORDER BY supprime_at DESC", list(_a)).fetchall()
    except Exception as e:
        return {"ok": False, "reason": str(e)[:160]}
    finally:
        if conn:
            try:
                conn.close()
            except Exception:
                pass
    out = []
    for x in rows:
        j = _mail_jours_depuis(x["supprime_at"])
        out.append({"id": x["id"], "display_name": x["display_name"],
                    "company": x["company"], "supprime_at": x["supprime_at"],
                    "jours": j, "restants": max(0, _CT_CORBEILLE_JOURS - max(0, j)),
                    # Une fiche absorbée par une fusion se restaure autrement :
                    # la remettre seule recréerait le doublon qu'on venait
                    # d'ôter. On le dit à l'écran.
                    "fusion_vers": x["fusion_vers"] or 0})
    return {"ok": True, "fiches": out, "jours": _CT_CORBEILLE_JOURS}


def contact_corbeille_purger(confirm: bool = False) -> dict:
    """Efface POUR DE BON ce qui a dépassé les trente jours.

    Sans `confirm`, on rend seulement le compte : une purge est le seul geste
    de ce fichier qui détruit vraiment quelque chose.
    """
    _contacts_migrate()
    _contact_links_migrate()
    limite = (datetime.now() - timedelta(days=_CT_CORBEILLE_JOURS)).strftime(
        "%Y-%m-%d %H:%M:%S")
    conn = None
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        _iso_migrer(conn)
        _c, _a = _iso_ou()
        vises = [x[0] for x in conn.execute(
            "SELECT id FROM contacts WHERE COALESCE(supprime_at,'')<>'' "
            "AND supprime_at < ?" + _c, [limite] + list(_a))]
        if not confirm or not vises:
            return {"ok": True, "a_purger": len(vises), "purgees": 0}
        marks = ",".join("?" * len(vises))
        conn.execute("DELETE FROM contact_emails WHERE contact_id IN (%s)" % marks, vises)
        conn.execute("DELETE FROM contact_links WHERE contact_id IN (%s)" % marks, vises)
        conn.execute("DELETE FROM contacts WHERE id IN (%s)" % marks, vises)
        conn.commit()
    except Exception as e:
        return {"ok": False, "reason": str(e)[:160]}
    finally:
        if conn:
            try:
                conn.close()
            except Exception:
                pass
    logging.info("[CARNET] %d fiche(s) purgée(s) de la corbeille", len(vises))
    return {"ok": True, "a_purger": 0, "purgees": len(vises)}


def contact_for_domain(domain: str) -> dict:
    """Qui prévenir pour ce domaine. Remonte au projet portant le domaine si
    aucun contact n'est rattaché au domaine lui-même — un site est presque
    toujours décrit par un projet, et personne ne remplit deux fois la même
    information."""
    dom = _norm_domain(domain)
    gens = contacts_of("domain", dom)
    if gens:
        return {"ok": True, "domain": dom, "contacts": gens, "via": "domaine"}
    try:
        _itare_projects_migrate()
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        r = conn.execute("SELECT id FROM itare_projects WHERE lower(domain)=?", (dom,)).fetchone()
        conn.close()
    except Exception as e:
        logging.info("[CONTACTS] projet du domaine : %s", e)
        r = None
    if r:
        gens = contacts_of("project", str(r[0]))
        if gens:
            return {"ok": True, "domain": dom, "contacts": gens, "via": "projet"}
    return {"ok": True, "domain": dom, "contacts": [], "via": ""}


def _contact_alert_line(domain: str) -> str:
    """Une ligne « à prévenir » à coller dans une alerte. Vide si personne n'est
    désigné : une alerte ne doit pas inventer un responsable."""
    r = contact_for_domain(domain)
    gens = r.get("contacts") or []
    if not gens:
        return ""
    return "À prévenir : " + ", ".join(
        "%s (%s)" % (c.get("display_name") or c.get("addr") or "?", c.get("role") or "contact")
        for c in gens[:3])


# La photo est une donnée `data:` bornée. On la garde en base plutôt qu'en
# fichier : une fiche doit rester lisible après une restauration de la seule
# base, et un avatar de quelques kilo-octets ne justifie pas un second
# emplacement à sauvegarder. La borne est basse à dessein — au-delà, ce n'est
# plus un portrait, c'est une pièce jointe.
# 150 ko de fichier, gonfles d'un tiers par base64, plus l'en-tete.
_CT_PHOTO_MAX = 210_000
_CT_PHOTO_RE = r"^data:image/(png|jpeg|webp|gif);base64,[A-Za-z0-9+/=\s]+$"


def _ct_photo(v: str) -> str:
    """Rend la photo si elle est acceptable, '' sinon. On refuse au lieu de
    tronquer : une image coupée en deux s'affiche comme une bande grise."""
    s = str(v or "").strip()
    if not s:
        return ""
    if len(s) > _CT_PHOTO_MAX or not re.match(_CT_PHOTO_RE, s):
        return ""
    return s


def _ct_meme_compte(ligne: str, compte: str) -> bool:
    """La ligne appartient-elle au compte demandé ? Un compte vide (agent, passe) ne borne rien — c'est le
    comportement d'avant, que le lot 2 refusera ; la machine ('*') voit tout ; une ligne sans propriétaire
    est à tous (règle de `_iso_ou`)."""
    c = (compte or "").strip().lower()
    if not c or c == "*":
        return True
    return (ligne or "").strip().lower() in ("", c)


_CT_CHAMPS_TEXTE = (("display_name", 120), ("company", 120), ("job_title", 120), ("phone", 60),
                    ("mobile", 60), ("address", 300), ("website", 200), ("notes", 4000), ("tags", 200))


def contact_save(display_name=None, emails=None, phone=None, mobile=None, company=None,
                 job_title=None, address=None, website=None, notes=None, tags=None,
                 favorite=None, cid=None, photo=None, vault_ref=None, compte=None,
                 dossier_id=None, anniversaire=None, source=None) -> dict:
    """Crée ou met à jour une fiche — EN PATCH.

    Sur une fiche existante, `None` veut dire « ne touche pas à ce champ » ; une chaîne vide l'efface.
    Avant, chaque enregistrement réécrivait TOUTES les colonnes et remplaçait les adresses : un client qui
    n'envoyait que {id, favorite} effaçait le reste (B1, débat du 16-09) — et le favori ne persistait jamais,
    la route traduisant son absence en faux. Les adresses ne sont resynchronisées QUE si `emails` est
    fourni. Une adresse déjà rattachée à quelqu'un d'autre est refusée plutôt que volée en silence.

    Le compte est un ARGUMENT : la route le pose depuis la session, une passe le passe de sa boucle ; à
    défaut on lit encore le fil (lot 2 : refus)."""
    _contacts_migrate()
    liste = None
    if emails is not None:
        liste = []
        for a in (emails or []):
            a = str(a or "").strip().lower()
            if not a:
                continue
            if not _EMAIL_RE.match(a):
                return {"ok": False, "reason": "adresse invalide : %s" % a}
            if a not in liste:
                liste.append(a)
    nom = None if display_name is None else str(display_name or "").strip()[:120]
    # Le proprietaire est le COMPTE, pas la boite : deux personnes sans IMAP
    # auraient sinon la meme valeur, « ? », donc le meme carnet.
    compte = (compte or "").strip().lower() or _iso_moi()
    if not compte:
        logging.warning("[CONTACTS] écriture sans compte (fiche %s) : le compte doit être passé en argument",
                        cid or nom or "?")
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        for a in (liste or []):
            proprio = _contact_addr_owner(conn, a)
            if proprio and (not cid or int(proprio) != int(cid)):
                conn.close()
                return {"ok": False, "reason": "l'adresse %s appartient déjà à une autre fiche" % a}
        if cid:
            # Existence ET appartenance : verifier seulement l'existence
            # laissait ecrire dans la fiche de quelqu'un d'autre. Et LE COMPTE REÇU
            # BORNE L'UPDATE : `_iso_ou()` est vide pour un agent ou un fil sans
            # utilisateur — le compte passé en argument ne servait qu'à l'INSERT
            # (Cassandra, #1673). Une fiche d'un autre compte est « introuvable ».
            _c, _a = _iso_ou()
            ex = conn.execute("SELECT id, COALESCE(compte,'') FROM contacts WHERE id=?" + _c,
                              [int(cid)] + list(_a)).fetchone()
            if not ex or not _ct_meme_compte(ex[1], compte):
                conn.close(); return {"ok": False, "reason": "fiche introuvable"}
            if nom is not None and not nom and not liste:
                conn.close(); return {"ok": False, "reason": "un nom ou une adresse au minimum"}
            sets, args = [], []
            recus = {"display_name": nom, "company": company, "job_title": job_title, "phone": phone,
                     "mobile": mobile, "address": address, "website": website, "notes": notes,
                     "tags": tags}
            for col, lg in _CT_CHAMPS_TEXTE:
                v = recus.get(col)
                if v is not None:
                    sets.append("%s=?" % col); args.append(str(v)[:lg])
            if favorite is not None:
                sets.append("favorite=?"); args.append(1 if favorite else 0)
            # `None` NE TOUCHE PAS au champ ; une chaîne vide l'efface. Sans
            # cette distinction, tout enregistrement partiel — changer un
            # numéro de téléphone — effacerait la photo au passage.
            if photo is not None:
                sets.append("photo=?"); args.append(_ct_photo(photo))
            if vault_ref is not None:
                sets.append("vault_ref=?"); args.append(str(vault_ref or "")[:160])
            if dossier_id is not None:
                sets.append("dossier_id=?"); args.append(int(dossier_id or 0))
            if anniversaire is not None:
                sets.append("anniversaire=?"); args.append(str(anniversaire or "")[:20])
            if sets:
                conn.execute("UPDATE contacts SET %s, updated_at=datetime('now') WHERE id=?"
                             % ", ".join(sets), args + [int(cid)])
            new_id = int(cid)
            if liste is not None:
                conn.execute("DELETE FROM contact_emails WHERE contact_id=?", (new_id,))
        else:
            if not nom and not liste:
                conn.close(); return {"ok": False, "reason": "un nom ou une adresse au minimum"}
            if not nom:
                nom = liste[0].split("@")[0]
            v = lambda x, lg: str(x or "")[:lg]
            cur = conn.execute(
                "INSERT INTO contacts (compte, account, display_name, company, job_title, "
                "phone, mobile, address, website, notes, tags, favorite, source) "
                "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)",
                (compte, _mail_account(), nom, v(company, 120), v(job_title, 120),
                 v(phone, 60), v(mobile, 60), v(address, 300), v(website, 200), v(notes, 4000),
                 v(tags, 200), 1 if favorite else 0, str(source or "manuel")[:40]))
            new_id = cur.lastrowid
            if photo or vault_ref:
                conn.execute("UPDATE contacts SET photo=?, vault_ref=? WHERE id=?",
                             (_ct_photo(photo), str(vault_ref or "")[:160], new_id))
            if dossier_id or anniversaire:
                conn.execute("UPDATE contacts SET dossier_id=COALESCE(?, dossier_id), "
                             "anniversaire=COALESCE(?, anniversaire) WHERE id=?",
                             (int(dossier_id) if dossier_id else None,
                              str(anniversaire)[:20] if anniversaire else None, new_id))
        for i, a in enumerate(liste or []):
            conn.execute("INSERT OR REPLACE INTO contact_emails (contact_id, addr, is_primary) "
                         "VALUES (?,?,?)", (new_id, a, 1 if i == 0 else 0))
        conn.commit(); conn.close()
        if photo is not None:
            # LOT 6 : la fiche est la troisième source de `portraits` (vide = effacé).
            _portrait_poser(compte, "contact:%d" % new_id, _ct_photo(photo), "fiche")
        try:
            log_user_activity(compte, compte, "contact_modifier" if cid else "contact_creer",
                              "#%s %s" % (new_id, (nom or "")[:60]))
        except Exception:
            pass
        return {"ok": True, "id": new_id}
    except Exception as e:
        return {"ok": False, "reason": str(e)}


def contact_delete(cid) -> dict:
    _contacts_migrate()
    _contact_links_migrate()
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        _iso_migrer(conn)
        # L'appartenance AVANT les suppressions en cascade : les vider puis
        # buter sur la fiche laisserait un contact sans adresses ni liens.
        _c, _a = _iso_ou()
        if not conn.execute("SELECT id FROM contacts WHERE id=?" + _c,
                            [int(cid)] + list(_a)).fetchone():
            conn.close()
            return {"ok": False, "reason": "fiche introuvable"}
        # LA CORBEILLE, PAS LE NÉANT. Adresses et liens sont GARDÉS : c'est
        # ce qui permet de restaurer la fiche là où elle était, et non dans un
        # carnet vide. L'effacement réel a lieu au bout de trente jours, par
        # `contact_corbeille_purger`.
        conn.execute("UPDATE contacts SET supprime_at=datetime('now'), "
                     "updated_at=datetime('now') WHERE id=?", (int(cid),))
        conn.commit(); conn.close()
        return {"ok": True, "corbeille": True, "jours": _CT_CORBEILLE_JOURS}
    except Exception as e:
        return {"ok": False, "reason": str(e)}


def _contact_row(conn, r) -> dict:
    adrs = [x[0] for x in conn.execute(
        "SELECT addr FROM contact_emails WHERE contact_id=? ORDER BY is_primary DESC, addr",
        (r["id"],))]
    recus, vu = 0, ""
    if adrs:
        marks = ",".join("?" * len(adrs))
        s = conn.execute("SELECT COUNT(*), MAX(date_iso) FROM mail_cache "
                         "WHERE account=? AND from_addr IN (%s)" % marks,
                         [_mail_account()] + adrs).fetchone()
        recus, vu = (s[0] or 0), (s[1] or "")
    d = dict(r)
    d["emails"] = adrs
    d["addr"] = adrs[0] if adrs else ""
    d["received"] = recus
    d["last_seen"] = vu
    return d


def _contact_rows(conn, rows) -> list:
    """La LISTE en deux requêtes groupées au lieu de deux PAR fiche : les adresses de toutes les fiches, puis
    un seul passage sur `mail_cache` pour compter ce que chacune a envoyé. 500 fiches faisaient 8 s
    (« Lecture… » à chaque ouverture du Répertoire) ; `_contact_row` reste pour la fiche seule."""
    rows = list(rows)
    if not rows:
        return []
    ids = [int(r["id"]) for r in rows]
    adrs = {}
    for i in range(0, len(ids), 400):
        lot = ids[i:i + 400]
        for cid, addr in conn.execute("SELECT contact_id, addr FROM contact_emails WHERE contact_id IN (%s) "
                                      "ORDER BY is_primary DESC, addr" % ",".join("?" * len(lot)), lot):
            adrs.setdefault(int(cid), []).append(addr)
    stats = {}
    toutes = sorted({a for l in adrs.values() for a in l})
    compte = _mail_account()
    for i in range(0, len(toutes), 400):
        lot = toutes[i:i + 400]
        for addr, n, vu in conn.execute("SELECT from_addr, COUNT(*), MAX(date_iso) FROM mail_cache "
                                        "WHERE account=? AND from_addr IN (%s) GROUP BY from_addr"
                                        % ",".join("?" * len(lot)), [compte] + lot):
            stats[addr] = (n or 0, vu or "")
    out = []
    for r in rows:
        d = dict(r)
        l = adrs.get(int(r["id"]), [])
        d["emails"] = l
        d["addr"] = l[0] if l else ""
        d["received"] = sum(stats.get(a, (0, ""))[0] for a in l)
        d["last_seen"] = max([stats.get(a, (0, ""))[1] for a in l] or [""])
        out.append(d)
    return out


# Les colonnes de la LISTE. `photo` n'en fait pas partie, et c'est le point :
# `SELECT *` emportait l'image de chaque fiche à chaque affichage — deux cents
# fiches à 200 ko font quarante mégaoctets de JSON pour montrer des noms. Ça ne
# se voyait pas tant que personne n'avait de portrait ; ça se verrait le jour
# même où la récupération automatique se met à les remplir.
_CT_COLS_LISTE = ("id, display_name, company, job_title, phone, mobile, address, "
                  "website, notes, tags, favorite, source, compte, vault_ref, "
                  "dossier_id, anniversaire, archive, supprime_at, fusion_vers, "
                  "photo_src, created_at, updated_at, "
                  "(COALESCE(photo,'') <> '') AS a_photo")


def contact_list(query: str = "", limit: int = 200, favorites_only=False,
                 dossier_id=None, vue: str = "") -> dict:
    """Carnet complet : fiches saisies ET correspondants déduits, dans une seule
    liste. Deux carnets côte à côte obligeraient à chercher deux fois.

    `vue` choisit ce qu'on regarde : "" pour le carnet vivant, "archive" pour
    ce qui est rangé, "corbeille" pour ce qui attend d'être effacé. Les trois
    s'excluent — une fiche à la corbeille n'a rien à faire dans une liste.
    """
    _contacts_migrate()
    _mail_cache_migrate()
    q = (query or "").strip().lower()
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10); conn.row_factory = sqlite3.Row
        _iso_migrer(conn)
        _c, _a = _iso_ou()
        _v = str(vue or "").strip().lower()
        if _v == "corbeille":
            _etat, _ea = " AND COALESCE(supprime_at,'')<>''", []
        elif _v == "archive":
            _etat, _ea = (" AND COALESCE(supprime_at,'')='' "
                          "AND COALESCE(archive,0)=1", [])
        else:
            _etat, _ea = (" AND COALESCE(supprime_at,'')='' "
                          "AND COALESCE(archive,0)=0", [])
        # `dossier_id=0` est un filtre VALIDE — « Sans dossier ». Tester la
        # vérité de l'entier confondrait « zéro » et « pas de filtre ».
        _dos, _da = "", []
        if dossier_id is not None and str(dossier_id) != "":
            _dos, _da = " AND COALESCE(dossier_id,0)=?", [int(dossier_id)]
        rows = conn.execute("SELECT " + _CT_COLS_LISTE + " FROM contacts WHERE 1=1" +
                            _c + _etat + _dos +
                            " ORDER BY favorite DESC, lower(display_name) LIMIT ?",
                            list(_a) + _ea + _da + [int(limit)]).fetchall()
        out = _contact_rows(conn, rows)
        # LOT 6 : « a un portrait » compte aussi ceux reçus par le courrier sur une de ses adresses.
        try:
            _ph = _portraits_contacts(conn, [c["id"] for c in out])
            for c in out:
                c["a_photo"] = bool(_ph.get(int(c["id"])))
        except Exception as e:
            logging.info("[PORTRAITS] liste : %s", e)
        conn.close()
    except Exception as e:
        return {"ok": False, "reason": str(e)}
    if favorites_only:
        out = [c for c in out if c.get("favorite")]
    if q:
        out = [c for c in out if q in (c.get("display_name", "") + " " + c.get("company", "") + " "
                                       + " ".join(c.get("emails", [])) + " "
                                       + c.get("phone", "") + " " + c.get("mobile", "")
                                       + " " + c.get("tags", "")).lower()]
    out.sort(key=lambda c: (0 if c.get("favorite") else 1, -(c.get("received") or 0),
                            (c.get("display_name") or "").lower()))
    return {"ok": True, "contacts": out}


def contact_photos(ids) -> dict:
    """Les portraits demandés, en UN aller-retour. Rien d'autre.
    L'écran affiche d'abord les initiales, puis demande les images de ce qui
    est visible. LOT 6 : lus dans `portraits` — la photo de la fiche, sinon celle
    reçue par le courrier sur une de ses adresses — et bornés au compte."""
    lot = _ct_ids(ids)
    if not lot:
        return {"ok": True, "photos": {}}
    _contacts_migrate()
    conn = None
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        _iso_migrer(conn)
        _c, _a = _iso_ou()
        marks = ",".join("?" * len(lot))
        miens = [int(x[0]) for x in conn.execute("SELECT id FROM contacts WHERE id IN (%s)" % marks + _c,
                                                 lot + list(_a)).fetchall()]
        ph = _portraits_contacts(conn, miens)
    except Exception as e:
        return {"ok": False, "reason": str(e)[:160]}
    finally:
        if conn:
            try:
                conn.close()
            except Exception:
                pass
    return {"ok": True,
            "photos": {str(i): v[0] for i, v in ph.items()},
            "sources": {str(i): (v[1] or "") for i, v in ph.items()}}


def contact_get(cid) -> dict:
    _contacts_migrate()
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10); conn.row_factory = sqlite3.Row
        _iso_migrer(conn)
        # Sans cette condition, un identifiant suffisait a lire la fiche de
        # n'importe qui : nom, telephone, adresse, notes.
        _c, _a = _iso_ou()
        r = conn.execute("SELECT * FROM contacts WHERE id=?" + _c,
                         [int(cid)] + list(_a)).fetchone()
        if not r:
            conn.close(); return {"ok": False, "reason": "fiche introuvable"}
        c = _contact_row(conn, r)
        conn.close()
    except Exception as e:
        return {"ok": False, "reason": str(e)}
    c["messages"] = contact_messages(cid).get("messages", [])
    c["links"] = contact_links_of(cid)
    return {"ok": True, "contact": c}


def contact_documents(cid) -> dict:
    """Les documents qui DÉSIGNENT ce contact, lus dans `ged_liens`.

    Le lien vit du côté du DOCUMENT, et nulle part ailleurs. En tenir une
    seconde copie dans `contact_links` les ferait diverger au premier
    détachement fait d'un seul côté : le carnet montrerait un devis que la GED
    ne connaît plus, ou l'inverse.

    On LIT donc chez elle, à la demande. C'est une jointure de plus à chaque
    ouverture de fiche, et c'est le prix d'une seule vérité.
    """
    try:
        cid = int(cid)
    except Exception:
        return {"ok": False, "reason": "identifiant invalide"}
    # La fiche doit appartenir au compte : sans ce contrôle, un identifiant
    # deviné donnerait la liste des documents de quelqu'un d'autre.
    if not (contact_get(cid) or {}).get("ok"):
        return {"ok": False, "reason": "fiche introuvable"}
    conn = None
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        conn.row_factory = sqlite3.Row
        rows = conn.execute(
            "SELECT f.id, f.nom, f.source, f.chemin, f.taille, f.kind, l.label "
            "FROM ged_liens l JOIN ged_fichiers f ON f.id = l.fichier_id "
            "WHERE l.kind='contact' AND l.ref=? ORDER BY f.nom LIMIT 200",
            (str(cid),)).fetchall()
    except Exception as e:
        # LA GED PEUT NE PAS EXISTER sur une installation neuve : c'est un
        # carnet sans documents, pas une panne.
        logging.info("[CARNET] documents de %s : %s", cid, e)
        return {"ok": True, "documents": []}
    finally:
        if conn:
            try:
                conn.close()
            except Exception:
                pass
    return {"ok": True, "documents": [dict(x) for x in rows]}


def contact_messages(cid, limit: int = 40) -> dict:
    """Messages échangés avec ce contact, toutes adresses et tous dossiers déjà
    parcourus confondus."""
    _contacts_migrate()
    _mail_cache_migrate()
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10); conn.row_factory = sqlite3.Row
        adrs = [x[0] for x in conn.execute(
            "SELECT addr FROM contact_emails WHERE contact_id=?", (int(cid),))]
        if not adrs:
            conn.close(); return {"ok": True, "messages": []}
        marks = ",".join("?" * len(adrs))
        rows = conn.execute(
            "SELECT folder, uid, subject, date_raw, date_iso, seen, has_attach, thread_key, "
            "from_addr FROM mail_cache WHERE account=? AND (from_addr IN (%s) OR to_addr LIKE ?) "
            "ORDER BY date_iso DESC LIMIT ?" % marks,
            [_mail_account()] + adrs + ["%%%s%%" % adrs[0], int(limit)]).fetchall()
        conn.close()
        return {"ok": True, "messages": [dict(r) for r in rows]}
    except Exception as e:
        return {"ok": False, "reason": str(e)}


def contact_for_addr(addr: str) -> dict:
    """Fiche associée à une adresse, pour ouvrir le contact depuis un message."""
    _contacts_migrate()
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        cid = _contact_addr_owner(conn, addr)
        conn.close()
    except Exception as e:
        return {"ok": False, "reason": str(e)}
    if not cid:
        return {"ok": True, "found": False}
    r = contact_get(cid)
    return dict(r, found=r.get("ok", False))


# ── vCard ───────────────────────────────────────────────────────────────────
# Un carnet qui ne parle pas au téléphone reste un carnet de plus. Mêmes pièges
# que l'iCal déjà traité : pliage des lignes longues, échappement des virgules
# et des points-virgules, et jeu de champs volontairement restreint.
def _vc_escape(s: str) -> str:
    return (str(s or "").replace("\\", "\\\\").replace("\n", "\\n")
            .replace(",", "\\,").replace(";", "\\;"))


def _vc_unescape(s: str) -> str:
    out, i = "", 0
    s = s or ""
    while i < len(s):
        if s[i] == "\\" and i + 1 < len(s):
            c = s[i + 1]
            out += {"n": "\n", "N": "\n", ",": ",", ";": ";", "\\": "\\"}.get(c, c)
            i += 2
        else:
            out += s[i]
            i += 1
    return out


def _vc_fold(ligne: str) -> str:
    """Repli à 75 octets, la continuation commençant par une espace (RFC 6350)."""
    b = ligne.encode("utf-8")
    if len(b) <= 75:
        return ligne
    morceaux, cur = [], b""
    for ch in ligne:
        e = ch.encode("utf-8")
        if len(cur) + len(e) > (75 if not morceaux else 74):
            morceaux.append(cur.decode("utf-8"))
            cur = b""
        cur += e
    if cur:
        morceaux.append(cur.decode("utf-8"))
    return morceaux[0] + "".join("\r\n " + m for m in morceaux[1:])


def vcard_export(ids=None) -> str:
    r = contact_list(limit=2000)
    fiches = r.get("contacts", []) if r.get("ok") else []
    if ids:
        garder = {int(x) for x in ids}
        fiches = [c for c in fiches if c["id"] in garder]
    lignes = []
    for c in fiches:
        nom = c.get("display_name") or (c.get("emails") or [""])[0]
        bouts = nom.split(" ", 1)
        famille = bouts[1] if len(bouts) > 1 else ""
        lignes += ["BEGIN:VCARD", "VERSION:3.0",
                   _vc_fold("FN:" + _vc_escape(nom)),
                   _vc_fold("N:%s;%s;;;" % (_vc_escape(famille), _vc_escape(bouts[0])))]
        for a in (c.get("emails") or []):
            lignes.append(_vc_fold("EMAIL;TYPE=INTERNET:" + _vc_escape(a)))
        if c.get("phone"):
            lignes.append(_vc_fold("TEL;TYPE=WORK,VOICE:" + _vc_escape(c["phone"])))
        if c.get("mobile"):
            lignes.append(_vc_fold("TEL;TYPE=CELL:" + _vc_escape(c["mobile"])))
        if c.get("company") or c.get("job_title"):
            lignes.append(_vc_fold("ORG:" + _vc_escape(c.get("company", ""))))
            if c.get("job_title"):
                lignes.append(_vc_fold("TITLE:" + _vc_escape(c["job_title"])))
        if c.get("address"):
            lignes.append(_vc_fold("ADR;TYPE=WORK:;;%s;;;;" % _vc_escape(c["address"])))
        if c.get("website"):
            lignes.append(_vc_fold("URL:" + _vc_escape(c["website"])))
        if c.get("tags"):
            lignes.append(_vc_fold("CATEGORIES:" + _vc_escape(c["tags"])))
        if c.get("notes"):
            lignes.append(_vc_fold("NOTE:" + _vc_escape(c["notes"])))
        lignes.append("END:VCARD")
    return "\r\n".join(lignes) + "\r\n"


def vcard_parse(texte: str) -> list:
    """Analyse un fichier vCard. Tolérant : un champ inconnu est ignoré, une
    fiche illisible n'interrompt pas l'import du reste."""
    brut = (texte or "").replace("\r\n", "\n").replace("\r", "\n")
    # Dépliage : une ligne commençant par une espace prolonge la précédente.
    lignes = []
    for l in brut.split("\n"):
        if l[:1] in (" ", "\t") and lignes:
            lignes[-1] += l[1:]
        else:
            lignes.append(l)
    fiches, cur = [], None
    for l in lignes:
        h = l.strip()
        if h.upper() == "BEGIN:VCARD":
            cur = {"emails": [], "tel": [], "cell": []}
            continue
        if h.upper() == "END:VCARD":
            if cur:
                fiches.append(cur)
            cur = None
            continue
        if cur is None or ":" not in h:
            continue
        gauche, _, val = h.partition(":")
        nom = gauche.split(";")[0].upper()
        params = gauche.upper()
        val = _vc_unescape(val)
        if nom == "FN":
            cur["display_name"] = val
        elif nom == "N" and not cur.get("display_name"):
            p = [x.strip() for x in val.split(";")]
            cur["display_name"] = " ".join(x for x in [p[1] if len(p) > 1 else "", p[0]] if x)
        elif nom == "EMAIL":
            if val:
                cur["emails"].append(val.strip().lower())
        elif nom == "TEL":
            (cur["cell"] if "CELL" in params or "MOBILE" in params else cur["tel"]).append(val)
        elif nom == "ORG":
            cur["company"] = val.split(";")[0].strip()
        elif nom == "TITLE":
            cur["job_title"] = val
        elif nom == "ADR":
            cur["address"] = ", ".join(x for x in [p.strip() for p in val.split(";")] if x)
        elif nom == "URL":
            cur["website"] = val
        elif nom == "CATEGORIES":
            cur["tags"] = val
        elif nom == "NOTE":
            cur["notes"] = val
    return fiches


# ══════════════════════════════════════════════════════════════════════════════
#  LE VERSEMENT — une seule porte pour toutes les voies d'import
#
#  vCard, CSV, Telegram, CardDAV, les bases de vos sites : cinq provenances,
#  un seul carnet. Si chacune écrivait à sa façon, cinq comportements
#  divergeraient sur les mêmes questions — que faire d'un doublon, où ranger,
#  quoi écraser.
#
#  DEUX RÈGLES QUI NE SE DISCUTENT PAS :
#
#    · ON DÉTECTE AVANT D'ÉCRIRE. « 412 fiches, dont 18 existent déjà » — on
#      rattache, on ne crée pas un doublon qu'il faudra fusionner ensuite.
#      Un import qui double le carnet est le pire des deux mondes : il ajoute
#      du travail au lieu d'en retirer.
#
#    · ON N'ÉCRASE JAMAIS CE QUI A ÉTÉ SAISI À LA MAIN. Une fiche `manuel`
#      est la seule dont on sache qu'un humain l'a voulue. Un import ne la
#      complète que là où elle est VIDE, et ne la contredit jamais.
# ══════════════════════════════════════════════════════════════════════════════

# Au-delà, ce n'est plus un carnet d'adresses qu'on importe, c'est une base
# clients. On s'arrête et on le dit, plutôt que de remplir en silence.
_CT_IMPORT_MAX = 2000


def _ct_tels_connus() -> dict:
    """Les téléphones déjà rattachés, normalisés. Une seule requête.

    Telegram ne donne PAS d'adresse : nom, pseudo, téléphone, rien d'autre.
    Sans ce second index, chaque liaison recréerait quarante-sept fiches à
    côté de celles qu'on a déjà — l'import doublerait le carnet au lieu de
    le remplir.
    """
    conn = None
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        _iso_migrer(conn)
        _c, _a = _iso_ou()
        out = {}
        for x in conn.execute("SELECT id, phone, mobile FROM contacts "
                              "WHERE COALESCE(supprime_at,'')=''" + _c, list(_a)):
            for t in (x[1], x[2]):
                k = _ct_norm_tel(t)
                # LE PREMIER GAGNE. Deux fiches partageant un fixe existent —
                # deux personnes d'un même foyer —, et l'import ne doit pas
                # choisir : il rattache à celle qu'il a vue en premier, et la
                # détection de doublons fera le reste, à l'écran.
                if k and k not in out:
                    out[k] = x[0]
        return out
    except Exception as e:
        logging.info("[CARNET] téléphones connus : %s", e)
        return {}
    finally:
        if conn:
            try:
                conn.close()
            except Exception:
                pass


def _ct_adresses_connues() -> dict:
    """Toute adresse déjà rattachée, et à quelle fiche. Une seule requête.

    Interroger la base par adresse ferait quatre cents allers-retours pour un
    import de quatre cents lignes — et l'écran attendrait pour un travail que
    SQLite fait en un coup.
    """
    conn = None
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        _iso_migrer(conn)
        _c, _a = _iso_ou("c")
        return {str(x[0]).lower(): x[1] for x in conn.execute(
            "SELECT e.addr, e.contact_id FROM contact_emails e "
            "JOIN contacts c ON c.id = e.contact_id WHERE 1=1" + _c, list(_a))}
    except Exception as e:
        logging.info("[CARNET] adresses connues : %s", e)
        return {}
    finally:
        if conn:
            try:
                conn.close()
            except Exception:
                pass


def _ct_completer(cid, venu: dict) -> int:
    """Complète une fiche EXISTANTE là où elle est vide. Rend le nb de champs.

    On ne contredit jamais : si la fiche porte déjà un téléphone, celui de
    l'import est ignoré. C'est la règle qui permet d'importer deux fois sans
    dégât, et de ne jamais perdre une correction faite à la main.
    """
    f = (contact_get(cid) or {}).get("contact") or {}
    if not f:
        return 0
    patch = {}
    for k in ("company", "job_title", "phone", "mobile", "address", "website"):
        v = str(venu.get(k) or "").strip()
        if v and not str(f.get(k) or "").strip():
            patch[k] = v
    # `anniversaire` n'est pas un paramètre de `contact_save` : il se pose à
    # part, comme à la création.
    _anv = str(venu.get("anniversaire") or "").strip()
    _anv_a_poser = _anv and not str(f.get("anniversaire") or "").strip()
    # Une adresse de plus n'écrase rien : elle s'ajoute.
    adrs = list(f.get("emails") or [])
    for a in (venu.get("emails") or []):
        a = str(a or "").strip().lower()
        if a and a not in adrs:
            adrs.append(a)
            patch["emails"] = adrs
    if _anv_a_poser:
        _ct_apres_creation(cid, {"anniversaire": _anv}, 0)
    if not patch:
        return 1 if _anv_a_poser else 0
    # `contact_save` RÉÉCRIT LA FICHE ENTIÈRE : un champ non transmis n'est pas
    # « laissé tel quel », il est remis à vide. Envoyer seulement les champs
    # complétés effaçait donc tout le reste — dont le téléphone saisi à la
    # main, exactement ce que ce complément est censé protéger.
    # On repart de la fiche COMPLÈTE, et on pose le patch dessus.
    plein = {k: (f.get(k) or "") for k in
             ("company", "job_title", "phone", "mobile", "address", "website",
              "notes", "tags")}
    plein.update({k: v for k, v in patch.items() if k != "emails"})
    try:
        contact_save(cid=cid, display_name=f.get("display_name") or "",
                     emails=patch.get("emails", adrs),
                     favorite=bool(f.get("favorite")),
                     vault_ref=f.get("vault_ref"), **plein)
    except Exception as e:
        logging.info("[CARNET] complément de %s : %s", cid, e)
        return 0
    return len(patch) + (1 if _anv_a_poser else 0)


def contacts_verser(fiches, source: str = "import", dossier_id=0,
                    completer: bool = True, compte: str = None) -> dict:
    """Verse un lot de fiches normalisées. Rend un COMPTE RENDU, pas un « ok ».

    Chaque entrée : {display_name, emails[], phone, mobile, company, job_title,
    address, website, anniversaire, notes, tags}.

    Un import silencieux qui double le carnet est le pire des deux mondes :
    on rend donc toujours combien sont créées, combien existaient déjà, et
    combien ont été complétées.
    """
    _contacts_migrate()
    lot = [f for f in (fiches or []) if isinstance(f, dict)][:_CT_IMPORT_MAX]
    if not lot:
        return {"ok": False, "reason": "rien à verser"}
    connues = _ct_adresses_connues()
    # L'index des téléphones ne se construit QUE si une entrée en a besoin :
    # une vCard ordinaire porte des adresses, et la requête serait perdue.
    tels = _ct_tels_connus() if any(
        not (f.get("emails") or []) and (f.get("phone") or f.get("mobile"))
        for f in lot) else {}
    compte = (compte or "").strip().lower() or _iso_moi()
    crees, deja, completees, refus = 0, 0, 0, []
    vus_ids = []
    for f in lot:
        adrs = [str(a or "").strip().lower() for a in (f.get("emails") or []) if a]
        adrs = [a for a in adrs if "@" in a]
        # ── DÉJÀ LÀ ? ───────────────────────────────────────────────────────
        cid = next((connues[a] for a in adrs if a in connues), 0)
        # PAS D'ADRESSE ? le téléphone sert de second recours. Jamais l'inverse :
        # une adresse est une identité, un numéro se partage et se recycle.
        if not cid and not adrs:
            for _t in (f.get("phone"), f.get("mobile")):
                _k = _ct_norm_tel(_t)
                if _k and _k in tels:
                    cid = tels[_k]
                    break
        if cid:
            deja += 1
            vus_ids.append(cid)
            if completer:
                completees += 1 if _ct_completer(cid, f) else 0
            continue
        nom = str(f.get("display_name") or "").strip()
        if not nom and not adrs:
            refus.append("une entrée sans nom ni adresse")
            continue
        try:
            r = contact_save(
                display_name=nom or adrs[0].split("@")[0],
                emails=adrs, phone=str(f.get("phone") or ""),
                mobile=str(f.get("mobile") or ""),
                company=str(f.get("company") or ""),
                job_title=str(f.get("job_title") or ""),
                address=str(f.get("address") or ""),
                website=str(f.get("website") or ""),
                notes=str(f.get("notes") or ""),
                tags=str(f.get("tags") or ""), compte=compte)
        except Exception as e:
            refus.append("%s : %s" % (nom or "?", str(e)[:60]))
            continue
        if not r.get("ok"):
            refus.append("%s : %s" % (nom or "?", r.get("reason") or "refusé"))
            continue
        crees += 1
        _id = r.get("id")
        if _id:
            vus_ids.append(_id)
            for a in adrs:
                connues[a] = _id
            # LE NUMÉRO AUSSI. L'index des téléphones n'était construit qu'une fois,
            # avant la boucle : un doublon présent dans la liste source n'était jamais
            # reconnu pendant la passe — 422 paires jumelles nées la même seconde le
            # 19-08 (B2, mesuré par Cassandra au tour 3).
            for _t in (f.get("phone"), f.get("mobile")):
                _k = _ct_norm_tel(_t)
                if _k and _k not in tels:
                    tels[_k] = _id
        # L'anniversaire et le dossier ne passent pas par `contact_save` :
        # ils sont posés juste après, sur la fiche qu'on vient de créer.
        _ct_apres_creation(_id, f, dossier_id, source)
    return {"ok": True, "crees": crees, "deja": deja, "completees": completees,
            "lus": len(lot), "refus": refus[:8], "ids": vus_ids[:500],
            "tronque": len(fiches or []) > _CT_IMPORT_MAX}


def _ct_apres_creation(cid, f: dict, dossier_id, source: str = "") -> None:
    """Le dossier et l'anniversaire, que `contact_save` ne connaît pas.

    Plutôt que d'élargir la porte d'écriture — qui sert à vingt appelants et
    dont chaque paramètre de plus est une occasion de casser —, on pose ces
    deux champs à côté, sur une fiche qui existe déjà.
    """
    if not cid:
        return
    sets, args = [], []
    if dossier_id:
        sets.append("dossier_id=?")
        args.append(int(dossier_id))
    # LA PROVENANCE se pose ICI, pas dans `contact_save` : cette porte sert à
    # vingt appelants, et chaque paramètre de plus y est une occasion de
    # casser. Sans elle, toute fiche importée se déclarerait « saisie à la
    # main » — et la règle qui protège les saisies protégerait alors tout,
    # donc plus rien.
    if source:
        sets.append("source=?")
        args.append(str(source)[:40])
    anv = str(f.get("anniversaire") or "").strip()[:20]
    if anv:
        sets.append("anniversaire=?")
        args.append(anv)
    if not sets:
        return
    conn = None
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        _iso_migrer(conn)
        _c, _a = _iso_ou()
        conn.execute("UPDATE contacts SET %s WHERE id=?%s" % (", ".join(sets), _c),
                     args + [int(cid)] + list(_a))
        conn.commit()
    except Exception as e:
        logging.info("[CARNET] après création de %s : %s", cid, e)
    finally:
        if conn:
            try:
                conn.close()
            except Exception:
                pass


def contact_dossier_pour(nom: str):
    """Le dossier de ce nom, créé s'il n'existe pas. Rend son identifiant.

    Chaque import range dans SON dossier — « Clients boutique.fr », « Telegram »
    — plutôt que dans un fourre-tout « importés » où deux cents inconnus se
    mélangeraient à vos clients.
    """
    nom = str(nom or "").strip()[:_CT_DOSSIER_MAX]
    if not nom:
        return 0
    d = contact_dossiers()
    for x in (d.get("dossiers") or []):
        if (x.get("nom") or "").strip().lower() == nom.lower():
            return x["id"]
    r = contact_dossier_save(nom)
    return r.get("id", 0) if r.get("ok") else 0


def contact_vcard_import(texte: str) -> dict:
    """Importe des vCard. Une fiche dont l'adresse est déjà connue MET À JOUR la
    fiche existante au lieu d'en créer une seconde — sinon chaque import du
    carnet du téléphone doublerait tout le monde."""
    _contacts_migrate()
    fiches = vcard_parse(texte)
    if not fiches:
        return {"ok": False, "reason": "aucune fiche vCard reconnue"}
    ajout, maj, erreurs = 0, 0, []
    for f in fiches:
        adrs = [a for a in f.get("emails", []) if _EMAIL_RE.match(a)]
        cid = None
        if adrs:
            try:
                conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
                for a in adrs:
                    cid = _contact_addr_owner(conn, a)
                    if cid:
                        break
                conn.close()
            except Exception as e:
                logging.info("[VCARD] recherche : %s", e)
        r = contact_save(display_name=f.get("display_name", ""), emails=adrs,
                         phone=(f.get("tel") or [""])[0], mobile=(f.get("cell") or [""])[0],
                         company=f.get("company", ""), job_title=f.get("job_title", ""),
                         address=f.get("address", ""), website=f.get("website", ""),
                         notes=f.get("notes", ""), tags=f.get("tags", ""), cid=cid)
        if r.get("ok"):
            maj += 1 if cid else 0
            ajout += 0 if cid else 1
        else:
            erreurs.append("%s : %s" % (f.get("display_name", "?"), r.get("reason")))
    return {"ok": True, "added": ajout, "updated": maj, "errors": erreurs[:10],
            "parsed": len(fiches)}


# ══════════════════════════════════════════════════════════════════════════════
#  L'IMPORT CSV — Google, Outlook, et tous les autres
#
#  C'est le format que rendent les deux carnets les plus répandus, et la SEULE
#  voie vivante pour Outlook, qui n'a jamais ouvert CardDAV.
#
#  Trois choses qu'un import CSV rate presque toujours, et qu'on traite ici :
#
#    · L'ENCODAGE. Un export Outlook français est en cp1252, pas en UTF-8 :
#      lu de travers, « Frédéric » devient « FrÃ©dÃ©ric » dans le carnet, et
#      personne ne remarque avant de chercher son nom.
#    · LE SÉPARATEUR. Excel francophone écrit des point-virgules. Lu avec des
#      virgules, le fichier entier tient dans une seule colonne.
#    · L'APPARIEMENT. Deux exports du même service n'ont pas les mêmes
#      colonnes d'une année sur l'autre. On reconnaît ce qu'on peut, et on
#      MONTRE le reste plutôt que de deviner.
# ══════════════════════════════════════════════════════════════════════════════

# Ce qu'on accepte de lire d'un coup. Au-delà, ce n'est plus un carnet.
_CSV_MAX = 6 * 1024 * 1024

# Les en-têtes reconnus, en français et en anglais, chez Google et chez
# Outlook. La clé est le libellé APLATI : sans accents, sans casse, sans
# ponctuation — « Téléphone professionnel » et « telephone professionnel » ne
# doivent pas demander deux entrées.
_CSV_CHAMPS = {
    # « Nom » N'EST PAS un nom complet. Chez Outlook francais il est le nom de
    # FAMILLE, à côté de « Prénom » — le ranger ici donnait des fiches nommées
    # « Béranger » sans leur prénom, et rien ne le signalait. Le nom entier se
    # dit « Nom complet » ou « Name », jamais « Nom » seul.
    "display_name": (
        "name", "nom complet", "full name", "display name",
        "nom affiche", "contact"),
    "_prenom": ("first name", "given name", "prenom"),
    "_nom": ("last name", "family name", "surname", "nom de famille", "nom"),
    "emails": (
        "e mail 1 value", "e mail address", "email address", "email",
        "e mail", "courriel", "adresse de messagerie", "adresse e mail",
        "e mail 2 value", "e mail address 2", "adresse de messagerie 2"),
    "phone": (
        "phone 1 value", "business phone", "home phone", "telephone",
        "telephone professionnel", "telephone domicile", "tel", "phone"),
    "mobile": (
        "phone 2 value", "mobile phone", "mobile", "portable",
        "telephone mobile", "cell phone"),
    "company": (
        "organization name", "organization 1 name", "company", "societe",
        "entreprise", "organisation"),
    "job_title": (
        "organization title", "organization 1 title", "job title", "fonction",
        "titre", "poste"),
    "address": (
        "address 1 formatted", "home address", "business street", "adresse",
        "rue", "adresse professionnelle", "address"),
    "website": ("website 1 value", "web page", "site web", "site", "url"),
    "anniversaire": ("birthday", "anniversaire", "date de naissance", "birth date"),
    "notes": ("notes", "note", "remarques", "comments"),
}
# Les colonnes qui portent PLUSIEURS adresses. Un carnet Google en a jusqu'à
# quatre ; n'en prendre qu'une perdrait l'adresse professionnelle de la moitié
# des fiches.
_CSV_MULTI = ("emails",)


def _csv_pla(s: str) -> str:
    """Un libellé d'en-tête aplati, pour le comparer sans y penser."""
    t = unicodedata.normalize("NFD", str(s or ""))
    t = "".join(c for c in t if unicodedata.category(c) != "Mn").lower()
    return " ".join(re.sub(r"[^a-z0-9]+", " ", t).split())


def _csv_decoder(octets: bytes) -> tuple:
    """Le texte et l'encodage retenu.

    L'ordre compte : UTF-8 d'abord parce qu'il ÉCHOUE franchement sur un
    fichier qui n'en est pas, alors que cp1252 accepte n'importe quels octets
    et rendrait des caractères faux sans jamais lever.
    """
    if octets[:3] == b"\xef\xbb\xbf":
        return (octets[3:].decode("utf-8", "replace"), "utf-8-bom")
    for enc in ("utf-8", "cp1252", "latin-1"):
        try:
            return (octets.decode(enc), enc)
        except Exception:
            continue
    return (octets.decode("utf-8", "replace"), "utf-8 (approché)")


def _csv_separateur(tete: str) -> str:
    """Le séparateur de la PREMIÈRE ligne : celui qui découpe le plus.

    `csv.Sniffer` se trompe sur les fichiers à une colonne et lève sur les
    fichiers courts. Compter trois caractères sur l'en-tête est plus bête et
    ne se trompe pas.
    """
    return max((";", ",", "\t", "|"), key=lambda c: tete.count(c))


def _csv_lire(octets: bytes) -> dict:
    """Découpe le fichier. Rend les en-têtes, les lignes, et ce qu'on a deviné."""
    import csv as _csv
    import io as _io          # locaux : ni l'un ni l'autre n'est global ici
    if not octets:
        return {"ok": False, "reason": "fichier vide"}
    if len(octets) > _CSV_MAX:
        return {"ok": False, "reason": "fichier trop volumineux (%d Ko)"
                                       % (len(octets) // 1024)}
    texte, enc = _csv_decoder(octets)
    tete = texte.split("\n", 1)[0]
    sep = _csv_separateur(tete)
    try:
        lignes = list(_csv.reader(_io.StringIO(texte), delimiter=sep))
    except Exception as e:
        return {"ok": False, "reason": "lecture impossible : %s" % str(e)[:80]}
    lignes = [l for l in lignes if any((x or "").strip() for x in l)]
    if len(lignes) < 2:
        return {"ok": False, "reason": "aucune ligne de données"}
    entetes = [(x or "").strip() for x in lignes[0]]
    return {"ok": True, "entetes": entetes, "lignes": lignes[1:],
            "encodage": enc, "separateur": sep}


def _csv_apparier(entetes: list) -> dict:
    """Appariement automatique : colonne → champ. Ce qui n'est pas reconnu
    reste vide, et l'écran le montre plutôt que de le deviner."""
    connus = {}
    for champ, libelles in _CSV_CHAMPS.items():
        for lib in libelles:
            connus[lib] = champ
    out = {}
    for i, e in enumerate(entetes):
        c = connus.get(_csv_pla(e))
        if c:
            out[str(i)] = c
    return out


def csv_apercu(contenu_b64: str) -> dict:
    """Ce qu'on a compris du fichier, AVANT d'écrire quoi que ce soit.

    Un import qui se lance sans montrer ce qu'il a compris ne se rattrape
    pas : les fiches sont créées, et il faut les retrouver une par une.
    """
    try:
        octets = base64.b64decode(contenu_b64 or "", validate=False)
    except Exception:
        return {"ok": False, "reason": "contenu illisible"}
    d = _csv_lire(octets)
    if not d.get("ok"):
        return d
    app = _csv_apparier(d["entetes"])
    # Trois lignes d'exemple : assez pour voir qu'une colonne est bien celle
    # qu'on croit, pas assez pour noyer l'écran.
    ex = [[(c or "")[:60] for c in l] for l in d["lignes"][:3]]
    reconnus = sorted(set(app.values()))
    return {"ok": True, "entetes": d["entetes"], "appariement": app,
            "exemples": ex, "lignes": len(d["lignes"]),
            "encodage": d["encodage"], "separateur": d["separateur"],
            "reconnus": reconnus,
            # Sans nom NI adresse, on ne saurait même pas nommer les fiches.
            "utilisable": bool({"display_name", "_prenom", "_nom", "emails"}
                               & set(reconnus))}


def _csv_valeur(ligne: list, i) -> str:
    try:
        return str(ligne[int(i)] or "").strip()
    except Exception:
        return ""


def csv_importer(contenu_b64: str, appariement=None, dossier: str = "") -> dict:
    """Verse un CSV par la porte commune, avec l'appariement confirmé."""
    try:
        octets = base64.b64decode(contenu_b64 or "", validate=False)
    except Exception:
        return {"ok": False, "reason": "contenu illisible"}
    d = _csv_lire(octets)
    if not d.get("ok"):
        return d
    app = appariement if isinstance(appariement, dict) and appariement \
        else _csv_apparier(d["entetes"])
    if not app:
        return {"ok": False, "reason": "aucune colonne reconnue — appariez-les "
                                       "à la main avant d'importer"}
    fiches = []
    for ligne in d["lignes"]:
        f, prenom, nom = {"emails": []}, "", ""
        for i, champ in app.items():
            v = _csv_valeur(ligne, i)
            if not v:
                continue
            if champ == "_prenom":
                prenom = v
            elif champ == "_nom":
                nom = v
            elif champ in _CSV_MULTI:
                # PLUSIEURS COLONNES POUR LE MÊME CHAMP : on les additionne au
                # lieu que la dernière écrase les précédentes.
                for a in re.split(r"[;,\s]+", v):
                    a = a.strip().lower()
                    if "@" in a and a not in f["emails"]:
                        f["emails"].append(a)
            elif champ not in f:
                f[champ] = v
        if not f.get("display_name"):
            f["display_name"] = " ".join(x for x in (prenom, nom) if x)
        if f.get("display_name") or f.get("emails"):
            fiches.append(f)
    if not fiches:
        return {"ok": False, "reason": "aucune ligne exploitable"}
    dos = contact_dossier_pour(dossier) if dossier else 0
    out = contacts_verser(fiches, source="csv", dossier_id=dos)
    if out.get("ok"):
        out["message"] = "%d fiche(s) créée(s), %d existaient déjà, %d complétée(s)" % (
            out.get("crees", 0), out.get("deja", 0), out.get("completees", 0))
    return out


# ══════════════════════════════════════════════════════════════════════════════
#  CARDDAV — la seule vraie synchro, et le même transport que l'agenda
#
#  Vérifié en août 2026 : iCloud l'ouvre avec un « mot de passe pour app »
#  créé en deux minutes ; Nextcloud aussi ; Google exige OAuth pour ce
#  protocole-là et Microsoft ne l'a jamais ouvert. On sert donc les deux
#  premiers, et on le dit pour les deux autres au lieu de les faire échouer
#  sans explication.
#
#  LES IDENTIFIANTS VONT AU COFFRE DU COMPTE, comme ceux de la boîte mail et
#  de l'agenda. Deux personnes sur la même machine relient chacune le sien
#  sans se voir, et rien n'est en clair sur le disque.
# ══════════════════════════════════════════════════════════════════════════════

_CARDDAV_SECRET = "carddav"
# Un carnet distant peut être gros ; au-delà on s'arrête et on le dit.
_CARDDAV_MAX = 3000
# Les serveurs connus, avec leur adresse toute prête. Le reste se saisit.
_CARDDAV_PRETS = {
    "icloud": {"nom": "iCloud", "url": "https://contacts.icloud.com",
               "aide": "Créez un « mot de passe pour app » sur votre compte "
                       "Apple : le mot de passe habituel ne passe pas."},
    "nextcloud": {"nom": "Nextcloud", "url": "",
                  "aide": "L'adresse ressemble à "
                          "https://cloud.exemple.fr/remote.php/dav"},
}


def _carddav_creds_du_coffre(user: str):
    """(url, identifiant, mot de passe) rangés dans le coffre de CETTE personne."""
    if not user:
        return None
    try:
        d = vault_native_get(user, _CARDDAV_SECRET)
    except Exception as e:
        logging.debug("[CARDDAV] coffre de %s : %s", user, e)
        return None
    if not isinstance(d, dict):
        return None
    url = (d.get("uri") or "").strip()
    if not url or not d.get("username"):
        return None
    return (url.rstrip("/"), (d.get("username") or "").strip(), d.get("password") or "")


def _carddav_creds():
    """Le carnet distant de CETTE personne, ou rien.

    Aucun repli sur une configuration commune : des identifiants partagés sont
    des données partagées, et c'est la règle déjà posée pour la boîte mail et
    pour l'agenda.
    """
    try:
        return _carddav_creds_du_coffre((get_current_user() or "").strip()) or ("", "", "")
    except Exception:
        return ("", "", "")


def carddav_relier(url: str, identifiant: str, mdp: str) -> dict:
    """Range les identifiants au coffre, après les avoir ESSAYÉS.

    Écrire d'abord et découvrir l'erreur au premier import laisserait un
    réglage qui a l'air posé et ne marche pas — le pire des deux.
    """
    url = str(url or "").strip().rstrip("/")
    identifiant = str(identifiant or "").strip()
    if not url or not identifiant:
        return {"ok": False, "reason": "adresse et identifiant requis"}
    if not url.lower().startswith("https://"):
        return {"ok": False, "reason": "seul HTTPS est accepté : en clair, vos "
                                       "contacts voyageraient lisibles"}
    compte = (get_current_user() or "").strip()
    if not compte:
        return {"ok": False, "reason": "aucun compte"}
    essai = _carddav_essai(url, identifiant, mdp)
    if not essai.get("ok"):
        return essai
    try:
        # `set_login` et non `set` : c'est la forme qui range séparément
        # l'adresse, l'identifiant et le mot de passe — celle que
        # `_carddav_creds_du_coffre` relit, et celle qu'emploient déjà la
        # boîte mail et l'agenda.
        _v = vault_native_set_login(compte, _CARDDAV_SECRET, identifiant, mdp, url)
        if not _v.get("ok"):
            return {"ok": False, "reason": "le coffre a refusé : %s"
                                           % (_v.get("error") or "indisponible")}
    except Exception as e:
        return {"ok": False, "reason": "le coffre a refusé : %s" % str(e)[:120]}
    return {"ok": True, "carnets": essai.get("carnets") or []}


def carddav_delier() -> dict:
    """Oublie les identifiants. Les fiches déjà importées RESTENT.

    Délier n'est pas supprimer : un carnet qu'on débranche ne doit pas emporter
    les gens qu'on y a trouvés.
    """
    compte = (get_current_user() or "").strip()
    if not compte:
        return {"ok": False, "reason": "aucun compte"}
    try:
        vault_native_delete(compte, _CARDDAV_SECRET)
    except Exception as e:
        return {"ok": False, "reason": str(e)[:120]}
    return {"ok": True}


def _carddav_req(methode, url, corps=None, entetes=None, user="", mdp=""):
    """Une requête DAV. Rend (code, texte). Ne lève pas : rend (0, message)."""
    import urllib.request
    import urllib.error
    try:
        data = corps.encode("utf-8") if isinstance(corps, str) else corps
        req = urllib.request.Request(url, data=data, method=methode)
        if user:
            req.add_header("Authorization", "Basic " + base64.b64encode(
                ("%s:%s" % (user, mdp)).encode()).decode())
        req.add_header("User-Agent", "Cassandra/carnet")
        for k, v in (entetes or {}).items():
            req.add_header(k, v)
        with urllib.request.urlopen(req, timeout=20) as rep:
            return (getattr(rep, "status", 200),
                    rep.read().decode("utf-8", errors="replace"))
    except urllib.error.HTTPError as e:
        try:
            corps_err = e.read().decode("utf-8", "replace")[:300]
        except Exception:
            corps_err = ""
        return (e.code, corps_err)
    except Exception as e:
        return (0, str(e)[:160])


# Les balises qu'on lit dans une réponse DAV. On ne monte pas d'analyseur XML
# complet : trois expressions suffisent, et un carnet mal formé ne fait pas
# tomber l'import.
_DAV_HREF = re.compile(r"<[^>]*href[^>]*>([^<]+)</[^>]*href>", re.I)
_DAV_ADRBOOK = re.compile(r"addressbook", re.I)
_DAV_DATA = re.compile(r"<[^>]*address-data[^>]*>(.*?)</[^>]*address-data>",
                       re.I | re.S)


def _carddav_essai(url, user, mdp) -> dict:
    """Cherche les carnets d'adresses à cette adresse. Sert aussi de test."""
    code, txt = _carddav_req(
        "PROPFIND", url,
        '<?xml version="1.0"?><d:propfind xmlns:d="DAV:">'
        '<d:prop><d:resourcetype/><d:displayname/></d:prop></d:propfind>',
        {"Depth": "1", "Content-Type": "application/xml; charset=utf-8"},
        user, mdp)
    if code == 401:
        return {"ok": False, "reason": "identifiants refusés. Chez iCloud, il "
                                       "faut un « mot de passe pour app », pas "
                                       "le mot de passe habituel."}
    if code == 0:
        return {"ok": False, "reason": "serveur injoignable : %s" % txt}
    if code not in (200, 207):
        return {"ok": False, "reason": "réponse inattendue du serveur (%d)" % code}
    carnets = []
    for bloc in re.split(r"<[^>]*response[^>]*>", txt, flags=re.I)[1:]:
        if not _DAV_ADRBOOK.search(bloc):
            continue
        h = _DAV_HREF.search(bloc)
        if h:
            carnets.append(h.group(1).strip())
    # PAS DE CARNET À CETTE ADRESSE ne veut pas dire « pas de carnet » : la
    # racine d'un serveur DAV renvoie souvent le PRINCIPAL, et les carnets
    # sont un cran plus bas. On le dit plutôt que d'annoncer un échec.
    return {"ok": True, "carnets": carnets,
            "message": ("%d carnet(s) trouvé(s)" % len(carnets)) if carnets else
                       "connexion acceptée, mais aucun carnet à cette adresse "
                       "exactement — essayez l'adresse complète du carnet"}


def carddav_etat() -> dict:
    """Ce qui est relié, sans jamais rendre le mot de passe."""
    url, user, _ = _carddav_creds()
    return {"ok": True, "relie": bool(url), "url": url, "identifiant": user,
            "prets": _CARDDAV_PRETS}


def carddav_importer(carnet: str = "", dossier: str = "") -> dict:
    """Lit le carnet distant et le verse par la porte commune.

    SENS UNIQUE POUR L'INSTANT : on lit, on ne réécrit rien chez le serveur.
    Une synchro qui écrit dans les deux sens demande de savoir qui a raison
    quand les deux côtés ont changé — et se tromper efface le carnet de
    quelqu'un. Elle se fera, mais elle se décidera.
    """
    url, user, mdp = _carddav_creds()
    if not url:
        return {"ok": False, "reason": "aucun carnet distant relié"}
    cible = str(carnet or "").strip() or url
    if cible.startswith("/"):
        # Un href DAV est relatif : on le recolle à l'origine, pas à l'URL
        # complète — sinon on empile deux chemins.
        m = re.match(r"^(https://[^/]+)", url)
        cible = (m.group(1) if m else url) + cible
    code, txt = _carddav_req(
        "REPORT", cible,
        '<?xml version="1.0"?><c:addressbook-query xmlns:d="DAV:" '
        'xmlns:c="urn:ietf:params:xml:ns:carddav"><d:prop><d:getetag/>'
        '<c:address-data/></d:prop></c:addressbook-query>',
        {"Depth": "1", "Content-Type": "application/xml; charset=utf-8"},
        user, mdp)
    if code == 401:
        return {"ok": False, "reason": "identifiants refusés"}
    if code not in (200, 207):
        return {"ok": False, "reason": "le serveur a répondu %d%s"
                                       % (code, (" : " + txt[:120]) if txt else "")}
    cartes = [_dav_detexte(x) for x in _DAV_DATA.findall(txt)]
    fiches = []
    for c in cartes[:_CARDDAV_MAX]:
        f = _vcard_une(c)
        if f:
            fiches.append(f)
    if not fiches:
        return {"ok": False, "reason": "aucune fiche lisible dans ce carnet"}
    dos = contact_dossier_pour(dossier) if dossier else 0
    out = contacts_verser(fiches, source="carddav", dossier_id=dos)
    if out.get("ok"):
        out["message"] = "%d fiche(s) créée(s), %d existaient déjà, %d complétée(s)" % (
            out.get("crees", 0), out.get("deja", 0), out.get("completees", 0))
    return out


def _dav_detexte(s: str) -> str:
    """Le contenu d'une balise XML, entités rendues à leur caractère."""
    t = str(s or "")
    for a, b in (("&lt;", "<"), ("&gt;", ">"), ("&quot;", '"'),
                 ("&#39;", "'"), ("&apos;", "'"), ("&amp;", "&")):
        t = t.replace(a, b)
    return t.strip()


# Une vCard replie ses lignes longues : la suite d'une valeur commence par une
# espace ou une tabulation. Sans les recoller, une adresse coupée en deux
# devient deux champs illisibles.
def _vcard_deplier(texte: str) -> list:
    out = []
    for ligne in str(texte or "").replace("\r\n", "\n").replace("\r", "\n").split("\n"):
        if ligne[:1] in (" ", "\t") and out:
            out[-1] += ligne[1:]
        else:
            out.append(ligne)
    return out


def _vcard_une(texte: str) -> dict:
    """Une vCard → une fiche normalisée, prête pour la porte commune."""
    f = {"emails": []}
    nom_n = ""
    for ligne in _vcard_deplier(texte):
        if ":" not in ligne:
            continue
        gauche, valeur = ligne.split(":", 1)
        cle = gauche.split(";")[0].strip().upper()
        params = gauche.upper()
        valeur = valeur.strip().replace("\\,", ",").replace("\\;", ";").replace("\\n", " ")
        if not valeur:
            continue
        if cle == "FN":
            f["display_name"] = valeur
        elif cle == "N" and not nom_n:
            # « Dubois;Marie;;; » — famille d'abord, prénom ensuite.
            p = [x.strip() for x in valeur.split(";")]
            nom_n = " ".join(x for x in (p[1] if len(p) > 1 else "",
                                         p[0] if p else "") if x)
        elif cle == "EMAIL":
            a = valeur.strip().lower()
            if "@" in a and a not in f["emails"]:
                f["emails"].append(a)
        elif cle == "TEL":
            if "CELL" in params or "MOBILE" in params:
                f.setdefault("mobile", valeur)
            else:
                f.setdefault("phone", valeur)
        elif cle == "ORG":
            f.setdefault("company", valeur.split(";")[0].strip())
        elif cle == "TITLE":
            f.setdefault("job_title", valeur)
        elif cle == "ADR":
            f.setdefault("address", " ".join(
                x.strip() for x in valeur.split(";") if x.strip()))
        elif cle == "URL":
            f.setdefault("website", valeur)
        elif cle == "BDAY":
            f.setdefault("anniversaire", valeur[:20])
        elif cle == "NOTE":
            f.setdefault("notes", valeur[:2000])
    if not f.get("display_name"):
        f["display_name"] = nom_n
    if not f.get("display_name") and not f["emails"]:
        return {}
    return f


# ══════════════════════════════════════════════════════════════════════════════
#  LES CARNETS DE VOS SITES — WordPress, Joomla, Dolibarr, PrestaShop
#
#  C'est la voie la plus riche, et la seule qui touche les données de TIERS.
#  Trois règles la cadrent, et aucune n'est négociable :
#
#    · EN LECTURE SEULE, TOUJOURS. Un carnet qui écrit dans une boutique en
#      production est un incident qui attend son heure. La requête est
#      contrôlée avant d'être lancée, pas seulement « prévue » en SELECT.
#
#    · BORNÉ AUX SITES QUE LE COMPTE POSSÈDE. La même porte que les quatre
#      outils de site : `user_owns_domain`, et le rattachement vient de
#      FastPanel, pas d'une ressemblance de noms.
#
#    · IMPORT SÉLECTIF, DANS SON PROPRE DOSSIER. Les 400 clients d'une
#      boutique ne sont pas votre carnet d'adresses : les verser en masse le
#      remplirait de gens que vous ne contacterez jamais — et vous en rendrait
#      responsable une seconde fois.
# ══════════════════════════════════════════════════════════════════════════════

# Au-delà, on s'arrête et on le dit : ce n'est plus un carnet qu'on reprend.
_CMS_LIGNES_MAX = 2000
# Une requête de lecture ne doit jamais retenir le serveur.
_CMS_DELAI = 12

# Ce qui reconnaît un logiciel : une table qui n'existe QUE chez lui. Le
# préfixe est libre chez presque tous — c'est donc le SUFFIXE qu'on cherche.
# Le souligné appartient au PRÉFIXE, pas à la signature : l'inclure ici
# donnait « wp » au lieu de « wp_ », et la requête visait « wpusers » — une
# table qui n'existe pas, donc zéro personne trouvée sans la moindre erreur.
_CMS_SIGNES = (
    ("dolibarr",    "socpeople",          "Dolibarr"),
    ("woocommerce", "wc_customer_lookup", "WooCommerce"),
    ("wordpress",   "options",            "WordPress"),
    ("joomla",      "extensions",         "Joomla"),
    ("prestashop",  "shop_url",           "PrestaShop"),
)


def _sql_lecture_seule(sql: str) -> bool:
    """La requête est-elle une simple lecture ?

    On ne se contente pas de « ça commence par SELECT » : un point-virgule
    suffirait à en accrocher une seconde. Une seule instruction, et aucun des
    verbes qui écrivent.
    """
    t = " ".join(str(sql or "").split()).strip().rstrip(";")
    if ";" in t:
        return False
    if not re.match(r"(?i)^(select|show)\s", t):
        return False
    return not re.search(
        r"(?i)\b(insert|update|delete|drop|alter|create|truncate|grant|"
        r"replace|rename|load|outfile|into\s+dumpfile)\b", t)


def _cms_sql(base: str, sql: str, colonnes: int = 1) -> list:
    """Lit une base de site. RIEN d'autre que lire.

    Les identifiants sont ceux que FastPanel emploie déjà pour sa propre base ;
    on change seulement de cible. Le nom de la base est vérifié caractère par
    caractère : il part sur une ligne de commande, et un nom fabriqué y serait
    une porte ouverte.
    """
    base = str(base or "").strip()
    if not re.match(r"^[A-Za-z0-9_]{1,64}$", base):
        logging.warning("[CMS] nom de base refusé : %r", base)
        return []
    if not _sql_lecture_seule(sql):
        logging.warning("[CMS] requête refusée (pas une lecture) : %.80s", sql)
        return []
    try:
        creds = _fp_mysql_direct._load_creds() if getattr(
            _fp_mysql_direct, "_load_creds", None) else {}
    except Exception as e:
        logging.info("[CMS] identifiants : %s", e)
        return []
    if not creds or not creds.get("database_password"):
        return []
    import shutil
    import subprocess
    mysql = shutil.which("mysql")
    if not mysql:
        return []
    cmd = [mysql,
           "-h%s" % (creds.get("database_host") or "127.0.0.1"),
           "-P%s" % (creds.get("database_port") or "3306"),
           "-u%s" % (creds.get("database_user") or "root"),
           base, "--batch", "--silent", "--skip-column-names", "-e", sql]
    try:
        res = subprocess.run(cmd, capture_output=True, text=True,
                             errors="replace", timeout=_CMS_DELAI,
                             env={"MYSQL_PWD": creds["database_password"]})
    except Exception as e:
        logging.info("[CMS] lecture de %s : %s", base, e)
        return []
    if res.returncode != 0:
        logging.info("[CMS] %s : %s", base, (res.stderr or "")[:160])
        return []
    out = []
    for ligne in (res.stdout or "").splitlines():
        if not ligne.strip():
            continue
        p = ligne.split("\t")
        out.append(p if colonnes > 1 else p[0])
        if len(out) > _CMS_LIGNES_MAX:
            break
    return out


def _cms_tables(base: str) -> list:
    return [str(x) for x in _cms_sql(base, "SHOW TABLES")]


def _cms_reconnaitre(tables: list) -> dict:
    """Quel logiciel, et avec quel préfixe. On ne devine pas le préfixe : on le
    DÉDUIT de la table qui a servi à reconnaître."""
    bas = [t.lower() for t in tables]
    for cle, signe, nom in _CMS_SIGNES:
        for t in bas:
            if not t.endswith(signe):
                continue
            p = t[:len(t) - len(signe)]
            # LE PRÉFIXE SE TERMINE PAR UN SOULIGNÉ, ou n'existe pas. Sans
            # cette exigence, une table « custom_options » ferait passer une
            # base quelconque pour un WordPress dont le préfixe serait
            # « custom_opt »… et toutes les requêtes suivantes viseraient des
            # tables imaginaires.
            if p and not p.endswith("_"):
                continue
            return {"cms": cle, "nom": nom, "prefixe": p}
    return {}


# La requête qui sort les gens, par logiciel. Toujours un SELECT, toujours
# borné, et toujours les mêmes cinq colonnes dans le même ordre : nom,
# adresse, société, téléphone, fonction.
def _cms_requete(info: dict) -> str:
    p = info.get("prefixe") or ""
    cms = info.get("cms")
    if cms == "dolibarr":
        return ("SELECT TRIM(CONCAT(COALESCE(p.firstname,''),' ',"
                "COALESCE(p.lastname,''))), COALESCE(p.email,''), "
                "COALESCE(s.nom,''), COALESCE(NULLIF(p.phone_mobile,''),"
                "COALESCE(p.phone,'')), COALESCE(p.poste,'') "
                "FROM %ssocpeople p LEFT JOIN %ssociete s ON s.rowid=p.fk_soc "
                "WHERE COALESCE(p.email,'')<>'' LIMIT %d"
                % (p or "llx_", p or "llx_", _CMS_LIGNES_MAX))
    if cms == "woocommerce":
        return ("SELECT TRIM(CONCAT(COALESCE(first_name,''),' ',"
                "COALESCE(last_name,''))), COALESCE(email,''), '', '', '' "
                "FROM %swc_customer_lookup WHERE COALESCE(email,'')<>'' "
                "LIMIT %d" % (p, _CMS_LIGNES_MAX))
    if cms == "wordpress":
        return ("SELECT COALESCE(display_name,''), COALESCE(user_email,''), "
                "'', '', '' FROM %susers WHERE COALESCE(user_email,'')<>'' "
                "LIMIT %d" % (p, _CMS_LIGNES_MAX))
    if cms == "joomla":
        return ("SELECT COALESCE(name,''), COALESCE(email,''), '', '', '' "
                "FROM %susers WHERE COALESCE(email,'')<>'' LIMIT %d"
                % (p, _CMS_LIGNES_MAX))
    if cms == "prestashop":
        return ("SELECT TRIM(CONCAT(COALESCE(firstname,''),' ',"
                "COALESCE(lastname,''))), COALESCE(email,''), "
                "COALESCE(company,''), '', '' FROM %scustomer "
                "WHERE COALESCE(email,'')<>'' LIMIT %d" % (p, _CMS_LIGNES_MAX))
    return ""


def site_bases_carnet() -> dict:
    """Les bases des sites QUE CE COMPTE POSSÈDE, et ce qu'on y reconnaît.

    Le rattachement vient de FastPanel (`db.site`), pas d'une ressemblance de
    noms : deviner « exemple_com_wp appartient à exemple.com » marcherait neuf
    fois sur dix, et la dixième montrerait la base de quelqu'un d'autre.
    """
    qui = get_current_user() or ""
    try:
        toutes = get_fp_databases() or []
    except Exception as e:
        return {"ok": False, "reason": "bases illisibles : %s" % str(e)[:120]}
    if not any(str(d.get("site") or "").strip()
               for d in toutes if isinstance(d, dict)):
        return {"ok": False,
                "reason": "le rattachement des bases aux sites n'est pas lisible "
                          "sur cette machine : je préfère ne rien montrer que "
                          "montrer celles d'un autre"}
    out = []
    for d in toutes:
        if not isinstance(d, dict):
            continue
        dom = _norm_domain(str(d.get("site") or ""))
        nom = str(d.get("name") or d.get("nom") or "").strip()
        if not dom or not nom:
            continue
        # LA MÊME PORTE QUE LES OUTILS DE SITE. Un administrateur voit tout ;
        # un compte ordinaire, ses domaines seulement.
        try:
            if not (is_admin(qui) or user_owns_domain(qui, dom)):
                continue
        except Exception:
            continue
        out.append({"base": nom, "domaine": dom})
    return {"ok": True, "bases": out}


def site_carnet_apercu(base: str) -> dict:
    """Ce qu'on reconnaît dans cette base, SANS rien importer."""
    tables = _cms_tables(base)
    if not tables:
        return {"ok": False, "reason": "base illisible ou vide — vérifiez que "
                                       "MySQL est joignable depuis la machine"}
    info = _cms_reconnaitre(tables)
    if not info:
        # ON N'INVENTE PAS. Mieux vaut montrer les tables et laisser désigner
        # que de parier sur une convention de nommage.
        return {"ok": True, "reconnu": False, "tables": sorted(tables)[:60],
                "message": "aucun logiciel reconnu dans cette base"}
    sql = _cms_requete(info)
    if not sql:
        return {"ok": True, "reconnu": False, "tables": sorted(tables)[:60]}
    lignes = _cms_sql(base, sql, colonnes=5)
    ex = [{"nom": l[0], "adresse": l[1] if len(l) > 1 else ""}
          for l in lignes[:5] if l and len(l) > 1]
    return {"ok": True, "reconnu": True, "cms": info["nom"],
            "prefixe": info.get("prefixe") or "", "trouves": len(lignes),
            "exemples": ex}


def site_carnet_importer(base: str, dossier: str = "", limite: int = 0) -> dict:
    """Verse les gens d'une base de site par la porte commune."""
    tables = _cms_tables(base)
    if not tables:
        return {"ok": False, "reason": "base illisible"}
    info = _cms_reconnaitre(tables)
    sql = _cms_requete(info) if info else ""
    if not sql:
        return {"ok": False, "reason": "aucun logiciel reconnu dans cette base"}
    lignes = _cms_sql(base, sql, colonnes=5)
    if not lignes:
        return {"ok": False, "reason": "aucune personne trouvée"}
    if limite:
        lignes = lignes[:max(1, int(limite))]
    fiches = []
    for l in lignes:
        l = list(l) + [""] * (5 - len(l))
        adr = str(l[1] or "").strip().lower()
        if "@" not in adr:
            continue
        fiches.append({"display_name": (l[0] or "").strip() or adr.split("@")[0],
                       "emails": [adr], "company": (l[2] or "").strip(),
                       "mobile": (l[3] or "").strip(),
                       "job_title": (l[4] or "").strip(),
                       "tags": "site"})
    if not fiches:
        return {"ok": False, "reason": "aucune adresse exploitable"}
    # UN DOSSIER PAR SITE, jamais un fourre-tout « importés » : « Clients
    # boutique.fr » et « Adhérents asso.org » ne se mélangent pas.
    dos = contact_dossier_pour(dossier or ("Contacts %s" % base))
    out = contacts_verser(fiches, source="site", dossier_id=dos)
    if out.get("ok"):
        out["cms"] = info.get("nom", "")
        out["message"] = "%d fiche(s) créée(s), %d existaient déjà, %d complétée(s)" % (
            out.get("crees", 0), out.get("deja", 0), out.get("completees", 0))
    return out


# ══════════════════════════════════════════════════════════════════════════════
#  LA FIN DES CORPS — ce qu'une signature dit d'une personne
#
#  Deux choses ne se trouvent nulle part ailleurs : la maison pour laquelle
#  quelqu'un écrit, et son numéro direct. Elles sont écrites en toutes lettres
#  au bas de chacun de ses messages, et le carnet ne les voyait pas.
# ══════════════════════════════════════════════════════════════════════════════

_MC_LONGUEUR = 1200          # ce qu'on garde de la fin d'un corps
_MC_LOT = 60                 # messages descendus par passage

# Là où commence la citation du message précédent. Tout ce qui suit appartient
# à quelqu'un d'autre : y chercher une signature donnerait celle du
# correspondant, et on écrirait le numéro de la mauvaise personne dans la fiche.
_MC_CITATION = re.compile(
    r"(?im)^\s*(?:>|-{2,}\s*(?:message d'origine|original message|forwarded)|"
    r"le .{0,60}\ba (?:é|e)crit\s*:|on .{0,60}\bwrote\s*:|"
    r"de\s*:\s*.{0,80}\benvoy(?:é|e)\s*:)")


def _mail_corps_fin(texte: str) -> str:
    """La fin du corps, citations retirées.

    On coupe AVANT la première citation, puis on garde la fin de ce qui reste.
    Couper après aurait ramassé la signature du correspondant."""
    t = (texte or "").replace("\r\n", "\n").replace("\r", "\n")
    m = _MC_CITATION.search(t)
    if m:
        t = t[:m.start()]
    t = re.sub(r"\n{3,}", "\n\n", t).strip()
    return t[-_MC_LONGUEUR:] if len(t) > _MC_LONGUEUR else t


def mail_corps_pass(limit: int = _MC_LOT) -> dict:
    """Descend la fin du corps des messages VENANT du carnet, et rien d'autre.

    Le tri se fait sur les fiches connues : descendre tout le courrier pour en
    tirer deux champs coûterait cent fois ce que ça rapporte, et remplirait le
    cache de lettres d'information dont personne ne veut la signature."""
    _mail_cache_migrate()
    _contacts_migrate()
    compte = _mail_account()
    if not compte or compte == "?":
        return {"ok": True, "lus": 0, "raison": "aucune boîte configurée"}
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10); conn.row_factory = sqlite3.Row
        _w, _a = _iso_ou("c")
        # Les messages sans corps, venant d'une adresse du carnet, les plus
        # récents d'abord : ce sont eux dont la signature est à jour.
        rows = conn.execute(
            "SELECT m.folder, m.uid FROM mail_cache m JOIN contact_emails e "
            "ON lower(e.addr) = lower(m.from_addr) JOIN contacts c ON c.id = e.contact_id "
            "WHERE m.account=? AND COALESCE(m.corps,'')='' AND COALESCE(m.corps_at,'')=''"
            + _w + " ORDER BY m.date_iso DESC LIMIT ?",
            [compte] + list(_a) + [int(limit)]).fetchall()
        conn.close()
    except Exception as e:
        return {"ok": False, "reason": str(e), "lus": 0}
    if not rows:
        return {"ok": True, "lus": 0}

    par_dossier = {}
    for r in rows:
        par_dossier.setdefault(r["folder"], []).append(r["uid"])

    # `_email` N'EST PAS GLOBAL dans ce fichier : sans cet import, l'appel
    # plus bas lève un NameError à l'exécution seulement — la compilation ne
    # voit rien, et le défaut attend le premier passage de veille.
    import email as _email
    lus = 0
    for folder, uids in par_dossier.items():
        def _fn(M, _u=uids):
            return M.uid("fetch", ",".join(_u).encode(), "(BODY.PEEK[])")
        rep = _imap_cmd(_fn, folder, readonly=True)
        if isinstance(rep, dict):          # `_imap_cmd` rend un dict sur échec
            logging.info("[CORPS] %s : %s", folder, rep.get("reason"))
            continue
        typ, d = rep
        maj = []
        for item in (d or []):
            if not isinstance(item, tuple) or len(item) < 2:
                continue
            meta = item[0].decode(errors="replace") if isinstance(item[0], bytes) else str(item[0])
            mu = re.search(r"UID (\d+)", meta)
            if not mu:
                continue
            try:
                fin = _mail_corps_fin(_mail_body(_email.message_from_bytes(item[1])))
            except Exception:
                fin = ""
            maj.append((fin, compte, folder, mu.group(1)))
        if not maj:
            continue
        try:
            conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
            # `corps_at` est écrit MÊME quand le corps ressort vide : sans lui,
            # un message illisible serait redescendu à chaque passage, pour
            # rien, indéfiniment.
            conn.executemany("UPDATE mail_cache SET corps=?, corps_at=datetime('now') "
                             "WHERE account=? AND folder=? AND uid=?", maj)
            conn.commit(); conn.close()
            lus += len(maj)
        except Exception as e:
            logging.info("[CORPS] écriture : %s", e)
    return {"ok": True, "lus": lus}


# ── CE QU'ON LIT DANS UNE FIN DE MESSAGE ──────────────────────────────────────
# Un numéro français, ou international. On exige des séparateurs cohérents :
# « 07 81 41 28 12 » est un numéro, « 20260817120000 » ne l'est pas.
_MC_TEL = re.compile(
    r"(?:(?<![\w.])(?:\+33|0033)\s?[1-9](?:[\s.\-]?\d{2}){4}(?![\w])"
    r"|(?<![\w.])0[1-9](?:[\s.\-]?\d{2}){4}(?![\w])"
    r"|(?<![\w.])\+\d{1,3}[\s.\-]?\d[\d\s.\-]{7,14}\d(?![\w]))")
# Les mentions qui désignent une maison plutôt qu'une personne.
_MC_MAISON = ("sarl", "sas", "sasu", "eurl", "sci", "scop", "snc", "gmbh", "ltd",
              "limited", "inc", "llc", "srl", "spa", "& fils", "et fils",
              "& associés", "et associés", "& cie", "et cie", "& co")


def _mc_tel_norme(t: str) -> str:
    """Les neuf derniers chiffres : c'est ce qui identifie un numéro quelle que
    soit sa présentation. « +33 7 81 41 28 12 » et « 07 81 41 28 12 » sont le
    même appareil, et les compter séparément ferait croire à deux numéros."""
    d = re.sub(r"\D", "", t or "")
    return d[-9:] if len(d) >= 9 else ""


def _mc_signaux(cid, fiche: dict) -> dict:
    """Numéro et maison lus dans les fins de messages de cette personne.

    LE SEUIL EST DE DEUX MESSAGES. Une occurrence unique peut être n'importe
    quoi — le numéro d'un tiers recopié, le nom d'un client cité en passant.
    Deux occurrences dans deux messages différents, c'est une signature."""
    out = {"tel": "", "tel_n": 0, "societe": "", "societe_n": 0}
    adrs = [a for a in (fiche.get("emails") or []) if a]
    if not adrs:
        return out
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        marks = ",".join("?" * len(adrs))
        fins = [x[0] for x in conn.execute(
            "SELECT corps FROM mail_cache WHERE account=? AND lower(from_addr) IN (%s) "
            "AND COALESCE(corps,'')<>'' ORDER BY date_iso DESC LIMIT 12" % marks,
            [_mail_account()] + [a.lower() for a in adrs])]
        conn.close()
    except Exception as e:
        logging.info("[SIGNAUX] lecture : %s", e)
        return out
    if len(fins) < 2:
        return out

    # ── LE NUMÉRO ────────────────────────────────────────────────────────
    vus, brut = {}, {}
    for f in fins:
        pour_ce_message = set()
        for m in _MC_TEL.finditer(f or ""):
            n = _mc_tel_norme(m.group(0))
            if n and n not in pour_ce_message:
                pour_ce_message.add(n)
                vus[n] = vus.get(n, 0) + 1
                brut.setdefault(n, m.group(0).strip())
    for n, c in sorted(vus.items(), key=lambda kv: -kv[1]):
        if c >= 2:
            out["tel"], out["tel_n"] = brut[n], c
            break

    # ── LA MAISON ────────────────────────────────────────────────────────
    # Une ligne courte, répétée d'un message à l'autre, qui n'est ni une
    # adresse ni une URL — et qui porte une forme juridique, OU qui reprend la
    # racine du domaine d'où la personne écrit. Le second cas est un relevé,
    # pas une intuition : « Leroy & Fils » et « @leroy.fr » se répondent.
    racine = ""
    d = _addr_domain(adrs[0])
    if d:
        racine = d.split(".")[0].strip().lower()
    lignes = {}
    for f in fins:
        pour_ce_message = set()
        for ligne in (f or "").split("\n"):
            l = ligne.strip(" \t-–—*·|")
            if not (3 <= len(l) <= 60) or "@" in l or "http" in l.lower():
                continue
            if _MC_TEL.search(l) or re.search(r"\d{4}", l):
                continue
            bas = l.lower()
            if bas == (fiche.get("display_name") or "").strip().lower():
                continue
            porte = any(k in bas for k in _MC_MAISON) or \
                (len(racine) >= 4 and racine in re.sub(r"[^a-z0-9]", "", bas))
            if porte and l not in pour_ce_message:
                pour_ce_message.add(l)
                lignes[l] = lignes.get(l, 0) + 1
    for l, c in sorted(lignes.items(), key=lambda kv: (-kv[1], -len(kv[0]))):
        if c >= 2:
            out["societe"], out["societe_n"] = l, c
            break
    return out


def contact_propositions(cid) -> dict:
    """Ce qu'Itare tire d'UNE fiche, sans rien écrire.

    Chaque ligne porte de quoi être vérifiée d'un coup d'œil, et une action que
    la personne déclenche. C'est le contrat déjà tenu par l'autoliaison : on
    n'écrit que sur une certitude, et tout le ressemblant se propose.

    La lecture est bornée par le cloisonnement de `contact_get` : une fiche
    qu'on n'a pas le droit de lire n'a pas de propositions.
    """
    _contacts_migrate()
    _contact_links_migrate()
    d = contact_get(cid)
    if not d.get("ok"):
        return {"ok": False, "reason": d.get("reason") or "fiche introuvable"}
    c = d["contact"]
    out = []
    adrs = [a for a in (c.get("emails") or []) if a]
    doms = {_addr_domain(a) for a in adrs}
    doms.discard("")
    liens = {(l.get("kind"), str(l.get("ref"))) for l in (c.get("links") or [])}
    # Ce que disent les fins de ses messages. Lecture de base seule : le
    # passage qui les descend tourne dans la veille, jamais ici.
    sig = _mc_signaux(c["id"], c)

    # ── ① UNE SECONDE FICHE PORTE LE MÊME NOM ────────────────────────────
    # On réemploie la détection de l'onglet Doublons : deux mesures pour la
    # même chose finiraient par se contredire, et c'est l'écran qui aurait
    # l'air de mentir.
    # `contact_duplicates` range ses paires SOUS « paires », et une paire porte
    # deux IDENTIFIANTS avec leurs noms a cote — pas deux fiches. Les lire comme
    # des objets aurait rendu « (sans nom) » sur toutes les lignes, sans erreur.
    try:
        paires = (contact_duplicates().get("paires") or {})
        trouve = False
        for niv in ("sur", "probable", "possible"):
            for paire in (paires.get(niv) or []):
                noms = paire.get("noms") or ["", ""]
                if paire.get("a") == c["id"]:
                    aid, anom = paire.get("b"), noms[1]
                elif paire.get("b") == c["id"]:
                    aid, anom = paire.get("a"), noms[0]
                else:
                    continue
                out.append({
                    "cle": "doublon", "ic": "\U0001F500",
                    "txt": "Une seconde fiche lui ressemble : <b>%s</b> — %s"
                           % (_html.escape(anom or "(sans nom)"),
                              _html.escape(paire.get("motif") or "")),
                    "niv": niv, "act": "doublon", "arg": str(aid or ""),
                    "bouton": "Comparer"})
                trouve = True
                break
            if trouve:
                break
    except Exception as e:
        logging.info("[PROPOSITIONS] doublons : %s", e)

    # ── ② UN ANNIVERSAIRE SANS RAPPEL ────────────────────────────────────
    # Une date notée et jamais rappelée ne sert à rien : on s'en souvient le
    # lendemain, tous les ans.
    anniv = (c.get("anniversaire") or "").strip()
    if anniv:
        nom = c.get("display_name") or ""
        deja = False
        try:
            for rp in (itare_reminder_list(include_done=True) or []):
                if nom and nom.lower() in (rp.get("text") or "").lower():
                    deja = True
                    break
        except Exception:
            pass
        if not deja:
            out.append({"cle": "anniv", "ic": "\U0001F382",
                        "txt": "Anniversaire le <b>%s</b>, et aucun rappel ne le "
                               "porte" % _html.escape(anniv),
                        "act": "anniv", "arg": anniv, "bouton": "Poser un rappel"})

    # ── ③ UNE SOCIÉTÉ QUE D'AUTRES FICHES PORTENT DÉJÀ ───────────────────
    # Le domaine de l'adresse est le même, et les voisines nomment toutes la
    # même maison. Ce n'est pas une intuition, c'est un relevé.
    if not (c.get("company") or "").strip() and doms:
        try:
            conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
            _w, _a = _iso_ou("c")
            noms = {}
            for dom in doms:
                for row in conn.execute(
                        "SELECT c.company FROM contacts c JOIN contact_emails e "
                        "ON e.contact_id = c.id WHERE c.id<>? AND e.addr LIKE ? "
                        "AND COALESCE(c.company,'')<>''" + _w,
                        [int(c["id"]), "%@" + dom] + list(_a)):
                    v = (row[0] or "").strip()
                    if v:
                        noms[v] = noms.get(v, 0) + 1
            conn.close()
            if noms:
                meilleur = max(noms.items(), key=lambda kv: kv[1])
                if meilleur[1] >= 1:
                    out.append({
                        "cle": "societe", "ic": "\U0001F3E2",
                        "txt": "%d autre(s) fiche(s) du même domaine nomment "
                               "<b>%s</b> — renseigner la société ?"
                               % (meilleur[1], _html.escape(meilleur[0])),
                        "act": "societe", "arg": meilleur[0],
                        "bouton": "Renseigner"})
            elif sig.get("societe"):
                # LA SIGNATURE, QUAND LE VOISINAGE NE DIT RIEN. Une seule
                # proposition par champ : deux lignes concurrentes sur la même
                # case obligeraient à choisir entre deux inconnues.
                out.append({
                    "cle": "societe", "ic": "\U0001F3E2",
                    "txt": "Sa signature dit <b>%s</b>, dans %d de ses messages "
                           "— renseigner la société ?"
                           % (_html.escape(sig["societe"]), sig["societe_n"]),
                    "act": "societe", "arg": sig["societe"],
                    "bouton": "Renseigner"})
        except Exception as e:
            logging.info("[PROPOSITIONS] societe : %s", e)

    # ── ③ bis UN NUMÉRO QU'ELLE SIGNE ET QUE LA FICHE N'A PAS ────────────
    # Le seuil de deux messages n'est pas de la prudence décorative : dans un
    # seul message, un numéro peut être celui d'un tiers, un numéro de commande
    # ou une référence. Répété d'une signature à l'autre, c'est le sien.
    if sig.get("tel") and not (c.get("phone") or "").strip() \
            and not (c.get("mobile") or "").strip():
        out.append({"cle": "tel", "ic": "\U0001F4DE",
                    "txt": "Un numéro revient dans <b>%d</b> de ses messages : "
                           "<b>%s</b>" % (sig["tel_n"], _html.escape(sig["tel"])),
                    "act": "tel", "arg": sig["tel"], "bouton": "Reprendre"})

    # ── ④ UN DOMAINE DU COMPTE, PAS ENCORE RATTACHÉ ──────────────────────
    # La personne écrit depuis un domaine que ce compte administre. Le lien ne
    # s'écrit pas tout seul — un salarié n'est pas le contact technique — mais
    # la question mérite d'être posée.
    try:
        mes = {(_norm_domain(s.get("domain") or ""))
               for s in (_user_sites_overview(get_current_user()).get("sites") or [])}
        for dom in sorted(doms):
            nd = _norm_domain(dom)
            if nd and nd in mes and ("domain", nd) not in liens:
                out.append({"cle": "domaine", "ic": "\U0001F310",
                            "txt": "Elle écrit depuis <b>%s</b>, un site de ce "
                                   "compte, et n'y est pas rattachée" % _html.escape(nd),
                            "act": "lier", "arg": "domain\t" + nd + "\t" + nd,
                            "bouton": "Rattacher"})
                break
    except Exception as e:
        logging.info("[PROPOSITIONS] domaine : %s", e)

    # ── ⑤ UN PROJET PRESSENTI, JAMAIS ÉCRIT ──────────────────────────────
    # Même règle que le quatrième temps de l'autoliaison : le nom évoque le
    # projet sans coïncider. Un humain tranche d'un coup d'œil, une machine
    # n'en a pas le droit.
    try:
        societe = (c.get("company") or "").strip().lower()
        adom = " ".join(adrs)
        for p in (pj_projets() or []):
            if p.get("archived") or ("project", str(p["id"])) in liens:
                continue
            nom = (p.get("name") or "").strip().lower()
            pdom = _norm_domain(p.get("domain") or "")
            racine = (pdom.split(".")[0] if pdom else nom).strip()
            if len(racine) < 4:
                continue
            if (racine in societe) or (nom and societe and nom in societe) or \
               (racine in _addr_domain(adom) and
                    not _domains_match(_addr_domain(adom), pdom)):
                out.append({
                    "cle": "projet", "ic": "\U0001F5C2",
                    "txt": "Son nom évoque le projet <b>%s</b> sans coïncider "
                           "exactement" % _html.escape(p.get("name") or ""),
                    "act": "lier",
                    "arg": "project\t%s\t%s" % (p["id"], p.get("name") or ""),
                    "bouton": "Rattacher"})
                break
    except Exception as e:
        logging.info("[PROPOSITIONS] projet pressenti : %s", e)

    # ── ⑥ UN SILENCE SUR UN PROJET ACTIF ─────────────────────────────────
    # `contact_stale_pass` fait déjà ce calcul, mais pour tout le carnet et vers
    # le fil de proactivité. Ici, c'est la fiche qu'on regarde.
    try:
        jours = 21
        limite = (_utcnow() - timedelta(days=jours)).strftime("%Y-%m-%d %H:%M:%S")
        vu = (c.get("last_seen") or "")
        if (not vu) or vu < limite:
            for l in (c.get("links") or []):
                if l.get("kind") != "project":
                    continue
                out.append({
                    "cle": "silence", "ic": "\u23F0",
                    "txt": "Projet <b>%s</b> toujours actif, et %s"
                           % (_html.escape(l.get("label") or l.get("ref") or ""),
                              ("dernier message le %s" % _html.escape(vu[:10])) if vu
                              else "aucun message enregistré"),
                    "act": "relance",
                    "arg": (c.get("display_name") or "") + "\t"
                           + (l.get("label") or l.get("ref") or ""),
                    "bouton": "Poser une relance"})
                break
    except Exception as e:
        logging.info("[PROPOSITIONS] silence : %s", e)

    return {"ok": True, "propositions": out}


def contact_stale_pass(jours: int = 21) -> dict:
    """Projets actifs dont le contact principal n'a plus donné signe de vie.

    Même logique que les crons muets : ce qui ne se produit pas ne déclenche
    rien tout seul. Un projet en cours sans échange depuis trois semaines
    mérite au moins une question."""
    if not _mem_cfg("contact_relance_enabled", True):
        return {"ok": True, "disabled": True, "stale": 0}
    _contact_links_migrate()
    _mail_cache_migrate()
    limite = (_utcnow() - timedelta(days=int(jours))).strftime("%Y-%m-%d %H:%M:%S")
    signales, crees = 0, 0
    try:
        projets = [p for p in (pj_projets() or []) if not p.get("archived")]
    except Exception as e:
        return {"ok": False, "reason": str(e)}
    for p in projets:
        gens = contacts_of("project", str(p["id"]))
        if not gens:
            continue
        principal = gens[0]
        dernier = principal.get("last_seen") or ""
        if dernier and dernier >= limite:
            continue
        cle = "relance:%s:%s:%s" % (p["id"], principal["id"], dernier[:10] or "jamais")
        if _cron_seen(cle):
            continue
        signales += 1
        nom = principal.get("display_name") or "ce contact"
        depuis = ("dernier message le %s" % dernier[:10]) if dernier else "aucun message enregistré"
        try:
            _itare_proactive_add(
                "Projet « %s » : silence côté %s" % (p.get("name"), nom),
                "%s — %s. Le projet est toujours actif." % (nom, depuis),
                source="projet", nature="evenement", sujet="projet:%s" % p["id"],
                cle="projet:silence:%s:%s" % (p["id"], nom))
            r = itare_task_from_source("auto-relance", cle,
                                       "Relancer %s au sujet de « %s »" % (nom, p.get("name")),
                                       project_id=p["id"])
            if r.get("created"):
                crees += 1
        except Exception as e:
            logging.info("[RELANCE] %s", e)
    return {"ok": True, "stale": signales, "created": crees}


def mail_contacts_sync(limit: int = 300) -> dict:
    """Le carnet apprend du courrier — PAR LA PORTE (LOT 6, B59). Une adresse déjà rattachée ne fait que
    mettre à jour ses compteurs (reçus, dernier) ; une adresse inconnue et humaine devient une fiche
    « courrier » par `contacts_verser`, avec le même dédoublonnage que tout import. Plus d'INSERT direct,
    plus de table `mail_contacts` : ses colonnes vivent sur `contact_emails`. Tourne PAR COMPTE, dans la
    passe du courrier (le compte et la boîte sont sur le fil)."""
    _mail_cache_migrate()
    _contacts_migrate()
    compte = _mail_account()
    qui = _iso_moi()
    if not qui or compte == "?":
        return {"ok": False, "reason": "aucun compte sur le fil : la synchronisation se fait par compte"}
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10); conn.row_factory = sqlite3.Row
        _iso_migrer(conn)
        rows = conn.execute(
            "SELECT c.from_addr, c.from_name, c.date_iso AS vu, g.n FROM mail_cache c "
            "JOIN (SELECT from_addr, COUNT(*) AS n, MAX(date_iso) AS dernier "
            "      FROM mail_cache WHERE account=? AND from_addr<>'' GROUP BY from_addr) g "
            "  ON g.from_addr = c.from_addr AND g.dernier = c.date_iso "
            "WHERE c.account=? GROUP BY c.from_addr ORDER BY g.n DESC LIMIT ?",
            (compte, compte, int(limit))).fetchall()
        maj, ignores, a_creer, stats = 0, 0, [], {}
        for r in rows:
            adr = (r["from_addr"] or "").strip().lower()
            if not adr:
                continue
            stats[adr] = (int(r["n"] or 0), r["vu"] or "")
            if _contact_addr_owner(conn, adr):
                conn.execute("UPDATE contact_emails SET received=?, last_seen=? WHERE addr=?",
                             (int(r["n"] or 0), r["vu"] or "", adr))
                maj += 1
                continue
            if mail_is_technical({"from_addr": adr, "subject": ""}) or _MAIL_NOREPLY.search(adr):
                ignores += 1
                continue
            a_creer.append({"display_name": (r["from_name"] or adr.split("@")[0])[:120], "emails": [adr]})
        conn.commit(); conn.close()
        crees = 0
        if a_creer:
            v = contacts_verser(a_creer, source="courrier", completer=False, compte=qui)
            crees = int(v.get("crees") or 0)
            try:
                conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
                for f in a_creer:
                    adr = f["emails"][0]
                    n, vu = stats.get(adr, (0, ""))
                    conn.execute("UPDATE contact_emails SET received=?, last_seen=? WHERE addr=?", (n, vu, adr))
                conn.commit(); conn.close()
            except Exception as e:
                logging.info("[CARNET] compteurs du courrier : %s", e)
        return {"ok": True, "contacts": len(rows), "created": crees, "skipped": ignores, "maj": maj}
    except Exception as e:
        return {"ok": False, "reason": str(e)}


def contact_merge(src_id, dst_id, compte: str = None) -> dict:
    """Fusionne deux fiches : `src` est absorbée par `dst`, puis supprimée.

    Les adresses, les liens et les champs vides de la destination sont repris —
    une fusion qui perdrait le téléphone saisi sur l'une des deux ferait plus de
    dégâts que les doublons qu'elle corrige."""
    _contacts_migrate()
    _contact_links_migrate()
    try:
        s, d = int(src_id), int(dst_id)
    except Exception:
        return {"ok": False, "reason": "identifiants invalides"}
    if s == d:
        return {"ok": False, "reason": "une fiche ne se fusionne pas avec elle-même"}
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10); conn.row_factory = sqlite3.Row
        a = conn.execute("SELECT * FROM contacts WHERE id=?", (s,)).fetchone()
        b = conn.execute("SELECT * FROM contacts WHERE id=?", (d,)).fetchone()
        if not a or not b:
            conn.close(); return {"ok": False, "reason": "fiche introuvable"}
        # LES DEUX FICHES SONT AU COMPTE QUI FUSIONNE : sans cela, la route ouverte aux comptes
        # laissait absorber la fiche d'un autre (Cassandra, #1673).
        compte = (compte or "").strip().lower() or _iso_moi()
        cols_a = a.keys()
        if "compte" in cols_a and not (_ct_meme_compte(a["compte"], compte) and _ct_meme_compte(b["compte"], compte)):
            conn.close(); return {"ok": False, "reason": "fiche introuvable"}
        # Champs vides de la destination complétés par la source, jamais l'inverse.
        # Un nom fabriqué à partir de l'adresse (« p.durand ») compte comme vide :
        # c'est un bouche-trou, il ne doit pas l'emporter sur un vrai nom.
        adr_b = [x[0] for x in conn.execute(
            "SELECT addr FROM contact_emails WHERE contact_id=?", (d,))]
        locaux = {x.split("@")[0].lower() for x in adr_b}
        maj = {}
        # TOUTES LES COLONNES, pas huit : la fusion perdait photo, coffre, anniversaire,
        # dossier et étiquettes de la fiche absorbée (B1b, simulé par Cassandra sur copie).
        cols_b = {x[1] for x in conn.execute("PRAGMA table_info(contacts)")}
        for col in ("display_name", "company", "job_title", "phone", "mobile",
                    "address", "website", "anniversaire", "vault_ref", "photo", "photo_src",
                    "dossier_id"):
            if col not in cols_b:
                continue
            vb, va = b[col], a[col]
            vide = not str(vb or "").strip() if not isinstance(vb, int) else not vb
            if col == "display_name" and not vide:
                vide = str(vb or "").strip().lower() in locaux
            if vide and (str(va or "").strip() if not isinstance(va, int) else va):
                maj[col] = va
        # Les étiquettes s'unissent, elles ne se remplacent pas.
        et = [t.strip() for t in str(b["tags"] or "").split(",") if t.strip()]
        for t in [t.strip() for t in str(a["tags"] or "").split(",") if t.strip()]:
            if t.lower() not in [x.lower() for x in et]:
                et.append(t)
        if ", ".join(et) != str(b["tags"] or ""):
            maj["tags"] = ", ".join(et)[:200]
        notes = "\n\n".join(x for x in [(b["notes"] or "").strip(), (a["notes"] or "").strip()] if x)
        if notes != (b["notes"] or ""):
            maj["notes"] = notes[:4000]
        if a["favorite"] and not b["favorite"]:
            maj["favorite"] = 1
        if maj:
            conn.execute("UPDATE contacts SET %s, updated_at=datetime('now') WHERE id=?"
                         % ", ".join("%s=?" % k for k in maj), list(maj.values()) + [d])
        conn.execute("UPDATE OR IGNORE contact_emails SET contact_id=?, is_primary=0 "
                     "WHERE contact_id=?", (d, s))
        conn.execute("DELETE FROM contact_emails WHERE contact_id=?", (s,))
        conn.execute("UPDATE OR IGNORE contact_links SET contact_id=? WHERE contact_id=?", (d, s))
        conn.execute("DELETE FROM contact_links WHERE contact_id=?", (s,))
        # TOUT CE QUI POINTAIT LA FICHE ABSORBÉE pointe la gardée : envois de mandat,
        # personnes de projet, rattachements par (kind='contact', ref=id). Une table
        # absente n'est pas une erreur.
        for _t, _col in (("mandat_envois", "contact_id"),):
            try:
                conn.execute("UPDATE %s SET %s=? WHERE %s=?" % (_t, _col, _col), (d, s))
            except Exception:
                pass
        for _t in ("itare_task_links", "itare_event_links", "itare_project_links", "ged_liens"):
            try:
                conn.execute("UPDATE OR IGNORE %s SET ref=? WHERE kind='contact' AND ref=?" % _t,
                             (str(d), str(s)))
                conn.execute("DELETE FROM %s WHERE kind='contact' AND ref=?" % _t, (str(s),))
            except Exception:
                pass
        try:
            conn.execute("DELETE FROM contact_pas_doublons WHERE a=? OR b=?", (s, s))
        except Exception:
            pass
        # LA SOURCE PART À LA CORBEILLE, elle n'est plus détruite. Une fusion
        # malheureuse se défait pendant trente jours — et c'est ce qui rend la
        # détection de doublons utilisable : on peut trancher sans craindre
        # l'irréparable. `fusion_vers` retient ce qui l'a absorbée, pour que la
        # restauration dise qu'elle recréerait le doublon.
        # LOT 6 : le portrait suit la fusion — celui de la destination est reposé, celui de
        # l'absorbée effacé.
        try:
            _pm = conn.execute("SELECT COALESCE(photo,''), COALESCE(NULLIF(photo_src,''),'fiche'), "
                               "COALESCE(compte,'') FROM contacts WHERE id=?", (d,)).fetchone()
            _portraits_migrer(conn)
            conn.execute("DELETE FROM portraits WHERE cle=?", ("contact:%d" % s,))
            if _pm and _pm[0]:
                conn.execute("INSERT OR REPLACE INTO portraits (compte, cle, photo, source, maj) "
                             "VALUES (?,?,?,?,datetime('now'))", (_pm[2], "contact:%d" % d, _pm[0], _pm[1]))
        except Exception as e:
            logging.info("[PORTRAITS] fusion : %s", e)
        conn.execute("UPDATE contacts SET supprime_at=datetime('now'), fusion_vers=?, "
                     "updated_at=datetime('now') WHERE id=?", (d, s))
        conn.commit(); conn.close()
        return {"ok": True, "id": d, "corbeille": s, "jours": _CT_CORBEILLE_JOURS}
    except Exception as e:
        return {"ok": False, "reason": str(e)}


# ══════════════════════════════════════════════════════════════════════════════
#  LES DOUBLONS, PAR DEGRÉ DE CERTITUDE
#
#  Une seule pile où tout se vaut oblige à examiner un doublon évident avec la
#  même attention qu'une homonymie douteuse — et on finit par ne plus rien
#  examiner du tout.
#
#    CERTAIN   une adresse partagée. Elle ne peut pas appartenir à deux
#              personnes ; c'est le seul degré qu'on accepte de fusionner en lot.
#    PROBABLE  le nom concorde ET un second signal — téléphone, société, site.
#              Deux signaux qui tombent juste par hasard, c'est rare.
#    POSSIBLE  un seul signal faible. « p.durand » chez deux employeurs, ou
#              « Martin » deux fois : le plus souvent des homonymes.
#
#  Chaque paire porte les signaux qui l'ont déclenchée, MOT POUR MOT. « même
#  nom » ne dit pas si c'est le nom brut ou le nom normalisé qui coïncide, et
#  c'est toute la différence entre une certitude et une coïncidence.
# ══════════════════════════════════════════════════════════════════════════════

# Les formes juridiques et suffixes commerciaux : « Atelier Beaumont » et
# « Atelier Beaumont SARL » sont la même maison.
_CT_FORMES = ("sarl", "sas", "sasu", "sa", "eurl", "sci", "scop", "scic", "snc",
              "gmbh", "ltd", "limited", "inc", "llc", "bv", "srl", "spa", "ag",
              "et fils", "and sons", "et cie", "and co", "group", "groupe")
# En deçà, une partie locale d'adresse ne dit rien : « rh », « info », « dev »
# se retrouvent chez la moitié des domaines.
_CT_LOCAL_MIN = 4
# Les parties locales génériques ne désignent personne, quelle que soit leur
# longueur : deux « contact@ » chez deux sociétés ne sont pas la même personne.
_CT_LOCAL_VIDES = ("contact", "info", "bonjour", "hello", "accueil", "secretariat",
                   "secretaire", "admin", "administration", "compta", "comptabilite",
                   "facture", "factures", "commande", "commandes", "service",
                   "support", "sav", "direction", "commercial", "commerciaux",
                   "noreply", "no-reply", "nepasrepondre", "postmaster", "webmaster",
                   "rh", "recrutement", "devis", "client", "clients")


def _ct_pla(s: str) -> str:
    """Une chaîne aplatie : sans accents, sans casse, sans ponctuation."""
    t = unicodedata.normalize("NFD", str(s or ""))
    t = "".join(c for c in t if unicodedata.category(c) != "Mn").lower()
    return " ".join(re.sub(r"[^a-z0-9]+", " ", t).split())


def _ct_norm_nom(s: str) -> str:
    """Le nom, comparable : aplati, et débarrassé de sa forme juridique.

    UN NOM SANS AUCUNE LETTRE garde une signature de ses symboles : « 🚫🚫🚫 » s'aplatissait
    en rien, le signal « nom » n'existait pas, et deux fiches portant le MÊME nom d'émojis
    passaient pour deux noms différents — rangées en « piège » (même numéro, noms
    différents), avec un motif qui mentait, au lieu de jumelles d'import (D7)."""
    t = _ct_pla(s)
    if not t:
        brut = " ".join(str(s or "").split())
        return ("sym:" + brut.lower()) if brut else ""
    for f in _CT_FORMES:
        t = re.sub(r"(^|\s)%s(\s|$)" % re.escape(f), " ", t)
    return " ".join(t.split())


def _ct_initiales(a: str, b: str) -> bool:
    """« J. Danet » est-il la forme abrégée de « Julie Danet » ?

    On exige que le DERNIER mot soit identique et que les précédents se
    correspondent lettre à lettre. Sans l'égalité du dernier mot, « J. Danet »
    et « Jean Dupont » se ressembleraient — ils n'ont que l'initiale en commun.
    """
    x, y = _ct_norm_nom(a).split(), _ct_norm_nom(b).split()
    if len(x) < 2 or len(y) < 2 or len(x) != len(y):
        return False
    if x[-1] != y[-1]:
        return False
    abrege = False
    for m, n in zip(x[:-1], y[:-1]):
        if m == n:
            continue
        if len(m) == 1 and n.startswith(m):
            abrege = True
            continue
        if len(n) == 1 and m.startswith(n):
            abrege = True
            continue
        return False
    return abrege


def _ct_norm_tel(s: str) -> str:
    """Un numéro comparable : les neuf derniers chiffres.

    « 06 88 41 22 09 », « +33 6 88 41 22 09 » et « 0033688412209 » sont le même
    numéro. Comparer les chaînes brutes en aurait fait trois.
    """
    d = re.sub(r"\D", "", str(s or ""))
    return d[-9:] if len(d) >= 9 else ""


def _ct_norm_site(s: str) -> str:
    """Le domaine d'un site, sans protocole ni « www »."""
    t = str(s or "").strip().lower()
    t = re.sub(r"^[a-z]+://", "", t).split("/")[0]
    t = re.sub(r"^www\.", "", t)
    return t if "." in t else ""


def _ct_paires_ecartees() -> set:
    """Les paires que l'on a déclarées « pas la même personne »."""
    conn = None
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        _iso_migrer(conn)
        _c, _a = _iso_ou()
        return {(int(x[0]), int(x[1])) for x in conn.execute(
            "SELECT a, b FROM contact_pas_doublons WHERE 1=1" + _c, list(_a))}
    except Exception as e:
        logging.info("[CARNET] paires écartées : %s", e)
        return set()
    finally:
        if conn:
            try:
                conn.close()
            except Exception:
                pass


def contact_pas_doublon(a, b, annuler: bool = False) -> dict:
    """Retient que ces deux fiches ne sont PAS la même personne.

    Sans cette mémoire, les mêmes faux doublons remontent chaque semaine et on
    cesse de regarder la pastille — ce qui revient à n'avoir pas de détection
    du tout. La paire est rangée triée : écarter (7,3) écarte aussi (3,7).
    """
    try:
        x, y = sorted((int(a), int(b)))
    except Exception:
        return {"ok": False, "reason": "identifiants invalides"}
    if x == y:
        return {"ok": False, "reason": "une fiche n'est pas son propre doublon"}
    _contacts_migrate()
    conn = None
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        if annuler:
            conn.execute("DELETE FROM contact_pas_doublons WHERE a=? AND b=?", (x, y))
        else:
            conn.execute("INSERT OR IGNORE INTO contact_pas_doublons (compte, a, b) "
                         "VALUES (?,?,?)", (get_current_user() or "", x, y))
        conn.commit()
    except Exception as e:
        return {"ok": False, "reason": str(e)[:160]}
    finally:
        if conn:
            try:
                conn.close()
            except Exception:
                pass
    return {"ok": True, "paire": [x, y], "ecartee": not annuler}


def _ct_signaux(fiches: list) -> dict:
    """Tous les rapprochements, paire par paire, avec ce qui les motive.

    On passe par des SEAUX plutôt que de comparer chacun à chacun : mille
    fiches feraient un demi-million de comparaisons, et l'écran attendrait.
    Un seau par signal, et seules les fiches qui tombent dans le même seau se
    comparent.
    """
    seaux = {}

    def _poser(cle, valeur, fid, dit):
        if valeur:
            seaux.setdefault((cle, valeur), []).append((fid, dit))

    for c in fiches:
        fid = c.get("id")
        if not fid:
            continue
        for a in (c.get("emails") or []):
            a = str(a or "").strip().lower()
            if not a:
                continue
            _poser("adresse", a, fid, "%s des deux côtés" % a)
            loc = a.split("@")[0]
            if len(loc) >= _CT_LOCAL_MIN and loc not in _CT_LOCAL_VIDES:
                _poser("local", loc, fid, "« %s » chez deux domaines" % loc)
        nom = _ct_norm_nom(c.get("display_name"))
        if nom:
            _poser("nom", nom, fid, "« %s » une fois le nom normalisé" % nom)
        tel = _ct_norm_tel(c.get("phone")) or _ct_norm_tel(c.get("mobile"))
        if tel:
            _poser("tel", tel, fid, "même numéro, …%s" % tel[-4:])
        soc = _ct_norm_nom(c.get("company"))
        if soc:
            _poser("societe", soc, fid, "même société : « %s »" % soc)
        site = _ct_norm_site(c.get("website"))
        if site:
            _poser("site", site, fid, "même site : %s" % site)

    paires = {}
    for (cle, _v), lot in seaux.items():
        if len(lot) < 2:
            continue
        # UN SEAU TROP PLEIN NE DIT PLUS RIEN. Trente fiches partageant un même
        # « nom » sont un nom de famille répandu, pas trente doublons — et les
        # apparier deux à deux ferait 435 fausses paires.
        if len(lot) > 8:
            continue
        for i in range(len(lot)):
            for j in range(i + 1, len(lot)):
                a, b = sorted((lot[i][0], lot[j][0]))
                if a == b:
                    continue
                paires.setdefault((a, b), {})[cle] = lot[i][1]
    return paires


def contact_duplicates() -> dict:
    """Fiches vraisemblablement identiques, rangées par degré de certitude.

    Proposé, JAMAIS fusionné d'office : deux homonymes existent, et le seul
    degré qu'on accepte de traiter en lot est celui de l'adresse partagée.
    """
    _contacts_migrate()
    r = contact_list(limit=1000)
    if not r.get("ok"):
        return r
    par_id = {c["id"]: c for c in r["contacts"] if c.get("id")}
    ecartees = _ct_paires_ecartees()
    out = {"jumelles": [], "sur": [], "probable": [], "possible": [], "piege": []}

    for (a, b), sig in _ct_signaux(list(par_id.values())).items():
        if (a, b) in ecartees:
            continue
        nom_ok = "nom" in sig
        # L'abréviation ne se voit pas au seau : deux orthographes différentes
        # tombent dans deux seaux. On la teste sur les paires DÉJÀ rapprochées
        # par un autre signal — c'est ce qui fait remonter « J. Danet » face à
        # « Julie Danet » quand elles partagent un téléphone.
        if not nom_ok and _ct_initiales(par_id[a].get("display_name"),
                                        par_id[b].get("display_name")):
            nom_ok = True
            sig["nom"] = "« %s » une fois les initiales développées" % _ct_norm_nom(
                par_id[b].get("display_name"))
        appuis = [k for k in ("tel", "societe", "site") if k in sig]
        if "adresse" in sig:
            niv = "sur"
        elif _ct_jumelles(par_id[a], par_id[b], sig):
            # JUMELLES D'IMPORT : même nom normalisé, même numéro, même source, même
            # compte, nées à la même minute — la même passe les a écrites deux fois
            # (B2). Elles se fusionnent en lot sans rien perdre : elles sont
            # identiques ligne à ligne.
            niv = "jumelles"
        elif not nom_ok and "tel" in sig:
            # LOT 6 (tour 16) : un même numéro sous des noms différents — famille, pro, numéro
            # recyclé. À MONTRER, jamais à fusionner en lot.
            niv = "piege"
        elif nom_ok and appuis:
            niv = "probable"
        else:
            niv = "possible"
        out[niv].append({
            "niveau": niv, "a": a, "b": b,
            "noms": [par_id[a].get("display_name") or "(sans nom)",
                     par_id[b].get("display_name") or "(sans nom)"],
            "sources": [par_id[a].get("source") or "", par_id[b].get("source") or ""],
            "signaux": [sig[k] for k in ("adresse", "nom", "tel", "societe", "site", "local")
                        if k in sig],
            "motif": {"sur": "adresse identique",
                      "jumelles": "jumelles d'import : même nom, même numéro, nées ensemble",
                      "piege": "même numéro, noms différents : famille, pro ou numéro recyclé",
                      "probable": "nom + " + " + ".join(
                          {"tel": "téléphone", "societe": "société",
                           "site": "site"}[k] for k in appuis),
                      "possible": "nom seul" if nom_ok else "même identifiant d'adresse"}[niv],
            "garder": _ct_meilleure(par_id[a], par_id[b])})

    total = sum(len(v) for v in out.values())
    return {"ok": True, "paires": out, "total": total, "examinees": len(par_id),
            "ecartees": len(ecartees),
            # L'ancienne forme, pour que rien de ce qui l'appelait ne tombe.
            "duplicates": [{"reason": p["motif"], "key": " / ".join(p["noms"]),
                            "contacts": [{"id": p["a"], "name": p["noms"][0],
                                          "source": p["sources"][0]},
                                         {"id": p["b"], "name": p["noms"][1],
                                          "source": p["sources"][1]}]}
                           for lot in out.values() for p in lot]}


def _ct_jumelles(a: dict, b: dict, sig: dict) -> bool:
    """Deux fiches écrites par la même passe d'import : nom ET numéro normalisés identiques, même
    source, même compte, créées dans la même minute. Rien d'autre ne mérite une fusion en lot."""
    if "nom" not in sig or "tel" not in sig:
        return False
    if str(a.get("source") or "") != str(b.get("source") or "") or not a.get("source"):
        return False
    if str(a.get("compte") or "") != str(b.get("compte") or ""):
        return False
    ca, cb = str(a.get("created_at") or "")[:16], str(b.get("created_at") or "")[:16]
    return bool(ca) and ca == cb


def contacts_jumelles_fusionner(confirme: bool = False) -> dict:
    """LA PASSE SÛRE : fusionne toutes les jumelles d'import, et rend le compte.

    Rejouable : sans jumelle, elle ne fait rien. Avec `confirme`, elle prend d'abord une COPIE de la base
    (`cassandra_memory.db.avant-jumelles-<horodatage>`, par l'API de sauvegarde SQLite) — la preuve ① du
    débat, une restauration possible en acte — puis écrit un rapport JSON à côté de la base."""
    _contacts_migrate()
    d = contact_duplicates()
    if not d.get("ok"):
        return d
    paires = (d.get("paires") or {}).get("jumelles", [])
    if not confirme or not paires:
        return {"ok": True, "jumelles": len(paires), "fusionnees": 0, "essai": not confirme,
                "paires": paires[:50]}
    horo = datetime.now().strftime("%Y%m%d-%H%M%S")
    copie = MEMORY_DB_PATH + ".avant-jumelles-" + horo
    try:
        src = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        dst = sqlite3.connect(copie)
        src.backup(dst)
        dst.close(); src.close()
    except Exception as e:
        return {"ok": False, "reason": "copie de sûreté impossible : %s" % e}
    # PAR LOTS DE 200 (le plafond de contact_fusion_lot), jusqu'au bout : au premier démarrage, 200
    # paires sur 420 étaient parties et la passe s'était crue finie.
    fusionnees, refusees, faits = 0, [], []
    restantes = list(paires)
    for _tour in range(12):
        if not restantes:
            break
        lot = restantes[:200]
        res = contact_fusion_lot([{"a": p["a"], "b": p["b"], "garder": p["garder"]} for p in lot])
        fusionnees += int(res.get("fusionnees", 0) or 0)
        refusees += list(res.get("refusees", []))
        faits += list(res.get("faits", []))
        if not res.get("ok") or not res.get("fusionnees"):
            break
        restantes = restantes[200:]
    rapport = {"quand": horo, "copie": copie, "jumelles": len(paires),
               "fusionnees": fusionnees, "refusees": refusees, "faits": faits}
    try:
        chemin = os.path.join(os.path.dirname(MEMORY_DB_PATH), "contacts_jumelles_%s.json" % horo)
        with open(chemin, "w", encoding="utf-8") as f:
            json.dump(rapport, f, ensure_ascii=False, indent=1)
        rapport["rapport"] = chemin
    except Exception as e:
        logging.info("[CONTACTS] rapport des jumelles : %s", e)
    logging.info("[CONTACTS] jumelles : %d paire(s), %d fusionnée(s), %d refusée(s), copie %s",
                 len(paires), rapport["fusionnees"], len(rapport["refusees"]), copie)
    return dict(rapport, ok=True)


_CT_JUMELLES_MARQUE = ".jumelles_fusionnees"
_ISO_MARQUE = ".comptes_attribues"


def _bureau_migrer_comptes_demarrage() -> None:
    """Une seule fois après le code (schéma → code → données, tour 24) : les colonnes `compte` neuves,
    les lignes orphelines à l'administrateur (`iso_orphelines`), les espaces de notes orphelins versés.
    Marquée à côté de la base ; rejouable à la main (`iso_orphelines`, `_nt_attribuer_orphelins`)."""
    try:
        marque = os.path.join(os.path.dirname(MEMORY_DB_PATH), _ISO_MARQUE)
        if os.path.exists(marque):
            return
        time.sleep(120)
        r1 = iso_orphelines(confirme=True)
        r2 = _nt_attribuer_orphelins()
        with open(marque, "w", encoding="utf-8") as f:
            f.write(json.dumps({"quand": datetime.now().isoformat(timespec="seconds"),
                                "lignes": r1.get("total"), "detail": r1.get("detail"),
                                "espaces": [e.get("dossier") for e in (r2.get("espaces") or [])]},
                               ensure_ascii=False))
        logging.info("[ISO] migration des comptes : %s ligne(s) attribuée(s), %d espace(s) de notes versé(s)",
                     r1.get("total"), len(r2.get("espaces") or []))
    except Exception as e:
        logging.warning("[ISO] migration des comptes au démarrage : %s", e)


def _contacts_jumelles_demarrage() -> None:
    """Une seule fois, après le code (schéma → code → données, tour 24) : la passe sûre au démarrage,
    marquée par un fichier à côté de la base. Rejouable à la main par la route."""
    try:
        marque = os.path.join(os.path.dirname(MEMORY_DB_PATH), _CT_JUMELLES_MARQUE)
        if os.path.exists(marque):
            return
        time.sleep(90)
        rep = contacts_jumelles_fusionner(confirme=True)
        with open(marque, "w", encoding="utf-8") as f:
            f.write(json.dumps({"quand": datetime.now().isoformat(timespec="seconds"),
                                "jumelles": rep.get("jumelles"), "fusionnees": rep.get("fusionnees")}))
    except Exception as e:
        logging.warning("[CONTACTS] jumelles au démarrage : %s", e)


def _ct_remplissage(c: dict) -> int:
    """Combien cette fiche porte d'informations. Sert à choisir laquelle garder."""
    n = 0
    for k in ("display_name", "company", "job_title", "phone", "mobile",
              "address", "website", "notes", "anniversaire", "vault_ref"):
        if str(c.get(k) or "").strip():
            n += 1
    n += len(c.get("emails") or [])
    if c.get("a_photo") or c.get("photo"):
        n += 2
    if c.get("favorite"):
        n += 3      # un favori a été désigné à la main : il pèse plus
    return n


def _ct_meilleure(a: dict, b: dict):
    """Laquelle des deux fiches mérite d'absorber l'autre.

    La plus renseignée, et à égalité la plus ancienne — celle qui a le plus de
    chances d'être déjà citée ailleurs. Ce n'est qu'une PROPOSITION : l'écran
    laisse inverser le sens d'un clic, parce qu'aucune règle ne sait qu'on
    tient à la fiche saisie hier plutôt qu'à celle importée l'an dernier.
    """
    ra, rb = _ct_remplissage(a), _ct_remplissage(b)
    if ra != rb:
        return a["id"] if ra > rb else b["id"]
    da, db = str(a.get("created_at") or ""), str(b.get("created_at") or "")
    if da and db and da != db:
        return a["id"] if da < db else b["id"]
    return min(a["id"], b["id"])


def contact_fusion_lot(paires, compte: str = None) -> dict:
    """Fusionne un lot de paires CERTAINES, et rend le compte.

    Réservé au degré « adresse identique » : proposer « tout fusionner » sur du
    probable, ce serait offrir de vider vingt fiches sur une intuition. Le
    contrôle est refait ici et ne se contente pas de ce que l'écran annonce.
    """
    if not isinstance(paires, list) or not paires:
        return {"ok": False, "reason": "aucune paire désignée"}
    sures = {}
    d = contact_duplicates()
    if not d.get("ok"):
        return d
    for p in (d.get("paires") or {}).get("sur", []) + (d.get("paires") or {}).get("jumelles", []):
        sures[(p["a"], p["b"])] = p["garder"]
    faits, refus = [], []
    for p in paires[:200]:
        try:
            a, b = sorted((int(p.get("a")), int(p.get("b"))))
        except Exception:
            continue
        if (a, b) not in sures:
            refus.append({"a": a, "b": b, "pourquoi": "n'est plus une paire certaine ni jumelle"})
            continue
        garder = int(p.get("garder") or sures[(a, b)])
        perdre = b if garder == a else a
        r = contact_merge(perdre, garder, compte=compte)
        if r.get("ok"):
            faits.append({"garde": garder, "corbeille": perdre})
        else:
            refus.append({"a": a, "b": b, "pourquoi": r.get("reason") or "échec"})
    return {"ok": True, "fusionnees": len(faits), "faits": faits,
            "refusees": refus, "jours": _CT_CORBEILLE_JOURS}


def mail_contacts(query: str = "", limit: int = 100) -> dict:
    """Les correspondants, depuis le carnet — LOT 6 : `mail_contacts` est fondue dans `contacts` +
    `contact_emails`, bornée au compte, les compteurs du courrier avec. Même forme qu'avant pour
    l'écran (addr, name, received, sent, last_seen)."""
    _contacts_migrate()
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10); conn.row_factory = sqlite3.Row
        _iso_migrer(conn)
        ou, args = _iso_ou("c")
        q = "%%%s%%" % (query or "").strip().lower()
        rows = conn.execute(
            "SELECT e.addr, c.display_name AS name, COALESCE(e.received,0) AS received, "
            "COALESCE(e.sent,0) AS sent, COALESCE(e.last_seen,'') AS last_seen "
            "FROM contact_emails e JOIN contacts c ON c.id = e.contact_id "
            "WHERE COALESCE(c.supprime_at,'')='' AND COALESCE(c.fusion_vers,0)=0" + ou +
            " AND (? = '%%' OR lower(e.addr) LIKE ? OR lower(c.display_name) LIKE ?) "
            "ORDER BY received DESC, lower(c.display_name) LIMIT ?",
            list(args) + [q, q, q, int(limit)]).fetchall()
        conn.close()
        return {"ok": True, "contacts": [dict(r) for r in rows]}
    except Exception as e:
        return {"ok": False, "reason": str(e)}


def mail_contacts_verser(confirme: bool = False) -> dict:
    """LOT 6 : ce que l'ancienne table `mail_contacts` savait passe au carnet — les compteurs sur les
    adresses déjà rattachées, une fiche « courrier » pour les humaines inconnues. La table reste (vide de
    sens) jusqu'au prochain ménage ; rapport JSON à côté de la base."""
    _contacts_migrate()
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10); conn.row_factory = sqlite3.Row
        _iso_migrer(conn)
        try:
            rows = [dict(r) for r in conn.execute("SELECT account, addr, name, sent, received, last_seen "
                                                  "FROM mail_contacts")]
        except Exception:
            rows = []
        boites = {}
        for u in list(load_users() or {}):
            u = (u or "").strip().lower()
            try:
                cr = _imap_creds_du_coffre(u) if u else None
            except Exception:
                cr = None
            if cr and cr[2]:
                boites[str(cr[2]).strip().lower()] = u
        copies, a_creer, orphelines = 0, {}, 0
        for r in rows:
            adr = (r.get("addr") or "").strip().lower()
            if not adr:
                continue
            qui = boites.get((r.get("account") or "").strip().lower(), "")
            if _contact_addr_owner(conn, adr):
                if confirme:
                    conn.execute("UPDATE contact_emails SET received=MAX(COALESCE(received,0), ?), "
                                 "sent=MAX(COALESCE(sent,0), ?), last_seen=MAX(COALESCE(last_seen,''), ?) "
                                 "WHERE addr=?", (int(r.get("received") or 0), int(r.get("sent") or 0),
                                                  r.get("last_seen") or "", adr))
                copies += 1
                continue
            if not qui:
                orphelines += 1
                continue
            if mail_is_technical({"from_addr": adr, "subject": ""}) or _MAIL_NOREPLY.search(adr):
                continue
            a_creer.setdefault(qui, []).append({"display_name": (r.get("name") or adr.split("@")[0])[:120],
                                                "emails": [adr], "_stats": (int(r.get("received") or 0),
                                                                            int(r.get("sent") or 0),
                                                                            r.get("last_seen") or "")})
        conn.commit(); conn.close()
        crees = 0
        if confirme:
            for qui, lot in a_creer.items():
                v = contacts_verser([{k: x[k] for k in ("display_name", "emails")} for x in lot],
                                    source="courrier", completer=False, compte=qui)
                crees += int(v.get("crees") or 0)
                try:
                    conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
                    for x in lot:
                        n, s, vu = x["_stats"]
                        conn.execute("UPDATE contact_emails SET received=?, sent=?, last_seen=? WHERE addr=?",
                                     (n, s, vu, x["emails"][0]))
                    conn.commit(); conn.close()
                except Exception as e:
                    logging.info("[CARNET] compteurs versés : %s", e)
        out = {"ok": True, "lignes": len(rows), "copies": copies, "a_creer": sum(len(v) for v in a_creer.values()),
               "crees": crees, "orphelines": orphelines, "confirme": bool(confirme)}
        if confirme and rows:
            try:
                rapport = os.path.join(os.path.dirname(MEMORY_DB_PATH),
                                       "mail_contacts_%s.json" % datetime.now().strftime("%Y%m%d-%H%M%S"))
                with open(rapport, "w", encoding="utf-8") as f:
                    json.dump({"bilan": out, "lignes": rows}, f, ensure_ascii=False, indent=1, default=str)
                out["rapport"] = rapport
            except Exception as e:
                logging.info("[CARNET] rapport du versement : %s", e)
            logging.info("[CARNET] mail_contacts versée : %d ligne(s), %d compteur(s) copié(s), %d fiche(s) courrier "
                         "créée(s), %d orpheline(s)", len(rows), copies, crees, orphelines)
        return out
    except Exception as e:
        return {"ok": False, "reason": str(e)[:160]}


def menage_lot8(confirme: bool = False) -> dict:
    """LOT 8 : les trois réserves versées dans le carnet et les portraits (`mail_avatars`, `tgc_avatars`,
    `mail_contacts`) et le journal des flux fantômes (`ged_sync_log`) sont retirés — après vérification
    que ce qu'ils portaient est bien arrivé. Rapport JSON à côté de la base."""
    _contacts_migrate()
    out = {"ok": True, "tables": {}, "retirees": [], "gardees": [], "confirme": bool(confirme)}
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        _portraits_migrer(conn)
        def _n(sql):
            try:
                return int(conn.execute(sql).fetchone()[0])
            except Exception:
                return -1
        p_mail = _n("SELECT COUNT(*) FROM portraits WHERE cle LIKE 'mail:%'")
        p_tg = _n("SELECT COUNT(*) FROM portraits WHERE cle LIKE 'tg:%'")
        marque_mc = os.path.exists(os.path.join(os.path.dirname(MEMORY_DB_PATH), ".mail_contacts_versees"))
        regles = {"mail_avatars": (_n("SELECT COUNT(*) FROM mail_avatars"), p_mail),
                  "tgc_avatars": (_n("SELECT COUNT(*) FROM tgc_avatars"), p_tg),
                  "mail_contacts": (_n("SELECT COUNT(*) FROM mail_contacts"), 10 ** 9 if marque_mc else -1),
                  "ged_sync_log": (_n("SELECT COUNT(*) FROM ged_sync_log"), 10 ** 9)}
        for table, (avant, arrive) in regles.items():
            out["tables"][table] = {"lignes": avant, "arrivees": arrive}
            if avant < 0:
                continue                      # n'existe pas (déjà retirée, ou base neuve)
            if arrive < avant:
                out["gardees"].append(table)  # ce qu'elle porte n'est pas arrivé : on ne retire rien
                continue
            if confirme:
                conn.execute("DROP TABLE IF EXISTS %s" % table)
            out["retirees"].append(table)
        conn.commit(); conn.close()
        if confirme and out["retirees"]:
            try:
                rapport = os.path.join(os.path.dirname(MEMORY_DB_PATH),
                                       "menage_lot8_%s.json" % datetime.now().strftime("%Y%m%d-%H%M%S"))
                with open(rapport, "w", encoding="utf-8") as f:
                    json.dump(out, f, ensure_ascii=False, indent=1, default=str)
                out["rapport"] = rapport
            except Exception as e:
                logging.info("[MENAGE] rapport : %s", e)
            logging.info("[MENAGE] lot 8 : %s retirée(s)%s", ", ".join(out["retirees"]),
                         (" ; gardée(s) : " + ", ".join(out["gardees"])) if out["gardees"] else "")
        return out
    except Exception as e:
        return {"ok": False, "error": str(e)[:160]}


