_MAIL_RULE_FIELDS = ("from", "subject", "to")
_MAIL_RULE_OPS = ("contains", "equals", "startswith", "endswith")
_MAIL_RULE_ACTIONS = ("move", "flag", "seen", "delete")

_MAIL_RULE_SYS = (
    "Tu convertis une consigne de tri d'e-mails en règle structurée.\n"
    'Réponds UNIQUEMENT par un objet JSON : {"label":"...","field":"from|subject|to",'
    '"op":"contains|equals|startswith|endswith","value":"...","action":"move|flag|seen|delete",'
    '"target":"nom du dossier si action=move, sinon \\"\\"","explication":"une phrase"}\n'
    "Règles : une seule condition ; préfère « contains » ; pour un expéditeur, mets le domaine "
    "ou l'adresse dans value ; n'invente pas de dossier hors de ceux fournis."
)


def mail_rule_suggest(text: str) -> dict:
    """Traduit « range les mails d'OVH dans Factures » en règle — proposée, pas
    appliquée. Une règle mal comprise déplacerait silencieusement du courrier
    qu'on ne retrouverait jamais."""
    demande = (text or "").strip()
    if not demande:
        return {"ok": False, "reason": "décris la règle voulue"}
    dossiers = []
    f = mail_folders()
    if f.get("ok"):
        dossiers = [d["name"] for d in f.get("folders", [])]
    try:
        raw = _itare_agent_text(
            [{"role": "user", "content": "Dossiers existants : %s\n\nConsigne : %s"
              % (", ".join(dossiers) or "(inconnus)", demande)}],
            system=_MAIL_RULE_SYS, max_tokens=3000, allow_reasoning=False)
    except Exception as e:
        return {"ok": False, "reason": "agent indisponible : %s" % e}
    s, e = (raw or "").find("{"), (raw or "").rfind("}")
    if s == -1 or e <= s:
        return {"ok": False, "reason": "réponse inexploitable", "raw": (raw or "")[:300]}
    try:
        d = json.loads(raw[s:e + 1])
    except Exception as ex:
        return {"ok": False, "reason": "JSON illisible : %s" % ex}
    champ = str(d.get("field", "")).lower()
    op = str(d.get("op", "")).lower()
    action = str(d.get("action", "")).lower()
    souci = []
    if champ not in _MAIL_RULE_FIELDS:
        souci.append("champ inconnu (%s)" % champ)
    if op not in _MAIL_RULE_OPS:
        souci.append("opérateur inconnu (%s)" % op)
    if action not in _MAIL_RULE_ACTIONS:
        souci.append("action inconnue (%s)" % action)
    if action == "move" and not str(d.get("target", "")).strip():
        souci.append("dossier de destination manquant")
    if not str(d.get("value", "")).strip():
        souci.append("valeur vide : la règle s'appliquerait à tout")
    return {"ok": True, "valid": not souci, "reason": " · ".join(souci),
            "label": str(d.get("label", ""))[:120], "field": champ, "op": op,
            "value": str(d.get("value", ""))[:200], "action": action,
            "target": str(d.get("target", ""))[:120],
            "explication": str(d.get("explication", ""))[:300],
            # Supprimer d'office sur une règle générée par un modèle serait
            # le seul geste vraiment irrattrapable de tout ce module.
            "destructive": action == "delete"}


def mail_rule_save(label, field, op, value, action, target="", enabled=True, rid=None,
                   compte=None) -> dict:
    _mail_links_migrate()
    compte = _iso_compte(compte, "règle de tri")
    if field not in _MAIL_RULE_FIELDS or op not in _MAIL_RULE_OPS or action not in _MAIL_RULE_ACTIONS:
        return {"ok": False, "reason": "règle invalide"}
    if not str(value or "").strip():
        return {"ok": False, "reason": "valeur vide : la règle s'appliquerait à tous les messages"}
    if action == "move" and not str(target or "").strip():
        return {"ok": False, "reason": "dossier de destination requis"}
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        _iso_migrer(conn)
        if rid:
            _w, _a = _iso_ou()
            cur = conn.execute("UPDATE mail_rules SET label=?, field=?, op=?, value=?, action=?, "
                               "target=?, enabled=? WHERE id=?" + _w,
                               [label or "", field, op, value, action, target or "",
                                1 if enabled else 0, int(rid)] + list(_a))
            if not cur.rowcount:
                conn.close(); return {"ok": False, "reason": "règle introuvable"}
            _id = int(rid)
        else:
            cur = conn.execute("INSERT INTO mail_rules (label, field, op, value, action, target, "
                               "enabled, compte) VALUES (?,?,?,?,?,?,?,?)",
                               (label or "", field, op, value, action, target or "",
                                1 if enabled else 0, compte))
            _id = cur.lastrowid
        conn.commit(); conn.close()
        try:
            log_user_activity(compte, compte, "regle_tri", "#%s %s %s" % (_id, action, (value or "")[:60]))
        except Exception:
            pass
        return {"ok": True, "id": _id}
    except Exception as e:
        return {"ok": False, "reason": str(e)}


