# ============================================================
# LE REGISTRE DES MODULES ET LE PANNEAU D'HÉBERGEMENT (V18 générique)
# ============================================================
# Chaque produit tiers s'annonce par une détection, se règle à un seul endroit, et s'absente
# proprement : un onglet, un outil d'agent, un cron ne s'affichent ou ne tournent que si le
# module est présent. Le registre ne fait que rendre visible ce que le code savait déjà
# (débat générique, t.5) ; les deux trous mesurés (la voix, Docker) y reçoivent une détection.

_MODULES_CACHE = {}   # nom -> (epoch, dict) ; 60 s

def _module_detect_sur():
    """Un helper interne : `shutil.which` sans lever."""
    import shutil
    return shutil.which

def _module_tg_liens() -> int:
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=5)
        try:
            return int(conn.execute("SELECT COUNT(*) FROM tg_liens").fetchone()[0])
        finally:
            conn.close()
    except Exception:
        return 0

def _module_etat_calcul(nom: str) -> dict:
    """L'état d'un module, calculé à l'instant : present, absent, non_configure, en_panne."""
    which = _module_detect_sur()
    cfg = get_cassandra_config()
    try:
        if nom == "panneau":
            p = panneau_courant()
            return {"etat": "present" if p.nom != "nu" else "absent", "detail": p.libelle, "capacites": sorted(p.capacites)}
        if nom == "tailscale":
            return {"etat": "present" if which("tailscale") else "absent", "detail": "binaire tailscale" if which("tailscale") else "non installé : la Flotte ne verra que cette machine"}
        if nom == "portier":
            d = str(cfg.get("portier_dir") or "/opt/authentik")
            if not os.path.exists(os.path.join(d, "docker-compose.yml")):
                return {"etat": "absent", "detail": "pas d'Authentik dans %s" % d}
            if not cfg.get("portier_url"):
                return {"etat": "non_configure", "detail": "portier_url non réglé"}
            return {"etat": "present", "detail": "%s · %s" % (d, cfg.get("portier_url"))}
        if nom == "docker":
            return {"etat": "present" if which("docker") else "absent", "detail": "binaire docker"}
        if nom == "nginx":
            return {"etat": "present" if which("nginx") else "absent", "detail": "binaire nginx"}
        if nom == "mysql":
            ok = bool(which("mysql")) or os.path.exists("/run/mysqld/mysqld.sock")
            return {"etat": "present" if ok else "absent", "detail": "client mysql ou socket local"}
        if nom == "ollama":
            base = FOURNISSEURS["ollama"]["base_url"]
            return {"etat": "present" if _serveur_modele_repond(base) else ("non_configure" if which("ollama") else "absent"), "detail": base}
        if nom == "coffre":
            try:
                ok = bool(globals().get("vault_available", lambda: False)())
            except Exception:
                ok = False
            return {"etat": "present" if ok else "non_configure", "detail": (cfg.get("vault_public_url") or "coffre local non initialisé")}
        if nom == "searxng":
            return {"etat": "present" if (cfg.get("searxng_url") or "").strip() else "non_configure", "detail": (cfg.get("searxng_url") or "aucune URL")}
        if nom == "telegram":
            n = _module_tg_liens()
            return {"etat": "present" if n else "non_configure", "detail": "%d compte(s) relié(s)" % n}
        if nom == "canva":
            try:
                cid, sec = _canva_cles()
            except Exception:
                cid = sec = ""
            return {"etat": "present" if (cid and sec) else "non_configure", "detail": "identifiants OAuth" if (cid and sec) else "aucun identifiant OAuth"}
        if nom == "plex":
            url = ""
            try:
                url = (str(_mem_cfg("plex_url", "")) or "").strip()
            except Exception:
                pass
            return {"etat": "present" if url else "non_configure", "detail": url or "aucune adresse"}
        if nom == "voix":
            d = globals().get("_VX_VOIX_DIR", "")
            ok = bool(d) and os.path.isdir(d) and any(f.endswith(".onnx") for f in os.listdir(d))
            return {"etat": "present" if ok else "absent", "detail": d or "aucun dossier de voix"}
    except Exception as e:
        return {"etat": "en_panne", "detail": str(e)[:120]}
    return {"etat": "absent", "detail": "module inconnu"}

# ── LE PORTIER (Authentik, forward auth) ─────────────────────────────────────────────────
# Un portier posé devant des sites du panneau : Authentik en Docker, son avant-poste intégré, et
# dans le `.includes` de chaque site protégé un bloc nginx `auth_request`. Cassandra le lit et le
# manie par OPÉRATIONS NOMMÉES : rien ne se compose. Elle agit SEULE (choix de Drisse, 05-10 : pas
# d'accord humain) ; chaque geste est journalisé, et aucun ne part d'un tour teinté par un contenu lu.
# Les valeurs propres à une maison vivent dans la configuration :
#   portier_dir     dossier du docker-compose d'Authentik (défaut /opt/authentik)
#   portier_url     adresse publique du portier (https://auth.exemple.fr)
#   portier_maison  réseaux qui entrent sans connexion (liste CIDR ; vide = tout le monde passe par la porte)
# Leçons gravées (05-10) : `satisfy`/`allow`/`auth_request` posés au niveau server valent pour toutes
# les locations, nommées comprises — les deux locations du portier portent donc `auth_request off;
# allow all;` ; `^~` sinon la location regex des fichiers statiques passe avant ; le défi ACME passe
# par le port 443 (le 80 redirige) : le fournisseur l'exempte (`skip_path_regex`), sans quoi le
# certificat ne se renouvelle plus.

import io as _pt_io   # `io` n'est pas global dans ce fichier

_PT_DEBUT = "# ── portier:debut — bloc géré par Cassandra (outil portier), ne pas éditer à la main ──"
_PT_FIN = "# ── portier:fin ──"
_PT_DOMAINE_RE = re.compile(r"^(?=.{4,253}$)([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$")
_PT_VERSION_RE = re.compile(r"^\d{4}\.\d{1,2}\.\d{1,3}$")
_PT_ACME = r"^/\.well-known/acme-challenge/"
_PT_MARQUE = "PORTIER_JSON:"


def _pt_dir() -> str:
    return str(_mem_cfg("portier_dir", "") or "/opt/authentik").rstrip("/")


def _pt_url() -> str:
    return str(_mem_cfg("portier_url", "") or "").strip().rstrip("/")


def _pt_maison() -> list:
    """Les réseaux de confiance, validés un par un : une entrée qui n'est pas un réseau est
    écartée, jamais recopiée telle quelle dans nginx."""
    import ipaddress
    brut = get_cassandra_config().get("portier_maison") or []   # brut : `_mem_cfg` ferait list("…") lettre à lettre
    if isinstance(brut, str):
        brut = [x for x in re.split(r"[\s,;]+", brut) if x]
    out = []
    for x in brut:
        try:
            out.append(str(ipaddress.ip_network(str(x).strip(), strict=False)))
        except ValueError:
            logging.warning("[PORTIER] portier_maison : « %s » n'est pas un réseau, écarté", x)
    return out


def _pt_run(cmd: list, timeout: int = 60, cwd: str = None) -> tuple:
    try:
        p = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout, cwd=cwd)
        return p.returncode == 0, (p.stdout or "") + (p.stderr or "")
    except Exception as e:
        return False, "%s: %s" % (type(e).__name__, e)


def _pt_compose(args: list, timeout: int = 120) -> tuple:
    return _pt_run(["docker", "compose"] + args, timeout=timeout, cwd=_pt_dir())


def _pt_ak(code: str, timeout: int = 90) -> dict:
    """Exécute un fragment Python dans l'ORM d'Authentik (`ak shell`). Le fragment range sa
    réponse dans `R` ; elle revient par une ligne marquée, le reste de la sortie (journaux JSON
    d'Authentik) est ignoré."""
    prog = "import json\nR = {}\n" + code + "\nprint(%r + json.dumps(R, default=str))" % _PT_MARQUE
    ok, out = _pt_compose(["exec", "-T", "server", "ak", "shell", "-c", prog], timeout=timeout)
    for ligne in reversed(out.splitlines()):
        if ligne.startswith(_PT_MARQUE):
            try:
                return {"ok": True, "data": json.loads(ligne[len(_PT_MARQUE):])}
            except ValueError:
                break
    return {"ok": False, "reason": (out.strip().splitlines() or ["ak shell muet"])[-1][:300]}


def _pt_includes(domaine: str) -> str:
    """Le fichier `.includes` FastPanel du site, quel que soit son propriétaire. Vide si absent."""
    import glob
    for f in sorted(glob.glob("/etc/nginx/fastpanel2-sites/*/%s.includes" % domaine)):
        return f
    return ""


def _pt_bloc(maison: list) -> str:
    l = [_PT_DEBUT,
         "# La maison passe sans connexion ; le reste passe par le portier. Hérité par toutes les locations."]
    if maison:
        l.append("satisfy any;")
        l += ["allow %s;" % r for r in maison]
        l.append("deny all;")
    l += ["",
          "auth_request /outpost.goauthentik.io/auth/nginx;",
          "error_page 401 = @goauthentik_proxy_signin;",
          "auth_request_set $auth_cookie $upstream_http_set_cookie;",
          "add_header Set-Cookie $auth_cookie;",
          "",
          "# ^~ : sinon la location regex des fichiers statiques passe avant.",
          "location ^~ /outpost.goauthentik.io {",
          "    auth_request off;",
          "    allow all;",
          "    proxy_pass http://127.0.0.1:%d/outpost.goauthentik.io;" % _pt_port(),
          "    proxy_set_header Host $host;",
          "    proxy_set_header X-Original-URL $scheme://$http_host$request_uri;",
          "    add_header Set-Cookie $auth_cookie;",
          "    auth_request_set $auth_cookie $upstream_http_set_cookie;",
          "    proxy_pass_request_body off;",
          "    proxy_set_header Content-Length \"\";",
          "}",
          "",
          "location @goauthentik_proxy_signin {",
          "    internal;",
          "    auth_request off;",
          "    allow all;",
          "    add_header Set-Cookie $auth_cookie;",
          "    return 302 /outpost.goauthentik.io/start?rd=$scheme://$http_host$request_uri;",
          "}",
          _PT_FIN]
    return "\n".join(l) + "\n"


def _pt_port() -> int:
    """Le port HTTP d'Authentik sur la machine, lu dans son .env (COMPOSE_PORT_HTTP=127.0.0.1:9180)."""
    try:
        for ligne in _pt_io.open(os.path.join(_pt_dir(), ".env"), encoding="utf-8"):
            if ligne.startswith("COMPOSE_PORT_HTTP="):
                return int(ligne.strip().rsplit(":", 1)[-1])
    except Exception:
        pass
    return 9000


def _pt_retirer_bloc(texte: str) -> tuple:
    """Retire le bloc géré. Rend (texte, retiré?). Un bloc posé à la main, sans marques, n'est pas
    touché : on ne retire que ce qu'on a écrit."""
    i, j = texte.find(_PT_DEBUT), texte.find(_PT_FIN)
    if i < 0 or j < i:
        return texte, False
    j += len(_PT_FIN)
    if texte[j:j + 1] == "\n":
        j += 1
    avant = texte[:i].rstrip("\n")
    apres = texte[j:].lstrip("\n")
    t = avant + ("\n" if avant and apres else "") + apres
    return (t + "\n" if t and not t.endswith("\n") else t), True


def _pt_ecrire(chemin: str, texte: str):
    """Écrit à côté puis remplace : un `open(..., "w")` tronque AVANT de pouvoir échouer."""
    st = os.stat(chemin)
    tmp = chemin + ".portier-tmp"
    with _pt_io.open(tmp, "w", encoding="utf-8", newline="\n") as f:
        f.write(texte)
    os.chmod(tmp, st.st_mode & 0o7777)
    try:
        os.chown(tmp, st.st_uid, st.st_gid)
    except (OSError, AttributeError):   # AttributeError : pas de chown hors POSIX
        pass
    os.replace(tmp, chemin)


def _pt_nginx_recharger() -> tuple:
    ok, out = _pt_run(["nginx", "-t"], timeout=30)
    # `nginx -t` peut rendre 0 en ayant échoué : on exige le mot du succès.
    if "test is successful" not in out:
        return False, out.strip()[-400:]
    ok, out2 = _pt_run(["systemctl", "reload", "nginx"], timeout=30)
    return ok, (out2.strip() or "nginx rechargé")


def _pt_sonde(domaine: str) -> int:
    """Le code que rend l'avant-poste pour ce site sans session : 401 = le portier le connaît et
    garde la porte. Interrogé en local, avec l'en-tête que nginx lui transmet."""
    try:
        req = urllib.request.Request("http://127.0.0.1:%d/outpost.goauthentik.io/auth/nginx" % _pt_port(),
                                     headers={"Host": domaine, "X-Original-URL": "https://%s/" % domaine})
        with urllib.request.urlopen(req, timeout=8) as r:
            return r.status
    except urllib.error.HTTPError as e:
        return e.code
    except Exception:
        return 0


def _pt_conteneurs() -> list:
    ok, out = _pt_compose(["ps", "--format", "{{.Service}}\t{{.Status}}"], timeout=20)
    if not ok:
        return []
    return [dict(zip(("service", "etat"), l.split("\t", 1))) for l in out.splitlines() if "\t" in l]


def _pt_sain(attente: int = 0) -> bool:
    fin = time.time() + attente
    while True:
        c = {x["service"]: x["etat"] for x in _pt_conteneurs()}
        if c.get("server", "").find("(healthy)") >= 0 and c.get("worker", "").find("(healthy)") >= 0:
            return True
        if time.time() >= fin:
            return False
        time.sleep(4)


def _pt_porte_repond() -> bool:
    """La porte maison est-elle servie ? (et non la page standard d'Authentik)"""
    try:
        req = urllib.request.Request("http://127.0.0.1:%d/if/flow/default-authentication-flow/" % _pt_port(),
                                     headers={"Host": re.sub(r"^https?://", "", _pt_url()) or "localhost"})
        with urllib.request.urlopen(req, timeout=10) as r:
            return 'data-slug="' in r.read(60000).decode("utf-8", "replace")
    except Exception:
        return False


def _pt_version() -> str:
    try:
        for ligne in _pt_io.open(os.path.join(_pt_dir(), ".env"), encoding="utf-8"):
            if ligne.startswith("AUTHENTIK_TAG="):
                return ligne.split("=", 1)[1].strip()
        m = re.search(r"AUTHENTIK_TAG:-([0-9.]+)", _pt_io.open(os.path.join(_pt_dir(), "docker-compose.yml"), encoding="utf-8").read())
        return m.group(1) if m else ""
    except Exception:
        return ""


def _pt_derniere_version() -> str:
    try:
        req = urllib.request.Request("https://api.github.com/repos/goauthentik/authentik/releases/latest",
                                     headers={"Accept": "application/vnd.github+json", "User-Agent": "Cassandra"})
        with urllib.request.urlopen(req, timeout=10) as r:
            tag = json.loads(r.read().decode("utf-8")).get("tag_name", "")
        v = tag.replace("version/", "").strip()
        return v if _PT_VERSION_RE.match(v) else ""
    except Exception:
        return ""


def portier_etat() -> dict:
    d = {"ok": True, "dossier": _pt_dir(), "url": _pt_url(), "maison": _pt_maison(),
         "version": _pt_version(), "conteneurs": _pt_conteneurs()}
    d["sain"] = _pt_sain(0)
    # Les sites gardés : un fournisseur en forward auth (lu dans Authentik) ET un bloc dans nginx.
    r = _pt_ak("from authentik.providers.proxy.models import ProxyProvider\n"
               "R['fournisseurs'] = [dict(nom=p.name, hote=p.external_host, mode=p.mode, acme=bool(p.skip_path_regex), "
               "appli=(p.application.slug if hasattr(p, 'application') else '')) for p in ProxyProvider.objects.all()]")
    sites = []
    for p in (r.get("data") or {}).get("fournisseurs", []):
        dom = re.sub(r"^https?://", "", p.get("hote") or "").strip("/")
        inc = _pt_includes(dom)
        texte = _pt_io.open(inc, encoding="utf-8").read() if inc else ""
        sites.append({"domaine": dom, "appli": p.get("appli"), "mode": p.get("mode"),
                      "acme_exempte": p.get("acme"),
                      "bloc_nginx": "gere" if _PT_DEBUT in texte else ("manuel" if "auth_request /outpost.goauthentik.io" in texte else "absent")})
    d["sites"] = sites
    if not r.get("ok"):
        d["erreur_authentik"] = r.get("reason")
    # La porte : sa source (le montage de /templates) et la surveillance qui recharge après retouche.
    try:
        m = re.search(r"-\s*(\S+):/templates", _pt_io.open(os.path.join(_pt_dir(), "docker-compose.yml"), encoding="utf-8").read())
        d["porte_source"] = m.group(1) if m else ""
    except Exception:
        d["porte_source"] = ""
    ok, out = _pt_run(["systemctl", "is-active", "portier-recharge.path"], timeout=10)
    d["recharge_auto"] = out.strip() == "active"
    return d


def portier_geste(action: str, arg: str = "", acteur: str = "") -> dict:
    """Les gestes du portier, exécutés tout de suite."""
    action = (action or "").strip()
    arg = (arg or "").strip().lower()

    def _journal(res, detail):
        try:
            log_admin_action(acteur or "", "portier_%s" % action[:20], res, detail[:200])
        except Exception as e:
            logging.debug("[AUDIT] %s", e)

    if action in ("proteger", "liberer"):
        if not _PT_DOMAINE_RE.match(arg):
            return {"ok": False, "reason": "domaine manquant ou invalide (ex. site.exemple.fr)"}
        inc = _pt_includes(arg)
        if not inc:
            return {"ok": False, "reason": "aucun site « %s » dans le panneau (fichier .includes introuvable)" % arg}
        texte = _pt_io.open(inc, encoding="utf-8").read()
        if action == "proteger":
            if "auth_request" in texte:
                return {"ok": False, "reason": "%s est déjà derrière une porte (%s)" % (arg, "bloc géré" if _PT_DEBUT in texte else "bloc posé à la main")}
            if not _pt_url():
                return {"ok": False, "reason": "portier_url n'est pas réglé : le portier n'a pas d'adresse publique"}
        else:
            if _PT_DEBUT not in texte:
                return {"ok": False, "reason": "pas de bloc géré dans %s%s" % (inc, " (un bloc posé à la main s'y trouve : à retirer à la main)" if "auth_request" in texte else "")}

        if action == "proteger":
            r = _pt_ak(
                "from authentik.flows.models import Flow\n"
                "from authentik.providers.proxy.models import ProxyProvider, ProxyMode\n"
                "from authentik.core.models import Application\n"
                "from authentik.outposts.models import Outpost\n"
                "d = %r\n" % arg +
                "az = Flow.objects.get(slug='default-provider-authorization-implicit-consent')\n"
                "inv = Flow.objects.get(slug='default-provider-invalidation-flow')\n"
                "p, _ = ProxyProvider.objects.update_or_create(name=d, defaults=dict(mode=ProxyMode.FORWARD_SINGLE, "
                "external_host='https://' + d, authorization_flow=az, invalidation_flow=inv, "
                "access_token_validity='hours=24', skip_path_regex=%r))\n" % _PT_ACME +
                "a, _ = Application.objects.update_or_create(slug=d.replace('.', '-'), defaults=dict(name=d, provider=p, "
                "meta_launch_url='https://' + d))\n"
                "o = Outpost.objects.get(managed='goauthentik.io/outposts/embedded')\n"
                "c = o.config; c.authentik_host = %r; o.config = c; o.save(); o.providers.add(p)\n" % _pt_url() +
                "R['fournisseur'] = p.pk")
            if not r.get("ok"):
                _journal("FAIL", "%s : Authentik %s" % (arg, r.get("reason")))
                return {"ok": False, "reason": "Authentik a refusé : %s" % r.get("reason")}
            avant = texte
            _pt_ecrire(inc, texte.rstrip("\n") + ("\n\n" if texte.strip() else "") + _pt_bloc(_pt_maison()))
            ok, msg = _pt_nginx_recharger()
            if not ok:
                _pt_ecrire(inc, avant)
                _pt_nginx_recharger()
                _journal("FAIL", "%s : nginx %s" % (arg, msg))
                return {"ok": False, "reason": "nginx refuse le bloc, fichier remis en l'état : %s" % msg}
            # L'avant-poste apprend le nouveau fournisseur en quelques secondes.
            code, fin = 0, time.time() + 45
            while time.time() < fin:
                code = _pt_sonde(arg)
                if code == 401:
                    break
                time.sleep(3)
            _journal("OK" if code == 401 else "FAIL", "%s : sonde %s" % (arg, code))
            return {"ok": code == 401, "action": action, "domaine": arg,
                    "verification": "l'avant-poste garde la porte (401 sans session)" if code == 401
                    else "l'avant-poste ne reconnaît pas encore le site (code %s) : réessayer « etat » dans une minute" % code}

        # liberer
        nouveau, _ = _pt_retirer_bloc(texte)
        _pt_ecrire(inc, nouveau)
        ok, msg = _pt_nginx_recharger()
        if not ok:
            _pt_ecrire(inc, texte)
            _pt_nginx_recharger()
            _journal("FAIL", "%s : nginx %s" % (arg, msg))
            return {"ok": False, "reason": "nginx refuse le fichier sans le bloc, remis en l'état : %s" % msg}
        r = _pt_ak("from authentik.providers.proxy.models import ProxyProvider\n"
                   "from authentik.core.models import Application\n"
                   "d = %r\n" % arg +
                   "R['applis'] = Application.objects.filter(provider__name=d).delete()[0]\n"
                   "R['fournisseurs'] = ProxyProvider.objects.filter(name=d).delete()[0]")
        _journal("OK" if r.get("ok") else "FAIL", "%s : %s" % (arg, r))
        return {"ok": True, "action": action, "domaine": arg,
                "authentik": "fournisseur et application supprimés" if r.get("ok") else "bloc retiré, mais Authentik : %s" % r.get("reason")}

    if action == "recharger":
        ok, out = _pt_compose(["restart", "server"], timeout=120)
        sain = ok and _pt_sain(150)
        _journal("OK" if sain else "FAIL", out[-150:])
        return {"ok": sain, "action": action, "detail": "serveur reparti et sain" if sain else out[-300:]}

    if action == "mettre_a_jour":
        actuelle = _pt_version()
        cible = arg or _pt_derniere_version()
        if not _PT_VERSION_RE.match(cible or ""):
            return {"ok": False, "reason": "version cible inconnue (donner la version, ex. 2026.10.1)"}
        if cible == actuelle:
            return {"ok": True, "action": action, "detail": "déjà en %s" % actuelle}
        env = os.path.join(_pt_dir(), ".env")
        texte = _pt_io.open(env, encoding="utf-8").read()
        sauv_dir = os.path.join(_pt_dir(), "sauvegardes")
        os.makedirs(sauv_dir, mode=0o700, exist_ok=True)
        dump = os.path.join(sauv_dir, "avant-%s.sql" % cible)
        ok, out = _pt_compose(["exec", "-T", "postgresql", "sh", "-c", 'pg_dump -U "${POSTGRES_USER:-authentik}" "${POSTGRES_DB:-authentik}"'], timeout=300)
        if not ok or "CREATE TABLE" not in out:
            _journal("FAIL", "sauvegarde : " + out[-150:])
            return {"ok": False, "reason": "sauvegarde de la base impossible, rien n'a changé : %s" % out[-200:]}
        with _pt_io.open(dump, "w", encoding="utf-8") as f:
            f.write(out)
        os.chmod(dump, 0o600)

        def _poser(v):
            t = re.sub(r"(?m)^AUTHENTIK_TAG=.*\n?", "", texte)
            _pt_ecrire(env, t.rstrip("\n") + "\nAUTHENTIK_TAG=%s\n" % v)

        _poser(cible)
        ok, out = _pt_compose(["pull", "-q"], timeout=900)
        if ok:
            ok, out = _pt_compose(["up", "-d"], timeout=300)
        sain = ok and _pt_sain(300)
        if not sain:
            _pt_ecrire(env, texte)
            _pt_compose(["up", "-d"], timeout=300)
            revenu = _pt_sain(300)
            _journal("FAIL", "%s → %s, retour %s" % (actuelle, cible, "sain" if revenu else "MALADE"))
            return {"ok": False, "reason": "%s ne repart pas sain : retour à %s (%s). Base sauvegardée : %s"
                    % (cible, actuelle, "le portier est reparti" if revenu else "LE PORTIER NE REPART PAS, à voir à la main", dump)}
        porte = _pt_porte_repond()
        _journal("OK", "%s → %s, porte %s" % (actuelle, cible, "maison" if porte else "STANDARD"))
        return {"ok": True, "action": action,
                "detail": "Authentik %s → %s, sain. Base d'avant : %s. %s" % (actuelle, cible, dump,
                          "La porte maison répond." if porte else
                          "ATTENTION : la porte maison ne répond pas, les visiteurs voient la page standard d'Authentik.")}

    return {"ok": False, "reason": "action inconnue (etat, journal, proteger, liberer, recharger, mettre_a_jour)"}


def portier_journal(n: int = 20) -> dict:
    """Les dernières entrées et tentatives au portier, lues dans les événements d'Authentik."""
    n = max(1, min(int(n or 20), 100))
    r = _pt_ak("from authentik.events.models import Event\n"
               "R['ev'] = [dict(quand=e.created.isoformat(timespec='seconds'), quoi=e.action, qui=(e.user or {}).get('username', ''), "
               "ip=e.client_ip, pays=((e.context or {}).get('geo') or {}).get('country', '')) "
               "for e in Event.objects.filter(action__in=['login', 'login_failed']).order_by('-created')[:%d]]" % n)
    if not r.get("ok"):
        return {"ok": False, "reason": r.get("reason")}
    return {"ok": True, "evenements": r["data"].get("ev", [])}


def _portier_impl(args: dict) -> tuple:
    action = str(args.get("action") or "etat").strip()
    if action == "etat":
        d = portier_etat()
        l = ["Authentik %s · %s · porte %s" % (d.get("version") or "?", "sain" if d.get("sain") else "PAS SAIN",
                                               d.get("url") or "(portier_url non réglé)")]
        l += ["  %s : %s" % (c["service"], c["etat"]) for c in d.get("conteneurs", [])]
        l.append("Sites gardés :" if d.get("sites") else "Aucun site gardé.")
        for s in d.get("sites", []):
            l.append("  %s — bloc nginx %s, ACME %s" % (s["domaine"], {"gere": "géré par Cassandra", "manuel": "posé à la main", "absent": "ABSENT (site ouvert)"}.get(s["bloc_nginx"], s["bloc_nginx"]), "exempté" if s["acme_exempte"] else "NON exempté (renouvellement bloqué)"))
        l.append("Entrent sans connexion : %s" % (", ".join(d.get("maison") or []) or "personne"))
        l.append("Source de la porte : %s · rechargement auto %s" % (d.get("porte_source") or "?", "actif" if d.get("recharge_auto") else "INACTIF"))
        if d.get("erreur_authentik"):
            l.append("Authentik injoignable : %s" % d["erreur_authentik"])
        return d, "\n".join(l), "#27c168" if d.get("sain") else "#e8c660"
    if action == "journal":
        d = portier_journal(args.get("arg") or 20)
        if not d.get("ok"):
            return d, "Échec : %s" % d.get("reason"), "#e0564a"
        l = ["%s  %s  %s  %s %s" % (e["quand"], "ENTRÉE " if e["quoi"] == "login" else "ÉCHEC  ", e["qui"] or "?", e["ip"] or "", e["pays"] or "")
             for e in d["evenements"]]
        return d, "\n".join(l) or "Aucune entrée ni tentative enregistrée.", "#27c168"
    # Un geste ne part pas d'un tour qui a lu du contenu étranger : un texte lu ne déclenche rien.
    try:
        if origine_courante().get("teintes") or []:
            return ({"ok": False}, "Refusé : ce tour a lu du contenu extérieur, un geste sur le portier ne part pas d'ici. "
                                   "Il partira d'un tour neuf.", "#e0564a")
    except Exception:
        pass
    r = portier_geste(action, str(args.get("arg") or ""), "agent")
    if not r.get("ok"):
        return r, "Échec : %s" % r.get("reason"), "#e0564a"
    return r, "Fait : %s" % "; ".join("%s=%s" % (k, v) for k, v in r.items() if k not in ("ok",)), "#27c168"


# nom -> libellé, outils d'agent portés (retirés au modèle quand le module est absent), onglet
MODULES = {
    "panneau":   {"libelle": "Panneau d'hébergement", "outils": ("panel_act",), "onglet": "fastpanel"},
    "tailscale": {"libelle": "Tailscale (réseau privé de la Flotte)", "outils": ("tailscale_peers",), "onglet": ""},
    "docker":    {"libelle": "Docker", "outils": (), "onglet": ""},
    "nginx":     {"libelle": "nginx", "outils": (), "onglet": ""},
    "mysql":     {"libelle": "MySQL / MariaDB", "outils": (), "onglet": ""},
    "ollama":    {"libelle": "Ollama (modèles locaux)", "outils": (), "onglet": ""},
    "coffre":    {"libelle": "Coffre de secrets", "outils": ("vault_list_secrets", "vault_store_secret", "vault_remove_secret"), "onglet": "vault"},
    "searxng":   {"libelle": "SearxNG (recherche web)", "outils": (), "onglet": ""},
    "telegram":  {"libelle": "Telegram", "outils": (), "onglet": ""},
    "canva":     {"libelle": "Canva", "outils": (), "onglet": ""},
    "plex":      {"libelle": "Plex", "outils": ("itare_plex",), "onglet": ""},
    "voix":      {"libelle": "Voix (dictée et lecture)", "outils": (), "onglet": ""},
    "portier":   {"libelle": "Portier (Authentik)", "outils": ("portier",), "onglet": ""},
}

def module_etat(nom: str) -> dict:
    c = _MODULES_CACHE.get(nom)
    if c and time.time() - c[0] < 60:
        return c[1]
    d = _module_etat_calcul(nom)
    _MODULES_CACHE[nom] = (time.time(), d)
    return d

def module_present(nom: str) -> bool:
    return module_etat(nom).get("etat") == "present"

def modules_etat() -> dict:
    """Ce que l'écran Réglages › Modules et /api/modules montrent : chaque module, son état, sa
    raison ; et le panneau détecté avec ses capacités."""
    p = panneau_courant()
    return {"ok": True,
            "modules": [dict(nom=n, libelle=m["libelle"], onglet=m["onglet"], outils=list(m["outils"]), **module_etat(n)) for n, m in MODULES.items()],
            "panneau": {"nom": p.nom, "libelle": p.libelle, "capacites": sorted(p.capacites), "pris_en_charge": p.pris_en_charge}}

def outils_disponibles(base: list = None) -> list:
    """Les outils passés au modèle, construits depuis le registre : un outil d'un module absent
    n'existe pas pour le modèle (un mur, pas une suggestion)."""
    base = CASSANDRA_TOOLS if base is None else base
    retires = set()
    for n, m in MODULES.items():
        if m["outils"] and not module_present(n):
            retires.update(m["outils"])
    if not retires:
        return list(base)
    return [t for t in base if (t.get("function") or {}).get("name") not in retires]


# ── LE PANNEAU D'HÉBERGEMENT : une interface, plusieurs dos ────────────────────────────
PANNEAU_CAPACITES = ("sites", "comptes", "bases", "mail", "ftp", "dns", "sauvegardes", "crons", "php", "services", "ssl", "actions", "scans")
# chaque route de lecture de l'onglet Hébergement dépend d'une capacité du dos courant
_FP_ROUTE_CAPACITE = {"/api/fp/domains": "sites", "/api/fp/users": "comptes", "/api/fp/databases": "bases",
                      "/api/fp/mail": "mail", "/api/fp/ftp": "ftp", "/api/fp/dns": "dns", "/api/fp/backups": "sauvegardes",
                      "/api/fp/crons": "crons", "/api/fp/php": "php", "/api/fp/services": "services",
                      "/api/fp/ssl": "ssl", "/api/fp/actions": "actions", "/api/fp/scans": "scans"}

class Panneau:
    """Le contrat : une méthode par capacité, chacune rend la même forme de données que les
    getters d'aujourd'hui (débat, t.6 p.2). Une capacité absente rend une liste vide avec sa
    raison, jamais une exception ; l'écran et les outils lisent `capacites` avant d'appeler."""
    nom = "nu"
    libelle = "aucun panneau détecté · version allégée"
    pris_en_charge = True
    capacites = frozenset()

    @classmethod
    def detecter(cls) -> bool:
        return True

    def absent(self, capacite: str) -> dict:
        return {"ok": False, "rows": [], "reason": "capacité « %s » non prise en charge par le dos courant (%s)" % (capacite, self.libelle)}

    def _capable(self, capacite: str, f):
        if capacite not in self.capacites:
            return self.absent(capacite)
        try:
            return f()
        except Exception as e:
            return {"ok": False, "rows": [], "reason": str(e)[:200]}

    def sites(self):       return self._capable("sites", lambda: get_fp_domains())
    def comptes(self):     return self._capable("comptes", lambda: get_fp_users())
    def bases(self):       return self._capable("bases", lambda: get_fp_databases())
    def mail(self):        return self._capable("mail", lambda: get_fp_mail())
    def ftp(self):         return self._capable("ftp", lambda: get_fp_ftp())
    def dns(self):         return self._capable("dns", lambda: get_fp_dns())
    def sauvegardes(self): return self._capable("sauvegardes", lambda: get_fp_backups())
    def crons(self):       return self._capable("crons", lambda: get_fp_crons())
    def php(self):         return self._capable("php", lambda: get_fp_php())
    def services(self):    return self._capable("services", lambda: get_fp_services())
    def ssl(self):         return self._capable("ssl", lambda: fp_ssl_overview())
    def actions(self):     return self._capable("actions", lambda: fp_actions_list())
    def scans(self):       return self._capable("scans", lambda: get_fp_scans())


class PanneauNu(Panneau):
    """Sans panneau : ce que l'hôte sait dire par lui-même — sites lus dans nginx, comptes unix,
    bases par MySQL, services par systemd, certificats par certbot, crons du système, versions
    PHP installées. Ce sont les branches basses des getters existants, exposées telles quelles.
    Absents : mail, ftp, dns, sauvegardes du panneau, actions de création, analyses antivirus."""
    nom = "nu"
    capacites = frozenset({"sites", "comptes", "bases", "crons", "php", "services", "ssl"})


class PanneauFastPanel(Panneau):
    nom = "fastpanel"
    libelle = "FastPanel"
    capacites = frozenset(PANNEAU_CAPACITES)

    @classmethod
    def detecter(cls) -> bool:
        try:
            return bool(_fp_db_path()) or os.path.isfile("/usr/local/fastpanel2/fastpanel")
        except Exception:
            return False


class PanneauDetecteSeulement(PanneauNu):
    """Un panneau reconnu par son marqueur mais sans dos écrit : la version allégée s'applique,
    et l'écran dit lequel a été vu. Chaque dos réel remplacera l'entrée correspondante."""
    pris_en_charge = False
    marqueurs = ()

    @classmethod
    def detecter(cls) -> bool:
        return any(os.path.exists(m) for m in cls.marqueurs)

class PanneauPlesk(PanneauDetecteSeulement):
    nom = "plesk"; libelle = "Plesk détecté (non pris en charge : version allégée)"; marqueurs = ("/usr/local/psa/admin/bin/plesk", "/etc/psa/psa.conf")
class PanneauCPanel(PanneauDetecteSeulement):
    nom = "cpanel"; libelle = "cPanel détecté (non pris en charge : version allégée)"; marqueurs = ("/usr/local/cpanel/cpanel",)
class PanneauHestia(PanneauDetecteSeulement):
    nom = "hestia"; libelle = "HestiaCP détecté (non pris en charge : version allégée)"; marqueurs = ("/usr/local/hestia/bin/v-list-sys-info",)
class PanneauDirectAdmin(PanneauDetecteSeulement):
    nom = "directadmin"; libelle = "DirectAdmin détecté (non pris en charge : version allégée)"; marqueurs = ("/usr/local/directadmin/directadmin",)
class PanneauWebmin(PanneauDetecteSeulement):
    nom = "webmin"; libelle = "Webmin détecté (non pris en charge : version allégée)"; marqueurs = ("/etc/webmin/config",)

PANNEAUX = (PanneauFastPanel, PanneauPlesk, PanneauCPanel, PanneauHestia, PanneauDirectAdmin, PanneauWebmin)
_PANNEAU = {"p": None, "t": 0.0}

def detecter_panneau() -> Panneau:
    """Le réglage `panneau` (fastpanel, plesk, …, nu) force ; sinon le premier marqueur trouvé ;
    sinon le dos nu. Le résultat est journalisé une fois et gardé cinq minutes."""
    force = (get_cassandra_config().get("panneau") or "").strip().lower()
    if force == "nu":
        return PanneauNu()
    for cls in PANNEAUX:
        if force and cls.nom == force:
            return cls()
    if force:
        logging.warning("[PANNEAU] réglage panneau=%r inconnu : détection automatique", force)
    for cls in PANNEAUX:
        try:
            if cls.detecter():
                return cls()
        except Exception:
            continue
    return PanneauNu()

def panneau_courant() -> Panneau:
    if _PANNEAU["p"] is None or time.time() - _PANNEAU["t"] > 300:
        p = detecter_panneau()
        if _PANNEAU["p"] is None or p.nom != _PANNEAU["p"].nom:
            logging.info("[PANNEAU] dos courant : %s (%s)", p.nom, p.libelle)
        _PANNEAU.update({"p": p, "t": time.time()})
    return _PANNEAU["p"]


