import functools
import re
import time
import json
import os
import logging
from typing import Generator, Any

# PERF: Déplacer la regex compilée en dehors de la fonction pour éviter recompilation à chaque appel
import re
_file_mod_re = re.compile(r'([/\w\.\-]+)')

import functools
import time
import os
import json
import logging
from typing import List, Dict, Any, Generator

# PERF: Constantes déplacées en dehors de la fonction pour éviter de les recréer à chaque appel
_MAX_TOOL_LOOPS = 90
_TOOL_LIMIT = 6000
_DISPLAY_LIMIT = 3000
_EMOJI_MAP = {'ssh': '🖥', 'synology': '🖧', 'proxmox': '🧱', 'ping': '📡', 'cassandra': '🤖'}

# PERF: Cache global pour les serveurs (rechargé uniquement si _ms_load() change)
# On suppose que _ms_load est déjà optimisé, sinon on pourrait ajouter un lru_cache ici
_servers_cache = None
_server_ssh_dict_cache = None

def _load_servers_once():
    global _servers_cache, _server_ssh_dict_cache
    if _servers_cache is None:
        _servers_cache = _ms_load()
        _server_ssh_dict_cache = {s["name"]: s for s in _servers_cache if s.get("type") == "ssh"}
    return _servers_cache, _server_ssh_dict_cache

# PERF: Cache LRU pour is_risky_command (limité à 1024 entrées)
@functools.lru_cache(maxsize=1024)
def _is_risky_command_cached(cmd: str) -> bool:
    return is_risky_command(cmd)

# PERF: Cache LRU pour _get_file_data (taille limitée, invalidation manuelle via cache_clear si besoin)
# On garde un cache manuel pour pouvoir invalider par path après exécution
_file_data_cache: Dict[str, tuple] = {}

def _get_file_data_cached(path: str):
    if path in _file_data_cache:
        return _file_data_cache[path]
    try:
        st = os.stat(path)
        if st.st_size >= 300_000:
            res = (False, 0, 0, None)
        else:
            with open(path, 'r', errors='replace') as fh:
                content = fh.read()
            res = (True, st.st_size, st.st_mtime, content)
    except (OSError, PermissionError) as e:
        logging.warning("[call_deepseek_stream] _get_file_data %s: %s", path, e)
        res = (False, 0, 0, None)
    _file_data_cache[path] = res
    return res

def _invalidate_file_cache(path: str):
    _file_data_cache.pop(path, None)

# PERF: Extraction des sous-fonctions en dehors de call_deepseek_stream pour éviter la re-définition à chaque appel et améliorer la maintenabilité.
# PERF: Utilisation de caches de niveau module (ex: _file_mod_re, _get_file_data_cached) déjà présents, pas de modification nécessaire.

def _run_bash(cmd: str, risky: bool, session_id: str) -> tuple:
    """Exécute une commande bash et retourne (html, content, dur, diff)."""
    t0 = time.perf_counter()
    files_before = {}
    if risky:
        # Borne : _file_mod_re capture TOUT jeton ressemblant à un chemin. Sans
        # plafond, une commande citant 40 chemins provoquait 40 lectures de fichier
        # avant exécution. D'autant plus sensible que le nouveau modèle de risque
        # classe bien plus de commandes en « risquées ».
        for fp in _file_mod_re.findall(cmd):
            if len(files_before) >= 12:
                break
            if fp.startswith('/'):
                data = _get_file_data_cached(fp)
                if data[0]:
                    files_before[fp] = data
    output = secure_execute_with_retry(cmd)
    dur = int((time.perf_counter() - t0) * 1000)
    out_len = len(output)

    diff = ''
    if risky and files_before:
        dp = []
        for fp, (ok, size, mtime_before, bc) in files_before.items():
            new_mtime = None
            try:
                new_mtime = os.path.getmtime(fp)
            except OSError as _e:
                # `issues` n'existait pas dans cette portée : le handler lui-même
                # levait NameError. Déclenché dès qu'une commande risquée SUPPRIME
                # un fichier (getmtime échoue) — le diff était alors perdu et l'agent
                # recevait « Erreur outil: name 'issues' is not defined ».
                logging.warning("[_run_bash] mtime indisponible pour %s : %s", fp, _e)
            if new_mtime is not None and new_mtime == mtime_before:
                continue
            _invalidate_file_cache(fp)
            ad = _get_file_data_cached(fp)
            if ad[0] and ad[3] is not None and ad[3] != bc:
                dp.append(generate_diff_html(bc, ad[3], fp))
        diff = ''.join(dp)

    display = output[:_DISPLAY_LIMIT]
    if out_len > _DISPLAY_LIMIT:
        dl = display.count('\n')
        display += f"\n…[tronqué — {out_len} chars, {dl} lignes]"
    extra = " data-risky='1'" if risky else ""
    tip = f" title='{dur}ms'" if risky else ""
    html = (f"<div class='exec-block'{extra}{tip}>"
            f"<code class='exec-cmd'>$ {cmd}</code>"
            f"<pre class='exec-output'>{display}</pre></div>")
    content = output[:_TOOL_LIMIT]
    if out_len > _TOOL_LIMIT:
        lines = content.count('\n')
        content += f"\n\n⚠️ OUTPUT TRONQUÉ : {out_len} chars > {_TOOL_LIMIT} limite. Environ {lines} lignes transmises."
    return html, content, dur, diff


def _remote_exec(target: str, cmd: str) -> tuple:
    """Exécution à distance via SSH."""
    target_stripped = target.strip()
    cmd_stripped = cmd.strip()
    server = _load_servers_once()[1].get(target_stripped)  # même cache que le global, sans dépendre du premier tour
    if not server:
        return None, f"Machine '{target_stripped}' introuvable", "#e0564a"
    try:
        t = time.perf_counter()
        out, err, rc = _ms_ssh_exec(server, cmd_stripped, timeout=60)
        dur = int((time.perf_counter() - t) * 1000)
        combined = out or ''
        if err and err.strip():
            combined += '\n[stderr] ' + err.strip()
        if rc != 0:
            combined += '\n[exit ' + str(rc) + ']'
        # LE TRIPLET, ET IL MANQUAIT SUR LE SEUL CHEMIN QUI REUSSIT.
        # L'executeur fait `result, content, color = handler(args)` : ce
        # couple levait `ValueError` a chaque execution ABOUTIE, tandis que
        # les deux chemins d'echec, eux, rendaient bien trois valeurs.
        # L'outil ne marchait donc que quand il ratait — et l'erreur ne
        # ressemblait en rien a sa cause.
        return (out, err, rc, dur), combined, "#4a9eff"
    except Exception as e:
        return None, str(e), "#e0564a"


def _pont_fil(compte: str) -> int:
    """Le fil « Pont · compte » du salon (origine `pont`), créé au premier usage,
    rouvert s'il était clos. Les résidents le voient (origine ≠ solo) ; les
    comptes ordinaires n'ont pas le salon — seul l'admin le lit à l'écran."""
    titre = "Pont · " + compte
    conn = _salon_conn()
    try:
        x = conn.execute("SELECT id, statut FROM salon_fils WHERE origine='pont' AND titre=? ORDER BY id DESC LIMIT 1",
                         (titre,)).fetchone()
        if x:
            if (x["statut"] or "") != "ouvert":
                conn.execute("UPDATE salon_fils SET statut='ouvert' WHERE id=?", (int(x["id"]),)); conn.commit()
            return int(x["id"])
        cur = conn.execute("INSERT INTO salon_fils (titre, but, par, origine) VALUES (?,?,?,?)",
                           (titre, "questions du bureau de %s à Itare Citadelle — lecture seule" % compte,
                            "bureau:" + compte, "pont"))
        conn.commit()
        return int(cur.lastrowid)
    finally:
        conn.close()


def _citadelle_demander_impl(args: dict) -> tuple:
    """LE PONT bureau → Citadelle : la question part dans le fil Pont du compte,
    adressée à Itare Citadelle ; on attend sa réponse (deux minutes), on la rend."""
    q = str(args.get("question") or "").strip()
    if not q:
        return {"ok": False}, "Question vide.", "#e0564a"
    compte = str(origine_courante().get("acteur") or "").strip()
    if not compte or compte in _SALON_RESIDENTS:
        return {"ok": False}, "Le pont se prend depuis le bureau d'un compte.", "#e0564a"
    try:
        fil = _pont_fil(compte)
        r = salon_dire(fil, "bureau:" + compte, ["itare"],
                       "[Question du bureau de %s, via son Itare]\n%s" % (compte, q[:2000]),
                       sources=["pont"], humain=True)
    except Exception as e:
        return {"ok": False}, "Le pont n'a pas pu poser la question : %s" % str(e)[:200], "#e0564a"
    if not r.get("ok"):
        return r, "Le pont n'a pas pu poser la question : %s" % (r.get("reason") or "?"), "#e0564a"
    depuis, fin = int(r["id"]), time.time() + 120
    while time.time() < fin:
        conn = _salon_conn()
        try:
            x = conn.execute("SELECT id, corps FROM salon_messages WHERE fil=? AND id>? AND auteur='itare' ORDER BY id LIMIT 1",
                             (fil, depuis)).fetchone()
        finally:
            conn.close()
        if x:
            return ({"ok": True, "fil": fil, "reponse": x["corps"]},
                    "Itare Citadelle répond :\n" + (x["corps"] or ""), "#7c5cfc")
        time.sleep(2.0)
    return ({"ok": False, "fil": fil, "attente": True},
            "Itare Citadelle n'a pas répondu dans les deux minutes (fil « Pont » n°%d) : repose la question un peu plus tard." % fil,
            "#e0564a")


def _memoire_rappel_impl(args: dict) -> tuple:
    r = memoire_rappel_poser(str(args.get("key") or ""), str(args.get("metrique") or ""), str(args.get("op") or ""),
                             args.get("seuil"), str(args.get("message") or ""))
    if r.get("ok"):
        return r, "✅ Rappel posé [R:%d] : quand %s %s %s → « %s »" % (r["id"], args.get("metrique"), args.get("op"), args.get("seuil"), str(args.get("message"))[:120]), "#00c896"
    return r, "⚠️ Rappel refusé : %s" % r.get("erreur"), "#e0564a"


def _remember_impl(args: dict) -> tuple:
    key = str(args.get("key", ""))[:120]
    value = str(args.get("value", ""))[:500]
    prov = str(args.get("provenance") or "infere").strip().lower()
    tour = _memoire_tour_courant()
    note = ""
    # LA PIÈCE EST LE MESSAGE (20-09) : ce que l'utilisateur vient de dire fonde le fait. Sans elle, chaque
    # souvenir de l'outil portait « aucune : dette de preuve ».
    piece = None
    if tour.get("question"):
        piece = {"type": "message", "source_table": "conversations",
                 "contenu": memoire_piece_du_tour(tour["question"], tour.get("debut"), get_current_user() or None),
                 "date": tour.get("debut") or _memoire_now()}
    # « OBSERVE » SE PROUVE : aucun geste de cage depuis le début du tour, donc rien n'a été mesuré — ce que
    # l'outil retient, c'est ce qu'on lui a DIT. Le modèle écrivait « hostname vérifié » sans rien avoir vérifié.
    if prov == "observe" and tour.get("debut") and memoire_actes_depuis(tour["debut"], get_current_user() or None) == 0:
        prov = "dit"
        note = " · provenance ramenée à « dit » : rien n'a été mesuré dans ce tour"
    r = memoire_ecrire(args.get("category", "fact"), key, value, provenance=prov,
                       # Le muet passe TEL QUEL : une valeur par défaut posée ICI comblerait le
                       # silence avant la porte, et rangerait d'office celui qui n'a pas répondu.
                       nature=args.get("nature"), sonde=args.get("sonde"),
                       sonde_args=args.get("sonde_args"), piece=piece,
                       confiance=float(args.get("confidence", 0.9) or 0.9), declencheur="outil_remember")
    if r.get("ok"):
        verbe = {"ecriture": "Retenu", "remplace": "Retenu, version nouvelle (l'ancienne expire)",
                 "quarantaine": "Retenu en QUARANTAINE : critique, il attend le veto d'Itare avant d'être servi",
                 "conteste": "Retenu en CONTESTÉ : une version plus forte existe, elle reste servie",
                 "inchange": "Déjà su, inchangé"}.get(r.get("action"), "Retenu")
        if r.get("rapproche_de"):
            note += " · même fait que la clé « %s » : rangé comme sa nouvelle version" % r.get("cle")
        return r, "✅ %s [M:%d]%s" % (verbe, r["id"], note), "#00c896"
    raisons = {"secret": "un secret ne va pas en mémoire : range-le dans le coffre (vault_store_secret)",
               "consigne": "un souvenir est un fait, jamais une consigne",
               "spi": "rien sur la santé, l'argent, les opinions ou l'humeur",
               "cle": "la clé doit être 2 à 6 mots-clés, pas une phrase",
               "categorie": "catégorie hors vocabulaire", "quota": "quota d'écriture atteint, réessaie plus tard",
               "sujet": "ce compte ne touche pas ce site", "piece_ancienne": "la pièce est antérieure à la version active",
               "nature": "dis ce qu'est ce souvenir : « constat » (daté, jamais relu) ou « etat-courant » "
                         "avec une sonde qui le rejoue — fonction_existe, fonction_absente, "
                         "fonction_contient, constante_vaut",
               "sonde": "la sonde n'a pas répondu OUI : on n'écrit pas un fait que la mesure ne "
                        "confirme pas maintenant"}
    return r, "⚠️ Refusé (%s) : %s" % (r.get("refus"), raisons.get(r.get("refus"), r.get("detail") or "")), "#e0564a"


def _fleet_list_impl(servers: list) -> tuple:
    if not servers:
        return servers, "Flotte vide — aucune machine ajoutée.", "#7c5cfc"
    # Le dernier état OBSERVÉ, lu en base : l'agent citait la liste des machines
    # sans jamais savoir laquelle était tombée.
    vus = {}
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=5)
        vus = {r[0]: (r[1], r[2]) for r in
               conn.execute("SELECT name, online, since FROM fleet_state_seen")}
        conn.close()
    except Exception:
        pass
    lines = []
    for t in servers:
        etat = vus.get(t["name"])
        if etat is None:
            obs = "état inconnu"
        elif etat[0]:
            obs = "● en ligne"
        else:
            obs = "○ HORS LIGNE depuis %s" % (etat[1] or "?")
        lines.append(
            f"{_EMOJI_MAP.get(t.get('type', 'cassandra'), '🖥')} {t['name']} "
            f"[{t.get('type', 'cassandra')}] — "
            f"{t.get('ssh_host') or t.get('syn_host') or t.get('syn_qc') or t.get('url', '')} "
            f"{'✓ actif' if t.get('enabled', True) else '✗ désactivé'} · {obs}")
    return servers, "Machines dans la flotte :\n" + "\n".join(lines), "#7c5cfc"


def _site_health_impl(args: dict) -> tuple:
    """Disponibilité MESURÉE des sites — et ce que le CMS trahit."""
    jours = int(args.get("days", 30) or 30)
    r = site_availability(jours)
    if not r.get("ok"):
        return r, "Disponibilité indisponible : %s" % r.get("reason", ""), "#e0564a"
    lst = r.get("sites") or []
    if not lst:
        return r, ("Aucune mesure enregistrée. La veille des sites n'a pas encore tourné "
                   "— revenir après le prochain cycle."), "#e8c660"
    lignes = []
    for x in lst:
        a, ms = x.get("availability"), x.get("response_avg_ms")
        lignes.append("· %s : %s, %s — %d panne(s), %s hors ligne"
                      % (x["domain"], ("%.2f %%" % a) if a is not None else "—",
                         ("%d ms" % ms) if ms is not None else "temps inconnu",
                         x.get("outages", 0), x.get("downtime", "0 min")))
    txt = "Disponibilité des sites sur %d jours :\n%s" % (r["days"], "\n".join(lignes))
    lents = [x["domain"] for x in lst
             if x.get("response_avg_ms") and x["response_avg_ms"] >= _SITE_LENT_MS]
    if lents:
        txt += ("\n\nSites lents (au-delà de %d ms, le visiteur les croit en panne) : %s"
                % (_SITE_LENT_MS, ", ".join(lents)))
    try:
        cms = (site_cms() or {}).get("cms") or []
        if cms:
            txt += "\n\nContenu détecté :\n" + "\n".join(
                "· %s : %s %s" % (c["domain"], c.get("type") or "?",
                                  c.get("version") or "(version inconnue)") for c in cms[:20])
    except Exception as e:
        logging.debug("[SITES] cms : %s", e)
    return r, txt, "#7c5cfc"


def _fleet_health_impl(args: dict) -> tuple:
    """Disponibilité réelle de la flotte, mesurée — pas devinée."""
    jours = int(args.get("days", 30) or 30)
    r = fleet_availability(jours)
    if not r.get("ok"):
        return r, "Disponibilité indisponible : %s" % r.get("reason", ""), "#ffa502"
    m = r.get("machines") or []
    if not m:
        return r, ("Aucune mesure enregistrée. La passe de flotte n'a pas encore tourné "
                   "— revenir après le prochain cycle."), "#ffa502"
    lignes = []
    for x in m:
        a = x.get("availability")
        lignes.append("· %s : %s%s — %d panne(s), %s hors ligne"
                      % (x["name"], ("%.2f %%" % a) if a is not None else "—",
                         "" if a is None or a >= 99 else "  ⚠",
                         x.get("outages", 0), x.get("downtime", "0 min")))
    hs = [x["name"] for x in m if (x.get("availability") or 100) < 100]
    txt = ("Disponibilité sur %d jours :\n%s" % (r["days"], "\n".join(lignes)))
    if hs:
        txt += "\n\nMachines ayant connu au moins une coupure : " + ", ".join(hs)
    return r, txt, "#7c5cfc"


