def _itare_panel_impl(args: dict) -> tuple:
    task = (args.get("task") or "").strip()
    if not task:
        return (False, "tâche requise pour le panel Itare", "#e0564a")
    # APPELE PAR CASSANDRA, donc le panel de la Citadelle — et c'est elle
    # l'administration, le droit suit.
    r = itare_panel(task, portee="citadelle", admin=True)
    if not r.get("ok"):
        return (False, "🜂 Panel : " + str(r.get("reason") or "indisponible"), "#e0564a")
    ans = r.get("answers", {})
    parts = []
    for role in ("sceptique", "securite", "synthese"):
        if ans.get(role):
            parts.append("• %s : %s" % (role.upper(), ans[role]))
    dis = r.get("disagreement")
    head = "🜂 Panel Itare" + (" — ⚠️ DÉSACCORD (à trancher)" if dis else
                               (" — consensus" if dis is False else ""))
    txt = head + "\n" + "\n".join(parts)
    return (txt, txt, "#bd93f9")


