def _itare_zip_impl(args: dict) -> tuple:
    """Fabrique une archive et la range dans « Mes documents ».

    ELLE NE PART NULLE PART. Ranger n'est pas envoyer : l'archive apparaît dans
    les Documents du compte, avec son bouton de téléchargement. L'envoyer par
    courriel reste un geste à part, avec son mandat.
    """
    # `io` et `zipfile` NE SONT PAS des noms globaux de ce fichier : sans ces
    # imports, l'outil leve un NameError la premiere fois qu'on s'en sert.
    import io
    import zipfile
    compte = get_current_user() or ""
    # L'ENVOI SE DÉCIDE AVANT DE COMPRESSER. Refuser après aurait laissé une
    # archive que personne n'a demandé à garder, et fait travailler la machine
    # pour rien. Les verrous sont CEUX DE TOUT ENVOI — la même fonction.
    _dest = (args.get("courriel") or "").strip()
    if _dest:
        _refus = _envoi_verrous()
        if _refus:
            return _refus
    nom = (args.get("nom") or "").strip() or "archive"
    nom = re.sub(r"[^\w .()\[\]-]", "_", os.path.basename(nom))[:120]
    if not nom.lower().endswith(".zip"):
        nom += ".zip"

    fichiers = []
    # LES PIÈCES DE LA SESSION : ce que la personne vient de déposer.
    _ids = args.get("pieces") or []
    if isinstance(_ids, (str, int)):
        _ids = [_ids]
    fichiers.extend(lab_pieces_octets(_ids, compte))

    # LES NOTES : résolues par le garde du dossier, qui neutralise toute
    # évasion et borne sur l'espace DU COMPTE.
    _refs = args.get("notes") or []
    if isinstance(_refs, str):
        _refs = [_refs]
    absents = []
    for ref in _refs[:200]:
        p = _itare_ws_safe(str(ref))
        if not p or not os.path.isfile(p):
            absents.append(str(ref))
            continue
        try:
            with open(p, "rb") as f:
                fichiers.append((os.path.basename(p), f.read()))
        except Exception:
            absents.append(str(ref))

    if not fichiers:
        return (False, "🗜 Rien à compresser : donne-moi des pièces (`pieces`) "
                       "ou des notes (`notes`)." +
                (" Introuvables : %s." % ", ".join(absents[:6]) if absents else ""),
                "#e0564a")

    total = sum(len(o) for _n, o in fichiers)
    if total > _GED_DEPOT_MAX:
        return (False, "🗜 %s à compresser, au-delà de la limite de dépôt (%s). "
                       "Fais-en plusieurs archives."
                % (_ged_octets(total), _ged_octets(_GED_DEPOT_MAX)), "#e0564a")

    # DEUX FICHIERS DE MÊME NOM ne peuvent pas coexister dans une archive : le
    # second écraserait le premier en silence. On numérote plutôt que de perdre.
    vus, tampon = {}, io.BytesIO()
    try:
        with zipfile.ZipFile(tampon, "w", zipfile.ZIP_DEFLATED) as z:
            for n, o in fichiers:
                base = os.path.basename(n) or "fichier"
                if base in vus:
                    vus[base] += 1
                    rac, ext = os.path.splitext(base)
                    base = "%s (%d)%s" % (rac, vus[base], ext)
                else:
                    vus[base] = 1
                z.writestr(base, o)
    except Exception as e:
        return (False, "🗜 Compression impossible : %s" % str(e)[:120], "#e0564a")

    octets = tampon.getvalue()
    d = ged_dossier_compte_creer(compte)
    if not d.get("ok"):
        return (False, "🗜 Dossier de documents indisponible : %s"
                % (d.get("reason") or "?"), "#e0564a")
    dep = ged_deposer("local:" + d["dossier"], "", nom,
                      base64.b64encode(octets).decode())
    if not dep.get("ok"):
        return (False, "🗜 Dépôt refusé : %s" % (dep.get("reason") or "?"),
                "#e0564a")
    trace_poser("archive_creee", "Archive « %s » (%d fichier(s))"
                % (nom, len(fichiers)))
    msg = ("🗜 « %s » créée — %d fichier(s), %s, rangée dans Mes documents."
           % (nom, len(fichiers), _ged_octets(len(octets))))
    if absents:
        msg += " Introuvables : %s." % ", ".join(absents[:6])

    # ── ET L'ENVOI, s'il a été demandé ──────────────────────────────────
    if _dest:
        _chemin = os.path.join(d["dossier"], nom)
        _obj = (args.get("objet") or "").strip() or nom
        _corps = (args.get("message") or "").strip() or (
            "Bonjour,\n\nVous trouverez ci-joint « %s ».\n" % nom)
        # `_mail_joindre` REFAIT le confinement sur ce chemin, alors qu'il
        # sort d'un dossier qu'on vient de déclarer : une pièce jointe est le
        # moyen le plus discret de faire sortir un fichier, et ce contrôle-là
        # doit tenir même si un appelant futur oublie le sien.
        _env = itare_mail_send(_dest, _obj, _corps, pieces=[_chemin])
        if not _env.get("ok"):
            return (False, "%s Mais l'envoi a échoué : %s"
                    % (msg, _env.get("reason") or "?"), "#e0564a")
        try:
            log_action("", "tool:itare_zip", "-> %s / %s"
                       % (_dest[:80], nom[:60]), 0, True, False)
        except Exception:
            pass
        trace_poser("courriel_envoye", "Archive « %s » envoyée à %s"
                    % (nom, _dest))
        msg += " ✉ Envoyée à %s." % _dest
        return (msg, msg, "#7bd88f")
    return (msg, msg, "#7bd88f")


def _itare_project_update_impl(args: dict) -> tuple:
    """Crée ou met à jour un projet DU COMPTE par son nom, et date la note au journal —
    le même moteur que l'écran (`pj_projet_save`), le même compte (`_iso_compte`)."""
    name = (args.get("name") or "").strip()
    if not name:
        return (False, "nom du projet requis", "#e0564a")
    p = pj_trouver(name)
    if p:
        # LOT A : le rôle du demandeur d'abord (fiche = co-propriétaire, journal = auteur), puis les droits d'Itare.
        _fiche = any(args.get(k) for k in ("status", "kind", "domain", "server", "objectif", "resume", "perimetre_in",
                                            "perimetre_out", "reussite", "dossier_vault", "nature"))
        for _g, _veut in (("fiche", _fiche), ("ecrire", bool(args.get("note")))):
            if _veut and not pj_peut(p["id"], _g):
                return (False, "Je ne peux pas : %s. J'agis avec les droits de la personne qui me le demande."
                        % _pj_refus(p["id"], _g)["reason"], "#e0564a")
        _dr = pj_droits_itare(p)
        if not _dr.get("fiche") and any(args.get(k) for k in (
                "status", "kind", "domain", "server", "objectif", "resume", "perimetre_in",
                "perimetre_out", "reussite", "dossier_vault", "nature")):
            return (False, "Dans « %s », le droit « modifier la fiche » est retiré à Itare." % name, "#e0564a")
        if args.get("note") and not _dr.get("journal"):
            return (False, "Dans « %s », le droit « écrire au journal » est retiré à Itare." % name, "#e0564a")
    r = pj_projet_save(pid=(p["id"] if p else None), name=name, status=args.get("status"),
                       append_note=args.get("note"), kind=args.get("kind"),
                       domain=args.get("domain"), server=args.get("server"),
                       objectif=args.get("objectif"), resume=args.get("resume"),
                       perimetre_in=args.get("perimetre_in"), perimetre_out=args.get("perimetre_out"),
                       reussite=args.get("reussite"), dossier_vault=args.get("dossier_vault"),
                       nature=args.get("nature"))
    if r.get("ok"):
        _anch = args.get("domain") or args.get("server") or args.get("dossier_vault")
        return (True, "🗂 Projet « %s » %s dans ton carnet.%s"
                % (name, "ouvert" if r.get("cree") else "mis à jour",
                   (" Ancré sur %s." % _anch) if _anch else ""), "#27c168")
    return (False, "Carnet : %s" % r.get("reason"), "#e0564a")


def _itare_event_add_impl(args: dict) -> tuple:
    summary = (args.get("summary") or "").strip()
    start = (args.get("start_at") or "").strip().replace("T", " ")[:16]
    if not summary or not start:
        return (False, "titre et date de début requis", "#e0564a")
    # Une date inexploitable est refusée plutôt qu'enregistrée de travers : un
    # événement à la mauvaise date est pire qu'un événement absent.
    if not re.match(r"^\d{4}-\d{2}-\d{2}( \d{2}:\d{2})?$", start):
        return (False, "date « %s » non exploitable — attendu AAAA-MM-JJ [HH:MM]" % start[:30], "#e0564a")
    all_day = 1 if len(start) == 10 else 0
    pid = None
    pname = (args.get("project") or "").strip()
    if pname:
        p = pj_trouver(pname)
        if not p:
            cr = pj_projet_save(name=pname)
            pid = cr.get("id") if cr.get("ok") else None
        else:
            pid = p["id"]
    r = itare_event_save(summary, start, end_at=(args.get("end_at") or ""),
                         description=(args.get("description") or ""),
                         location=(args.get("location") or ""),
                         all_day=all_day, project_id=pid)
    if not r.get("ok"):
        return (False, "Agenda : %s" % r.get("reason"), "#e0564a")
    bits = ["📅 Événement ajouté : %s — %s" % (summary[:110], start)]
    if args.get("location"):
        bits.append("à " + str(args["location"])[:60])
    if pname:
        bits.append("projet « %s »" % pname)
    return (True, " · ".join(bits), "#f1c40f")


def _contact_find_impl(args: dict) -> tuple:
    """Recherche de contacts pour un agent. La vue renvoyée est expurgée dès que
    l'inférence est distante — c'est `contact_public` qui en décide, pas ici."""
    dom = (args.get("domain") or "").strip()
    proj = (args.get("project") or "").strip()
    q = (args.get("query") or "").strip()
    if dom:
        r = contact_for_domain(dom)
        gens, titre = r.get("contacts", []), "responsables de %s (via %s)" % (dom, r.get("via") or "aucun lien")
    elif proj:
        p = pj_trouver(proj)
        gens = contacts_of("project", str(p["id"])) if p else []
        titre = "intervenants du projet %s" % proj
    else:
        gens = contact_list(q, limit=25).get("contacts", [])
        titre = "contacts correspondant à « %s »" % q if q else "contacts"
    vue = contacts_public(gens)
    if not vue:
        return (vue, "Aucun contact trouvé (%s)." % titre, "#8a8a9a")
    lignes = []
    for c in vue:
        bouts = [c.get("display_name") or "?"]
        if c.get("role"):
            bouts.append("rôle : %s" % c["role"])
        if c.get("company"):
            bouts.append(c["company"])
        if c.get("redacted"):
            dispo = [n for n, k in (("e-mail", "has_email"), ("téléphone", "has_phone"),
                                    ("adresse", "has_address")) if c.get(k)]
            bouts.append("coordonnées non transmises (%s disponible%s)"
                         % (", ".join(dispo) or "aucune", "s" if len(dispo) > 1 else ""))
        else:
            bouts += [x for x in [", ".join(c.get("emails") or []), c.get("phone"),
                                  c.get("mobile")] if x]
        lignes.append("• [#%s] %s" % (c.get("id"), " — ".join(bouts)))
    return (vue, "%s :\n%s" % (titre.capitalize(), "\n".join(lignes)), "#00d9a3")


def _contact_add_impl(args: dict) -> tuple:
    adr = (args.get("email") or "").strip()
    r = contact_save(display_name=(args.get("display_name") or "").strip(),
                     emails=[adr] if adr else [],
                     phone=(args.get("phone") or "").strip(),
                     mobile=(args.get("mobile") or "").strip(),
                     company=(args.get("company") or "").strip(),
                     job_title=(args.get("job_title") or "").strip(),
                     notes=(args.get("notes") or "").strip(),
                     cid=args.get("id"))
    if not r.get("ok"):
        return (r, "Fiche non enregistrée : %s" % r.get("reason"), "#e0564a")
    return (r, "Fiche enregistrée (#%s)." % r.get("id"), "#2ed573")


def _contact_attach_impl(args: dict) -> tuple:
    kind = (args.get("kind") or "").strip().lower()
    ref = (args.get("ref") or "").strip()
    if kind == "project" and ref and not ref.isdigit():
        p = pj_trouver(ref)
        if not p:
            return (False, "Projet « %s » introuvable." % ref, "#e0564a")
        ref = str(p["id"])
    r = contact_link(args.get("contact_id"), kind, ref,
                     (args.get("role") or "autre").strip().lower())
    if not r.get("ok"):
        return (r, "Rattachement refusé : %s" % r.get("reason"), "#e0564a")
    return (r, "Contact #%s rattaché à %s « %s » comme %s."
            % (args.get("contact_id"), kind, ref, args.get("role") or "autre"), "#2ed573")


def _itare_task_add_impl(args: dict) -> tuple:
    text = _html.unescape((args.get("text") or "").strip())
    if not text:
        return (False, "texte de la tâche requis", "#e0564a")
    pid = None
    pname = (args.get("project") or "").strip()
    if pname:
        p = pj_trouver(pname)
        if not p:
            # On crée le projet plutôt que de perdre la tâche : l'utilisateur a
            # nommé un projet, c'est une intention suffisamment claire.
            cr = pj_projet_save(name=pname)
            pid = cr.get("id") if cr.get("ok") else None
        else:
            pid = p["id"]
    r = itare_task_save(text, project_id=pid, due=args.get("due"))
    if not r.get("ok"):
        return (False, "Tâche : %s" % r.get("reason"), "#e0564a")
    bits = ["✅ Tâche ajoutée : %s" % text[:120]]
    if pname:
        bits.append("projet « %s »" % pname)
    if r.get("due_at"):
        bits.append("échéance %s" % r["due_at"])
    return (True, " · ".join(bits), "#27c168")


_PJ_DROITS_DEFAUT = {"modifier": True, "remettre": True, "organiser": True, "fiche": True,
                     "passe": True, "journal": True}


def pj_droits_itare(p: dict) -> dict:
    """Ce qu'Itare peut faire dans ce projet (réglé dans la fiche). Tout est permis par défaut."""
    d = dict(_PJ_DROITS_DEFAUT)
    try:
        v = json.loads(str((p or {}).get("itare_droits") or "") or "{}")
        if isinstance(v, dict):
            d.update({k: bool(v[k]) for k in d if k in v})
    except Exception:
        pass
    return d


def _dossiers_impl(args: dict) -> tuple:
    """Itare et les dossiers des machines : lister, créer, mettre à la corbeille (jamais effacer). Les gardes sont
    celles des gestes de l'écran : administrateur, chemins système refusés, tour teinté refusé."""
    op = str(args.get("op") or "").strip()
    m = str(args.get("machine") or "").strip()
    ch = str(args.get("chemin") or "").strip()
    if op == "machines":
        r = pj_dossier_parcourir()
        if not r.get("ok"):
            return (False, r.get("reason") or "échec", "#e0564a")
        return (r, "Machines : " + ", ".join("%s%s" % (x["nom"], " (Windows)" if x.get("windows") else "")
                                              for x in r["machines"]), "#8be9fd")
    if op == "lister":
        r = pj_dossier_parcourir(m, ch or "/")
        if not r.get("ok"):
            return (False, r.get("reason") or "échec", "#e0564a")
        return (r, "📁 %s:%s — %d sous-dossier(s) :\n%s" % (m, r["chemin"], len(r["dossiers"]),
                                                              "\n".join(r["dossiers"]) or "(aucun)"), "#8be9fd")
    if op == "creer":
        r = pj_dossier_creer(m, ch, str(args.get("nom") or ""))
        if not r.get("ok"):
            return (False, r.get("reason") or "échec", "#e0564a")
        return (r, "📁 Dossier créé : %s:%s" % (m, r["chemin"]), "#8be9fd")
    if op == "corbeille":
        r = pj_dossier_corbeille(m, ch)
        if not r.get("ok"):
            return (False, r.get("reason") or "échec", "#e0564a")
        return (r, "🗑 À la corbeille : %s:%s → %s (il s'y reprend tel quel)." % (m, ch, r["corbeille"]), "#8be9fd")
    return (False, "op inconnue (machines, lister, creer, corbeille)", "#e0564a")


def _projet_fichier_impl(args: dict) -> tuple:
    """Itare dans le dossier d'un projet : elle modifie en place, chaque écriture est une version."""
    p = pj_trouver(str(args.get("projet") or "").strip())
    if not p:
        return (False, "Projet introuvable : %s" % (args.get("projet") or ""), "#e0564a")
    pid, op = p["id"], str(args.get("op") or "lister").strip()
    ch = str(args.get("chemin") or "").strip()
    droits = pj_droits_itare(p)
    # LOT A : D'ABORD le rôle de la personne qui demande (le compte courant), ENSUITE les droits d'Itare.
    _ecrit = op in ("ecrire", "remplacer", "creer", "remettre", "deplacer", "dossier", "retirer")
    if _ecrit and not pj_peut(pid, "ecrire"):
        return (False, "Je ne peux pas : %s. J'agis avec les droits de la personne qui me le demande."
                % _pj_refus(pid, "ecrire")["reason"], "#e0564a")
    besoin = {"ecrire": "modifier", "remplacer": "modifier", "creer": "modifier", "remettre": "remettre",
              "deplacer": "organiser", "dossier": "organiser", "retirer": "organiser"}.get(op)
    if besoin and not droits.get(besoin):
        return (False, "Dans « %s », le droit « %s » est retiré à Itare (fiche du projet › Itare dans ce projet)."
                % (p.get("name"), besoin), "#e0564a")
    if op == "chercher":
        # « la note test », « le chapitre 13 », « Kormis » : on cherche le NOM dans tout le dossier du projet.
        import unicodedata as _ud
        _n = lambda x: "".join(k for k in _ud.normalize("NFD", str(x)) if _ud.category(k) != "Mn").lower()
        q = _n(str(args.get("question") or ch or "").strip().strip("/"))
        if not q:
            return (False, "Chercher : donne un nom (chemin = « test », « Chapitre 13 »…)", "#e0564a")
        idx = atelier_index(pid)
        if not idx.get("ok"):
            return (False, "Chercher : %s" % idx.get("reason"), "#e0564a")
        tous = (idx.get("notes") or []) + (idx.get("medias") or [])
        nom = lambda x: _n(_coffre_sans_md(x.rsplit("/", 1)[-1]))
        exacts = [x for x in tous if nom(x) == _n(_coffre_sans_md(q.rsplit("/", 1)[-1]))]
        proches = [x for x in tous if q in _n(x) and x not in exacts]
        L = (exacts + sorted(proches, key=len))[:40]
        if not L:
            return ({"ok": True, "chemins": []}, "🔎 Aucun fichier du dossier ne porte « %s » dans son nom (%d fichiers regardés)."
                    % (args.get("question") or ch, len(tous)), "#8be9fd")
        return ({"ok": True, "chemins": L}, "🔎 %d fichier(s) pour « %s »%s :\n%s" % (
            len(L), args.get("question") or ch, " (nom exact en tête)" if exacts else "", "\n".join("- " + x for x in L)), "#8be9fd")
    if op == "lister":
        r = atelier_lister(pid, ch)
        if not r.get("ok"):
            return (False, "Dossier : %s" % r.get("reason"), "#e0564a")
        txt = "📁 %s/%s\n%s" % (p.get("name"), r["dossier"], "\n".join(
            ("%s/" % i["nom"]) if i["dossier"] else "%s  (%d o, %s)" % (i["nom"], i["taille"], i["modifie"]) for i in r["items"][:300]))
        return (r, txt, "#8be9fd")
    if op == "lire":
        r = atelier_lire(pid, ch)
        if not r.get("ok"):
            return (False, "Lecture : %s" % r.get("reason"), "#e0564a")
        if r.get("binaire"):
            return (r, "%s : fichier non textuel (%d o)." % (r["chemin"], r["taille"]), "#8be9fd")
        return (r, "📄 %s (%d o, modifié %s)\n\n%s" % (r["chemin"], r["taille"], r["modifie"], r["texte"][:60000]), "#8be9fd")
    if op in ("ecrire", "creer"):
        r = atelier_ecrire(pid, ch, str(args.get("texte") or ""), "", "Itare", creer=(op == "creer"))
    elif op == "remplacer":
        r = atelier_remplacer(pid, ch, str(args.get("ancien") or ""), str(args.get("nouveau") or ""), "Itare")
    elif op == "deplacer":
        r = atelier_deplacer(pid, ch, str(args.get("vers") or ""), "Itare")
    elif op == "dossier":
        r = atelier_dossier_creer(pid, ch)
    elif op == "retirer":
        r = atelier_retirer(pid, ch, "Itare")
        if r.get("ok") and r.get("dossier"):
            return (r, "🗑 Dossier « %s » mis à la corbeille : %s (il s'y reprend tel quel)." % (r["chemin"], r["corbeille"]), "#8be9fd")
    elif op == "versions":
        r = atelier_versions(pid, ch)
        if r.get("ok"):
            txt = "🕘 Versions de %s (rangées dans %s) :\n%s" % (r["chemin"], r["rangees"], "\n".join(
                "v%d · %s · %s%s" % (v["n"], v["auteur"], v["ts"], (" — " + v["note"]) if v["note"] else "") for v in r["versions"]))
            return (r, txt, "#8be9fd")
    elif op == "voir":
        r = atelier_voir(pid, ch, str(args.get("question") or ""))
        if not r.get("ok"):
            return (r, "Voir : %s" % r.get("reason"), "#e0564a")
        return (r, "🖼️ %s — regardée par %s (%d s) :\n%s" % (r["chemin"], r["modele"], r["secondes"], r["description"]), "#8be9fd")
    elif op == "remettre":
        r = atelier_remettre(pid, ch, int(args.get("version") or 0), "Itare")
    else:
        return (False, "Opération inconnue : %s" % op, "#e0564a")
    if not r.get("ok"):
        return (r, "Échec : %s" % r.get("reason"), "#e0564a")
    try:
        pj_projet_save(pid=pid, append_note="Itare · %s %s%s" % (op, ch, (" → v%s" % r["version"]) if r.get("version") else ""))
    except Exception:
        pass
    return (r, "Fait : %s" % "; ".join("%s=%s" % (k, v) for k, v in r.items() if k not in ("ok", "texte", "octets")), "#27c168")


def _itare_project_notes_impl(args: dict) -> tuple:
    """Les notes du dossier d'un projet, les plus récentes d'abord (lecture seule)."""
    p = pj_trouver((args.get("name") or "").strip())
    if not p:
        return (False, "Projet introuvable : %s" % (args.get("name") or ""), "#e0564a")
    dv = str(p.get("dossier_vault") or "") if isinstance(p, dict) else ""
    if not dv:
        return (False, "Le projet « %s » n'est ancré sur aucun dossier (dossier_vault)." % p.get("name"), "#e0564a")
    inv = pj_inventaire(dv, recents=max(1, min(int(args.get("limit") or 30), 200)))
    if not inv.get("ok"):
        return (False, "Notes : %s" % inv.get("reason"), "#e0564a")
    txt = "📚 %s — %d notes, %.0f Ko, dernière touchée %s :\n%s" % (
        dv, inv["n"], inv["octets"] / 1024, inv["derniere"] or "—",
        "\n".join("• %s — %s (%d o)" % (r["quand"], r["note"], r["octets"]) for r in inv["recents"]))
    return (inv, txt, "#8be9fd")


def _itare_project_brief_impl(args: dict) -> tuple:
    """La vue complète d'un projet, par le moteur : plan, jalons, décisions, tâches,
    infrastructure, activité, ancrages, santé — et ce qui n'a pas pu être regardé."""
    p = pj_trouver(args.get("name") or "")
    if not p:
        return (False, "Projet introuvable : %s" % (args.get("name") or ""), "#e0564a")
    ctx = pj_contexte(p["id"])
    if not ctx.get("ok"):
        return (False, "Projet : %s" % ctx.get("reason"), "#e0564a")
    pr, inf, act, cpt = ctx["projet"], ctx["infra"], ctx["activite"], ctx["compte"]
    L = ["🗂 %s [%s · %s] — %s %d/100, avancement %s"
         % (pr["name"], pr.get("status") or "actif", ctx["modele"]["nom"],
            ctx["sante"]["verdict"], ctx["sante"]["score"],
            ("%d %% (%s)" % (ctx["avancement"]["global"], ctx["avancement"].get("detail") or ""))
            if ctx["avancement"].get("mesure") else "non mesuré")]
    if ctx["journal"]:
        L.append("Dernière note : " + ctx["journal"][0]["texte"][:160])
    if ctx["phases"]:
        L.append("Plan : " + " ; ".join("%s (%s)" % (x["nom"], x["etat"]) for x in ctx["phases"]))
    proches = [j for j in ctx["jalons"] if j.get("etat") in ("", "prevu", None)]
    if proches:
        L.append("Étapes à venir : " + " ; ".join("%s %s" % (j.get("date"), j.get("nom")) for j in proches[:5]))
    ouvertes = [d for d in ctx["decisions"] if d.get("etat") == "ouverte"]
    if ouvertes:
        L.append("Décisions à trancher (%d) : " % len(ouvertes) + " ; ".join(d["question"] for d in ouvertes[:4]))
    todo = [t for t in ctx["taches"] if t["status"] not in _ITARE_TASK_FERMES]
    if todo:
        L.append("Tâches ouvertes (%d) :" % len(todo))
        for t in todo[:8]:
            L.append("  • %s%s" % (t["text"][:110],
                                   (" — échéance %s" % t["due_at"]) if t["due_at"] else ""))
    else:
        L.append("Aucune tâche ouverte.")
    if cpt.get("attente"):
        L.append("En attente d'un tiers : %d" % cpt["attente"])
    _dv = str((ctx.get("projet") or {}).get("dossier_vault") or "")
    if _dv:
        _inv = pj_inventaire(_dv, recents=5)
        if _inv.get("ok"):
            L.append("Notes (%s) : %d notes, %.0f Ko, dernière touchée %s" % (
                _dv, _inv["n"], _inv["octets"] / 1024, _inv["derniere"] or "—"))
            for r in _inv["recents"]:
                L.append("  • %s — %s" % (r["quand"], r["note"][:110]))
        else:
            L.append("Notes (%s) : %s" % (_dv, _inv.get("reason")))
    if inf.get("ssl"):
        L.append("SSL %s : %s jours restants" % (inf["domain"], inf["ssl"].get("days_left", "?")))
    if inf.get("site"):
        L.append("Site : %s (%s)" % (inf["domain"], inf["site"].get("status", "?")))
    if inf.get("fleet"):
        L.append("Serveur %s : %s" % (inf["server"],
                                      "en ligne" if inf["fleet"].get("online") else "HORS LIGNE"))
    if act.get("findings"):
        L.append("⚠️ Alertes ouvertes (%d) :" % len(act["findings"]))
        for f in act["findings"][:4]:
            L.append("  • [%s] %s" % (f.get("severity"), str(f.get("title"))[:100]))
    if act.get("actions"):
        L.append("Dernières commandes liées :")
        for a in act["actions"][:4]:
            L.append("  • %s — %s" % (str(a.get("ts"))[:16], str(a.get("command"))[:90]))
    if ctx["ancrages"]:
        L.append("Rattachés : " + ", ".join("%s:%s" % (l["kind"], l["ref"][:40])
                                            for l in ctx["ancrages"][:8]))
    muets = [x["nom"] for x in ctx["sante"]["signaux"] if x["niveau"] == "muet"]
    if muets:
        L.append("(non évalué : %s)" % ", ".join(muets))
    if inf.get("errors"):
        L.append("(sources indisponibles : %s)" % "; ".join(inf["errors"][:2]))
    return (ctx, "\n".join(L), "#6c5ce7")


