def _itare_mail_uids(args: dict) -> list:
    """Les uid passés par le modèle : un seul, ou plusieurs séparés par des
    virgules / espaces. `_uid_set` n'accepte que des entiers un par un."""
    brut = args.get("uids")
    if isinstance(brut, list):
        vals = [str(x) for x in brut]
    else:
        vals = re.split(r"[\s,]+", str(brut or ""))
    return [v.strip() for v in vals if v.strip().isdigit()]


