def _mandat_declencher_impl(args: dict) -> tuple:
    """L'agent passe par ici, comme tout le reste. Aucun chemin plus court
    n'existe : c'est le seul point du programme d'où un agent peut faire partir
    un e-mail, et il n'y choisit ni l'adresse, ni le texte, ni le fichier."""
    nom = str((args or {}).get("mandat") or "").strip()
    if not nom:
        return (False, "Nom du mandat requis — appelle d'abord mandats_list.", "#e0564a")
    ctx = {"reference": str(args.get("reference") or "").strip(),
           "variables": args.get("variables") if isinstance(args.get("variables"), dict) else {}}
    if args.get("essai"):
        p = mandat_preparer(nom, ctx, essai=True)
        if not p.get("ok"):
            m = "🚫 Essai refusé : %s" % p.get("reason")
            return (False, m, "#e0564a")
        m = ("✅ Essai — rien n'a été mis en file.\nMandat : %s\nDestinataire : %s (%s)\n"
             "Objet : %s\nPièce : %s"
             % (p["mandat"], ", ".join(p["destinataires"]), p["via"], p["objet"],
                (p.get("piece") or {}).get("nom") or "aucune"))
        return (m, m, "#8be9fd")
    r = mandat_declencher(nom, ctx)
    if not r.get("ok"):
        m = "🚫 Envoi refusé (%s) : %s" % (r.get("refus") or "règle", r.get("reason"))
        return (False, m, "#e0564a")
    if r.get("attente"):
        m = ("⏸ Préparé et EN ATTENTE DE L'ACCORD de l'utilisateur.\nMandat : %s\n"
             "À : %s\nObjet : %s%s\n\nRien n'est parti. Dis-le-lui : il approuve depuis "
             "Courrier → Mandats, ou depuis la notification."
             % (r["mandat"], ", ".join(r.get("destinataires") or []), r.get("objet", ""),
                "\n(le tour a été teinté par une lecture extérieure : l'accord devient "
                "obligatoire)" if r.get("teinte_declasse") else ""))
        return (m, m, "#f1c440")
    if r.get("controle") == "differe":
        m = ("⏳ Partira le %s — annulable jusque-là.\nMandat : %s\nÀ : %s\nObjet : %s"
             % (r.get("part_a", ""), r["mandat"], ", ".join(r.get("destinataires") or []),
                r.get("objet", "")))
        return (m, m, "#f1c440")
    m = "📤 Envoyé — mandat « %s » → %s" % (r.get("mandat", nom), r.get("to", ""))
    return (m, m, "#27c168")


