_AGENDA_KIND_ICON = {"event": "📅", "task": "✅", "reminder": "⏰", "ssl": "🔒", "cron": "⚙️"}


def _itare_agenda_list_impl(args: dict) -> tuple:
    """Vue UNIFIÉE pour l'agent. Elle ne servait que les événements : interrogée sur
    « qu'est-ce que j'ai cette semaine ? », Cassandra passait à côté des tâches
    datées, des rappels et des expirations de certificats. L'agent et l'interface
    voient désormais exactement la même chose."""
    days = int(args.get("days", 14) or 14)
    d_from = datetime.now().strftime("%Y-%m-%d")
    d_to = (datetime.now() + timedelta(days=days)).strftime("%Y-%m-%d")
    try:
        items = itare_calendar_items(d_from, d_to)
    except Exception as e:
        return (False, "📅 Agenda indisponible : %s" % e, "#e0564a")
    # CalDAV en plus, s'il est configuré.
    try:
        r = itare_agenda_list(days=days)
        for e in (r.get("events") or []):
            if e.get("origin") == "caldav":
                items.append({"kind": "event", "summary": e.get("summary", ""),
                              "when": e.get("start", ""), "source": "caldav",
                              "location": e.get("location", "")})
    except Exception:
        pass
    items.sort(key=lambda x: x.get("when") or "")
    if not items:
        return (True, "📅 Rien de prévu dans les %d prochains jours." % days, "#8a8a9a")
    lines = []
    for e in items[:50]:
        ic = _AGENDA_KIND_ICON.get(e.get("kind"), "•")
        extra = ""
        if e.get("location"):
            extra += " @ " + str(e["location"])
        if e.get("project_name"):
            extra += " [%s]" % e["project_name"]
        if e.get("kind") == "task" and e.get("status") == "fait":
            extra += " (fait)"
        if e.get("kind") == "ssl" and e.get("days_left"):
            extra += " (dans %s j)" % e["days_left"]
        lines.append("%s %s — %s%s" % (ic, e.get("when", "?"), e.get("summary", ""), extra))
    txt = "📅 Agenda sur %d jours (%d élément(s)) :\n%s" % (days, len(items), "\n".join(lines))
    return (txt, txt, "#8be9fd")


