def _vault_remove_impl(args) -> tuple:
    name = (args.get("name") or "").strip()
    if not name:
        return (False, "nom du secret requis", "#e0564a")
    r = vault_delete(name)
    if r.get("ok"):
        return (True, "🔐 Secret « %s » supprimé du coffre." % name, "#27c168")
    return (False, "Échec : %s" % r.get("error"), "#e0564a")


# ── Gestion de site via mogwai (CLI FastPanel) — source fiable, scopée par domaine ──
def _mogwai_json(args_list, timeout=40):
    """Lance `mogwai --json <args>` et parse la sortie JSON. Retourne (data, err)."""
    try:
        r = subprocess.run(["mogwai", "--json"] + list(args_list),
                           capture_output=True, text=True, timeout=timeout)
        out = (r.stdout or "").strip()
        if not out:
            return None, (r.stderr or "sortie vide")[:200]
        start = min([i for i in (out.find("["), out.find("{")) if i >= 0], default=-1)
        if start < 0:
            return None, out[:200]
        return json.loads(out[start:]), None
    except Exception as e:
        return None, str(e)


def _mogwai_run(args_list, timeout=180):
    """Lance une commande mogwai d'ÉCRITURE. Retourne (ok, message)."""
    try:
        r = subprocess.run(["mogwai"] + list(args_list), capture_output=True, text=True, timeout=timeout)
        if r.returncode == 0:
            return True, (r.stdout or "OK").strip()[:300]
        return False, (r.stderr or r.stdout or "échec").strip()[:300]
    except Exception as e:
        return False, str(e)


def _fp_site_by_domain(domain):
    """Trouve le site FastPanel (objet mogwai) par domaine OU alias. Retourne (site, err)."""
    # PERF: importer time en début pour éviter __import__ à chaque appel
    import time
    from functools import lru_cache

    # PERF: créer une seule fois le cache de normalisation comme attribut de fonction
    if not hasattr(_fp_site_by_domain, '_cached_norm'):
        _fp_site_by_domain._cached_norm = lru_cache(maxsize=None)(_norm_domain)
    _cached_norm = _fp_site_by_domain._cached_norm

    # ROBUSTESSE: validation du paramètre d'entrée
    if not domain or not isinstance(domain, str):
        return None, "domaine invalide"

    dn = _cached_norm(domain)

    cache = _fp_site_by_domain
    # PERF: utiliser monotonic pour éviter les décalages d'horloge système
    now = time.monotonic()
    # PERF: initialiser _cache_time à 0 pour éviter hasattr à chaque vérification
    if not hasattr(cache, '_cache_time'):
        cache._cache_time = 0.0
    # PERF: vérifier existence et expiration du cache en une seule condition
    if hasattr(cache, '_cache_data') and (now - cache._cache_time) <= 300:
        domain_map, alias_map = cache._cache_data
    else:
        # ROBUSTESSE: try/except pour les erreurs réseau ou JSON malformé
        try:
            sites, err = _mogwai_json(["sites", "list"])
        except Exception as e:
            return None, f"erreur lors de la récupération des sites: {str(e)}"

        if not sites:
            return None, err or "liste des sites indisponible"

        # PERF: dictionnaires pour lookup O(1)
        domain_map = {}
        alias_map = {}

        # PERF: filtrer les sites non-dicts en amont pour éviter les isinstance dans la boucle
        valid_sites = [s for s in sites if isinstance(s, dict)]

        # PERF: remplacer la boucle imbriquée par une génération unique des mappages
        for s in valid_sites:
            raw_domain = s.get("domain")
            # PERF: normalisation unique du domaine principal
            if raw_domain and isinstance(raw_domain, str):
                norm_domain = _cached_norm(raw_domain)
                domain_map[norm_domain] = s

            aliases = s.get("aliases")
            # PERF: traitement des alias sans boucle explicite via compréhension
            if isinstance(aliases, list):
                # PERF: construire alias_map en une passe (élimine un isinstance redondant)
                alias_map.update({
                    _cached_norm(name): s
                    for a in aliases
                    if isinstance(a, dict)
                    and (name := a.get("name") or a.get("raw_name"))
                    and isinstance(name, str)
                })

        cache._cache_data = (domain_map, alias_map)
        cache._cache_time = now

    # PERF: lookup O(1)
    if dn in domain_map:
        return domain_map[dn], None
    if dn in alias_map:
        return alias_map[dn], None
    return None, "site introuvable"


def _site_status_impl(args) -> tuple:
    """Statut d'un site par domaine (propriété vérifiée en amont par _handle_tool). Source: mogwai."""
    domain = _norm_domain(args.get("domain", ""))
    if not domain:
        return (False, "domaine requis", "#e0564a")
    site, err = _fp_site_by_domain(domain)
    if not site:
        return (False, "Site « %s » introuvable (%s)." % (domain, err or "?"), "#e0564a")
    lines = ["📂 Site %s" % domain,
             "• Statut : %s%s" % (site.get("status") or "?", "" if site.get("enabled", True) else " (désactivé)")]
    be = site.get("main_backend") or {}
    if be.get("handler"):
        lines.append("• Backend : %s%s" % (be.get("handler"), " — actif" if be.get("is_running") else ""))
    cert = site.get("certificate")
    dl = _cert_days(cert)
    if cert and dl is not None:
        lines.append("• SSL : %s — %s"
                     % (cert.get("type", "?"),
                        ("expire dans %d j" % dl) if dl >= 0
                        else ("EXPIRÉ depuis %d j" % abs(dl))))
        if not site.get("https_redirect"):
            lines.append("• ⚠ Redirection HTTP→HTTPS désactivée")
    elif cert:
        lines.append("• SSL : certificat présent mais sa date d'expiration est "
                     "inexploitable (%r) — à vérifier dans le panneau."
                     % (cert.get("expires"),))
    else:
        lines.append("• SSL : aucun certificat")
    if site.get("index_dir"):
        lines.append("• Racine : %s" % site.get("index_dir"))
    feats = [f for f, on in (("HTTP/2", site.get("http2")), ("HTTP/3", site.get("http3")),
                             ("HSTS", site.get("hsts")), ("redirection HTTPS", site.get("https_redirect"))) if on]
    if feats:
        lines.append("• Options : %s" % ", ".join(feats))
    if site.get("status_code") is not None:
        lines.append("• Réponse HTTP : %s" % site.get("status_code"))
    return (True, "\n".join(lines), "#27c168")


# ── Quota Let's Encrypt ────────────────────────────────────────────────────
# Let's Encrypt refuse plus de 5 certificats par domaine et par semaine, et ce
# refus n'a AUCUN contournement : le domaine reste bloqué sept jours. Le
# renouvellement automatique était protégé (une tentative par 12 h) ; le bouton
# manuel, celui qu'on peut marteler, ne l'était pas. Un double-clic ou un
# rechargement suffisait à consommer le quota.
_LE_MAX_PAR_SEMAINE = 5
_LE_FENETRE_S = 7 * 24 * 3600


def _ssl_quota_migrate():
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        conn.execute("CREATE TABLE IF NOT EXISTS ssl_issuances ("
                     "id INTEGER PRIMARY KEY AUTOINCREMENT, domain TEXT, "
                     "ts TEXT DEFAULT (datetime('now')), actor TEXT, ok INTEGER)")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_ssl_issuances_dom "
                     "ON ssl_issuances(domain, ts)")
        conn.commit(); conn.close()
    except Exception as e:
        logging.warning("[SSL] quota : migration %s", e)


def ssl_quota_state(domain: str) -> dict:
    """Combien d'émissions restent pour ce domaine, et quand le quota se libère.

    On compte les tentatives ABOUTIES : Let's Encrypt ne décompte que les
    certificats réellement émis. Une réémission qui échoue pour une autre
    raison ne doit pas bloquer les suivantes."""
    dn = _norm_domain(domain)
    _ssl_quota_migrate()
    limite = (_utcnow() - timedelta(seconds=_LE_FENETRE_S)).strftime("%Y-%m-%d %H:%M:%S")
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        rows = conn.execute("SELECT ts FROM ssl_issuances WHERE domain=? AND ok=1 AND ts >= ? "
                            "ORDER BY ts", (dn, limite)).fetchall()
        conn.close()
    except Exception as e:
        # En cas de doute on n'empêche pas d'agir : on ne remplace pas un
        # blocage Let's Encrypt par un blocage maison.
        logging.warning("[SSL] quota illisible : %s", e)
        return {"ok": True, "used": 0, "remaining": _LE_MAX_PAR_SEMAINE, "unknown": True}
    used = len(rows)
    libre = ""
    if used >= _LE_MAX_PAR_SEMAINE and rows:
        try:
            libre = (datetime.strptime(rows[0][0][:19], "%Y-%m-%d %H:%M:%S")
                     + timedelta(seconds=_LE_FENETRE_S)).strftime("%d/%m/%Y à %H:%M")
        except Exception:
            libre = "dans moins de 7 jours"
    return {"ok": True, "domain": dn, "used": used,
            "remaining": max(0, _LE_MAX_PAR_SEMAINE - used),
            "limit": _LE_MAX_PAR_SEMAINE, "blocked": used >= _LE_MAX_PAR_SEMAINE,
            "free_at": libre}


def _ssl_quota_note(domain: str, ok: bool, actor: str = ""):
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        conn.execute("INSERT INTO ssl_issuances (domain, ts, actor, ok) "
                     "VALUES (?, datetime('now'), ?, ?)",
                     (_norm_domain(domain), (actor or "")[:60], 1 if ok else 0))
        conn.commit(); conn.close()
    except Exception as e:
        logging.warning("[SSL] quota : enregistrement %s", e)


def _site_ssl_renew_impl(args) -> tuple:
    """Réémet le certificat Let's Encrypt du domaine (propriété vérifiée en amont)."""
    domain = _norm_domain(args.get("domain", ""))
    if not domain:
        return (False, "domaine requis", "#e0564a")
    # Le quota se vérifie AVANT d'appeler l'autorité : une fois la limite
    # atteinte, plus rien ne débloque le domaine avant sept jours.
    q = ssl_quota_state(domain)
    if q.get("blocked"):
        return (False,
                "Quota Let's Encrypt atteint pour %s : %d certificats émis en 7 jours "
                "(limite %d). L'autorité refusera toute nouvelle demande jusqu'au %s. "
                "Ce n'est pas contournable — le certificat en place reste valide."
                % (domain, q["used"], q["limit"], q.get("free_at") or "déblocage"),
                "#e8c660")
    certs, err = _mogwai_json(["certificates", "list"])
    if not certs:
        return (False, "Certificats illisibles (%s)." % (err or "?"), "#e0564a")
    cert = next((c for c in certs if _norm_domain(c.get("common_name", "")) == domain), None)
    if not cert:
        return (False, "Aucun certificat trouvé pour %s." % domain, "#e0564a")
    ok, msg = _mogwai_run(["certificates", "reissue", "--id=%s" % cert.get("id")])
    _ssl_quota_note(domain, ok, str(args.get("actor", "")))
    if ok:
        try: notify_site_owners(domain, "ssl_renew")
        except Exception: pass
        reste = max(0, q.get("remaining", _LE_MAX_PAR_SEMAINE) - 1)
        return (True, "🔒 Certificat SSL de %s réémis (réémission lancée).%s"
                % (domain, ("\n⚠ Il reste %d émission(s) autorisée(s) cette semaine "
                            "pour ce domaine." % reste) if reste <= 2 else ""), "#27c168")
    return (False, "Échec réémission SSL pour %s : %s" % (domain, msg), "#e0564a")


def _site_restart_impl(args) -> tuple:
    """Redémarre le backend (PHP/app) du site, sans impacter les autres (propriété vérifiée en amont)."""
    domain = _norm_domain(args.get("domain", ""))
    if not domain:
        return (False, "domaine requis", "#e0564a")
    site, err = _fp_site_by_domain(domain)
    if not site:
        return (False, "Site « %s » introuvable (%s)." % (domain, err or "?"), "#e0564a")
    svc = (site.get("main_backend") or {}).get("service_name")
    if not svc:
        return (False, "Pas de service backend dédié pour %s (rien à redémarrer)." % domain, "#e0564a")
    ok, msg = _mogwai_run(["sites", "backend", "actions", "-n", svc, "-a", "restart"], timeout=60)
    if ok:
        try: notify_site_owners(domain, "restart")
        except Exception: pass
        return (True, "♻️ Backend du site %s redémarré." % domain, "#27c168")
    return (False, "Échec du redémarrage de %s : %s" % (domain, msg), "#e0564a")


def _site_fiche(domain: str):
    """(fiche du domaine, erreur). Le dossier et la version PHP viennent de
    FastPanel — jamais de la requête : un chemin donné par l'appelant serait
    une sortie du périmètre déguisée en argument."""
    d = next((x for x in (get_fp_domains() or [])
              if isinstance(x, dict)
              and _norm_domain(str(x.get("domain") or "")) == domain), None)
    if not d:
        return None, "Site « %s » introuvable." % domain
    return d, ""


def _site_php_version_impl(args) -> tuple:
    """La version de PHP du site. Lecture seule, propriété vérifiée en amont."""
    domain = _norm_domain(args.get("domain", ""))
    if not domain:
        return (False, "domaine requis", "#e0564a")
    d, err = _site_fiche(domain)
    if not d:
        return (False, err, "#e0564a")
    v = str(d.get("php_version") or "").strip()
    if not v:
        return ("\U0001F418 « %s » ne déclare aucune version de PHP : soit le site "
                "est servi en statique, soit le panneau ne la connaît pas."
                % domain,
                "\U0001F418 « %s » ne déclare aucune version de PHP." % domain,
                "#e8c660")
    msg = "\U0001F418 « %s » tourne en PHP %s." % (domain, v)
    _st = str(d.get("status") or "").strip()
    if _st and _st.lower() not in ("active", "actif", "1", "on"):
        msg += " (état du site : %s)" % _st
    return (msg, msg, "#8be9fd")


def _site_disk_impl(args) -> tuple:
    """Ce que le site occupe, et OÙ. Lecture seule.

    « Mon disque se remplit » n'a de réponse utile que si l'on dit quel dossier
    gonfle : un total seul oblige à chercher à la main, et c'est justement ce
    qu'on ne peut pas faire sans accès au serveur.
    """
    domain = _norm_domain(args.get("domain", ""))
    if not domain:
        return (False, "domaine requis", "#e0564a")
    d, err = _site_fiche(domain)
    if not d:
        return (False, err, "#e0564a")
    racine = str(d.get("document_root") or "").strip()
    # LE CHEMIN VIENT DU PANNEAU, mais on le vérifie quand même : une base
    # abîmée ou un champ vide donnerait `du /`, qui balaierait le serveur
    # entier et mettrait des minutes à répondre.
    # UN CHEMIN QUI COMMENCE PAR « / » ET SANS « .. » NE SUFFIT PAS : « / »
    # remplit les deux conditions, et `du -sh /` balaie le serveur entier
    # pendant des minutes. On exige un chemin PROFOND, et jamais une racine
    # système — c'est le genre de valeur qu'une base de panneau abîmée rend.
    _r = "/" + racine.strip().strip("/")
    if (not racine or not racine.startswith("/") or ".." in racine
            or _r.count("/") < 3
            # Cette liste est REDONDANTE avec la profondeur ci-dessus — toutes
            # ces racines n'ont qu'un « / ». Elle reste comme second filet, et
            # parce qu'elle NOMME ce qu'on refuse : la règle de profondeur, à
            # elle seule, ne dit pas pourquoi.
            or _r in ("/etc", "/root", "/var", "/usr", "/srv", "/home",
                      "/tmp", "/boot", "/opt", "/bin", "/lib")):
        return (False, "Le dossier de « %s » n'est pas exploitable (%s) : je ne "
                       "mesure pas une racine du système."
                % (domain, racine or "chemin vide"), "#e8c660")
    if not os.path.isdir(racine):
        return (False, "Le dossier de « %s » n'existe pas sur le disque : %s"
                % (domain, racine), "#e8c660")
    try:
        _t = subprocess.run(["du", "-sh", racine], capture_output=True,
                            text=True, timeout=60)
        total = (_t.stdout or "").split("\t")[0].strip() or "?"
    except Exception as e:
        return (False, "Mesure impossible : %s" % str(e)[:120], "#e0564a")
    lignes = []
    try:
        _l = subprocess.run("du -sh %s/* 2>/dev/null | sort -rh | head -8"
                            % racine.replace("'", ""), shell=True,
                            capture_output=True, text=True, timeout=90)
        for ligne in (_l.stdout or "").strip().split("\n"):
            if not ligne.strip():
                continue
            _p = ligne.split("\t")
            if len(_p) == 2:
                lignes.append("• %s — %s" % (os.path.basename(_p[1]) or _p[1], _p[0]))
    except Exception:
        pass
    msg = "\U0001F4BE « %s » occupe %s (%s)." % (domain, total, racine)
    if lignes:
        msg += "\nLes plus gros dossiers :\n" + "\n".join(lignes)
    else:
        msg += "\n(Le détail par dossier n'a pas pu être établi.)"
    return (msg, msg, "#8be9fd")


def _site_backup_impl(args) -> tuple:
    """L'ÉTAT des sauvegardes du site : ses bases, et quand elles ont été prises.

    Elle ne DÉCLENCHE rien. FastPanel ne sait pas sauvegarder un site seul —
    ses actions de sauvegarde portent sur le panneau entier —, et lancer un
    plan de Cassandra sur le dossier d'un site demanderait un plan par site.
    Dire honnêtement quand la dernière a eu lieu vaut mieux qu'un bouton qui
    prétend agir.
    """
    domain = _norm_domain(args.get("domain", ""))
    if not domain:
        return (False, "domaine requis", "#e0564a")
    d, err = _site_fiche(domain)
    if not d:
        return (False, err, "#e0564a")
    try:
        toutes = get_fp_databases() or []
    except Exception as e:
        return (False, "Bases illisibles : %s" % str(e)[:120], "#e0564a")
    if not any(str(x.get("site") or "").strip() for x in toutes if isinstance(x, dict)):
        return (False, "Le rattachement des bases aux sites n'est pas lisible sur "
                       "cette machine : je ne peux rien dire des sauvegardes de "
                       "« %s » sans risquer de parler de celles d'un autre."
                % domain, "#e8c660")
    miennes = [x for x in toutes
               if isinstance(x, dict)
               and _norm_domain(str(x.get("site") or "")) == domain]
    lignes, jamais = [], []
    for x in sorted(miennes, key=lambda y: str(y.get("name") or "")):
        _q = str(x.get("dump_at") or "").strip()
        if _q:
            lignes.append("• %s — dernière sauvegarde le %s" % (x.get("name"), _q))
        else:
            jamais.append(str(x.get("name") or "?"))
    if not miennes:
        msg = ("\U0001F5C4 « %s » n'a aucune base rattachée : il n'y a donc rien "
               "à sauvegarder de ce côté." % domain)
        return (msg, msg, "#8be9fd")
    msg = "\U0001F4E6 Sauvegardes des bases de « %s » :" % domain
    if lignes:
        msg += "\n" + "\n".join(lignes)
    if jamais:
        msg += ("\n\u26a0 JAMAIS SAUVEGARDÉE(S) : %s. C'est le genre de chose "
                "qu'on découvre le jour où l'on en a besoin."
                % ", ".join(jamais))
    msg += ("\n(Les FICHIERS du site, eux, dépendent des plans de sauvegarde du "
            "serveur — je ne les vois pas d'ici.)")
    return (msg, msg, "#8be9fd" if not jamais else "#e8c660")


def _site_databases_impl(args) -> tuple:
    """Les bases de données DU SITE. Lecture seule, propriété vérifiée en amont.

    Le rattachement vient de FastPanel (`db.site_id`), pas d'une ressemblance
    de noms : deviner « exemple_com_wp appartient à exemple.com » marcherait
    neuf fois sur dix, et la dixième montrerait la base de quelqu'un d'autre.
    """
    domain = _norm_domain(args.get("domain", ""))
    if not domain:
        return (False, "domaine requis", "#e0564a")
    try:
        toutes = get_fp_databases() or []
    except Exception as e:
        return (False, "Bases illisibles : %s" % str(e)[:120], "#e0564a")
    # SANS RATTACHEMENT, ON NE MONTRE RIEN. Une liste où aucune base ne porte
    # de site vient d'un panneau qui ne le sait pas : filtrer dessus rendrait
    # zéro, et le dire « ce site n'a pas de base » serait faux. Pire, une
    # écriture distraite rendrait TOUT.
    if not any(str(d.get("site") or "").strip() for d in toutes if isinstance(d, dict)):
        return (False, "Le rattachement des bases aux sites n'est pas lisible sur "
                       "cette machine : je ne peux pas dire lesquelles sont à "
                       "« %s », et je préfère ne rien montrer que montrer celles "
                       "d'un autre." % domain, "#e8c660")
    miennes = [d for d in toutes
               if isinstance(d, dict)
               and _norm_domain(str(d.get("site") or "")) == domain]
    if not miennes:
        return ("🗄 Aucune base de données rattachée à « %s »." % domain,
                "🗄 Aucune base de données rattachée à « %s »." % domain, "#8be9fd")
    lignes = []
    for d in sorted(miennes, key=lambda x: str(x.get("name") or "")):
        _t = float(d.get("size_mb") or 0)
        _taille = ("%.0f Mo" % _t) if _t >= 1 else ("%.2f Mo" % _t if _t else "vide")
        _bout = ["%s — %s, %s" % (d.get("name") or "?",
                                  d.get("db_type") or "mysql", _taille)]
        if d.get("db_user"):
            _bout.append("accès : %s" % d["db_user"])
        if d.get("dump_at"):
            _bout.append("dernière sauvegarde : %s" % d["dump_at"])
        if not int(d.get("enabled", 1) or 0):
            _bout.append("DÉSACTIVÉE")
        lignes.append("• " + " · ".join(_bout))
    msg = ("🗄 %d base(s) rattachée(s) à « %s » :\n%s"
           % (len(miennes), domain, "\n".join(lignes)))
    return (msg, msg, "#8be9fd")


def _site_logs_impl(args) -> tuple:
    """Dernières lignes du log d'erreur d'un site (lecture seule, propriété vérifiée en amont)."""
    domain = _norm_domain(args.get("domain", ""))
    if not domain:
        return (False, "domaine requis", "#e0564a")
    site, err = _fp_site_by_domain(domain)
    if not site:
        return (False, "Site « %s » introuvable (%s)." % (domain, err or "?"), "#e0564a")
    home = ((site.get("owner") or {}).get("home_dir")) or "/var/www"
    cands = ["%s/logs/%s/%s-error.log" % (home, domain, domain),
             "%s/logs/%s.error.log" % (home, domain),
             "%s/logs/%s/error.log" % (home, domain),
             "/var/log/nginx/%s-error.log" % domain,
             "/var/log/nginx/%s.error.log" % domain]
    path = next((p for p in cands if os.path.exists(p)), None)
    if not path:
        return (False, "Aucun fichier de log d'erreur trouvé pour %s." % domain, "#e8c660")
    try:
        r = subprocess.run(["tail", "-n", "40", path], capture_output=True, text=True, timeout=10)
        out = (r.stdout or "").strip() or "(log vide)"
    except Exception as e:
        return (False, "Lecture du log échouée : %s" % e, "#e0564a")
    return (True, "📄 %s (40 dernières lignes)\n%s" % (path, out[-2500:]), "#27c168")


# `mogwai sites list` prend jusqu'à 40 s. L'accueil et l'onglet appelaient la
# même route l'un après l'autre : deux fois le même travail, deux fois l'attente.
_SITES_CACHE = {"data": None, "err": None, "t": 0.0}
_SITES_CACHE_TTL = 30


def _sites_list_cached(force: bool = False):
    now = time.time()
    if not force and _SITES_CACHE["data"] is not None and now - _SITES_CACHE["t"] < _SITES_CACHE_TTL:
        return _SITES_CACHE["data"], _SITES_CACHE["err"]
    data, err = _mogwai_json(["sites", "list"])
    if data is None and _SITES_CACHE["data"] is not None:
        # Le collecteur a hoqueté : mieux vaut une liste d'il y a une minute
        # qu'une page vide qui laisse croire que les sites ont disparu.
        logging.info("[SITES] liste indisponible (%s), on garde le cache", err)
        return _SITES_CACHE["data"], None
    _SITES_CACHE.update({"data": data, "err": err, "t": now})
    return data, err


_DATE_FORMATS = ("%Y-%m-%dT%H:%M:%S", "%Y-%m-%d %H:%M:%S", "%Y-%m-%dT%H:%M",
                 "%Y-%m-%d", "%d/%m/%Y %H:%M:%S", "%d/%m/%Y")


def _vers_epoch(v):
    """Convertit une date mogwai — nombre ou chaîne — en secondes epoch."""
    if v is None or v == "":
        return None
    if isinstance(v, (int, float)) and not isinstance(v, bool):
        f = float(v)
        if f > 1e11:            # millisecondes
            f /= 1000.0
        return f if f > 1262304000 else None
    s = str(v).strip().replace("Z", "").split(".")[0]
    if s.replace("-", "").isdigit() and len(s) >= 10 and "-" not in s[1:]:
        try:
            return _vers_epoch(float(s))
        except ValueError:
            pass
    for fmt in _DATE_FORMATS:
        try:
            return datetime.strptime(s[:len(datetime.now().strftime(fmt))], fmt).timestamp()
        except (ValueError, OverflowError):
            continue
    return None


def _cert_days(cert: dict):
    """Jours avant expiration d'un certificat mogwai, ou None si indéterminable.

    LE PIÈGE : `expires` n'est PAS une date, c'est la DURÉE DE VALIDITÉ en
    jours — il vaut 90 pour tous les certificats Let's Encrypt de ce serveur.
    Le code d'origine le traitait comme un horodatage et calculait
    `(90 - maintenant) / 86400`, d'où le fameux « expire dans -20672 j ».
    La vraie date est dans `expired_at`, que rien ne lisait.

    Trois sources, dans l'ordre de fiabilité : la date d'expiration, puis la
    date de création augmentée de la durée, et rien d'autre. On ne devine pas."""
    c = cert or {}
    fin = _vers_epoch(c.get("expired_at") or c.get("expire_at")
                      or c.get("not_after") or c.get("valid_till"))
    if fin is None:
        debut = _vers_epoch(c.get("created_at") or c.get("issued_at"))
        try:
            duree = float(c.get("expires"))
        except (TypeError, ValueError):
            duree = None
        # Une durée plausible : entre un jour et dix ans.
        if debut is not None and duree is not None and 1 <= duree <= 3650:
            fin = debut + duree * 86400
    if fin is None:
        return None
    # ARRONDI, pas troncature : un certificat expirant dans 55,99 jours devient
    # « 55 j » par troncature, alors que le panneau d'accueil affiche 56. Deux
    # chiffres différents pour le même certificat se lisent comme un défaut.
    return int(round((fin - time.time()) / 86400.0))


def _site_up(s: dict) -> bool:
    """Un site en ligne, au sens du visiteur.

    N'exiger que 200 était faux : un site qui force correctement HTTPS répond
    301 en HTTP, et s'affichait en alerte JUSTE À CÔTÉ de la mention verte
    « HTTPS forcé ». Une redirection est une réponse, pas une panne."""
    code = s.get("status_code")
    try:
        code = int(code)
    except (TypeError, ValueError):
        return False
    if code in (301, 302, 307, 308):
        return True
    return 200 <= code < 400


def _user_sites_overview(user, force: bool = False) -> dict:
    """Liste des sites visibles par l'utilisateur (les siens ; tous si admin) + statut résumé."""
    sites_filter = None if is_admin(user) else set(user_sites(user))
    if sites_filter is not None and not sites_filter:
        return {"ok": True, "sites": []}
    all_sites, err = _sites_list_cached(force)
    if all_sites is None:
        return {"ok": False, "error": err or "indisponible", "sites": []}
    out = []
    for s in all_sites:
        dn = _norm_domain(s.get("domain", ""))
        if sites_filter is not None and dn not in sites_filter:
            continue
        days = _cert_days(s.get("certificate") or {})
        be = s.get("main_backend") or {}
        out.append({"domain": s.get("domain"), "status": s.get("status"),
                    "backend": be.get("handler"), "running": bool(be.get("is_running")),
                    "ssl_days": days, "https": bool(s.get("https_redirect")),
                    "http_code": s.get("status_code"), "up": _site_up(s),
                    "root": s.get("index_dir")})
    out.sort(key=lambda x: (x.get("domain") or "").lower())
    return {"ok": True, "sites": out}


_SITE_ACTION_IMPLS = {
    "status": lambda d, a="": _site_status_impl({"domain": d}),
    "ssl_renew": lambda d, a="": _site_ssl_renew_impl({"domain": d, "actor": a}),
    "restart": lambda d, a="": _site_restart_impl({"domain": d}),
    "logs": lambda d, a="": _site_logs_impl({"domain": d}),
}

# Ce qui modifie l'état exige un accord EXPLICITE côté serveur. Le confirm()
# du navigateur ne protège rien : un rechargement, un double-clic ou un appel
# direct à la route le contournent — et pour le SSL, chaque contournement
# consomme une émission Let's Encrypt qu'on ne récupère pas.
_SITE_ACTIONS_MODIFIANTES = {
    "ssl_renew": "Réémet le certificat SSL. Let's Encrypt n'autorise que "
                 "%d émissions par domaine et par semaine." % _LE_MAX_PAR_SEMAINE,
    "restart": "Redémarre le backend du site : les visiteurs en cours sont coupés.",
}

# ══════════════════════════════════════════════════════════════════════════════
#  SITES PAR COMPTE (20-09, fil 29) — la vue, la fiche, le journal, les gestes
#
#  Un compte voit ses sites : ceux du panneau (compte adossé) et ceux qu'il a
#  déclarés, réunis en une liste où chaque site dit sa source. L'administrateur
#  voit la liste et l'état technique de tous, groupés par compte, jamais le
#  contenu (journaux, archives). Tout est réuni en UN appel : la vue portait
#  neuf champs et le reste vivait dans cinq routes.
# ══════════════════════════════════════════════════════════════════════════════
_SITES_VUE_CACHES = {}          # {clé de portée: {"t": …, "data": …}} — un compte n'efface plus la vue de l'admin (21-09)
_SITES_VUE_TTL = 30


class _SitesVueCacheCompat(dict):
    """`_SITES_VUE_CACHE["data"] = None` vidait le cache : le geste survit, il vide tous les caches."""
    def __setitem__(self, k, v):
        if k == "data" and v is None:
            _SITES_VUE_CACHES.clear()
        dict.__setitem__(self, k, v)


_SITES_VUE_CACHE = _SitesVueCacheCompat()
_SITE_DOMAINE_RE = re.compile(r"^(?=.{4,253}$)([a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,24}$")


def _sites_panneau_domaines() -> set:
    """Les domaines que le panneau gère — déclarer l'un d'eux à la main serait s'en emparer."""
    out = set()
    try:
        brut, _e = _sites_list_cached()
        out |= {_norm_domain(x.get("domain") or "") for x in (brut or []) if isinstance(x, dict)}
    except Exception:
        pass
    try:
        for doms in (fp_comptes_sites() or {}).values():
            out |= {_norm_domain(d) for d in (doms or []) if d}
    except Exception:
        pass
    out.discard("")
    return out


def _sites_comptes_map(avec_admins: bool = False) -> dict:
    """{domaine: [comptes Cassandra qui le voient]} — déclarés et hérités du panneau. Sans les
    administrateurs par défaut (la vue les groupe par compte ordinaire) ; avec, pour juger une
    propriété."""
    out = {}
    try:
        for email, v in load_users().items():
            if not avec_admins and _user_record(v).get("role") == "admin":
                continue
            for d in (user_sites(email) or []):
                out.setdefault(_norm_domain(d), []).append(email)
    except Exception:
        pass
    return out


def _sites_declares_tous() -> dict:
    """{domaine déclaré à la main: [comptes]} — les sites saisis dans users.json, tous comptes."""
    out = {}
    try:
        for email, v in load_users().items():
            for d in (_user_record(v).get("sites") or []):
                out.setdefault(_norm_domain(d), []).append(email)
    except Exception:
        pass
    return out


def _cert_sonde_jours(domain: str, timeout: float = 5.0):
    """Jours avant expiration du certificat SERVI — pour un site hors panneau, c'est tout ce qu'on sait."""
    try:
        import ssl as _ssl, socket as _socket
        ctx = _ssl.create_default_context()
        with _socket.create_connection((domain, 443), timeout=timeout) as sock:
            with ctx.wrap_socket(sock, server_hostname=domain) as ss:
                cert = ss.getpeercert()
        fin = cert.get("notAfter")
        if not fin:
            return None
        dt = datetime.strptime(fin, "%b %d %H:%M:%S %Y %Z")
        return int((dt - datetime.utcnow()).total_seconds() // 86400)
    except Exception:
        return None


def _sites_derniere_sonde() -> dict:
    """{domaine: {ts, http_code, response_ms, up, ssl_days}} — la dernière ligne de la veille."""
    out = {}
    try:
        _site_migrate()
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        for r in conn.execute("SELECT domain, ts, http_code, response_ms, up, ssl_days FROM site_status "
                              "WHERE id IN (SELECT MAX(id) FROM site_status GROUP BY domain)"):
            out[_norm_domain(r[0] or "")] = {"ts": r[1], "http_code": r[2], "response_ms": r[3],
                                             "up": bool(r[4]), "ssl_days": r[5]}
        conn.close()
    except Exception:
        pass
    return out


def _site_plan_pour(fp_compte: str):
    """Le plan de sauvegarde qui couvre un compte du panneau. Le moteur v2 copie PAR COMPTE : un plan
    porte `user_id` (un compte) ou couvre tout. Sans correspondance sûre, le premier plan, dit tel."""
    try:
        plans = (fp_backup_plans() or {}).get("plans") or []
    except Exception:
        plans = []
    if not plans:
        return None
    cid = None
    try:
        for c in (_fp_comptes_panneau() or []):
            if isinstance(c, dict) and str(c.get("username") or "").lower() == (fp_compte or "").lower():
                cid = c.get("id")
    except Exception:
        cid = None
    if cid is not None:
        for p in plans:
            if str(p.get("user_id") or "") == str(cid):
                return p
    return plans[0]


def sites_vue(user, force: bool = False, admin_force: bool = False) -> dict:
    """La vue d'un compte (ou de l'admin) : panneau ∪ déclarés, onze champs par site, vigilances, portée.
    `admin_force` : la sonde réchauffe la vue administrateur sans compte sur le fil."""
    admin = bool(admin_force) or is_admin(user)
    miens = {} if admin else {_norm_domain(x) for x in (user_sites(user) or []) if x}
    cle = ("admin" if admin else (user or "")) + "|" + ",".join(sorted(miens))
    now = time.time()
    _c = _SITES_VUE_CACHES.get(cle)
    if not force and _c and _c.get("data") is not None and now - _c["t"] < _SITES_VUE_TTL:
        return _c["data"]
    if not admin and not miens:
        return {"ok": True, "sites": [], "vigilances": [],
                "portee": {"admin": False, "compte": user, "sites": 0, "panneau": 0, "declares": 0},
                "releve": _utcnow().strftime("%Y-%m-%d %H:%M:%S")}
    brut, err = _sites_list_cached(force)
    panneau_ok = brut is not None
    fpd, scans, copies, dispo, cms, sonde = {}, {}, {}, {}, {}, {}
    try:
        fpd = {_norm_domain(d.get("domain") or ""): d for d in (get_fp_domains() or []) if isinstance(d, dict)}
    except Exception:
        fpd = {}
    try:
        for sc in (get_fp_scans() or []):
            dn = _norm_domain(sc.get("domain") or "")
            if dn and dn not in scans:
                scans[dn] = {"at": sc.get("created_at") or "", "status": sc.get("status") or "inconnu"}
    except Exception:
        scans = {}
    try:
        for c in (_fp_backups_riches() or []):
            if c.get("status") != "success":
                continue
            cp = str(c.get("compte") or c.get("user") or "").lower()
            if cp and cp not in copies:
                copies[cp] = {"at": c.get("created_at") or "", "size_mb": c.get("size_mb"),
                              "bases": c.get("bases") or []}
    except Exception:
        copies = {}
    try:
        for x in (site_availability(30) or {}).get("sites", []):
            dispo[_norm_domain(x.get("domain") or "")] = {"pct": x.get("availability"),
                                                          "outages": x.get("outages"),
                                                          "downtime": x.get("downtime")}
    except Exception:
        dispo = {}
    try:
        for x in (site_cms() or {}).get("cms", []):
            cms[_norm_domain(x.get("domain") or "")] = {"type": x.get("type"), "version": x.get("version")}
    except Exception:
        cms = {}
    sonde = _sites_derniere_sonde()
    comptes_map = _sites_comptes_map() if admin else {}
    declares = _sites_declares_tous()
    out = {}
    for sb in (brut or []):
        dn = _norm_domain(sb.get("domain") or "")
        if not dn:
            continue
        if not admin and not _fp_appartient(dn, miens):
            continue
        days = _cert_days(sb.get("certificate") or {})
        be = sb.get("main_backend") or {}
        f = fpd.get(dn) or {}
        cp = str(f.get("user") or "").lower()
        out[dn] = {"domain": sb.get("domain"), "source": "panneau", "status": sb.get("status"),
                   "backend": be.get("handler"), "running": bool(be.get("is_running")),
                   "ssl_days": days, "ssl_source": "panneau", "https": bool(sb.get("https_redirect")),
                   "http_code": sb.get("status_code"), "up": _site_up(sb), "root": sb.get("index_dir"),
                   "php": f.get("php_version") or "", "fp_compte": cp,
                   "disk_mb": f.get("files_mb"), "sauvegarde": copies.get(cp),
                   "scan": scans.get(dn), "cms": cms.get(dn), "dispo30": dispo.get(dn),
                   "sonde": sonde.get(dn), "comptes": comptes_map.get(dn, []) if admin else None,
                   "declare_par": declares.get(dn, [])}
    for dn, qui in declares.items():
        if dn in out:
            continue
        if not admin and not _fp_appartient(dn, miens):
            continue
        so = sonde.get(dn) or {}
        out[dn] = {"domain": dn, "source": "declare", "status": None, "backend": None, "running": None,
                   "ssl_days": so.get("ssl_days"), "ssl_source": "sonde", "https": None,
                   "http_code": so.get("http_code"), "up": so.get("up"), "root": None,
                   "php": "", "fp_compte": "", "disk_mb": None, "sauvegarde": None, "scan": None,
                   "cms": cms.get(dn), "dispo30": dispo.get(dn), "sonde": so or None,
                   "comptes": comptes_map.get(dn, qui) if admin else None, "declare_par": qui}
    sites = sorted(out.values(), key=lambda x: (x.get("domain") or "").lower())
    # Les demandes d'adossement (v2) : l'administrateur les voit toutes, un compte voit les siennes sur ses sites.
    demandes = sites_demandes_lister("ouverte", "" if admin else (user or ""))
    for x in sites:
        x["demande"] = next((d for d in demandes if _norm_domain(d.get("domain") or "") == _norm_domain(x.get("domain") or "")), None)
    vig = _sites_vigilances(sites, admin, demandes)
    comptes = set()
    for x in sites:
        for c in (x.get("comptes") or []):
            comptes.add(c)
    portee = {"admin": admin, "compte": user, "sites": len(sites),
              "panneau": sum(1 for x in sites if x["source"] == "panneau"),
              "declares": sum(1 for x in sites if x["source"] == "declare"),
              "comptes": len(comptes) if admin else None,
              "panneau_ok": panneau_ok, "panneau_erreur": (err or "") if not panneau_ok else ""}
    data = {"ok": True, "sites": sites, "vigilances": vig, "portee": portee,
            "releve": _utcnow().strftime("%Y-%m-%d %H:%M:%S")}
    _SITES_VUE_CACHES[cle] = {"t": now, "data": data}
    return data


def _sites_vigilances(sites: list, admin: bool, demandes=None) -> list:
    """Ce qui demande un geste, tiré de l'état : site tombé, certificat court, scan absent ou infecté,
    sauvegarde absente, site hors panneau, demande d'adossement. Chaque ligne nomme son geste."""
    vig = []
    for d in (demandes or []):
        if admin:
            vig.append({"niveau": "regarder", "site": d.get("domain"), "titre": "%s : adossement demandé par %s" % (d.get("domain"), d.get("compte")),
                        "detail": (d.get("message") or "sans message") + " · " + str(d.get("ts") or "")[:16], "geste": "demande", "demande": d.get("id")})
        else:
            vig.append({"niveau": "info", "site": d.get("domain"), "titre": "%s : demande d'adossement en attente" % d.get("domain"),
                        "detail": "envoyée le " + str(d.get("ts") or "")[:16], "geste": None})
    for x in sites:
        dn = x.get("domain") or ""
        panneau = x.get("source") == "panneau"
        if x.get("up") is False:
            vig.append({"niveau": "panne", "site": dn, "titre": "%s ne répond pas" % dn,
                        "detail": ("code %s" % x.get("http_code")) if x.get("http_code") else "délai dépassé",
                        "geste": "restart" if panneau else "status"})
        d = x.get("ssl_days")
        if isinstance(d, (int, float)):
            if d < 7:
                vig.append({"niveau": "panne", "site": dn, "titre": "certificat de %s : %d jour(s)" % (dn, d),
                            "detail": "renouvellement urgent", "geste": "ssl_renew" if panneau else None})
            elif d < 21:
                vig.append({"niveau": "regarder", "site": dn, "titre": "certificat de %s : %d jours" % (dn, d),
                            "detail": "Cassandra tentera le renouvellement automatique sous 21 jours",
                            "geste": "ssl_renew" if panneau else None})
        if panneau:
            sc = x.get("scan")
            if sc and sc.get("status") == "infecté":
                vig.append({"niveau": "panne", "site": dn, "titre": "%s : analyse antivirus positive" % dn,
                            "detail": "rapport du %s" % (sc.get("at") or "?"), "geste": "scan"})
            elif not sc:
                vig.append({"niveau": "regarder", "site": dn, "titre": "%s : jamais analysé" % dn,
                            "detail": "aucune analyse antivirus connue du panneau", "geste": "scan"})
            else:
                try:
                    age = (datetime.utcnow() - datetime.strptime(str(sc.get("at"))[:19], "%Y-%m-%d %H:%M:%S")).days
                except Exception:
                    age = None
                if age is not None and age > 30:
                    vig.append({"niveau": "regarder", "site": dn,
                                "titre": "%s : %d jours sans analyse" % (dn, age),
                                "detail": "dernière analyse %s" % (sc.get("status") or "?"), "geste": "scan"})
            if not x.get("sauvegarde"):
                vig.append({"niveau": "regarder", "site": dn, "titre": "%s : aucune sauvegarde connue" % dn,
                            "detail": "aucune copie réussie du compte %s" % (x.get("fp_compte") or "?"),
                            "geste": "sauvegarde"})
        elif not x.get("demande"):
            vig.append({"niveau": "info", "site": dn, "titre": "%s : hors panneau" % dn,
                        "detail": "déclaré à la main : sonde, capture, historique et journal seulement",
                        "geste": "attribuer" if admin else "demander"})
    ordre = {"panne": 0, "regarder": 1, "info": 2}
    vig.sort(key=lambda v: (ordre.get(v["niveau"], 9), v["site"]))
    return vig


def site_fiche(domain: str, user) -> dict:
    """La fiche d'un site en UN appel : la ligne de la vue, l'historique 24 h, le quota Let's Encrypt,
    les bases, les rattachements, les derniers gestes, et ce que CE compte peut faire dessus."""
    dn = _norm_domain(domain)
    vue = sites_vue(user)
    ligne = next((x for x in vue.get("sites", []) if _norm_domain(x.get("domain") or "") == dn), None)
    if not ligne:
        return {"ok": False, "reason": "site hors de ta portée", "domain": dn}
    admin = is_admin(user)
    mien = _site_est_a_moi(user, dn)
    panneau = ligne.get("source") == "panneau"
    fiche = {"ok": True, "domain": dn, "site": ligne, "admin_autrui": bool(admin and not mien),
             "mien": bool(mien), "hors_panneau": not panneau}
    try:
        h = site_history(dn, 24)
        fiche["histoire"] = {"availability": h.get("availability"), "response_avg_ms": h.get("response_avg_ms"),
                             "response_max_ms": h.get("response_max_ms"), "samples": h.get("samples"),
                             "events": (h.get("events") or [])[:8]}
    except Exception:
        fiche["histoire"] = None
    try:
        fiche["quota"] = ssl_quota_state(dn) if panneau else None
    except Exception:
        fiche["quota"] = None
    try:
        fiche["bases"] = [{"name": b.get("name"), "size_mb": b.get("size_mb")}
                          for b in (get_fp_databases() or []) if isinstance(b, dict)
                          and _norm_domain(b.get("site") or "") == dn] if panneau else []
    except Exception:
        fiche["bases"] = []
    try:
        fiche["liens"] = site_links_list(dn).get("links", [])
    except Exception:
        fiche["liens"] = []
    try:
        fiche["journal"] = site_journal(user, dn, 12).get("lignes", [])
    except Exception:
        fiche["journal"] = []
    seul = ["status", "thumb", "history", "links"] + (["logs"] if (mien and panneau) else [])
    confirm = ["ssl_renew", "restart", "scan", "sauvegarde"] if panneau else []
    refuses = {}
    if admin and not mien:
        refuses["logs"] = "contenu réservé au propriétaire du site"
        refuses["restaurer"] = "accord du propriétaire requis"
    if not panneau:
        for g in ("ssl_renew", "restart", "scan", "sauvegarde", "logs"):
            refuses[g] = "hors panneau"
    plan = _site_plan_pour(ligne.get("fp_compte") or "") if panneau else None
    accord = site_accord_valide(dn, "restaurer") if panneau else None
    if panneau and admin and not mien and not accord:
        refuses["restaurer"] = "accord du propriétaire requis"
    elif panneau and (mien or accord):
        refuses.pop("restaurer", None)
    fiche["gestes"] = {"seul": seul, "confirm": confirm + (["restaurer"] if panneau and (mien or accord) else []), "refuses": refuses,
                       "plan": ({"id": plan.get("id"), "name": plan.get("name")} if isinstance(plan, dict) else None),
                       "retirer": bool(ligne.get("source") == "declare" and (mien or admin)),
                       "attribuer": bool(admin), "transferer": bool(admin and (ligne.get("declare_par") or [])),
                       "demander": bool(mien and not admin and ligne.get("source") == "declare" and not ligne.get("demande")),
                       "accord": bool(mien and not admin and panneau)}
    fiche["accord"] = accord
    fiche["demande"] = ligne.get("demande")
    # DNS et courrier du domaine (v2) : les mêmes lectures que l'onglet Hébergement, bornées au domaine.
    fiche["dns"], fiche["courrier"] = [], []
    if panneau:
        try:
            fiche["dns"] = [x for x in (get_fp_dns() or []) if isinstance(x, dict) and _norm_domain(x.get("zone") or "") == dn][:40]
        except Exception:
            fiche["dns"] = []
        try:
            fiche["courrier"] = [x for x in (get_fp_mail() or []) if isinstance(x, dict) and _norm_domain(x.get("domain") or "") == dn][:40]
        except Exception:
            fiche["courrier"] = []
    return fiche


_SITE_JOURNAL_ACTIONS = ("down", "ssl_renew", "restart", "ssl_expiring", "scan", "sauvegarde",
                         "declare", "retire", "attribue", "link_save", "link_delete")


def site_journal(user, domain: str = "", limite: int = 60) -> dict:
    """Le journal d'un site, ou de tous les sites de la portée : les gestes de l'écran (vault_audit
    « site:… »), ceux des outils de Cassandra (agent_actions « site:… »), les alertes aux propriétaires
    (user_activity) et les pannes et retours de la veille (site_events). Rien n'est réécrit : lu et fondu."""
    admin = is_admin(user)
    dn = _norm_domain(domain) if domain else ""
    miens = None if admin else {_norm_domain(x) for x in (user_sites(user) or []) if x}
    if dn and not admin and not _fp_appartient(dn, miens or set()):
        return {"ok": False, "reason": "site hors de ta portée", "lignes": []}

    def _dans(site):
        site = _norm_domain(site or "")
        if not site:
            return False
        if dn:
            return site == dn or site.endswith("." + dn)
        return admin or _fp_appartient(site, miens or set())
    lignes = []
    lim = max(10, min(int(limite or 60), 600))
    try:
        _site_migrate()
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        for r in conn.execute("SELECT ts, username, action, secret_name FROM vault_audit "
                              "WHERE action LIKE 'site:%' ORDER BY id DESC LIMIT ?", (lim * 3,)):
            site = str(r[3] or "").split(" ")[0]
            if _dans(site):
                lignes.append({"ts": r[0], "verbe": str(r[2] or "")[5:], "site": site,
                               "acteur": r[1] or "?", "detail": str(r[3] or "")[len(site):].strip(),
                               "source": "ecran"})
        for r in conn.execute("SELECT ts, username, actor, action, detail FROM user_activity "
                              "WHERE action IN (%s) ORDER BY id DESC LIMIT ?"
                              % ",".join("?" * len(_SITE_JOURNAL_ACTIONS)),
                              tuple(_SITE_JOURNAL_ACTIONS) + (lim * 3,)):
            site = str(r[4] or "").split(" ")[0]
            if _dans(site):
                lignes.append({"ts": r[0], "verbe": r[3], "site": site, "acteur": r[2] or "cassandra",
                               "detail": "notifié : %s" % (r[1] or "?"), "source": "alerte"})
        for r in conn.execute("SELECT ts, domain, kind, detail, duration_min FROM site_events "
                              "ORDER BY id DESC LIMIT ?", (lim * 3,)):
            if _dans(r[1]):
                d = str(r[3] or "")
                if r[4]:
                    d = (d + " · " if d else "") + "%s min" % r[4]
                lignes.append({"ts": r[0], "verbe": r[2], "site": _norm_domain(r[1] or ""),
                               "acteur": "sonde", "detail": d, "source": "veille"})
        for r in conn.execute("SELECT ts, session_id, command, output FROM agent_actions "
                              "WHERE command LIKE 'site:%' ORDER BY id DESC LIMIT ?", (lim * 3,)):
            parts = str(r[2] or "").split(":")
            if len(parts) < 3 or not _dans(parts[2]):
                continue
            try:
                qui = get_session_user(r[1]) or "cassandra"
            except Exception:
                qui = "cassandra"
            lignes.append({"ts": r[0], "verbe": parts[1], "site": _norm_domain(parts[2]),
                           "acteur": qui, "detail": str(r[3] or "")[:120], "source": "outil"})
        conn.close()
    except Exception as e:
        return {"ok": False, "reason": str(e), "lignes": lignes}
    lignes.sort(key=lambda x: str(x.get("ts") or ""), reverse=True)
    # Un même geste s'écrit deux fois (l'écran dans vault_audit, la notification dans user_activity) :
    # une seule ligne, celle de l'écran, qui dit qui a été prévenu.
    fondues = []
    for x in lignes:
        doublon = None
        for y in fondues[-6:]:
            if y.get("verbe") == x.get("verbe") and y.get("site") == x.get("site") and y.get("source") != x.get("source")                     and str(y.get("ts") or "")[:16] == str(x.get("ts") or "")[:16] and {y.get("source"), x.get("source")} == {"ecran", "alerte"}:
                doublon = y
                break
        if doublon is None:
            fondues.append(x)
            continue
        if doublon.get("source") == "alerte":
            # l'écran remplace l'alerte, en gardant « notifié : … »
            x["detail"] = " · ".join(p for p in (x.get("detail"), doublon.get("detail")) if p)
            fondues[fondues.index(doublon)] = x
        else:
            doublon["detail"] = " · ".join(p for p in (doublon.get("detail"), x.get("detail")) if p)
    return {"ok": True, "lignes": fondues[:lim], "domain": dn}


def _sites_ecrire_declares(email: str, sites: list) -> bool:
    users = load_users()
    if email not in users:
        return False
    rec = dict(_user_record(users[email]))
    rec["sites"] = sorted({_norm_domain(x) for x in sites if x})
    users[email] = rec
    return save_users(users)


def sites_declarer(user: str, domain: str, par: str = "", panneau_ok: bool = False) -> dict:
    """Un compte déclare un site qu'il possède ailleurs : la sonde le suivra, rien de plus tant qu'il n'est
    pas dans le panneau. Refusé s'il appartient déjà à un autre compte, ou si le panneau le gère (un
    site du panneau s'ATTRIBUE, par l'administrateur — `panneau_ok`)."""
    dn = _norm_domain(domain)
    if not dn or not _SITE_DOMAINE_RE.match(dn):
        return {"ok": False, "reason": "nom de domaine invalide"}
    if not user or user not in load_users():
        return {"ok": False, "reason": "compte inconnu"}
    if dn in {_norm_domain(x) for x in (user_sites(user) or [])}:
        return {"ok": False, "reason": "déjà dans la liste de ce compte"}
    if not panneau_ok and dn in _sites_panneau_domaines():
        return {"ok": False, "reason": "ce site est géré par le panneau : c'est à l'administrateur de te l'attribuer"}
    # Les administrateurs comptent comme propriétaires — sauf quand l'un d'eux attribue lui-même
    # (`panneau_ok`) : il cède alors un site qu'il détient par le panneau.
    autres = [e for e in _sites_comptes_map(avec_admins=not panneau_ok).get(dn, []) if e != user]
    if autres:
        return {"ok": False, "reason": "ce site appartient déjà à un autre compte"}
    rec = get_user_record(user)
    if not _sites_ecrire_declares(user, list(rec.get("sites") or []) + [dn]):
        return {"ok": False, "reason": "écriture des comptes impossible"}
    _sites_declares_marquer(dn, "declare", par or user, user)
    return {"ok": True, "domain": dn}


def sites_retirer(user: str, domain: str, par: str = "") -> dict:
    """Retire un site DÉCLARÉ de la liste d'un compte. Un site hérité du panneau ne se retire pas ici,
    et un site du panneau attribué par l'administrateur non plus : c'est lui qui le reprend."""
    dn = _norm_domain(domain)
    rec = get_user_record(user)
    if dn not in {_norm_domain(x) for x in (rec.get("sites") or [])}:
        if _site_est_a_moi(user, dn):
            return {"ok": False, "reason": "ce site vient du panneau : il se détache dans Réglages, pas ici"}
        return {"ok": False, "reason": "site absent de la liste"}
    if not is_admin(user) and dn in _sites_panneau_domaines():
        return {"ok": False, "reason": "ce site est géré par le panneau et t'a été attribué : seul l'administrateur le reprend"}
    if not _sites_ecrire_declares(user, [x for x in rec.get("sites") if _norm_domain(x) != dn]):
        return {"ok": False, "reason": "écriture des comptes impossible"}
    _sites_declares_marquer(dn, "retire", par or user, user)
    _SITES_VUE_CACHE["data"] = None
    return {"ok": True, "domain": dn}


def sites_attribuer(admin: str, domain: str, compte: str) -> dict:
    """L'administrateur attribue un site déclaré à un compte. Journalisé, le compte est prévenu."""
    compte = (compte or "").strip().lower()
    if compte not in load_users():
        return {"ok": False, "reason": "compte inconnu"}
    r = sites_declarer(compte, domain, par=admin, panneau_ok=True)
    if r.get("ok"):
        try:
            log_user_activity(compte, admin, "attribue", r["domain"])
        except Exception:
            pass
    return r


def _sites_declares_marquer(dn: str, verbe: str, par: str, compte: str) -> None:
    _SITES_VUE_CACHE["data"] = None
    try:
        _vault_audit(par, "site:" + verbe, dn + (" → " + compte if compte != par else ""))
    except Exception:
        pass
    try:
        log_user_activity(compte, par, verbe, dn)
    except Exception:
        pass


# ══ LA SONDE DES SITES, À SON PROPRE PAS (20-09) ══
# `site_pass()` ne vivait que dans `fp_infra_pass()`, c'est-à-dire dans la passe d'autonomie d'Itare :
# au plus une fois par jour, et seulement si l'autonomie est activée. Sur le serveur de test elle ne
# tournait en fait qu'à chaque redémarrage (les réflexes repartaient de zéro) — 2 552 relevés en
# dents de scie, puis plus rien dès que les réflexes sont devenus persistants. L'écran promet une
# sonde toutes les cinq minutes : elle part du relevé de cinq minutes, dans son propre fil, jamais
# deux fois en même temps.
_SITE_PASS_ETAT = {"t": 0.0, "en_cours": False}


def _site_pass_periodique() -> None:
    inter = max(60, int(_mem_cfg("site_watch_interval_min", 5)) * 60)
    now = time.time()
    if _SITE_PASS_ETAT["en_cours"] or now - _SITE_PASS_ETAT["t"] < inter - 15:
        return
    _SITE_PASS_ETAT["t"] = now

    def _courir():
        _SITE_PASS_ETAT["en_cours"] = True
        try:
            r = site_pass()
            if r and (r.get("alerts") or r.get("transitions")):
                logging.info("[SITES] sonde : %s site(s), %s alerte(s), %s transition(s)",
                             r.get("sites"), r.get("alerts"), len(r.get("transitions") or []))
        except Exception as e:
            logging.info("[SITES] sonde : %s", e)
        # La vue administrateur des sites se réchauffe ici, dans ce fil : la Vue d'ensemble la LIT,
        # elle ne la recalcule jamais à froid (21-09, fil 30).
        try:
            sites_vue(None, force=True, admin_force=True)
        except Exception as e:
            logging.info("[SITES] réchauffage de la vue : %s", e)
        finally:
            _SITE_PASS_ETAT["en_cours"] = False
    threading.Thread(target=_courir, daemon=True, name="site-pass").start()


# ══════════════════════════════════════════════════════════════════════════════
#  LA VUE D'ENSEMBLE (21-09, fil 30) — une route, un calcul, un âge par carte
#
#  Elle répond à une question : y a-t-il un geste à faire, et où. Elle ne
#  recalcule rien à froid : le verdict des mesures est mis en cache 60 s, la
#  prévision de disque 10 min, la vue des sites est lue dans le cache que la
#  sonde réchauffe toutes les cinq minutes. « Ce qui demande un geste » lit la
#  cloche des notifications, elle n'écrit rien. Une source qui se tait donne
#  « inconnu », jamais « stable ».
# ══════════════════════════════════════════════════════════════════════════════
_VUE_GET_ADMIN = ("/api/metrics", "/api/dashboard", "/api/ssl", "/api/sessions", "/api/ports", "/api/processes",
                  "/api/failed", "/api/docker", "/api/smart", "/api/server_info", "/api/sites", "/api/remotes",
                  "/api/tailscale", "/api/fail2ban", "/api/oom")
_VUE_CACHE = {"verdict_t": 0.0, "verdict": None, "forecast_t": 0.0, "forecast": None, "chauffe_t": 0.0}


def _vue_cache_lire(cle: str, ttl: int, calc, defaut) -> dict:
    """Un cache de la vue : à froid on calcule (une fois par processus) ; périmé, on REND la valeur d'avant
    et on recalcule dans un fil. Le chemin de l'écran ne paie jamais un calcul — `metric_verdict` coûte
    400 ms (il mesure), et le relevé de l'écran toutes les 60 s tombait chaque fois sur le cache périmé."""
    now = time.time()

    def _calc():
        try:
            _VUE_CACHE[cle] = calc()
        except Exception as e:
            _VUE_CACHE[cle] = defaut(e)
        _VUE_CACHE[cle + "_t"] = time.time()

    if _VUE_CACHE.get(cle) is None:
        _calc()
    elif now - _VUE_CACHE.get(cle + "_t", 0) > ttl and now - _VUE_CACHE.get(cle + "_chauffe", 0) > 30:
        _VUE_CACHE[cle + "_chauffe"] = now
        threading.Thread(target=_calc, daemon=True, name="vue-" + cle).start()
    return _VUE_CACHE[cle]


def _vue_mesures() -> dict:
    return _vue_cache_lire("verdict", 60, metric_verdict,
                           lambda e: {"ok": False, "niveau": "inconnu", "titre": "Verdict des mesures illisible",
                                      "sous_titre": str(e)[:120], "lignes": [], "sources": {}, "lu_le": ""})


def _vue_forecast() -> dict:
    return _vue_cache_lire("forecast", 600, lambda: metric_forecast("disk") or {},
                           lambda e: {"ok": False, "reason": str(e)[:120]})


def _vue_metriques():
    """Les jauges de la machine SANS mesurer, et le collecteur dit vivant sans mesurer non plus.
    GET_METRICS fait dormir le collecteur 300 ms (`get_cpu` compare deux lectures de /proc/stat) : c'était
    toute la durée de la vue. La trame WebSocket de la seconde (déjà mesurée pour les jauges) sert d'abord
    quand elle a moins de 15 s ; sinon la dernière ligne écrite par le collecteur (toutes les 30 s).
    Rend (mesures, collecteur_vivant, unités tombées, source des mesures)."""
    m, src = {}, ""
    try:
        p = json.loads(_ws_last_payload) if _ws_last_payload else {}
        ts = str(p.get("ts") or "")
        if p.get("type") == "metrics" and ts and (datetime.now() - datetime.fromisoformat(ts[:19])).total_seconds() < 15:
            m, src = dict(p.get("metrics") or {}), "websocket"
    except Exception:
        m = {}
    # Le collecteur est vivant parce qu'il ÉCRIT : sa dernière ligne de mesures (toutes les 30 s) a moins
    # de 90 s. Aucune demande au socket : le diffuseur WebSocket l'occupe 300 ms par seconde (GET_METRICS
    # mesure en dormant) et le socket sert un client à la fois — une lecture d'entité de 8 ms y attendait
    # jusqu'à 200 ms.
    vivant = False
    try:
        rows = query_db("SELECT ts FROM metrics_realtime ORDER BY id DESC LIMIT 1") or []
        ts = str((rows[0] if rows else {}).get("ts") or "")
        if ts:
            vivant = abs((datetime.now() - datetime.fromisoformat(ts[:19])).total_seconds()) < 90
    except Exception:
        vivant = False
    # Les unités tombées : la table que le collecteur écrit — la même que le socket rendait — et jamais
    # la commande système sur le chemin de l'écran.
    try:
        failed = [u for u in (query_db("SELECT unit, active_state, description FROM failed_units "
                                       "WHERE active_state = 'failed'") or [])
                  if isinstance(u, dict) and u.get("unit", "?") not in UNIT_BULLETS and u.get("unit", "?") != "?"]
    except Exception:
        failed = []
    if not m:
        try:
            m, src = get_metrics_fallback() or {}, "base"
        except Exception:
            m, src = {}, ""
    return m, vivant, failed, src


def _vue_sites_admin():
    """La vue administrateur des sites, LUE dans son cache quel que soit son âge ; réchauffée en fil
    si elle manque ou date de plus de dix minutes. Jamais calculée sur le chemin de l'écran."""
    c = _SITES_VUE_CACHES.get("admin|")
    age = (time.time() - c["t"]) if c else None
    if (c is None or age > 600) and time.time() - _VUE_CACHE["chauffe_t"] > 60:
        _VUE_CACHE["chauffe_t"] = time.time()
        threading.Thread(target=lambda: sites_vue(None, force=True, admin_force=True),
                         daemon=True, name="vue-chauffe").start()
    return (c or {}).get("data"), age


def _vue_compter(sql: str, args=()) -> int:
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        n = conn.execute(sql, args).fetchone()[0] or 0
        conn.close()
        return int(n)
    except Exception:
        return 0


def _vue_heure(ts) -> str:
    t = str(ts or "")
    return t[11:16] if len(t) >= 16 else t


def _vue_gestes_cloche(user, admin: bool, limite: int = 6) -> dict:
    """La liste « ce qui demande un geste » : les notifications à faire, puis celles en cours, la critique
    d'abord ; chaque ligne garde sa clé, son renvoi (`aller`) et ses actions — l'écran ne décide rien.
    Les MÊMES filtres que `notifs()` (à faire, en cours, destinataires), lus en une connexion et sans les
    compteurs, le battement et l'urgence que `notifs()` recalcule à chaque appel (deux appels = 25-48 ms
    en service) ; seules les lignes rendues sont enrichies, les autres ne font que compter."""
    compte = (user or "").strip().lower()
    filtre, args = _nt_filtre_dest(compte, admin)
    ordre = {"critique": 0, "avoir": 1, "info": 2}
    bruts, lignes, vus = [], [], set()
    try:
        _nt_migrate()
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10); conn.row_factory = sqlite3.Row
        for ou, tri in ((" AND n.resolue = 0 AND (n.niveau = 'critique' OR n.nature IN ('decision','evenement'))",
                         "ORDER BY CASE n.niveau WHEN 'critique' THEN 0 WHEN 'avoir' THEN 1 ELSE 2 END, n.id DESC"),
                        (" AND n.resolue = 0 AND n.nature = 'etat' AND n.niveau = 'avoir'", "ORDER BY n.maj DESC")):
            q = ("SELECT n.*, d.vu_le AS vu_le, d.acquitte_le AS acquitte_le FROM notifs n "
                 "LEFT JOIN notif_dest d ON d.notif = n.id AND d.compte = ? WHERE 1=1 %s%s %s LIMIT 12" % (ou, filtre, tri))
            for r in conn.execute(q, [compte] + list(args)).fetchall():
                x = dict(r)
                if x.get("id") in vus:
                    continue
                vus.add(x.get("id"))
                bruts.append(x)
        bruts.sort(key=lambda x: (ordre.get(x.get("niveau"), 3), -(x.get("id") or 0)))
        for x in bruts[:limite]:
            x = _nt_enrichir(conn, x, compte)
            lignes.append({"id": x.get("id"), "cle": x.get("cle"), "source": x.get("source"),
                           "source_nom": x.get("source_nom"), "sujet": x.get("sujet"), "niveau": x.get("niveau"),
                           "nature": x.get("nature"), "titre": x.get("titre"), "corps": str(x.get("corps") or "")[:200],
                           "n": x.get("n"), "maj": x.get("maj") or x.get("ts"), "aller": x.get("aller"),
                           "actions": x.get("actions") or [], "provenance": x.get("provenance")})
        conn.close()
    except Exception as e:
        logging.info("[VUE] cloche : %s", e)
    try:
        cpt = notif_compteurs(compte, admin)
    except Exception:
        cpt = {}
    return {"lignes": lignes, "total": len(bruts), "compteurs": cpt}


def _vue_cassandra_calc() -> dict:
    """La carte « Cassandra, maintenant », part lente : réglages, palier et budget (deux migrations),
    trois COUNT, les fils du salon en attente — en cache 30 s. Le vif (collecteur, WebSocket, version)
    se pose dans `vue_ensemble`."""
    try:
        cfg = get_cassandra_config() or {}
    except Exception:
        cfg = {}
    try:
        auto = pf_autonomie() or {}
    except Exception:
        auto = {}
    try:
        budget = (pf_budget_utilise() or {}).get("jour", 0)
    except Exception:
        budget = 0
    faites24 = _vue_compter("SELECT COUNT(*) FROM proactive_findings WHERE status='acted' AND acted_at >= datetime('now','-1 day')")
    notifs24 = _vue_compter("SELECT COUNT(*) FROM notifs WHERE ts >= datetime('now','-1 day')")
    avis = _vue_compter("SELECT COUNT(*) FROM proactive_findings WHERE status='pending'")
    try:
        attente = len(salon_fils(statut="attente") or [])
    except Exception:
        attente = 0
    return {"modele": cfg.get("model") or "", "fournisseur": cfg.get("provider") or "", "itare": cfg.get("itare_citadelle_model") or cfg.get("itare_model") or "",
            "palier": auto.get("palier"), "palier_nom": auto.get("palier_nom"), "budget_jour": auto.get("budget_jour"), "budget_utilise": budget,
            "pause": bool(auto.get("pause")), "faites24": faites24, "notifs24": notifs24, "avis": avis, "salon_attente": attente}


def vue_ensemble(user) -> dict:
    """La Vue d'ensemble d'un administrateur (tout) ou d'un compte (ses sites, ses notifications)."""
    t0 = time.time()
    admin = is_admin(user)
    if not admin:
        return _vue_compte(user, t0)
    ages, sources = {}, {}
    # Le budget se tient brique par brique : `profil` (ms par étape) part avec la réponse, lu dans la charge.
    profil, _tp = {}, [time.time()]

    def _lap(nom):
        n = time.time()
        profil[nom] = int((n - _tp[0]) * 1000)
        _tp[0] = n
    # ── la machine et le collecteur : jamais une mesure sur le chemin de l'écran (lot G) ──
    m, collecteur_vivant, failed, m_source = _vue_metriques()
    _lap("machine")
    try:
        hs = get_health_score() or {}
    except Exception:
        hs = {}
    _lap("sante")
    # ── les sites : dernière sonde (une lecture) + cache administrateur (jamais à froid) ──
    sonde = _sites_derniere_sonde()
    sv, sv_age = _vue_sites_admin()
    sites = []
    if sv:
        for x in sv.get("sites", []):
            so = sonde.get(_norm_domain(x.get("domain") or "")) or x.get("sonde") or {}
            sites.append({"domain": x.get("domain"), "source": x.get("source"), "up": so.get("up") if so else x.get("up"),
                          "http_code": so.get("http_code") if so else x.get("http_code"), "response_ms": (so or {}).get("response_ms"),
                          "ssl_days": x.get("ssl_days") if x.get("ssl_days") is not None else (so or {}).get("ssl_days"),
                          "sauvegarde": x.get("sauvegarde"), "scan": x.get("scan"), "fp_compte": x.get("fp_compte"),
                          "comptes": x.get("comptes") or []})
        ages["sites"] = sv.get("releve")
    else:
        for dn, so in sonde.items():
            sites.append({"domain": dn, "source": "sonde", "up": so.get("up"), "http_code": so.get("http_code"),
                          "response_ms": so.get("response_ms"), "ssl_days": so.get("ssl_days"), "sauvegarde": None,
                          "scan": None, "fp_compte": "", "comptes": []})
        ages["sites"] = None
    sites.sort(key=lambda x: (0 if x.get("up") is False else 1, str(x.get("domain") or "")))
    ages["sonde"] = max([str(v.get("ts") or "") for v in sonde.values()] or [""]) or None
    n_sites = len(sites)
    _lap("sites")
    tombes = [x for x in sites if x.get("up") is False]
    en_ligne = sum(1 for x in sites if x.get("up") is True)
    tls = sorted([(x["ssl_days"], x["domain"]) for x in sites if isinstance(x.get("ssl_days"), (int, float))])
    tls_min = tls[0] if tls else None
    panneau = [x for x in sites if x.get("source") == "panneau"]
    copies = sorted([str((x.get("sauvegarde") or {}).get("at") or "") for x in panneau if x.get("sauvegarde")], reverse=True)
    sans_copie = [x["domain"] for x in panneau if not x.get("sauvegarde")]
    infectes = [x["domain"] for x in panneau if (x.get("scan") or {}).get("status") == "infecté"]
    scans_revoir = 0
    for x in panneau:
        sc = x.get("scan")
        if not sc or sc.get("status") == "infecté":
            scans_revoir += 1
        else:
            try:
                if (datetime.utcnow() - datetime.strptime(str(sc.get("at"))[:19], "%Y-%m-%d %H:%M:%S")).days > 30:
                    scans_revoir += 1
            except Exception:
                pass
    # ── les unités tombées : lues avec la preuve de vie du collecteur, plus haut ──
    noms_failed = [str((u.get("unit") if isinstance(u, dict) else u) or "?") for u in failed][:5]
    # ── le disque ──
    fc = _vue_forecast() or {}
    sat_j = fc.get("saturation_days")
    _lap("forecast")
    # ── la flotte : flotte_parc fait foi (attendue ≠ intermittente ≠ retirée) ; quatre sources, 25 ms en
    # service → 30 s de cache rendu périmé puis recalculé en fil ──
    fp = _vue_cache_lire("flotte", 30, lambda: flotte_parc() or {}, lambda e: {"ok": False, "reason": str(e)[:120]}) or {}
    machines = [z for z in (fp.get("machines") or []) if isinstance(z, dict) and z.get("statut") == "attendue" and not z.get("disparue")]
    machines_hl = [z for z in machines if z.get("etat") == "erreur" or z.get("en_ligne") is False]
    ages["flotte"] = fp.get("releve")
    _lap("flotte")
    # ── les incidents ──
    try:
        inc = (pf_incidents(limit=20) or {}).get("incidents") or []
    except Exception:
        inc = []
    inc_ouverts = [i for i in inc if str(i.get("statut") or "ouvert") == "ouvert"]
    _lap("incidents")
    # ── le redémarrage requis ──
    reboot = os.path.exists("/var/run/reboot-required")
    # ── le verdict composite ──
    base = _vue_mesures()
    _lap("verdict")
    pannes, regarder = [], []
    for x in tombes:
        pannes.append({"titre": "%s ne répond pas%s" % (x["domain"], (" (code %s)" % x["http_code"]) if x.get("http_code") else ""),
                       "geste": {"type": "site", "action": "restart" if x.get("source") == "panneau" else "status", "domain": x["domain"],
                                 "label": ("Redémarrer PHP de %s" if x.get("source") == "panneau" else "Vérifier %s") % x["domain"]}})
    for z in machines_hl:
        dc = str(z.get("dernier_contact") or "")
        pannes.append({"titre": "%s est attendue et ne répond plus%s" % (z.get("nom"), (" depuis %s" % _vue_heure(dc)) if dc else ""),
                       "geste": {"type": "aller", "aller": ["fleet", "flOpen", z.get("nom")], "label": "Voir %s" % z.get("nom")}})
    for u in noms_failed:
        pannes.append({"titre": "unité %s tombée" % u, "geste": {"type": "aller", "aller": ["fastpanel", "fpNav", "services"], "label": "Voir les services"}})
    for d in infectes:
        pannes.append({"titre": "analyse antivirus positive sur %s" % d, "geste": {"type": "site", "action": "scan", "domain": d, "label": "Relancer l'analyse"}})
    if tls_min and tls_min[0] < 7:
        pannes.append({"titre": "certificat de %s : %d jour(s)" % (tls_min[1], tls_min[0]),
                       "geste": {"type": "site", "action": "ssl_renew", "domain": tls_min[1], "label": "Renouveler le certificat"}})
    elif tls_min and tls_min[0] < 21:
        regarder.append({"titre": "certificat de %s dans %d jours" % (tls_min[1], tls_min[0]),
                         "geste": {"type": "site", "action": "ssl_renew", "domain": tls_min[1], "label": "Renouveler le certificat"}})
    if isinstance(sat_j, (int, float)):
        if sat_j <= 7:
            pannes.append({"titre": "disque plein dans %d jour(s)" % int(sat_j), "geste": {"type": "aller", "aller": ["history", "mxOpen", "disk"], "label": "Voir le disque"}})
        elif sat_j <= 30:
            regarder.append({"titre": "disque plein dans %d jours" % int(sat_j), "geste": {"type": "aller", "aller": ["history", "mxOpen", "disk"], "label": "Voir le disque"}})
    for i in inc_ouverts[:3]:
        regarder.append({"titre": "incident ouvert : %s" % str(i.get("titre") or i.get("cle") or "?")[:80],
                         "geste": {"type": "aller", "aller": ["proactive", "pfVue", "inc"], "label": "Voir les incidents"}})
    if panneau and sans_copie and len(sans_copie) == len(panneau):
        regarder.append({"titre": "aucune sauvegarde connue pour les %d sites du panneau" % len(panneau),
                         "geste": {"type": "aller", "aller": ["fastpanel", "fpNav", "backups"], "label": "Voir les sauvegardes"}})
    elif copies:
        try:
            age_j = (datetime.utcnow() - datetime.strptime(copies[0][:19], "%Y-%m-%d %H:%M:%S")).days
            if age_j > 2:
                regarder.append({"titre": "dernière sauvegarde il y a %d jours" % age_j,
                                 "geste": {"type": "aller", "aller": ["fastpanel", "fpNav", "backups"], "label": "Voir les sauvegardes"}})
        except Exception:
            pass
    if scans_revoir and not infectes:
        regarder.append({"titre": "%d site(s) sans analyse antivirus récente" % scans_revoir,
                         "geste": {"type": "aller", "aller": ["mysites", "stAller", "alertes"], "label": "Voir dans Sites"}})
    if reboot:
        regarder.append({"titre": "redémarrage du système requis (noyau ou bibliothèque mise à jour)",
                         "geste": {"type": "aller", "aller": ["proactive", "pfVue", "inc"], "label": "Voir la proactivité"}})
    for l in (base.get("lignes") or []):
        tt = str(l.get("titre") or "")
        if l.get("niveau") in ("panne", "regarder") and not any(w in tt.lower() for w in ("ne répond", "hors ligne", "attendue", "disque")):
            (pannes if l.get("niveau") == "panne" else regarder).append({"titre": tt, "detail": l.get("detail"),
                                                                        "geste": {"type": "aller", "aller": ["history", None, None], "label": "Voir les mesures"}})
    muettes = list((base.get("sources") or {}).get("muettes") or [])
    if not collecteur_vivant:
        muettes.insert(0, "collecteur")
    if pannes:
        niveau = "panne"
        titre = pannes[0]["titre"][0].upper() + pannes[0]["titre"][1:]
        if len(pannes) > 1:
            titre = "%d pannes : %s et %s" % (len(pannes), pannes[0]["titre"], pannes[1]["titre"]) if len(pannes) == 2 else \
                    "%d pannes : %s, et %d autres" % (len(pannes), pannes[0]["titre"], len(pannes) - 1)
        sous = "%d site%s sur %d répond%s, %d machine%s attendue%s en ligne sur %d, %d unité%s tombée%s. %s" % (
            en_ligne, "s" if en_ligne > 1 else "", n_sites, "ent" if en_ligne > 1 else "", len(machines) - len(machines_hl),
            "s" if (len(machines) - len(machines_hl)) > 1 else "", "s" if (len(machines) - len(machines_hl)) > 1 else "", len(machines),
            len(noms_failed), "s" if len(noms_failed) > 1 else "", "s" if len(noms_failed) > 1 else "",
            ("%d point%s à regarder derrière." % (len(regarder), "s" if len(regarder) > 1 else "")) if regarder else "")
    elif not collecteur_vivant:
        niveau = "inconnu"
        titre = "Inconnu : le collecteur se tait"
        sous = "Aucune mesure machine à l'instant ; les sites, la flotte et les sauvegardes ont leur propre relevé. Le verdict ne dit pas « stable » tant que la machine ne parle pas."
    elif regarder:
        niveau = "regarder"
        titre = "Rien de cassé, %d point%s à regarder" % (len(regarder), "s" if len(regarder) > 1 else "")
        sous = "%d site%s répondent, %d machine%s attendue%s en ligne, %s. À regarder : %s." % (
            en_ligne, "s" if en_ligne > 1 else "", len(machines), "s" if len(machines) > 1 else "", "s" if len(machines) > 1 else "",
            ("dernière sauvegarde %s" % str(copies[0])[:16]) if copies else "aucune sauvegarde connue",
            " ; ".join(r["titre"] for r in regarder[:3]))
    else:
        niveau = "stable"
        titre = "Rien ne demande un geste ce matin" if 5 <= datetime.now().hour < 12 else "Rien ne demande un geste"
        _nu = len(SERVICES_LIST) if "SERVICES_LIST" in globals() else 0
        sous = "%d site%s répondent, %d machine%s attendue%s en ligne, %s, %s, certificats et analyses à jour." % (
            en_ligne, "s" if en_ligne > 1 else "", len(machines), "s" if len(machines) > 1 else "", "s" if len(machines) > 1 else "",
            ("dernière sauvegarde %s" % str(copies[0])[:16]) if copies else "aucune sauvegarde connue",
            ("%d unités suivies, aucune tombée" % _nu) if _nu else "aucune unité tombée")
    if muettes and niveau == "stable":
        niveau = "inconnu"
        titre = "Inconnu : %s se tai%s" % (", ".join(muettes[:3]), "sent" if len(muettes) > 1 else "t")
    gestes = [p["geste"] for p in pannes[:2]] + [r["geste"] for r in regarder[:1]]
    gestes.append({"type": "aller", "aller": ["overview", "vuAller", "gestes"], "label": "Tout ce qui demande un geste"})
    # ── les huit compteurs ──
    fl_c = fp.get("compte") or {}
    # Le détail de la santé : le score de la machine AVANT le malus, et le malus en valeur absolue — le
    # serveur le range négatif, l'écran écrivait « machine 88.0 · malus flotte −-12 ».
    _hs_bd = hs.get("breakdown") or {}
    try:
        _hs_mal = abs(int(round(float((_hs_bd.get("flotte") or {}).get("malus", 0) or 0))))
    except Exception:
        _hs_mal = 0
    try:
        _hs_loc = int(round(float(_hs_bd["local"]) if _hs_bd.get("local") is not None else (float(hs.get("score") or 0) + _hs_mal)))
    except Exception:
        _hs_loc = hs.get("score")
    compteurs = [
        {"cle": "sante", "nom": "Santé", "valeur": hs.get("score"), "unite": "", "niveau": ("panne" if (hs.get("score") or 0) < 50 else "regarder" if (hs.get("score") or 0) < 75 else "ok") if hs else "inconnu",
         "detail": ("machine %s · malus flotte −%s" % (_hs_loc, _hs_mal)) if hs else "pas de score",
         "source": "WebSocket · 1 s" if collecteur_vivant else "collecteur muet", "aller": ["history", "mxOpen", "fleet_up"]},
        {"cle": "sites", "nom": "Sites en ligne", "valeur": "%d / %d" % (en_ligne, n_sites), "niveau": "panne" if tombes else ("ok" if n_sites else "inconnu"),
         "detail": (tombes[0]["domain"] + (" · %s" % tombes[0]["http_code"] if tombes[0].get("http_code") else " · ne répond pas")) if tombes else ("tous répondent" if n_sites else "aucun site connu"),
         "source": "sonde · %s" % (_vue_heure(ages["sonde"]) if ages.get("sonde") else "jamais"), "aller": ["mysites", "stFiltre", "tombes"]},
        {"cle": "tls", "nom": "TLS", "valeur": ("%d j" % tls_min[0]) if tls_min else "—", "niveau": ("panne" if tls_min[0] < 7 else "regarder" if tls_min[0] < 21 else "ok") if tls_min else "inconnu",
         "detail": ("%s · %d autre%s" % (tls_min[1], len(tls) - 1, "s" if len(tls) > 2 else "")) if tls_min else "aucun certificat connu",
         "source": "sonde · 1 h", "aller": ["mysites", "stOpen", tls_min[1] if tls_min else None]},
        {"cle": "sauvegardes", "nom": "Sauvegardes", "valeur": (_vue_heure(copies[0]) + " · " + str(copies[0])[5:10]) if copies else "aucune", "niveau": ("regarder" if sans_copie else "ok") if panneau else "inconnu",
         "detail": ("%d / %d sites couverts" % (len(panneau) - len(sans_copie), len(panneau))) if panneau else "pas de panneau",
         "source": "panneau · %s" % (_vue_heure(ages.get("sites")) if ages.get("sites") else "pas encore relevé"), "aller": ["fastpanel", "fpNav", "backups"]},
        {"cle": "services", "nom": "Services tombés", "valeur": len(noms_failed), "niveau": "panne" if noms_failed else "ok",
         "detail": ", ".join(noms_failed[:3]) if noms_failed else "aucune unité tombée", "source": "collecteur · %s" % (_vue_heure(_utcnow().strftime("%Y-%m-%d %H:%M")) if collecteur_vivant else "muet"),
         "aller": ["fastpanel", "fpNav", "services"]},
        {"cle": "disque", "nom": "Disque", "valeur": ("%d j" % int(sat_j)) if isinstance(sat_j, (int, float)) else ("%d %%" % round(m.get("disk") or 0) if m else "—"),
         "niveau": ("panne" if sat_j <= 7 else "regarder" if sat_j <= 30 else "ok") if isinstance(sat_j, (int, float)) else "ok",
         "detail": ("%d %% · avant saturation" % round(m.get("disk") or 0)) if isinstance(sat_j, (int, float)) else (fc.get("note") or "tendance stable"),
         "source": "prévision · 10 min", "aller": ["history", "mxOpen", "disk"]},
        {"cle": "flotte", "nom": "Flotte attendue", "valeur": "%d / %d" % (len(machines) - len(machines_hl), len(machines)), "niveau": "panne" if machines_hl else ("ok" if machines else "inconnu"),
         "detail": (machines_hl[0].get("nom") + " · " + (_vue_heure(machines_hl[0].get("dernier_contact")) or "?")) if machines_hl else ("%d intermittente%s à part" % (fl_c.get("volontaires") or 0, "s" if (fl_c.get("volontaires") or 0) > 1 else "") if fl_c.get("volontaires") else "toutes en ligne"),
         "source": "présence · %s" % (_vue_heure(ages.get("flotte")) if ages.get("flotte") else "jamais"), "aller": ["fleet", "flVue", "signaux"]},
        {"cle": "incidents", "nom": "Incidents ouverts", "valeur": len(inc_ouverts), "niveau": "regarder" if inc_ouverts else "ok",
         "detail": (str(inc_ouverts[0].get("titre") or inc_ouverts[0].get("cle") or "")[:60]) if inc_ouverts else "aucun", "source": "proactivité · 5 min", "aller": ["proactive", "pfVue", "inc"]},
    ]
    # ── ce qui demande un geste : la cloche ──
    _lap("compteurs")
    cloche = _vue_gestes_cloche(user, True, 6)
    _lap("cloche")
    # ── Cassandra, maintenant : la part lente en cache 30 s, le vif posé ici ──
    cass = dict(_vue_cache_lire("cass", 30, _vue_cassandra_calc, lambda e: {}) or {})
    cass.update({"collecteur": collecteur_vivant, "ws_clients": len(_ws_clients), "version": CASSANDRA_VERSION,
                 "demarre": datetime.fromtimestamp(START_TIME).strftime("%Y-%m-%d %H:%M") if START_TIME else ""})
    _lap("cassandra")
    # ── le fil : six journaux sur 24 h, 15 ms → 30 s de cache rendu périmé puis recalculé en fil ──
    try:
        rf = _vue_cache_lire("fil", 30, lambda: pf_fil(24, 8) or {}, lambda e: {}) or {}
        fil = rf.get("fil") or rf.get("lignes") or rf.get("items") or []
    except Exception:
        fil = []
    _lap("fil")
    return {"ok": True, "admin": True, "compte": user, "niveau": niveau, "titre": titre, "sous_titre": sous, "gestes": gestes,
            "pannes": pannes, "regarder": regarder, "muettes": muettes, "compteurs": compteurs, "cloche": cloche, "cassandra": cass,
            "sites": sites[:10], "n_sites": n_sites, "flotte": {"machines": [{"nom": z.get("nom"), "en_ligne": z.get("en_ligne"), "etat": z.get("etat"),
                                                                            "dernier_contact": z.get("dernier_contact"), "os": z.get("os")} for z in machines[:8]],
                                                                "compte": fl_c, "hors_ligne": [z.get("nom") for z in machines_hl]},
            "fil": fil[:8] if isinstance(fil, list) else [],
            "machine": {"cpu": m.get("cpu"), "ram": m.get("ram"), "disk": m.get("disk"), "load_1m": m.get("load_1m"), "vivant": collecteur_vivant,
                        "source": m_source},
            "ages": {"sonde": ages.get("sonde"), "sites": ages.get("sites"), "sites_age_s": int(sv_age) if sv_age is not None else None,
                     "flotte": ages.get("flotte"), "mesures": base.get("lu_le"), "machine": _utcnow().strftime("%Y-%m-%d %H:%M:%S") if collecteur_vivant else None},
            "releve": _utcnow().strftime("%Y-%m-%d %H:%M:%S"), "profil": profil, "duree_ms": int((time.time() - t0) * 1000)}


def _vue_compte(user, t0=None) -> dict:
    """La vue d'un compte ordinaire : SES sites, SES notifications, des renvois. Aucun fait machine."""
    t0 = t0 or time.time()
    try:
        sv = sites_vue(user) or {}
    except Exception as e:
        sv = {"ok": False, "sites": [], "vigilances": [], "reason": str(e)[:120]}
    sites = sv.get("sites") or []
    tombes = [x for x in sites if x.get("up") is False]
    en_ligne = sum(1 for x in sites if x.get("up") is True)
    tls = sorted([(x["ssl_days"], x["domain"]) for x in sites if isinstance(x.get("ssl_days"), (int, float))])
    panneau = [x for x in sites if x.get("source") == "panneau"]
    copies = sorted([str((x.get("sauvegarde") or {}).get("at") or "") for x in panneau if x.get("sauvegarde")], reverse=True)
    if tombes:
        niveau, titre = "panne", "%s ne répond pas" % tombes[0]["domain"]
    elif tls and tls[0][0] < 21:
        niveau, titre = "regarder", "Tes %d site%s répondent · le certificat de %s expire dans %d jours" % (len(sites), "s" if len(sites) > 1 else "", tls[0][1], tls[0][0])
    elif not sites:
        niveau, titre = "inconnu", "Aucun site dans ta portée"
    else:
        niveau, titre = "stable", "Tes %d site%s répondent" % (len(sites), "s" if len(sites) > 1 else "")
    compteurs = [
        {"cle": "sites", "nom": "En ligne", "valeur": "%d / %d" % (en_ligne, len(sites)), "niveau": "panne" if tombes else "ok", "detail": tombes[0]["domain"] if tombes else "tous répondent", "source": "sonde", "aller": ["mysites", "stFiltre", "tombes"]},
        {"cle": "tls", "nom": "TLS", "valeur": ("%d j" % tls[0][0]) if tls else "—", "niveau": ("panne" if tls[0][0] < 7 else "regarder" if tls[0][0] < 21 else "ok") if tls else "inconnu", "detail": tls[0][1] if tls else "—", "source": "sonde", "aller": ["mysites", "stOpen", tls[0][1] if tls else None]},
        {"cle": "sauvegardes", "nom": "Sauvegardes", "valeur": _vue_heure(copies[0]) if copies else "—", "niveau": "ok" if copies else ("regarder" if panneau else "inconnu"), "detail": "%d sites du panneau" % len(panneau), "source": "panneau", "aller": ["mysites", "stAller", "journal"]},
        {"cle": "analyses", "nom": "Analyses", "valeur": sum(1 for v in (sv.get("vigilances") or []) if v.get("geste") == "scan"), "niveau": "regarder" if any(v.get("geste") == "scan" for v in (sv.get("vigilances") or [])) else "ok", "detail": "à revoir", "source": "panneau", "aller": ["mysites", "stAller", "alertes"]},
    ]
    return {"ok": True, "admin": False, "compte": user, "niveau": niveau, "titre": titre,
            "sous_titre": "%d du panneau, %d déclaré%s." % (len(panneau), len(sites) - len(panneau), "s" if (len(sites) - len(panneau)) > 1 else ""),
            "gestes": [{"type": "aller", "aller": ["mysites", None, None], "label": "Ouvrir Sites"}], "compteurs": compteurs,
            "cloche": _vue_gestes_cloche(user, False, 6), "sites": sites[:10], "n_sites": len(sites),
            "releve": sv.get("releve"), "duree_ms": int((time.time() - t0) * 1000)}


# ══ SITES, V2 (20-09) : demandes d'adossement, accords et restauration, rapport mensuel, transfert ══
_SITE_V2_SEEN = [False]


def _site_v2_migrate() -> None:
    if _SITE_V2_SEEN[0]:
        return
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        conn.execute("CREATE TABLE IF NOT EXISTS site_demandes (id INTEGER PRIMARY KEY AUTOINCREMENT, "
                     "ts TEXT DEFAULT (datetime('now')), domain TEXT, compte TEXT, message TEXT, "
                     "statut TEXT DEFAULT 'ouverte', reponse TEXT, traite_par TEXT, traite_ts TEXT)")
        conn.execute("CREATE TABLE IF NOT EXISTS site_accords (id INTEGER PRIMARY KEY AUTOINCREMENT, "
                     "ts TEXT DEFAULT (datetime('now')), domain TEXT, compte TEXT, geste TEXT, jusqu_a TEXT, par TEXT)")
        conn.execute("CREATE TABLE IF NOT EXISTS site_rapports_envoyes (id INTEGER PRIMARY KEY AUTOINCREMENT, "
                     "ts TEXT DEFAULT (datetime('now')), domain TEXT, mois TEXT, compte TEXT)")
        conn.commit(); conn.close()
        _SITE_V2_SEEN[0] = True
    except Exception as e:
        logging.warning("[SITES] tables v2 : %s", e)


def sites_demandes_lister(statut: str = "ouverte", compte: str = "") -> list:
    _site_v2_migrate()
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        q = "SELECT id, ts, domain, compte, message, statut, reponse, traite_par, traite_ts FROM site_demandes"
        cond, args = [], []
        if statut:
            cond.append("statut = ?"); args.append(statut)
        if compte:
            cond.append("compte = ?"); args.append(compte)
        if cond:
            q += " WHERE " + " AND ".join(cond)
        rows = conn.execute(q + " ORDER BY id DESC LIMIT 200", tuple(args)).fetchall()
        conn.close()
    except Exception:
        return []
    return [{"id": r[0], "ts": r[1], "domain": r[2], "compte": r[3], "message": r[4], "statut": r[5],
             "reponse": r[6], "traite_par": r[7], "traite_ts": r[8]} for r in rows]


def sites_demander(user: str, domain: str, message: str = "") -> dict:
    """Un compte demande que son site déclaré passe au panneau. Une demande ouverte par site ; les
    administrateurs la voient en vigilance et en notification."""
    dn = _norm_domain(domain)
    rec = get_user_record(user)
    if dn not in {_norm_domain(x) for x in (rec.get("sites") or [])}:
        return {"ok": False, "reason": "ce site n'est pas déclaré par ton compte"}
    if dn in _sites_panneau_domaines():
        return {"ok": False, "reason": "ce site est déjà géré par le panneau"}
    _site_v2_migrate()
    message = str(message or "").strip()[:500]
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        deja = conn.execute("SELECT id FROM site_demandes WHERE domain=? AND statut='ouverte'", (dn,)).fetchone()
        if deja:
            conn.execute("UPDATE site_demandes SET message=?, ts=datetime('now'), compte=? WHERE id=?", (message, user, deja[0]))
            did = deja[0]
        else:
            conn.execute("INSERT INTO site_demandes (domain, compte, message) VALUES (?,?,?)", (dn, user, message))
            did = conn.execute("SELECT last_insert_rowid()").fetchone()[0]
        conn.commit(); conn.close()
    except Exception as e:
        return {"ok": False, "reason": str(e)}
    _SITES_VUE_CACHE["data"] = None
    try:
        notif("Adossement demandé : %s" % dn,
              "%s demande que son site %s passe au panneau.%s" % (user, dn, (" « %s »" % message) if message else ""),
              source="site", niveau="avoir", nature="decision", sujet=dn, cle="site:adossement:" + dn, dest=["admins"])
    except Exception as e:
        logging.info("[SITES] notification de demande : %s", e)
    try:
        _vault_audit(user, "site:demande", dn)
        log_user_activity(user, user, "demande", dn)
    except Exception:
        pass
    return {"ok": True, "id": did, "domain": dn}


def sites_demande_repondre(admin: str, did, decision: str, reponse: str = "") -> dict:
    """« fait » (l'administrateur a adossé le site dans le panneau) ou « refusee » : la demande se ferme,
    la notification se résout, le compte est prévenu."""
    _site_v2_migrate()
    decision = "fait" if str(decision or "").lower().startswith("f") else "refusee"
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        r = conn.execute("SELECT id, domain, compte FROM site_demandes WHERE id=? AND statut='ouverte'", (int(did),)).fetchone()
        if not r:
            conn.close()
            return {"ok": False, "reason": "demande introuvable ou déjà traitée"}
        conn.execute("UPDATE site_demandes SET statut=?, reponse=?, traite_par=?, traite_ts=datetime('now') WHERE id=?",
                     (decision, str(reponse or "")[:500], admin, r[0]))
        conn.commit(); conn.close()
    except Exception as e:
        return {"ok": False, "reason": str(e)}
    dn, compte = r[1], r[2]
    _SITES_VUE_CACHE["data"] = None
    try:
        notif_resoudre_cle("site:adossement:" + dn, par=admin, detail=decision)
    except Exception:
        pass
    try:
        _vault_audit(admin, "site:adossement_" + ("fait" if decision == "fait" else "refuse"), dn + " → " + compte)
    except Exception:
        pass
    try:
        for o in ([compte] if compte else []):
            log_user_activity(o, admin, "adossement_fait" if decision == "fait" else "adossement_refuse",
                              dn + ((" · " + reponse) if reponse else ""))
            tmpl = _SITE_ACTION_MAIL.get("adossement_fait" if decision == "fait" else "adossement_refuse")
            if tmpl and mail_configured():
                base = _app_public_url()
                notify_user_email(o, "Cassandra · %s" % dn, tmpl[0], tmpl[1] % dn, ("Voir mon espace" if base else ""), base, genre="site")
    except Exception:
        pass
    return {"ok": True, "id": r[0], "domain": dn, "compte": compte, "statut": decision}


def site_accord_donner(user: str, domain: str, geste: str = "restaurer", heures: int = 24) -> dict:
    """Le propriétaire autorise l'administrateur à faire un geste lourd sur son site, pour un temps."""
    dn = _norm_domain(domain)
    if not _site_est_a_moi(user, dn):
        return {"ok": False, "reason": "ce site n'est pas à toi"}
    geste = (geste or "restaurer").strip().lower()[:32]
    heures = max(1, min(int(heures or 24), 168))
    _site_v2_migrate()
    fin = (_utcnow() + timedelta(hours=heures)).strftime("%Y-%m-%d %H:%M:%S")
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        conn.execute("INSERT INTO site_accords (domain, compte, geste, jusqu_a, par) VALUES (?,?,?,?,?)", (dn, user, geste, fin, user))
        conn.commit(); conn.close()
    except Exception as e:
        return {"ok": False, "reason": str(e)}
    try:
        _vault_audit(user, "site:accord", "%s %s jusqu'à %s" % (dn, geste, fin))
        notif("Accord donné : %s sur %s" % (geste, dn), "%s autorise un administrateur à %s son site %s jusqu'à %s." % (user, geste, dn, fin),
              source="site", niveau="info", nature="evenement", sujet=dn, cle="site:accord:%s:%s" % (geste, dn), dest=["admins"])
    except Exception:
        pass
    return {"ok": True, "domain": dn, "geste": geste, "jusqu_a": fin}


def site_accord_valide(domain: str, geste: str = "restaurer"):
    _site_v2_migrate()
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        r = conn.execute("SELECT par, jusqu_a FROM site_accords WHERE domain=? AND geste=? AND jusqu_a > ? "
                         "ORDER BY id DESC LIMIT 1", (_norm_domain(domain), geste, _utcnow().strftime("%Y-%m-%d %H:%M:%S"))).fetchone()
        conn.close()
    except Exception:
        return None
    return {"par": r[0], "jusqu_a": r[1]} if r else None


def fp_backup_copies(plan_id, limite: int = 12) -> dict:
    """Les copies d'un plan, telles que le panneau les liste (`GET /api/v2/backup/plans/{id}/copies`)."""
    r = fp_api_call("GET", "/api/v2/backup/plans/%s/copies" % plan_id)
    if not r.get("ok"):
        return {"ok": False, "reason": r.get("reason") or ("HTTP %s" % r.get("status")), "copies": []}
    d = r.get("data")
    items = d.get("data") if isinstance(d, dict) and isinstance(d.get("data"), list) else (d if isinstance(d, list) else [])
    out = []
    for c in items:
        if not isinstance(c, dict):
            continue
        out.append({"id": c.get("id"), "debut": c.get("startedAt") or c.get("start_at") or "",
                    "fin": c.get("endedAt") or c.get("end_at") or "", "compte": c.get("copiedUser") or c.get("copied_user") or "",
                    "bases": [str(x.get("name") or x) for x in (c.get("dbs") or []) if x], "partielle": bool(c.get("partial")),
                    "octets": c.get("totalUploaded") or c.get("total_uploaded") or 0})
    out.sort(key=lambda x: str(x.get("debut") or ""), reverse=True)
    return {"ok": True, "copies": out[:max(1, min(int(limite or 12), 60))]}


def fp_backup_restaurer(copie_id, dst_user: str, force_clear: bool = False, acteur: str = "") -> dict:
    """`PUT /api/v2/backup/copy/{id}/restore` avec les champs du formulaire du panneau (dstUser,
    forceClearWebsites, dstPath). Un refus 400 rend {"errors": {champ: raison}} : il est rendu tel quel."""
    corps = {"dstUser": str(dst_user or ""), "forceClearWebsites": bool(force_clear), "dstPath": ""}
    r = fp_api_call("PUT", "/api/v2/backup/copy/%s/restore" % copie_id, corps)
    try:
        log_action("", "fp:restore:%s" % copie_id, ("ok" if r.get("ok") else "refus %s" % r.get("status")) + " · " + str(r.get("data") or r.get("reason") or "")[:300], 0, True, True)
    except Exception:
        pass
    if not r.get("ok"):
        d = r.get("data")
        return {"ok": False, "status": r.get("status"), "reason": r.get("reason") or ("HTTP %s" % r.get("status")),
                "errors": (d.get("errors") if isinstance(d, dict) else None)}
    return {"ok": True, "status": r.get("status"), "data": r.get("data")}


def site_rapport(domain: str, mois: str = "") -> dict:
    """Le mois d'un site : disponibilité, coupures, réponse, certificat, sauvegardes, analyses, gestes."""
    dn = _norm_domain(domain)
    if not mois:
        mois = _utcnow().strftime("%Y-%m")
    mois = str(mois)[:7]
    debut = mois + "-01 00:00:00"
    try:
        y, m = int(mois[:4]), int(mois[5:7])
        fin = ("%04d-%02d-01 00:00:00" % ((y + 1, 1) if m == 12 else (y, m + 1)))
    except Exception:
        return {"ok": False, "reason": "mois invalide (AAAA-MM)"}
    r = {"ok": True, "domain": dn, "mois": mois, "sonde": {}, "coupures": [], "gestes": {}, "sauvegardes": [], "analyses": []}
    try:
        _site_migrate()
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        row = conn.execute("SELECT COUNT(*), SUM(CASE WHEN up=1 THEN 1 ELSE 0 END), AVG(response_ms), MAX(response_ms), MIN(ssl_days) "
                           "FROM site_status WHERE domain=? AND ts>=? AND ts<?", (dn, debut, fin)).fetchone()
        n = row[0] or 0
        r["sonde"] = {"mesures": n, "disponibilite": (round(100.0 * (row[1] or 0) / n, 2) if n else None),
                      "reponse_moy_ms": (int(row[2]) if row[2] else None), "reponse_max_ms": row[3], "ssl_min": row[4]}
        for e in conn.execute("SELECT ts, kind, detail, duration_min FROM site_events WHERE domain=? AND ts>=? AND ts<? ORDER BY ts", (dn, debut, fin)):
            r["coupures"].append({"ts": e[0], "kind": e[1], "detail": e[2], "duree_min": e[3]})
        for a in conn.execute("SELECT action, COUNT(*) FROM vault_audit WHERE action LIKE 'site:%' AND secret_name LIKE ? AND ts>=? AND ts<? GROUP BY action", (dn + "%", debut, fin)):
            r["gestes"][str(a[0])[5:]] = a[1]
        conn.close()
    except Exception as e:
        r["sonde_erreur"] = str(e)
    r["pannes"] = sum(1 for c in r["coupures"] if c["kind"] == "panne")
    r["retours"] = sum(1 for c in r["coupures"] if c["kind"] == "retour")
    # Les minutes d'indisponibilité sont portées par le RETOUR : une coupure commencée le mois d'avant
    # se solde ici. On le dit tel quel plutôt que d'annoncer « 0 coupure » et des milliers de minutes.
    r["indisponible_min"] = sum(int(c["duree_min"] or 0) for c in r["coupures"] if c["kind"] == "retour")
    vue = None
    try:
        vue = next((x for x in sites_vue("__rapport__admin__", force=False).get("sites", []) if x.get("domain") == dn), None)
    except Exception:
        vue = None
    if vue is None:
        try:
            fpd = {_norm_domain(d.get("domain") or ""): d for d in (get_fp_domains() or []) if isinstance(d, dict)}
            vue = {"fp_compte": str((fpd.get(dn) or {}).get("user") or "").lower(), "source": "panneau" if dn in fpd else "declare"}
        except Exception:
            vue = {"fp_compte": "", "source": "declare"}
    cp = str(vue.get("fp_compte") or "").lower()
    try:
        for c in (_fp_backups_riches() or []):
            if str(c.get("compte") or c.get("user") or "").lower() == cp and cp and str(c.get("created_at") or "")[:7] == mois:
                r["sauvegardes"].append({"at": c.get("created_at"), "status": c.get("status"), "size_mb": c.get("size_mb")})
    except Exception:
        pass
    try:
        for sc in (get_fp_scans() or []):
            if _norm_domain(sc.get("domain") or "") == dn and str(sc.get("created_at") or "")[:7] == mois:
                r["analyses"].append({"at": sc.get("created_at"), "status": sc.get("status")})
    except Exception:
        pass
    r["source"] = vue.get("source")
    r["ssl_days"] = vue.get("ssl_days") if isinstance(vue, dict) else None
    r["php"] = vue.get("php") if isinstance(vue, dict) else ""
    r["cms"] = vue.get("cms") if isinstance(vue, dict) else None
    so = r["sonde"]
    nsv = sum(1 for x in r["sauvegardes"] if x["status"] == "success")
    coup = ("%d coupure%s commencée%s ce mois" % (r["pannes"], "s" if r["pannes"] > 1 else "", "s" if r["pannes"] > 1 else ""))
    if r["retours"]:
        coup += ", %d retour%s (%d min d'indisponibilité soldée%s)" % (r["retours"], "s" if r["retours"] > 1 else "", r["indisponible_min"], "s" if r["indisponible_min"] > 1 else "")
    r["phrase"] = ("%s en %s : %s de disponibilité sur %d mesures, %s, %d sauvegarde%s réussie%s, %d analyse%s."
                   % (dn, mois, ("%.2f %%" % so["disponibilite"]) if so.get("disponibilite") is not None else "pas de sonde",
                      so.get("mesures") or 0, coup, nsv, "s" if nsv > 1 else "", "s" if nsv > 1 else "",
                      len(r["analyses"]), "s" if len(r["analyses"]) > 1 else ""))
    return r


def site_rapport_html(r: dict) -> str:
    so = r.get("sonde") or {}
    lignes = [("Disponibilité", ("%.2f %%" % so["disponibilite"]) if so.get("disponibilite") is not None else "pas de sonde"),
              ("Mesures", str(so.get("mesures") or 0)),
              ("Réponse moyenne", ("%s ms" % so["reponse_moy_ms"]) if so.get("reponse_moy_ms") else "—"),
              ("Coupures", "%d (%d min)" % (r.get("pannes") or 0, r.get("indisponible_min") or 0)),
              ("Certificat", ("%s jours" % r["ssl_days"]) if isinstance(r.get("ssl_days"), (int, float)) else "—"),
              ("Sauvegardes réussies", str(sum(1 for x in (r.get("sauvegardes") or []) if x.get("status") == "success"))),
              ("Analyses antivirus", ", ".join("%s (%s)" % (str(a.get("at") or "")[:10], a.get("status")) for a in (r.get("analyses") or [])) or "aucune"),
              ("Gestes", ", ".join("%s ×%d" % (k, v) for k, v in (r.get("gestes") or {}).items()) or "aucun")]
    return ("<p>%s</p><table style='border-collapse:collapse'>%s</table>"
            % (html.escape(r.get("phrase") or ""),
               "".join("<tr><td style='padding:4px 10px 4px 0;color:#666'>%s</td><td style='padding:4px 0'><b>%s</b></td></tr>"
                       % (html.escape(k), html.escape(v)) for k, v in lignes)))


def site_rapport_envoyer(domain: str, mois: str, par: str, destinataires=None) -> dict:
    """Expédie le rapport d'un mois aux propriétaires du site (ou à `par` s'il est le propriétaire)."""
    dn = _norm_domain(domain)
    r = site_rapport(dn, mois)
    if not r.get("ok"):
        return r
    dests = list(destinataires or []) or _site_owners(dn) or ([par] if par and _site_est_a_moi(par, dn) else [])
    if not dests:
        return {"ok": False, "reason": "aucun propriétaire à qui envoyer", "rapport": r}
    if not mail_configured():
        return {"ok": False, "reason": "courrier non configuré", "rapport": r}
    corps = site_rapport_html(r)
    base = _app_public_url()
    envoyes = []
    for o in dests:
        try:
            if notify_user_email(o, "Cassandra · rapport %s · %s" % (r["mois"], dn), "Rapport mensuel de %s" % dn, corps,
                                 ("Voir mon espace" if base else ""), base, genre="site"):
                envoyes.append(o)
        except Exception:
            pass
    _site_v2_migrate()
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        for o in envoyes:
            conn.execute("INSERT INTO site_rapports_envoyes (domain, mois, compte) VALUES (?,?,?)", (dn, r["mois"], o))
        conn.commit(); conn.close()
    except Exception:
        pass
    if envoyes:
        try:
            _vault_audit(par, "site:rapport", "%s %s → %s" % (dn, r["mois"], ", ".join(envoyes)))
            for o in envoyes:
                log_user_activity(o, par, "rapport", dn + " " + r["mois"])
        except Exception:
            pass
    return {"ok": bool(envoyes), "envoyes": envoyes, "rapport": r, "reason": "" if envoyes else "aucun envoi n'a abouti"}


_SITES_RAPPORT_DERNIER = [0.0]


def sites_rapport_mensuel_passer(force: bool = False) -> dict:
    """Le 1er du mois (et les deux jours suivants, si le service dormait), le rapport du mois écoulé part
    aux comptes ordinaires qui ont des sites — une fois par site et par mois. Réglage `sites_rapport_mensuel`."""
    now = time.time()
    if not force and now - _SITES_RAPPORT_DERNIER[0] < 3600:
        return {"ok": True, "saute": "déjà vérifié cette heure"}
    _SITES_RAPPORT_DERNIER[0] = now
    if not _mem_cfg("sites_rapport_mensuel", True):
        return {"ok": True, "disabled": True}
    d = _utcnow()
    if not force and d.day > 3:
        return {"ok": True, "saute": "pas le début du mois"}
    prem = d.replace(day=1)
    mois = (prem - timedelta(days=1)).strftime("%Y-%m")
    _site_v2_migrate()
    deja = set()
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        deja = {(r[0], r[1]) for r in conn.execute("SELECT domain, compte FROM site_rapports_envoyes WHERE mois=?", (mois,))}
        conn.close()
    except Exception:
        pass
    envoyes, erreurs = 0, 0
    try:
        for email, v in load_users().items():
            rec = _user_record(v)
            if rec.get("role") == "admin":
                continue
            for dn in (user_sites(email) or []):
                dn = _norm_domain(dn)
                if (dn, email) in deja:
                    continue
                r = site_rapport_envoyer(dn, mois, "cassandra", destinataires=[email])
                if r.get("ok"):
                    envoyes += 1
                else:
                    erreurs += 1
    except Exception as e:
        logging.info("[SITES] rapports mensuels : %s", e)
    if envoyes or erreurs:
        logging.info("[SITES] rapports mensuels %s : %d envoyé(s), %d échec(s)", mois, envoyes, erreurs)
    return {"ok": True, "mois": mois, "envoyes": envoyes, "erreurs": erreurs}


def sites_transferer(admin: str, domain: str, vers: str) -> dict:
    """Un site déclaré ou attribué passe d'un compte à un autre. Les deux sont prévenus, tout est journalisé."""
    dn = _norm_domain(domain)
    vers = (vers or "").strip().lower()
    users = load_users()
    if vers not in users:
        return {"ok": False, "reason": "compte destinataire inconnu"}
    depuis = [e for e, v in users.items() if dn in {_norm_domain(x) for x in (_user_record(v).get("sites") or [])}]
    if not depuis:
        return {"ok": False, "reason": "ce site n'est déclaré ni attribué à aucun compte : il s'attribue, il ne se transfère pas"}
    if depuis == [vers]:
        return {"ok": False, "reason": "ce site est déjà à ce compte"}
    for e in depuis:
        if e == vers:
            continue
        rec = _user_record(users[e])
        if not _sites_ecrire_declares(e, [x for x in rec.get("sites") if _norm_domain(x) != dn]):
            return {"ok": False, "reason": "écriture des comptes impossible"}
        try:
            log_user_activity(e, admin, "transfere", dn + " → " + vers)
            tmpl = _SITE_ACTION_MAIL.get("transfere")
            if tmpl and mail_configured():
                base = _app_public_url()
                notify_user_email(e, "Cassandra · %s" % dn, tmpl[0], tmpl[1] % dn, ("Voir mon espace" if base else ""), base, genre="site")
        except Exception:
            pass
    if vers not in depuis:
        r = sites_declarer(vers, dn, par=admin, panneau_ok=True)
        if not r.get("ok"):
            return r
        try:
            tmpl = _SITE_ACTION_MAIL.get("attribue")
            if tmpl and mail_configured():
                base = _app_public_url()
                notify_user_email(vers, "Cassandra · %s" % dn, tmpl[0], tmpl[1] % dn, ("Voir mon espace" if base else ""), base, genre="site")
        except Exception:
            pass
    _SITES_VUE_CACHE["data"] = None
    try:
        _vault_audit(admin, "site:transfere", "%s %s → %s" % (dn, ", ".join(x for x in depuis if x != vers), vers))
    except Exception:
        pass
    return {"ok": True, "domain": dn, "depuis": [x for x in depuis if x != vers], "vers": vers}


# ── Auto-renouvellement SSL des domaines des users (proactif, avant expiration) ──
_SSL_AUTO_RENEW_DAYS = 21
_SSL_AUTO_LAST_RUN = [0.0]
_ssl_auto_attempts = {}


def _auto_renew_user_ssl() -> int:
    """Renouvelle automatiquement le SSL des domaines POSSÉDÉS par des users, avant expiration.
    Action vettée et scopée (domaine assigné) → pas de shell arbitraire. Notifie le propriétaire."""
    owned = set()
    try:
        for email, v in load_users().items():
            rec = _user_record(v)
            if rec["role"] != "admin":
                owned.update(_norm_domain(d) for d in (user_sites(email) or []) if d)
    except Exception:
        pass
    if not owned:
        return 0
    certs, err = _mogwai_json(["certificates", "list"])
    if not certs:
        return 0
    now = time.time(); renewed = 0
    for c in certs:
        cn = _norm_domain(c.get("common_name", ""))
        if cn not in owned:
            continue
        exp = c.get("expires")
        if not exp:
            continue
        days = (exp - now) / 86400.0
        if days < 0 or days > _SSL_AUTO_RENEW_DAYS:
            continue                       # pas urgent, ou déjà expiré (laisser au manuel)
        if now - _ssl_auto_attempts.get(cn, 0) < 12 * 3600:
            continue                       # anti-boucle : pas deux fois en 12 h
        _ssl_auto_attempts[cn] = now
        try:
            ok, msg, _c = _site_ssl_renew_impl({"domain": cn})   # réémet + notifie le propriétaire
            logging.info("[SSL-AUTO] %s expire dans %.0f j → réémission auto (%s)"
                         % (cn, days, "ok" if ok else str(msg)[:60]))
            if ok:
                renewed += 1
        except Exception as e:
            logging.warning("[SSL-AUTO] %s: %s" % (cn, e))
    return renewed


# ── MODIFIER ET SUPPRIMER : les verbes qui manquaient ────────────────────────
# Itare pouvait créer et lire ; elle ne pouvait ni corriger ni ranger. Un
# assistant qui ajoute sans jamais retirer laisse derrière lui un espace qui
# ne fait que grossir.


# ── DOCUMENTS (GED) ET PIÈCES JOINTES : lecture, recherche, contrôle ─────────
# Itare lisait le courrier et ses notes, mais pas les documents ni le contenu
# des pièces jointes. Ces outils lui ouvrent la GED (lecture + contrôle) et
# l'index des pièces jointes (recherche par mot-clé dans le texte extrait).

def _ged_sources_impl(args: dict) -> tuple:
    r = ged_sources()
    if not r.get("ok"):
        return (False, "🗄 " + str(r.get("reason")), "#e0564a")
    lignes = []
    for g in (r.get("groupes") or []):
        lignes.append("▸ %s" % g.get("g", ""))
        for x in (g.get("l") or []):
            lignes.append("  • %s %s (%d)  → source=%r%s"
                          % (x.get("ic", ""), x.get("nm", ""), x.get("n") or 0,
                             x.get("id", ""), "  [lecture seule]" if x.get("ro") else ""))
    defaut = r.get("defaut") or ""
    txt = ("🗄 Espaces de documents du compte — passe l'`id` TEL QUEL dans `source` de ged_list :\n"
           + "\n".join(lignes)
           + ("\n\n(Source ouverte par défaut : %r.)" % defaut if defaut else ""))
    return (txt, txt, "#8be9fd")


def _ged_list_impl(args: dict) -> tuple:
    source = _html.unescape(str(args.get("source") or "").strip())
    chemin = _html.unescape(str(args.get("chemin") or "").strip())
    query = _html.unescape(str(args.get("query") or "").strip())
    if not source:
        s = ged_sources()
        source = (s.get("defaut") or "") if s.get("ok") else ""
        if not source:
            return (False, "🗄 aucun espace de documents disponible", "#e0564a")
    r = ged_lister(source, chemin, query)
    if not r.get("ok"):
        return (False, "🗄 " + str(r.get("reason")), "#e0564a")
    items = r.get("items") or []
    if not items:
        return (True, "🗄 %s : vide." % (r.get("nom") or source), "#8a8a9a")
    lignes = []
    for it in items[:60]:
        if it.get("dossier"):
            lignes.append("• 📁 %s/  (%d)" % (it.get("nom", ""), it.get("n") or 0))
        else:
            l = "• %s  %s  %s" % (it.get("nom", ""), it.get("taille_h") or "", it.get("modifie") or "")
            if it.get("id"):
                l += "  [id=%s]" % it.get("id")
            if it.get("a_extraire"):
                l += "  (à extraire)"
            lignes.append(l)
    txt = "🗄 %s (%d élément(s)) — pour LIRE un fichier, passe son `id` (ou `source`+`chemin`) à ged_texte :\n%s" % (
        r.get("nom") or source, len(items), "\n".join(lignes))
    return (txt, txt, "#8be9fd")


def _ged_fiche_impl(args: dict) -> tuple:
    fid = args.get("fid") or args.get("id")
    source = _html.unescape(str(args.get("source") or "").strip())
    chemin = _html.unescape(str(args.get("chemin") or "").strip())
    r = ged_fiche(fid=fid, source=source, chemin=chemin)
    if not r.get("ok"):
        return (False, "🗄 " + str(r.get("reason")), "#e0564a")
    f = r.get("fichier") or {}
    lignes = ["📄 %s" % (f.get("nom") or chemin or fid),
              "• id=%s" % (f.get("id") or ""),
              "• %s · %s" % (f.get("taille_h") or "", f.get("kind") or ""),
              "• modifié : %s" % (f.get("modifie") or "")]
    if f.get("de"):
        lignes.append("• de : %s" % f.get("de"))
    if f.get("sujet"):
        lignes.append("• sujet : %s" % f.get("sujet"))
    liens = r.get("liens") or []
    if liens:
        lignes.append("• liens : " + ", ".join("%s=%s" % (l.get("kind"), l.get("nom") or l.get("ref")) for l in liens[:12]))
    if (r.get("jumeaux") or 0) > 1:
        lignes.append("• %d exemplaire(s) (doublons)" % r.get("jumeaux"))
    return ("\n".join(lignes), "\n".join(lignes), "#8be9fd")


def _ged_texte_impl(args: dict) -> tuple:
    fid = args.get("fid") or args.get("id")
