def _ged_corbeille_restaurer_impl(args: dict) -> tuple:
    chemins = args.get("chemins") or args.get("chemin") or []
    if isinstance(chemins, str):
        chemins = [chemins]
    chemins = [_html.unescape(str(c)) for c in chemins]
    if not chemins:
        return (False, "chemin(s) à restaurer requis (via ged_corbeille_lister)", "#e0564a")
    r = ged_corbeille_restaurer(chemins, confirm=True)
    if not r.get("ok"):
        return (False, "🗄 " + str(r.get("reason")), "#e0564a")
    trace_poser("document_restaure", "Document(s) restauré(s) depuis la corbeille")
    msg = "♻️ %d document(s) restauré(s)." % (r.get("faits") or 0)
    if r.get("erreurs"):
        msg += " Échecs : %s" % ", ".join(r.get("erreurs") or [])
    return (True, msg, "#7bd88f")


