def _piece_lire_impl(args: dict) -> tuple:
    folder = _html.unescape(str(args.get("folder") or "INBOX") or "INBOX")
    uid = str(args.get("uid") or "").strip()
    idx = args.get("idx") if args.get("idx") is not None else args.get("index")
    if not uid:
        return (False, "uid du mail requis", "#e0564a")
    try:
        idx = int(idx or 0)
    except Exception:
        idx = 0
    d = ged_piece_octets(folder, uid, idx)
    if not d.get("ok"):
        return (False, "📎 " + str(d.get("reason")), "#e0564a")
    octets = d.get("data") or b""
    if len(octets) > _MEDIA_LIRE_MAX:
        return (False, "📎 pièce trop volumineuse pour être lue (%s)." % _ged_octets(len(octets)), "#e0564a")
    ex = _extract_text_from_upload(octets, d.get("mime") or "", d.get("nom") or "piece")
    texte = (ex or {}).get("text") or ""
    if not texte.strip():
        return (False, "📎 %s : %s" % (d.get("nom") or "pièce", (ex or {}).get("error") or "aucun texte lisible"), "#e0564a")
    txt = "📎 %s (via %s) :\n\n%s" % (d.get("nom") or "pièce", (ex or {}).get("method") or "?", texte[:_MEDIA_TEXTE_MAX])
    if (ex or {}).get("truncated"):
        txt += "\n… (texte tronqué)"
    return (txt, txt, "#8be9fd")

