def _itare_task_update_impl(args: dict) -> tuple:
    """`itare_task_save` préserve déjà ce qu'on ne lui donne pas : on ne passe
    que ce qui change."""
    tid = args.get("id")
    if not tid:
        return (False, "identifiant de la tâche requis", "#e0564a")
    # LA TÂCHE D'AVANT. `itare_task_save` préserve ce qu'on ne lui donne pas,
    # donc l'état d'avant doit être LU, pas déduit des arguments.
    _av = None
    try:
        _cx = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        _cx.row_factory = sqlite3.Row
        _rw = _cx.execute("SELECT * FROM itare_tasks WHERE id=?",
                          (int(tid),)).fetchone()
        _cx.close()
        if _rw:
            _av = {"id": int(tid), "text": _rw["text"],
                   "status": _rw["status"], "due_at": _rw["due_at"]}
    except Exception:
        _av = None
    if _av:
        trace_poser("tache_modifiee", "Tâche « %s » modifiée" % _av["text"][:60],
                    _av)
    _st = str(args.get("status") or "").strip().lower().replace("à faire", "todo").replace("a faire", "todo")
    _st = {"abandonnée": "abandonnee", "abandonner": "abandonnee", "faite": "fait"}.get(_st, _st)
    r2 = itare_task_save(text=_html.unescape((args.get("text") or "").strip()), tid=int(tid),
                         status=(_st or None),
                         due=(args.get("due") or None),
                         avancement=args.get("avancement"), raison=args.get("raison"),
                         responsable=args.get("responsable"))
    if r2.get("ok"):
        return (True, "✅ Tâche mise à jour.", "#7bd88f")
    return (False, str(r2.get("reason") or "refusé"), "#e0564a")


