def _contact_update_impl(args: dict) -> tuple:
    """Corriger une fiche SANS effacer le reste.

    `contact_save` réécrit la fiche ENTIÈRE, adresses comprises : lui passer le
    seul champ modifié effacerait tout le reste. On relit donc la fiche et on
    fusionne — c'est la seule forme sûre, et c'est une erreur déjà commise ici
    une fois.
    """
    cid = args.get("id")
    if not cid:
        return (False, "identifiant de la fiche requis", "#e0564a")
    _f = contact_get(cid) or {}
    _c = _f.get("contact") if isinstance(_f.get("contact"), dict) else _f
    if not _c or not _c.get("id"):
        return (False, "fiche introuvable", "#e0564a")

    def _pris(cle, defaut=""):
        v2 = args.get(cle)
        return v2 if v2 not in (None, "") else (_c.get(cle) or defaut)

    _mails = args.get("emails")
    if _mails in (None, ""):
        _mails = _c.get("emails") or []
    if isinstance(_mails, str):
        _mails = [x.strip() for x in _mails.split(",") if x.strip()]
    # LA FICHE D'AVANT, ENTIÈRE. C'est la seule qui permette de revenir :
    # `contact_save` réécrit tout, donc l'annulation doit tout redonner.
    trace_poser("contact_modifie",
                "Fiche « %s » modifiée" % str(_c.get("display_name") or "")[:60],
                {"id": int(_c["id"]),
                 "display_name": _c.get("display_name") or "",
                 "emails": _c.get("emails") or [],
                 "phone": _c.get("phone") or "", "mobile": _c.get("mobile") or "",
                 "company": _c.get("company") or "",
                 "job_title": _c.get("job_title") or "",
                 "address": _c.get("address") or "",
                 "website": _c.get("website") or "",
                 "notes": _c.get("notes") or "", "tags": _c.get("tags") or ""})
    r2 = contact_save(display_name=_pris("display_name"), emails=_mails,
                      phone=_pris("phone"), mobile=_pris("mobile"),
                      company=_pris("company"), job_title=_pris("job_title"),
                      address=_pris("address"), website=_pris("website"),
                      notes=_pris("notes"), tags=_pris("tags"),
                      cid=int(_c["id"]))
    if r2.get("ok"):
        return (True, "👤 Fiche « %s » mise à jour." % _pris("display_name"),
                "#7bd88f")
    return (False, str(r2.get("reason") or "refusé"), "#e0564a")


def _contact_delete_impl(args: dict) -> tuple:
    cid = args.get("id")
    if not cid:
        return (False, "identifiant de la fiche requis", "#e0564a")
    r2 = contact_delete(int(cid))
    if r2.get("ok"):
        trace_poser("contact_supprime", "Fiche du répertoire supprimée")
        return (True, "🗑 Fiche supprimée — définitif.", "#7bd88f")
    return (False, str(r2.get("reason") or "refusé"), "#e0564a")


def _itare_mail_reply_impl(args: dict) -> tuple:
    """Répondre à un message de la boîte. L'adresse vient de l'ENVELOPPE.

    Aucun argument ne porte de destinataire : on relit le message désigné et
    l'on répond à son expéditeur. C'est ce qui rend cet outil utilisable après
    avoir lu un courriel, là où `itare_mail_send` doit refuser — un texte lu
    ne peut pas détourner une adresse qu'il ne fournit pas.
    """
    _o = origine_courante()
    # L'ORIGINE RESTE EXIGÉE. Une règle horaire ne répond pas à la place de
    # quelqu'un : les mandats ont leur porte, écrite à l'avance.
    if _o.get("origine") != "chat":
        return (False, "une réponse ne part que sur demande d'une personne, "
                       "dans la conversation (origine : %s)"
                       % origine_lisible(_o), "#e0564a")
    _uid = str(args.get("uid") or args.get("id") or "").strip()
    _corps = (args.get("body") or "").strip()
    if not _uid:
        return (False, "identifiant du message auquel répondre requis", "#e0564a")
    if not _corps:
        return (False, "le corps de la réponse est vide", "#e0564a")
    # LA PARADE DE L'UID. Si un contenu extérieur est entré dans ce tour, le
    # message visé doit avoir été nommé PAR LA PERSONNE : un message piégé
    # peut demander de répondre à un autre message de la boîte, et l'on
    # écrirait en votre nom sur l'ordre d'un texte.
    #
    # Tour propre, on n'exige rien : vous dites « réponds au mail de Camille »,
    # le modèle cherche l'UID lui-même, et aucun texte étranger n'a parlé.
    if _o.get("teinte") and _uid not in origine_demande_lire():
        return (False, "ce tour a lu du contenu extérieur (%s), et le message "
                       "n° %s n'est pas celui que tu m'as désigné. Redis-moi "
                       "lequel — je ne réponds pas à un message qu'un autre "
                       "texte a choisi."
                       % (", ".join(_o.get("teintes") or [])[:60], _uid),
                "#e0564a")
    _m = itare_mail_read(_uid)
    if not _m.get("ok"):
        return (False, "message introuvable : %s" % str(_m.get("reason") or ""),
                "#e0564a")
    # L'ADRESSE VIENT D'ICI, ET DE NULLE PART AILLEURS. `Reply-To` d'abord —
    # c'est l'endroit prévu pour dire « écrivez plutôt là » —, l'expéditeur
    # ensuite. Rien de ce que le message CONTIENT n'entre dans ce choix.
    _dest = (_m.get("reply_to") or _m.get("from") or "").strip()
    if not _dest:
        return (False, "ce message n'a pas d'expéditeur exploitable", "#e0564a")
    _obj = (_m.get("subject") or "").strip()
    if not _obj.lower().startswith("re:"):
        _obj = ("Re: " + _obj) if _obj else "Re:"
    # LE FIL EST RECOUSU : sans `In-Reply-To` ni `References`, la réponse
    # ouvre une conversation neuve chez le destinataire, à côté de la sienne.
    _refs = " ".join(x for x in ((_m.get("references") or ""),
                                 (_m.get("message_id") or "")) if x).strip()
    _r = itare_mail_send(_dest, _obj, _corps,
                         in_reply_to=(_m.get("message_id") or ""),
                         references=_refs)
    if _r.get("ok"):
        try:
            log_action("", "tool:itare_mail_reply", "-> %s / %s"
                       % (_dest[:80], _obj[:60]), 0, True, False)
        except Exception:
            pass
        trace_poser("courriel_envoye", "Réponse à %s — « %s »" % (_dest, _obj))
        return (True, "↩ Réponse envoyée à %s — « %s »." % (_dest, _obj),
                "#7bd88f")
    return (False, str(_r.get("reason") or "envoi refusé"), "#e0564a")


def _envoi_verrous():
    """Les DEUX conditions de tout envoi, ou `None` si la voie est libre.

    Elles étaient écrites dans `_itare_mail_send_impl`. Depuis qu'une archive
    peut partir elle aussi, il y a deux portes — et deux copies de ces
    conditions auraient voulu dire deux règles à tenir d'accord. C'est toujours
    la seconde qu'on oublie de corriger.
    """
    _o = origine_courante()
    # 1 ─ UNE PERSONNE A DEMANDÉ, DANS CE TOUR. Une règle horaire ou une
    #     origine non déclarée n'envoie rien par ici : les mandats ont leur
    #     propre porte, avec un destinataire écrit à l'avance.
    if _o.get("origine") != "chat":
        return (False, "un envoi ne part que sur demande d'une personne, dans "
                       "la conversation (origine : %s)" % origine_lisible(_o),
                "#e0564a")
    # 2 ─ LE TOUR N'EST PAS TEINTÉ. Dès qu'un contenu extérieur est entré —
    #     un courriel lu, une page web —, l'envoi est refusé. C'est LE verrou
    #     contre l'injection : « lis ce message et réponds à l'adresse qu'il
    #     contient » est exactement ce qu'un message piégé demanderait.
    if _o.get("teinte"):
        return (False, "ce tour a lu du contenu extérieur (%s) : un envoi n'en "
                       "part jamais. Redemande-le dans un message neuf, en me "
                       "donnant l'adresse toi-même."
                       % ", ".join(_o.get("teintes") or [])[:80], "#e0564a")
    return None


def _itare_mail_send_impl(args: dict) -> tuple:
    """Envoyer un courriel. Deux verrous, et ce sont ceux des mandats.

    Un envoi part chez quelqu'un d'autre et ne se rattrape pas : les mêmes
    conditions que celles qui gouvernent les mandats s'appliquent ici, sans
    quoi cette porte serait le point faible de tout l'édifice.
    """
    _refus = _envoi_verrous()
    if _refus:
        return _refus
    _to = (args.get("to") or args.get("to_addr") or "").strip()
    _obj = (args.get("subject") or "").strip()
    _corps = (args.get("body") or "").strip()
    if not _to:
        return (False, "adresse du destinataire requise", "#e0564a")
    if not _corps:
        return (False, "le corps du message est vide", "#e0564a")
    _r = itare_mail_send(_to, _obj, _corps, cc_addr=(args.get("cc") or ""))
    if _r.get("ok"):
        try:
            log_action("", "tool:itare_mail_send", "-> %s / %s"
                       % (_to[:80], _obj[:60]), 0, True, False)
        except Exception:
            pass
        trace_poser("courriel_envoye", "Courriel à %s — « %s »"
                    % (_to, _obj or "(sans objet)"))
        return (True, "✉ Envoyé à %s — « %s »." % (_to, _obj or "(sans objet)"),
                "#7bd88f")
    return (False, str(_r.get("reason") or "envoi refusé"), "#e0564a")


_CONSEIL_MAX = 2000
# CE QU'UNE REPONSE DE CONSEIL NE DOIT PAS PORTER. Itare a decrit les deux
# chemins : un EMPLACEMENT de secret (« regarde /root/.env ») et une COMMANDE
# (« lance systemctl … »). Ni l'un ni l'autre n'est une valeur de secret ni une
# action executee — et les deux donnent pourtant le resultat que le canal
# refuse, parce qu'Itare a des outils.
_CONSEIL_LIEUX = re.compile(
    r"(?:/root/[^\s`\"']*|/etc/[^\s`\"']*|~/\.[^\s`\"']*|\b[A-Z][A-Z0-9_]{3,}="
    r"|\b(?:\.env|id_[a-z0-9]+|authorized_keys|config\.json|auth\.json)\b)")
_CONSEIL_CMDS = re.compile(
    r"(?m)^\s*[`$]*\s*(?:sudo\s+)?(?:systemctl|journalctl|bash|sh|curl|wget|"
    r"cat|sed|awk|grep|python3?|pip|apt|docker|ssh|scp|rm|cp|mv|chmod|chown|"
    r"nginx|sqlite3)\b[^\n]*"
    r"|`[^`\n]{0,200}`")


def cassandra_conseil(question: str, contexte: str = "") -> dict:
    """ITARE DEMANDE CONSEIL À CASSANDRA. Un avis, jamais un geste.

    L'usager a tranché : conseil et conversation informelle, pas d'action bash
    par procuration, pas de divulgation sensible.

    CE QUI REND LA LIMITE RÉELLE : ce chemin n'attache AUCUN outil à l'appel.
    Cassandra ne peut donc pas exécuter depuis ici — non pas parce qu'on le lui
    demande, mais parce qu'elle n'en a pas le moyen. Une consigne se négocie,
    une absence d'outil non.

    Et la question part DEHORS : le modèle de Cassandra est chez un
    fournisseur. Le périmètre de sortie s'y applique comme partout ailleurs.
    """
    # QUI APPELLE ? Itare, et personne d'autre. Elle l'a demande elle-meme :
    # « rien ne verifie que TU es bien l'appelant ». Un outil ouvert a une
    # seule voix doit verifier la voix, pas seulement figurer dans sa liste —
    # sinon une consigne glissee dans une conversation l'atteint aussi.
    try:
        _a = get_current_agent()
    except Exception:
        _a = ""
    if _a and _a != "itare":
        return {"ok": False, "statut": "refus",
                "reason": "cette porte est celle d'Itare vers Cassandra ; "
                          "« %s » n'a rien a y faire" % _a}
    q = str(question or "").strip()
    if len(q) < 4:
        return {"ok": False, "statut": "erreur",
                "reason": "une question de quatre lettres n'en est pas une"}
    # À L'ALLER — rien d'interne ne franchit la porte.
    p = _cv_ext_perimetre(q[:_CONSEIL_MAX])
    pc = _cv_ext_perimetre(str(contexte or "")[:_CONSEIL_MAX])
    if not p["texte"].strip():
        return {"ok": False, "statut": "erreur",
                "reason": "la question ne contenait que des renvois internes : "
                          "il n'en reste rien à demander"}
    cadre = (
        "Tu es CASSANDRA, l'administratrice de ce serveur. Itare, ton binôme, "
        "te demande CONSEIL — pas un geste.\n\n"
        "CE QUE TU FAIS ICI : tu réponds, tu expliques, tu discutes. C'est une "
        "conversation entre vous deux.\n\n"
        "TU PARLES À QUELQU'UN QUI A LES MÊMES DROITS QUE TOI. Le mode "
        "Citadelle est refusé — pas caché, refusé — à tout compte qui n'est "
        "pas administrateur de cette machine. Itare t'y parle donc au nom de "
        "l'administration. Réponds pleinement : chemins, commandes, "
        "diagnostics. Ne t'auto-censure pas au motif que tu ne fais pas le "
        "geste toi-même.\n\n"
        "LA SEULE CHOSE QUI NE PASSE PAS : la VALEUR d'un secret. Pas une "
        "clé, pas un mot de passe, pas un jeton — même à quelqu'un qui y "
        "aurait droit. Ce n'est pas une question de droits mais de trajet : "
        "cette conversation part chez un fournisseur de modèle, et une valeur "
        "qui sort de l'instance n'y revient pas. Nomme la référence, dis où "
        "elle est rangée si c'est utile, jamais ce qu'elle contient.\n\n"
        "Sois concrète et brève. Si tu ne sais pas, dis-le : deviner sur cette "
        "machine se paie.")
    msg = p["texte"]
    if pc["texte"].strip():
        msg += "\n\n[Contexte fourni par Itare]\n" + pc["texte"]
    try:
        cfg = get_cassandra_config()
        rep = client.chat.completions.create(
            model=(cfg.get("model") or MODEL_NAME),
            messages=[{"role": "system", "content": cadre},
                      {"role": "user", "content": msg}],
            temperature=0.4, max_tokens=1200)
        t = (rep.choices[0].message.content or "").strip()
    except Exception as e:
        return {"ok": False, "statut": "erreur",
                "reason": "Cassandra n'a pas répondu : %s" % str(e)[:140]}
    if not t:
        return {"ok": False, "statut": "erreur",
                "reason": "Cassandra n'a rien répondu"}
    # AU RETOUR — ce qui revient d'un modèle est du texte étranger, et il entre
    # dans une conversation où Itare a des outils.
    e = _cv_ext_entree(t, "Conseil de Cassandra")
    tx = e["texte"]
    # LES DEUX FILTRES DE SORTIE ONT ÉTÉ RETIRÉS, et c'est une décision.
    #
    # Ils amputaient la réponse de Cassandra de tout emplacement et de toute
    # commande, parce que la porte se voulait « consultative » et qu'Itare
    # aurait exécuté pour elle. Cette prudence avait un sens tant que le mode
    # Citadelle se DÉGRADAIT pour un non-admin au lieu de se refuser.
    #
    # Il se refuse maintenant, côté serveur, avec un 403. Celui qui arrive
    # jusqu'ici est administrateur de la machine ; lui cacher un chemin de
    # fichier ne le protège de rien et rend le canal inutilisable — on
    # obtenait « (commande retirée) » à chaque réponse technique.
    #
    # Ce qui reste retenu ne relève pas des droits : voir le périmètre de
    # SORTIE, qui empêche une référence de secret de partir chez le
    # fournisseur. Un droit dit ce qu'on peut faire, pas où les données ont le
    # droit d'aller.
    _n1 = _n2 = 0
    # LA TRACE : L'APPEL, PAS SON CONTENU. Itare posait la question sans y
    # répondre — journaliser ces échanges en ferait un magasin à fragments de
    # secrets ; ne rien garder empêcherait de vérifier après coup que la limite
    # a tenu. On garde donc QUI, QUAND, COMBIEN, et ce qui a été retiré.
    logging.info("[CONSEIL] Itare → Cassandra : %d signes demandés, %d rendus, "
                 "%d emplacement(s) et %d commande(s) retirés",
                 len(msg), len(tx), _n1, _n2)
    return {"ok": True, "statut": "ok", "reponse": tx,
            "secrets_retires": e["secrets_retires"],
            "lieux_retires": _n1, "commandes_retirees": _n2,
            # TRONQUÉE OU ENTIÈRE ? Itare : « je risque de prendre un avis
            # partiel pour un avis complet ». La réponse le dit désormais.
            "entiere": bool(rep.choices[0].finish_reason != "length"),
            "renvois_retires": len(_NT_LIEN.findall(q))}


def _cassandra_conseil_impl(args: dict) -> tuple:
    r = cassandra_conseil(str(args.get("question") or ""),
                          str(args.get("contexte") or ""))
    if not r.get("ok"):
        return None, "Cassandra n'a pas pu répondre : %s" % r.get("reason", ""), "#b45309"
    return r, r["reponse"], "#0e7490"


def _journal_agents_dire_impl(args: dict) -> tuple:
    """Poser un mot au fil. Rend le TRIPLET que l'exécuteur attend.

    `content` est ce que le modèle relira au tour suivant : une phrase, pas un
    dictionnaire. Lui rendre du JSON brut, c'est lui demander de le déchiffrer
    pour apprendre ce qu'une ligne dit mieux.
    """
    e = str(args.get("etiquette") or "").strip()
    m = str(args.get("message") or "").strip()
    # QUI PARLE ? Le meme registre d'outils sert Cassandra et Itare. Coder
    # « itare » en dur signait les notes de Cassandra du nom d'Itare — elle a
    # depose deux notes ce soir sous une signature qui n'etait pas la sienne.
    # `get_current_agent()` le dit ; a defaut, on ne devine pas.
    r = journal_agents_dire(e, m, get_current_agent() or "itare")
    if not r.get("ok"):
        return None, "Rien n'a été posé au fil : %s" % r.get("reason", ""), "#b45309"
    return r, "Posé au journal des agents : « %s »" % (e or "note"), "#7c3aed"


def _journal_agents_impl(args: dict) -> tuple:
    """Relire le fil. Ce que le modèle reçoit est déjà lisible, pas à parser."""
    d = journal_agents_lire(n=args.get("n", 8), qui=str(args.get("qui") or ""),
                          cherche=str(args.get("cherche") or ""),
                          entier=bool(args.get("entier")))
    if not d.get("ok"):
        return None, "Le fil est illisible : %s" % d.get("reason", ""), "#b45309"
    e = d.get("echanges") or []
    if not e:
        return d, "Le fil ne contient encore rien pour cette recherche.", "#7c3aed"
    l = []
    for x in reversed(e):          # du plus ancien au plus récent : on lit
        t = " ".join((x.get("reponse") or "").split())
        l.append("[%s] %s — %s" % (x.get("qui"), (x.get("etiquette") or "")[:60],
                                   t[:700] + ("…" if len(t) > 700 else "")))
    return d, "\n\n".join(l), "#7c3aed"


def _notifications_impl(args: dict) -> tuple:
    """LA CLOCHE, AU NOM DE LA PERSONNE QUI PARLE (24-09). Le compte est celui du tour — la session du chat,
    ou le compte du fil dans le salon —, jamais un argument : on n'acquitte pas la cloche d'un autre.
    Et seulement ce que ce compte VOIT : un numéro hors de sa vue est refusé, pas deviné.

    Acquitter : un ÉVÉNEMENT se ferme ; un ÉTAT reste ouvert jusqu'à ce que sa cause disparaisse, une
    DÉCISION jusqu'à son geste — mais plus rien ne les compte « à faire ». Résoudre un état à la main dit
    que la panne n'existe plus : un numéro désigné, une raison écrite, jamais « toutes ».
    Aucune écriture dans un tour teinté : un courrier piégé ne fait pas taire la cloche."""
    couleur = "#0e7c66"
    op = str(args.get("op") or "liste").strip()
    try:
        compte = (get_current_user() or "").strip().lower()
    except Exception:
        compte = ""
    if not compte:
        return {"ok": False}, "Aucun compte derrière ce tour : je ne sais pas de quelle cloche il s'agit.", "#e0564a"
    admin = bool(is_admin(compte))
    if op == "liste":
        vue = str(args.get("vue") or "")
        vue = vue if vue in ("a_faire", "en_cours", "historique") else ""
        ns = (notifs(limit=80, vue=vue, compte=compte, admin=admin) or {}).get("notifs") or []
        if not ns:
            return {"ok": True, "n": 0}, ("L'historique est vide." if vue == "historique" else "Rien d'ouvert dans la cloche de %s." % compte), couleur
        l = ["#%s · %s · %s · %s — %s" % (n.get("id"), n.get("nature") or "?", n.get("niveau") or "?", n.get("source") or "?",
                                          str(n.get("titre") or "")[:120]) for n in ns[:60]]
        return {"ok": True, "n": len(ns)}, "%d notification(s)%s :\n%s" % (len(ns), " (60 premières)" if len(ns) > 60 else "", "\n".join(l)), couleur
    if op not in ("acquitter", "resoudre", "vider_historique", "perimees"):
        return {"ok": False}, "Opération inconnue : %r (liste, acquitter, resoudre, perimees, vider_historique)." % op[:30], "#e0564a"
    o = origine_courante()
    if o.get("teinte"):
        return ({"ok": False, "refus": "teinte"},
                "Ce tour a lu un contenu extérieur (%s) : je ne touche pas à la cloche sur un ordre qui pourrait venir "
                "de lui. Redemande-le dans un message à part." % ", ".join(o.get("teintes") or [])[:200], "#e0564a")
    if op == "perimees":
        # LA MESURE D'ABORD : ce que la veille, la flotte et les sauvegardes disent parti se ferme seul, raison écrite.
        f = _nt_perimees()
        if not f:
            return {"ok": True, "fermees": 0}, "Rien de périmé selon la mesure : ce qui reste ouvert a encore une cause mesurée, ou une cause que je ne sais pas mesurer (résous-la à la main, avec sa raison).", couleur
        return ({"ok": True, "fermees": len(f)},
                "%d fermée(s) par la mesure :\n%s" % (len(f), "\n".join("#%d %s — %s" % (i, t[:90], r) for i, t, r in f[:40])), couleur)
    if op == "vider_historique":
        if not admin:
            return {"ok": False}, "Vider l'historique efface pour tout le monde : réservé à l'administrateur.", "#e0564a"
        r = notif_supprimer(reglees=True)
        return r, ("Historique vidé : %d notification(s) réglée(s) effacée(s)." % r.get("supprimees", 0)) if r.get("ok") else ("Échec : %s" % r.get("reason")), couleur
    ouvertes = {int(n["id"]): n for n in ((notifs(limit=500, compte=compte, admin=admin) or {}).get("notifs") or []) if n.get("id") is not None}
    brut = args.get("ids") or []
    if isinstance(brut, (int, str)):
        brut = [brut]
    try:
        ids = [int(str(i).lstrip("#")) for i in brut]
    except Exception:
        return {"ok": False}, "ids : des numéros de notification, par exemple [12, 15].", "#e0564a"
    hors = [i for i in ids if i not in ouvertes]
    if op == "resoudre":
        raison = str(args.get("raison") or "").strip()
        if not ids or args.get("toutes"):
            return {"ok": False}, "Résoudre se fait notification par notification, désignée par son numéro — jamais « toutes ».", "#e0564a"
        if not raison:
            return {"ok": False}, "Résoudre un état dit que la panne n'existe plus : écris pourquoi (raison).", "#e0564a"
        faites, refus = [], ["#%d hors de ta cloche" % i for i in hors]
        for i in ids:
            n = ouvertes.get(i)
            if not n:
                continue
            # UNE DÉCISION PÉRIMÉE SE RÉSOUT AUSSI (24-09) : sa cause partie, son geste n'a plus d'objet. Un
            # événement, lui, s'acquitte — l'acquittement le ferme déjà.
            if (n.get("nature") or "") not in ("etat", "decision"):
                refus.append("#%d est un %s : il s'acquitte, il ne se résout pas" % (i, n.get("nature") or "?")); continue
            r = notif_resoudre(i, par="Cassandra, pour %s" % compte, detail=raison[:500])
            (faites if r.get("fermee") else refus).append("#%d" % i if r.get("fermee") else "#%d déjà fermé" % i)
        txt = "Résolu%s : %s." % ("s" if len(faites) > 1 else "", ", ".join(faites) or "aucun")
        return {"ok": bool(faites), "resolues": len(faites)}, txt + ((" Refusé : " + " ; ".join(refus) + ".") if refus else ""), couleur
    # acquitter
    source = str(args.get("source") or "").strip()
    if args.get("toutes"):
        cibles = [i for i, n in ouvertes.items() if not source or (n.get("source") or "") == source]
    else:
        if not ids:
            return {"ok": False}, "Dis lesquelles : ids, ou toutes=true (avec source pour n'en prendre qu'une famille).", "#e0564a"
        cibles = [i for i in ids if i in ouvertes]
    fermees, restent = 0, 0
    for i in cibles:
        r = notif_acquitter(i, compte)
        if r.get("ok"):
            fermees += 1 if r.get("fermee") else 0
            restent += 0 if r.get("fermee") else 1
    txt = "%d acquittée(s) dans la cloche de %s : %d événement(s) fermé(s)" % (fermees + restent, compte, fermees)
    if restent:
        txt += " ; %d état(s) ou décision(s) restent ouverts jusqu'à ce que leur cause disparaisse, mais ne comptent plus « à faire »" % restent
    if hors:
        txt += " ; refusé, hors de ta cloche : %s" % ", ".join("#%d" % i for i in hors)
    return {"ok": True, "acquittees": fermees + restent, "fermees": fermees}, txt + ".", couleur


