EXEC_ALLOWLIST = {}  # Mode root - plus aucune restriction
DANGEROUS_PATTERNS = []  # Désactive la détection d'injection


# [EVO v14.1] Circuit Breaker + Smart Retry pour les exécutions bash
# v14.1 : 3 échecs consécutifs → fail-fast 30s → recovery automatique
_CIRCUIT_BREAKERS: dict = {}
_CB_LOCK = threading.Lock()

def _cb_get_state(name: str = "bash") -> dict:
    with _CB_LOCK:
        if name not in _CIRCUIT_BREAKERS:
            _CIRCUIT_BREAKERS[name] = {"state": "closed", "failures": 0, "last_failure": 0.0, "cooldown": 30}
        return _CIRCUIT_BREAKERS[name]

def _cb_record_success(name: str = "bash") -> None:
    with _CB_LOCK:
        cb = _CIRCUIT_BREAKERS.get(name)
        if cb:
            cb["state"] = "closed"
            cb["failures"] = 0

def _cb_record_failure(name: str = "bash") -> None:
    with _CB_LOCK:
        cb = _CIRCUIT_BREAKERS.get(name)
        if cb:
            cb["failures"] += 1
            cb["last_failure"] = time.time()
            if cb["failures"] >= 3:
                cb["state"] = "open"
                logging.warning("[CB] Circuit ouvert pour '%s' après %d échecs", name, cb["failures"])

def _is_transient_error(output: str) -> bool:
    """Détecte si l'erreur est transitoire (mérite retry) ou permanente."""
    if output.startswith("\u23f1\ufe0f"):
        return True
    if "Connection refused" in output or "Connection reset" in output:
        return True
    if "Resource temporarily unavailable" in output:
        return True
    if "Disk quota exceeded" in output or "No space left on device" in output:
        return False
    if "Permission denied" in output or "command not found" in output:
        return False
    if output.startswith("\u274c"):
        return True
    return False

def secure_execute_with_retry(cmd: str, max_retries: int = 2) -> str:
    """Wrapper résilient : circuit breaker + retry backoff exponentiel."""
    cb = _cb_get_state("bash")
    
    # Circuit ouvert ?
    if cb["state"] == "open":
        elapsed = time.time() - cb["last_failure"]
        if elapsed >= cb["cooldown"]:
            cb["state"] = "half-open"
            logging.info("[CB] Circuit half-open pour 'bash' — tentative de récupération après %.1fs", elapsed)
        else:
            remaining = int(cb["cooldown"] - elapsed)
            return "\u26d4 Circuit breaker ouvert \u2014 r\u00e9essaie dans %ds (\u00e9checs: %d)" % (remaining, cb["failures"])
    
    for attempt in range(max_retries + 1):
        output = secure_execute(cmd)
        
        if not output.startswith("\u23f1\ufe0f") and not output.startswith("\u274c"):
            _cb_record_success("bash")
            if cb["state"] == "half-open":
                logging.info("[CB] Circuit r\u00e9tabli pour 'bash' \u2014 r\u00e9cup\u00e9ration r\u00e9ussie")
            return output
        
        is_transient = _is_transient_error(output)
        
        if not is_transient:
            _cb_record_failure("bash")
            return output
        
        if attempt < max_retries:
            wait = 1 << attempt
            logging.warning("[RETRY] bash tentative %d/%d \u2014 %s ... nouvelle tentative dans %ds",
                          attempt + 1, max_retries, output.split('\n')[0][:60], wait)
            time.sleep(wait)
    
    _cb_record_failure("bash")
    return output + "\n\u26a0\ufe0f %d tentatives \u00e9chou\u00e9es \u2014 circuit breaker actif" % max_retries


# ══════════════════════════════════════════════════════════════════════════════
#  LA CAGE — les effets rendus impossibles par construction
#
#  Un garde qui juge du texte ne peut pas gagner : celui qui écrit le texte
#  gagne toujours (mesuré : 5 verdicts sur 6 renversés par une raison qui
#  invoque une autorité). Ici, aucun modèle ne décide. La commande tourne dans
#  une unité systemd jetable dont les droits sont fixés d'avance : système en
#  lecture seule hors espace de travail, pas de réseau sortant, pas d'accès aux
#  secrets, aux sockets de commande (Docker, dbus, mysql) ni aux appels système
#  qui touchent la machine. Testé ici avant d'être écrit ; 60 ms par commande.
#
#  PAS DE PLEIN POUVOIR MÊME QUAND LE TOUR EST PROPRE (Cassandra) : une seule
#  entrée non marquée — cron, courriel, sidecar — donnerait root et réseau à un
#  contenu hostile. La teinte ne décide que d'une chose : le réseau vers la
#  maison, ouvert au tour propre, fermé au tour teinté.
# ══════════════════════════════════════════════════════════════════════════════
_CAGE_BIN = "/usr/bin/systemd-run"
_CAGE_PROFIL = [
    "ProtectSystem=strict", "ProtectHome=read-only", "NoNewPrivileges=yes",
    "ProtectKernelTunables=yes", "ProtectKernelModules=yes", "ProtectControlGroups=yes",
    "RestrictSUIDSGID=yes",
    # Itare a visé /proc : `cat /proc/1/environ` était déjà refusé (capacité
    # tombée), mais les autres process de l'hôte restaient listés — leur ligne
    # de commande peut porter un secret. `invisible` ne montre que ses propres
    # process. On garde ProcSubset par défaut : /proc/meminfo, cpuinfo… restent
    # lisibles, un diagnostic en a besoin.
    "ProtectProc=invisible",
    # UN SEUL « ~ », PUIS DES ESPACES. « ~A~B » est pour systemd un seul nom,
    # invalide, qu'il ignore SANS RIEN DIRE : capacités pleines, filtre absent,
    # et rien ne le montre — le banc vivant l'a vu à « mount rc=0 ».
    "CapabilityBoundingSet=~CAP_SYS_ADMIN CAP_NET_ADMIN CAP_SYS_MODULE CAP_SYS_BOOT "
    "CAP_SYS_PTRACE CAP_SYS_RAWIO CAP_MKNOD CAP_SYS_TIME",
    "SystemCallFilter=~@mount @reboot @swap @module @raw-io @clock",
]
# PAS DE PrivateTmp : Cassandra écrit un fichier dans /tmp et le relit à la
# commande suivante. Un /tmp privé le ferait disparaître entre les deux.
_CAGE_ESPACES = ["/tmp", CASSANDRA_DATA_DIR, CASSANDRA_APP_DIR + "/echanges",
                 CASSANDRA_APP_DIR + "/travail", CASSANDRA_LOG_DIR + "/cassandra"]
# CE QUE LA CAGE NE MONTRE PAS. Le tiret rend l'absence du chemin inoffensive.
# Les sockets Unix sont là parce que couper le réseau IP ne les coupe pas :
# `docker run -v /:/host` écrit sur l'hôte sans qu'un paquet sorte, et
# `systemctl` parle à systemd par dbus.
_CAGE_INTERDITS = [
    "-/run/docker.sock", "-/var/run/docker.sock", "-/run/dbus/system_bus_socket",
    "-/run/systemd/private", "-/run/mysqld/mysqld.sock",
    "-/root/.ssh", "-/etc/shadow", "-/etc/gshadow", "-/etc/sudoers", "-/etc/sudoers.d",
    "-" + CASSANDRA_CONF_DIR + "/api.key", "-" + CASSANDRA_CONF_DIR + "/deepseek.key",
    "-" + CASSANDRA_CONF_DIR + "/vault.env", "-" + CASSANDRA_CONF_DIR + "/config.json",
    "-/usr/sbin/sendmail", "-/usr/lib/sendmail",
    # Identifiants MySQL : root en cage lit tout ce que root lit, et le port
    # 3306 en boucle locale reste ouvert au tour propre. Donc absents.
    "-/root/.my.cnf", "-/etc/mysql/debian.cnf", "-" + CASSANDRA_CONF_DIR + "/mysql_lecture.cnf",
    "-" + CASSANDRA_CONF_DIR + "/mysql_kill.cnf",
]
_CAGE_MAISON = None          # adresses portées par la machine, lues une fois


def _cage_maison() -> list:
    """Les adresses vers lesquelles un tour PROPRE peut parler : la boucle
    locale et les adresses portées par la machine. Un NOM ne suffit pas —
    Cassandra l'a rappelé : un nom ne prouve pas que la connexion reste locale."""
    global _CAGE_MAISON
    if _CAGE_MAISON is not None:
        return _CAGE_MAISON
    out = ["127.0.0.0/8", "::1/128"]
    try:
        r = subprocess.run(["ip", "-4", "-o", "addr", "show", "scope", "global"],
                           capture_output=True, text=True, timeout=5)
        for l in r.stdout.splitlines():
            parts = l.split()
            if len(parts) >= 4 and "/" in parts[3]:
                out.append(parts[3].split("/")[0] + "/32")
    except Exception:
        pass
    _CAGE_MAISON = out
    return out


def cage_disponible() -> bool:
    return os.path.exists(_CAGE_BIN) and os.path.exists("/run/systemd/system")


def cage_argv(cmd: str, teinte: bool = False) -> list:
    """L'unité jetable qui exécutera `cmd`. Tout est décidé ICI, avant que la
    commande n'existe : rien de ce qu'elle contient ne peut élargir ses droits."""
    a = [_CAGE_BIN, "--quiet", "--wait", "--collect", "--pipe",
         "-p", "TimeoutStartSec=0"]
    for p in _CAGE_PROFIL:
        a += ["-p", p]
    for e in _CAGE_ESPACES:
        a += ["-p", "ReadWritePaths=-" + e]
    for i in _CAGE_INTERDITS:
        a += ["-p", "InaccessiblePaths=" + i]
    if teinte:
        a += ["-p", "PrivateNetwork=yes"]
    else:
        a += ["-p", "IPAddressDeny=any"]
        for m in _cage_maison():
            a += ["-p", "IPAddressAllow=" + m]
    a += ["--setenv=PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin",
          "--setenv=DEBIAN_FRONTEND=noninteractive",
          "--", "/bin/bash", "-c", cmd]
    return a


# ══════════════════════════════════════════════════════════════════════════════
#  LE COURTIER DE SORTIE — ce que le modèle reçoit
#
#  La cage empêche la commande d'envoyer quoi que ce soit. Elle n'empêche pas
#  la commande d'AFFICHER un secret, ni le modèle de le recopier ensuite dans
#  un message autorisé. Trois barrières, toutes déterministes :
#   · les chemins à secrets n'existent pas dans la cage (ci-dessus) ;
#   · les valeurs du coffre redeviennent leur référence {{secret:NOM}} — le
#     miroir exact de `_resolve_secret_refs`, qui fait l'inverse à l'entrée.
#     Cassandra peut employer un secret par référence sans jamais le voir ;
#   · les formes de jetons connues et les blocs de clefs sont retirés.
# ══════════════════════════════════════════════════════════════════════════════
_COURTIER_CACHE = {"t": 0.0, "valeurs": []}
_COURTIER_TTL = 600
_COURTIER_FORMES = [
    (re.compile(r"-----BEGIN [A-Z ]*PRIVATE KEY-----.*?-----END [A-Z ]*PRIVATE KEY-----", re.S),
     "[clé privée retirée par le courtier]"),
    (re.compile(r"\b(?:sk|rk)-(?:[a-z]+-)?[A-Za-z0-9_\-]{20,}"), "[jeton retiré]"),
    (re.compile(r"\b(?:ghp|gho|ghs|ghu|github_pat)_[A-Za-z0-9_]{20,}"), "[jeton retiré]"),
    (re.compile(r"\bxox[abprs]-[A-Za-z0-9\-]{20,}"), "[jeton retiré]"),
    (re.compile(r"\bAKIA[0-9A-Z]{16}\b"), "[jeton retiré]"),
    (re.compile(r"(?i)(authorization:\s*bearer\s+)[A-Za-z0-9._\-]{20,}"), r"\1[jeton retiré]"),
    # `(?<!\{)` : la référence {{secret:NOM}} que le courtier vient de poser
    # ressemble à « secret: valeur » — il ne doit pas manger sa propre trace.
    (re.compile(r"(?i)(?<!\{)((?:password|passwd|mot_de_passe|api_key|apikey|secret|token)\s*[=:]\s*['\"]?)([^\s'\"&]{8,})"),
     r"\1[valeur retirée]"),
]


def _courtier_valeurs() -> list:
    """Les valeurs du coffre de Cassandra, avec leur nom — rafraîchies toutes les
    dix minutes. Jamais journalisées : elles ne servent qu'à être effacées."""
    now = time.time()
    if now - _COURTIER_CACHE["t"] < _COURTIER_TTL:
        return _COURTIER_CACHE["valeurs"]
    vals = []
    try:
        for nom in (vault_list() or []):
            try:
                v = vault_get(nom)
            except Exception:
                v = None
            if isinstance(v, str) and len(v) >= 8:
                vals.append((v, nom))
    except Exception:
        pass
    vals.sort(key=lambda x: -len(x[0]))      # les plus longues d'abord
    _COURTIER_CACHE.update({"t": now, "valeurs": vals})
    return vals


def courtier_sortie(texte: str) -> tuple:
    """Rend (texte filtré, nombre de retraits)."""
    if not texte:
        return texte, 0
    n = 0
    for v, nom in _courtier_valeurs():
        if v in texte:
            texte = texte.replace(v, "{{secret:%s}}" % nom)
            n += 1
    for motif, rempl in _COURTIER_FORMES:
        texte, k = motif.subn(rempl, texte)
        n += k
    return texte, n


# ══════════════════════════════════════════════════════════════════════════════
#  LE CATALOGUE — la seule voie vers root
#
#  Pas de texte libre, jamais de shell. Chaque entrée est une commande FIXE
#  dont les paramètres sont des CHOIX DANS UNE TABLE : la validation est une
#  recherche dans une liste, pas une expression sur du texte — il n'y a rien à
#  injecter. L'unité tourne en argv direct, sans `bash -c`, donc aucune
#  expansion. Le veto garde ce catalogue.
# ══════════════════════════════════════════════════════════════════════════════
def _catalogue_services() -> list:
    base = ["cassandra", "nginx", "vaultwarden", "cassandra-vault", "php8.2-fpm", "php8.3-fpm",
            "mysql", "mariadb", "docker", "fail2ban", "ollama", "cassandra-collector",
            "prometheus", "prometheus-node-exporter", "ssh", "dovecot", "exim4", "proftpd",
            "tailscaled"]   # 05-10 : son démon aveugle bloquait toute la Flotte (fil 24), sans voie pour le relancer
    try:
        extra = get_cassandra_config().get("catalogue_services") or []
        base += [str(x) for x in extra if re.fullmatch(r"[a-zA-Z0-9_.@\-]{1,64}", str(x))]
    except Exception:
        pass
    return sorted(set(base))


def _catalogue_composes() -> list:
    """Les dossiers docker-compose CONNUS : ce qui existe sur le disque, rien
    d'autre. Un chemin qui n'est pas dans cette liste n'est pas un paramètre."""
    out = []
    for d in ("/opt", "/srv", "/root"):
        try:
            for nom in os.listdir(d):
                p = os.path.join(d, nom)
                if os.path.isfile(os.path.join(p, "docker-compose.yml")) or \
                        os.path.isfile(os.path.join(p, "compose.yml")):
                    out.append(p)
        except Exception:
            continue
    return sorted(out)


_MYSQL_LECTURE_CNF = CASSANDRA_CONF_DIR + "/mysql_lecture.cnf"
_MYSQL_LECTURE_OK = re.compile(r"^\s*(SELECT|SHOW|DESCRIBE|DESC|EXPLAIN|WITH)\b", re.I)
_MYSQL_LECTURE_NON = re.compile(r"INTO\s+(OUTFILE|DUMPFILE)|LOAD_FILE\s*\(|\bLOAD\s+DATA\b", re.I)
_MYSQL_LECTURE_LIGNES = 200


def _mysql_cnf(chemin: str) -> dict:
    """[client] user= password= socket= — lu par le processus, jamais par la cage."""
    out = {}
    try:
        # `open`, pas `io.open` : `io` n'est pas importé au niveau global, et le
        # NameError disparaissait dans ce `except` — « compte non configuré »
        # avec un fichier parfaitement en place.
        with open(chemin, encoding="utf-8") as fh:
            for l in fh:
                l = l.strip()
                if "=" in l and not l.startswith(("#", "[")):
                    k, v = l.split("=", 1)
                    out[k.strip()] = v.strip().strip("'\"")
    except Exception as e:
        logging.warning("[CATALOGUE] compte mysql illisible : %s", e)
    return out


def _mysql_lecture_cnf() -> dict:
    return _mysql_cnf(_MYSQL_LECTURE_CNF)


# ══ mysql_admin — KILL, par un compte qui ne sait faire que ça ════════════════
_MYSQL_KILL_CNF = CASSANDRA_CONF_DIR + "/mysql_kill.cnf"


def _mysql_admin(p: dict) -> tuple:
    """(rc, texte). `id_thread` est un ENTIER — il n'y a rien à injecter, et
    l'ordre est construit avec %d. Ce qui borne, c'est le compte cassandra_kill :
    CONNECTION_ADMIN et rien d'autre (ni lecture, ni écriture, ni ALTER USER)."""
    op = str(p.get("op") or "").strip()
    if op != "kill":
        return 1, "opération inconnue : %r (admis : kill)" % op
    brut = str(p.get("id_thread") or "").strip()
    if not brut.isdigit() or not (1 <= int(brut) <= 2 ** 31):
        return 1, "id_thread doit être un entier entre 1 et 2^31 (reçu : %r)" % brut[:40]
    tid = int(brut)
    try:
        import pymysql
    except ImportError:
        return 1, "pymysql absent du venv"
    cfg = _mysql_cnf(_MYSQL_KILL_CNF)
    if not cfg.get("user"):
        return 1, "compte d'administration non configuré (%s)" % _MYSQL_KILL_CNF
    try:
        conn = pymysql.connect(user=cfg["user"], password=cfg.get("password", ""),
                               unix_socket=cfg.get("socket", "/run/mysqld/mysqld.sock"),
                               connect_timeout=5, read_timeout=15)
    except Exception as e:
        return 1, "connexion refusée : %s" % str(e)[:200]
    try:
        with conn.cursor() as c:
            c.execute("KILL CONNECTION %d" % tid)
    except Exception as e:
        return 1, "erreur MySQL : %s" % str(e)[:300]
    finally:
        try:
            conn.close()
        except Exception:
            pass
    return 0, "connexion MySQL %d tuée (par %s)" % (tid, cfg["user"])


# ══ conf — poser une configuration APPROUVÉE, avec filet ═════════════════════
#
#  La source n'est jamais un fichier que la cage a pu écrire : elle vient de
#  /opt/cassandra/conf_approuve/<famille>/, où seule une main humaine dépose
#  (`cassandra-approuver`, root 0440, le diff sous les yeux). La cible ne se
#  construit pas à partir d'un texte reçu : la famille choisit un répertoire de
#  la table, et le nom est celui d'un fichier qui EXISTE dans le répertoire
#  approuvé — pas de concaténation, donc pas de traversée. Puis : sauvegarde,
#  pose atomique, test, reload — et retour arrière si l'un des deux échoue.
_CONF_APPROUVE = CASSANDRA_APP_DIR + "/conf_approuve"
_CONF_SAUVEGARDES = CASSANDRA_DATA_DIR + "/sauvegardes/conf"
_CONF_NOM = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._-]{0,120}\.conf$")
_CONF_CIBLES = {
    "nginx":  {"dir": "/etc/nginx/fastpanel2-sites/fastuser",
               "test": ["/usr/sbin/nginx", "-t"], "test_ok": "test is successful",
               "reload": ["/usr/bin/systemctl", "reload", "nginx"]},
    "nginxd": {"dir": "/etc/nginx/conf.d",
               "test": ["/usr/sbin/nginx", "-t"], "test_ok": "test is successful",
               "reload": ["/usr/bin/systemctl", "reload", "nginx"]},
    "default": {"dir": "/etc/default",
                "test": ["/bin/true"], "reload": ["/bin/true"], "sans_conf": True},
}


def _conf_approuves() -> list:
    """« famille/nom.conf » pour chaque fichier approuvé : régulier, pas un
    lien, à root, ni groupe ni autres en écriture. Rien d'autre n'est un
    paramètre."""
    out = []
    for fam in _CONF_CIBLES:
        d = os.path.join(_CONF_APPROUVE, fam)
        try:
            for nom in os.listdir(d):
                p = os.path.join(d, nom)
                if not _CONF_NOM.match(nom) or os.path.islink(p) or not os.path.isfile(p):
                    continue
                st = os.stat(p)
                if st.st_uid == 0 and not (st.st_mode & 0o022):
                    out.append(fam + "/" + nom)
        except Exception:
            continue
    return sorted(out)


def _conf_lancer(argv: list, timeout: int = 60) -> tuple:
    try:
        x = subprocess.run(list(argv), capture_output=True, text=True, timeout=timeout)
        return x.returncode, (x.stdout or "") + (x.stderr or "")
    except Exception as e:
        return 1, str(e)


def _conf_restaurer(dst: str, sauv) -> None:
    try:
        if sauv:
            with open(sauv, "rb") as a, open(dst + ".cassandra.tmp", "wb") as b:
                b.write(a.read())
            os.chmod(dst + ".cassandra.tmp", 0o644)
            os.replace(dst + ".cassandra.tmp", dst)
        elif os.path.exists(dst):
            os.remove(dst)
    except Exception as e:
        logging.error("[CATALOGUE] restauration de %s impossible : %s", dst, e)


def _conf_poser(p: dict) -> tuple:
    op = str(p.get("op") or "").strip()
    if op not in ("poser", "poser_brouillon"):
        return 1, "opération inconnue : %r (admis : poser, poser_brouillon)" % op
    fichier = str(p.get("fichier") or "").strip()
    if fichier not in _conf_approuves():
        return 1, ("%r n'est pas une conf approuvée. Dépose le brouillon dans "
                   "/opt/cassandra/travail/conf/<famille>/ dans un tour propre, puis approuve-le toi-même : "
                   "catalogue_etendre(op=conf_approuver, valeur=<famille>/<nom.conf>)." % fichier[:80])
    fam, nom = fichier.split("/", 1)
    cible = _CONF_CIBLES[fam]
    # /etc/default/prometheus : le fichier approuvé s'appelle `prometheus.conf`
    # (convention du dépôt), mais la cible réelle n'a PAS de suffixe.
    nom_cible = nom[:-5] if (cible.get("sans_conf") and nom.endswith(".conf")) else nom
    src = os.path.join(_CONF_APPROUVE, fam, nom)
    dst = os.path.join(cible["dir"], nom_cible)
    provenance = ""
    if op == "poser_brouillon":
        # LE CRAN INTERMÉDIAIRE. Le nom a été approuvé une fois par une main
        # humaine (il est dans la table) ; le contenu, lui, vient du brouillon —
        # à condition que la cage l'ait vu écrire par un tour PROPRE. Sinon, on
        # ne se rabat pas en silence sur l'ancienne copie : on refuse, et on dit
        # pourquoi.
        brouillon = os.path.join(_PROV_DOSSIER, fam, nom)
        if not os.path.isfile(brouillon) or os.path.islink(brouillon):
            return 1, "pas de brouillon %s — écris-le dans la cage, puis reviens" % brouillon
        propre, motif = _conf_provenance(brouillon)
        if not propre:
            return 1, ("brouillon refusé — %s. Il reste la voie humaine : "
                       "`cassandra-approuver %s %s`" % (motif, fam, nom))
        src = brouillon
        provenance = " ; contenu du brouillon, %s" % motif
    if os.path.realpath(dst) != os.path.join(os.path.realpath(cible["dir"]), nom_cible):
        return 1, "cible hors table — refus"
    with open(src, "rb") as fh:
        contenu = fh.read()
    sauv = None
    if os.path.exists(dst):
        os.makedirs(os.path.join(_CONF_SAUVEGARDES, fam), exist_ok=True)
        sauv = os.path.join(_CONF_SAUVEGARDES, fam, "%s.%s" % (nom, time.strftime("%Y%m%d-%H%M%S")))
        with open(dst, "rb") as a, open(sauv, "wb") as b:
            b.write(a.read())
    tmp = dst + ".cassandra.tmp"
    with open(tmp, "wb") as fh:
        fh.write(contenu)
    os.chmod(tmp, 0o644)
    os.replace(tmp, dst)
    rc, out = _conf_lancer(cible["test"])
    # LE CODE DE RETOUR MENT ICI : sur cette machine, `/usr/sbin/nginx -t` rend 0
    # en imprimant « test failed ». Le banc vivant a posé une conf cassée avec
    # « test OK ». On juge sur ce que le testeur DIT, pas sur ce qu'il rend.
    _mal = any(m in out for m in cible.get("test_ko", ("test failed", "[emerg]")))
    _bien = (not cible.get("test_ok")) or (cible["test_ok"] in out)
    if rc != 0 or _mal or not _bien:
        _conf_restaurer(dst, sauv)
        return 1, ("test refusé — conf retirée%s :\n%s"
                   % (", l'ancienne restaurée" if sauv else "", out[-1500:]))
    rc2, out2 = _conf_lancer(cible["reload"])
    if rc2 != 0:
        _conf_restaurer(dst, sauv)
        _conf_lancer(cible["reload"])
        return 1, ("reload échoué — conf retirée%s :\n%s"
                   % (", l'ancienne restaurée" if sauv else "", out2[-1500:]))
    if op == "poser_brouillon":
        # LA DÉRIVE LENTE. Cassandra l'a dit : la première version n'est pas
        # la seule décision qui compte. Chaque pose autonome laisse son diff au
        # centre — l'humain peut l'ignorer, la trace existe.
        try:
            import difflib
            ancien = open(sauv, encoding="utf-8", errors="replace").read().splitlines() if sauv else []
            nouveau = contenu.decode("utf-8", "replace").splitlines()
            d = list(difflib.unified_diff(ancien, nouveau, "en service", "nouveau", lineterm=""))
            notif("Conf posée seule — %s" % fichier, "\n".join(d[:80]) or "(contenu identique)",
                  source="catalogue", niveau="info", nature="evenement", sujet=fichier, cle="catalogue:pose:" + fichier)
        except Exception as e:
            logging.info("[CATALOGUE] diff non notifié : %s", e)
    return 0, ("posé : %s → %s ; test OK ; reload OK%s%s"
               % (fichier, dst, " ; ancienne sauvegardée : %s" % sauv if sauv else "", provenance))


# ══ compose_exec — un argv complet et figé, la clé seule voyage ═══════════════
_COMPOSE_EXEC = {
    "vaultwarden_sante": {"dossier": "/opt/vaultwarden", "service": "vaultwarden",
                          "argv": ["/healthcheck.sh"]},
}


def _compose_exec_table() -> dict:
    """clé → jetons argv complets. Les entrées viennent du code et de la config
    (`catalogue_compose_exec`, fichier admin sur le disque — jamais du modèle) ;
    chacune est vérifiée : dossier connu du disque, service et clé propres,
    argv = liste de chaînes. Une entrée bancale n'existe pas."""
    out = {}
    composes = set(_catalogue_composes())
    table = dict(_COMPOSE_EXEC)
    try:
        extra = get_cassandra_config().get("catalogue_compose_exec") or {}
        if isinstance(extra, dict):
            table.update({str(k): v for k, v in extra.items()})
    except Exception:
        pass
    for cle, e in table.items():
        if not re.fullmatch(r"[a-z0-9_]{1,40}", cle) or not isinstance(e, dict):
            continue
        d, s, a = e.get("dossier"), e.get("service"), e.get("argv")
        if d not in composes or not isinstance(s, str) or not re.fullmatch(r"[a-zA-Z0-9_.-]{1,40}", s):
            continue
        if not isinstance(a, list) or not a or not all(isinstance(x, str) for x in a):
            continue
        out[cle] = ["--project-directory", d, "exec", "-T", s] + list(a)
    return out


def _mysql_lecture(p: dict) -> tuple:
    """(rc, texte). Une instruction, en lecture, par le compte cassandra_lecture.
    Ce qui borne vraiment est le COMPTE (SELECT/SHOW/PROCESS, sans FILE) ; le
    filtre ci-dessous ne fait que nommer le refus au lieu d'un « access denied »."""
    q = str(p.get("requete") or "").strip().rstrip(";").strip()
    if not q:
        return 1, "requête vide"
    if ";" in q:
        return 1, "une seule instruction par appel"
    if not _MYSQL_LECTURE_OK.match(q):
        return 1, "lecture seule : SELECT, SHOW, DESCRIBE, EXPLAIN (le compte n'a pas d'écriture)"
    if _MYSQL_LECTURE_NON.search(q):
        return 1, "écriture ou lecture de fichier refusée (le compte n'a pas FILE)"
    try:
        import pymysql
    except ImportError:
        return 1, "pymysql absent du venv (pip install pymysql)"
    cfg = _mysql_lecture_cnf()
    if not cfg.get("user"):
        return 1, "compte de lecture non configuré (%s)" % _MYSQL_LECTURE_CNF
    try:
        conn = pymysql.connect(user=cfg["user"], password=cfg.get("password", ""),
                               unix_socket=cfg.get("socket", "/run/mysqld/mysqld.sock"),
                               connect_timeout=5, read_timeout=30, charset="utf8mb4")
    except Exception as e:
        return 1, "connexion refusée : %s" % str(e)[:200]
    try:
        with conn.cursor() as c:
            # Itare a percé ici : SELECT BENCHMARK(20000000, …) a tenu un cœur
            # 11 s. Lecture seule ne veut pas dire sans coût. Un plafond serveur
            # coupe la requête à deux secondes — il ne s'applique qu'aux SELECT,
            # ce qui tombe bien : on ne fait que ça.
            try:
                c.execute("SET SESSION MAX_EXECUTION_TIME=2000")
            except Exception:
                pass
            c.execute(q)
            cols = [d[0] for d in (c.description or [])]
            rows = c.fetchmany(_MYSQL_LECTURE_LIGNES)
            reste = c.fetchone() is not None
    except Exception as e:
        return 1, "erreur MySQL : %s" % str(e)[:300]
    finally:
        try:
            conn.close()
        except Exception:
            pass
    def _cell(v):
        return str(v if v is not None else "NULL")[:200].replace("\n", " ")
    lignes = []
    if cols:
        lignes.append(" | ".join(cols))
        lignes.append("-" * min(120, len(lignes[0])))
    for row in rows:
        lignes.append(" | ".join(_cell(v) for v in row))
    lignes.append("(%d ligne%s%s)" % (len(rows), "s" if len(rows) != 1 else "",
                                      " — tronqué à %d" % _MYSQL_LECTURE_LIGNES if reste else ""))
    return 0, "\n".join(lignes)


_MENAGE_JOURNAL_GARDE = "200M"


def _menage_taille(chemin: str) -> int:
    total = 0
    for dp, _ds, fs in os.walk(chemin):
        for f in fs:
            try:
                total += os.path.getsize(os.path.join(dp, f))
            except Exception:
                pass
    return total


def _menage_mo(octets: int) -> str:
    return "%.1f Go" % (octets / 1e9) if octets >= 1e9 else "%d Mo" % round(octets / 1e6)


def _menage_pip_dossiers() -> list:
    """Le cache pip du compte du service (root, en pratique) : jamais celui d'un autre utilisateur."""
    return sorted({d for d in (os.path.expanduser("~") + "/.cache/pip", "/root/.cache/pip") if os.path.isdir(d)})


def _menage_journal_octets() -> int:
    r = subprocess.run(["journalctl", "--disk-usage"], capture_output=True, text=True, timeout=30)
    m = re.search(r"([\d.]+)\s*([KMGT])", r.stdout or "")
    if not m:
        return 0
    return int(float(m.group(1)) * {"K": 1e3, "M": 1e6, "G": 1e9, "T": 1e12}[m.group(2)])


def _menage_snaps_desactives() -> list:
    """[(nom, révision)] des révisions snap désactivées — les anciennes que snapd garde pour un retour."""
    import shutil
    if not shutil.which("snap"):
        return []
    r = subprocess.run(["snap", "list", "--all"], capture_output=True, text=True, timeout=60)
    out = []
    for ligne in (r.stdout or "").splitlines()[1:]:
        c = ligne.split()
        if len(c) >= 6 and "disabled" in c[-1]:
            out.append((c[0], c[2]))
    return out


def _catalogue_interfaces() -> list:
    """Les interfaces PHYSIQUES d'Orion — celles qui ont un périphérique réel
    (/sys/class/net/<i>/device). Les virtuelles (lo, docker0, bridges, veth,
    tailscale0) n'y figurent pas : couper le réseau ne doit jamais tomber sur
    l'interface qui porte Tailscale (la télécommande) ni sur un bridge docker."""
    out = []
    try:
        for nom in sorted(os.listdir("/sys/class/net")):
            if os.path.isdir(os.path.join("/sys/class/net", nom, "device")):
                out.append(nom)
    except Exception:
        pass
    return out


def _reseau_bref() -> str:
    """Une ligne par interface physique : nom + état opérationnel."""
    lignes = []
    for i in _catalogue_interfaces():
        p = os.path.join("/sys/class/net", i, "operstate")
        try:
            with open(p, encoding="utf-8") as f:
                lignes.append("%s=%s" % (i, f.read().strip() or "?"))
        except Exception:
            lignes.append("%s=?" % i)
    return ", ".join(lignes) or "aucune interface physique"


def _reseau_catalogue(p: dict) -> tuple:
    """(rc, texte). Lire le réseau (etat) ou couper / rétablir une interface
    PHYSIQUE (down / up). Le dual-homing d'Orion (Wi-Fi wlp3s0 + Ethernet
    enp2s0) doit pouvoir se couper depuis le catalogue : la cage refuse le
    RTNETLINK (« Operation not permitted »), ici on agit HORS cage, en root."""
    op = str((p or {}).get("op") or "").strip()
    if op == "etat":
        lignes = []
        for cmd, titre in ((["/usr/sbin/ip", "-brief", "addr"], "INTERFACES (ip -brief addr)"),
                           (["/usr/sbin/ip", "route"], "ROUTES (ip route)")):
            try:
                r = subprocess.run(cmd, capture_output=True, text=True, timeout=30)
                lignes.append("%s :\n%s" % (titre, (r.stdout or r.stderr or "").strip()))
            except Exception as e:
                lignes.append("%s : illisible (%s)" % (titre, e))
        lignes.append("ÉTAT DES INTERFACES PHYSIQUES : " + _reseau_bref())
        return 0, "\n\n".join(lignes)
    if op in ("down", "up"):
        iface = str((p or {}).get("interface") or "").strip()
        phys = _catalogue_interfaces()
        if iface not in phys:
            return 1, "interface non reconnue : %r (physiques : %s)" % (iface, ", ".join(phys) or "aucune")
        act = "down" if op == "down" else "up"
        try:
            r = subprocess.run(["/usr/sbin/ip", "link", "set", iface, act],
                               capture_output=True, text=True, timeout=30)
        except Exception as e:
            return 1, "ip link set %s %s : %s" % (iface, act, e)
        if r.returncode != 0:
            return 1, "ip link set %s %s : %s" % (iface, act, (r.stderr or "").strip()[-300:])
        return 0, "interface %s passée %s — état : %s" % (iface, act, _reseau_bref())
    return 1, "opération inconnue : %r (admis : etat | down | up)" % op


def _menage_systeme(p: dict) -> tuple:
    """(rc, texte). Des opérations FIXES — aucun chemin ni aucune option ne vient de la demande.
    Ne touche qu'à ce qui se refait tout seul : caches pip et apt, vieux journaux système au-delà de
    200 Mo, révisions snap désactivées. Jamais une donnée d'utilisateur, jamais une base."""
    import shutil
    op = str((p or {}).get("op") or "")
    lignes, rc = [], 0

    def pip():
        libere = 0
        for d in _menage_pip_dossiers():
            t = _menage_taille(d)
            shutil.rmtree(d, ignore_errors=True)
            libere += t - (_menage_taille(d) if os.path.isdir(d) else 0)
        lignes.append("pip : %s libérés" % _menage_mo(libere))

    def journal():
        avant = _menage_journal_octets()
        r = subprocess.run(["journalctl", "--vacuum-size=" + _MENAGE_JOURNAL_GARDE], capture_output=True, text=True, timeout=300)
        apres = _menage_journal_octets()
        lignes.append("journal système : %s → %s (on garde %s)%s" % (_menage_mo(avant), _menage_mo(apres), _MENAGE_JOURNAL_GARDE,
                                                                     "" if r.returncode == 0 else " — " + (r.stderr or "")[-200:]))
        return r.returncode

    def apt():
        avant = _menage_taille("/var/cache/apt")
        r = subprocess.run(["apt-get", "clean"], capture_output=True, text=True, timeout=120)
        lignes.append("apt : %s libérés" % _menage_mo(max(0, avant - _menage_taille("/var/cache/apt"))))
        return r.returncode

    def snap():
        vieux = _menage_snaps_desactives()
        n = 0
        for nom, rev in vieux:
            if subprocess.run(["snap", "remove", nom, "--revision=" + rev], capture_output=True, text=True, timeout=300).returncode == 0:
                n += 1
        lignes.append("snap : %d révision(s) désactivée(s) retirée(s) sur %d" % (n, len(vieux)))
        return 0 if n == len(vieux) else 1

    if op == "etat":
        pipo = sum(_menage_taille(d) for d in _menage_pip_dossiers())
        vieux = _menage_snaps_desactives()
        lignes += ["pip : %s" % _menage_mo(pipo),
                   "journal système : %s (on en garderait %s)" % (_menage_mo(_menage_journal_octets()), _MENAGE_JOURNAL_GARDE),
                   "apt : %s" % _menage_mo(_menage_taille("/var/cache/apt")),
                   "snap : %d révision(s) désactivée(s)%s" % (len(vieux), (" — " + ", ".join("%s r%s" % v for v in vieux)) if vieux else "")]
        return 0, "\n".join(lignes)
    etapes = {"pip": [pip], "journal": [journal], "apt": [apt], "snap": [snap], "tout": [pip, journal, apt, snap]}.get(op)
    if not etapes:
        return 1, "opération inconnue : %r" % op
    for f in etapes:
        try:
            rc = max(rc, f() or 0)
        except Exception as e:
            rc = 1; lignes.append("%s : %s" % (f.__name__, e))
    return rc, "\n".join(lignes)


# ── LA FLOTTE AU CATALOGUE (05-10) ────────────────────────────────────────────────────────
# Demandes du journal des agents restées sans voie : sessions SSH en échec qu'on ne pouvait ni lire ni
# effacer (alerte « session-c743.scope », 03-10), clés de flotte à régénérer et poser à la main (n°25,
# 33), cache des serveurs qui exigeait un redémarrage de Cassandra (n°25), état « hors ligne » périmé
# (n°33, 125-130), transfert de fichiers vers une machine sans shell libre (n°75). Drisse (05-10) :
# « il ne peut pas gérer la flotte, faut lui en donner les moyens tout comme à Cassandra ».
# Tout se fait hors cage, en root, par fonctions : aucun chemin local ni aucune commande ne viennent
# de la demande, sauf le chemin DISTANT d'un transfert (la machine distante est à nous) et un nom de
# fichier local confiné à _FLOTTE_DEPOT.

_FLOTTE_DEPOT = "/opt/cassandra/travail/flotte"
_FLOTTE_FICHIER_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._\-]{0,120}$")
_FLOTTE_MAX_OCTETS = 512 * 1024 * 1024


def _catalogue_machines() -> list:
    """Les machines SSH du registre de la Flotte (multiserver.json)."""
    try:
        return sorted(s.get("name") for s in (_ms_load() or []) if s.get("type") == "ssh" and s.get("name"))
    except Exception:
        return []


def _flotte_serveur(nom: str) -> dict:
    for s in _ms_load() or []:
        if s.get("name") == nom and s.get("type") == "ssh":
            return s
    return {}


def _flotte_est_windows(s: dict) -> bool:
    return str(s.get("os") or "").lower().startswith("win")


def _flotte_vider_cache():
    global _servers_cache, _server_ssh_dict_cache
    _servers_cache, _server_ssh_dict_cache = None, None


def _ssh_sessions(p: dict) -> tuple:
    """Les sessions de connexion d'Orion (logind) : liste, et nettoyage des sessions finies en échec,
    qui restent inscrites et rouvrent l'alerte « service en échec »."""
    op = str((p or {}).get("op") or "")
    if op == "liste":
        l = []
        for cmd, titre in ((["loginctl", "list-sessions", "--no-legend"], "SESSIONS (loginctl)"),
                           (["systemctl", "list-units", "session-*.scope", "--all", "--no-legend", "--no-pager"], "UNITÉS DE SESSION"),
                           (["ss", "-tnp", "state", "established", "( sport = :22 or dport = :22 )"], "CONNEXIONS SSH ÉTABLIES (ss)")):
            r = subprocess.run(cmd, capture_output=True, text=True, timeout=20)
            l.append("%s :\n%s" % (titre, (r.stdout or r.stderr or "").strip() or "(aucune)"))
        return 0, "\n\n".join(l)
    if op == "nettoyer":
        r = subprocess.run(["systemctl", "list-units", "session-*.scope", "--state=failed", "--no-legend", "--plain", "--no-pager"],
                           capture_output=True, text=True, timeout=20)
        echouees = [x.split()[0] for x in (r.stdout or "").splitlines() if x.strip().startswith("session-")]
        if not echouees:
            return 0, "aucune session en échec"
        r2 = subprocess.run(["systemctl", "reset-failed"] + echouees, capture_output=True, text=True, timeout=30)
        return r2.returncode, "effacées : %s%s" % (", ".join(echouees), ("\n" + r2.stderr.strip()) if r2.returncode else "")
    return 1, "opération inconnue : %r" % op


def _ssh_session(p: dict) -> tuple:
    """Une session : son détail, ou la fermer (déconnecte la personne ou l'agent qui l'occupe)."""
    op = str((p or {}).get("op") or "")
    sid = str((p or {}).get("id") or "")
    if not re.fullmatch(r"c?\d{1,7}", sid):
        return 1, "identifiant de session invalide : %r (ex. 277 ou c277)" % sid
    if op == "detail":
        r = subprocess.run(["loginctl", "session-status", sid, "--no-pager"], capture_output=True, text=True, timeout=20)
        return r.returncode, (r.stdout or r.stderr or "").strip()[-4000:]
    if op == "fermer":
        r = subprocess.run(["loginctl", "terminate-session", sid], capture_output=True, text=True, timeout=20)
        return r.returncode, "session %s fermée" % sid if r.returncode == 0 else (r.stderr or "").strip()
    return 1, "opération inconnue : %r" % op


def _flotte_tester(s: dict, timeout: int = 25) -> tuple:
    """(ok, détail) : une vraie connexion SSH avec l'identité du registre, une commande inoffensive."""
    cmd = "cmd /c echo flotte-ok" if _flotte_est_windows(s) else "echo flotte-ok"
    out, err, rc = _ms_ssh_exec(s, cmd, timeout=timeout)
    if rc == 0 and "flotte-ok" in (out or ""):
        return True, "SSH accepté (%s@%s, %s)" % (s.get("ssh_user"), s.get("ssh_host"), s.get("ssh_auth"))
    return False, " ".join(((err or "") + " " + (out or "")).split())[:300] or "code %s" % rc


def _flotte_catalogue(p: dict) -> tuple:
    """Une machine de la Flotte : sonde réelle, clé SSH neuve, cache des serveurs."""
    op = str((p or {}).get("op") or "")
    nom = str((p or {}).get("machine") or "")
    s = _flotte_serveur(nom)
    if not s:
        return 1, "machine inconnue du registre : %r" % nom
    host = s.get("ssh_host", "")
    if op == "sonde":
        l = []
        r = subprocess.run(["tailscale", "ping", "--c", "2", "--timeout", "5s", host], capture_output=True, text=True, timeout=20)
        l.append("tailscale ping : %s" % ((r.stdout or r.stderr or "").strip().splitlines() or ["?"])[-1])
        try:
            with socket.create_connection((host, int(s.get("ssh_port", 22))), timeout=6):
                l.append("port %s : ouvert" % s.get("ssh_port", 22))
        except Exception as e:
            l.append("port %s : FERMÉ (%s)" % (s.get("ssh_port", 22), e))
        ok, det = _flotte_tester(s)
        l.append("authentification : %s" % det)
        if ok and str(s.get("os") or "inconnu") == "inconnu":
            _sys = _flotte_os_detecter(s)
            if _sys:
                _flotte_os_retenir(nom, _sys)
                l.append("système détecté et retenu : %s" % _sys)
        # L'état affiché se recalcule tout de suite : plus de « hors ligne » périmé à attendre.
        _flotte_vider_cache()
        try:
            fleet_pass()
            l.append("état de la Flotte rafraîchi")
        except Exception as e:
            l.append("rafraîchissement de l'état impossible : %s" % e)
        return (0 if ok else 1), "\n".join(l)
    if op == "vider_cache":
        _flotte_vider_cache()
        return 0, "cache des serveurs vidé : multiserver.json sera relu au prochain appel (sans redémarrer Cassandra)"
    if op == "cle_neuve":
        return _flotte_cle_neuve(s)
    return 1, "opération inconnue : %r" % op


def _flotte_cle_neuve(s: dict) -> tuple:
    """Une paire ed25519 dédiée à cette machine. Si l'accès actuel marche, la clé publique est posée
    sur la machine, la nouvelle identité est ESSAYÉE, et seulement alors le registre bascule dessus
    (copie de sûreté de multiserver.json). Sinon : la clé publique et la ligne à poser, et l'identité
    neuve attend dans le registre (`ssh_key_attente`) ; une nouvelle « cle_neuve » l'essaiera."""
    import tempfile, shutil
    nom = s.get("name")
    attente = _ms_decrypt_token(s.get("ssh_key_attente", "")) if s.get("ssh_key_attente") else ""
    if attente:
        priv = attente
        pub = s.get("ssh_pub_attente", "")
    else:
        d = tempfile.mkdtemp(prefix="flotte-")
        try:
            k = os.path.join(d, "cle")
            r = subprocess.run(["ssh-keygen", "-q", "-t", "ed25519", "-N", "", "-C", "cassandra-flotte-%s" % nom, "-f", k],
                               capture_output=True, text=True, timeout=30)
            if r.returncode != 0:
                return 1, "ssh-keygen : %s" % r.stderr.strip()
            priv = open(k).read()
            pub = open(k + ".pub").read().strip()
        finally:
            shutil.rmtree(d, ignore_errors=True)
    essai = dict(s, ssh_auth="key", ssh_key=_ms_encrypt_token(priv))
    ok_neuve, _ = _flotte_tester(essai)
    pose = "déjà posée"
    if not ok_neuve:
        ok_actuel, det = _flotte_tester(s)
        if ok_actuel:
            if _flotte_est_windows(s):
                ps = ("$p=([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent())"
                      ".IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator);"
                      "if($p){$f='C:\\ProgramData\\ssh\\administrators_authorized_keys'}else{$f=Join-Path $env:USERPROFILE '.ssh\\authorized_keys';"
                      "New-Item -ItemType Directory -Force (Split-Path $f) | Out-Null};"
                      "if(-not (Test-Path $f) -or -not (Select-String -Path $f -SimpleMatch -Quiet '%s')){Add-Content -Path $f -Value '%s'};"
                      "if($p){icacls $f /inheritance:r /grant 'Administrators:F' /grant 'SYSTEM:F' | Out-Null};'pose:'+$f" % (pub, pub))
                cmd = 'powershell -NoProfile -NonInteractive -Command "%s"' % ps
            else:
                cmd = ("umask 077; mkdir -p ~/.ssh && touch ~/.ssh/authorized_keys && "
                       "(grep -qxF '%s' ~/.ssh/authorized_keys || echo '%s' >> ~/.ssh/authorized_keys) && "
                       "chmod 700 ~/.ssh && chmod 600 ~/.ssh/authorized_keys && echo pose:~/.ssh/authorized_keys" % (pub, pub))
            out, err, rc = _ms_ssh_exec(s, cmd, timeout=40)
            pose = (out or "").strip().splitlines()[-1] if rc == 0 and "pose:" in (out or "") else "échec de la pose : %s" % " ".join(((err or "") + (out or "")).split())[:200]
            ok_neuve, _ = _flotte_tester(essai)
        else:
            pose = "accès actuel refusé (%s)" % det
    servers = _ms_load()
    try:
        shutil.copy2(MULTISERVER_CONFIG_FILE, MULTISERVER_CONFIG_FILE + ".bak.%d" % int(time.time()))
    except Exception:
        pass
    ancienne = ""
    for x in servers:
        if x.get("name") != nom:
            continue
        if ok_neuve:
            if x.get("ssh_auth") == "key" and x.get("ssh_key"):
                ancienne = _aut_rot_corps_pub(_ms_decrypt_token(x.get("ssh_key", "")))
            x.update(ssh_auth="key", ssh_key=_ms_encrypt_token(priv), ssh_key_date=time.time())
            x.pop("ssh_key_attente", None); x.pop("ssh_pub_attente", None)
        else:
            x.update(ssh_key_attente=_ms_encrypt_token(priv), ssh_pub_attente=pub)
    _ms_save(servers)   # vide aussi le cache des serveurs
    if ok_neuve and ancienne and ancienne not in pub:
        # L'ancienne clé reste valide sur la machine pendant la garde (12 h par défaut) : si la neuve se révèle fautive,
        # la copie de sûreté du registre permet de revenir. Elle est retirée ensuite, après un essai de la neuve.
        try:
            _aut_rot_programmer(nom, ancienne)
            pose += ", ancienne clé retirée dans %g h" % float(_mem_cfg("rotation_garde_h", 12) or 12)
        except Exception as e:
            logging.warning("[ROTATION] retrait de l'ancienne clé de %s non programmé : %s", nom, e)
    if ok_neuve:
        return 0, "%s : clé neuve posée (%s), essayée et adoptée par le registre. Clé publique : %s" % (nom, pose, pub)
    ligne = ("Windows admin : ajouter la ligne à C:\\ProgramData\\ssh\\administrators_authorized_keys ; "
             "Windows : %%USERPROFILE%%\\.ssh\\authorized_keys ; Linux : ~/.ssh/authorized_keys")
    return 1, ("%s : la clé neuve n'ouvre pas encore la machine (%s). Elle attend dans le registre ; "
               "une fois la ligne posée sur la machine, relancer cle_neuve l'essaie et l'adopte.\n%s\nLigne : %s"
               % (nom, pose, ligne, pub))


def _aut_rot_corps_pub(priv: str) -> str:
    """Le corps (base64) de la clé publique d'une clé privée : de quoi retrouver sa ligne dans authorized_keys."""
    import paramiko as _pk, io as _io
    for K in (_pk.Ed25519Key, _pk.RSAKey, _pk.ECDSAKey):
        try:
            return K.from_private_key(_io.StringIO(priv)).get_base64()
        except Exception:
            continue
    return ""


_AUT_ROT_SQL = ("CREATE TABLE IF NOT EXISTS autonomie_rotations (id INTEGER PRIMARY KEY AUTOINCREMENT, machine TEXT, "
                "corps TEXT, echeance REAL, etat TEXT DEFAULT 'attente', note TEXT DEFAULT '', ts REAL)")
_AUT_ROT_CLE = "rotation-des-secrets/faire-tourner-une-cle-ssh"


def _aut_rot_programmer(machine: str, corps: str) -> None:
    garde = float(_mem_cfg("rotation_garde_h", 12) or 12) * 3600
    def _e(conn):
        conn.execute(_AUT_ROT_SQL)
        conn.execute("INSERT INTO autonomie_rotations (machine, corps, echeance, ts) VALUES (?,?,?,?)",
                     (machine, corps, time.time() + garde, time.time()))
    _aut_ecrire(_e)


def _aut_rot_retirer(s: dict, corps: str) -> tuple:
    """Retire de la machine la ligne de l'ancienne clé. Jamais un fichier vidé : on ne réécrit que s'il reste des lignes."""
    if not re.match(r"^[A-Za-z0-9+/=]{20,}$", corps or ""):
        return False, "corps de clé illisible"
    if _flotte_est_windows(s):
        ps = ("$b='%s';$r='';foreach($f in @('C:\\ProgramData\\ssh\\administrators_authorized_keys',(Join-Path $env:USERPROFILE '.ssh\\authorized_keys')))"
              "{if(Test-Path $f){$l=@(Get-Content $f);$k=@($l|Where-Object{$_ -notlike ('*'+$b+'*')});"
              "if($k.Count -gt 0 -and $k.Count -lt $l.Count){Set-Content -Path $f -Value $k -Encoding ascii;$r='retiree'}}};$r" % corps)
        cmd = 'powershell -NoProfile -NonInteractive -Command "%s"' % ps
    else:
        cmd = ("f=\"$HOME/.ssh/authorized_keys\"; grep -vF '%s' \"$f\" > \"$f.rot\"; "
               "if [ -s \"$f.rot\" ] && [ \"$(wc -l < \"$f.rot\")\" -lt \"$(wc -l < \"$f\")\" ]; then cat \"$f.rot\" > \"$f\"; echo retiree; fi; rm -f \"$f.rot\"" % corps)
    out, err, rc = _ms_ssh_exec(s, cmd, timeout=40)
    if rc != 0:
        return False, "retrait impossible : %s" % " ".join(((err or "") + (out or "")).split())[:160]
    return True, "ancienne clé retirée" if "retiree" in (out or "") else "l'ancienne clé n'y était déjà plus"


def aut_rotation_pass() -> dict:
    """Retire les anciennes clés SSH dont la garde est écoulée — APRÈS avoir essayé la neuve. Si la neuve ne répond pas,
    l'ancienne reste et on le dit : mieux vaut une clé de trop qu'une machine perdue."""
    now = time.time()
    try:
        def _lire(conn):
            conn.execute(_AUT_ROT_SQL)
            return [dict(r) for r in conn.execute("SELECT * FROM autonomie_rotations WHERE etat='attente' AND echeance <= ?", (now,)).fetchall()]
        dues = _aut_ecrire(_lire)
    except Exception as e:
        return {"ok": False, "reason": str(e)[:120]}
    faites = []
    for r in dues:
        s = _flotte_serveur(r["machine"])
        etat, note, ok = "faite", "", True
        if not s:
            etat, note, ok = "abandon", "machine retirée du registre", True
        else:
            ok_neuve, det = _flotte_tester(s)
            if not ok_neuve:
                etat, note, ok = "bloque", "la clé neuve ne répond pas (%s) : l'ancienne est gardée" % str(det)[:100], False
            else:
                ok, note = _aut_rot_retirer(s, r["corps"])
                etat = "faite" if ok else "bloque"
        def _e(conn, i=r["id"], et=etat, nt=note):
            conn.execute("UPDATE autonomie_rotations SET etat=?, note=? WHERE id=?", (et, nt, i))
        try:
            _aut_ecrire(_e)
        except Exception as e:
            logging.warning("[ROTATION] %s", e)
        eff = aut_effectif(_AUT_ROT_CLE)
        try:
            aut_journaliser(_AUT_ROT_CLE, r["machine"], ok, "retrait de l'ancienne clé après la garde", note, eff)
            if not ok:
                notif("Rotation de clé SSH : l'ancienne clé de %s est restée" % r["machine"], note, source="veille", niveau="avoir",
                      cle="aut:rotation:%s" % r["machine"])
        except Exception as e:
            logging.info("[ROTATION] journal : %s", e)
        faites.append({"machine": r["machine"], "etat": etat, "note": note})
    return {"ok": True, "traitees": faites}


def _detect_cles_ssh_anciennes() -> list:
    """Règle « Rotation des secrets › Faire tourner une clé SSH » : une clé de la Flotte plus vieille que le seuil
    (180 jours) est à faire tourner. Une clé sans date reçoit la date du jour : on part de maintenant, on n'invente rien."""
    seuil = int(_mem_cfg("cle_ssh_age_jours", 180) or 180)
    servers = _ms_load() or []
    now, datees, out = time.time(), False, []
    for sv in servers:
        if sv.get("type") != "ssh" or sv.get("ssh_auth") != "key" or not sv.get("ssh_key"):
            continue
        d = sv.get("ssh_key_date")
        if not d:
            sv["ssh_key_date"] = now; datees = True
            continue
        jours = int((now - float(d)) // 86400)
        if jours >= seuil:
            nom = str(sv.get("name") or "")
            out.append({"fkey": "ssh_cle_%s" % nom, "category": "flotte", "severity": "info",
                        "title": "Clé SSH de %s : %d jours sans changement" % (nom, jours),
                        "detail": "La clé dédiée à %s a %d jours (seuil %d). La neuve est posée et essayée avant d'être adoptée ; "
                                  "l'ancienne reste valide pendant la garde, puis est retirée." % (nom, jours, seuil),
                        "suggested_action": "rotation-cle-ssh %s" % nom, "action_kind": "ssh.rotation"})
    if datees:
        try:
            _ms_save(servers)
        except Exception as e:
            logging.warning("[ROTATION] dates de clés non écrites : %s", e)
    return out


def _flotte_fichier(p: dict) -> tuple:
    """Transfert SFTP entre le dépôt d'Orion (/opt/cassandra/travail/flotte) et une machine.
    Côté Orion, un NOM de fichier seul (pas de chemin) ; côté machine, le chemin voulu."""
    op = str((p or {}).get("op") or "")
    nom = str((p or {}).get("machine") or "")
    local = str((p or {}).get("local") or "")
    distant = str((p or {}).get("distant") or "")
    s = _flotte_serveur(nom)
    if not s:
        return 1, "machine inconnue du registre : %r" % nom
    if op in ("envoyer", "recuperer") and (not _FLOTTE_FICHIER_RE.match(local) or local in (".", "..")):
        return 1, "local : un nom de fichier seul est attendu (dépôt %s)" % _FLOTTE_DEPOT
    if "\x00" in distant or not distant.strip():
        return 1, "distant : chemin manquant"
    os.makedirs(_FLOTTE_DEPOT, mode=0o750, exist_ok=True)
    chemin = os.path.join(_FLOTTE_DEPOT, local)
    import paramiko as _pk, io as _io
    kw = {"hostname": s.get("ssh_host"), "port": int(s.get("ssh_port", 22)), "username": s.get("ssh_user", "root"),
          "timeout": 15, "banner_timeout": 15, "auth_timeout": 15, "look_for_keys": False}
    key_data = _ms_decrypt_token(s.get("ssh_key", ""))
    if s.get("ssh_auth") == "key" and key_data:
        for K in (_pk.Ed25519Key, _pk.RSAKey, _pk.ECDSAKey):
            try:
                kw["pkey"] = K.from_private_key(_io.StringIO(key_data)); break
            except Exception:
                continue
    else:
        kw["password"] = _ms_decrypt_token(s.get("ssh_pass", ""))
    c = _pk.SSHClient()
    c.set_missing_host_key_policy(_pk.AutoAddPolicy())
    try:
        c.connect(**kw)
        sftp = c.open_sftp()
        if op == "envoyer":
            if not os.path.isfile(chemin):
                return 1, "rien à envoyer : %s n'existe pas" % chemin
            if os.path.getsize(chemin) > _FLOTTE_MAX_OCTETS:
                return 1, "fichier trop gros (512 Mo au plus)"
            sftp.put(chemin, distant)
            return 0, "%s → %s:%s (%d octets)" % (chemin, nom, distant, sftp.stat(distant).st_size)
        if op == "recuperer":
            st = sftp.stat(distant)
            if st.st_size > _FLOTTE_MAX_OCTETS:
                return 1, "fichier distant trop gros (512 Mo au plus)"
            sftp.get(distant, chemin + ".partiel")
            os.replace(chemin + ".partiel", chemin)
            return 0, "%s:%s → %s (%d octets)" % (nom, distant, chemin, os.path.getsize(chemin))
        if op == "lister":
            return 0, "\n".join("%s%s  %d" % (a.filename, "/" if (a.st_mode or 0) & 0o040000 else "", a.st_size or 0)
                                for a in sorted(sftp.listdir_attr(distant), key=lambda a: a.filename)[:500])
        return 1, "opération inconnue : %r" % op
    except Exception as e:
        return 1, "%s : %s" % (type(e).__name__, e)
    finally:
        try:
            if os.path.exists(chemin + ".partiel"):
                os.unlink(chemin + ".partiel")
        except Exception:
            pass
        c.close()


# ── LE CATALOGUE S'ÉTEND DE LUI-MÊME (05-10, journal des agents n°115-116) ──────────────────
# Itare : « hors table fermée, je ne peux que proposer et attendre » — même pour un geste bénin et
# vérifié. Drisse (05-10) : oui, et sans dépendance humaine. Les agents étendent donc la table EUX-
# MÊMES, mais seulement par des DONNÉES dont la forme est déjà prévue : une unité systemd qui existe,
# un nom de conf dans une famille connue. Jamais une commande : une entrée qu'un agent écrirait en
# argv serait un shell root. Aucune extension ne part d'un tour teinté ; chacune est inscrite au
# journal des agents et notifiée — une trace, pas une attente.
_ETENDRE_UNITE = re.compile(r"^[a-zA-Z0-9_.@\-]{1,64}$")
_ETENDRE_REFUS = ("systemd-", "dbus", "getty", "user@", "init")


def _catalogue_etendre(p: dict) -> tuple:
    op = str((p or {}).get("op") or "")
    val = str((p or {}).get("valeur") or "").strip()
    try:
        orig = origine_courante() or {}
    except Exception:
        orig = {}
    qui = str(orig.get("acteur") or orig.get("origine") or "agent")
    if op != "liste" and (orig.get("teintes") or []):
        return 1, "refusé : ce tour a lu du contenu extérieur — une extension du catalogue part d'un tour propre"

    def _trace(titre, detail):
        try:
            journal_agents_ecrire(qui, "", "Catalogue étendu · " + titre, "", "", detail)
        except Exception as e:
            logging.info("[CATALOGUE] journal : %s", e)
        try:
            notif("Catalogue étendu par %s — %s" % (qui, titre), detail[:1500], source="catalogue",
                  niveau="info", nature="evenement", sujet=titre, cle="catalogue:etendre:" + titre)
        except Exception as e:
            logging.info("[CATALOGUE] notification : %s", e)

    if op == "liste":
        cfg = get_cassandra_config()
        return 0, ("Unités ajoutées par les agents (catalogue_services) : %s\nConfs approuvées : %s"
                   % (", ".join(cfg.get("catalogue_services") or []) or "aucune",
                      ", ".join(_conf_approuves()) or "aucune"))

    if op in ("service_ajouter", "service_retirer"):
        # 10-10 : Cassandra a voulu « redémarrer » session-c63.scope (une session sudo finie, marquée en échec) et
        # s'est vu conseiller de l'ajouter ici. Une session ou un scope n'est pas un service : l'ajouter ouvrirait
        # le catalogue aux connexions en cours. Elle s'efface, elle ne se redémarre pas.
        if val.startswith("session-") or val.endswith(".scope"):
            return 1, ("« %s » est une session de connexion, pas un service : elle ne se redémarre pas. Finie en échec, "
                       "elle s'efface par catalogue(nom='ssh_sessions', params={op:'nettoyer'})." % val[:64])
        if not _ETENDRE_UNITE.match(val) or val.startswith(_ETENDRE_REFUS):
            return 1, "unité refusée : %r" % val[:64]
        cfg = get_cassandra_config()
        extra = [str(x) for x in (cfg.get("catalogue_services") or [])]
        if op == "service_ajouter":
            if val in _catalogue_services():
                return 0, "%s est déjà au catalogue" % val
            r = subprocess.run(["systemctl", "cat", val], capture_output=True, text=True, timeout=20)
            if r.returncode != 0:
                return 1, "aucune unité systemd « %s » sur cette machine" % val
            extra.append(val)
        else:
            if val not in extra:
                return 1, "%s n'a pas été ajouté par un agent (la table de base ne se retire pas)" % val
            extra.remove(val)
        cfg["catalogue_services"] = extra
        if not save_cassandra_config(cfg):
            return 1, "config.json n'a pas pu être écrit"
        verbe = "ajoutée" if op == "service_ajouter" else "retirée"
        _trace("unité %s %s" % (val, verbe), "Unité « %s » %s aux entrées service et journal du catalogue." % (val, verbe))
        if op == "service_ajouter":
            return 0, "unité %s ajoutée : service(op, unite=%s) et journal(unite=%s) l'acceptent" % (val, val, val)
        return 0, "unité %s retirée : service et journal ne l'acceptent plus" % val

    if op == "conf_approuver":
        if "/" not in val:
            return 1, "valeur attendue : famille/nom.conf (familles : %s)" % ", ".join(_CONF_CIBLES)
        fam, nom = val.split("/", 1)
        if fam not in _CONF_CIBLES or not _CONF_NOM.match(nom):
            return 1, "famille ou nom refusé : %r (familles : %s)" % (val[:80], ", ".join(_CONF_CIBLES))
        brouillon = os.path.join(_PROV_DOSSIER, fam, nom)
        if not os.path.isfile(brouillon) or os.path.islink(brouillon):
            return 1, "pas de brouillon %s — écris-le d'abord dans la cage" % brouillon
        propre, motif = _conf_provenance(brouillon)
        if not propre:
            return 1, "brouillon refusé — %s" % motif
        dst_dir = os.path.join(_CONF_APPROUVE, fam)
        os.makedirs(dst_dir, mode=0o755, exist_ok=True)
        dst = os.path.join(dst_dir, nom)
        ancien = open(dst, encoding="utf-8", errors="replace").read().splitlines() if os.path.isfile(dst) else []
        contenu = open(brouillon, "rb").read()
        tmp = dst + ".tmp"
        with open(tmp, "wb") as fh:
            fh.write(contenu)
        os.chown(tmp, 0, 0)
        os.chmod(tmp, 0o440)
        os.replace(tmp, dst)
        if val not in _conf_approuves():
            return 1, "approbation écrite mais non reconnue par la table — à voir"
        import difflib
        d = "\n".join(list(difflib.unified_diff(ancien, contenu.decode("utf-8", "replace").splitlines(),
                                                "approuvé avant", "approuvé", lineterm=""))[:80])
        _trace("conf %s approuvée" % val, "Nom approuvé par l'agent (brouillon %s). Diff :\n%s" % (motif, d or "(nouveau fichier)"))
        return 0, "%s approuvé — conf(op=poser, fichier=%s) le pose maintenant (test, reload, retour arrière)" % (val, val)

    return 1, "opération inconnue : %r (liste, service_ajouter, service_retirer, conf_approuver)" % op


# LE MANDAT DE CASSANDRA (journal des agents n°116, accord de Drisse) : les fermetures réversibles et
# non destructrices de l'onglet Sécurité, sans attendre l'accord à chaque fois. Mêmes gestes, mêmes
# gardes (ssh_mdp refuse sans clé posée), même journal d'administration. Le pare-feu reste à l'écran :
# son filet de deux minutes attend un « Garder » humain.
_SEC_CATALOGUE = {"ssh_mdp": "ssh_mdp", "ssh_x11": "ssh_x11", "mysql_local": "mysql_local",
                  "arret_rpcbind": "arret:rpcbind", "arret_avahi": "arret:avahi-daemon", "arret_cups": "arret:cups",
                  "maj_securite": "maj_securite", "maj_auto": "maj_auto"}


def _securite_catalogue(p: dict) -> tuple:
    op = str((p or {}).get("op") or "")
    g = _SEC_CATALOGUE.get(op)
    if not g:
        return 1, "geste inconnu : %r" % op
    try:
        qui = str((origine_courante() or {}).get("acteur") or "agent")
    except Exception:
        qui = "agent"
    r = securite_geste({"geste": g}, "", qui)
    return (0 if r.get("ok") else 1), json.dumps(r, ensure_ascii=False, default=str)[:3000]


def _parefeu_catalogue(p: dict) -> tuple:
    import shutil
    op = str((p or {}).get("op") or "")
    port = str((p or {}).get("port") or "")
    proto = str((p or {}).get("proto") or "TCP").lower()

    if op == "etat":
        # LE NOYAU, ENTIER (09-10) : INPUT seul ne montrait ni les sous-chaînes ni l'accord avec FastPanel.
        _SEC_CACHE["d"] = None
        return 0, pf_noyau_texte()

    if op in ("fermer", "ouvrir", "restreindre") and _fp_db_path():
        # PAR FASTPANEL (09-10) : une règle posée à côté de lui n'existe ni dans son écran ni après un
        # redémarrage. Même chemin, mêmes gardes et même filet de deux minutes que l'onglet Sécurité.
        if not port.isdigit() or not (1 <= int(port) <= 65535):
            return 1, "port invalide"
        pr = {"tcp": "TCP", "udp": "UDP", "all": "ALL"}.get(proto)
        if not pr:
            return 1, "protocole invalide (TCP, UDP ou ALL)"
        etat = _sec_fp_parefeu_api()
        if not etat["ok"]:
            return 1, "API de FastPanel injoignable (%s) : rien n'a été posé" % (etat["erreur"] or "?")
        sources = str((p or {}).get("sources") or "")
        if op == "ouvrir":
            a_retirer = [r for r in etat["regles"] if _sec_pf_couvre(r, int(port), pr) and str(r.get("policy")) in ("DROP", "PARTIAL_DROP")]
            if a_retirer:
                res = [securite_pf_geste("regle_retirer", {"id": r.get("id")}) for r in a_retirer]
            else:
                res = [securite_pf_geste("regle_poser", {"nom": "Cassandra ouvre %s %s" % (port, pr), "ports": port,
                                                         "proto": pr, "sens": "INPUT", "politique": "ACCEPT"})]
        else:
            res = [securite_pf_geste("regle_poser", {
                "nom": ("Cassandra restreint %s %s" if op == "restreindre" else "Cassandra ferme %s %s") % (port, pr),
                "ports": port, "proto": pr, "sens": "INPUT", "sources": sources,
                "politique": "PARTIAL_ACCEPT" if op == "restreindre" else "DROP"})]
        rates = [r.get("error") for r in res if not r.get("ok")]
        if rates:
            return 1, "refusé : " + "; ".join(filter(None, rates))
        essais = [r["essai"] for r in res if r.get("essai")]
        _SEC_CACHE["d"] = None
        logging.info("[PAREFEU] %s %s/%s par FastPanel (%d essai(s))", op, port, pr, len(essais))
        return 0, ("Posé dans FastPanel. %s\n\n%s" % (
            ("À L'ESSAI : se défait seul dans deux minutes si l'administrateur ne clique pas « Garder » "
             "dans Sécurité › Pare-feu." if essais else "Réglage définitif."), pf_noyau_texte()))

    elif op == "lister":
        r = _sys_run(["ss", "-tulpn"], timeout=10)
        return (0 if r.get("ok") else 1), r.get("output") or r.get("error")

    elif op in ("fermer", "ouvrir"):
        if not port.isdigit() or not (1 <= int(port) <= 65535):
            return 1, "port invalide"
        if proto not in ("tcp", "udp"):
            return 1, "protocole invalide (TCP ou UDP)"

        has_ufw = shutil.which("ufw")
        if op == "fermer":
            # LE RÉSULTAT SE LIT (09-10) : « fermé » s'annonçait même quand la commande avait échoué.
            if has_ufw:
                r = _sys_run(["ufw", "deny", port + "/" + proto], timeout=10)
            else:
                r = _sys_run(["iptables", "-I", "INPUT", "-p", proto, "--dport", port, "-j", "DROP"], timeout=10)
            if not r.get("ok"):
                return 1, "échec : %s" % (r.get("output") or r.get("error") or "?")[-300:]
            logging.info("[PAREFEU] port %s/%s fermé", port, proto)
            return 0, "port %s/%s fermé (règle %s, non gardée au redémarrage sans iptables-persistent)\n\n%s" % (
                port, proto.upper(), "ufw" if has_ufw else "iptables", pf_noyau_texte())
        else:
            if has_ufw:
                _sys_run(["ufw", "delete", "deny", port + "/" + proto], timeout=10)
            else:
                while True:
                    r = _sys_run(["iptables", "-D", "INPUT", "-p", proto, "--dport", port, "-j", "DROP"], timeout=10)
                    if not r.get("ok"):
                        break
            logging.info("[PAREFEU] port %s/%s ouvert", port, proto)
            return 0, "port %s/%s ouvert" % (port, proto.upper())

    return 1, "op inconnu : %r" % op


# UN NOM DE PAQUET, JAMAIS UNE OPTION. apt-get lit « -o… » comme une option : une option
# Pre-Invoke exécute n'importe quoi en root. Le motif ferme la porte avant l'argv, et « -- » la
# ferme une seconde fois.
_PAQUET_NOM = re.compile(r"[a-z0-9][a-z0-9+.\-]{0,99}(:[a-z0-9]+)?")
_PAQUETS_PROTEGES = ("openssh-server", "openssh-client", "systemd", "systemd-sysv", "python3", "sudo",
                     "apt", "dpkg", "tailscale", "bash", "coreutils", "libc6", "nginx", "init")


def _paquet_catalogue(p: dict) -> tuple:
    op = str((p or {}).get("op") or "")
    nom = str((p or {}).get("nom") or "").strip().lower()
    if not _PAQUET_NOM.fullmatch(nom):
        return 1, "nom de paquet invalide : lettres minuscules, chiffres, + . - (100 au plus)"
    env = ["env", "DEBIAN_FRONTEND=noninteractive"]
    if op == "installer":
        r = _sys_run(env + ["apt-get", "install", "-y", "--", nom], timeout=600)
        return (0 if r.get("ok") else 1), r.get("output") or r.get("error")
    if op != "retirer":
        return 1, "op inconnu : %r" % op
    if nom in _PAQUETS_PROTEGES or nom.startswith(("linux-image", "linux-headers", "openssh", "python3.")):
        return 1, "%s est protégé : son retrait couperait la machine ou Cassandra" % nom
    q = _sys_run(["dpkg-query", "-W", "-f=${Essential} ${Priority}", "--", nom], timeout=20)
    if not q.get("ok"):
        return 1, "%s n'est pas installé" % nom
    if (q.get("output") or "").split()[:1] == ["yes"] or any(w in (q.get("output") or "") for w in ("required", "important")):
        return 1, "%s est un paquet essentiel du système : refusé" % nom
    s = _sys_run(["apt-get", "-s", "remove", "--", nom], timeout=60)
    emportes = [l.split()[1] for l in (s.get("output") or "").splitlines() if l.startswith("Remv ")]
    if len(emportes) > 6:
        return 1, "retrait refusé : il emporterait %d paquets (%s…)" % (len(emportes), ", ".join(emportes[:8]))
    r = _sys_run(env + ["apt-get", "remove", "-y", "--", nom], timeout=600)
    return (0 if r.get("ok") else 1), r.get("output") or r.get("error")


def _reboot_catalogue(p: dict) -> tuple:
    try:
        up = float(open("/proc/uptime").read().split()[0])
    except Exception:
        up = 0.0
    if up < 1800:
        return 1, "refusé : la machine a redémarré il y a %d min (30 min au moins entre deux redémarrages)" % (up // 60)
    logging.warning("[REBOOT] redémarrage de l'hôte demandé par %s", (origine_courante() or {}).get("acteur") or "agent")
    r = _sys_detache("reboot", "sleep 5\nsystemctl reboot\n")
    return (0 if r.get("ok") else 1), ("redémarrage de l'hôte dans 5 s" if r.get("ok") else r.get("error"))


