# LA LISTE MONTRÉE AU MODÈLE SUIT LA TABLE. L'énumération du schéma `catalogue` était écrite à la main
# et avait pris du retard (reglage, reseau absents : le modèle ne pouvait pas les choisir). Elle se
# recalcule ici, une fois la table connue ; la description nomme les entrées ajoutées depuis.
def _catalogue_schema_suivre():
    for t in CASSANDRA_TOOLS:
        f = t.get("function") or {}
        if f.get("name") != "catalogue":
            continue
        props = f["parameters"]["properties"]
        props["nom"]["enum"] = ["liste"] + list(_CATALOGUE)
        marque = " Aussi : "
        base = f["description"].split(marque)[0]
        nouveaux = [n for n in _CATALOGUE if ("%s(" % n) not in base and (" %s " % n) not in base and ("· %s" % n) not in base]
        if nouveaux:
            f["description"] = base + marque + " · ".join(
                "%s(%s)" % (n, ", ".join(_CATALOGUE[n]["params"])) for n in nouveaux) +                 ". Le détail de chaque entrée : catalogue(nom='liste')."


_catalogue_schema_suivre()


def catalogue_liste() -> list:
    """Ce que le modèle peut demander, avec les valeurs admises — rien d'autre."""
    out = []
    for nom, e in _CATALOGUE.items():
        ps = {}
        for k, v in e["params"].items():
            if isinstance(v, dict) and v.get("libre"):
                ps[k] = "(texte libre, %d signes au plus)" % v.get("max", 4000)
            elif isinstance(v, dict) and v.get("entier"):
                ps[k] = "(entier entre %d et %d)" % (v.get("min", 0), v.get("max", 2 ** 31))
            else:
                w = v() if callable(v) else v
                ps[k] = sorted(w.keys()) if isinstance(w, dict) else list(w)
        out.append({"nom": nom, "quoi": e["quoi"], "params": ps})
    return out


def catalogue_argv(nom: str, params: dict) -> tuple:
    """(argv, erreur). Un paramètre absent de la table est une erreur, jamais
    une chaîne qu'on passerait quand même."""
    e = _CATALOGUE.get(nom)
    if not e:
        return None, "entrée inconnue du catalogue : %r" % nom
    params = params or {}
    argv = []
    if e.get("fonction"):
        # UNE FONCTION, PAS UN PROCESSUS. Le texte libre est borné en taille ;
        # ce qui le borne en EFFETS, c'est la fonction (et son compte).
        argv.append("python:" + e["fonction"])
        for k, spec in e["params"].items():
            val = str(params.get(k, "") or "")
            if not val.strip():
                if k in e.get("facultatifs", ()):
                    argv.append("")
                    continue
                return None, "paramètre %r manquant" % k
            if isinstance(spec, dict) and spec.get("libre"):
                if len(val) > spec.get("max", 4000):
                    return None, "%s : trop long (%d signes au plus)" % (k, spec.get("max", 4000))
                if "\x00" in val:
                    return None, "%s : caractère nul" % k
                argv.append(val)
            elif isinstance(spec, dict) and spec.get("entier"):
                v = val.strip()
                lo, hi = spec.get("min", 0), spec.get("max", 2 ** 31)
                if not v.isdigit() or not (lo <= int(v) <= hi):
                    return None, "%s : entier attendu entre %d et %d" % (k, lo, hi)
                argv.append(v)
            else:
                v = val.strip()
                admis = spec() if callable(spec) else spec
                if v not in admis:
                    return None, ("%s=%r n'est pas admis (admis : %s)%s"
                                  % (k, v[:40], ", ".join(sorted(admis)) or "rien",
                                     ("\n" + e["aide"]) if e.get("aide") else ""))
                argv.append(v)
        for k in params:
            if k not in e["params"]:
                return None, "paramètre %r non prévu" % k
        return argv, None
    for tok in e["argv"]:
        if tok.startswith("{") and tok.endswith("}"):
            k = tok[1:-1]
            spec = e["params"].get(k)
            val = str(params.get(k, "")).strip()
            if spec is None:
                return None, "paramètre %r non prévu" % k
            # L'aide de l'entrée s'ajoute au refus : c'est elle qui dit le geste
            # humain à demander — et c'est sur elle que le centre de notifications
            # se déclenche quand personne ne lit la réponse.
            _aide = ("\n" + e["aide"]) if e.get("aide") else ""
            if isinstance(spec, dict):
                if val not in spec:
                    return None, "%s=%r n'est pas admis (admis : %s)%s" % (k, val, ", ".join(sorted(spec)), _aide)
                argv += list(spec[val])
            else:
                admis = spec()
                if val not in admis:
                    return None, "%s=%r n'est pas admis (admis : %s)%s" % (k, val[:40], ", ".join(sorted(admis)), _aide)
                # une table rend ses jetons, une liste rend la valeur elle-même
                argv += list(admis[val]) if isinstance(admis, dict) else [val]
        else:
            argv.append(tok)
    for k in params:
        if k not in e["params"]:
            return None, "paramètre %r non prévu" % k
    return argv, None


_REGLAGE_SECRET = re.compile(r"(pass|secret|token|jeton|key|cle_|clé|mdp|hash|salt|credential|api_)", re.I)


def _reglage_lecture(params: dict):
    """Une clé de la configuration, ou la liste des clés (« liste » / « * »).
    Un nom qui sent le secret rend un masque, jamais la valeur : le vérificateur
    lit le réglage qu'on vient de basculer, pas les clés du coffre."""
    cle = str((params or {}).get("cle") or "").strip()
    if not re.fullmatch(r"[A-Za-z0-9_.\-]{1,80}|\*", cle):
        return 1, "clé invalide : lettres, chiffres, _ . - (80 au plus), ou « liste »"
    try:
        cfg = get_cassandra_config() or {}
    except Exception as e:
        return 1, "configuration illisible : %s" % e
    if cle in ("liste", "*"):
        lignes = []
        for k in sorted(cfg.keys()):
            lignes.append("%s = %s" % (k, "•••• (secret)" if _REGLAGE_SECRET.search(k) else json.dumps(cfg[k], ensure_ascii=False)[:120]))
        return 0, "\n".join(lignes) or "(configuration vide)"
    if _REGLAGE_SECRET.search(cle):
        return 0, "%s = •••• (secret : présent, non lisible)" % cle if cle in cfg else "%s = (absent)" % cle
    if cle not in cfg:
        return 0, "%s = (absent — la valeur par défaut du code s'applique)" % cle
    return 0, "%s = %s" % (cle, json.dumps(cfg[cle], ensure_ascii=False)[:2000])


def catalogue_executer(nom: str, params: dict, timeout: int = 600) -> dict:
    """Exécute une entrée du catalogue, en root, en argv direct, sous veto.
    L'argv est construit ici et lancé tel quel : il n'y a aucun entre-deux où
    le texte pourrait changer. C'est la seule fonction de tout le fichier qui
    lance quelque chose avec de vrais droits."""
    argv, err = catalogue_argv(nom, params)
    if err:
        # À QUI DEMANDE-T-ELLE ? Dans une session de chat, à la personne qui lit.
        # Seule (proactif, horaire, Telegram), personne ne lit sa réponse : le
        # refus qui exige un geste humain part au centre de notifications, qui
        # sait joindre l'usager par ses canaux.
        _aide = (_CATALOGUE.get(nom) or {}).get("aide")
        if _aide and _aide in err:
            try:
                if origine_courante().get("origine") != "chat":
                    # Une unité à relancer : la ligne se ferme seule quand l'unité tourne (07-10).
                    _u = str((params or {}).get("unite") or "")
                    notif("Cassandra attend un geste de ta part — catalogue %s" % nom,
                          "Paramètres : %s\n\n%s" % (json.dumps(params, ensure_ascii=False)[:300], _aide),
                          source="catalogue", niveau="avoir", sujet=nom,
                          sonde=("service:%s" % _u) if (_u and str((params or {}).get("op") or "") in
                                                         ("restart", "start", "reload")) else "")
            except Exception as _e:
                logging.info("[CATALOGUE] notification impossible : %s", _e)
        return {"ok": False, "error": err}
    ligne = " ".join(argv)
    v = veto_root(ligne)
    if v:
        _cage_journal("catalogue", nom, ligne, -1, 0, 0, "veto : " + v)
        return {"ok": False, "error": "⛔ Geste interdit — %s" % v}
    e = _CATALOGUE[nom]
    if e.get("fonction"):
        fn = globals().get(e["fonction"])
        t0 = time.time()
        try:
            rc, out = fn(dict(zip(e["params"].keys(), argv[1:]))) if callable(fn) else (1, "fonction absente")
        except Exception as ex:
            rc, out = 1, "❌ %s" % ex
        out, nred = courtier_sortie(out or "")
        _cage_journal("catalogue", nom, ligne, rc, int((time.time() - t0) * 1000), nred, "")
        return {"ok": rc == 0, "rc": rc, "sortie": out[:6000], "commande": ligne}
    a = [_CAGE_BIN, "--quiet", "--wait", "--collect", "--pipe", "-p", "TimeoutStartSec=0",
         "-p", "ProtectHome=read-only", "-p", "NoNewPrivileges=yes"]
    if not e.get("reseau"):
        a += ["-p", "IPAddressDeny=any"]
        for m in _cage_maison():
            a += ["-p", "IPAddressAllow=" + m]
    a += ["--setenv=PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin",
          "--setenv=DEBIAN_FRONTEND=noninteractive", "--"] + argv
    t0 = time.time()
    try:
        r = subprocess.run(a, capture_output=True, text=True, timeout=timeout)
        out = (r.stdout or "") + (r.stderr or "")
        rc = r.returncode
    except subprocess.TimeoutExpired:
        out, rc = "⏱️ délai dépassé (%ds)" % timeout, 124
    except Exception as ex:
        out, rc = "❌ %s" % ex, 1
    out, nred = courtier_sortie(out)
    _cage_journal("catalogue", nom, ligne, rc, int((time.time() - t0) * 1000), nred, "")
    return {"ok": rc == 0, "rc": rc, "sortie": out[:6000], "commande": ligne}


def _cage_journal(mode: str, teinte, commande: str, rc: int, duree_ms: int,
                  redactions: int, motif: str) -> None:
    """Tout ce qui tourne en cage ou par le catalogue laisse une ligne : la
    commande ENTIÈRE (le registre précédent tronquait à 300 signes, et deux
    refus sur quatre n'étaient plus analysables), son empreinte, son code de
    retour, sa durée, et ce que le courtier a retiré."""
    conn = None
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        conn.execute("CREATE TABLE IF NOT EXISTS cage_journal ("
                     "id INTEGER PRIMARY KEY AUTOINCREMENT, ts TEXT DEFAULT (datetime('now')), "
                     "mode TEXT, teinte TEXT, empreinte TEXT, commande TEXT, rc INTEGER, "
                     "duree_ms INTEGER, redactions INTEGER, motif TEXT)")
        try:
            conn.execute("ALTER TABLE cage_journal ADD COLUMN acteur TEXT DEFAULT ''")
        except Exception:
            pass
        try:
            _act = str(origine_courante().get("acteur") or "")[:80]
        except Exception:
            _act = ""
        conn.execute("INSERT INTO cage_journal (mode, teinte, empreinte, commande, rc, duree_ms, redactions, motif, acteur) "
                     "VALUES (?,?,?,?,?,?,?,?,?)",
                     (mode, str(teinte), hashlib.sha256(commande.encode("utf-8", "replace")).hexdigest()[:16],
                      commande[:8192], rc, duree_ms, redactions, motif[:300], _act))
        conn.execute("DELETE FROM cage_journal WHERE id NOT IN (SELECT id FROM cage_journal ORDER BY id DESC LIMIT 5000)")
        conn.commit()
    except Exception:
        pass
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


# ══ LA PROVENANCE DES BROUILLONS ═══════════════════════════════════════════════
#  Qui a écrit ce fichier, et dans quel tour ? La cage ne sait pas ce qu'une
#  commande touche ; mais le dossier des brouillons est minuscule, et le
#  comparer avant/après chaque commande dit exactement quels fichiers ont
#  changé. On inscrit chacun avec l'empreinte de son contenu et la teinte du
#  tour. C'est une constatation, jamais une déclaration.
_PROV_DOSSIER = CASSANDRA_APP_DIR + "/travail/conf"


def _prov_etat() -> dict:
    out = {}
    try:
        for fam in os.listdir(_PROV_DOSSIER):
            d = os.path.join(_PROV_DOSSIER, fam)
            if not os.path.isdir(d):
                continue
            for nom in os.listdir(d):
                p = os.path.join(d, nom)
                try:
                    st = os.stat(p)
                except Exception:
                    continue
                if os.path.isfile(p):
                    out[p] = (st.st_mtime_ns, st.st_size)
    except Exception:
        pass
    return out


def _prov_sha(chemin: str) -> str:
    try:
        with open(chemin, "rb") as fh:
            return hashlib.sha256(fh.read()).hexdigest()
    except Exception:
        return ""


def _prov_enregistrer(avant: dict, apres: dict, teinte, cmd: str) -> int:
    """Inscrit chaque brouillon créé ou modifié par la commande qui vient de
    tourner. Rend le nombre d'inscriptions."""
    touches = [p for p, v in apres.items() if avant.get(p) != v]
    if not touches:
        return 0
    conn = None
    n = 0
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        conn.execute("CREATE TABLE IF NOT EXISTS brouillons_provenance ("
                     "id INTEGER PRIMARY KEY AUTOINCREMENT, ts TEXT DEFAULT (datetime('now')), "
                     "chemin TEXT, sha256 TEXT, teinte INTEGER, empreinte TEXT)")
        for p in touches:
            conn.execute("INSERT INTO brouillons_provenance (chemin, sha256, teinte, empreinte) VALUES (?,?,?,?)",
                         (p, _prov_sha(p), int(teinte) if isinstance(teinte, int) else (1 if teinte else 0),
                          hashlib.sha256(cmd.encode("utf-8", "replace")).hexdigest()[:16]))
            n += 1
        conn.execute("DELETE FROM brouillons_provenance WHERE id NOT IN "
                     "(SELECT id FROM brouillons_provenance ORDER BY id DESC LIMIT 2000)")
        conn.commit()
    except Exception as e:
        logging.warning("[PROVENANCE] inscription : %s", e)
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass
    return n


# ══ LA TEINTE DU FIL ═══════════════════════════════════════════════════════════
#  Le tour finit, mais l'historique reste : ce qu'un outil de lecture a fait
#  entrer dans la conversation y est encore au tour suivant. La teinte
#  s'inscrit donc avec la session, et se relit au début de chaque tour.
def _fil_teinte_lire(session_id: str) -> list:
    if not session_id:
        return []
    conn = None
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        conn.execute("CREATE TABLE IF NOT EXISTS fil_teintes (id INTEGER PRIMARY KEY AUTOINCREMENT, "
                     "ts TEXT DEFAULT (datetime('now')), session_id TEXT, outil TEXT)")
        return [x[0] for x in conn.execute(
            "SELECT DISTINCT outil FROM fil_teintes WHERE session_id=? ORDER BY outil", (session_id,))]
    except Exception as e:
        logging.warning("[TEINTE] lecture du fil : %s", e)
        return []
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


def _fil_teinte_ecrire(session_id: str, outils) -> int:
    if not session_id or not outils:
        return 0
    deja = set(_fil_teinte_lire(session_id))
    neufs = [str(o)[:60] for o in outils if str(o)[:60] not in deja]
    if not neufs:
        return 0
    conn = None
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        conn.executemany("INSERT INTO fil_teintes (session_id, outil) VALUES (?,?)",
                         [(session_id, o) for o in neufs])
        conn.execute("DELETE FROM fil_teintes WHERE ts < datetime('now','-7 days')")
        conn.commit()
        return len(neufs)
    except Exception as e:
        logging.warning("[TEINTE] inscription du fil : %s", e)
        return 0
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


def _conf_provenance(chemin: str) -> tuple:
    """(propre, motif). Propre si l'empreinte ACTUELLE du fichier a été écrite
    par un tour propre et par aucun tour teinté — un tour teinté qui n'a fait
    que toucher un contenu déjà là compte comme l'avoir écrit."""
    sha = _prov_sha(chemin)
    if not sha:
        return False, "brouillon illisible"
    conn = None
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        rows = conn.execute("SELECT teinte FROM brouillons_provenance WHERE chemin=? AND sha256=?",
                            (chemin, sha)).fetchall()
    except Exception as e:
        return False, "registre de provenance illisible : %s" % e
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass
    if not rows:
        return False, "aucune provenance connue pour ce contenu (écrit hors de la cage ?)"
    if any(int(t[0] or 0) == 2 for t in rows):
        return False, ("ce contenu a été écrit par un agent INVITÉ — ce qu'il a lu de son côté est "
                       "invisible d'ici, sa provenance ne peut pas être constatée. Il reste la voie "
                       "humaine : `cassandra-approuver`, le diff sous les yeux")
    if any(int(t[0] or 0) for t in rows):
        return False, ("ce contenu a été écrit ou touché dans un tour TEINTÉ — un contenu extérieur a été lu "
                       "dans ce tour, ou plus tôt dans cette conversation. La voie propre est une "
                       "conversation NEUVE, où ce contenu n'est plus dans le contexte")
    return True, "écrit par un tour propre"


def cage_stats() -> dict:
    """Ce que l'écran « Esprits » et l'audit affichent : par mode, puis les
    trente dernières lignes. Même forme que l'ancien registre, pour que
    l'écran n'ait rien à réapprendre."""
    out = {"by_kind": [], "recent": []}
    conn = None
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        conn.row_factory = sqlite3.Row
        for x in conn.execute("SELECT mode AS action_kind, COUNT(*) n, SUM(motif LIKE 'veto%') f, "
                              "SUM(motif NOT LIKE 'veto%') a FROM cage_journal GROUP BY mode ORDER BY n DESC"):
            out["by_kind"].append(dict(x))
        for x in conn.execute("SELECT ts, mode, commande, rc, motif FROM cage_journal ORDER BY id DESC LIMIT 30"):
            veto = (x["motif"] or "").startswith("veto")
            out["recent"].append({"ts": x["ts"], "action_kind": x["mode"],
                                  "decision": "REFUSE" if veto else "AUTORISE",
                                  "reason": x["motif"] if veto else
                                  "rc=%s · %s" % (x["rc"], (x["commande"] or "")[:90])})
    except Exception as e:
        out["error"] = str(e)
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass
    return out


def _catalogue_impl(args: dict) -> tuple:
    nom = str((args or {}).get("nom") or "").strip()
    params = (args or {}).get("params") or {}
    if not isinstance(params, dict):
        params = {}
    if nom == "liste":
        # LA DÉCOUVERTE. Sans elle, Cassandra allait chercher les valeurs admises
        # dans son propre code source (dix-sept commandes pour une conf).
        lignes = []
        for e in catalogue_liste():
            ps = " · ".join("%s=%s" % (k, v if isinstance(v, str) else "|".join(map(str, v)) or "(rien)")
                            for k, v in e["params"].items()) or "(sans paramètre)"
            lignes.append("%s — %s\n    %s" % (e["nom"], e["quoi"], ps))
        return (True, "\n".join(lignes), "#7bd88f")
    r = catalogue_executer(nom, params)
    if not r.get("ok"):
        return (False, r.get("error") or ("rc=%s\n%s" % (r.get("rc"), r.get("sortie", "")))[:3000], "#e0564a")
    return (True, "✓ %s\n%s" % (r.get("commande", nom), r.get("sortie", "")[:3000]), "#7bd88f")


# ══════════════════════════════════════════════════════════════════════════════
#  LE CANAL DESK — le bureau des utilisateurs, séparé du catalogue-root
#
#  Décision actée (journal des agents, arbitrage desk) : un canal DISTINCT du
#  catalogue. Le catalogue reste l'unique voie vers root ; le desk ne touche
#  qu'aux espaces des utilisateurs sous /mnt/desk/<user>/. Garde-fous propres :
#    · confinement strict : chaque chemin est résolu (realpath) puis vérifié
#      sous /mnt/desk/<user>/ — jamais /, /etc, ni un chemin système ;
#    · identifiants réseau (CIFS…) au coffre, par {{secret:NOM}}, jamais en clair ;
#    · dry-run obligatoire avant toute copie (rsync) ;
#    · --delete et tout montage exigent une confirmation explicite.
#  Exécution HORS cage, en root (comme _reseau_catalogue) : le desk a besoin du
#  réseau vers la flotte, que la cage refuse par construction.
# ══════════════════════════════════════════════════════════════════════════════

_DESK_RACINE = "/mnt/desk"
_DESK_USER = re.compile(r"^[a-z0-9][a-z0-9._-]{0,31}$")
_DESK_TYPES = ("nfs", "cifs", "sshfs")
_DESK_RSYNC_EXCLU = re.compile(r"^--exclude=.{1,200}$")
_DESK_ETAT = CASSANDRA_DATA_DIR + "/desk_etat"
_DESK_SAUVEGARDES = "/mnt/desk/.sauvegardes"
_DESK_SAUVEGARDE_NOM = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._-]{0,80}\.tar\.gz$")

_DESK = {
    "montage": {
        "quoi": ("Monter / démonter / lister un dossier réseau pour un utilisateur : "
                 "op=monter|demonter|etat · type=nfs|cifs|sshfs · source=adresse distante "
                 "· cible=chemin confiné sous /mnt/desk/<user>/ · options · secret={{secret:NOM}} "
                 "(CIFS) · confirmation='oui' exigée pour monter."),
        "fonction": "_desk_montage",
        "params": ("user", "op", "type", "source", "cible", "options", "secret", "confirmation"),
    },
    "rsync": {
        "quoi": ("Transférer des fichiers dans l'espace de l'utilisateur : op=simuler (dry-run, "
                 "obligatoire) puis op=copier (confirmation='oui'). source et cible confinées "
                 "sous /mnt/desk/<user>/ · options restreintes (-a -v -r -u -z -t --exclude=…, "
                 "et --delete seulement avec confirmation='oui')."),
        "fonction": "_desk_rsync",
        "params": ("user", "op", "source", "cible", "options", "confirmation"),
    },
    "partage_etat": {
        "quoi": "Lister les montages actifs de l'utilisateur (sous /mnt/desk/<user>/).",
        "fonction": "_desk_partage_etat",
        "params": ("user",),
    },
    "sauvegarde": {
        "quoi": ("Sauvegarder / restaurer l'espace desk d'un utilisateur : op=lister|creer|restaurer · "
                 "nom=<fichier>.tar.gz (pour restaurer) · confirmation='oui' exigée pour restaurer (écrase). "
                 "Les archives sont stockées HORS de l'espace, sous /mnt/desk/.sauvegardes/<user>/."),
        "fonction": "_desk_sauvegarde",
        "params": ("user", "op", "nom", "confirmation"),
    },
    "archive": {
        "quoi": ("Lire une archive (.zip, .tar, .tar.gz…) dans l'espace de l'utilisateur : op=lister "
                 "(contenu) | extraire (dans un dossier frère neuf <archive>.extrait, jamais par-dessus "
                 "l'existant). Chemin confiné sous /mnt/desk/<user>/."),
        "fonction": "_desk_archive",
        "params": ("user", "op", "source"),
    },
}


def _desk_utilisateur(p):
    """Le nom d'utilisateur est un jeton sûr, jamais un chemin."""
    u = str((p or {}).get("user") or "").strip().lower()
    return u if _DESK_USER.match(u) else ""


def _desk_preparer(user):
    """(racine réelle, erreur). Prépare /mnt/desk/<user>/ et rend son realpath."""
    racine = os.path.realpath(os.path.join(_DESK_RACINE, user))
    try:
        os.makedirs(racine, mode=0o700, exist_ok=True)
    except Exception as e:
        return "", "impossible de préparer %s : %s" % (racine, e)
    return racine, ""


def _desk_confiner(user, chemin):
    """(chemin réel, erreur). `chemin` doit être SOUS /mnt/desk/<user>/ —
    jamais un chemin système, jamais une traversée (realpath résout les liens)."""
    if chemin is None or "\x00" in str(chemin):
        return "", "chemin refusé (vide ou caractère nul)"
    chemin = str(chemin).strip()
    if not chemin:
        return "", "chemin vide"
    racine, err = _desk_preparer(user)
    if err:
        return "", err
    c = os.path.realpath(chemin)
    if c != racine and not c.startswith(racine + os.sep):
        return "", ("chemin refusé : %r sort de /mnt/desk/%s/ — jamais /, /etc, "
                    "ni un chemin système" % (chemin[:80], user))
    return c, ""


def _desk_confirmer(p):
    return str((p or {}).get("confirmation") or "").strip().lower() == "oui"


def _desk_dry_run_cle(user, source, cible, options):
    return "|".join((user, source, cible, options))


def _desk_dry_run_marquer(user, cle, lignes):
    try:
        os.makedirs(_DESK_ETAT, mode=0o700, exist_ok=True)
        with open(os.path.join(_DESK_ETAT, user + ".json"), "w", encoding="utf-8") as fh:
            json.dump({"cle": cle, "ts": time.time(), "lignes": lignes[:4000]}, fh)
    except Exception as e:
        logging.warning("[DESK] dry-run non mémorisé : %s", e)


def _desk_dry_run_verifier(user, cle):
    """(ok, message). Une copie n'est admise que si un dry-run RÉCENT (≤ 30 min)
    a été fait pour la même source/cible/options — le garde-fou « simuler avant
    copier » est réel, pas un conseil."""
    try:
        p = os.path.join(_DESK_ETAT, user + ".json")
        if not os.path.isfile(p):
            return False, "aucun dry-run enregistré : fais d'abord op=simuler, puis relance op=copier avec confirmation='oui'."
        with open(p, encoding="utf-8") as fh:
            d = json.load(fh)
        if d.get("cle") != cle:
            return False, "le dry-run enregistré ne correspond pas à cette source/cible/options : refais op=simuler."
        if time.time() - float(d.get("ts", 0)) > 1800:
            return False, "dry-run trop ancien (plus de 30 min) : refais op=simuler."
        return True, ""
    except Exception as e:
        return False, "état de dry-run illisible : %s" % e


def _desk_partage_etat(p):
    user = _desk_utilisateur(p)
    if not user:
        return 1, "utilisateur invalide (admis : [a-z0-9._-], 32 signes au plus, sans chemin)"
    racine, err = _desk_preparer(user)
    if err:
        return 1, err
    lignes = []
    try:
        with open("/proc/mounts", encoding="utf-8") as fh:
            for l in fh:
                c = l.split()
                if len(c) >= 3:
                    pt = os.path.realpath(c[1]) if os.path.exists(c[1]) else c[1]
                    if pt == racine or pt.startswith(racine + os.sep):
                        lignes.append("%s -> %s (%s)" % (c[0][:80], c[1], c[2]))
    except Exception as e:
        return 1, "lecture de /proc/mounts impossible : %s" % e
    return 0, "\n".join(lignes) or "aucun montage actif sous /mnt/desk/%s/" % user


def _desk_montage(p):
    user = _desk_utilisateur(p)
    if not user:
        return 1, "utilisateur invalide (admis : [a-z0-9._-], 32 signes au plus, sans chemin)"
    op = str((p or {}).get("op") or "").strip()
    if op == "etat":
        return _desk_partage_etat(p)
    if op not in ("monter", "demonter"):
        return 1, "opération inconnue : %r (admis : monter | demonter | etat)" % op
    typ = str((p or {}).get("type") or "").strip().lower()
    if typ not in _DESK_TYPES:
        return 1, "type inconnu : %r (admis : nfs | cifs | sshfs)" % typ
    cible, err = _desk_confiner(user, str((p or {}).get("cible") or ""))
    if err:
        return 1, err
    if op == "demonter":
        try:
            r = subprocess.run(["/usr/bin/umount", cible], capture_output=True, text=True, timeout=60)
        except FileNotFoundError:
            return 1, "umount absent"
        except Exception as e:
            return 1, "umount impossible : %s" % e
        if r.returncode != 0:
            return 1, "umount : %s" % (r.stderr or r.stdout or "").strip()[-400:]
        return 0, "démonté : %s" % cible
    if not _desk_confirmer(p):
        return 1, "montage refusé : confirmation='oui' exigée — l'usager doit valider la source et les options."
    source = str((p or {}).get("source") or "").strip()
    if not source or "\n" in source or "\x00" in source:
        return 1, "source invalide (adresse distante requise, sans retour à la ligne)"
    options = str((p or {}).get("options") or "").strip()
    try:
        os.makedirs(cible, exist_ok=True)
    except Exception as e:
        return 1, "cible inutilisable : %s" % e
    creds_file = None
    binaire = "/usr/bin/mount"
    try:
        if typ == "nfs":
            argv = [binaire, "-t", "nfs"]
            if options:
                argv += ["-o", options]
            argv += [source, cible]
        elif typ == "cifs":
            secret = _resolve_secret_refs(str((p or {}).get("secret") or "").strip())
            usr = ""
            autres = []
            for tok in re.split(r"[, ]+", options):
                if tok.startswith("username="):
                    usr = tok[len("username="):]
                elif tok:
                    autres.append(tok)
            if not usr:
                return 1, "CIFS : options doit contenir username=<compte>"
            if not secret or secret.startswith("{{secret:"):
                return 1, "CIFS : secret introuvable au coffre — fournis secret={{secret:NOM}}"
            os.makedirs("/run/cassandra-desks", mode=0o700, exist_ok=True)
            creds_file = "/run/cassandra-desks/%s.%d" % (usr, os.getpid())
            with open(creds_file, "w", encoding="utf-8") as fh:
                fh.write("username=%s\n" % usr)
                fh.write("password=%s\n" % secret)
            os.chmod(creds_file, 0o600)
            argv = [binaire, "-t", "cifs", "-o", ",".join(["credentials=" + creds_file] + autres), source, cible]
        else:  # sshfs — par clé, sans mot de passe en clair
            binaire = "/usr/bin/sshfs"
            argv = [binaire]
            if options:
                argv += ["-o", options]
            argv += [source, cible]
        r = subprocess.run(argv, capture_output=True, text=True, timeout=120)
    except FileNotFoundError:
        return 1, "binaire absent : %s" % binaire
    except Exception as e:
        return 1, "montage impossible : %s" % e
    finally:
        if creds_file:
            try:
                os.remove(creds_file)
            except Exception:
                pass
    if r.returncode != 0:
        return 1, "montage : %s" % (r.stderr or r.stdout or "").strip()[-600:]
    return 0, "monté (%s) : %s → %s" % (typ, source, cible)


def _desk_rsync(p):
    import shlex
    user = _desk_utilisateur(p)
    if not user:
        return 1, "utilisateur invalide (admis : [a-z0-9._-], 32 signes au plus, sans chemin)"
    op = str((p or {}).get("op") or "").strip()
    if op not in ("simuler", "copier"):
        return 1, "opération inconnue : %r (admis : simuler | copier)" % op
    source, err = _desk_confiner(user, str((p or {}).get("source") or ""))
    if err:
        return 1, "source — " + err
    cible, err = _desk_confiner(user, str((p or {}).get("cible") or ""))
    if err:
        return 1, "cible — " + err
    options = str((p or {}).get("options") or "").strip()
    try:
        toks = shlex.split(options) if options else []
    except ValueError as e:
        return 1, "options illisibles : %s" % e
    opts = []
    suppr = False
    for t in toks:
        if t in ("-a", "-v", "-r", "-u", "-z", "-t", "--times"):
            opts.append(t)
        elif t == "--delete":
            suppr = True
        elif _DESK_RSYNC_EXCLU.match(t):
            opts.append(t)
        else:
            return 1, "option rsync refusée : %r (admis : -a -v -r -u -z -t --exclude=… --delete)" % t[:60]
    if suppr and not _desk_confirmer(p):
        return 1, "--delete refusé : confirmation='oui' exigée."
    if op == "simuler":
        argv = ["/usr/bin/rsync", "--dry-run", "--itemize-changes"] + opts + [source + "/", cible]
        if suppr:
            argv.append("--delete")
        try:
            r = subprocess.run(argv, capture_output=True, text=True, timeout=300)
        except FileNotFoundError:
            return 1, "rsync absent"
        except Exception as e:
            return 1, "rsync : %s" % e
        out = (r.stdout or "") + (r.stderr or "")
        _desk_dry_run_marquer(user, _desk_dry_run_cle(user, source, cible, options), out[:4000])
        if r.returncode != 0:
            return 1, "simulation rsync :\n%s" % out[-1500:]
        return 0, ("simulation (dry-run) — rien n'a été copié :\n%s\n\n"
                   "Pour copier : relance avec op=copier, confirmation='oui'." % out[-2500:])
    # copier
    if not _desk_confirmer(p):
        return 1, "copie refusée : confirmation='oui' exigée."
    ok, msg = _desk_dry_run_verifier(user, _desk_dry_run_cle(user, source, cible, options))
    if not ok:
        return 1, msg
    argv = ["/usr/bin/rsync", "-a"] + opts + [source + "/", cible]
    if suppr:
        argv.append("--delete")
    try:
        r = subprocess.run(argv, capture_output=True, text=True, timeout=600)
    except FileNotFoundError:
        return 1, "rsync absent"
    except Exception as e:
        return 1, "rsync : %s" % e
    out = (r.stdout or "") + (r.stderr or "")
    return (0 if r.returncode == 0 else 1), "copié : %s → %s\n%s" % (source, cible, out[-2000:])




def _desk_sauvegarde(p):
    import tarfile
    user = _desk_utilisateur(p)
    if not user:
        return 1, "utilisateur invalide (admis : [a-z0-9._-], 32 signes au plus, sans chemin)"
    op = str((p or {}).get("op") or "").strip()
    if op not in ("lister", "creer", "restaurer"):
        return 1, "opération inconnue : %r (admis : lister | creer | restaurer)" % op
    racine, err = _desk_preparer(user)
    if err:
        return 1, err
    depot = os.path.join(_DESK_SAUVEGARDES, user)
    try:
        os.makedirs(depot, mode=0o700, exist_ok=True)
    except Exception as e:
        return 1, "impossible de préparer le dépôt de sauvegardes : %s" % e
    if op == "lister":
        lignes = []
        try:
            for nom in sorted(os.listdir(depot)):
                if not _DESK_SAUVEGARDE_NOM.match(nom):
                    continue
                st = os.stat(os.path.join(depot, nom))
                lignes.append("%s — %s octets — %s" % (nom, st.st_size,
                                                       time.strftime("%Y-%m-%d %H:%M", time.localtime(st.st_mtime))))
        except Exception as e:
            return 1, "liste impossible : %s" % e
        return 0, "\n".join(lignes) or "aucune sauvegarde"
    if op == "creer":
        nom = "desk-%s.tar.gz" % time.strftime("%Y%m%d-%H%M%S")
        bak = os.path.join(depot, nom)
        try:
            with tarfile.open(bak, "w:gz") as tf:
                for nom_f in sorted(os.listdir(racine)):
                    tf.add(os.path.join(racine, nom_f), arcname=nom_f)
        except Exception as e:
            return 1, "sauvegarde impossible : %s" % e
        return 0, "sauvegarde créée : %s (%s octets)" % (nom, os.path.getsize(bak))
    # restaurer — écrase l'espace actuel : confirmation exigée
    if not _desk_confirmer(p):
        return 1, "restauration refusée : confirmation='oui' exigée — elle écrase l'espace actuel."
    nom = str((p or {}).get("nom") or "").strip()
    if not _DESK_SAUVEGARDE_NOM.match(nom):
        return 1, "nom de sauvegarde invalide (admis : <nom>.tar.gz)"
    bak = os.path.join(depot, nom)
    if not os.path.isfile(bak):
        return 1, "sauvegarde introuvable : %s" % nom
    try:
        with tarfile.open(bak) as tf:
            for m in tf.getmembers():
                if m.name.startswith("/") or ".." in m.name.split("/"):
                    return 1, "archive refusée : chemin %r" % m.name
                if m.issym() or m.islnk():
                    return 1, "archive refusée : lien %r" % m.name
                dest = os.path.realpath(os.path.join(racine, m.name))
                if dest != racine and not dest.startswith(racine + os.sep):
                    return 1, "archive refusée : %r sort de l'espace" % m.name
            tf.extractall(racine)
    except Exception as e:
        return 1, "restauration impossible : %s" % e
    return 0, "restauré : %s → %s" % (nom, racine)


def _desk_archive(p):
    import zipfile
    import tarfile
    user = _desk_utilisateur(p)
    if not user:
        return 1, "utilisateur invalide (admis : [a-z0-9._-], 32 signes au plus, sans chemin)"
    op = str((p or {}).get("op") or "").strip()
    if op not in ("lister", "extraire"):
        return 1, "opération inconnue : %r (admis : lister | extraire)" % op
    source, err = _desk_confiner(user, str((p or {}).get("source") or ""))
    if err:
        return 1, "source — " + err
    if not os.path.isfile(source):
        return 1, "archive introuvable : %s" % source
    try:
        if source.endswith(".zip"):
            zf = zipfile.ZipFile(source)
        elif source.endswith((".tar", ".tar.gz", ".tgz", ".tar.bz2", ".tar.xz")):
            zf = tarfile.open(source)
        else:
            return 1, "format non reconnu (admis : .zip, .tar, .tar.gz, .tgz, .tar.bz2, .tar.xz)"
    except Exception as e:
        return 1, "lecture de l'archive impossible : %s" % e
    try:
        if op == "lister":
            lignes = []
            if isinstance(zf, zipfile.ZipFile):
                for i, m in enumerate(zf.infolist()):
                    lignes.append("%s (%s o)" % (m.filename, m.file_size))
                    if i >= 499:
                        lignes.append("… (liste tronquée à 500 entrées)")
                        break
            else:
                for i, m in enumerate(zf.getmembers()):
                    lignes.append("%s (%s o)" % (m.name, m.size))
                    if i >= 499:
                        lignes.append("… (liste tronquée à 500 entrées)")
                        break
            return 0, "\n".join(lignes) or "archive vide"
        # extraire → dossier frère neuf, jamais par-dessus l'existant
        cible, err = _desk_confiner(user, source + ".extrait")
        if err:
            return 1, "cible — " + err
        if os.path.exists(cible):
            return 1, "cible déjà existante : %s — vide ce dossier ou choisis une autre archive." % cible
        os.makedirs(cible, exist_ok=True)
        if isinstance(zf, zipfile.ZipFile):
            for m in zf.infolist():
                dest = os.path.realpath(os.path.join(cible, m.filename))
                if dest != cible and not dest.startswith(cible + os.sep):
                    return 1, "archive refusée : %r sort de l'espace" % m.filename
            zf.extractall(cible)
        else:
            for m in zf.getmembers():
                if m.name.startswith("/") or ".." in m.name.split("/"):
                    return 1, "archive refusée : chemin %r" % m.name
                if m.issym() or m.islnk():
                    return 1, "archive refusée : lien %r" % m.name
                dest = os.path.realpath(os.path.join(cible, m.name))
                if dest != cible and not dest.startswith(cible + os.sep):
                    return 1, "archive refusée : %r sort de l'espace" % m.name
            zf.extractall(cible)
        return 0, "extrait dans : %s" % cible
    finally:
        zf.close()


def desk_liste():
    out = []
    for nom, e in _DESK.items():
        out.append({"nom": nom, "quoi": e["quoi"], "params": list(e["params"])})
    return out


def desk_executer(nom, params):
    e = _DESK.get(nom)
    if not e:
        return {"ok": False, "error": "entrée inconnue du desk : %r (admis : %s)" % (nom, ", ".join(sorted(_DESK)))}
    params = params or {}
    if not isinstance(params, dict):
        return {"ok": False, "error": "params doit être un objet"}
    for k in params:
        if k not in e["params"]:
            return {"ok": False, "error": "paramètre %r non prévu pour %s" % (k, nom)}
    for k, v in params.items():
        if isinstance(v, str) and "\x00" in v:
            return {"ok": False, "error": "%s : caractère nul" % k}
        if isinstance(v, str) and len(v) > 4000:
            return {"ok": False, "error": "%s : trop long (4000 signes au plus)" % k}
    fn = globals().get(e["fonction"])
    if not callable(fn):
        return {"ok": False, "error": "fonction %s absente" % e["fonction"]}
    t0 = time.time()
    try:
        rc, out = fn(params)
    except Exception as ex:
        rc, out = 1, "❌ %s" % ex
    out, nred = courtier_sortie(out or "")
    _cage_journal("desk", nom, json.dumps(params, ensure_ascii=False)[:500], rc,
                  int((time.time() - t0) * 1000), nred, "")
    return {"ok": rc == 0, "rc": rc, "sortie": out[:6000]}


def _desk_impl(args):
    nom = str((args or {}).get("nom") or "").strip()
    params = (args or {}).get("params") or {}
    if not isinstance(params, dict):
        params = {}
    if nom == "liste":
        lignes = []
        for e in desk_liste():
            lignes.append("%s — %s\n    params : %s" % (e["nom"], e["quoi"], ", ".join(e["params"])))
        return (True, "\n".join(lignes), "#7bd88f")
    r = desk_executer(nom, params)
    if not r.get("ok"):
        return (False, r.get("error") or ("rc=%s\n%s" % (r.get("rc"), r.get("sortie", "")))[:3000], "#e0564a")
    return (True, "✓ %s\n%s" % (nom, r.get("sortie", "")), "#7bd88f")


def secure_execute(cmd: str) -> str:
    """EN CAGE. La commande tourne dans une unité systemd jetable aux droits
    fixés d'avance — système en lecture seule hors espace de travail, pas de
    réseau sortant, pas d'accès aux secrets ni aux sockets de commande. Aucun
    modèle ne décide : ce qu'elle ne doit pas faire, elle ne PEUT pas le faire.
    La teinte du tour ne décide que du réseau vers la maison.
    """
    if not cmd or not cmd.strip():
        return "Commande vide"
    cmd = _resolve_secret_refs(cmd)   # {{secret:NOM}} → valeur réelle, JIT (jamais en logs/prompt)
    # LE DERNIER FILET, SUR LE TEXTE QUI PART VRAIMENT. La ligne ci-dessus vient
    # de remplacer les références du coffre : ce que l'outil a vu et ce que bash
    # va lancer ne sont plus le même texte. Et tout appelant qui arrive ici sans
    # passer par la boucle d'outils trouve quand même le veto.
    _v = veto_root(cmd)
    if _v:
        _cage_journal("cage", "", cmd, -1, 0, 0, "veto : " + _v)
        return ("⛔ Geste interdit — %s. Aucune autorisation ne lève ce refus : "
                "il porte sur ce que la commande fait à la machine, pas sur "
                "l'intention déclarée." % _v)
    # LA TEINTE VIENT DE CE QUI S'EST PASSÉ, pas de ce qui est écrit : un outil
    # de lecture externe a-t-il tourné dans ce tour ?
    try:
        _teinte = bool(origine_courante().get("teintes"))
    except Exception:
        _teinte = True                    # dans le doute, la cage la plus fermée
    _t0 = time.time()
    _prov_avant = _prov_etat()
    try:
        if cage_disponible():
            result = subprocess.run(cage_argv(cmd, _teinte), capture_output=True,
                                    text=True, timeout=120)
        else:
            # SANS systemd (banc, autre machine) : on ne fait pas semblant. La
            # commande tourne à découvert et le journal le dit.
            result = subprocess.run(
                cmd, shell=True, executable='/bin/bash', capture_output=True, text=True,
                timeout=120,
                env=dict(os.environ, PATH="/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin"))
        output = result.stdout + result.stderr
        # 2 = écrit par un INVITÉ : ce qu'il a lu de son côté est invisible d'ici.
        _prov_enregistrer(_prov_avant, _prov_etat(),
                          2 if origine_courante().get("origine") == "invite" else _teinte, cmd)
        output, _nred = courtier_sortie(output)
        _cage_journal("cage" if cage_disponible() else "DECOUVERT", _teinte, cmd,
                      result.returncode, int((time.time() - _t0) * 1000), _nred, "")
        if not output:
            output = f"✓ Code {result.returncode}"
        return output
    except subprocess.TimeoutExpired:
        return "⏱️ Timeout 120s"
    except Exception as e:
        return f"❌ Erreur: {e}"


# ============================================================
# 15.4 PROACTIVITÉ — Sensorium → détection → investigation → action sous garde
#   Cassandra surveille son serveur, signale les problèmes, peut les diagnostiquer
#   (lecture seule) et appliquer une correction RÉVERSIBLE — chaque action passant
#   par la cage : les effets sont impossibles par construction.
#   Seul le redémarrage d'un service systemd tombé est éligible à l'auto-remédiation ;
#   disque / SSL / sécurité = détection + investigation + action sur clic.
# ============================================================
_PROACTIVE_LAST = [0.0]
_SAFE_ACTION_KINDS = ("service.restart", "securite.bannir", "site.relancer", "sauvegarde.relancer", "ssh.rotation", "conteneur.relancer", "disque.purger")   # seules actions auto-remédiables (réversibles)


def _detect_disk() -> list:
    out = []
    m = get_metrics() or {}
    def _f(x):
        try: return float(x or 0)
        except Exception: return 0.0
    # get_metrics() rend « disk » et « swap » (10-10 : lus sous « disk_pct », ils valaient toujours 0)
    disk = _f(m.get("disk", m.get("disk_pct"))); swap = _f(m.get("swap", m.get("swap_pct")))
    warn = _mem_cfg("proactive_disk_warn", 80.0); crit = _mem_cfg("proactive_disk_crit", 90.0)
    if disk >= warn:
        sev = "critical" if disk >= crit else "warning"
        out.append({"fkey": "disk_root", "category": "disk", "severity": sev,
                    "title": "Disque / à %.0f%%" % disk,
                    "detail": "La partition racine est remplie à %.0f%% (seuil %.0f%%). Les vieux journaux et les paquets téléchargés peuvent être purgés." % (disk, crit if sev == "critical" else warn),
                    "suggested_action": "purger-caches", "action_kind": "disque.purger"})
    if swap >= 80:
        out.append({"fkey": "swap_high", "category": "disk", "severity": "warning",
                    "title": "Swap à %.0f%%" % swap,
                    "detail": "Utilisation swap élevée (%.0f%%) — pression mémoire probable." % swap,
                    "suggested_action": "", "action_kind": "diagnostic"})
    return out


_PURGE_ETAPES = (("journaux de plus de 14 jours", ["journalctl", "--vacuum-time=14d"]),
                 ("paquets téléchargés", ["apt-get", "clean"]))


def _aut_purger_caches() -> tuple:
    """(ok, détail). UNE liste fermée de purges inoffensives (vieux journaux, paquets déjà installés) : rien d'autre, jamais un chemin
    venu du constat. Dit ce qui a été libéré, mesuré sur le disque."""
    import shutil
    avant = shutil.disk_usage("/").used
    faits, rates = [], []
    for nom, cmd in _PURGE_ETAPES:
        try:
            p = subprocess.run(cmd, capture_output=True, text=True, timeout=180)
            (faits if p.returncode == 0 else rates).append(nom)
        except Exception as e:
            rates.append("%s (%s)" % (nom, str(e)[:40]))
    libere = max(0, avant - shutil.disk_usage("/").used) // (1024 * 1024)
    det = "%d Mo libérés (%s)" % (libere, ", ".join(faits) or "rien de purgé")
    if rates:
        return False, det + " · échec : " + ", ".join(rates)
    return True, det


def _detect_pieces() -> list:
    """Le dossier des pièces jointes de session : ce qu'il pèse, ce qui traîne.

    Il grossit vite — une archive de vingt PDF, et c'est autant d'octets gardés
    pour la journée — et rien à l'écran ne le montre. C'est exactement le genre
    d'endroit qui remplit un disque sans que personne le voie venir.
    """
    out = []
    b = lab_pieces_bilan()
    if not b.get("ok"):
        return out
    mo = b["octets"] / (1024.0 * 1024.0)
    warn = float(_mem_cfg("proactive_pieces_mo_warn", 1024.0))
    crit = float(_mem_cfg("proactive_pieces_mo_crit", 3072.0))
    if mo >= warn:
        sev = "critical" if mo >= crit else "warning"
        out.append({
            "fkey": "pieces_volume", "category": "disk", "severity": sev,
            "title": "Pièces jointes : %s" % _ged_octets(b["octets"]),
            "detail": ("Le dossier des pièces déposées dans les conversations "
                       "occupe %s pour %d fichier(s) (seuil %.0f Mo). Elles "
                       "s'effacent d'elles-mêmes au bout de %d h ; si le "
                       "volume ne baisse pas, c'est que de nouvelles arrivent "
                       "plus vite qu'elles ne partent."
                       % (_ged_octets(b["octets"]), b["fichiers"],
                          crit if sev == "critical" else warn,
                          _LAB_PIECES_TTL_H)),
            "suggested_action": "", "action_kind": "diagnostic"})
    # UN ORPHELIN N'EST PAS UN VOLUME, C'EST UNE FUITE. Des octets que plus
    # aucune ligne ne désigne ne partiront jamais d'eux-mêmes : le compte à
    # rebours des vingt-quatre heures s'applique aux LIGNES, pas à eux.
    if b["orphelins"]:
        out.append({
            "fkey": "pieces_orphelins", "category": "disk", "severity": "warning",
            "title": "%d pièce(s) sans propriétaire" % b["orphelins"],
            "detail": ("%d fichier(s) (%s) traînent dans le dossier des pièces "
                       "sans qu'aucune conversation ne les désigne — un arrêt "
                       "entre l'écriture et l'enregistrement, probablement. Le "
                       "ménage les emporte au prochain passage ; s'ils "
                       "reviennent, c'est qu'un dépôt échoue à répétition."
                       % (b["orphelins"], _ged_octets(b["orphelins_octets"]))),
            "suggested_action": "", "action_kind": "diagnostic"})
    return out


def _detect_ssl() -> list:
    out = []
    warn = _mem_cfg("proactive_ssl_warn", 30); crit = _mem_cfg("proactive_ssl_crit", 7)
    for c in (get_ssl_certificates() or []):
        try: d = int(c.get("days_left", 999))
        except Exception: continue
        dom = c.get("domain", "?")
        if d <= warn:
            sev = "critical" if d <= crit else "warning"
            out.append({"fkey": "ssl_%s" % dom, "category": "ssl", "severity": sev,
                        "title": "SSL %s expire dans %dj" % (dom, d),
                        "detail": "Le certificat de %s expire dans %d jours (seuil %d)." % (dom, d, crit if sev == "critical" else warn),
                        "suggested_action": "", "action_kind": "diagnostic"})
    return out


def _detect_services() -> list:
    out = []
    try:
        for u in (get_failed_units() or [])[:30]:
            unit = (u.get("unit") or "").strip()
            if not unit or unit in UNIT_BULLETS or unit == "?":
                continue
            # Des unités dont l'échec ne dit rien de la santé de la machine (le crochet d'ARRÊT d'unattended-upgrades :
            # les mises à jour, elles, passent par le minuteur apt-daily-upgrade). Réglable.
            if unit in {x.strip() for x in str(_mem_cfg("proactive_services_ignores",
                                                         "unattended-upgrades.service") or "").split(",") if x.strip()}:
                continue
            out.append({"fkey": "service_down_%s" % unit, "category": "service", "severity": "critical",
                        "title": "Service en échec : %s" % unit,
                        "detail": "L'unité systemd %s est en état 'failed'%s." % (unit, (" — " + u.get("description", "")) if u.get("description") else ""),
                        "suggested_action": "systemctl restart %s" % unit, "action_kind": "service.restart"})
    except Exception:
        pass
    try:
        h = get_health_score() or {}
        sc = h.get("score")
        if sc is not None and float(sc) < _mem_cfg("proactive_health_min", 60):
            out.append({"fkey": "health_low", "category": "health",
                        "severity": "critical" if float(sc) < 40 else "warning",
                        "title": "Score de santé bas : %s/100" % sc,
                        "detail": "Le score de santé global est à %s (%s)." % (sc, h.get("status", "")),
                        "suggested_action": "", "action_kind": "diagnostic"})
    except Exception:
        pass
    try:
        n = len(get_oom_events() or [])
        if n > 0:
            out.append({"fkey": "oom_24h", "category": "health", "severity": "warning",
                        "title": "%d OOM kill(s) en 24h" % n,
                        "detail": "%d processus tué(s) par le OOM killer ces 24 dernières heures — pression mémoire." % n,
                        "suggested_action": "", "action_kind": "diagnostic"})
    except Exception:
        pass
    return out


def _detect_security() -> list:
    out = []
    try:
        f = query_db("SELECT COUNT(*) c FROM fail2ban_banned_ips")
        n = f[0]["c"] if f else 0
        if n >= _mem_cfg("proactive_ban_spike", 25):
            out.append({"fkey": "fail2ban_spike", "category": "security", "severity": "warning",
                        "title": "%d IP bannies (fail2ban)" % n,
                        "detail": "%d IP actuellement bannies — pic d'attaques possible." % n,
                        "suggested_action": "", "action_kind": "diagnostic"})
    except Exception:
        pass
    out += _detect_attaquants()
    return out


def _detect_attaquants() -> list:
    """Adresses insistantes : beaucoup d'attaques repoussées sur les sites ces deux derniers jours, et pas encore bannies.

    Chacune devient un constat qui porte son bannissement (CrowdSec, sept jours, réversible). La règle « Réseau et accès ›
    Bannir ou débannir » décide si Cassandra le pose seule. Une adresse de confiance (la maison, le tailnet, l'adresse
    publique) n'est JAMAIS proposée : sinon son refus compterait comme un échec et ferait sauter le disjoncteur."""
    import shutil                                       # pas d'import global de shutil dans ce module
    out = []
    try:
        if not shutil.which("cscli"):
            return out                                  # sans CrowdSec, le bannissement est impossible : pas de constat
        seuil = int(_mem_cfg("proactive_ban_min", 40))
        rows = query_db("SELECT ip, SUM(n) n FROM secu_ip WHERE jour >= date('now','localtime','-1 days') "
                        "GROUP BY ip HAVING SUM(n) >= ? ORDER BY n DESC LIMIT 10", (seuil,)) or []
        if not rows:
            return out
        ok, brut = _sec_cscli(["decisions", "list", "-o", "json"])
        bannies = set()
        if ok:
            try:
                for a in (json.loads(brut or "null") or []):
                    for d in (a.get("decisions") or []):
                        bannies.add(str(d.get("value") or ""))
            except Exception:
                pass
        for r in rows:
            ip = str(r["ip"] or "").strip()
            if not ip or ip in bannies or _sec_de_confiance(ip):
                continue
            out.append({"fkey": "attaquant_%s" % ip, "category": "security", "severity": "warning",
                        "title": "Adresse insistante : %s (%d attaques repoussées)" % (ip, int(r["n"])),
                        "detail": "%s a tenté %d fois en deux jours : sondes d'effraction, mots de passe refusés. "
                                  "Pas encore bannie." % (ip, int(r["n"])),
                        "suggested_action": "bannir %s" % ip, "action_kind": "securite.bannir"})
    except Exception as e:
        logging.info("[PROACTIF] adresses insistantes : %s", e)
    return out


def _detect_vault() -> list:
    """Surveille le coffre : service arrêté, API injoignable, ou coffre verrouillé."""
    out = []
    if not os.path.exists(CASSANDRA_CONF_DIR + "/vault.env") and \
       not os.path.exists("/etc/systemd/system/cassandra-vault.service"):
        return out  # coffre non installé → rien à surveiller
    try:
        active = subprocess.run(["systemctl", "is-active", "cassandra-vault"],
                                capture_output=True, text=True, timeout=5).stdout.strip()
    except Exception:
        active = "unknown"
    if active != "active":
        out.append({"fkey": "vault_service_down", "category": "service", "severity": "critical",
                    "title": "Coffre Vaultwarden arrêté",
                    "detail": "Le service cassandra-vault n'est pas actif (%s) — secrets et coffres "
                              "utilisateurs indisponibles." % active,
                    "suggested_action": "systemctl restart cassandra-vault",
                    "action_kind": "service.restart"})
        return out
    try:
        st = vault_status()
        if not st.get("available"):
            out.append({"fkey": "vault_api_down", "category": "service", "severity": "warning",
                        "title": "API du coffre injoignable",
                        "detail": "Le service tourne mais l'API locale (sidecar bw serve) ne répond pas.",
                        "suggested_action": "systemctl restart cassandra-vault",
                        "action_kind": "service.restart"})
        elif st.get("status") != "unlocked":
            out.append({"fkey": "vault_locked", "category": "service", "severity": "warning",
                        "title": "Coffre verrouillé",
                        "detail": "Le coffre est en état '%s' — déverrouillage requis pour "
                                  "lire/écrire les secrets." % st.get("status"),
                        "suggested_action": "systemctl restart cassandra-vault",
                        "action_kind": "service.restart"})
        else:
            out += _detect_secrets_anciens()
    except Exception:
        pass
    return out


# Ce qui n'est pas un secret : identifiants publics, pseudos, mots de passe des coffres de comptes (leur rotation est un changement de mot de passe d'utilisateur).
_SEC_PAS_UN_SECRET = ("/id", "/nom", "/pseudo", "/tel", "/qui", "/api_user", "/api_id")


def _detect_secrets_anciens() -> list:
    """Règle « Rotation des secrets › Signaler un secret trop ancien » : lecture seule, les NOMS seulement, jamais une valeur.
    Un secret dont la dernière révision dépasse le seuil (180 jours par défaut) est signalé en un seul constat."""
    seuil = int(_mem_cfg("secret_age_jours", 180) or 180)
    r = _vault_req("GET", "/list/object/items")
    items = ((r.get("data") or {}).get("data")) or []
    maintenant = time.time()
    vieux = []
    for it in items:
        nom = str(it.get("name") or "")
        if not nom or nom.startswith("cassandra/comptes/") or nom.endswith(_SEC_PAS_UN_SECRET):
            continue
        try:
            rev = datetime.strptime(str(it.get("revisionDate") or "")[:19], "%Y-%m-%dT%H:%M:%S")
            jours = int((datetime.utcnow() - rev).total_seconds() // 86400)
        except Exception:
            continue
        if jours >= seuil:
            vieux.append((jours, nom))
    if not vieux:
        return []
    vieux.sort(reverse=True)
    liste = ", ".join("%s (%d j)" % (n, j) for j, n in vieux[:12])
    return [{"fkey": "secrets_anciens", "category": "vault", "severity": "info",
             "title": "%d secret%s sans changement depuis plus de %d jours" % (len(vieux), "s" if len(vieux) > 1 else "", seuil),
             "detail": "Les plus anciens : %s. À faire tourner quand tu peux ; seuls les noms sont affichés." % liste,
             "suggested_action": "", "action_kind": "diagnostic"}]


# ── Échantillonnage de métriques (alimente la tendance disque + les sparklines) ──
def _proactive_sample_metrics() -> None:
    try:
        m = get_metrics() or {}
        try:
            load1 = os.getloadavg()[0]
        except Exception:
            load1 = 0.0
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        conn.execute("CREATE TABLE IF NOT EXISTS proactive_metrics (ts REAL PRIMARY KEY, "
                     "disk_pct REAL, disk_free_gb REAL, ram_pct REAL, load1 REAL)")
        def _f(*keys):
            for k in keys:
                try:
                    v = m.get(k)
                    if v not in (None, ""):
                        return float(v)
                except Exception:
                    pass
            return 0.0
        conn.execute("INSERT OR REPLACE INTO proactive_metrics VALUES (?,?,?,?,?)",
                     (time.time(), _f("disk_pct", "disk"), _f("disk_free_gb"),
                      _f("ram_pct", "ram_used_pct", "ram"), float(load1)))   # get_metrics rend « ram »/« disk » (t14 : série morte à 0)
        conn.execute("DELETE FROM proactive_metrics WHERE ts < ?", (time.time() - 14 * 86400,))
        conn.commit(); conn.close()
        try:
            memoire_rappels_evaluer()   # la mémoire adressée : une condition mécanique, jamais le modèle
        except Exception as _re:
            logging.debug("[MEMOIRE] rappels conditionnés : %s", _re)
        try:
            # LA PÉREMPTION, ICI et pas ailleurs : le relevé vient de mesurer le monde que ces
            # souvenirs décrivent. Un artefact de code ne bouge qu'au déploiement, un état observé
            # qu'au relevé — ce point les couvre tous les deux. (Défaut trouvé le 11-09 : la passe
            # existait depuis la veille et n'était appelée nulle part.)
            memoire_relire()
        except Exception as _re:
            logging.debug("[MEMOIRE] relecture : %s", _re)
        try:
            memoire_episodes_fermer_echus()   # une session abandonnée se ferme ici, pas au message suivant (20-09)
        except Exception as _re:
            logging.debug("[MEMOIRE] épisodes échus : %s", _re)
        try:
            sites_rapport_mensuel_passer()    # le 1er du mois, le rapport du mois écoulé part aux comptes (v2, 20-09)
        except Exception as _re:
            logging.debug("[SITES] rapports mensuels : %s", _re)
        try:
            _site_pass_periodique()           # LA SONDE DES SITES (20-09) : elle ne tournait qu'aux redémarrages
        except Exception as _re:
            logging.debug("[SITES] sonde périodique : %s", _re)
    except Exception:
        pass


def _all_user_domains() -> list:
    doms = set()
    try:
        for _e, v in load_users().items():
            for s in _user_record(v).get("sites", []):
                if s:
                    doms.add(_norm_domain(s))
    except Exception:
        pass
    return sorted(doms)


def _http_probe(domain: str) -> dict:
    url = "https://" + domain
    t0 = time.time()
    try:
        req = urllib.request.Request(url, method="GET",
                                     headers={"User-Agent": "Cassandra-HealthCheck/1.0"})
        with urllib.request.urlopen(req, timeout=10) as r:
            code = getattr(r, "status", 200); r.read(2048)
        return {"ok": True, "code": code, "ms": int((time.time() - t0) * 1000)}
    except urllib.error.HTTPError as e:
        return {"ok": e.code < 500, "code": e.code, "ms": int((time.time() - t0) * 1000)}
    except Exception as e:
        return {"ok": False, "code": 0, "ms": int((time.time() - t0) * 1000), "err": str(e)[:80]}


_DISK_TREND_HIST_MIN = 48 * 3600   # secondes d'histoire exigées avant de projeter


def _detect_disk_trend() -> list:
    """Régression linéaire sur l'espace libre des 7 derniers jours → date de saturation.

    48 HEURES D'HISTOIRE AVANT DE PROJETER (24-09). Sur une installation neuve, les premières heures
    voient pip, Docker et les modèles écrire des dizaines de Go d'un coup : une pente tirée de 2 h 30
    annonçait « disque plein dans ~10 j » sur 845 Go libres. Même leçon que metric_forecast."""
    out = []
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10); conn.row_factory = sqlite3.Row
        conn.execute("CREATE TABLE IF NOT EXISTS proactive_metrics (ts REAL PRIMARY KEY, "
                     "disk_pct REAL, disk_free_gb REAL, ram_pct REAL, load1 REAL)")
        rows = conn.execute("SELECT ts, disk_free_gb FROM proactive_metrics WHERE ts > ? "
                            "ORDER BY ts ASC", (time.time() - 7 * 86400,)).fetchall()
        conn.close()
        if len(rows) >= 6 and (rows[-1]["ts"] - rows[0]["ts"]) >= _DISK_TREND_HIST_MIN:
            x0 = rows[0]["ts"]
            xs = [(r["ts"] - x0) / 86400.0 for r in rows]
            ys = [float(r["disk_free_gb"] or 0) for r in rows]
            n = len(xs); sx = sum(xs); sy = sum(ys)
            sxx = sum(v * v for v in xs); sxy = sum(xs[i] * ys[i] for i in range(n))
            denom = n * sxx - sx * sx
            if denom:
                slope = (n * sxy - sx * sy) / denom   # Go/jour (négatif = se remplit)
                cur = ys[-1]
                if slope < -0.05 and cur > 0:
                    days = cur / (-slope)
                    if days < 14:
                        sev = "critical" if days < 4 else "warning"
                        out.append({"fkey": "disk_trend", "category": "disk", "severity": sev,
                                    "title": "Disque plein dans ~%d j" % int(days),
                                    "detail": "À ce rythme (%.2f Go/j), il reste %.1f Go : saturation dans ~%d jours."
                                              % (-slope, cur, int(days)),
                                    "suggested_action": "du -xh --max-depth=2 / 2>/dev/null | sort -rh | head -15",
                                    "action_kind": "diagnostic"})
    except Exception:
        pass
    return out


def _detect_sites_http() -> list:
    """Santé HTTP réelle des domaines gérés par les users (down / lent)."""
    out = []
    for dom in _all_user_domains():
        p = _http_probe(dom)
        if not p.get("ok"):
            out.append({"fkey": "site_http_%s" % dom, "category": "site_http", "severity": "critical",
                        "title": "Site %s injoignable" % dom,
                        "detail": "%s ne répond pas correctement (code %s%s)."
                                  % (dom, p.get("code"), (", " + p["err"]) if p.get("err") else ""),
                        # 10-10 : la relance du service qui sert les sites, puis la preuve (le site répond de nouveau).
                        "suggested_action": "relancer-site %s" % dom, "action_kind": "site.relancer"})
        elif p.get("ms", 0) > 5000:
            out.append({"fkey": "site_slow_%s" % dom, "category": "site_http", "severity": "warning",
                        "title": "Site %s lent (%.1fs)" % (dom, p["ms"] / 1000.0),
                        "detail": "%s répond en %d ms (> 5 s) — surcharge ou souci backend." % (dom, p["ms"]),
                        "suggested_action": "", "action_kind": "diagnostic"})
    return out


def _detect_sauvegardes_echec() -> list:
    """Un plan de sauvegarde de Cassandra dont la dernière exécution a échoué n'est retenté qu'à sa période suivante :
    c'est parfois une semaine. Le constat porte la relance (règle « Hébergement › Relancer une sauvegarde en échec »)."""
    out = []
    try:
        for p in (sauv_plans(inclure_fp=False).get("plans") or []):
            if not int(p.get("actif") or 0) or str(p.get("moteur") or "") == "fastpanel":
                continue
            if str(p.get("dernier_res") or "").startswith("échec"):
                out.append({"fkey": "sauv_echec_%s" % p["id"], "category": "backup", "severity": "critical",
                            "title": "Sauvegarde en échec : %s" % p.get("nom", p["id"]),
                            "detail": "Dernière exécution : %s" % str(p.get("dernier_res"))[:200],
                            "suggested_action": "relancer-sauvegarde %s" % p["id"], "action_kind": "sauvegarde.relancer"})
    except Exception as e:
        logging.info("[PROACTIF] sauvegardes en échec : %s", e)
    return out


_CONT_NOM_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9_.-]{0,63}$")


def _docker_inspecter() -> list:
    """Tous les conteneurs (arrêtés compris), tels que `docker inspect` les décrit. [] si Docker est absent ou muet."""
    import shutil
    if not shutil.which("docker"):
        return []
    p = subprocess.run(["docker", "ps", "-aq"], capture_output=True, text=True, timeout=20)
    ids = (p.stdout or "").split()
    if p.returncode != 0 or not ids:
        return []
    q = subprocess.run(["docker", "inspect"] + ids[:60], capture_output=True, text=True, timeout=40)
    try:
        return json.loads(q.stdout or "[]") or []
    except Exception:
        return []


def _detect_conteneurs() -> list:
    """Règle « Conteneurs › Relancer un conteneur » : un conteneur en mauvaise santé, ou tombé en ERREUR depuis moins de 24 h.
    Un conteneur arrêté proprement (code 0) ou à la main n'est JAMAIS relancé : on ne contredit pas une décision."""
    out = []
    try:
        maintenant = datetime.utcnow()
        for c in _docker_inspecter():
            nom = str(c.get("Name") or "").lstrip("/")
            st = c.get("State") or {}
            if not _CONT_NOM_RE.match(nom):
                continue
            sante = str((st.get("Health") or {}).get("Status") or "")
            raison = ""
            if sante == "unhealthy":
                raison = "en mauvaise santé (« unhealthy »)"
            elif str(st.get("Status")) in ("exited", "dead") and int(st.get("ExitCode") or 0) != 0:
                try:
                    fin = datetime.strptime(str(st.get("FinishedAt") or "")[:19], "%Y-%m-%dT%H:%M:%S")
                    recent = (maintenant - fin).total_seconds() < 86400
                except Exception:
                    recent = False
                if recent:
                    raison = "tombé en erreur (code %s)" % st.get("ExitCode")
            if raison:
                out.append({"fkey": "conteneur_%s" % nom, "category": "service", "severity": "warning",
                            "title": "Conteneur %s %s" % (nom, raison),
                            "detail": "Le conteneur %s est %s. Une relance suffit souvent ; elle est vérifiée après coup." % (nom, raison),
                            "suggested_action": "relancer-conteneur %s" % nom, "action_kind": "conteneur.relancer"})
    except Exception as e:
        logging.info("[PROACTIF] conteneurs : %s", e)
    return out


def _aut_relancer_conteneur(nom: str) -> tuple:
    """(ok, détail). Relance un conteneur CONNU, puis prouve qu'il tourne et qu'il n'est pas « unhealthy »."""
    if not _CONT_NOM_RE.match(nom or ""):
        return False, "nom de conteneur illisible"
    connus = {str(c.get("Name") or "").lstrip("/") for c in _docker_inspecter()}
    if nom not in connus:
        return False, "conteneur inconnu de Docker : %s" % nom
    p = subprocess.run(["docker", "restart", "-t", "20", nom], capture_output=True, text=True, timeout=90)
    if p.returncode != 0:
        return False, "relance impossible : %s" % " ".join(((p.stderr or "") + (p.stdout or "")).split())[:160]
    etat = ""
    for _ in range(12):
        time.sleep(5)
        cur = next((c for c in _docker_inspecter() if str(c.get("Name") or "").lstrip("/") == nom), None)
        st = (cur or {}).get("State") or {}
        sante = str((st.get("Health") or {}).get("Status") or "")
        etat = "%s%s" % (st.get("Status", "?"), (" / " + sante) if sante else "")
        if st.get("Status") == "running" and sante in ("", "healthy"):
            return True, "%s relancé, il tourne (%s)" % (nom, etat)
        if st.get("Status") in ("exited", "dead"):
            break
    return False, "%s relancé mais ne va pas mieux (%s)" % (nom, etat)


def _aut_relancer_site(domaine: str) -> tuple:
    """Relance ce qui sert les sites, puis VÉRIFIE que le site répond de nouveau. (ok, détail).
    nginx arrêté : on le relance ; sinon php-fpm. Une relance qui ne rend pas le site est un échec : le disjoncteur compte."""
    quoi = "php-fpm"
    try:
        if (fp_service_state("nginx") or {}).get("active") != "active":
            quoi = "nginx"
    except Exception:
        pass
    r = fp_service_action(quoi, "restart", confirm=True) or {}
    if not r.get("ok"):
        return False, "%s : relance impossible (%s)" % (quoi, str(r.get("reason") or r.get("error") or "?")[:120])
    time.sleep(4)
    pr = _http_probe(domaine)
    if pr.get("ok"):
        return True, "%s relancé : %s répond de nouveau (code %s, %d ms)" % (quoi, domaine, pr.get("code"), pr.get("ms", 0))
    return False, "%s relancé, mais %s ne répond toujours pas (code %s)" % (quoi, domaine, pr.get("code"))


def _aut_sauvegarde_differee(pid, cle: str, eff: dict, sujet: str, titre: str) -> None:
    """Une sauvegarde dure jusqu'à une demi-heure : elle ne bloque pas la boucle proactive. Le disjoncteur, le journal
    et le récit sont écrits ICI, quand le résultat est connu."""
    ok, detail = False, ""
    try:
        r = sauv_plan_run(pid, blanc=False, confirm=True, acteur="cassandra") or {}
        ok, detail = bool(r.get("ok")), str(r.get("resultat") or r.get("reason") or "")[:240]
    except Exception as e:
        detail = "erreur : %s" % str(e)[:200]
    try:
        aut_disj_resultat(cle, sujet, ok, eff)
        aut_journaliser(cle, sujet, ok, titre, detail, eff)
        aut_raconter(cle, sujet, ok, titre, detail, eff)
    except Exception as e:
        logging.info("[AUTONOMIE] sauvegarde différée : %s", e)


def _detect_backups() -> list:
    """Sauvegardes FastPanel manquantes ou trop anciennes (best-effort via mogwai JSON), et plans de Cassandra
    dont la dernière exécution a échoué (la relance est alors le geste proposé)."""
    out = list(_detect_sauvegardes_echec())
    try:
        data = _mogwai_json("backups", "list")
    except Exception:
        data = None
    if not isinstance(data, list) or not data:
        return out
    newest = 0.0
    for b in data:
        for k in ("created_at", "created", "date", "finished_at", "timestamp"):
            v = b.get(k) if isinstance(b, dict) else None
            if not v:
                continue
            try:
                ts = float(v) if str(v).replace(".", "").isdigit() else \
                    datetime.strptime(str(v)[:19], "%Y-%m-%d %H:%M:%S").timestamp()
                newest = max(newest, ts)
            except Exception:
                pass
    if newest:
        age_d = (time.time() - newest) / 86400.0
        if age_d > 8:
            out.append({"fkey": "backup_stale", "category": "backup", "severity": "warning",
                        "title": "Dernière sauvegarde il y a %d j" % int(age_d),
                        "detail": "La sauvegarde la plus récente date de %d jours — vérifie la planification." % int(age_d),
                        "suggested_action": "", "action_kind": "diagnostic"})
    return out


def _maj_auto_etat() -> dict:
    """Les mises à jour automatiques tournent-elles ? Réglées (Unattended-Upgrade "1") ET passées il y a moins de
    36 h (le journal d'unattended-upgrades est écrit à chaque passage, même quand il n'a rien à poser)."""
    import io          # pas global dans ce fichier
    conf = ""
    try:
        for f in sorted(os.listdir("/etc/apt/apt.conf.d")):
            try:
                conf += io.open(os.path.join("/etc/apt/apt.conf.d", f), encoding="utf-8", errors="replace").read() + "\n"
            except Exception:
                pass
    except Exception:
        pass
    reglees = bool(re.search(r'Unattended-Upgrade\s+"1"', conf))
    try:
        age_h = (time.time() - os.path.getmtime("/var/log/unattended-upgrades/unattended-upgrades.log")) / 3600.0
    except Exception:
        age_h = None
    return {"reglees": reglees, "age_h": age_h, "saines": bool(reglees and age_h is not None and age_h < 36)}


def _detect_updates() -> list:
    """Mises à jour de sécurité en attente + redémarrage requis."""
    out = []
    try:
        # `grep -c` rend 1 quand il compte zéro : un serveur sain faisait un
        # faux échec à chaque passage, et le journal de la cage s'en remplissait.
        r = secure_execute("apt-get -s upgrade 2>/dev/null | grep -c '^Inst.*[Ss]ecurity' || true")
        n = int((r or "0").strip().split("\n")[0] or 0)
    except Exception:
        n = 0
    # QUAND L'AUTOMATE TOURNE, IL N'Y A RIEN À FAIRE (07-10) : un paquet en attente sera posé au prochain passage
    # du matin. On ne prévient que si les mises à jour automatiques ne sont pas réglées, ou se sont arrêtées.
    auto = _maj_auto_etat()
    if n > 0 and not auto["saines"]:
        pourquoi = ("les mises à jour automatiques ne sont pas activées" if not auto["reglees"] else
                    ("elles ne sont pas passées depuis %d h" % int(auto["age_h"]) if auto["age_h"] is not None
                     else "leur journal est introuvable"))
        out.append({"fkey": "apt_security", "category": "updates", "severity": "warning",
                    "title": "%d mise(s) à jour de sécurité en attente" % n,
                    "detail": "%d paquet(s) de sécurité attendent, et %s." % (n, pourquoi),
                    "suggested_action": "apt-get update && apt-get -y upgrade", "action_kind": "diagnostic"})
    if os.path.exists("/var/run/reboot-required"):
        out.append({"fkey": "reboot_required", "category": "updates", "severity": "warning",
                    "title": "Redémarrage requis",
                    "detail": "Le noyau ou des paquets critiques ont été mis à jour — un redémarrage est nécessaire.",
                    "suggested_action": "", "action_kind": "diagnostic"})
    return out


def _detect_db() -> list:
    """Connexions MySQL/MariaDB proches de la limite (best-effort, auth socket root)."""
    out = []
    try:
        # PAR LE CATALOGUE, pas par le shell : la cage n'a pas la socket mysql,
        # et cette mesure échouait à chaque passage — un rc=1 permanent qui
        # aurait masqué une vraie panne. La lecture MySQL a sa route.
        rc, txt = _mysql_lecture({"requete": "SELECT @@max_connections, "
                                             "(SELECT COUNT(*) FROM information_schema.PROCESSLIST)"})
        lignes = [l for l in (txt or "").splitlines() if " | " in l]
        parts = [x.strip() for x in lignes[1].split(" | ")] if rc == 0 and len(lignes) >= 2 else []
        if len(parts) >= 2 and parts[0].isdigit() and parts[1].isdigit():
            maxc = int(parts[0]); cur = int(parts[1])
            if maxc and cur / maxc >= 0.8:
                out.append({"fkey": "db_conn", "category": "database", "severity": "warning",
                            "title": "BDD : %d/%d connexions" % (cur, maxc),
                            "detail": "MySQL/MariaDB utilise %d connexions sur %d (> 80 %%)." % (cur, maxc),
                            "suggested_action": "", "action_kind": "diagnostic"})
    except Exception:
        pass
    return out


def _detect_collector() -> list:
    """Collecteur silencieux : si la base de connaissance n'est plus écrite depuis trop
    longtemps, Cassandra raisonne sur un Sensorium périmé sans le savoir. Détection via le
    mtime du WAL (écrit à chaque cycle) — robuste et sans souci de fuseau horaire."""
    out = []
    age_min = None
    try:
        mt = 0.0
        for _p in (DB_PATH + "-wal", DB_PATH):
            try:
                mt = max(mt, os.path.getmtime(_p))
            except Exception:
                pass
        if mt > 0:
            age_min = (time.time() - mt) / 60.0
    except Exception:
        age_min = None
    thresh = float(_mem_cfg("collector_stale_min", 20))
    if age_min is not None and age_min > thresh:
        out.append({"fkey": "collector_stale", "category": "service", "severity": "warning",
                    "title": "Collecteur de connaissance silencieux",
                    "detail": "Aucune écriture depuis %d min — le Sensorium (état système) peut être périmé."
                              % int(age_min),
                    # 10-10 : une relance suffit presque toujours, et elle est réversible : le constat porte
                    # désormais l'action (règle « Machine › Relancer le collecteur »). Le diagnostic reste lisible
                    # dans le détail du constat.
                    "suggested_action": "systemctl restart cassandra-collector",
                    "action_kind": "service.restart"})
    return out


# Le détail du dernier passage, détecteur par détecteur. Il ne sert qu'à la
# note de scan, mais il change tout : sans lui, un détecteur ÉTEINT et un
# détecteur qui ne trouve rien se ressemblent exactement.
_PF_DETAIL = [[]]
_PF_DETECTEURS = (
    ("disk", "Disque", "proactive_watch_disk", "_detect_disk"),
    ("disk_trend", "Pente du disque", "proactive_watch_disk", "_detect_disk_trend"),
    ("pieces", "Pièces jointes", "proactive_watch_pieces", "_detect_pieces"),
    ("ssl", "Certificats", "proactive_watch_ssl", "_detect_ssl"),
    ("service", "Services", "proactive_watch_service", "_detect_services"),
    ("security", "Sécurité", "proactive_watch_security", "_detect_security"),
    ("vault", "Coffre-fort", "proactive_watch_vault", "_detect_vault"),
    ("sites", "Sites", "proactive_watch_sites", "_detect_sites_http"),
    ("backups", "Sauvegardes", "proactive_watch_backups", "_detect_backups"),
    ("updates", "Mises à jour", "proactive_watch_updates", "_detect_updates"),
    ("db", "Bases de données", "proactive_watch_db", "_detect_db"),
    ("collector", "Collecteur", "proactive_watch_collector", "_detect_collector"),
    ("ssh", "Clés SSH", "proactive_watch_ssh", "_detect_cles_ssh_anciennes"),
    ("conteneurs", "Conteneurs", "proactive_watch_containers", "_detect_conteneurs"),
)


def _proactive_detect_all() -> list:
    findings = []
    detail = []
    for cle, nom, drapeau, fn_nom in _PF_DETECTEURS:
        if not _mem_cfg(drapeau, True):
            detail.append({"cle": cle, "nom": nom, "etat": "éteint", "n": 0, "ms": 0,
                           "detail": "désactivé dans les réglages"})
            continue
        f = globals().get(fn_nom)
        if not callable(f):
            detail.append({"cle": cle, "nom": nom, "etat": "absent", "n": 0, "ms": 0,
                           "detail": "détecteur introuvable dans le programme"})
            continue
        t0 = time.time()
        try:
            r = f() or []
            findings += r
            detail.append({"cle": cle, "nom": nom, "etat": "vu", "n": len(r),
                           "ms": int((time.time() - t0) * 1000), "detail": ""})
        except Exception as e:
            # Un détecteur qui plante rendait une liste vide et se confondait
            # avec « rien à signaler ». C'est le pire silence qui soit.
            detail.append({"cle": cle, "nom": nom, "etat": "échec", "n": 0,
                           "ms": int((time.time() - t0) * 1000),
                           "detail": str(e)[:200]})
            logging.warning("[PROACTIF] détecteur %s : %s", cle, e)
    _PF_DETAIL[0] = detail
    return findings


# ══════════════════════════════════════════════════════════════════════════════
#  PROACTIVITÉ — le récit, et l'autonomie qui se gagne
#
#  Onze détecteurs existaient déjà, avec leurs découvertes, leur corrélation et
#  leurs playbooks. Ce qui manquait n'était pas un détecteur de plus :
#
#    · l'INCIDENT — cinq anomalies entre 02:58 et 03:14 racontent une histoire,
#      et chacune vivait seule avec son statut ;
#    · le FIL — six journaux disaient chacun un bout de la nuit, et « pourquoi
#      le site est tombé à 03:12 » n'avait de réponse dans aucun ;
#    · la PROJECTION — les pentes étaient mesurées pour déclencher une alerte au
#      dépassement, jamais pour dire la date ;
#    · le SAVOIR-FAIRE MESURÉ — l'autonomie était une case à cocher, pas une
#      confiance qui s'acquiert geste par geste.
# ══════════════════════════════════════════════════════════════════════════════
_PF_MIGRE = [False]
_PF_PALIERS = ("observer", "proposer", "maitrise", "raconter")
_PF_PALIER_NOM = {
    "observer": "Observer — elle remarque et prévient, elle n'agit jamais",
    "proposer": "Proposer — elle prépare le geste et attend un appui",
    "maitrise": "Agir sur ce qu'elle maîtrise — savoir-faire éprouvés seulement",
    "raconter": "Agir puis raconter — tout ce qui est réversible",
}
# Un savoir devient éprouvé à dix réussites, et retombe à deux échecs d'affilée.
_PF_SEUIL_PROMO = 10
_PF_SEUIL_RETRO = 2


def _pf_migrate():
    if _PF_MIGRE[0]:
        return
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        conn.execute("CREATE TABLE IF NOT EXISTS pf_incidents ("
                     "id INTEGER PRIMARY KEY AUTOINCREMENT, cle TEXT, "
                     "ouvert_le TEXT DEFAULT (datetime('now')), ferme_le TEXT DEFAULT '', "
                     "titre TEXT DEFAULT '', cause TEXT DEFAULT '', "
                     "gravite TEXT DEFAULT 'warning', statut TEXT DEFAULT 'ouvert', "
                     "preuve TEXT DEFAULT '', duree_min INTEGER DEFAULT 0)")
        conn.execute("CREATE UNIQUE INDEX IF NOT EXISTS idx_pf_inc_cle ON pf_incidents(cle) "
                     "WHERE statut = 'ouvert'")
        conn.execute("CREATE TABLE IF NOT EXISTS pf_incident_liens ("
                     "incident_id INTEGER, fkey TEXT, role TEXT DEFAULT 'effet', "
                     "ts TEXT DEFAULT (datetime('now')), PRIMARY KEY (incident_id, fkey))")
        # Ce qu'elle AURAIT fait. Rien n'est exécuté : c'est la façon honnête
        # d'accorder de l'autonomie — la regarder travailler à vide, puis choisir.
        conn.execute("CREATE TABLE IF NOT EXISTS pf_ombre ("
                     "id INTEGER PRIMARY KEY AUTOINCREMENT, ts TEXT DEFAULT (datetime('now')), "
                     "fkey TEXT, signature TEXT, action_kind TEXT, action TEXT, "
                     "titre TEXT DEFAULT '', motif TEXT DEFAULT '', "
                     "verdict TEXT DEFAULT '', avis TEXT DEFAULT '')")
        conn.execute("CREATE TABLE IF NOT EXISTS pf_savoir_props ("
                     "signature TEXT PRIMARY KEY, action_kind TEXT, action TEXT, "
                     "vu INTEGER DEFAULT 1, dernier TEXT DEFAULT (datetime('now')), "
                     "etat TEXT DEFAULT 'propose')")
        conn.execute("CREATE TABLE IF NOT EXISTS proactive_playbooks (signature TEXT PRIMARY KEY, "
                     "action_kind TEXT, action TEXT, successes INTEGER DEFAULT 0, "
                     "failures INTEGER DEFAULT 0, last_used TEXT, last_outcome TEXT)")
        for col, ddl in (("etat", "TEXT DEFAULT 'proposition'"),
                         ("echecs_suite", "INTEGER DEFAULT 0"),
                         ("reversible", "INTEGER DEFAULT 1"),
                         ("promu_le", "TEXT DEFAULT ''"),
                         ("nom", "TEXT DEFAULT ''")):
            try:
                conn.execute("ALTER TABLE proactive_playbooks ADD COLUMN %s %s" % (col, ddl))
            except Exception:
                pass
        conn.commit(); conn.close()
        _PF_MIGRE[0] = True
    except Exception as e:
        logging.warning("[PROACTIF] migration : %s", e)


# ── L'autonomie : un palier et un budget, pas un interrupteur ──────────────
def pf_autonomie() -> dict:
    _pf_migrate()
    cfg = get_cassandra_config()
    p = str(cfg.get("pf_palier") or "")
    if p not in _PF_PALIERS:
        # Reprise du réglage d'avant : une case cochée valait « maîtrise ».
        p = "maitrise" if cfg.get("proactive_auto_remediate") else "proposer"
    return {"palier": p, "palier_nom": _PF_PALIER_NOM[p],
            "budget_jour": int(cfg.get("pf_budget_jour", 9) or 9),
            "budget_sujet": int(cfg.get("pf_budget_sujet", 3) or 3),
            "pause_debut": str(cfg.get("pf_pause_debut", "09:00")),
            "pause_fin": str(cfg.get("pf_pause_fin", "18:00")),
            "pause": bool(cfg.get("pf_pause", True)),
            "reversible": bool(cfg.get("pf_reversible", True)),
            "instantane": bool(cfg.get("pf_instantane", True)),
            "retrograde": bool(cfg.get("pf_retrograde", True)),
            "utilise": pf_budget_utilise(), "paliers": list(_PF_PALIERS),
            "noms": _PF_PALIER_NOM}


def pf_autonomie_set(d: dict, acteur: str = "") -> dict:
    _pf_migrate()
    p = str(d.get("palier", ""))
    if p and p not in _PF_PALIERS:
        return {"ok": False, "reason": "palier inconnu"}
    cfg = get_cassandra_config()
    if p:
        cfg["pf_palier"] = p
        # L'ancien drapeau reste synchronisé : d'autres passages le lisent.
        cfg["proactive_auto_remediate"] = p in ("maitrise", "raconter")
    for k, borne in (("pf_budget_jour", (0, 100)), ("pf_budget_sujet", (0, 20))):
        if k in d:
            cfg[k] = max(borne[0], min(borne[1], int(d.get(k) or 0)))
    for k in ("pf_pause", "pf_reversible", "pf_instantane", "pf_retrograde"):
        if k in d:
            cfg[k] = bool(d[k])
    for k in ("pf_pause_debut", "pf_pause_fin"):
        if k in d:
            cfg[k] = str(d[k])[:5]
    save_cassandra_config(cfg)
    try:
        log_user_activity(acteur, acteur, "pf_autonomie", p or "réglages")
    except Exception:
        pass
    return {"ok": True, "autonomie": pf_autonomie()}


def pf_budget_utilise() -> dict:
    _pf_migrate()
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        n = conn.execute("SELECT COUNT(*) FROM proactive_findings WHERE acted_at >= "
                         "date('now') AND status='acted'").fetchone()[0]
        conn.close()
        return {"jour": n}
    except Exception:
        return {"jour": 0}


def _pf_en_pause() -> bool:
    a = pf_autonomie()
    if not a["pause"]:
        return False
    h = datetime.now().strftime("%H:%M")
    d, f = a["pause_debut"], a["pause_fin"]
    return (d <= h < f) if d < f else (h >= d or h < f)


# ════════════════════════════════════════════════════════
#  L'AUTONOMIE PAR DOMAINE ET PAR GESTE (10-10)
#
#  Un seul curseur pour tout (le palier global) ne disait pas « sur ce sujet agis seule, sur celui-là
#  demande ». Ici : un catalogue de domaines et de gestes (la liste validée sur maquette), un réglage par
#  domaine et par geste (SQLite, pas config.json : « la sauvegarde remplace TOUT le fichier »), des
#  DISJONCTEURS à la place du plafond par jour, et chaque action autonome inscrite au journal avec la règle
#  qui l'a permise.
#
#  Rien ne change tant qu'on ne règle rien : un geste sans réglage retombe sur le palier global, comme avant.
#  Les gestes « à brancher » ou « à écrire » ne SAVENT pas encore agir : leur palier est borné à « proposer ».
#  Un geste « garde dure » reste à « proposer », quoi qu'on écrive.
# ════════════════════════════════════════════════════════
