_AUT_INDEX = {}


def _aut_index() -> dict:
    """cle -> (domaine, geste) ; « d:<dom> » pour un domaine, « g:<dom>/<geste> » pour un geste."""
    if not _AUT_INDEX:
        for did, dnom, ddesc, gestes in _AUT_CATALOGUE:
            _AUT_INDEX["d:" + did] = {"domaine": did, "nom": dnom, "desc": ddesc}
            for gid, gnom, st, rev, garde in gestes:
                _AUT_INDEX["g:%s/%s" % (did, gid)] = {"domaine": did, "geste": gid, "nom": gnom, "st": st,
                                                       "rev": rev, "garde": garde, "dnom": dnom}
    return _AUT_INDEX


def aut_libelle(cle: str) -> str:
    """« Machine › Relancer un service » pour « machine/relancer-un-service »."""
    e = _aut_index().get("g:" + str(cle or ""))
    return ("%s › %s" % (e["dnom"], e["nom"])) if e else str(cle or "")


def _aut_conn():
    conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
    conn.row_factory = sqlite3.Row
    conn.execute("CREATE TABLE IF NOT EXISTS autonomie_reglages (cle TEXT PRIMARY KEY, reglages TEXT NOT NULL, "
                 "ts TEXT DEFAULT (datetime('now','localtime')), par TEXT DEFAULT '')")
    conn.execute("CREATE TABLE IF NOT EXISTS autonomie_disj (cle TEXT PRIMARY KEY, etat TEXT NOT NULL DEFAULT 'arme', "
                 "raison TEXT DEFAULT '', depuis TEXT DEFAULT '', echecs_suite INTEGER DEFAULT 0)")
    conn.execute("CREATE TABLE IF NOT EXISTS autonomie_actions (id INTEGER PRIMARY KEY AUTOINCREMENT, ts REAL NOT NULL, "
                 "cle TEXT NOT NULL, sujet TEXT DEFAULT '', ok INTEGER)")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_aut_act ON autonomie_actions(cle, sujet, ts)")
    return conn


def _aut_ecrire(fn, essais: int = 4):
    """Exécute `fn(conn)` dans UNE transaction d'écriture prise d'entrée (BEGIN IMMEDIATE), et la rejoue si la base est
    occupée. En mode WAL, lire PUIS écrire sur la même connexion échoue sur-le-champ (« database is locked », sans
    attendre le délai) dès qu'un autre écrivain a commité entre les deux : prendre le verrou avant de lire l'évite.
    Une occupation est inscrite au journal : c'est la seule façon de savoir qui gêne."""
    derniere = None
    for i in range(essais):
        conn = _aut_conn()
        try:
            conn.execute("BEGIN IMMEDIATE")
            r = fn(conn)
            conn.commit()
            return r
        except sqlite3.OperationalError as e:
            derniere = e
            try:
                conn.rollback()
            except Exception:
                pass
            if "lock" not in str(e).lower() and "busy" not in str(e).lower():
                raise
            logging.warning("[AUTONOMIE] base occupée (essai %d/%d) : %s", i + 1, essais, e)
            time.sleep(0.4 * (i + 1))
        finally:
            conn.close()
    raise derniere


def aut_reglages_lire() -> dict:
    try:
        conn = _aut_conn()
        try:
            out = {}
            for r in conn.execute("SELECT cle, reglages FROM autonomie_reglages"):
                try:
                    out[r["cle"]] = json.loads(r["reglages"] or "{}")
                except Exception:
                    out[r["cle"]] = {}
            return out
        finally:
            conn.close()
    except Exception as e:
        logging.info("[AUTONOMIE] lecture des réglages : %s", e)
        return {}


def aut_regler(cle: str, reglages: dict, acteur: str = "") -> dict:
    ent = _aut_index().get(str(cle or ""))
    if not ent:
        return {"ok": False, "error": "domaine ou geste inconnu"}
    est_geste = "geste" in ent
    propres = {}
    for k, v in (reglages or {}).items():
        if k not in _AUT_DEFAUT:
            return {"ok": False, "error": "réglage inconnu : %s" % str(k)[:40]}
        if not est_geste and k not in ("lv", "per", "persel"):
            return {"ok": False, "error": "un domaine ne porte que le palier et le périmètre"}
        if k == "lv":
            if v in (None, ""):
                propres[k] = None
            elif v not in _PF_PALIERS:
                return {"ok": False, "error": "palier inconnu"}
            elif est_geste and ent["st"] in ("dur", "ecrire") and _PF_PALIERS.index(v) > _PF_PALIERS.index("proposer"):
                return {"ok": False, "error": "ce geste %s : il ne peut pas dépasser « proposer »" %
                        ("est en garde dure" if ent["st"] == "dur" else "n'existe pas encore")}
            else:
                propres[k] = v
        elif k in ("ombre", "avis", "snap"):
            propres[k] = None if v is None else bool(v)
        elif k in ("ech", "boucle"):
            try:
                n = int(v)
            except Exception:
                return {"ok": False, "error": "%s : un nombre est attendu" % k}
            borne = (1, 5) if k == "ech" else (1, 10)
            if not borne[0] <= n <= borne[1]:
                return {"ok": False, "error": "%s : entre %d et %d" % (k, borne[0], borne[1])}
            propres[k] = n
        elif k in ("fd", "ff"):
            if not re.fullmatch(r"([01]\d|2[0-3]):[0-5]\d", str(v or "")):
                return {"ok": False, "error": "%s : une heure HH:MM est attendue" % k}
            propres[k] = str(v)
        elif k in ("excl", "persel"):
            propres[k] = str(v or "")[:300]
        elif k == "aviq":
            propres[k] = str(v or _AUT_DEFAUT["aviq"])[:120]
        else:                                   # decl, per, fen, boucleh, ou, nuit : une liste fermée
            if str(v) not in _AUT_CHOIX[k]:
                return {"ok": False, "error": "%s : valeur inconnue" % k}
            propres[k] = str(v)
    def _ecrire(conn):
        row = conn.execute("SELECT reglages FROM autonomie_reglages WHERE cle = ?", (cle,)).fetchall()
        actuel = json.loads(row[0]["reglages"]) if row else {}
        actuel.update(propres)
        actuel = {k: v for k, v in actuel.items() if v != _AUT_DEFAUT.get(k)}
        if actuel:
            conn.execute("INSERT INTO autonomie_reglages (cle, reglages, par) VALUES (?,?,?) "
                         "ON CONFLICT(cle) DO UPDATE SET reglages = excluded.reglages, par = excluded.par, "
                         "ts = datetime('now','localtime')", (cle, json.dumps(actuel, ensure_ascii=False), acteur or ""))
        else:
            conn.execute("DELETE FROM autonomie_reglages WHERE cle = ?", (cle,))
    try:
        _aut_ecrire(_ecrire)
    except Exception as e:
        return {"ok": False, "error": "enregistrement impossible : %s" % str(e)[:120]}
    try:
        log_user_activity(acteur, acteur, "autonomie_regler", "%s %s" % (cle, json.dumps(propres, ensure_ascii=False)[:160]))
    except Exception:
        pass
    return {"ok": True}


def aut_remettre(cle: str, acteur: str = "") -> dict:
    if str(cle or "") not in _aut_index():
        return {"ok": False, "error": "domaine ou geste inconnu"}
    try:
        _aut_ecrire(lambda conn: conn.execute("DELETE FROM autonomie_reglages WHERE cle = ?", (cle,)))
    except Exception as e:
        return {"ok": False, "error": str(e)[:120]}
    return {"ok": True}


def aut_effectif(cle: str, reglages: dict = None) -> dict:
    """Ce qui s'applique à ce geste : le sien, sinon celui de son domaine, sinon le palier global."""
    ent = _aut_index().get("g:" + str(cle or ""))
    if not ent:
        return {}
    regl = reglages if reglages is not None else aut_reglages_lire()
    g = regl.get("g:" + cle, {})
    d = regl.get("d:" + ent["domaine"], {})
    eff = dict(_AUT_DEFAUT)
    eff.update({k: v for k, v in g.items() if k in _AUT_DEFAUT})
    lv = g.get("lv") or d.get("lv")
    origine = "geste" if g.get("lv") else ("domaine" if d.get("lv") else "global")
    if not lv:
        try:
            lv = pf_autonomie()["palier"]
        except Exception:
            lv = "proposer"
    borne = lv
    if ent["st"] in ("dur", "ecrire") and _PF_PALIERS.index(lv) > _PF_PALIERS.index("proposer"):
        borne = "proposer"
    if eff["per"] == _AUT_DEFAUT["per"] and d.get("per"):
        eff["per"] = d["per"]
    eff.update({"palier": borne, "palier_voulu": lv, "origine": origine, "st": ent["st"], "rev": ent["rev"],
                "cle": cle, "libelle": aut_libelle(cle)})
    return eff


def _aut_fenetre_ok(eff: dict) -> bool:
    f = eff.get("fen")
    if f == "Toujours":
        return True
    h = datetime.now().strftime("%H:%M")
    if f == "Plage horaire":
        d, e = eff.get("fd", "02:00"), eff.get("ff", "06:00")
        return (d <= h < e) if d < e else (h >= d or h < e)
    if f == "Hors heures ouvrées":
        return not (str(_mem_cfg("pf_pause_debut", "09:00")) <= h < str(_mem_cfg("pf_pause_fin", "18:00")))
    return True


def _aut_declenche(cle: str, raison: str) -> None:
    def _ecrire(conn):
        conn.execute("INSERT INTO autonomie_disj (cle, etat, raison, depuis, echecs_suite) VALUES (?, 'declenche', ?, "
                     "datetime('now','localtime'), 0) ON CONFLICT(cle) DO UPDATE SET etat = 'declenche', raison = excluded.raison, "
                     "depuis = excluded.depuis", (cle, raison[:240]))
    _aut_ecrire(_ecrire)
    try:
        notif("Disjoncteur déclenché : %s" % aut_libelle(cle),
              "%s. Cette règle ne fait plus rien seule ; tu la débloques dans Proactivité › Règles quand la cause est réglée." % raison,
              source="veille", niveau="avoir", cle="aut:disj:%s" % cle)
    except Exception as e:
        logging.info("[AUTONOMIE] notification du disjoncteur : %s", e)


def aut_disj_verifier(cle: str, sujet: str, eff: dict):
    """Un motif de refus si le disjoncteur est déclenché, ou s'il se déclenche à l'instant (boucle) ; sinon None."""
    try:
        conn = _aut_conn()
        try:
            r = conn.execute("SELECT etat, raison FROM autonomie_disj WHERE cle = ?", (cle,)).fetchall()
            if r and r[0]["etat"] == "declenche":
                return "disjoncteur déclenché : %s" % (r[0]["raison"] or "?")
            heures = {"1 h": 1, "6 h": 6, "24 h": 24}.get(eff.get("boucleh"), 1)
            n = conn.execute("SELECT COUNT(*) FROM autonomie_actions WHERE cle = ? AND sujet = ? AND ts > ?",
                             (cle, sujet or "", time.time() - heures * 3600)).fetchall()[0][0]
        finally:
            conn.close()
        if n >= int(eff.get("boucle") or 3):
            raison = "boucle : %d actions sur « %s » en %s" % (n, (sujet or "?")[:60], eff.get("boucleh"))
            _aut_declenche(cle, raison)
            return "disjoncteur déclenché : %s" % raison
    except Exception as e:
        logging.info("[AUTONOMIE] vérification du disjoncteur : %s", e)
    return None


def aut_disj_resultat(cle: str, sujet: str, ok: bool, eff: dict) -> None:
    def _ecrire(conn):
        conn.execute("INSERT INTO autonomie_actions (ts, cle, sujet, ok) VALUES (?,?,?,?)",
                     (time.time(), cle, sujet or "", 1 if ok else 0))
        conn.execute("DELETE FROM autonomie_actions WHERE ts < ?", (time.time() - 3 * 86400,))
        r = conn.execute("SELECT echecs_suite FROM autonomie_disj WHERE cle = ?", (cle,)).fetchall()
        suite = 0 if ok else ((r[0]["echecs_suite"] if r else 0) or 0) + 1
        conn.execute("INSERT INTO autonomie_disj (cle, etat, echecs_suite) VALUES (?, 'arme', ?) "
                     "ON CONFLICT(cle) DO UPDATE SET echecs_suite = excluded.echecs_suite", (cle, suite))
        return suite
    try:
        suite = _aut_ecrire(_ecrire)
        if not ok and suite >= int(eff.get("ech") or 2):
            _aut_declenche(cle, "%d échecs d'affilée (dernier sujet : %s)" % (suite, (sujet or "?")[:60]))
    except Exception as e:
        logging.info("[AUTONOMIE] résultat : %s", e)


def aut_debloquer(cle: str, acteur: str = "") -> dict:
    if "g:" + str(cle or "") not in _aut_index():
        return {"ok": False, "error": "geste inconnu"}
    def _ecrire(conn):
        conn.execute("UPDATE autonomie_disj SET etat = 'arme', raison = '', echecs_suite = 0 WHERE cle = ?", (cle,))
        conn.execute("DELETE FROM autonomie_actions WHERE cle = ?", (cle,))
    try:
        _aut_ecrire(_ecrire)
    except Exception as e:
        return {"ok": False, "error": str(e)[:120]}
    try:
        notif_resoudre_cle("aut:disj:%s" % cle, par=acteur or "vous", detail="disjoncteur débloqué")
    except Exception:
        pass
    try:
        conn = _sec_gestes_conn()
        try:
            conn.execute("INSERT INTO gestes_humains (qui, geste, cible, detail, ok, resultat, defaire) VALUES (?,?,?,?,?,?,?)",
                         (acteur or "?", "aut:debloquer", aut_libelle(cle), "disjoncteur débloqué", 1, "", ""))
            conn.commit()
        finally:
            conn.close()
    except Exception:
        pass
    return {"ok": True}


def aut_journaliser(cle: str, sujet: str, ok: bool, detail: str, resultat: str, eff: dict, defaire=None) -> None:
    """Une action autonome entre au journal « Qui a fait quoi », avec la règle qui l'a permise."""
    try:
        conn = _sec_gestes_conn()
        try:
            conn.execute("INSERT INTO gestes_humains (qui, geste, cible, detail, ok, resultat, defaire) VALUES (?,?,?,?,?,?,?)",
                         ("cassandra", "aut:" + cle, (sujet or "")[:120],
                          ("règle %s · palier %s%s" % (eff.get("libelle", cle), eff.get("palier", "?"),
                                                       (" · " + detail) if detail else ""))[:400],
                          1 if ok else 0, (resultat or "")[:400], json.dumps(defaire, ensure_ascii=False) if (defaire and ok) else ""))
            conn.commit()
        finally:
            conn.close()
    except Exception as e:
        logging.info("[AUTONOMIE] journal : %s", e)


# ── LA GOUVERNANCE TRANSVERSE (10-10) : ce qui vaut pour tous les gestes ──────────────────────────────
# Les intouchables, le second avis par défaut et son repli, le point de restauration. Une seule ligne dans
# `autonomie_reglages` (clé « gov »). Le récit passe, lui, par la politique du Centre de notifications.
_AUT_AVIS_SECOURS = ("Elle propose seulement", "Elle agit quand même si le geste est réversible", "Elle attend, sans rien faire")
_AUT_SNAP_MODES = ("Fichiers et base, avant chaque geste en plusieurs étapes", "Fichiers seulement")
# Par défaut : les appareils de Sandrine. « On n'écrit jamais chez l'autre » : Drisse le retire ou l'étend à sa guise.
_AUT_GOV_DEFAUT = {"avis_defaut": "", "avis_secours": _AUT_AVIS_SECOURS[0], "snap_mode": _AUT_SNAP_MODES[0],
                   "intouchables": ["ragnar", "iphone-sandrine"]}
_AUT_AVIS_CACHE = {}               # (cle, sujet, commande) -> (epoch, verdict) ; une demande d'avis se paie en secondes
_AUT_AVIS_TTL_S = 1800


def aut_gouvernance() -> dict:
    g = dict(_AUT_GOV_DEFAUT)
    g["intouchables"] = list(_AUT_GOV_DEFAUT["intouchables"])
    g.update({k: v for k, v in (aut_reglages_lire().get("gov") or {}).items() if k in _AUT_GOV_DEFAUT})
    return g


def aut_gouverner(champs: dict, acteur: str = "") -> dict:
    propres = {}
    for k, v in (champs or {}).items():
        if k not in _AUT_GOV_DEFAUT:
            return {"ok": False, "error": "réglage inconnu : %s" % str(k)[:40]}
        if k == "avis_secours":
            if v not in _AUT_AVIS_SECOURS:
                return {"ok": False, "error": "repli inconnu"}
            propres[k] = v
        elif k == "snap_mode":
            if v not in _AUT_SNAP_MODES:
                return {"ok": False, "error": "mode de restauration inconnu"}
            propres[k] = v
        elif k == "avis_defaut":
            propres[k] = str(v or "")[:160]
        elif k == "intouchables":
            if not isinstance(v, list):
                return {"ok": False, "error": "une liste est attendue"}
            propres[k] = [str(x).strip()[:120] for x in v if str(x).strip()][:200]
    def _ecrire(conn):
        row = conn.execute("SELECT reglages FROM autonomie_reglages WHERE cle = 'gov'").fetchall()
        actuel = json.loads(row[0]["reglages"]) if row else {}
        actuel.update(propres)
        conn.execute("INSERT INTO autonomie_reglages (cle, reglages, par) VALUES ('gov', ?, ?) "
                     "ON CONFLICT(cle) DO UPDATE SET reglages = excluded.reglages, par = excluded.par, "
                     "ts = datetime('now','localtime')", (json.dumps(actuel, ensure_ascii=False), acteur or ""))
    try:
        _aut_ecrire(_ecrire)
    except Exception as e:
        return {"ok": False, "error": "enregistrement impossible : %s" % str(e)[:120]}
    try:
        log_user_activity(acteur, acteur, "autonomie_gouverner", json.dumps(propres, ensure_ascii=False)[:200])
    except Exception:
        pass
    return {"ok": True}


def aut_correspond(liste, *textes) -> str:
    """La première entrée de la liste que ces textes nomment : un nom (mot entier), une adresse, un réseau CIDR.
    « ragnar (le PC de Sandrine) » vaut « ragnar »."""
    import ipaddress
    brut = " ".join(str(t or "") for t in textes).lower()
    if not brut.strip():
        return ""
    ips = []
    for m in re.findall(r"\b(?:\d{1,3}\.){3}\d{1,3}\b", brut):
        try:
            ips.append(ipaddress.ip_address(m))
        except Exception:
            pass
    for entree in (liste or []):
        nom = str(entree).split("(")[0].strip().lower()
        if not nom:
            continue
        try:
            reseau = ipaddress.ip_network(nom, strict=False)
            if any(ip in reseau for ip in ips):
                return str(entree)
            continue
        except Exception:
            pass
        if re.search(r"(?<![a-z0-9])" + re.escape(nom) + r"(?![a-z0-9])", brut):
            return str(entree)
    return ""


def _aut_exclusions(eff: dict) -> list:
    return [x.strip() for x in str(eff.get("excl") or "").split(",") if x.strip()]


_AUT_DOMAINE_RE = re.compile(r"(?<![a-z0-9.-])((?:[a-z0-9][a-z0-9-]*\.)+[a-z]{2,})(?![a-z0-9-])")


def _aut_machines_flotte() -> list:
    """Les machines du parc enregistrées dans la Flotte : tout ce qui n'est pas Orion."""
    try:
        return [str(x.get("name")) for x in (_ms_load() or []) if x.get("name")]
    except Exception:
        return []


def _aut_sites_maison():
    """Les sites de la maison : ceux du panneau qui n'appartiennent à AUCUN compte. None si on ne peut pas l'établir."""
    try:
        doms = {_norm_domain(str(d.get("domain") or "")) for d in (get_fp_domains() or []) if isinstance(d, dict) and d.get("domain")}
        comptes = set(_all_user_domains())
        return {d for d in doms if d and d not in comptes}
    except Exception:
        return None


def aut_perimetre_motif(eff: dict, sujet: str, titre: str = "", cmd: str = "") -> str:
    """Le périmètre du geste (« Orion seulement », « les sites de la maison », une sélection). Vide si la cible est dans la borne.
    « Hérite du domaine » ne borne rien. Une borne qu'on ne peut pas établir retient : dans le doute, elle ne touche pas."""
    per = str((eff or {}).get("per") or "")
    if per in ("", _AUT_DEFAUT["per"]):
        return ""
    texte = " ".join(str(t or "") for t in (sujet, titre, cmd))
    if per == "Orion seulement":
        hit = aut_correspond(_aut_machines_flotte(), texte)
        return "« %s » n'est pas Orion : ce geste est limité à Orion" % hit if hit else ""
    if per == "Les sites de la maison seulement":
        cibles = sorted(set(_AUT_DOMAINE_RE.findall(texte.lower())))
        if not cibles:
            return ""                                      # le geste ne vise pas un site : la borne ne le concerne pas
        maison = _aut_sites_maison()
        if maison is None:
            return "impossible d'établir quels sont les sites de la maison : elle ne touche à rien"
        hors = [d for d in cibles if d not in maison]
        return "« %s » n'est pas un site de la maison (ce geste y est limité)" % hors[0] if hors else ""
    if per == "Une sélection à choisir":
        sel = [x.strip() for x in str((eff or {}).get("persel") or "").replace(";", ",").split(",") if x.strip()]
        if not sel:
            return "périmètre « sélection » sans aucun nom choisi : elle ne touche à rien"
        return "" if aut_correspond(sel, texte) else "la cible n'est pas dans la sélection de ce geste"
    return ""


# Ce que chaque geste sauvegarde avant d'agir, EN PLUS des fichiers que sa commande réécrit.
_AUT_SNAP_FICHIERS = {"rotation-des-secrets/faire-tourner-une-cle-ssh": lambda: [MULTISERVER_CONFIG_FILE]}


def aut_snap_actif(eff: dict) -> bool:
    """Le point de restauration est-il demandé ? Le réglage du geste, sinon « partiellement réversible » ; coupé net si le réglage général
    « Instantané avant chaque action autonome » est décoché (sauf demande explicite du geste)."""
    snap = (eff or {}).get("snap")
    if snap is not None:
        return bool(snap)
    if not _mem_cfg("pf_instantane", True):
        return False
    return (eff or {}).get("rev") == "part"


def aut_point_restauration(g: dict, cmd: str = "") -> str:
    """Copie, avant le geste, les fichiers qu'il va modifier. Rend une phrase pour le journal (vide : rien à sauvegarder).
    Une copie qui échoue n'arrête pas le geste : elle est dite."""
    eff = (g or {}).get("eff") or {}
    cle = (g or {}).get("cle")
    if not cle or not aut_snap_actif(eff):
        return ""
    fichiers = []
    try:
        fichiers += _files_to_snapshot(cmd) if cmd else []
        if cle in _AUT_SNAP_FICHIERS:
            fichiers += _AUT_SNAP_FICHIERS[cle]()
    except Exception as e:
        logging.info("[AUTONOMIE] point de restauration : %s", e)
    ids, manque = [], []
    for fp in list(dict.fromkeys(fichiers))[:6]:
        try:
            if os.path.isfile(fp) and os.path.getsize(fp) < 300_000:
                with open(fp, "r", errors="replace") as fh:
                    contenu = fh.read()
                conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
                try:
                    cur = conn.execute("INSERT INTO file_snapshots (ts,session_id,trigger_command,file_path,content_before,action_id) "
                                       "VALUES (datetime('now'),?,?,?,?,0)", ("autonomie", ("%s %s" % (cle, g.get("sujet") or ""))[:500], fp, contenu))
                    conn.commit(); ids.append(cur.lastrowid)
                finally:
                    conn.close()
            else:
                manque.append(os.path.basename(fp))
        except Exception as e:
            manque.append("%s (%s)" % (os.path.basename(fp), str(e)[:40]))
    if not ids and not manque:
        return ""
    return "point de restauration n° %s%s" % (", ".join(str(i) for i in ids) or "—", (" · non sauvegardé : " + ", ".join(manque)) if manque else "")


def aut_retenue(eff: dict, sujet: str, titre: str = "", cmd: str = "", chemin: str = "alerte") -> str:
    """Un motif de refus tiré des règles de PORTÉE : intouchables, exclusions du geste, déclencheur. Vide si rien ne retient."""
    gov = aut_gouvernance()
    hit = aut_correspond(gov["intouchables"], sujet, titre, cmd)
    if hit:
        return "« %s » est dans les intouchables : aucune règle n'agit dessus" % hit
    hit = aut_correspond(_aut_exclusions(eff), sujet, titre, cmd)
    if hit:
        return "« %s » est exclu de « %s »" % (hit, eff.get("libelle", eff.get("cle", "?")))
    decl = eff.get("decl")
    if decl == "Sur demande seulement":
        return "déclencheur « sur demande seulement » : elle n'agit pas seule"
    return aut_perimetre_motif(eff, sujet, titre, cmd)


def _aut_modele_creds(label: str):
    """(clé, modèle, base, fournisseur) du modèle nommé par un libellé du menu « nom · fournisseur » / « nom · local »."""
    label = str(label or "").strip()
    if not label or label == _AUT_DEFAUT["aviq"]:
        label = aut_gouvernance().get("avis_defaut") or ""
    if not label:
        return None
    if label.endswith(" · local"):
        nom = label[:-len(" · local")]
        try:
            if ollama_available() and any(m["name"] == nom for m in (ollama_list() or [])):
                return ("ollama", nom, _ollama_base() + "/v1", "ollama")
        except Exception:
            pass
        return None
    if " · " in label:
        nom, fourn = label.rsplit(" · ", 1)
        try:
            conn = _modeles_conn()
            try:
                r = conn.execute("SELECT id FROM modeles_registre WHERE nom = ? AND fournisseur = ?", (nom, fourn)).fetchone()
            finally:
                conn.close()
            return modele_creds(r["id"]) if r else None
        except Exception:
            return None
    return None


def _aut_lire_avis(texte: str):
    """('oui'|'non', raison) tiré de la réponse du relecteur, ou None si elle ne se lit pas."""
    t = str(texte or "")
    m = re.search(r"\{.*\}", t, re.S)
    if m:
        try:
            j = json.loads(m.group(0))
            a = str(j.get("avis") or j.get("verdict") or "").strip().lower()
            if a in ("oui", "non"):
                return a, str(j.get("raison") or j.get("reason") or "")[:240]
        except Exception:
            pass
    mots = re.findall(r"\b(oui|non)\b", t.lower())
    if len(set(mots)) == 1:
        return mots[0], t.strip()[:240]
    return None


def aut_second_avis(eff: dict, sujet: str, titre: str, cmd: str) -> dict:
    """Un modèle relit le geste AVANT qu'il parte. Rend {ok, raison, modele, dispo}. `dispo` est faux quand aucun
    avis n'a pu être obtenu : c'est le repli de la gouvernance qui tranche alors, pas un silence."""
    cle = eff.get("cle", "")
    k = (cle, str(sujet or ""), str(cmd or ""))
    c = _AUT_AVIS_CACHE.get(k)
    if c and time.time() - c[0] < _AUT_AVIS_TTL_S:
        return c[1]
    creds = _aut_modele_creds(eff.get("aviq"))
    if not creds:
        v = {"ok": False, "dispo": False, "raison": "aucun modèle de second avis n'est choisi ou joignable", "modele": ""}
        _AUT_AVIS_CACHE[k] = (time.time() - _AUT_AVIS_TTL_S + 120, v)     # on retente dans deux minutes
        return v
    consigne = ("Tu es le second avis d'un agent qui administre un serveur Linux. L'agent s'apprête à exécuter un geste. "
                "Dis s'il est raisonnable de le laisser partir SEUL, sans demander à l'humain. Sois prudent : au moindre "
                "doute sur la commande, sa cible, sa réversibilité ou sa cause, réponds non.\n"
                "Réponds par UN SEUL objet JSON, rien d'autre : {\"avis\": \"oui\" ou \"non\", \"raison\": \"une phrase\"}.")
    contexte = ("Règle : %s\nGeste réversible : %s\nSujet : %s\nCause constatée : %s\nCommande : %s"
                % (eff.get("libelle", cle), {"oui": "oui", "part": "en partie", "non": "non"}.get(eff.get("rev"), "?"),
                   str(sujet or "")[:160], str(titre or "")[:200], str(cmd or "")[:300]))
    txt = ""
    try:
        txt = _itare_agent_text([{"role": "user", "content": contexte}], system=consigne, max_tokens=500, temperature=0.0,
                                timeout=60.0, reflexion=False, creds=creds)
    except Exception as e:
        logging.info("[AUTONOMIE] second avis : %s", e)
    lu = _aut_lire_avis(txt)
    modele = "%s (%s)" % (creds[1], creds[3])
    if not lu:
        v = {"ok": False, "dispo": False, "raison": "le second avis n'a pas répondu de façon lisible", "modele": modele}
        _AUT_AVIS_CACHE[k] = (time.time() - _AUT_AVIS_TTL_S + 120, v)
        return v
    v = {"ok": lu[0] == "oui", "dispo": True, "raison": lu[1], "modele": modele}
    _AUT_AVIS_CACHE[k] = (time.time(), v)
    return v


def aut_avis_requis(eff: dict) -> bool:
    if eff.get("avis") is not None:
        return bool(eff["avis"])
    return eff.get("rev") != "oui"          # par défaut : tout ce qui n'est pas pleinement réversible


def aut_avis_porte(eff: dict, sujet: str, titre: str, cmd: str) -> str:
    """Un motif de refus issu du second avis (ou de son repli), vide si le geste peut partir."""
    if not aut_avis_requis(eff):
        return ""
    v = aut_second_avis(eff, sujet, titre, cmd)
    eff["avis_rendu"] = v
    if v.get("dispo"):
        return "" if v["ok"] else "second avis négatif (%s) : %s" % (v.get("modele", "?"), v.get("raison", ""))
    repli = aut_gouvernance().get("avis_secours")
    if repli == _AUT_AVIS_SECOURS[1] and eff.get("rev") == "oui":
        return ""
    return "pas de second avis (%s) : %s" % (v.get("raison", "indisponible"),
                                             "elle attend" if repli == _AUT_AVIS_SECOURS[2] else "elle propose seulement")


_AUT_NIVEAU_DE_OU = {"Info : la cloche": "info", "À voir : cloche et e-mail à l'administrateur": "avoir",
                     "Critique : cloche, e-mail et Telegram": "critique"}


def aut_raconter(cle: str, sujet: str, ok: bool, detail: str, resultat: str, eff: dict) -> None:
    """« Agir puis raconter » : la notification passe par le Centre (la cloche reçoit toujours ; l'e-mail et Telegram
    suivent la politique de la gravité). Au palier « Agir », le journal seul garde la trace."""
    if (eff or {}).get("palier") != "raconter":
        return
    niveau = _AUT_NIVEAU_DE_OU.get(eff.get("ou")) or ("info" if ok else "avoir")
    if not ok and niveau == "info":
        niveau = "avoir"
    if eff.get("nuit") == "Non, jamais pour ce geste" and niveau == "critique":
        niveau = "avoir"
    if eff.get("nuit") == "Oui, pour ce geste" and not ok:
        niveau = "critique"
    lib = eff.get("libelle") or aut_libelle(cle)
    try:
        notif(("Fait seule : %s" if ok else "Échec seule : %s") % lib,
              ("%s · %s%s" % ((sujet or "?")[:100], detail or "", (" · " + resultat) if (resultat and not ok) else ""))[:400],
              source="veille", niveau=niveau, sujet=(sujet or "")[:100], cle="aut:fait:%s:%s" % (cle, (sujet or "")[:60]),
              nature="evenement")
    except Exception as e:
        logging.info("[AUTONOMIE] récit : %s", e)


def aut_porte(cle: str, sujet: str = "", titre: str = "") -> dict:
    """La porte des mécanismes autonomes qui ne passent PAS par le moteur proactif (renouvellement SSL…).

    Un geste que le catalogue ne connaît pas ne bloque jamais. Un geste SANS réglage propre (palier hérité du
    global) garde son comportement d'avant : seuls un réglage explicite de palier, la fenêtre et le
    disjoncteur le retiennent. Le disjoncteur, lui, s'applique toujours : c'est lui qui protège un quota externe."""
    eff = aut_effectif(cle)
    if not eff:
        return {"ok": True, "eff": {}, "cle": None, "sujet": sujet}
    def _non(motif):
        pf_ombre_ajouter(sujet, cle, "mecanisme", titre or sujet, titre or eff.get("libelle", cle), motif)
        return {"ok": False, "motif": motif, "eff": eff, "cle": cle, "sujet": sujet}
    if autonomie_gelee():
        return _non("l'autonomie de Cassandra est gelée")
    if cle != _CRISE_CLE and crise_lecture_seule():
        return _non("crise en cours : lecture seule")
    if eff.get("origine") != "global" and eff.get("palier") in ("observer", "proposer"):
        return _non("palier « %s » sur « %s » : elle ne le fait pas seule" % (eff["palier"], eff.get("libelle", cle)))
    if not _aut_fenetre_ok(eff):
        return _non("hors de la fenêtre réglée pour « %s » (%s)" % (eff.get("libelle", cle), eff.get("fen")))
    motif = aut_retenue(eff, sujet, titre, "", "planifie")
    if motif:
        return _non(motif)
    motif = aut_disj_verifier(cle, sujet, eff)
    if motif:
        return _non(motif)
    motif = aut_avis_porte(eff, sujet, titre, "")
    if motif:
        return _non(motif)
    return {"ok": True, "eff": eff, "cle": cle, "sujet": sujet}


def aut_fin(porte: dict, ok: bool, detail: str = "", resultat: str = "") -> None:
    """Après le geste : le disjoncteur compte, le journal inscrit la règle."""
    if not porte or not porte.get("cle"):
        return
    aut_disj_resultat(porte["cle"], porte.get("sujet") or "", bool(ok), porte.get("eff") or {})
    aut_journaliser(porte["cle"], porte.get("sujet") or "", bool(ok), detail, resultat, porte.get("eff") or {})
    aut_raconter(porte["cle"], porte.get("sujet") or "", bool(ok), detail, resultat, porte.get("eff") or {})


def autonomie_etat() -> dict:
    """Tout ce que l'écran des règles montre : le catalogue, les réglages, l'effet de chacun, les disjoncteurs."""
    regl = aut_reglages_lire()
    disj = {}
    try:
        conn = _aut_conn()
        try:
            disj = {r["cle"]: dict(r) for r in conn.execute("SELECT * FROM autonomie_disj")}
        finally:
            conn.close()
    except Exception:
        pass
    domaines = []
    for did, dnom, ddesc, gestes in _AUT_CATALOGUE:
        gl = []
        for gid, gnom, st, rev, garde in gestes:
            cle = "%s/%s" % (did, gid)
            eff = aut_effectif(cle, regl)
            dj = disj.get(cle) or {}
            gl.append({"id": gid, "cle": cle, "nom": gnom, "st": st, "statut": _AUT_STATUTS[st], "rev": rev, "garde": garde,
                       "reglages": regl.get("g:" + cle, {}), "palier": eff["palier"], "origine": eff["origine"],
                       "disjoncteur": {"etat": dj.get("etat") or "arme", "raison": dj.get("raison") or "",
                                       "depuis": dj.get("depuis") or "", "echecs_suite": dj.get("echecs_suite") or 0}})
        domaines.append({"id": did, "nom": dnom, "desc": ddesc, "reglages": regl.get("d:" + did, {}), "gestes": gl})
    try:
        glob = pf_autonomie()
        glob = {"palier": glob["palier"], "palier_nom": glob["palier_nom"], "gelee": bool(autonomie_gelee())}
    except Exception:
        glob = {}
    actions = []
    try:
        conn = _sec_gestes_conn()
        try:
            actions = [dict(r) for r in conn.execute(
                "SELECT id, ts, qui, geste, cible, detail, ok, resultat, defait FROM gestes_humains "
                "WHERE geste LIKE 'aut:%' ORDER BY id DESC LIMIT 20")]
        finally:
            conn.close()
        for a in actions:
            a["libelle"] = aut_libelle(a["geste"][4:]) if a["geste"] != "aut:debloquer" else "Disjoncteur débloqué"
    except Exception:
        pass
    recit, canaux = {}, {}
    try:
        recit = notif_politique(_NT_MACHINE)
        canaux = notif_canaux_etat()
        canaux = {"mail": bool((canaux.get("mail") or {}).get("declare")), "telegram": bool((canaux.get("telegram") or {}).get("declare")),
                  "webhook": bool((canaux.get("webhook") or {}).get("declare"))}
    except Exception as e:
        logging.info("[AUTONOMIE] politique de récit : %s", e)
    machines, sites = [], []
    try:
        machines = sorted({str(m.get("name") or m.get("nom") or "") for m in (flotte_parc().get("machines") or []) if (m.get("name") or m.get("nom"))})
    except Exception:
        pass
    try:
        sites = _sec_sites_geres()
    except Exception:
        pass
    return {"ok": True, "global": glob, "paliers": list(_PF_PALIERS), "domaines": domaines, "actions": actions,
            "gouvernance": aut_gouvernance(), "recit": recit, "canaux": canaux,
            "choix_gouvernance": {"avis_secours": list(_AUT_AVIS_SECOURS), "snap_mode": list(_AUT_SNAP_MODES)},
            "intouchables_choix": {"machines": machines, "sites": sites},
            "choix": {k: list(v) for k, v in _AUT_CHOIX.items()}, "defaut": _AUT_DEFAUT,
            "declenches": [aut_libelle(k) for k, v in disj.items() if v.get("etat") == "declenche"]}


def pf_autorise(signature: str, action_kind: str, cmd: str, fkey: str = "",
                titre: str = "") -> dict:
    """Le geste peut-il partir seul ?

    Rend toujours un motif. Un refus n'est pas un silence : il devient une
    ligne dans l'ombre, qui servira à décider plus tard s'il fallait autoriser.

    10-10 : le palier se lit PAR GESTE (réglage du geste, sinon du domaine, sinon le palier global) et un
    disjoncteur remplace le plafond par jour. Un action_kind que le catalogue ne connaît pas garde l'ancien
    comportement : le palier global, sans disjoncteur."""
    _pf_migrate()
    a = pf_autonomie()
    sav = pf_savoir(signature)
    cle = _AUT_GESTE_DE_FKEY.get(str(fkey or "")) or _AUT_GESTE_DE_KIND.get(str(action_kind or ""))
    eff = aut_effectif(cle) if cle else {}
    palier = eff.get("palier") or a["palier"]
    def _non(motif):
        pf_ombre_ajouter(fkey, signature, action_kind, cmd, titre, motif)
        return {"ok": False, "motif": motif, "palier": palier}
    if autonomie_gelee():
        return _non("l'autonomie de Cassandra est gelée")
    if crise_lecture_seule(action_kind):
        return _non("crise en cours : lecture seule, seul le bannissement reste permis")
    if palier == "observer":
        return _non("palier « observer » : elle ne fait rien seule")
    if palier == "proposer":
        return _non("palier « proposer » : elle attend un appui")
    if a["reversible"] and not (sav or {}).get("reversible", 1):
        return _non("ce geste n'est pas réversible")
    if palier == "maitrise":
        if not sav or sav.get("etat") != "auto":
            return _non("« %s » n'est pas encore un savoir-faire éprouvé (%d/%d réussites)"
                        % (signature, (sav or {}).get("successes", 0), _PF_SEUIL_PROMO))
    if eff and not _aut_fenetre_ok(eff):
        return _non("hors de la fenêtre réglée pour « %s » (%s)" % (eff.get("libelle", cle), eff.get("fen")))
    if eff:
        motif = aut_retenue(eff, fkey, titre, cmd, "alerte")
        if motif:
            return _non(motif)
    if _pf_en_pause():
        return _non("heures où vous êtes là (%s–%s) : elle propose au lieu d'agir"
                    % (a["pause_debut"], a["pause_fin"]))
    if eff:
        motif = aut_disj_verifier(cle, fkey or titre, eff)
        if motif:
            return _non(motif)
        motif = aut_avis_porte(eff, fkey or titre, titre, cmd)
        if motif:
            return _non(motif)
    # Plus de plafond par jour (décision du 10-10) : le disjoncteur, qui mesure des erreurs et des boucles,
    # a pris sa place. Le compteur du jour ne sert plus qu'à l'affichage.
    return {"ok": True, "palier": palier, "savoir": sav, "cle": cle, "eff": eff, "sujet": fkey or titre}


def pf_ombre_ajouter(fkey, signature, action_kind, cmd, titre, motif) -> None:
    _pf_migrate()
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        conn.execute("INSERT INTO pf_ombre (fkey, signature, action_kind, action, titre, "
                     "motif) VALUES (?,?,?,?,?,?)",
                     (str(fkey or ""), str(signature or ""), str(action_kind or ""),
                      str(cmd or "")[:400], str(titre or "")[:200], str(motif or "")[:250]))
        conn.execute("DELETE FROM pf_ombre WHERE id NOT IN "
                     "(SELECT id FROM pf_ombre ORDER BY id DESC LIMIT 200)")
        conn.commit(); conn.close()
    except Exception as e:
        logging.info("[PROACTIF] ombre : %s", e)


def pf_ombre(limit: int = 40) -> dict:
    _pf_migrate()
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10); conn.row_factory = sqlite3.Row
        rows = [dict(r) for r in conn.execute(
            "SELECT * FROM pf_ombre ORDER BY id DESC LIMIT ?", (int(limit),)).fetchall()]
        conn.close()
        return {"ok": True, "ombre": rows,
                "justes": len([r for r in rows if r.get("avis") == "juste"]),
                "discutables": len([r for r in rows if r.get("avis") == "discutable"])}
    except Exception as e:
        return {"ok": False, "reason": str(e), "ombre": []}


def pf_ombre_avis(oid, avis: str) -> dict:
    if avis not in ("juste", "discutable", ""):
        return {"ok": False, "reason": "avis inconnu"}
    _pf_migrate()
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        conn.execute("UPDATE pf_ombre SET avis=? WHERE id=?", (avis, int(oid)))
        conn.commit(); conn.close()
        return {"ok": True}
    except Exception as e:
        return {"ok": False, "reason": str(e)}


# ── Savoir-faire : la confiance se mesure ──────────────────────────────────
def pf_savoir(signature: str):
    _pf_migrate()
    if not signature:
        return None
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10); conn.row_factory = sqlite3.Row
        r = conn.execute("SELECT * FROM proactive_playbooks WHERE signature=?",
                         (signature,)).fetchone()
        conn.close()
        return dict(r) if r else None
    except Exception:
        return None


def pf_savoirs() -> dict:
    _pf_migrate()
    out = []
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10); conn.row_factory = sqlite3.Row
        for r in conn.execute("SELECT * FROM proactive_playbooks ORDER BY "
                              "successes DESC").fetchall():
            d = dict(r)
            t = (d.get("successes") or 0) + (d.get("failures") or 0)
            d["total"] = t
            d["taux"] = round(100.0 * (d.get("successes") or 0) / t) if t else 0
            d["etat"] = d.get("etat") or "proposition"
            d["promouvable"] = bool((d.get("successes") or 0) >= _PF_SEUIL_PROMO
                                    and not (d.get("echecs_suite") or 0)
                                    and d["etat"] != "auto")
            out.append(d)
        props = [dict(x) for x in conn.execute(
            "SELECT * FROM pf_savoir_props WHERE etat='propose' AND vu >= 3 "
            "ORDER BY vu DESC LIMIT 6").fetchall()]
        conn.close()
    except Exception as e:
        logging.warning("[PROACTIF] savoirs : %s", e)
        props = []
    return {"ok": True, "savoirs": out, "propositions": props,
            "seuil_promo": _PF_SEUIL_PROMO, "seuil_retro": _PF_SEUIL_RETRO}


def pf_savoir_etat(signature: str, etat: str, acteur: str = "") -> dict:
    if etat not in ("auto", "proposition", "manuel"):
        return {"ok": False, "reason": "état inconnu"}
    sav = pf_savoir(signature)
    if not sav:
        return {"ok": False, "reason": "savoir-faire inconnu"}
    if etat == "auto" and (sav.get("successes") or 0) < _PF_SEUIL_PROMO:
        return {"ok": False, "reason": "il faut %d réussites pour confier ce geste "
                                       "(actuellement %d)"
                                       % (_PF_SEUIL_PROMO, sav.get("successes") or 0)}
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        # Le compteur d'échecs consécutifs repart de zéro : sans cela, un geste
        # qu'on reconfie après une rétrogradation serait repris au premier faux
        # pas, avec le compteur de la fois d'avant.
        conn.execute("UPDATE proactive_playbooks SET etat=?, promu_le=?, echecs_suite=0 "
                     "WHERE signature=?",
                     (etat, _utcnow().strftime("%Y-%m-%d %H:%M") if etat == "auto" else "",
                      signature))
        conn.commit(); conn.close()
    except Exception as e:
        return {"ok": False, "reason": str(e)}
    notif("Savoir-faire « %s » : %s" % (signature, etat),
          "Décidé par %s." % (acteur or "vous"), source="veille", niveau="info",
          cle="pf:savoir:%s" % signature)
    return {"ok": True}


def pf_savoir_resultat(signature: str, reussi: bool) -> None:
    """Met à jour le compteur, et RÉTROGRADE tout seul.

    Deux échecs d'affilée sur un geste confié : il repasse en proposition sans
    qu'on ait à s'en apercevoir. Une autonomie qui ne se retire jamais toute
    seule n'en est pas une, c'est un pari."""
    _pf_migrate()
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10); conn.row_factory = sqlite3.Row
        r = conn.execute("SELECT etat, echecs_suite FROM proactive_playbooks "
                         "WHERE signature=?", (signature,)).fetchone()
        suite = 0 if reussi else ((r["echecs_suite"] if r else 0) or 0) + 1
        conn.execute("UPDATE proactive_playbooks SET echecs_suite=? WHERE signature=?",
                     (suite, signature))
        retro = (r and r["etat"] == "auto" and suite >= _PF_SEUIL_RETRO
                 and bool(_mem_cfg("pf_retrograde", True)))
        if retro:
            conn.execute("UPDATE proactive_playbooks SET etat='proposition', promu_le='' "
                         "WHERE signature=?", (signature,))
        conn.commit(); conn.close()
    except Exception as e:
        logging.info("[PROACTIF] résultat : %s", e)
        return
    if retro:
        notif("Savoir-faire rétrogradé : %s" % signature,
              "%d échecs d'affilée. Le geste repasse en proposition et attend votre "
              "avis." % suite, source="veille", niveau="avoir",
              cle="pf:retro:%s" % signature)


def pf_savoir_observe(signature: str, action_kind: str, cmd: str) -> None:
    """Cassandra apprend un geste en vous regardant le faire.

    Trois fois le même geste après la même alerte : elle l'écrit noir sur blanc
    et demande la permission. Rien n'est appris en silence."""
    _pf_migrate()
    if not signature or not cmd:
        return
    if pf_savoir(signature):
        return                          # déjà connu
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        cur = conn.execute("UPDATE pf_savoir_props SET vu = vu + 1, "
                           "dernier=datetime('now'), action=? WHERE signature=? "
                           "AND etat='propose'", (str(cmd)[:400], signature))
        if not cur.rowcount:
            conn.execute("INSERT OR IGNORE INTO pf_savoir_props (signature, action_kind, "
                         "action) VALUES (?,?,?)",
                         (signature, str(action_kind or "")[:40], str(cmd)[:400]))
        vu = conn.execute("SELECT vu FROM pf_savoir_props WHERE signature=?",
                          (signature,)).fetchone()
        conn.commit(); conn.close()
    except Exception as e:
        logging.info("[PROACTIF] observation : %s", e)
        return
    if vu and vu[0] == 3:
        notif("Un geste revient : « %s »" % signature,
              "Vous l'avez fait trois fois après la même alerte. Cassandra propose de "
              "l'écrire comme un savoir-faire — elle ne l'exécutera pas avant que vous "
              "l'ayez relu.", source="veille", niveau="info",
              cle="pf:prop:%s" % signature)


def pf_savoir_accepter(signature: str, acteur: str = "") -> dict:
    _pf_migrate()
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10); conn.row_factory = sqlite3.Row
        p = conn.execute("SELECT * FROM pf_savoir_props WHERE signature=?",
                         (signature,)).fetchone()
        if not p:
            conn.close()
            return {"ok": False, "reason": "proposition inconnue"}
        conn.execute("INSERT OR IGNORE INTO proactive_playbooks (signature, action_kind, "
                     "action, successes, failures, etat) VALUES (?,?,?,0,0,'proposition')",
                     (signature, p["action_kind"], p["action"]))
        conn.execute("UPDATE pf_savoir_props SET etat='accepte' WHERE signature=?",
                     (signature,))
        conn.commit(); conn.close()
    except Exception as e:
        return {"ok": False, "reason": str(e)}
    notif_resoudre_cle("pf:prop:%s" % signature, par=acteur or "vous",
                       detail="savoir-faire accepté, en proposition")
    return {"ok": True}


def pf_savoir_ecarter(signature: str) -> dict:
    _pf_migrate()
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        conn.execute("UPDATE pf_savoir_props SET etat='ecarte' WHERE signature=?",
                     (signature,))
        conn.commit(); conn.close()
        notif_resoudre_cle("pf:prop:%s" % signature, par="écarté")
        return {"ok": True}
    except Exception as e:
        return {"ok": False, "reason": str(e)}


# ── Incidents : cinq anomalies, une histoire ───────────────────────────────
def pf_incidents_batir() -> dict:
    """Regroupe les découvertes ouvertes en incidents, par cause commune.

    `_proactive_correlate` savait déjà désigner la cause racine ; personne n'en
    faisait un objet. Un incident a un début, une cause, une chaîne et une fin
    prouvée — c'est ce qui manquait pour répondre à « que s'est-il passé »."""
    _pf_migrate()
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10); conn.row_factory = sqlite3.Row
        rows = [dict(r) for r in conn.execute(
            "SELECT id, fkey, category, severity, title, detail, first_seen, status "
            "FROM proactive_findings WHERE status != 'resolved'").fetchall()]
    except Exception as e:
        return {"ok": False, "reason": str(e)}
    causes = _proactive_correlate(rows)
    groupes = {}
    for r in rows:
        c = causes.get(r["fkey"])
        if not c:
            continue
        groupes.setdefault(c, []).append(r)
    ouverts = []
    for cause, membres in groupes.items():
        if len(membres) < 2:
            continue               # une conséquence isolée n'est pas une histoire
        cle = "inc:" + re.sub(r"\W+", "-", cause.lower())[:40]
        grav = "critical" if any(m["severity"] == "critical" for m in membres) else "warning"
        debut = min(str(m.get("first_seen") or "") for m in membres)
        try:
            cur = conn.execute(
                "INSERT INTO pf_incidents (cle, titre, cause, gravite, ouvert_le) "
                "VALUES (?,?,?,?,?)",
                (cle, "%s — %d conséquence(s)" % (cause, len(membres)), cause, grav, debut))
            iid = cur.lastrowid
        except sqlite3.IntegrityError:
            row = conn.execute("SELECT id FROM pf_incidents WHERE cle=? AND statut='ouvert'",
                               (cle,)).fetchone()
            iid = row["id"] if row else None
            if iid:
                conn.execute("UPDATE pf_incidents SET titre=?, gravite=? WHERE id=?",
                             ("%s — %d conséquence(s)" % (cause, len(membres)), grav, iid))
        if not iid:
            continue
        neuf = cle not in [x["cle"] for x in conn.execute(
            "SELECT cle FROM pf_incidents WHERE statut='ouvert' AND id <> ?", (iid,))]
        for m in membres:
            conn.execute("INSERT OR IGNORE INTO pf_incident_liens (incident_id, fkey, role) "
                         "VALUES (?,?,?)", (iid, m["fkey"], "effet"))
        ouverts.append(cle)
        # L'incident EST l'histoire : la cloche doit l'apprendre, et une seule
        # fois — la clé du regroupement s'en charge.
        try:
            notif("Incident : %s" % cause,
                  "%d anomalie(s) partagent cette cause : %s. Cassandra les suit "
                  "ensemble." % (len(membres),
                                 ", ".join(str(m["title"])[:40] for m in membres[:3])),
                  source="incident",
                  niveau="critique" if grav == "critical" else "avoir",
                  sujet=cle, cle="incident:%s" % cle)
        except Exception as _e:
            logging.info("[PROACTIF] notification d'incident : %s", _e)
    # Un incident se ferme quand TOUTES ses conséquences sont retombées : c'est
    # la preuve, pas l'absence de nouvelle alerte.
    fermes = []
    try:
        for inc in conn.execute("SELECT id, cle, ouvert_le FROM pf_incidents "
                                "WHERE statut='ouvert'").fetchall():
            liens = [x["fkey"] for x in conn.execute(
                "SELECT fkey FROM pf_incident_liens WHERE incident_id=?", (inc["id"],))]
            if not liens:
                continue
            restants = conn.execute(
                "SELECT COUNT(*) FROM proactive_findings WHERE fkey IN (%s) "
                "AND status != 'resolved'" % ",".join("?" * len(liens)), liens).fetchone()[0]
            if restants == 0:
                conn.execute(
                    "UPDATE pf_incidents SET statut='clos', ferme_le=datetime('now'), "
                    "preuve=?, duree_min=CAST((julianday('now')-julianday(ouvert_le))*1440 "
                    "AS INTEGER) WHERE id=?",
                    ("les %d contrôles qui avaient échoué sont repassés" % len(liens),
                     inc["id"]))
                fermes.append(inc["cle"])
                try:
                    notif_resoudre_cle(
                        "incident:%s" % inc["cle"], par="rentré dans l'ordre",
                        detail="les %d contrôles qui avaient échoué sont repassés"
                               % len(liens))
                except Exception as _e:
                    logging.info("[PROACTIF] clôture notifiée : %s", _e)
        conn.commit()
    except Exception as e:
        logging.info("[PROACTIF] clôture : %s", e)
    conn.close()
    return {"ok": True, "ouverts": ouverts, "fermes": fermes}


def pf_incidents(limit: int = 20, tout: bool = False) -> dict:
    _pf_migrate()
    out = []
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10); conn.row_factory = sqlite3.Row
        q = ("SELECT * FROM pf_incidents %s ORDER BY id DESC LIMIT ?"
             % ("" if tout else "WHERE statut='ouvert'"))
        for r in conn.execute(q, (int(limit),)).fetchall():
            d = dict(r)
            d["chaine"] = [dict(x) for x in conn.execute(
                "SELECT l.fkey, l.role, f.title, f.detail, f.severity, f.category, "
                "f.first_seen, f.status, f.action_result FROM pf_incident_liens l "
                "LEFT JOIN proactive_findings f ON f.fkey = l.fkey "
                "WHERE l.incident_id=? ORDER BY f.first_seen", (d["id"],)).fetchall()]
            out.append(d)
        conn.close()
    except Exception as e:
        logging.warning("[PROACTIF] incidents : %s", e)
    return {"ok": True, "incidents": out}


# ── Le fil : six journaux fondus en un ─────────────────────────────────────
def pf_fil(heures: int = 24, limit: int = 80) -> dict:
    """Une seule ligne de temps. « Pourquoi le site est tombé à 03:12 » n'a de
    réponse dans aucun journal pris seul ; elle est dans leur superposition."""
    _pf_migrate()
    depuis = (_utcnow() - timedelta(hours=max(1, min(168, int(heures or 24))))
              ).strftime("%Y-%m-%d %H:%M:%S")
    out = []

    def _add(ts, src, c, titre, detail, par_elle=0, gros=0):
        if ts:
            out.append({"ts": str(ts)[:19], "source": src, "couleur": c,
                        "titre": str(titre)[:180], "detail": str(detail or "")[:260],
                        "par_elle": par_elle, "gros": gros})

    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10); conn.row_factory = sqlite3.Row
        for r in conn.execute("SELECT first_seen, severity, category, title, detail "
                              "FROM proactive_findings WHERE first_seen >= ?",
                              (depuis,)).fetchall():
            _add(r["first_seen"], (r["category"] or "veille").upper(),
                 "danger" if r["severity"] == "critical" else "warn",
                 r["title"], r["detail"], 0, 1 if r["severity"] == "critical" else 0)
        for r in conn.execute("SELECT acted_at, title, action_result FROM proactive_findings "
                              "WHERE acted_at >= ?", (depuis,)).fetchall():
            _add(r["acted_at"], "CASSANDRA", "ok", "Action : " + str(r["title"]),
                 r["action_result"], 1, 1)
        for r in conn.execute("SELECT ouvert_le, ferme_le, titre, cause, statut, preuve "
                              "FROM pf_incidents WHERE ouvert_le >= ? OR ferme_le >= ?",
                              (depuis, depuis)).fetchall():
            _add(r["ouvert_le"], "INCIDENT", "danger", "Incident : " + str(r["cause"]),
                 str(r["titre"]), 0, 1)
            if r["ferme_le"]:
                _add(r["ferme_le"], "INCIDENT", "ok", "Incident clos : " + str(r["cause"]),
                     str(r["preuve"] or ""), 0, 1)
        for r in conn.execute("SELECT ts, etat, objet, destinataire FROM mandat_envois "
                              "WHERE ts >= ?", (depuis,)).fetchall():
            _add(r["ts"], "MANDAT",
                 {"envoye": "ok", "refuse": "danger", "echec": "danger"}.get(r["etat"], "warn"),
                 "%s — %s" % (r["etat"], str(r["objet"])[:70]),
                 str(r["destinataire"] or "")[:70])
        for r in conn.execute("SELECT ts, title, body FROM itare_proactive_feed "
                              "WHERE ts >= ?", (depuis,)).fetchall():
            _add(r["ts"], "VEILLE", "info", r["title"], r["body"])
        for r in conn.execute("SELECT ts, source, niveau, titre, corps FROM notifs "
                              "WHERE ts >= ?", (depuis,)).fetchall():
            if r["source"] in ("systeme", "site", "certificat"):
                continue           # déjà présentes comme découvertes
            _add(r["ts"], (r["source"] or "").upper(),
                 {"critique": "danger", "avoir": "warn"}.get(r["niveau"], "info"),
                 r["titre"], r["corps"])
        for r in conn.execute("SELECT started_at, ref, exit_code, duration_ms, trigger "
                              "FROM cron_runs WHERE started_at >= ?", (depuis,)).fetchall():
            _add(r["started_at"], "TÂCHE", "danger" if r["exit_code"] else "info",
                 str(r["ref"] or "")[:70],
                 "code %s · %s · %s" % (r["exit_code"], _ged_octets(0).replace("0 o", "")
                                        or "", r["trigger"] or ""))
        for r in conn.execute("SELECT ts, resultat, destination, fichiers FROM sauv_copies "
                              "WHERE ts >= ?", (depuis,)).fetchall():
            _add(r["ts"], "SAUVEGARDE",
                 "danger" if "échec" in str(r["resultat"]) else "ok",
                 str(r["resultat"])[:90], "%s fichier(s) → %s"
                 % (r["fichiers"], str(r["destination"])[:60]))
        conn.close()
    except Exception as e:
        logging.info("[PROACTIF] fil : %s", e)
    out.sort(key=lambda x: x["ts"], reverse=True)
    return {"ok": True, "fil": out[:int(limit)],
            "par_elle": len([x for x in out if x["par_elle"]])}


# ── Projections : une pente connue dit une date ────────────────────────────
def pf_projections() -> dict:
    """Les tendances étaient mesurées pour déclencher au dépassement. Une pente
    permet de dire QUAND — et de s'en occuper un mardi après-midi."""
    _pf_migrate()
    out = []
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        conn.execute("CREATE TABLE IF NOT EXISTS proactive_metrics (ts REAL PRIMARY KEY, "
                     "disk_pct REAL, disk_free_gb REAL, ram_pct REAL, load1 REAL)")
        rows = conn.execute("SELECT ts, disk_pct, disk_free_gb FROM proactive_metrics "
                            "WHERE ts > ? ORDER BY ts", (time.time() - 21 * 86400,)).fetchall()
        conn.close()
    except Exception:
        rows = []
    if len(rows) >= 12:
        t0, p0 = rows[0][0], rows[0][1] or 0
        t1, p1 = rows[-1][0], rows[-1][1] or 0
        jours = max(0.5, (t1 - t0) / 86400.0)
        pente = (p1 - p0) / jours                     # points de % par jour
        if pente > 0.05 and p1 < 100:
            reste = (95.0 - p1) / pente
            if 0 < reste < 400:
                quand = (_utcnow() + timedelta(days=reste)).strftime("%Y-%m-%d")
                out.append({"cle": "disque", "gravite": "danger" if reste < 45 else "warn",
                            "titre": "Le disque atteindra 95 %% le %s" % quand,
                            "detail": "+%.2f point par jour depuis %d jours. Il reste "
                                      "%d jours." % (pente, int(jours), int(reste)),
                            "quand": quand, "action": "Planifier"})
    # La durée d'une sauvegarde qui dérive finit par dépasser la nuit.
    try:
        for p in (sauv_plans(inclure_fp=False).get("plans") or []):
            d = cron_derive("sauv:%s" % p["id"]) if "cron_derive" in globals() else {}
            if d:
                out.append({"cle": "sauvegarde", "gravite": "warn",
                            "titre": "« %s » a vu sa durée multipliée par %s"
                                     % (p["nom"], d["facteur"]),
                            "detail": "elle finira par dépasser sa fenêtre de nuit.",
                            "quand": "", "action": "Ouvrir"})
    except Exception as e:
        logging.debug("[PROACTIF] projection sauvegarde : %s", e)
    try:
        for c in (get_ssl_certificates() or []):
            j = c.get("days_left")
            if isinstance(j, int) and 0 < j <= 15:
                out.append({"cle": "certificat", "gravite": "warn" if j > 5 else "danger",
                            "titre": "Le certificat de %s expire dans %d jours"
                                     % (c.get("domain") or "?", j),
                            "detail": "renouvellement à prévoir.", "quand": "",
                            "action": "Renouveler"})
    except Exception as e:
        logging.debug("[PROACTIF] projection certificat : %s", e)
    return {"ok": True, "projections": out[:8]}


def pf_tableau() -> dict:
    """Ce que la page ouvre : l'état, le fil, ce qui vient, ce qui attend."""
    inc = pf_incidents().get("incidents") or []
    att = []
    try:
        for f in (proactive_list().get("findings") or []):
            if f.get("status") in ("open", "investigating") and f.get("suggested_action"):
                att.append(f)
    except Exception as e:
        logging.info("[PROACTIF] attente : %s", e)
    a = pf_autonomie()
    return {"ok": True, "incidents": inc, "attente": att[:10],
            "fil": pf_fil().get("fil", [])[:30],
            "projections": pf_projections().get("projections", []),
            "autonomie": a,
            "faites": pf_budget_utilise()["jour"]}


# ── Notes de scan ───────────────────────────────────────────────────────────
def _pf_scans_migrate():
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        conn.execute("CREATE TABLE IF NOT EXISTS pf_scans ("
                     "id INTEGER PRIMARY KEY AUTOINCREMENT, "
                     "ts TEXT DEFAULT (datetime('now')), duree_ms INTEGER DEFAULT 0, "
                     "declencheur TEXT DEFAULT 'manuel', resume TEXT DEFAULT '', "
                     "vus INTEGER DEFAULT 0, muets INTEGER DEFAULT 0, "
                     "trouves INTEGER DEFAULT 0, nouveaux INTEGER DEFAULT 0, "
                     "resolus INTEGER DEFAULT 0, actions INTEGER DEFAULT 0, "
                     "detail TEXT DEFAULT '[]', diff TEXT DEFAULT '[]')")
        conn.commit(); conn.close()
    except Exception as e:
        logging.warning("[PROACTIF] migration des scans : %s", e)


def pf_scan(declencheur: str = "manuel", acteur: str = "") -> dict:
    """Lance un passage complet et en rend compte.

    Le bouton lançait un fil d'arrière-plan et rendait la main aussitôt : la
    page se rechargeait avant la fin, rien ne bougeait, et le scan passait pour
    inerte. Il est désormais synchrone, et il LAISSE UNE NOTE."""
    _pf_scans_migrate()
    _pf_migrate()
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        avant = {r[0] for r in conn.execute(
            "SELECT fkey FROM proactive_findings WHERE status != 'resolved'")}
        conn.close()
    except Exception:
        avant = set()
    t0 = time.time()
    r = proactive_scan(auto_act=None)
    duree = int((time.time() - t0) * 1000)
    detail = list(_PF_DETAIL[0] or [])
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        apres = {x[0] for x in conn.execute(
            "SELECT fkey FROM proactive_findings WHERE status != 'resolved'")}
        conn.close()
    except Exception:
        apres = set()
    diff = ([{"sens": "apparu", "fkey": k} for k in sorted(apres - avant)] +
            [{"sens": "disparu", "fkey": k} for k in sorted(avant - apres)])
    vus = [d for d in detail if d["etat"] == "vu"]
    muets = [d for d in detail if d["etat"] != "vu"]
    resume = "%d détecteur(s) passés, %d anomalie(s)" % (len(vus), len(apres))
    if muets:
        # C'est la phrase qui compte : un silence n'est une bonne nouvelle que
        # si quelqu'un a regardé.
        resume += " — %d détecteur(s) N'ONT PAS regardé (%s)" % (
            len(muets), ", ".join(d["nom"] for d in muets[:4]))
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        cur = conn.execute(
            "INSERT INTO pf_scans (duree_ms, declencheur, resume, vus, muets, trouves, "
            "nouveaux, resolus, actions, detail, diff) VALUES (?,?,?,?,?,?,?,?,?,?,?)",
            (duree, declencheur or "manuel", resume, len(vus), len(muets), len(apres),
             len(apres - avant), len(avant - apres),
             len((r or {}).get("acted") or []),
             json.dumps(detail, ensure_ascii=False), json.dumps(diff, ensure_ascii=False)))
        sid = cur.lastrowid
        conn.execute("DELETE FROM pf_scans WHERE id NOT IN "
                     "(SELECT id FROM pf_scans ORDER BY id DESC LIMIT 100)")
        conn.commit(); conn.close()
    except Exception as e:
        return {"ok": False, "reason": str(e)}
    # Un détecteur en échec est une panne de la surveillance elle-même : elle
    # se dit, sinon on croit que tout va bien parce que personne ne parle.
    for d in detail:
        if d["etat"] == "échec":
            notif("Le détecteur « %s » a échoué" % d["nom"],
                  "%s\nTant qu'il ne passe pas, son silence ne veut rien dire."
                  % d["detail"], source="proactivite", niveau="avoir",
                  sujet=d["cle"], cle="pf:detecteur:%s" % d["cle"])
        else:
            notif_resoudre_cle("pf:detecteur:%s" % d["cle"], par="détecteur rétabli")
    return dict(pf_scan_note(sid), ok=True)


def pf_scan_note(sid=None) -> dict:
    _pf_scans_migrate()
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10); conn.row_factory = sqlite3.Row
        r = (conn.execute("SELECT * FROM pf_scans WHERE id=?", (int(sid),)).fetchone()
             if sid else
             conn.execute("SELECT * FROM pf_scans ORDER BY id DESC LIMIT 1").fetchone())
        conn.close()
    except Exception as e:
        return {"ok": False, "reason": str(e)}
    if not r:
        return {"ok": False, "reason": "aucune note de scan"}
    d = dict(r)
    d["detail"] = _md_json(d.get("detail"), [])
    d["diff"] = _md_json(d.get("diff"), [])
    d["ok"] = True
    return d


def pf_scans(limit: int = 40) -> dict:
    _pf_scans_migrate()
    out = []
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10); conn.row_factory = sqlite3.Row
        for r in conn.execute("SELECT id, ts, duree_ms, declencheur, resume, vus, muets, "
                              "trouves, nouveaux, resolus, actions FROM pf_scans "
                              "ORDER BY id DESC LIMIT ?", (int(limit),)).fetchall():
            out.append(dict(r))
        conn.close()
    except Exception as e:
        logging.warning("[PROACTIF] scans : %s", e)
    return {"ok": True, "scans": out}


def pf_reprendre_ouvertes() -> int:
    """Les découvertes déjà ouvertes n'avaient jamais notifié.

    `_pf_push_alert` ne parle que des NOUVELLES : au déploiement, une anomalie
    ouverte depuis la veille restait muette, et la pastille du menu comptait
    une chose que la cloche ignorait. Rejoué une seule fois."""
    _pf_migrate()
    n = 0
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10); conn.row_factory = sqlite3.Row
        rows = [dict(x) for x in conn.execute(
            "SELECT fkey, category, severity, title FROM proactive_findings "
            "WHERE status != 'resolved'").fetchall()]
        deja = {x[0] for x in conn.execute(
            "SELECT cle FROM notifs WHERE cle LIKE 'pf:%' AND resolue = 0")}
        conn.close()
    except Exception:
        return 0
    for r in rows:
        cle = "pf:%s" % (r["fkey"] or r["category"])
        if cle in deja:
            continue
        notif(r["title"] or r["fkey"], "", source="proactivite",
              niveau="critique" if r["severity"] == "critical" else "avoir",
              sujet=r["fkey"] or r["category"], cle=cle)
        n += 1
    return n


def _pf_push_alert(severity: str, category: str, message: str, fkey: str = "") -> None:
    """Notifie la découverte — au centre seulement (B13).

    LA CLÉ EST LE FKEY, JAMAIS LA CATÉGORIE (tour 21) : « apt » et « reboot » partageaient la clé
    « pf:updates » et un fait sortait deux fois. Et la garde en toutes lettres (tour 27) : fkey ET catégorie
    vides, on n'écrit RIEN — `pf:` seul fusionnerait tout sous l'index unique."""
    if not (fkey or category):
        logging.warning("[PROACTIF] découverte sans clé ni catégorie, non notifiée : %s", str(message)[:80])
        return
    cle = fkey or category
    try:
        notif(message, "", source="proactivite", nature="decision",
              niveau="critique" if severity == "critical" else "avoir",
              sujet=cle, cle="pf:%s" % cle)
    except Exception as e:
        logging.info("[PROACTIF] relais vers le centre : %s", e)


from collections import defaultdict
import time

# Supprimer défauts pour les drapeaux et le drapeau 'escalated'
MENSURE_NORMALE = 0.3 * (60 + 1)

def _proactive_escalate() -> None:
    """Escalade tout finding CRITIQUE non résolu depuis > N minutes.

    Elle n'envoyait QUE des mails : une escalade n'apparaissait donc nulle part
    dans l'interface, et il fallait ouvrir sa boîte pour savoir que Cassandra
    avait haussé le ton. Le centre reçoit désormais la même chose."""
    # ROBUSTESSE: validation du type et valeur par défaut sécurisée
    mins_raw = _mem_cfg("proactive_escalate_min", 30)
    try:
        mins = int(mins_raw) if mins_raw is not None else MENSURE_NORMALE
    except (ValueError, TypeError):
        mins = MENSURE_NORMALE
    if mins <= 0:
        return  # PERF: retour explicite précoce si délai invalide

    # ROBUSTESSE: load_users() peut échouer, on utilise un fallback
    try:
        admins = list(load_users().keys())  # PERF: ne garder que les clés (identifiants)
    except Exception:
        admins = []

    if not admins:
        return

    # Les findings vivent en BASE. L'ancienne version itérait `admin_findings`,
    # un nom qui n'a jamais existé nulle part : la fonction levait NameError à
    # chaque scan (avalée par le try/except de l'appelant) — aucune escalade n'a
    # donc jamais été envoyée. Second écart : la sévérité est stockée en
    # minuscules ('critical'), la comparaison portait sur 'CRITICAL'.
    conn = None
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        _pf_ensure_columns(conn)
        conn.row_factory = sqlite3.Row

        # AMORÇAGE UNIQUE. Cette escalade n'a jamais fonctionné (NameError à chaque
        # scan) : à la première exécution après correctif, tout l'arriéré de findings
        # critiques ouverts partirait d'un coup en e-mail. On solde donc le passé en
        # le marquant comme déjà escaladé — seuls les findings apparus APRÈS ce
        # déploiement déclencheront une alerte.
        if not _mem_cfg("escalate_backlog_cleared", False):
            try:
                cur = conn.execute(
                    "UPDATE proactive_findings SET escalated=1 "
                    "WHERE lower(severity)='critical' AND status='open' "
                    "AND COALESCE(escalated,0)=0")
                conn.commit()
                cfg = get_cassandra_config()
                cfg["escalate_backlog_cleared"] = True
                save_cassandra_config(cfg)
                logging.warning("[PROACTIVE] escalate: amorçage — %d finding(s) "
                                "critique(s) antérieur(s) marqué(s) comme déjà "
                                "escaladé(s) (pas de rafale d'e-mails).", cur.rowcount)
            except Exception as e:
                logging.warning("[PROACTIVE] escalate: amorçage impossible : %s", e)
                # On NE poursuit PAS : mieux vaut ne rien envoyer que tout envoyer.
                try:
                    conn.close()
                except Exception:
                    pass
                return

        rows = conn.execute(
            "SELECT id, title FROM proactive_findings "
            "WHERE lower(severity)='critical' AND status='open' "
            "AND COALESCE(escalated,0)=0 "
            "AND first_seen <= datetime('now', ?) "
            "ORDER BY id LIMIT 20",              # borne : pas de rafale d'e-mails
            ("-%d minutes" % int(mins),)).fetchall()
    except Exception as e:
        logging.warning("[PROACTIVE] escalate: lecture impossible : %s", e)
        if conn:
            try:
                conn.close()
            except Exception:
                pass
        return

    for r in rows:
        fid = r["id"]
        title = (r["title"] or "sans titre").strip()
        message = ("Escalade du finding %s : %s n'est pas résolu depuis plus de "
                   "%s minutes." % (fid, title, mins))
        try:
            notify_user_email(", ".join(admins), "Cassandra · ALERTE finding non résolu",
                              message, _html.escape(title), force=True)
        except Exception as e:
            # Envoi échoué : on NE marque PAS comme escaladé, pour réessayer au
            # prochain scan plutôt que de perdre l'alerte silencieusement.
            logging.warning("[PROACTIVE] escalate: envoi échoué (#%s) : %s", fid, e)
            continue
        try:
            conn.execute("UPDATE proactive_findings SET escalated=1 WHERE id=?", (fid,))
            try:
                notif("Escalade : %s" % str(title)[:120],
                      "Critique non résolu depuis trop longtemps. Un mail est parti aux "
                      "administrateurs.", source="proactivite", niveau="critique",
                      sujet=str(fid), cle="pf:escalade:%s" % fid)
            except Exception as _e:
                logging.info("[PROACTIF] escalade notifiée : %s", _e)
            conn.commit()
        except Exception as e:
            logging.warning("[PROACTIVE] escalate: marquage #%s : %s", fid, e)
    try:
        conn.close()
    except Exception:
        pass


def _itare_triage_new(fkeys: list) -> None:
    """ITARE PREMIER RÉPONDANT — tourne en LOCAL, gratuit, après chaque scan : il qualifie les
    NOUVEAUX findings (gravité ressentie, doublon probable, action suggérée, confiance) AVANT
    toute escalade coûteuse vers Cassandra/cloud. Always-on, borné (max 6/scan), non bloquant.

    Garde-fous (fail-safe) :
      • ANNOTATION par défaut : Itare ne fait qu'étiqueter, le comportement ne change pas.
      • AUTO-FILTRE opt-in (itare_autofilter_enabled) : il peut mettre en veille douce ce qu'il
        juge « bruit » À FORTE CONFIANCE — JAMAIS un finding 'critical' (la sévérité du détecteur
        prime côté prudent), et c'est réversible (re-détecté au prochain scan s'il persiste).
      • 100% générique : aucune hypothèse sur un serveur précis.
    """
    if not fkeys or not _mem_cfg("itare_triage_enabled", True) or not _itare_agent_available():
        return
    autofilter = bool(_mem_cfg("itare_autofilter_enabled", False))
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10); conn.row_factory = sqlite3.Row
        _pf_ensure_columns(conn)
        qmarks = ",".join("?" * len(fkeys[:6]))
        rows = conn.execute("SELECT id, fkey, category, severity, title, detail FROM proactive_findings "
                            "WHERE fkey IN (%s) AND status NOT IN ('resolved','acted')" % qmarks,
                            tuple(fkeys[:6])).fetchall()
        conn.close()
    except Exception:
        return
    for r in rows:
        try:
            ev = (r["title"] or "") + ((" — " + (r["detail"] or "")[:240]) if r["detail"] else "")
            tri = itare_qualify_event(ev, context="catégorie=%s · gravité détecteur=%s"
                                      % (r["category"], r["severity"]))
            if not tri:
                continue
            isev = str(tri.get("gravite", "")).lower()
            try:
                c2 = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
                c2.execute("UPDATE proactive_findings SET itare_triage=?, itare_sev=? WHERE id=?",
                           (json.dumps(tri, ensure_ascii=False)[:800], isev, r["id"]))
                # AUTO-FILTRE (opt-in) : bruit à forte confiance, jamais sur du critical détecteur.
                if (autofilter and isev == "bruit" and float(tri.get("confiance", 0) or 0) >= 0.8
                        and r["severity"] != "critical"):
                    c2.execute("UPDATE proactive_findings SET snoozed_until=? WHERE id=?",
                               (time.time() + 6 * 3600, r["id"]))
                c2.commit(); c2.close()
            except Exception:
                pass
        except Exception:
            continue


def proactive_scan(auto_act: bool = None) -> dict:
    # PERF: _utcnow() une seule fois pour toutes les requêtes
    now_str = _utcnow().strftime('%Y-%m-%d %H:%M:%S')

    def _process_findings(cur, findings):
        fkeys = [f["fkey"] for f in findings] if findings else []
        existing_map = {}
        if fkeys:
            placeholders = ','.join(['?'] * len(fkeys))
            rows = cur.execute(
                f"SELECT id, fkey, severity, status FROM proactive_findings WHERE fkey IN ({placeholders})",
                fkeys
            ).fetchall()
            existing_map = {r["fkey"]: r for r in rows}

        active = set()
        new = 0
        alert = []
        log_ev = []
        notify = []
        updates = []
        inserts = []

        for f in findings:
            fkey = f["fkey"]
            active.add(fkey)
            row = existing_map.get(fkey)
            if row:
                new_status = "open" if row["status"] == "resolved" else row["status"]
                updates.append((
                    f["severity"], f["title"], f["detail"], f["suggested_action"],
                    f["action_kind"], new_status, row["id"]
                ))
                if row["status"] == "resolved":
                    alert.append((f["severity"], f["category"], f["title"], f["fkey"]))
            else:
                inserts.append((
                    f["fkey"], f["category"], f["severity"], f["title"], f["detail"],
                    f["suggested_action"], f["action_kind"]
                ))
                alert.append((f["severity"], f["category"], f["title"], f["fkey"]))
                log_ev.append((f["fkey"], f["title"]))
                if f["category"] == "site_http" and fkey.startswith("site_http_"):
                    notify.append(fkey[len("site_http_"):])
                new += 1

        if updates:
            cur.executemany(
                "UPDATE proactive_findings SET severity=?, title=?, detail=?, "
                "suggested_action=?, action_kind=?, status=?, last_seen=? WHERE id=?",
                [(u[0], u[1], u[2], u[3], u[4], u[5], now_str, u[6]) for u in updates]
            )
        if inserts:
            cur.executemany(
                "INSERT INTO proactive_findings (fkey, category, severity, title, detail, suggested_action, action_kind, last_seen) "
                "VALUES (?,?,?,?,?,?,?,?)",
                [(i[0], i[1], i[2], i[3], i[4], i[5], i[6], now_str) for i in inserts]
            )
        return active, new, alert, log_ev, notify

    def _auto_resolve(cur, active_keys):
        # Ce qui retombe doit refermer sa notification, sinon la cloche garde
        # une alerte pour un problème réglé — et c'est ce qui apprend à ne plus
        # la regarder.
        # PERF: ne charger que les enregistrements qui vont être résolus (fkey NOT IN active_keys)
        active_list = list(active_keys)
        if active_list:
            placeholders = ','.join(['?'] * len(active_list))
            opened = cur.execute(
                f"SELECT id, fkey, category, title, detail, severity, status, action_kind, suggested_action "
                f"FROM proactive_findings WHERE status IN ('open','acted','investigating') "
                f"AND fkey NOT IN ({placeholders})",
                active_list
            ).fetchall()
        else:
            opened = cur.execute(
                "SELECT id, fkey, category, title, detail, severity, status, action_kind, suggested_action "
                "FROM proactive_findings WHERE status IN ('open','acted','investigating')"
            ).fetchall()

        learned = []
        resolved_crit = []
        ids_to_resolve = []
        alert_updates = []
        fkeys_retombees = []
        for o in opened:
            ids_to_resolve.append(o["id"])
            fkeys_retombees.append(o["fkey"])
            if o["status"] == "acted" and (o["suggested_action"] or "").strip():
                learned.append((o["category"], o["action_kind"], o["suggested_action"]))
            if o["severity"] == "critical":
                resolved_crit.append((o["title"], o["detail"]))
            alert_updates.append(o["title"])

        if ids_to_resolve:
            placeholders = ','.join(['?'] * len(ids_to_resolve))
            cur.execute(
                f"UPDATE proactive_findings SET status='resolved', last_seen=? WHERE id IN ({placeholders})",
                [now_str] + ids_to_resolve
            )
            # Déclencheur « incident clos » de la mémoire : un incident traité puis disparu
            # est un fait qui mérite une leçon ; la porte garde, la distillation reformule.
            _clos = [(o["title"], o["detail"], o["suggested_action"]) for o in opened
                     if o["status"] == "acted" and (o["title"] or "")][:3]
            if _clos:
                def _distiller_clos(lst=_clos):
                    try:
                        set_current_user("")
                        for _t, _d, _a in lst:
                            memoire_distiller("incident_clos", "Incident clos : %s\n%s" % (_t, (_d or "")[:600]),
                                              "Action appliquée : %s" % ((_a or "")[:400]),
                                              piece={"type": "arbitrage", "source_table": "proactive_findings",
                                                     "contenu": ("%s\n%s\n— action : %s" % (_t or "", (_d or "")[:600], (_a or "")[:400]))[:1500],
                                                     "date": now_str},
                                              acteur="cassandra", maxi=2)
                    except Exception as _e:
                        logging.debug("[MEMOIRE] incident clos : %s", _e)
                threading.Thread(target=_distiller_clos, daemon=True, name="memoire-incident").start()
        if alert_updates:
            try:
                cur.executemany(
                    "UPDATE alerts SET resolved=1, resolved_at=? WHERE message=? AND resolved=0",
                    [(now_str, msg) for msg in alert_updates]
                )
            except Exception as e:
                logging.warning("[proactive_scan] alert resolve batch: %s", e)
        # La table `alerts` se referme ci-dessus ; le CENTRE, lui, se ferme par
        # la clé de la découverte. Sans cette ligne, la cloche gardait une
        # alerte pour un problème réglé.
        _pf_resoudre_notifs(fkeys_retombees)
        return learned, resolved_crit

    def _post_transaction_actions(alert, notify, learned, log_ev, resolved_crit):
        for a in alert:
            _pf_push_alert(*a)
        for dom in notify:
            try:
                notify_site_owners(dom, "site_down")
            except Exception as e:
                logging.warning("[proactive_scan] notify owner: %s", e)
        for cat, ak, act in learned:
            try:
                _playbook_record(cat or "?", ak or "", act or "", True)
            except Exception as e:
                logging.warning("[proactive_scan] playbook credit: %s", e)
        for fk, ti in log_ev:
            try:
                _proactive_log_event(fk, ti)
            except Exception as e:
                logging.warning("[proactive_scan] log event: %s", e)
        if resolved_crit and _reflex_due("postmortem", 2):
            try:
                t, d = resolved_crit[0]
                threading.Thread(target=generate_postmortem, args=(t or "Incident", d or ""),
                                 daemon=True, name="postmortem").start()
            except Exception as e:
                logging.warning("[proactive_scan] postmortem: %s", e)

    def _auto_remediate_task(do_auto, conn):
        """Le palier décide, pas un booléen.

        Un refus n'est plus un silence : il devient une ligne dans l'ombre, avec
        son motif. C'est elle qu'on relit au bout d'une semaine pour décider
        s'il fallait autoriser."""
        acted = []
        try:
            cur = conn.cursor()
            todo = cur.execute(
                "SELECT id, fkey, category, title, action_kind, suggested_action "
                "FROM proactive_findings WHERE status='open' "
                "AND COALESCE(suggested_action,'') <> ''"
            ).fetchall()
            for t in todo:
                g = pf_autorise(t["category"], t["action_kind"], t["suggested_action"],
                                t["fkey"], t["title"])
                if not g.get("ok"):
                    acted.append({"id": t["id"], "ok": False, "ombre": g.get("motif")})
                    continue
                if not _in_maintenance_window():
                    pf_ombre_ajouter(t["fkey"], t["category"], t["action_kind"],
                                     t["suggested_action"], t["title"],
                                     "hors de la fenêtre de maintenance")
                    continue
                _pt = aut_point_restauration(g, t["suggested_action"])
                r = proactive_act(t["id"], auto=True)
                acted.append({"id": t["id"], "ok": r.get("ok"), "gate": r.get("gate")})
                if g.get("cle") and not r.get("differe"):
                    aut_disj_resultat(g["cle"], g.get("sujet") or "", bool(r.get("ok")), g.get("eff") or {})
                    aut_journaliser(g["cle"], g.get("sujet") or "", bool(r.get("ok")), t["title"] + ((" — " + _pt) if _pt else ""),
                                    str(r.get("error") or r.get("gate") or "")[:300], g.get("eff") or {}, r.get("inverse"))
                    aut_raconter(g["cle"], g.get("sujet") or "", bool(r.get("ok")), t["title"],
                                 str(r.get("error") or r.get("gate") or "")[:300], g.get("eff") or {})
        except Exception as e:
            logging.warning("[PROACTIVE] auto-act: %s", e)
        return acted

    # --- corps principal ---
    _proactive_sample_metrics()
    findings = _proactive_detect_all()
    # Les incidents se recomposent après coup : ils ont besoin des découvertes
    # à jour, y compris de celles qui viennent de se résoudre.
    _pf_batir_apres = True
    active_keys = new_count = 0
    to_alert = to_notify_owner = to_log_event = learned = resolved_crit = None

    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        active_keys, new_count, to_alert, to_log_event, to_notify_owner = _process_findings(cur, findings)
        learned, resolved_crit = _auto_resolve(cur, active_keys)
        conn.commit()
        do_auto = True if auto_act is None else auto_act
        acted = _auto_remediate_task(do_auto, conn) if do_auto else []
        try:
            if _pf_batir_apres:
                pf_incidents_batir()
        except Exception as _e:
            logging.info("[PROACTIF] incidents : %s", _e)
        conn.commit()
    except Exception as e:
        logging.warning("[PROACTIVE] scan transaction: %s", e)
        if 'conn' in locals():
            conn.rollback()
        acted = []
        return {"detected": len(findings), "new": 0, "auto_acted": acted}
    finally:
        if 'conn' in locals():
            conn.close()

    _post_transaction_actions(to_alert, to_notify_owner, learned, to_log_event, resolved_crit)

    # PERF: lancement thread avec vérification de liste non vide
    if to_log_event:
        try:
            new_fkeys = [fk for fk, _ in to_log_event]
            threading.Thread(target=_itare_triage_new, args=(new_fkeys,),
                             daemon=True, name="itare-triage").start()
        except Exception as e:
            logging.warning("[proactive_scan] itare triage: %s", e)

    _PROACTIVE_LAST[0] = time.time()

    try:
        _proactive_escalate()
    except Exception as e:
        logging.warning("[PROACTIVE] escalate: %s", e)

    return {"detected": len(findings), "new": new_count, "auto_acted": acted}


def _pf_ensure_columns(conn) -> None:
    for col, ddl in (("escalated", "INTEGER DEFAULT 0"), ("snoozed_until", "REAL DEFAULT 0"),
                     ("itare_triage", "TEXT DEFAULT ''"), ("itare_sev", "TEXT DEFAULT ''")):
        try:
            conn.execute("ALTER TABLE proactive_findings ADD COLUMN %s %s" % (col, ddl))
        except Exception:
            pass


def _pf_resoudre_notifs(fkeys) -> None:
    """Une anomalie retombée referme sa notification.

    Sans cela la cloche gardait une alerte pour un problème réglé — et c'est
    exactement ce qui apprend à ne plus la regarder."""
    for k in (fkeys or []):
        try:
            notif_resoudre_cle("pf:%s" % k, par="rentré dans l'ordre")
        except Exception as e:
            logging.debug("[PROACTIF] clôture de %s : %s", k, e)


def proactive_snooze(fid, hours: float = 24) -> dict:
    try:
        until = time.time() + float(hours) * 3600 if hours else 0
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        _pf_ensure_columns(conn)
        conn.execute("UPDATE proactive_findings SET snoozed_until=? WHERE id=?", (until, int(fid)))
        conn.commit(); conn.close()
        return {"ok": True, "snoozed_until": until}
    except Exception as e:
        return {"ok": False, "error": str(e)}


# ── Playbooks : Cassandra apprend quelle réparation a marché, par catégorie ──────
def _playbook_record(signature: str, action_kind: str, action: str, success: bool) -> None:
    # Le compteur existait ; ce qui manquait, c'est la conséquence — une suite
    # d'échecs doit RETIRER l'autonomie sans qu'on ait à s'en apercevoir.
    try:
        pf_savoir_resultat(signature, success)
    except Exception as e:
        logging.info("[PROACTIF] suite du savoir : %s", e)
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        conn.execute("CREATE TABLE IF NOT EXISTS proactive_playbooks (signature TEXT PRIMARY KEY, "
                     "action_kind TEXT, action TEXT, successes INTEGER DEFAULT 0, failures INTEGER DEFAULT 0, "
                     "last_used TEXT, last_outcome TEXT)")
        row = conn.execute("SELECT 1 FROM proactive_playbooks WHERE signature=?", (signature,)).fetchone()
        if row:
            conn.execute("UPDATE proactive_playbooks SET action_kind=?, action=?, successes=successes+?, "
                         "failures=failures+?, last_used=datetime('now'), last_outcome=? WHERE signature=?",
                         (action_kind, action, 1 if success else 0, 0 if success else 1,
                          "success" if success else "failure", signature))
        else:
            conn.execute("INSERT INTO proactive_playbooks (signature, action_kind, action, successes, failures, "
                         "last_used, last_outcome) VALUES (?,?,?,?,?,datetime('now'),?)",
                         (signature, action_kind, action, 1 if success else 0, 0 if success else 1,
                          "success" if success else "failure"))
        conn.commit(); conn.close()
    except Exception:
        pass


def _playbook_for(signature: str):
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10); conn.row_factory = sqlite3.Row
        conn.execute("CREATE TABLE IF NOT EXISTS proactive_playbooks (signature TEXT PRIMARY KEY, "
                     "action_kind TEXT, action TEXT, successes INTEGER DEFAULT 0, failures INTEGER DEFAULT 0, "
                     "last_used TEXT, last_outcome TEXT)")
        r = conn.execute("SELECT action_kind, action, successes, failures FROM proactive_playbooks "
                         "WHERE signature=?", (signature,)).fetchone()
        conn.close()
        if r and r["successes"] > 0:
            return {"action_kind": r["action_kind"], "action": r["action"],
                    "successes": r["successes"], "failures": r["failures"]}
    except Exception:
        pass
    return None


def proactive_playbooks_list() -> dict:
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10); conn.row_factory = sqlite3.Row
        conn.execute("CREATE TABLE IF NOT EXISTS proactive_playbooks (signature TEXT PRIMARY KEY, "
                     "action_kind TEXT, action TEXT, successes INTEGER DEFAULT 0, failures INTEGER DEFAULT 0, "
                     "last_used TEXT, last_outcome TEXT)")
        rows = [dict(r) for r in conn.execute("SELECT * FROM proactive_playbooks ORDER BY successes DESC LIMIT 50")]
        conn.close()
        return {"playbooks": rows}
    except Exception as e:
        return {"playbooks": [], "error": str(e)}


# ── Récurrence temporelle : « ça revient chaque lundi / tous les N jours » ───────
def _proactive_log_event(fkey: str, title: str) -> None:
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        conn.execute("CREATE TABLE IF NOT EXISTS proactive_events (id INTEGER PRIMARY KEY AUTOINCREMENT, "
                     "ts REAL, fkey TEXT, title TEXT)")
        conn.execute("INSERT INTO proactive_events (ts, fkey, title) VALUES (?,?,?)",
                     (time.time(), fkey, (title or "")[:160]))
        conn.execute("DELETE FROM proactive_events WHERE ts < ?", (time.time() - 90 * 86400,))
        conn.commit(); conn.close()
    except Exception:
        pass


_WEEKDAYS_FR = ["lundi", "mardi", "mercredi", "jeudi", "vendredi", "samedi", "dimanche"]

def _recurrence_report(min_count: int = 3) -> list:
    """Analyse proactive_events : motifs qui reviennent (≥min_count), intervalle médian + jour dominant."""
    out = []
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10); conn.row_factory = sqlite3.Row
        conn.execute("CREATE TABLE IF NOT EXISTS proactive_events (id INTEGER PRIMARY KEY AUTOINCREMENT, "
                     "ts REAL, fkey TEXT, title TEXT)")
        groups = {}
        for r in conn.execute("SELECT ts, fkey, title FROM proactive_events ORDER BY ts ASC"):
            groups.setdefault(r["fkey"], {"ts": [], "title": r["title"]})
            groups[r["fkey"]]["ts"].append(r["ts"])
            groups[r["fkey"]]["title"] = r["title"]
        conn.close()
        for fkey, g in groups.items():
            tss = g["ts"]
            if len(tss) < min_count:
                continue
            intervals = sorted((tss[i + 1] - tss[i]) / 86400.0 for i in range(len(tss) - 1))
            med = intervals[len(intervals) // 2] if intervals else 0
            wd = [datetime.fromtimestamp(t).weekday() for t in tss]
            dom_wd = max(set(wd), key=wd.count)
            dom_share = wd.count(dom_wd) / len(wd)
            note = ""
            if dom_share >= 0.6:
                note = "souvent le %s" % _WEEKDAYS_FR[dom_wd]
            elif med >= 0.5:
                note = "~tous les %d j" % round(med)
            out.append({"fkey": fkey, "title": g["title"], "count": len(tss),
                        "median_days": round(med, 1), "weekday": _WEEKDAYS_FR[dom_wd], "note": note})
        out.sort(key=lambda x: -x["count"])
    except Exception:
        pass
    return out


def _proactive_correlate(rows: list) -> dict:
    """Retourne {fkey: 'cause racine probable'} pour les findings qui sont des conséquences."""
    cause = {}
    try:
        fkeys = set(r.get("fkey") for r in rows)
        disk_crit = any(r.get("category") == "disk" and r.get("severity") == "critical" for r in rows)
        oom = ("oom_24h" in fkeys) or any((r.get("fkey") or "").startswith("swap") for r in rows)
        vault_down = "vault_service_down" in fkeys
        site_down = {(r.get("fkey") or "")[len("site_http_"):] for r in rows
                     if (r.get("fkey") or "").startswith("site_http_")}
        for r in rows:
            fk = r.get("fkey") or ""; cat = r.get("category")
            if disk_crit and cat in ("service", "health", "database"):
                cause[fk] = "Disque saturé"
            elif oom and cat == "service":
                cause[fk] = "Pression mémoire (OOM)"
            elif vault_down and fk.startswith("vault_") and fk != "vault_service_down":
                cause[fk] = "Coffre Vaultwarden arrêté"
    except Exception:
        pass
    return cause


# ── Fenêtre de maintenance : différer les actions risquées aux heures creuses ────
def _in_maintenance_window() -> bool:
    """True si l'auto-action est autorisée maintenant (toujours True si la restriction est OFF)."""
    try:
        if not _mem_cfg("proactive_maint_only", False):
            return True
        s = int(_mem_cfg("proactive_maint_start", 2)); e = int(_mem_cfg("proactive_maint_end", 6))
        hr = datetime.now().hour
        if s == e:
            return True
        return (s <= hr < e) if s < e else (hr >= s or hr < e)
    except Exception:
        return True


def _proactive_trend(hours: int = 24, points: int = 40) -> dict:
    """Séries temporelles (disque/RAM/charge) pour les sparklines."""
    out = {"disk_pct": [], "ram_pct": [], "load1": []}
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10); conn.row_factory = sqlite3.Row
        conn.execute("CREATE TABLE IF NOT EXISTS proactive_metrics (ts REAL PRIMARY KEY, "
                     "disk_pct REAL, disk_free_gb REAL, ram_pct REAL, load1 REAL)")
        rows = conn.execute("SELECT ts, disk_pct, ram_pct, load1 FROM proactive_metrics "
                            "WHERE ts > ? ORDER BY ts ASC", (time.time() - hours * 3600,)).fetchall()
        conn.close()
        if rows:
            step = max(1, len(rows) // points)
            for i in range(0, len(rows), step):
                r = rows[i]
                out["disk_pct"].append(round(float(r["disk_pct"] or 0), 1))
                out["ram_pct"].append(round(float(r["ram_pct"] or 0), 1))
                out["load1"].append(round(float(r["load1"] or 0), 2))
    except Exception:
        pass
    return out


def proactive_list(include_resolved: bool = False) -> dict:
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        conn.row_factory = sqlite3.Row
        _pf_ensure_columns(conn)
        now = time.time()
        where = "" if include_resolved else "WHERE status != 'resolved'"
        snz = ("AND " if where else "WHERE ") + "COALESCE(snoozed_until,0) < %f" % now
        rows = [dict(r) for r in conn.execute(
            "SELECT id, fkey, category, severity, title, detail, suggested_action, action_kind, "
            "status, analysis, first_seen, last_seen, acted_at, action_result, snoozed_until, "
            "itare_triage, itare_sev "
            "FROM proactive_findings %s %s ORDER BY "
            "CASE severity WHEN 'critical' THEN 0 WHEN 'warning' THEN 1 ELSE 2 END, last_seen DESC LIMIT 100" % (where, snz)).fetchall()]
        counts = {}
        for r in conn.execute("SELECT severity, COUNT(*) c FROM proactive_findings "
                              "WHERE status!='resolved' AND COALESCE(snoozed_until,0) < ? GROUP BY severity", (now,)):
            counts[r["severity"]] = r["c"]
        conn.close()
        # Annotations : cause racine (corrélation) + playbook éprouvé (apprentissage)
        cause = _proactive_correlate(rows)
        for r in rows:
            rc = cause.get(r.get("fkey"))
            if rc and rc not in (r.get("title") or ""):
                r["root_cause"] = rc
            pb = _playbook_for(r.get("category"))
            if pb:
                r["playbook"] = pb
        ls = _PROACTIVE_LAST[0] or float(get_cassandra_config().get("proactive_last_ts") or 0)
        return {"findings": rows, "counts": counts,
                "last_scan": (datetime.fromtimestamp(ls).strftime("%Y-%m-%d %H:%M") if ls else None),
                "config": proactive_get_config()}
    except Exception as e:
        return {"findings": [], "counts": {}, "error": str(e)}


def _pf_get(fid):
    conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10); conn.row_factory = sqlite3.Row
    row = conn.execute("SELECT * FROM proactive_findings WHERE id=?", (int(fid),)).fetchone()
    conn.close()
    return dict(row) if row else None


def proactive_investigate(fid) -> dict:
    """Diagnostic LECTURE SEULE : exécute des commandes read-only adaptées à la catégorie,
    puis demande à l'agent secondaire une analyse + l'action corrective la plus sûre."""
    f = _pf_get(fid)
    if not f:
        return {"ok": False, "error": "introuvable"}
    cat = f.get("category")
    unit = f.get("fkey", "").replace("service_down_", "")
    diag_cmd = {
        "service":  "systemctl status %s --no-pager -l 2>&1 | head -25; echo '--- journal ---'; journalctl -u %s -n 30 --no-pager 2>&1 | tail -30" % (unit, unit),
        "disk":     "df -hP | grep -vE 'tmpfs|udev'; echo '--- gros dossiers ---'; du -xh --max-depth=2 /var /home 2>/dev/null | sort -rh | head -15",
        "health":   "systemctl --failed --no-pager 2>&1 | head -15; echo '--- mem ---'; free -m; echo '--- oom ---'; dmesg -T 2>/dev/null | grep -i 'killed process' | tail -5",
        "ssl":      "for d in $(ls /etc/letsencrypt/live 2>/dev/null); do echo $d; done; echo 'certs FastPanel: /var/www/httpd-cert/'",
        "security": "fail2ban-client status 2>&1 | head -20; echo '--- jails ---'; fail2ban-client status sshd 2>&1 | head -20",
    }.get(cat, "echo 'pas de diagnostic spécifique'")
    raw = secure_execute(diag_cmd)[:4000]
    analysis, better_action = "", f.get("suggested_action", "")
    # Playbook agissant : si une approche a DÉJÀ résolu ce type, on la met en avant pour que l'IA l'adapte.
    pb = None
    try:
        pb = _playbook_for(cat)
    except Exception:
        pb = None
    pb_hint = ""
    if pb and pb.get("action"):
        pb_hint = ("\n\nPLAYBOOK ÉPROUVÉ (a déjà résolu ce type de problème %d×, approche=%s, ex. `%s`). "
                   "Privilégie cette approche en l'ADAPTANT au contexte actuel si elle s'applique."
                   % (pb.get("successes", 0), pb.get("action_kind", "?"), str(pb.get("action"))[:120]))
    if _itare_agent_available():
        prompt = (
            "Tu es Cassandra, IA sysadmin. Un problème a été détecté sur TON serveur :\n"
            "TITRE : %s\nDÉTAIL : %s\n\nDIAGNOSTIC BRUT (lecture seule) :\n%s%s\n\n"
            "Donne une ANALYSE courte (cause probable, 2-3 phrases) et l'ACTION corrective "
            "la plus SÛRE et RÉVERSIBLE (commande shell unique, ou \"\" si aucune action sûre). "
            "Réponds UNIQUEMENT en JSON : {\"analysis\":\"...\",\"action\":\"...\"}"
            % (f.get("title"), f.get("detail"), raw, pb_hint))
        out = _itare_agent_text([{"role": "user", "content": prompt}], max_tokens=400) or ""
        try:
            data = _evo_json_extract(out) or {}
            analysis = (data.get("analysis") or "").strip()[:1200]
            act = (data.get("action") or "").strip()
            if act and f.get("action_kind") in ("diagnostic", "none", ""):
                better_action = act[:300]
        except Exception:
            pass
    # Délibération avant acte CRITIQUE et NOVATEUR (aucun playbook) : un passage « avocat du diable »
    # sur l'action proposée, plié dans l'analyse. 1 seul appel, en tâche de fond (zéro latence user).
    if (f.get("severity") == "critical" and not pb and (better_action or "").strip()
            and _itare_agent_available()):
        try:
            crit = (_itare_agent_text([{"role": "user", "content":
                    "Avocat du diable : risques et angles morts de cette action corrective sur un serveur "
                    "en prod ? Sois bref.\nPROBLÈME : %s\nACTION : %s" % (f.get("title"), better_action)}],
                    max_tokens=180) or "").strip()
            if crit:
                analysis = (analysis + "\n\n😈 Délibération (avocat du diable) : " + crit[:500]).strip()
        except Exception:
            pass
    if not analysis:
        analysis = "Diagnostic brut :\n" + raw[:1000]
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        conn.execute("UPDATE proactive_findings SET analysis=?, suggested_action=COALESCE(NULLIF(?,''), suggested_action), "
                     "status=CASE WHEN status='open' THEN 'investigating' ELSE status END WHERE id=?",
                     (analysis, better_action, int(fid)))
        conn.commit(); conn.close()
    except Exception:
        pass
    return {"ok": True, "analysis": analysis, "suggested_action": better_action, "diagnostic": raw[:2000]}


def proactive_act(fid, auto: bool = False, acteur: str = "") -> dict:
    """Exécute la correction d'un finding — TOUJOURS EN CAGE, sous veto. Ce n'est pas un contrôle de l'autonomie de
    Cassandra mais sa protection contre une action INDUITE PAR MANIPULATION EXTERNE (injection
    via log/web/flotte) : le vérificateur ne voit pas le contexte empoisonné, il bloque donc
    l'action trahie. NON DÉSACTIVABLE. Réversible. En auto, restreint aux actions sûres (service.restart)."""
    f = _pf_get(fid)
    if not f:
        return {"ok": False, "error": "introuvable"}
    cmd = (f.get("suggested_action") or "").strip()
    kind = f.get("action_kind") or "bash"
    if not cmd:
        return {"ok": False, "error": "aucune action corrective définie — lance d'abord l'investigation"}
    if not auto:
        # Vous venez de faire un geste après une alerte. Au troisième, Cassandra
        # le propose comme savoir-faire — écrit, relu, jamais appris en silence.
        try:
            pf_savoir_observe(f.get("category") or "", kind, cmd)
        except Exception as e:
            logging.info("[PROACTIF] observation : %s", e)
    if auto and kind not in _SAFE_ACTION_KINDS:
        return {"ok": False, "error": "action non éligible à l'auto-remédiation"}
    # UN BANNISSEMENT passe par le geste de Sécurité (CrowdSec, vérifié après coup, avec son inverse), pas par la cage :
    # c'est le même geste que celui de l'humain, avec les mêmes refus (la maison, le tailnet, les adresses de confiance).
    if kind == "securite.bannir":
        _m = re.match(r"^\s*bannir\s+([0-9a-fA-F:.]+(?:/\d{1,3})?)\s*$", cmd)
        if not _m:
            return {"ok": False, "error": "commande de bannissement illisible"}
        _res, _inv = _sec_geste_executer("bannir", {"ip": _m.group(1), "jours": int(_mem_cfg("proactive_ban_jours", 7))}, "cassandra")
        out = ("bannie : " + str(_res.get("detail") or "")) if _res.get("ok") else ("⛔ " + str(_res.get("error") or "refusé"))
        try:
            log_action("proactive", cmd, out, 0, True, False)
        except Exception:
            pass
        try:
            conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
            conn.execute("UPDATE proactive_findings SET status='acted', acted_at=datetime('now'), action_result=? WHERE id=?",
                         (("auto • " if auto else "") + str(out)[:1500], int(fid)))
            conn.commit(); conn.close()
        except Exception:
            pass
        return {"ok": bool(_res.get("ok")), "output": str(out)[:2000], "gate": "", "inverse": _inv if _res.get("ok") else None}
    # UN SITE qui ne répond pas : relance, puis preuve. UNE SAUVEGARDE en échec : relance en arrière-plan.
    if kind == "site.relancer":
        _m = re.match(r"^\s*relancer-site\s+([A-Za-z0-9.-]+)\s*$", cmd)
        if not _m:
            return {"ok": False, "error": "commande de relance de site illisible"}
        _ok, out = _aut_relancer_site(_m.group(1))
        try:
            log_action("proactive", cmd, out, 0, True, False)
        except Exception:
            pass
        try:
            conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
            conn.execute("UPDATE proactive_findings SET status='acted', acted_at=datetime('now'), action_result=? WHERE id=?",
                         (("auto • " if auto else "") + str(out)[:1500], int(fid)))
            conn.commit(); conn.close()
        except Exception:
            pass
        return {"ok": bool(_ok), "output": str(out)[:2000], "gate": ""}
    if kind == "conteneur.relancer":
        _m = re.match(r"^\s*relancer-conteneur\s+([A-Za-z0-9][A-Za-z0-9_.-]{0,63})\s*$", cmd)
        if not _m:
            return {"ok": False, "error": "commande de relance de conteneur illisible"}
        _ok, out = _aut_relancer_conteneur(_m.group(1))
        try:
            log_action("proactive", cmd, out, 0, True, False)
        except Exception:
            pass
        try:
            conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
            conn.execute("UPDATE proactive_findings SET status='acted', acted_at=datetime('now'), action_result=? WHERE id=?",
                         (("auto • " if auto else "") + str(out)[:1500], int(fid)))
            conn.commit(); conn.close()
        except Exception:
            pass
        return {"ok": bool(_ok), "output": str(out)[:2000], "gate": ""}
    if kind == "disque.purger":
        if cmd.strip() != "purger-caches":
            return {"ok": False, "error": "commande de purge illisible"}
        _ok, out = _aut_purger_caches()
        try:
            log_action("proactive", cmd, out, 0, True, False)
        except Exception:
            pass
        try:
            conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
            conn.execute("UPDATE proactive_findings SET status='acted', acted_at=datetime('now'), action_result=? WHERE id=?",
                         (("auto • " if auto else "") + str(out)[:1500], int(fid)))
            conn.commit(); conn.close()
        except Exception:
            pass
        return {"ok": bool(_ok), "output": str(out)[:2000], "gate": ""}
    if kind == "ssh.rotation":
        _m = re.match(r"^\s*rotation-cle-ssh\s+([A-Za-z0-9._-]+)\s*$", cmd)
        if not _m:
            return {"ok": False, "error": "commande de rotation illisible"}
        _sv = _flotte_serveur(_m.group(1))
        if not _sv:
            return {"ok": False, "error": "machine inconnue du registre"}
        _rc, out = _flotte_cle_neuve(_sv)
        try:
            log_action("proactive", cmd, out, 0, True, False)
        except Exception:
            pass
        try:
            conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
            conn.execute("UPDATE proactive_findings SET status='acted', acted_at=datetime('now'), action_result=? WHERE id=?",
                         (("auto • " if auto else "") + str(out)[:1500], int(fid)))
            conn.commit(); conn.close()
        except Exception:
            pass
        return {"ok": _rc == 0, "output": str(out)[:2000], "gate": ""}
    if kind == "sauvegarde.relancer":
        _m = re.match(r"^\s*relancer-sauvegarde\s+(\d+)\s*$", cmd)
        if not _m:
            return {"ok": False, "error": "commande de relance de sauvegarde illisible"}
        _cle = _AUT_GESTE_DE_KIND.get(kind)
        threading.Thread(target=_aut_sauvegarde_differee,
                         args=(int(_m.group(1)), _cle, aut_effectif(_cle), f.get("fkey") or "", f.get("title") or ""),
                         daemon=True, name="aut-sauvegarde").start()
        out = "relance lancée en arrière-plan : le résultat s'écrit au journal quand elle est finie"
        try:
            conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
            conn.execute("UPDATE proactive_findings SET status='acted', acted_at=datetime('now'), action_result=? WHERE id=?",
                         (("auto • " if auto else "") + out, int(fid)))
            conn.commit(); conn.close()
        except Exception:
            pass
        return {"ok": True, "output": out, "gate": "", "differe": True}
    # Plus de juge : la commande tourne en cage comme toute autre. Seul le veto
    # parle avant, pour NOMMER le geste au lieu de rendre un « permission denied ».
    _v = veto_root(cmd)
    if _v:
        try:
            conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
            conn.execute("UPDATE proactive_findings SET action_result=? WHERE id=?",
                         ("⛔ geste interdit : " + _v, int(fid)))
            conn.commit(); conn.close()
        except Exception:
            pass
        return {"ok": False, "gate": "geste interdit — " + _v}
    # LA SOUVERAINETÉ PASSE PAR LE CATALOGUE. Un « systemctl restart nginx » lancé
    # dans la cage échoue (le bus est une socket rendue inaccessible) : la
    # correction automatique d'un service tombé serait morte en silence. Ce qui
    # est un geste du catalogue y va — en root, sans shell, sous veto. Une unité
    # hors table est refusée avec son aide, et l'aide part au centre de
    # notifications puisque personne ne lit cette réponse-ci.
    _m = re.match(r"^\s*systemctl\s+(restart|reload|start|stop|status)\s+([A-Za-z0-9_.@\-]+)\s*$", cmd)
    if _m:
        _r = catalogue_executer("service", {"op": _m.group(1), "unite": _m.group(2)})
        out = _r.get("sortie") or _r.get("error") or ""
        if not _r.get("ok"):
            out = "⛔ " + out
    else:
        out = secure_execute(cmd)
    try:
        log_action("proactive", cmd, out, 0, True, False)
    except Exception:
        pass
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        conn.execute("UPDATE proactive_findings SET status='acted', acted_at=datetime('now'), action_result=? WHERE id=?",
                     (("auto • " if auto else "") + str(out)[:1500], int(fid)))
        conn.commit(); conn.close()
    except Exception:
        pass
    # ré-évalue : si le problème a disparu, le prochain scan le résoudra
    threading.Thread(target=proactive_scan, kwargs={"auto_act": False}, daemon=True, name="pf-rescan").start()
    return {"ok": not str(out).startswith("⛔"), "output": str(out)[:2000], "gate": ""}


def proactive_ignore(fid) -> dict:
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        conn.execute("UPDATE proactive_findings SET status='ignored' WHERE id=?", (int(fid),))
        conn.commit(); conn.close()
        return {"ok": True}
    except Exception as e:
        return {"ok": False, "error": str(e)}


_PROACTIVE_CFG_KEYS = (
    ("proactive_enabled", True), ("proactive_auto_remediate", False),
    ("proactive_watch_disk", True), ("proactive_watch_ssl", True),
    ("proactive_watch_service", True), ("proactive_watch_security", True),
    ("proactive_watch_sites", True), ("proactive_watch_backups", True),
    ("proactive_watch_updates", True), ("proactive_watch_db", True),
    ("proactive_disk_warn", 80.0), ("proactive_disk_crit", 90.0),
    ("proactive_ssl_warn", 30), ("proactive_ssl_crit", 7),
    ("proactive_health_min", 60), ("proactive_ban_spike", 25),
    ("proactive_interval_min", 5), ("proactive_escalate_min", 30),
    ("proactive_maint_only", False), ("proactive_maint_start", 2), ("proactive_maint_end", 6),
    # Itare premier répondant : il qualifie chaque nouveau finding en local (annotation, défaut ON).
    # L'auto-filtre (mettre en veille ce qu'Itare juge « bruit ») reste OPT-IN, jamais sur du critique.
    ("itare_triage_enabled", True), ("itare_autofilter_enabled", False),
)


def proactive_get_config() -> dict:
    cfg = get_cassandra_config()
    return {k: (bool(cfg.get(k, d)) if isinstance(d, bool) else cfg.get(k, d)) for k, d in _PROACTIVE_CFG_KEYS}


def proactive_set_config(params: dict) -> dict:
    allowed = {k for k, _ in _PROACTIVE_CFG_KEYS}
    cfg = get_cassandra_config()
    changed = {}
    for k, v in (params or {}).items():
        if k in allowed:
            cfg[k] = v; changed[k] = v
    if changed:
        try:
            save_cassandra_config(cfg)
        except Exception as e:
            return {"ok": False, "error": str(e)}
    return {"ok": True, "updated": changed, "config": proactive_get_config()}


class _GelAutonomie(Exception):
    """L'autonomie est gelée : on saute les actions, pas les mesures."""


def _proactive_mesures_seules() -> None:
    """Ce que Cassandra continue de faire quand elle n'a plus le droit d'agir :
    regarder, et le dire. Sans cela, geler reviendrait à s'aveugler — soit
    exactement ce qu'un attaquant souhaite."""
    try:
        _proactive_sample_metrics()
    except Exception as e:
        logging.info("[PROACTIVE] mesures : %s", e)
    try:
        notif("Autonomie gelée — surveillance active",
              "Cassandra continue de mesurer et de notifier. Aucune action n'est prise.",
              source="securite", niveau="avoir", nature="etat", sujet="urgence:gel-rappel",
              cle="urgence:gel-rappel")
    except Exception:
        pass


def _proactive_loop():
    """Veille périodique (gardée). Démarre 90 s après le boot, puis selon l'intervalle config."""
    time.sleep(90)
    while True:
        try:
          with _Origine("regle", "veille"):
            # Geler l'autonomie ne coupe pas la veille : elle continue de
            # mesurer et de notifier. Elle cesse seulement d'AGIR.
            if autonomie_gelee():
                raise _GelAutonomie()
            if _mem_cfg("proactive_enabled", True):
                proactive_scan()
                try:
                    cfg = get_cassandra_config(); cfg["proactive_last_ts"] = _PROACTIVE_LAST[0]; save_cassandra_config(cfg)
                except Exception:
                    pass
                # LE MÉNAGE DES PIÈCES, ici aussi. Il tournait au DÉPÔT : une
                # semaine sans conversation laissait tout en place, et les
                # orphelins n'attendent pas qu'on dépose pour apparaître.
                if time.time() - _PIECES_MENAGE_LAST[0] > 6 * 3600:
                    _PIECES_MENAGE_LAST[0] = time.time()
                    try:
                        lab_pieces_purger()
                    except Exception as _e:
                        logging.debug("[PIECES] menage periodique : %s", _e)
                # Auto-renouvellement SSL des sites des users (avant expiration) — throttle 6 h.
                if _mem_cfg("proactive_auto_ssl", True) and _in_maintenance_window() \
                        and (time.time() - _SSL_AUTO_LAST_RUN[0] > 6 * 3600):
                    _SSL_AUTO_LAST_RUN[0] = time.time()
                    try:
                        _auto_renew_user_ssl()
                    except Exception as _e:
                        logging.warning("[SSL-AUTO] %s" % _e)
                # Sauvegardes de la GED : les flux planifiés en mode « copy ».
                # Vérifiées toutes les 15 min ; chaque flux porte son propre
                # rythme, donc ce passage ne fait presque jamais rien.
                if _mem_cfg("ged_backup_enabled", True) and \
                        (time.time() - _GED_BACKUP_LAST[0] > 900):
                    _GED_BACKUP_LAST[0] = time.time()
                    try:
                        _bk = sauv_tick()
                        if _bk.get("lances"):
                            logging.info("[SAUV] plans exécutés : %s", _bk["lances"])
                    except Exception as _e:
                        logging.warning("[SAUV] plan : %s", _e)
                    try:
                        _ap = cron_apres_tick()
                        if _ap.get("lances"):
                            logging.info("[CRON] enchaînements : %s", _ap["lances"])
                    except Exception as _e:
                        logging.warning("[CRON] enchaînement : %s", _e)
                    try:
                        messages_tick()
                        _md = mandat_tick()
                        if _md.get("partis"):
                            logging.info("[MANDAT] envois différés partis : %s", _md["partis"])
                    except Exception as _e:
                        logging.warning("[MANDAT] minuterie : %s", _e)
                    try:
                        _bg = {"lances": []}         # LOT 8 : plus de flux ged_sync à lancer
                        if _bg.get("lances"):
                            logging.info("[GED] flux : %s", _bg["lances"])
                    except Exception as _e:
                        logging.warning("[GED] flux : %s", _e)
                # Récap hebdomadaire par e-mail (admin + users) — throttle 7 j, jour/heure configurables.
                if _mem_cfg("mail_weekly_recap", True) and mail_configured() and _recap_due():
                    try:
                        r = send_weekly_recaps()
                        logging.info("[RECAP] hebdo envoyé: %s" % r)
                    except Exception as _e:
                        logging.warning("[RECAP] %s" % _e)
        except _GelAutonomie:
            try:
                _proactive_mesures_seules()
            except Exception as e:
                logging.info("[PROACTIVE] mesures pendant le gel : %s", e)
        except Exception as e:
            logging.warning("[PROACTIVE] loop: %s" % e)
        time.sleep(max(60, int(_mem_cfg("proactive_interval_min", 5)) * 60))


def start_proactive():
    threading.Thread(target=_proactive_loop, daemon=True, name="proactive").start()
    print("[PROACTIVE] Veille proactive démarrée")


def _system_uninstall(wipe_vault: bool = True, garder: list = None) -> dict:
    """DÉSINSTALLATION COMPLÈTE, détachée (systemd-run, unité horodatée, journal sous CASSANDRA_LOG_DIR),
    par les CONSTANTES du programme — avant, sept chemins en dur ignoraient une installation faite
    ailleurs. `garder` dit ce qui reste : swap, depots (deploy.sh), searxng, journaux, coffre (= KEEP_VAULT).
    Ce qui part toujours : les trois racines, les unités, le socket, fail2ban et logrotate de l'installeur."""
    garder = set(garder or [])
    if not wipe_vault:
        garder.add("coffre")
    vault_dir = os.environ.get("CASSANDRA_VAULT_DIR") or "/opt/vaultwarden"
    searx_dir = os.environ.get("CASSANDRA_SEARXNG_DIR") or "/opt/searxng"
    L = ["# 1) Services",
         "systemctl stop cassandra cassandra-collector cassandra-vault 2>/dev/null",
         "systemctl disable cassandra cassandra-collector cassandra-vault 2>/dev/null",
         "rm -f /etc/systemd/system/cassandra.service /etc/systemd/system/cassandra-collector.service /etc/systemd/system/cassandra-vault.service",
         "systemctl daemon-reload 2>/dev/null"]
    if "coffre" in garder:
        L.append("# 2) Coffre conservé")
    else:
        L += ["# 2) Coffre Vaultwarden — éradication (ne dépend pas de docker compose)",
              "pkill -f 'bw serve' 2>/dev/null || true",
              "(cd %s 2>/dev/null && (docker compose down -v 2>/dev/null || docker-compose down -v 2>/dev/null)) || true" % vault_dir,
              "docker rm -f vaultwarden 2>/dev/null || true", "docker rmi -f vaultwarden/server:latest 2>/dev/null || true",
              "rm -rf %s" % vault_dir,
              "rm -rf \"$HOME/.config/Bitwarden CLI\" \"$HOME\"/.config/Bitwarden* \"$HOME\"/.cache/Bitwarden* 2>/dev/null || true",
              "npm uninstall -g @bitwarden/cli 2>/dev/null || true", "rm -f \"$(command -v bw 2>/dev/null)\" 2>/dev/null || true"]
    L += ["# 3) Code + configuration + données",
          "chattr -R -i %s %s %s 2>/dev/null || true" % (CASSANDRA_CONF_DIR, CASSANDRA_APP_DIR, CASSANDRA_DATA_DIR),
          "rm -rf %s %s %s" % (CASSANDRA_APP_DIR, CASSANDRA_CONF_DIR, CASSANDRA_DATA_DIR)]
    if "depots" in garder:
        L.append("# 4) Dépôts de deploy.sh conservés (%s)" % _SYS_DEPOTS)
    else:
        L.append("rm -rf %s" % _SYS_DEPOTS)
    if "journaux" in garder:
        L.append("# 5) Journaux conservés")
    else:
        L += ["rm -f %s/cassandra.log %s/cassandra-collector.log %s/cassandra_admin.log" % (CASSANDRA_LOG_DIR, CASSANDRA_LOG_DIR, CASSANDRA_LOG_DIR),
              "rm -f %s/cassandra-install-*.log %s/cassandra-reset-*.log %s/cassandra-restaure-*.log %s/cassandra-retour-*.log 2>/dev/null || true"
              % (CASSANDRA_LOG_DIR, CASSANDRA_LOG_DIR, CASSANDRA_LOG_DIR, CASSANDRA_LOG_DIR)]
    if "swap" in garder:
        L.append("# 6) Swap et tuning conservés")
    else:
        L += ["swapoff /swapfile 2>/dev/null; rm -f /swapfile", "sed -i '\\#/swapfile#d' /etc/fstab 2>/dev/null",
              "rm -f /etc/sysctl.d/99-cassandra.conf"]
    L += ["# 7) Socket + temporaires", "rm -rf /run/cassandra /tmp/cassandra_knowledge.sock /tmp/cassandra_*.sock /tmp/cassandra_smoke* 2>/dev/null"]
    if "searxng" in garder:
        L.append("# 8) SearXNG conservé")
    else:
        L += ["docker rm -f searxng 2>/dev/null || true", "docker rmi -f searxng/searxng 2>/dev/null || true", "rm -rf %s" % searx_dir]
    L += ["# 9) Durcissement laissé par l'installeur",
          "rm -f /etc/sysctl.d/98-cassandra-securite.conf 2>/dev/null || true",
          "rm -f /etc/fail2ban/jail.d/cassandra.local 2>/dev/null || true",
          "(systemctl reload fail2ban 2>/dev/null || systemctl restart fail2ban 2>/dev/null) || true",
          "rm -f /etc/logrotate.d/cassandra 2>/dev/null || true",
          "echo \"$(date) Cassandra desinstallee\""]
    try:
        r = _sys_detache("desinstalle", "\n".join(L) + "\n", dossier=_sys_travail_hors_racines("desinstalle"))
        return dict(r, garder=sorted(garder))
    except Exception as e:
        return {"ok": False, "error": str(e)}

# ============================================================
# 15.45 COFFRE VAULTWARDEN — couche d'accès souveraine (via bw serve local)
#   Cassandra détient le coffre. Elle lit/écrit les secrets via l'API REST locale
#   du sidecar (127.0.0.1:VAULT_SERVE_PORT), déjà déverrouillée au boot. Les secrets
#   sont stockés en notes sécurisées (name = nom du secret, notes = valeur).
#   Dégradation propre : si le coffre est indisponible/verrouillé, on renvoie None/échec.
# ============================================================
def _vault_serve_port() -> int:
    try:
        with open(CASSANDRA_CONF_DIR + "/vault.env") as f:
            for line in f:
                if line.strip().startswith("VAULT_SERVE_PORT"):
                    return int(line.split("=", 1)[1].strip().strip('"').strip("'"))
    except Exception:
        pass
    return 8088


def _vault_req(method: str, path: str, body=None, timeout: int = 8) -> dict:
    import urllib.request, urllib.error
    url = "http://127.0.0.1:%d%s" % (_vault_serve_port(), path)
    data = json.dumps(body).encode() if body is not None else None
    req = urllib.request.Request(url, data=data, method=method,
                                 headers={"Content-Type": "application/json"})
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            raw = r.read().decode("utf-8", "replace")
        return json.loads(raw) if raw else {}
    except urllib.error.HTTPError as e:
        try:
            return json.loads(e.read().decode("utf-8", "replace"))
        except Exception:
            return {"success": False, "error": "HTTP %s" % e.code}
    except Exception as e:
        return {"success": False, "error": str(e)}


def vault_status() -> dict:
    r = _vault_req("GET", "/status")
    t = ((r.get("data") or {}).get("template")) or {}
    return {"available": bool(r.get("success")), "status": t.get("status"),
            "email": t.get("userEmail"), "server": t.get("serverUrl"),
            "error": r.get("error")}


def vault_available() -> bool:
    s = vault_status()
    return bool(s.get("available")) and s.get("status") == "unlocked"


def _vault_find(name: str):
    """Item EXACT (par nom) ou None."""
    import urllib.parse
    r = _vault_req("GET", "/list/object/items?search=" + urllib.parse.quote(name))
    items = ((r.get("data") or {}).get("data")) or []
    for it in items:
        if it.get("name") == name:
            return it
    return None


def vault_get(name: str):
    """Valeur d'un secret par nom (note sécurisée → notes), ou None. Ne lève jamais."""
    try:
        it = _vault_find(name)
        return it.get("notes") if it else None
    except Exception:
        return None


def vault_set(name: str, value: str) -> dict:
    """Crée ou met à jour un secret (idempotent, réversible)."""
    if not vault_available():
        return {"ok": False, "error": "coffre indisponible ou verrouillé"}
    try:
        it = _vault_find(name)
        if it:
            it["notes"] = value
            r = _vault_req("PUT", "/object/item/%s" % it["id"], it)
        else:
            body = {"type": 2, "name": name, "notes": value,
                    "secureNote": {"type": 0}, "fields": []}
            r = _vault_req("POST", "/object/item", body)
        if r.get("success"):
            return {"ok": True, "id": ((r.get("data") or {}).get("id")) or (it or {}).get("id")}
        return {"ok": False, "error": r.get("error") or "échec écriture coffre"}
    except Exception as e:
        return {"ok": False, "error": str(e)}


def vault_rotate(name: str, new_value: str) -> dict:
    return vault_set(name, new_value)


def vault_delete(name: str) -> dict:
    try:
        it = _vault_find(name)
        if not it:
            return {"ok": True, "note": "déjà absent"}
        r = _vault_req("DELETE", "/object/item/%s" % it["id"])
        return {"ok": bool(r.get("success", True))}
    except Exception as e:
        return {"ok": False, "error": str(e)}


def vault_list(prefix: str = "") -> list:
    """Liste les NOMS de secrets (JAMAIS les valeurs)."""
    try:
        r = _vault_req("GET", "/list/object/items")
        items = ((r.get("data") or {}).get("data")) or []
        names = [it.get("name") for it in items if it.get("name")]
        if prefix:
            names = [n for n in names if n.startswith(prefix)]
        return sorted(set(names))
    except Exception:
        return []


# ══ V-ACCOUNTS : compte Cassandra = compte Vault natif ═════════════════════════
#   Créer un compte Cassandra crée DE FAIT son coffre Vaultwarden : même pseudo,
#   même mot de passe. Cassandra détient le mdp de chaque coffre (rangé dans SON
#   propre coffre, sous cassandra/comptes/<pseudo>) → elle opère n'importe quel
#   coffre même user déconnecté. La table user EST le registre des coffres.
try:
    import vault_client as _vaultcli   # déployé dans /opt/cassandra par install.sh
except Exception:
    _vaultcli = None

_USER_VAULT_SESS: dict = {}            # username -> (session, ts)
_USER_VAULT_SESS_TTL = 1800
# LE DERNIER ÉCHEC, ET UNE MINUTE DE PAUSE. Chaque écran qui lisait le coffre retentait la connexion : après la mise à
# jour de Vaultwarden (1.37, 05-10), les refus se sont enchaînés jusqu'au « Too many login requests » — le limiteur
# bloquait alors même une connexion correcte. Un échec est gardé 60 s et rendu tel quel.
_USER_VAULT_ERR: dict = {}             # username -> (erreur, ts)
_USER_VAULT_PAUSE = 60
_user_vault_lock = threading.Lock()


def _vault_env() -> dict:
    """Lit /etc/cassandra/vault.env → {BW_SERVER, BW_EMAIL, BW_PASSWORD, ...}."""
    out = {}
    try:
        with open(CASSANDRA_CONF_DIR + "/vault.env") as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith("#") or "=" not in line:
                    continue
                k, v = line.split("=", 1)
                out[k.strip()] = v.strip().strip('"').strip("'")
    except Exception:
        pass
    return out


def _vault_domain() -> str:
    em = _vault_env().get("BW_EMAIL", "cassandra@vault.local")
    return em.split("@", 1)[1] if "@" in em else "vault.local"


def _vault_account_email(username: str) -> str:
    u = (username or "").strip().lower()
    if "@" in u:                      # déjà une adresse e-mail → identité Vault telle quelle
        return u
    safe = re.sub(r"[^a-z0-9_.\-]", "", u) or "user"   # legacy : ancien pseudo → @<domaine>
    return "%s@%s" % (safe, _vault_domain())


def _vault_account_pw_name(username: str) -> str:
    return "cassandra/comptes/%s" % re.sub(r"[^A-Za-z0-9_.\-]", "_", (username or "").strip())


def vault_account_provisioned(username: str) -> bool:
    """Vrai si Cassandra détient déjà le mot de passe du coffre de ce user."""
    try:
        return bool(vault_get(_vault_account_pw_name(username)))
    except Exception:
        return False


def provision_user_vault(username: str, password: str) -> dict:
    """Crée le coffre Vault natif du user (pseudo@<domaine>) et range son mdp dans le coffre
    de Cassandra (cassandra/comptes/<pseudo>) pour qu'elle puisse l'opérer même user
    déconnecté. Idempotent : rc 0 si le compte existait déjà."""
    if _vaultcli is None:
        return {"ok": False, "error": "vault_client indisponible"}
    env = _vault_env()
    server = env.get("BW_SERVER")
    if not server:
        return {"ok": False, "error": "vault.env sans BW_SERVER"}
    email = _vault_account_email(username)
    # 1) crée le compte Vault natif (vault_register.py — rc 0 si créé OU déjà existant)
    try:
        reg = os.path.join(os.path.dirname(os.path.abspath(__file__)), "vault_register.py")
        envp = dict(os.environ)
        envp.update({"VW_SERVER": server, "VW_EMAIL": email,
                     "VW_PASSWORD": password, "VW_NAME": username or "user"})
        r = subprocess.run([sys.executable, reg], env=envp, capture_output=True,
                           text=True, timeout=60)
        if r.returncode != 0:
            return {"ok": False, "error": "register: %s" % (r.stderr or r.stdout)[:200]}
    except Exception as e:
        return {"ok": False, "error": "register: %s" % e}
    # 2) Cassandra mémorise le mdp du coffre (pour opérer même user déconnecté)
    try:
        vault_set(_vault_account_pw_name(username), password)
    except Exception:
        pass
    return {"ok": True, "email": email}


def _vault_account_api_name(username: str) -> str:
    """La clé d'API personnelle du coffre de ce user (JSON client_id / client_secret), au coffre système."""
    return "cassandra/comptes-api/%s" % re.sub(r"[^A-Za-z0-9_.\-]", "_", (username or "").strip())


def _vault_cle_api(username: str):
    """(client_id, client_secret) si la personne a confié sa clé d'API, sinon None."""
    try:
        d = json.loads(vault_get(_vault_account_api_name(username)) or "null")
        if isinstance(d, dict) and d.get("client_id") and d.get("client_secret"):
            return str(d["client_id"]), str(d["client_secret"])
    except Exception:
        pass
    return None


def _vault_login(server: str, email: str, pw: str, api=None):
    """Connexion par mot de passe, ou par clé d'API (second facteur). Un client d'avant la clé d'API l'ignore."""
    if api:
        try:
            return _vaultcli.login(server, email, pw, api=api)
        except TypeError:
            return None, "client du coffre trop ancien pour la clé d'API (réinstaller vault_client.py)"
    return _vaultcli.login(server, email, pw)


def _user_vault_session(username: str):
    """Ouvre (et met en cache) une session sur le coffre NATIF du user. Retourne (sess, err)."""
    if _vaultcli is None:
        return None, "vault_client indisponible"
    with _user_vault_lock:
        cached = _USER_VAULT_SESS.get(username)
        if cached and (time.time() - cached[1]) < _USER_VAULT_SESS_TTL:
            return cached[0], None
        echec = _USER_VAULT_ERR.get(username)
        if echec and (time.time() - echec[1]) < _USER_VAULT_PAUSE:
            return None, echec[0]
    pw = None
    try:
        pw = vault_get(_vault_account_pw_name(username))
    except Exception:
        pw = None
    if not pw:
        return None, "coffre du user non provisionné"
    env = _vault_env()
    server = env.get("BW_SERVER")
    if not server:
        return None, "vault.env sans BW_SERVER"
    sess, err = _vault_login(server, _vault_account_email(username), pw, _vault_cle_api(username))
    if err:
        if "TwoFactorProviders" in str(err):
            err = "second_facteur"
        with _user_vault_lock:
            _USER_VAULT_ERR[username] = (str(err)[:300], time.time())
        logging.info("[COFFRE] ouverture du coffre de %s : %s", username, str(err)[:160])
        return None, err
    with _user_vault_lock:
        _USER_VAULT_SESS[username] = (sess, time.time())
        _USER_VAULT_ERR.pop(username, None)
    return sess, None


def vault_cle_api_poser(username: str, client_id: str, client_secret: str) -> dict:
    """La personne confie la clé d'API de SON coffre (Paramètres › Sécurité › Clés du coffre web). Elle est essayée
    AVANT d'être gardée : une clé fausse ne remplace jamais une bonne. Vide = la retirer."""
    if not username or _vaultcli is None:
        return {"ok": False, "reason": "coffre indisponible"}
    client_id, client_secret = str(client_id or "").strip(), str(client_secret or "").strip()
    nom = _vault_account_api_name(username)
    if not client_id and not client_secret:
        vault_delete(nom)
        _user_vault_invalidate(username)
        return {"ok": True, "retiree": True}
    if not re.fullmatch(r"user\.[0-9a-fA-F-]{36}", client_id) or len(client_secret) < 20:
        return {"ok": False, "reason": "client_id attendu sous la forme « user.xxxxxxxx-… », et le client_secret entier"}
    pw = vault_get(_vault_account_pw_name(username))
    server = _vault_env().get("BW_SERVER")
    if not pw or not server:
        return {"ok": False, "reason": "coffre du compte non provisionné"}
    sess, err = _vault_login(server, _vault_account_email(username), pw, (client_id, client_secret))
    if err:
        return {"ok": False, "reason": "le coffre refuse cette clé : %s" % str(err)[:160]}
    r = vault_set(nom, json.dumps({"client_id": client_id, "client_secret": client_secret}))
    if not r.get("ok"):
        return {"ok": False, "reason": r.get("error") or "rangement impossible"}
    with _user_vault_lock:
        _USER_VAULT_SESS[username] = (sess, time.time())
        _USER_VAULT_ERR.pop(username, None)
    return {"ok": True}


def _user_vault_invalidate(username: str) -> None:
    with _user_vault_lock:
        _USER_VAULT_SESS.pop(username, None)
        _USER_VAULT_ERR.pop(username, None)


# ── LA FICHE D'UN SECRET (22-09, maquette validée par l'usager) ──────────────────────────────────────
# Le client minimal de vault_client.py ne lit qu'une partie d'un chiffré (nom, identifiant, mot de passe,
# première adresse, code TOTP) et ne sait que créer ou remplacer. La fiche a besoin de TOUT ce que le coffre
# sait — notes d'un identifiant, champs personnalisés, favori, dates, anciens mots de passe, la carte entière —
# et de MODIFIER un secret sans rien perdre de ce qu'elle ne montre pas (dossier, organisation, réinvite,
# identité). Tout est ici, sur les primitives du client (chiffrer, déchiffrer, appeler) : le fichier installé
# par install.sh ne bouge pas.
_VW_KINDS = {1: "login", 2: "note", 3: "card", 4: "identity"}
_VW_AGENT_CHAMP = "cassandra"        # le champ personnalisé qui dit « utilisable par Cassandra pour agir »
_VW_CONTEXTE_CHAMP = "contexte"      # pour une note : ce qu'elle est, à côté de sa valeur (un champ, pas les notes)
_VW_HISTORIQUE_MAX = 5


def _vw_g(o, *cles):
    """Un champ d'un chiffré, quelle que soit la casse de sa clé (« Id » ou « id ») : Vaultwarden rend l'une
    ou l'autre selon le client qu'il croit servir."""
    if not isinstance(o, dict):
        return None
    for k in cles:
        for kk in (k, k[:1].lower() + k[1:], k[:1].upper() + k[1:]):
            if kk in o and o[kk] is not None:
                return o[kk]
    return None


def _vw_maintenant() -> str:
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.000Z")


def _vw_agent(d) -> bool:
    """« Utilisable par Cassandra pour agir » : le champ personnalisé `cassandra = oui`, ou — pour les secrets
    de service qu'elle pose elle-même (courrier, Telegram, agenda…) — un nom en chemin `xxx/yyy`."""
    for f in (d.get("fields") or []):
        if str(f.get("name") or "").strip().lower() == _VW_AGENT_CHAMP:
            return str(f.get("value") or "").strip().lower() in ("oui", "1", "true", "yes")
    return "/" in str(d.get("name") or "")


def _vw_decoder(c, ek, mk) -> dict:
    """Le chiffré entier, déchiffré. Une valeur absente est une chaîne vide, jamais None : la fiche affiche."""
    def dec(x):
        v = _vaultcli._dec_str(x, ek, mk) if x else None
        return v if v is not None else ""
    typ = int(_vw_g(c, "Type") or 2)
    d = {"id": _vw_g(c, "Id"), "type": typ, "kind": _VW_KINDS.get(typ, "note"),
         "name": dec(_vw_g(c, "Name")), "notes": dec(_vw_g(c, "Notes")),
         "favorite": bool(_vw_g(c, "Favorite") or False),
         "creation": str(_vw_g(c, "CreationDate") or "")[:19], "revision": str(_vw_g(c, "RevisionDate") or "")[:19],
         "fields": [], "historique": [], "uris": [], "username": "", "password": "", "totp": "", "uri": "", "mdp_date": ""}
    for f in (_vw_g(c, "Fields") or []):
        d["fields"].append({"name": dec(_vw_g(f, "Name")), "value": dec(_vw_g(f, "Value")), "type": int(_vw_g(f, "Type") or 0)})
    for h in (_vw_g(c, "PasswordHistory") or []):
        d["historique"].append({"password": dec(_vw_g(h, "Password")), "date": str(_vw_g(h, "LastUsedDate") or "")[:19]})
    lg = _vw_g(c, "Login")
    if lg:
        d["username"] = dec(_vw_g(lg, "Username"))
        d["password"] = dec(_vw_g(lg, "Password"))
        d["totp"] = dec(_vw_g(lg, "Totp"))
        d["uris"] = [dec(_vw_g(u, "Uri")) for u in (_vw_g(lg, "Uris") or []) if _vw_g(u, "Uri")]
        d["uri"] = d["uris"][0] if d["uris"] else ""
        d["mdp_date"] = str(_vw_g(lg, "PasswordRevisionDate") or "")[:19]
    cd = _vw_g(c, "Card")
    if cd:
        for cle, brut in (("card_holder", "CardholderName"), ("card_number", "Number"), ("card_brand", "Brand"),
                          ("card_exp_month", "ExpMonth"), ("card_exp_year", "ExpYear"), ("card_code", "Code")):
            d[cle] = dec(_vw_g(cd, brut))
    if d["kind"] == "note":
        d["value"] = d["notes"]
    d["agent"] = _vw_agent(d)
    return d


def _vw_age_jours(d):
    """Depuis quand ce mot de passe : sa date de révision, sinon la plus récente des anciennes valeurs (le jour
    où on l'a remplacée), sinon la création. None si rien n'est daté."""
    dates = []
    if d.get("mdp_date"):
        dates = [d["mdp_date"]]
    else:
        anciennes = sorted([h.get("date") for h in (d.get("historique") or []) if h.get("date")], reverse=True)
        dates = anciennes[:1] or ([d.get("creation")] if d.get("creation") else [])
    for src in dates:
        try:
            t = datetime.strptime(str(src)[:19], "%Y-%m-%dT%H:%M:%S")
            return max(0, int((datetime.utcnow() - t).total_seconds() // 86400))
        except Exception:
            continue
    return None


def _vw_chiffres(sess):
    """Tous les chiffrés du coffre, bruts ET lus : [(brut, lu)]. Un chiffré illisible est passé, pas fatal."""
    raw, err = _vaultcli._ciphers_raw(sess)
    if err:
        return [], str(err)
    ek, mk = sess["user_enc"], sess["user_mac"]
    out = []
    for c in (raw or []):
        try:
            out.append((c, _vw_decoder(c, ek, mk)))
        except Exception as e:
            logging.info("[COFFRE] chiffré illisible : %s", e)
    return out, None


def _vw_trouver(sess, name):
    paires, err = _vw_chiffres(sess)
    if err:
        return None, None, err
    for c, d in paires:
        if d.get("name") == name:
            return c, d, None
    return None, None, None


def _vw_camel(o):
    """Les clés d'un sous-objet passées en camelCase, telles que l'API les attend en écriture."""
    if not isinstance(o, dict):
        return o
    return {(k[:1].lower() + k[1:]): v for k, v in o.items()}


def _vw_requete(c, ek, mk, patch: dict) -> dict:
    """Le corps d'une réécriture : le chiffré tel qu'il est, où seuls les champs du `patch` changent (et sont
    rechiffrés). Ce que la fiche ne montre pas — dossier, organisation, réinvite, identité — repart intact."""
    def enc(x):
        x = "" if x is None else str(x)
        return _vaultcli._enc(x.encode("utf-8"), ek, mk) if x else None
    typ = int(_vw_g(c, "Type") or 2)
    body = {"type": typ, "organizationId": _vw_g(c, "OrganizationId"), "folderId": _vw_g(c, "FolderId"),
            "favorite": bool(patch["favorite"]) if "favorite" in patch else bool(_vw_g(c, "Favorite") or False),
            "reprompt": int(_vw_g(c, "Reprompt") or 0),
            "name": enc(patch["name"]) if "name" in patch else _vw_g(c, "Name"),
            "notes": enc(patch["notes"]) if "notes" in patch else _vw_g(c, "Notes"),
            "login": None, "secureNote": None, "card": None, "identity": None}
    # LES CHAMPS PERSONNALISÉS — et le drapeau « utilisable par Cassandra », qui en est un
    if "fields" in patch:
        champs = [{"type": int(f.get("type") or 0), "name": enc(f.get("name")), "value": enc(f.get("value")), "linkedId": None}
                  for f in (patch.get("fields") or []) if isinstance(f, dict) and str(f.get("name") or "").strip()
                  and str(f.get("name")).strip().lower() != _VW_AGENT_CHAMP]
        # le drapeau tel qu'il était, si le patch ne le touche pas
        if "agent" not in patch:
            for f in (_vw_g(c, "Fields") or []):
                nom = _vaultcli._dec_str(_vw_g(f, "Name"), ek, mk) if _vw_g(f, "Name") else ""
                if str(nom or "").strip().lower() == _VW_AGENT_CHAMP:
                    champs.append({"type": int(_vw_g(f, "Type") or 0), "name": _vw_g(f, "Name"), "value": _vw_g(f, "Value"), "linkedId": None})
    else:
        champs = [{"type": int(_vw_g(f, "Type") or 0), "name": _vw_g(f, "Name"), "value": _vw_g(f, "Value"), "linkedId": _vw_g(f, "LinkedId")}
                  for f in (_vw_g(c, "Fields") or [])]
        if "agent" in patch:
            garde = []
            for f in champs:
                nom = _vaultcli._dec_str(f.get("name"), ek, mk) if (f.get("name") and str(f.get("name")).startswith("2.")) else f.get("name")
                if str(nom or "").strip().lower() != _VW_AGENT_CHAMP:
                    garde.append(f)
            champs = garde
    if "agent" in patch and patch.get("agent"):
        champs.append({"type": 0, "name": enc(_VW_AGENT_CHAMP), "value": enc("oui"), "linkedId": None})
    body["fields"] = champs or None
    hist = [{"password": _vw_g(h, "Password"), "lastUsedDate": _vw_g(h, "LastUsedDate")} for h in (_vw_g(c, "PasswordHistory") or [])]
    if typ == 1:
        lg = _vw_g(c, "Login") or {}
        ancien = _vw_g(lg, "Password")
        mdp_date = _vw_g(lg, "PasswordRevisionDate")
        nouveau = ancien
        if "password" in patch:
            clair_ancien = (_vaultcli._dec_str(ancien, ek, mk) if ancien else "") or ""
            if str(patch.get("password") or "") != clair_ancien:
                nouveau = enc(patch.get("password"))
                if ancien:
                    # L'ANCIEN MOT DE PASSE ENTRE DANS L'HISTORIQUE, DATÉ : c'est ce que fait l'application Bitwarden
                    hist.insert(0, {"password": ancien, "lastUsedDate": _vw_maintenant()})
                    hist = hist[:_VW_HISTORIQUE_MAX]
                mdp_date = _vw_maintenant()
        uris = [{"uri": _vw_g(u, "Uri"), "match": _vw_g(u, "Match")} for u in (_vw_g(lg, "Uris") or [])]
        if "uri" in patch:
            premiere = ([{"uri": enc(patch.get("uri")), "match": None}] if str(patch.get("uri") or "").strip() else [])
            uris = premiere + uris[1:]
        body["login"] = {"username": enc(patch["username"]) if "username" in patch else _vw_g(lg, "Username"),
                         "password": nouveau, "totp": enc(patch["totp"]) if "totp" in patch else _vw_g(lg, "Totp"),
                         "uris": uris or None, "passwordRevisionDate": mdp_date,
                         "autofillOnPageLoad": _vw_g(lg, "AutofillOnPageLoad")}
    elif typ == 2:
        sn = _vw_g(c, "SecureNote") or {}
        body["secureNote"] = {"type": int(_vw_g(sn, "Type") or 0)}
        if "value" in patch:
            body["notes"] = enc(patch.get("value"))
    elif typ == 3:
        cd = _vw_g(c, "Card") or {}
        body["card"] = {}
        for cle, brut, api in (("card_holder", "CardholderName", "cardholderName"), ("card_brand", "Brand", "brand"),
                               ("card_number", "Number", "number"), ("card_exp_month", "ExpMonth", "expMonth"),
                               ("card_exp_year", "ExpYear", "expYear"), ("card_code", "Code", "code")):
            body["card"][api] = enc(patch[cle]) if cle in patch else _vw_g(cd, brut)
    else:
        body["identity"] = _vw_camel(_vw_g(c, "Identity"))
    body["passwordHistory"] = hist or None
    return body


def _vw_corps_neuf(kind: str, name: str, v: dict, ek, mk) -> dict:
    """Le corps d'un secret NEUF, par genre — identifiant, note, carte — avec ses notes, ses champs, son drapeau."""
    def enc(x):
        x = "" if x is None else str(x)
        return _vaultcli._enc(x.encode("utf-8"), ek, mk) if x else None
    typ = {"login": 1, "note": 2, "card": 3}.get(kind, 2)
    champs = [{"type": int(f.get("type") or 0), "name": enc(f.get("name")), "value": enc(f.get("value")), "linkedId": None}
              for f in (v.get("fields") or []) if isinstance(f, dict) and str(f.get("name") or "").strip()
              and str(f.get("name")).strip().lower() != _VW_AGENT_CHAMP]
    if v.get("agent"):
        champs.append({"type": 0, "name": enc(_VW_AGENT_CHAMP), "value": enc("oui"), "linkedId": None})
    body = {"type": typ, "name": enc(name), "notes": enc(v.get("value") if kind == "note" else v.get("notes")),
            "favorite": bool(v.get("favorite")), "fields": champs, "folderId": None, "organizationId": None,
            "reprompt": 0, "login": None, "secureNote": None, "card": None, "identity": None, "passwordHistory": None}
    if typ == 1:
        uri = str(v.get("uri") or "").strip()
        body["login"] = {"username": enc(v.get("username")), "password": enc(v.get("password")), "totp": enc(v.get("totp")),
                         "uris": ([{"uri": enc(uri), "match": None}] if uri else None),
                         "passwordRevisionDate": (_vw_maintenant() if v.get("password") else None), "autofillOnPageLoad": None}
    elif typ == 2:
        body["secureNote"] = {"type": 0}
    else:
        body["card"] = {"cardholderName": enc(v.get("card_holder")), "brand": enc(v.get("card_brand")), "number": enc(v.get("card_number")),
                        "expMonth": enc(v.get("card_exp_month")), "expYear": enc(v.get("card_exp_year")), "code": enc(v.get("card_code"))}
    return body


def vault_native_list(username: str) -> dict:
    """Liste SANS valeurs sensibles — mais avec ce que la liste et la fiche montrent : genre, identifiant, adresse,
    favori, dates, drapeau « utilisable par Cassandra », présence d'un code TOTP, nombre de champs, âge du mot de
    passe, et « même mot de passe qu'un autre » (compté ici ; la valeur ne sort jamais)."""
    sess, err = _user_vault_session(username)
    if not sess:
        return {"ok": False, "error": err, "items": [], "names": []}
    paires, e = _vw_chiffres(sess)
    if e:
        return {"ok": False, "error": str(e), "items": [], "names": []}
    empreintes = {}
    for _c, d in paires:
        if d.get("kind") == "login" and d.get("password"):
            empreintes.setdefault(hashlib.sha256(d["password"].encode("utf-8")).hexdigest(), []).append(d.get("name"))
    out = []
    for _c, d in paires:
        if not d.get("name"):
            continue
        h = hashlib.sha256(d["password"].encode("utf-8")).hexdigest() if (d.get("kind") == "login" and d.get("password")) else ""
        out.append({"name": d["name"], "kind": d.get("kind", "note"), "username": d.get("username") or "", "uri": d.get("uri") or "",
                    "favorite": bool(d.get("favorite")), "revision": d.get("revision") or "", "creation": d.get("creation") or "",
                    "agent": bool(d.get("agent")), "totp": bool(d.get("totp")),
                    "champs": len([f for f in (d.get("fields") or []) if str(f.get("name") or "").strip().lower() not in (_VW_AGENT_CHAMP, _VW_CONTEXTE_CHAMP)]),
                    "mdp_age": _vw_age_jours(d) if d.get("kind") == "login" else None,
                    "doublon": bool(h and len(empreintes.get(h) or []) > 1)})
    out.sort(key=lambda x: x["name"].lower())
    return {"ok": True, "items": out, "names": [o["name"] for o in out]}


def vault_native_get(username: str, name: str):
    """Détail complet d'un secret (valeurs comprises) — pour révélation côté propriétaire. Les anciens mots de
    passe ne sortent pas d'ici (voir `vault_native_historique`) : on n'en donne que le nombre. Les clés que les
    services lisent (username, password, uri, totp, value, card_*) sont inchangées."""
    sess, err = _user_vault_session(username)
    if not sess:
        return None
    paires, e = _vw_chiffres(sess)
    if e:
        return None
    vise = None
    for _c, d in paires:
        if d.get("name") == (name or "").strip():
            vise = d
            break
    if not vise:
        return None
    d = dict(vise)
    d["historique_n"] = len(d.pop("historique", []) or [])
    tous_champs = d.pop("fields", []) or []
    d["fields"] = [f for f in tous_champs if str(f.get("name") or "").strip().lower() not in (_VW_AGENT_CHAMP, _VW_CONTEXTE_CHAMP)]
    d["contexte"] = next((str(f.get("value") or "") for f in tous_champs if str(f.get("name") or "").strip().lower() == _VW_CONTEXTE_CHAMP), "")
    d["doublons"] = [x.get("name") for _c, x in paires if x is not vise and d.get("kind") == "login" and x.get("kind") == "login"
                     and d.get("password") and x.get("password") == d.get("password")]
    d["mdp_age"] = _vw_age_jours(vise) if d.get("kind") == "login" else None
    return d


def vault_native_update(username: str, name: str, patch: dict) -> dict:
    """Modifie un secret SANS rien perdre. `patch` ne porte que ce qui change : name, username, password, uri,
    totp, notes, value (note), contexte (note), fields, favorite, agent, card_*."""
    name = (name or "").strip()
    if not name:
        return {"ok": False, "error": "nom requis"}
    if not isinstance(patch, dict) or not patch:
        return {"ok": False, "error": "rien à modifier"}
    sess, err = _user_vault_session(username)
    if not sess:
        return {"ok": False, "error": err or "coffre indisponible"}
    paires, e = _vw_chiffres(sess)
    if e:
        return {"ok": False, "error": str(e)}
    c, lu = None, None
    for brut, d in paires:
        if d.get("name") == name:
            c, lu = brut, d
            break
    if c is None:
        return {"ok": False, "error": "secret introuvable"}
    patch = dict(patch)
    if "name" in patch:
        nouveau_nom = str(patch.get("name") or "").strip()
        if not nouveau_nom:
            return {"ok": False, "error": "le nom ne peut pas être vide"}
        if nouveau_nom != name and any(d.get("name") == nouveau_nom for _b, d in paires):
            return {"ok": False, "error": "un secret porte déjà ce nom"}
        patch["name"] = nouveau_nom
    # LE CONTEXTE D'UNE NOTE est un champ personnalisé : il se range avec les autres champs
    if "contexte" in patch:
        champs = patch.get("fields") if "fields" in patch else [f for f in (lu.get("fields") or [])
                                                                 if str(f.get("name") or "").strip().lower() not in (_VW_AGENT_CHAMP, _VW_CONTEXTE_CHAMP)]
        champs = [f for f in (champs or []) if str((f or {}).get("name") or "").strip().lower() != _VW_CONTEXTE_CHAMP]
        if str(patch.get("contexte") or "").strip():
            champs.append({"name": _VW_CONTEXTE_CHAMP, "value": str(patch.get("contexte")), "type": 0})
        patch["fields"] = champs
        patch.pop("contexte", None)
    elif "fields" in patch:
        # les champs édités arrivent sans le contexte : on le garde tel qu'il est
        ctx = next((f for f in (lu.get("fields") or []) if str(f.get("name") or "").strip().lower() == _VW_CONTEXTE_CHAMP), None)
        if ctx:
            patch["fields"] = list(patch.get("fields") or []) + [ctx]
    body = _vw_requete(c, sess["user_enc"], sess["user_mac"], patch)
    data, e = _vaultcli._req("PUT", sess["server"] + "/api/ciphers/" + str(_vw_g(c, "Id")), body, headers=_vaultcli._auth(sess))
    if data is None:
        return {"ok": False, "error": str(e)[:200]}
    return {"ok": True, "id": _vw_g(data, "Id") or _vw_g(c, "Id"), "name": patch.get("name") or name}


def vault_native_creer(username: str, name: str, kind: str, valeurs: dict) -> dict:
    """Crée un secret complet — identifiant, note ou carte — avec notes, champs, contexte et drapeau, en un appel."""
    name = (name or "").strip()
    if not name:
        return {"ok": False, "error": "nom requis"}
    sess, err = _user_vault_session(username)
    if not sess:
        return {"ok": False, "error": err or "coffre indisponible"}
    paires, e = _vw_chiffres(sess)
    if e:
        return {"ok": False, "error": str(e)}
    if any(d.get("name") == name for _b, d in paires):
        return {"ok": False, "error": "un secret porte déjà ce nom"}
    v = dict(valeurs or {})
    if str(v.get("contexte") or "").strip():
        v["fields"] = list(v.get("fields") or []) + [{"name": _VW_CONTEXTE_CHAMP, "value": str(v.get("contexte")), "type": 0}]
    body = _vw_corps_neuf(kind, name, v, sess["user_enc"], sess["user_mac"])
    data, e = _vaultcli._req("POST", sess["server"] + "/api/ciphers", body, headers=_vaultcli._auth(sess))
    if data is None:
        return {"ok": False, "error": str(e)[:200]}
    return {"ok": True, "id": _vw_g(data, "Id"), "name": name}


def vault_native_historique(username: str, name: str) -> dict:
    """Les anciens mots de passe d'un identifiant, datés — révélés à la demande ; la route les inscrit au journal."""
    sess, err = _user_vault_session(username)
    if not sess:
        return {"ok": False, "error": err or "coffre indisponible", "historique": []}
    _c, d, e = _vw_trouver(sess, (name or "").strip())
    if e or not d:
        return {"ok": False, "error": str(e) if e else "secret introuvable", "historique": []}
    return {"ok": True, "historique": d.get("historique") or []}


def _totp_code(secret: str, quand: float = None):
    """Le code à usage unique courant d'une clé TOTP (RFC 6238) : (code, secondes restantes, période). La clé est
    soit un `otpauth://totp/...?secret=…&digits=…&period=…&algorithm=…`, soit la seule graine en base32.
    None si la clé ne se lit pas."""
    x = str(secret or "").strip()
    if not x:
        return None
    graine, chiffres, periode, algo = x, 6, 30, "sha1"
    if x.lower().startswith("otpauth://"):
        try:
            from urllib.parse import urlparse as _up, parse_qs as _pq
            q = _pq(_up(x).query)
            graine = (q.get("secret") or [""])[0]
            chiffres = int((q.get("digits") or ["6"])[0] or 6)
            periode = int((q.get("period") or ["30"])[0] or 30)
            algo = ((q.get("algorithm") or ["SHA1"])[0] or "SHA1").lower().replace("-", "")
        except Exception:
            return None
    graine = re.sub(r"[\s\-]", "", graine).upper()
    try:
        cle = base64.b32decode(graine + "=" * (-len(graine) % 8), casefold=True)
    except Exception:
        return None
    if not cle:
        return None
    t = int(quand if quand is not None else time.time())
    periode = max(1, periode)
    h = hmac.new(cle, struct.pack(">Q", t // periode), getattr(hashlib, algo if algo in ("sha1", "sha256", "sha512") else "sha1")).digest()
    o = h[-1] & 0x0F
    code = (struct.unpack(">I", h[o:o + 4])[0] & 0x7FFFFFFF) % (10 ** chiffres)
    return str(code).zfill(chiffres), periode - (t % periode), periode


_VW_TOTP_TRACE = {}    # (compte, nom) -> dernière inscription au journal : le code se relit toutes les trente secondes


def vault_native_totp(username: str, name: str) -> dict:
    sess, err = _user_vault_session(username)
    if not sess:
        return {"ok": False, "error": err or "coffre indisponible"}
    _c, d, e = _vw_trouver(sess, (name or "").strip())
    if e or not d:
        return {"ok": False, "error": str(e) if e else "secret introuvable"}
    if not d.get("totp"):
        return {"ok": False, "error": "pas de clé TOTP sur ce secret"}
    r = _totp_code(d["totp"])
    if not r:
        return {"ok": False, "error": "clé TOTP illisible"}
    cle = ((username or "").strip().lower(), (name or "").strip())
    if time.time() - _VW_TOTP_TRACE.get(cle, 0) > 600:
        _VW_TOTP_TRACE[cle] = time.time()
        _vault_audit(username, "totp", name)
    return {"ok": True, "code": r[0], "reste": r[1], "periode": r[2]}


def vault_native_get_pour_agent(username: str, name: str):
    """[QUARANTAINE jusqu'au 2027-01-08] Aucun usage trouvé le 2026-10-10 : ni lecture de son nom,
    ni chaîne qui le porte, ni décorateur, ni trace au journal sur trente jours. Le corps est mis de
    côté, pas supprimé : s'il est appelé, le fil se tire — alerte critique, quarantaine annulée,
    version d'avant restaurée. Une fonction ne se retire qu'après avoir crié sans être entendue.

    Ce que la fonction disait d'elle-même :
    Ce qu'un AGENT peut lire du coffre d'une personne : un secret marqué « utilisable par Cassandra », rien
    d'autre — et l'usage s'inscrit au journal sous ce nom. C'est la porte que la fiche décrit ; aucun outil ne
    la franchit encore de lui-même : les secrets de service passent par leurs clés fixes.
    """
    return evolution_fil_tire('vault_native_get_pour_agent')


def vault_native_set(username: str, name: str, value: str) -> dict:
    name = (name or "").strip()
    if not name:
        return {"ok": False, "error": "nom requis"}
    sess, err = _user_vault_session(username)
    if not sess:
        return {"ok": False, "error": err or "coffre indisponible"}
    _id, e = _vaultcli.set_item(sess, name, value)
    return {"ok": e is None, "error": (str(e) if e else None), "id": _id}


def vault_native_set_login(username: str, name: str, login_user: str, login_pwd: str,
                           uri: str = "", totp: str = "") -> dict:
    name = (name or "").strip()
    if not name:
        return {"ok": False, "error": "nom requis"}
    sess, err = _user_vault_session(username)
    if not sess:
        return {"ok": False, "error": err or "coffre indisponible"}
    _id, e = _vaultcli.set_login(sess, name, login_user or "", login_pwd or "", uri or "", totp or "")
    return {"ok": e is None, "error": (str(e) if e else None), "id": _id}


def vault_native_delete(username: str, name: str) -> dict:
    sess, err = _user_vault_session(username)
    if not sess:
        return {"ok": False, "error": err or "coffre indisponible"}
    ok, e = _vaultcli.delete_item(sess, (name or "").strip())
    return {"ok": bool(ok), "error": (str(e) if e else None)}


# ── Onboarding app Bitwarden : URL publique du coffre + QR ──────────────────────
def _vault_public_url() -> str:
    """URL que l'user saisit dans l'app Bitwarden (serveur auto-hébergé). Admin-réglable ;
    sinon repli sur VAULT_DOMAIN / BW_SERVER."""
    try:
        u = (get_cassandra_config().get("vault_public_url") or "").strip()
        if u:
            return u
    except Exception:
        pass
    env = _vault_env()
    return env.get("VAULT_DOMAIN") or env.get("BW_SERVER") or "https://127.0.0.1:8087"


def _vault_set_public_url(url: str) -> dict:
    url = (url or "").strip()
    if url and not url.startswith(("http://", "https://")):
        url = "https://" + url
    try:
        cfg = get_cassandra_config()
        cfg["vault_public_url"] = url
        save_cassandra_config(cfg)
        return {"ok": True, "url": url}
    except Exception as e:
        return {"ok": False, "error": str(e)}


def _vault_qr_svg(url: str) -> dict:
    """QR (SVG, sans dépendance PIL) encodant l'URL du coffre. Dégradation propre si qrcode absent."""
    try:
        import qrcode
        import qrcode.image.svg as _svg
        qr = qrcode.QRCode(box_size=8, border=2)
        qr.add_data(url or "")
        qr.make(fit=True)
        import io
        buf = io.BytesIO()
        qr.make_image(image_factory=_svg.SvgPathImage).save(buf)
        return {"ok": True, "svg": buf.getvalue().decode("utf-8"), "url": url}
    except Exception:
        return {"ok": False, "error": "qrcode indisponible", "url": url}


def sync_user_vault_password(username: str, new_password: str) -> dict:
    """Garde le coffre natif aligné sur le mdp Cassandra. Si non provisionné → provisionne.
    Si le mdp change → re-clé le compte Vault (les secrets restent lisibles)."""
    if _vaultcli is None:
        return {"ok": False, "error": "vault_client indisponible"}
    old_pw = None
    try:
        old_pw = vault_get(_vault_account_pw_name(username))
    except Exception:
        old_pw = None
    if not old_pw:
        return provision_user_vault(username, new_password)
    if old_pw == new_password:
        return {"ok": True, "unchanged": True}
    env = _vault_env()
    server = env.get("BW_SERVER")
    if not server:
        return {"ok": False, "error": "vault.env sans BW_SERVER"}
    ok, err = _vaultcli.change_password(server, _vault_account_email(username), old_pw, new_password)
    if not ok:
        return {"ok": False, "error": "re-clé coffre: %s" % err}
    try:
        vault_set(_vault_account_pw_name(username), new_password)
    except Exception:
        pass
    _user_vault_invalidate(username)
    return {"ok": True, "rekeyed": True}


def provision_user_vault_async(username: str, password: str) -> None:
    """Provisionne/aligne le coffre en arrière-plan (ne ralentit jamais le login).
    Met aussi le compte en file d'attente : si le coffre est indisponible MAINTENANT,
    le réconciliateur le rattrapera dès qu'il revient (auto-réparation)."""
    enqueue_vault_provision(username, password)
    def _run():
        try:
            sync_user_vault_password(username, password)
        except Exception as e:
            print("[VAULT] provisioning %s: %s" % (username, e))
    threading.Thread(target=_run, daemon=True).start()


# ── Réconciliateur : auto-réparation du provisioning des coffres ────────────────
#   Si le coffre est down quand un compte est créé/connecté, le mdp est gardé EN RAM
#   (jamais sur disque) et le provisioning est retenté périodiquement jusqu'à réussite.
_VAULT_PENDING: dict = {}            # email -> password (volatile, RAM uniquement)
_vault_pending_lock = threading.Lock()


def enqueue_vault_provision(username: str, password: str) -> None:
    u = (username or "").strip().lower()
    if not u or not password:
        return
    with _vault_pending_lock:
        _VAULT_PENDING[u] = password


def _vault_reconcile_once() -> int:
    """Tente de provisionner tous les comptes en attente. Retire ceux désormais OK.
    Retourne le nombre encore en attente."""
    if _vaultcli is None or not vault_available():
        with _vault_pending_lock:
            return len(_VAULT_PENDING)
    with _vault_pending_lock:
        items = list(_VAULT_PENDING.items())
    done = []
    for email, pw in items:
        try:
            if vault_account_provisioned(email):
                done.append(email); continue
            r = sync_user_vault_password(email, pw)
            if r.get("ok"):
                done.append(email)
                print("[VAULT] coffre réconcilié pour %s" % email)
        except Exception as e:
            print("[VAULT] réconciliation %s: %s" % (email, e))
    with _vault_pending_lock:
        for e in done:
            _VAULT_PENDING.pop(e, None)
        return len(_VAULT_PENDING)


def _vault_reconcile_loop():
    # petit délai initial pour laisser le coffre démarrer au boot
    _shutdown_event.wait(45)
    while not _shutdown_event.is_set():
        try:
            _vault_reconcile_once()
        except Exception:
            pass
        _shutdown_event.wait(120)


def start_vault_reconcile():
    threading.Thread(target=_vault_reconcile_loop, daemon=True, name="vault-reconcile").start()


# ── V6 : audit des accès au coffre (qui, quoi, quand — jamais la valeur) ────────
def _vault_audit(username: str, action: str, secret_name: str) -> None:
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        conn.execute("CREATE TABLE IF NOT EXISTS vault_audit (id INTEGER PRIMARY KEY AUTOINCREMENT, "
                     "ts TEXT DEFAULT (datetime('now')), username TEXT, action TEXT, secret_name TEXT)")
        conn.execute("INSERT INTO vault_audit (username, action, secret_name) VALUES (?,?,?)",
                     (username or "?", action, secret_name or ""))
        conn.execute("DELETE FROM vault_audit WHERE id NOT IN (SELECT id FROM vault_audit ORDER BY id DESC LIMIT 3000)")
        conn.commit(); conn.close()
    except Exception:
        pass


def vault_audit_recent(username: str = None, limit: int = 50) -> list:
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10); conn.row_factory = sqlite3.Row
        if username:
            rows = conn.execute("SELECT ts, action, secret_name FROM vault_audit WHERE username=? "
                                "ORDER BY id DESC LIMIT ?", (username, limit)).fetchall()
        else:
            rows = conn.execute("SELECT ts, username, action, secret_name FROM vault_audit "
                                "ORDER BY id DESC LIMIT ?", (limit,)).fetchall()
        conn.close()
        return [dict(r) for r in rows]
    except Exception:
        return []


# ── Journal d'activité par utilisateur (ce que le user ET Cassandra font sur ses sites) ──
def log_user_activity(username: str, actor: str, action: str, detail: str = "") -> None:
    if str(action or "").startswith("note_"):
        try:
            _BJ_SIGNAL_CACHE.pop(((username or "").strip().lower(), "notes"), None)
        except Exception:
            pass
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        conn.execute("CREATE TABLE IF NOT EXISTS user_activity (id INTEGER PRIMARY KEY AUTOINCREMENT, "
                     "ts TEXT DEFAULT (datetime('now')), username TEXT, actor TEXT, action TEXT, detail TEXT)")
        conn.execute("INSERT INTO user_activity (username, actor, action, detail) VALUES (?,?,?,?)",
                     (username, actor, action, (detail or "")[:200]))
        conn.execute("DELETE FROM user_activity WHERE id NOT IN (SELECT id FROM user_activity ORDER BY id DESC LIMIT 5000)")
        conn.commit(); conn.close()
    except Exception:
        pass


def get_user_activity(username: str, limit: int = 40) -> list:
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10); conn.row_factory = sqlite3.Row
        conn.execute("CREATE TABLE IF NOT EXISTS user_activity (id INTEGER PRIMARY KEY AUTOINCREMENT, "
                     "ts TEXT DEFAULT (datetime('now')), username TEXT, actor TEXT, action TEXT, detail TEXT)")
        rows = conn.execute("SELECT ts, actor, action, detail FROM user_activity WHERE username=? "
                            "ORDER BY id DESC LIMIT ?", (username, limit)).fetchall()
        conn.close()
        return [dict(r) for r in rows]
    except Exception:
        return []


def _site_owners(domain: str) -> list:
    """Users (non-admin) qui possèdent ce domaine — pour leur notifier les actions sur leur site."""
    dn = _norm_domain(domain)
    out = []
    try:
        for email, v in load_users().items():
            rec = _user_record(v)
            # `user_sites` et non `rec["sites"]` : un compte dont les sites viennent du panneau
            # (fp_account) les voit dans l'onglet, il doit aussi en recevoir les alertes.
            if rec["role"] != "admin" and _site_est_a_moi(email, dn):
                out.append(email)
    except Exception:
        pass
    return out


def notify_site_owners(domain: str, action: str, actor: str = "cassandra") -> None:
    dn = _norm_domain(domain)
    for o in _site_owners(domain):
        log_user_activity(o, actor, action, dn)
        try:
            tmpl = _SITE_ACTION_MAIL.get(action)
            if tmpl and mail_configured():
                base = _app_public_url()
                notify_user_email(o, "Cassandra · %s" % dn, tmpl[0], tmpl[1] % dn,
                                  ("Voir mon espace" if base else ""), base, genre="site")
        except Exception:
            pass


def get_user_feed(username: str, limit: int = 40) -> list:
    """Fil fusionné : actions de site (user_activity) + accès au coffre (vault_audit)."""
    feed = []
    for a in get_user_activity(username, limit):
        feed.append({"ts": a.get("ts", ""), "who": a.get("actor", "cassandra"),
                     "action": a.get("action", ""), "detail": a.get("detail", "")})
    for e in vault_audit_recent(username, limit):
        feed.append({"ts": e.get("ts", ""), "who": "user",
                     "action": e.get("action", ""), "detail": e.get("secret_name", "")})
    feed.sort(key=lambda x: x.get("ts", ""), reverse=True)
    return feed[:limit]


def _vault_seed_secrets(force: bool = False) -> int:
    """Rapatrie les secrets actuels (fichiers/config) DANS le coffre. NE SUPPRIME RIEN : les
    sources d'origine restent (filet anti-lock-out). force=False → ne touche pas un secret déjà
    présent ; force=True → rafraîchit (upsert) depuis les sources actuelles."""
    if not vault_available():
        return 0
    try:
        cfg = get_cassandra_config()
    except Exception:
        cfg = {}
    pairs = [
        ("cassandra/deepseek_key", get_deepseek_key() or ""),
        ("cassandra/smtp_password", cfg.get("smtp_password", "")),
    ]
    for k in ("secondary_api_key", "dual_agent_key", "gemini_api_key", "secondary_key"):
        if cfg.get(k):
            pairs.append(("cassandra/secondary_key", cfg.get(k)))
            break
    seeded = 0
    for name, val in pairs:
        if not val:
            continue
        if force or vault_get(name) is None:
            if vault_set(name, str(val)).get("ok"):
                seeded += 1
    if seeded:
        logging.info("[VAULT] %d secret(s) rapatrié(s) dans le coffre" % seeded)
    return seeded


def _vault_seed_loop():
    """Attend que le coffre soit déverrouillé (sidecar ~qq s après boot), puis sème une fois."""
    for _ in range(40):
        try:
            if vault_available():
                _vault_seed_secrets(force=False)
                return
        except Exception as e:
            logging.warning("[VAULT] seed: %s" % e)
            return
        time.sleep(3)


def start_vault_seed():
    threading.Thread(target=_vault_seed_loop, daemon=True, name="vault-seed").start()


def _resolve_secret_refs(cmd: str) -> str:
    """Remplace {{secret:NOM}} par la valeur réelle du coffre, JUSTE avant l'exécution.
    La référence (pas la valeur) reste dans la commande affichée, journalisée et soumise à
    l'outil → le secret n'entre jamais dans le prompt, les logs, ni le modèle."""
    if not cmd or "{{secret:" not in cmd:
        return cmd
    def _repl(m):
        val = vault_get(m.group(1).strip())
        return val if val is not None else m.group(0)
    try:
        return re.sub(r"\{\{secret:([^}]+)\}\}", _repl, cmd)
    except Exception:
        return cmd


# ============================================================
# 15.5 MODE MULTI-SERVEUR — tokens chiffrés au repos
# ============================================================
MULTISERVER_CONFIG_FILE = CASSANDRA_DATA_DIR + "/multiserver.json"
_ms_lock = threading.Lock()
_ms_derived_key: bytes = b""          # cache — invalidé sur rotate_deepseek_key
_ms_derived_key_lock = threading.Lock()


FLOTTE_CLE_FILE = os.environ.get("CASSANDRA_FLOTTE_KEY_FILE") or CASSANDRA_CONF_DIR + "/flotte.key"


def _ms_maitre_ouvre(master: str) -> bool:
    """Ce secret maître ouvre-t-il les secrets déjà chiffrés de la Flotte ? Vrai s'il n'y en a aucun."""
    try:
        with open(MULTISERVER_CONFIG_FILE) as f:
            raw = json.load(f)
    except Exception:
        return True
    enc = [str(s.get(k) or "") for s in raw for k in ("ssh_key", "ssh_pass", "token")
           if str(s.get(k) or "").startswith("enc1:")]
    if not enc:
        return True
    try:
        from cryptography.fernet import Fernet
        kb = hashlib.pbkdf2_hmac("sha256", master.encode(), b"cassandra-multiserver-token-encryption-v1",
                                 iterations=100_000, dklen=32)
        Fernet(base64.urlsafe_b64encode(kb)).decrypt(enc[0][5:].encode())
        return True
    except Exception:
        return False


def _ms_maitre() -> str:
    """LE SECRET MAÎTRE DE LA FLOTTE, indépendant de la clé du modèle. Le fichier flotte.key
    d'abord ; à défaut, la clé API du moment est scellée dans ce fichier — mais seulement si
    elle ouvre bien les secrets existants : une clé qui vient de changer ne doit pas être
    gravée comme maître, sinon l'erreur deviendrait définitive."""
    try:
        with open(FLOTTE_CLE_FILE) as f:
            m = f.read().strip()
        if m:
            return m
    except FileNotFoundError:
        pass
    except Exception as e:
        logging.warning("[FLOTTE] %s illisible : %s", FLOTTE_CLE_FILE, e)
    m = DEEPSEEK_API_KEY or "cassandra-fallback-salt-insecure"
    if DEEPSEEK_API_KEY and _ms_maitre_ouvre(m):
        try:
            fd = os.open(FLOTTE_CLE_FILE, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
            with os.fdopen(fd, "w") as f:
                f.write(m)
            logging.info("[FLOTTE] secret maître scellé dans %s", FLOTTE_CLE_FILE)
        except FileExistsError:
            pass
        except Exception as e:
            logging.warning("[FLOTTE] scellement impossible : %s", e)
    elif DEEPSEEK_API_KEY:
        logging.warning("[FLOTTE] la clé API actuelle n'ouvre pas les secrets de la Flotte : posez l'ancienne "
                        "dans %s (chmod 600)", FLOTTE_CLE_FILE)
    return m


def _ms_derive_key() -> bytes:
    """Dérive la clé de chiffrement des tokens — mis en cache, coûteux une seule fois."""
    global _ms_derived_key
    with _ms_derived_key_lock:
        if _ms_derived_key:
            return _ms_derived_key
        master = _ms_maitre().encode()
        _ms_derived_key = hashlib.pbkdf2_hmac(
            "sha256",
            master,
            b"cassandra-multiserver-token-encryption-v1",
            iterations=100_000,
            dklen=32,
        )
        return _ms_derived_key


def _ms_invalidate_key_cache() -> None:
    """Appelé après rotate_deepseek_key pour forcer la re-dérivation."""
    global _ms_derived_key
    with _ms_derived_key_lock:
        _ms_derived_key = b""


def _ms_encrypt_token(token: str) -> str:
    if not token:
        return ""
    try:
        from cryptography.fernet import Fernet
        import base64 as b64
        key_bytes = _ms_derive_key()
        fernet_key = b64.urlsafe_b64encode(key_bytes)
        f = Fernet(fernet_key)
        encrypted = f.encrypt(token.encode())
        return "enc1:" + encrypted.decode()
    except ImportError:
        pass
    import hmac
    key = _ms_derive_key()
    token_bytes = token.encode()
    keystream = b""
    counter = 0
    while len(keystream) < len(token_bytes):
        keystream += hmac.new(key, struct.pack(">I", counter), "sha256").digest()
        counter += 1
    xored = bytes(a ^ b for a, b in zip(token_bytes, keystream[:len(token_bytes)]))
    mac = hmac.new(key, xored, "sha256").digest()
    payload = mac + xored
    return "enc0:" + base64.b64encode(payload).decode()


def _ms_decrypt_token(stored: str) -> str:
    if not stored:
        return ""
    if stored.startswith("enc1:"):
        try:
            from cryptography.fernet import Fernet
            import base64 as b64
            key_bytes = _ms_derive_key()
            fernet_key = b64.urlsafe_b64encode(key_bytes)
            f = Fernet(fernet_key)
            return f.decrypt(stored[5:].encode()).decode()
        except Exception as e:
            print(f"[MULTISERVER] Erreur déchiffrement Fernet: {e}", file=sys.stderr)
            return ""
    if stored.startswith("enc0:"):
        try:
            import hmac
            key = _ms_derive_key()
            payload = base64.b64decode(stored[5:])
            mac_stored, xored = payload[:32], payload[32:]
            keystream = b""
            counter = 0
            while len(keystream) < len(xored):
                keystream += hmac.new(key, struct.pack(">I", counter), "sha256").digest()
                counter += 1
            mac_check = hmac.new(key, xored, "sha256").digest()
            if not hmac.compare_digest(mac_stored, mac_check):
                print("[MULTISERVER] HMAC invalide", file=sys.stderr)
                return ""
            token_bytes = bytes(a ^ b for a, b in zip(xored, keystream[:len(xored)]))
            return token_bytes.decode()
        except Exception as e:
            print(f"[MULTISERVER] Erreur déchiffrement fallback: {e}", file=sys.stderr)
            return ""
    print("[MULTISERVER] ⚠️ Token en clair détecté", file=sys.stderr)
    return stored


def _ms_load() -> list:
    try:
        if os.path.exists(MULTISERVER_CONFIG_FILE):
            with open(MULTISERVER_CONFIG_FILE, "r") as f:
                raw = json.load(f)
            for s in raw:
                if "token" in s:
                    s["token"] = _ms_decrypt_token(s["token"])
                    s["_token_encrypted"] = True
            return raw
    except Exception as e:
        print(f"[MULTISERVER] Erreur chargement: {e}", file=sys.stderr)
    return []


def _ms_save(servers: list) -> None:
    # Le cache par processus (_load_servers_once) ne se vidait jamais : une machine ajoutée
    # depuis l'onglet restait invisible à fleet_list et remote_exec jusqu'au redémarrage.
    global _servers_cache, _server_ssh_dict_cache
    _servers_cache, _server_ssh_dict_cache = None, None
    try:
        Path(MULTISERVER_CONFIG_FILE).parent.mkdir(parents=True, exist_ok=True)
        safe = []
        for s in servers:
            entry = {k: v for k, v in s.items() if k != "_token_encrypted"}
            if "token" in entry and entry["token"]:
                raw_token = entry["token"]
                if not raw_token.startswith(("enc1:", "enc0:")):
                    entry["token"] = _ms_encrypt_token(raw_token)
            safe.append(entry)
        with open(MULTISERVER_CONFIG_FILE, "w") as f:
            json.dump(safe, f, indent=2, ensure_ascii=False)
        os.chmod(MULTISERVER_CONFIG_FILE, 0o600)
    except Exception as e:
        print(f"[MULTISERVER] Erreur sauvegarde: {e}", file=sys.stderr)


def ms_migrate_plaintext_tokens() -> int:
    if not os.path.exists(MULTISERVER_CONFIG_FILE):
        return 0
    try:
        with open(MULTISERVER_CONFIG_FILE, "r") as f:
            raw = json.load(f)
        migrated = 0
        for s in raw:
            tok = s.get("token", "")
            if tok and not tok.startswith(("enc1:", "enc0:")):
                s["token"] = _ms_encrypt_token(tok)
                migrated += 1
        if migrated:
            with open(MULTISERVER_CONFIG_FILE, "w") as f:
                json.dump(raw, f, indent=2, ensure_ascii=False)
            os.chmod(MULTISERVER_CONFIG_FILE, 0o600)
            print(f"[MULTISERVER] ✅ {migrated} token(s) migrés", file=sys.stderr)
        return migrated
    except Exception as e:
        print(f"[MULTISERVER] Erreur migration: {e}", file=sys.stderr)
        return 0


def ms_list() -> list:
    servers = _ms_load()
    return [{"name": s["name"], "url": s["url"], "enabled": s.get("enabled", True)} for s in servers]


def ms_add(name: str, url: str, token: str) -> dict:
    name = name.strip()
    url = url.rstrip("/")
    if not name or not url or not token:
        return {"ok": False, "error": "name, url et token sont requis"}
    if not url.startswith(("http://", "https://")):
        return {"ok": False, "error": "URL doit commencer par http:// ou https://"}
    with _ms_lock:
        servers = _ms_load()
        for s in servers:
            # 🔄 LIGNE MODIFIÉE : On compare l'URL unique plutôt que le nom
            if s["url"] == url:
                s["name"] = name
                s["token"] = token
                s["enabled"] = True
                _ms_save(servers)
                return {"ok": True, "action": "updated", "name": name}
        servers.append({"name": name, "url": url, "token": token, "enabled": True})
        _ms_save(servers)
        return {"ok": True, "action": "added", "name": name}


def ms_remove(name: str) -> dict:
    with _ms_lock:
        servers = _ms_load()
        before = len(servers)
        servers = [s for s in servers if s["name"] != name]
        if len(servers) == before:
            return {"ok": False, "error": f"Serveur '{name}' non trouvé"}
        _ms_save(servers)
    return {"ok": True, "name": name}


def ms_toggle(name: str, enabled: bool) -> dict:
    with _ms_lock:
        servers = _ms_load()
        for s in servers:
            if s["name"] == name:
                s["enabled"] = enabled
                _ms_save(servers)
                return {"ok": True, "name": name, "enabled": enabled}
    return {"ok": False, "error": f"Serveur '{name}' non trouvé"}


def _ms_fetch(server: dict, path: str, timeout: int = 6) -> dict | None:
    try:
        url = f"{server['url']}{path}"
        req = urllib.request.Request(url, headers={
            "X-Session-Token": server.get("token", ""),
            "User-Agent": "CASSANDRA-MultiServer/1.0",
        })
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            return json.loads(resp.read().decode())
    except urllib.error.HTTPError as e:
        return {"_error": f"HTTP {e.code}", "_server": server["name"]}
    except Exception as e:
        return {"_error": type(e).__name__, "_server": server["name"]}


# ── Fleet : connecteurs multi-type ────────────────────────────────────────────

def _ms_resolve_quickconnect(qc_id: str) -> tuple:
    """Résout un QuickConnect ID Synology → (host, port). Retourne ('',0) si échec."""
    try:
        data = json.dumps({
            "version": "1", "command": "get_server_info",
            "stop_when_error": "false", "stop_when_success": "false",
            "id": "dsm_portal_v2", "serverID": qc_id
        }).encode()
        req = urllib.request.Request(
            "https://global.quickconnect.to/Serv.php", data=data,
            headers={"Content-Type": "application/json"}, method="POST")
        with urllib.request.urlopen(req, timeout=10) as r:
            d = json.loads(r.read())
        env = d.get("env", {})
        ctrl = d.get("server", {})
        # Préférer l'accès externe (relais), sinon interface locale
        host = env.get("relay_region", "") and ctrl.get("interface", [{}])[0].get("ip", "")
        if not host:
            ifaces = ctrl.get("interface", [])
            host = ifaces[0].get("ip", "") if ifaces else ""
        port = ctrl.get("port", 5001)
        if host:
            return host, int(port)
    except Exception:
        pass
    return "", 0


def _ms_fetch_synology(server: dict) -> dict:
    """Métriques Synology DSM via SYNO.API — auth user/pass, pas de token."""
    import ssl as _ssl
    host     = server.get("syn_host", "").strip()
    qc_id    = server.get("syn_qc", "").strip()
    port     = int(server.get("syn_port", 5000))
    username = server.get("syn_user", "")
    password = _ms_decrypt_token(server.get("syn_pass", ""))
    use_ssl  = bool(server.get("syn_ssl", False))
    scheme   = "https" if use_ssl else "http"
    name     = server.get("name", "")

    if qc_id and not host:
        host, port = _ms_resolve_quickconnect(qc_id)
        if not host:
            return {"_error": "QuickConnect introuvable", "_server": name}

    ctx = _ssl._create_unverified_context() if use_ssl else None

    def _get(api, version, method, extra="", sid=""):
        sid_param = f"&_sid={sid}" if sid else ""
        url = (f"{scheme}://{host}:{port}/webapi/entry.cgi?"
               f"api={api}&version={version}&method={method}{extra}{sid_param}")
        req = urllib.request.Request(url, headers={"User-Agent": "CASSANDRA/1.0"})
        kw = {"timeout": 7}
        if ctx: kw["context"] = ctx
        with urllib.request.urlopen(req, **kw) as r:
            return json.loads(r.read())

    # Auth
    try:
        auth_url = (f"{scheme}://{host}:{port}/webapi/auth.cgi?"
                    f"api=SYNO.API.Auth&version=3&method=login"
                    f"&account={urllib.parse.quote(username)}"
                    f"&passwd={urllib.parse.quote(password)}"
                    f"&session=Cassandra&format=sid")
        req = urllib.request.Request(auth_url, headers={"User-Agent": "CASSANDRA/1.0"})
        kw = {"timeout": 8}
        if ctx: kw["context"] = ctx
        with urllib.request.urlopen(req, **kw) as r:
            auth_resp = json.loads(r.read())
        if not auth_resp.get("success"):
            err_code = auth_resp.get("error", {}).get("code", "?")
            return {"_error": f"Auth DSM échouée (code {err_code})", "_server": name}
        sid = auth_resp["data"]["sid"]
    except Exception as e:
        return {"_error": f"Connexion DSM: {type(e).__name__}", "_server": name}

    result = {"type": "synology", "_server": name, "online": True,
              "url": f"{scheme}://{host}:{port}"}

    # Info DSM
    try:
        info = _get("SYNO.DSM.Info", "2", "getinfo", sid=sid)
        if info.get("success"):
            d = info["data"]
            result["model"]       = d.get("model", "")
            result["dsm_version"] = d.get("version", "")
            result["hostname"]    = d.get("hostname", host)
    except Exception:
        pass

    # CPU / RAM
    try:
        util = _get("SYNO.Core.System.Utilization", "1", "get", sid=sid)
        if util.get("success"):
            d = util["data"]
            cpu_d = d.get("cpu", {})
            result["cpu"] = round(cpu_d.get("user_load", 0) + cpu_d.get("system_load", 0), 1)
            mem = d.get("memory", {})
            mem_total = mem.get("memory_size", 0)
            mem_avail = mem.get("avail_real", 0)
            result["ram"] = round((mem_total - mem_avail) / max(mem_total, 1) * 100, 1) if mem_total else 0
    except Exception:
        pass

    # Volumes disque
    try:
        vols = _get("SYNO.Storage.CGI.Storage", "1", "load", extra="&type=volume", sid=sid)
        if vols.get("success"):
            vlist = vols.get("data", {}).get("volumes", [])
            total_b = sum(v.get("size", {}).get("total", 0) for v in vlist)
            used_b  = sum(v.get("size", {}).get("used",  0) for v in vlist)
            result["disk"]          = round(used_b / max(total_b, 1) * 100, 1)
            result["disk_total_gb"] = round(total_b / 1073741824, 1)
            result["disk_used_gb"]  = round(used_b  / 1073741824, 1)
            result["volumes"]       = len(vlist)
    except Exception:
        pass

    # Logout (best-effort)
    try:
        _get("SYNO.API.Auth", "1", "logout", extra="&session=Cassandra", sid=sid)
    except Exception:
        pass

    return result


def _ms_fetch_ping(server: dict) -> dict:
    """Vérification TCP (ping applicatif) — pas de métriques, juste online/offline."""
    import socket as _sock
    host = server.get("ping_host", "")
    port = int(server.get("ping_port", 80))
    name = server.get("name", "")
    try:
        s = _sock.create_connection((host, port), timeout=3)
        s.close()
        return {"name": name, "type": "ping", "online": True,
                "url": f"{host}:{port}", "cpu": 0, "ram": 0, "disk": 0}
    except Exception as e:
        return {"name": name, "type": "ping", "online": False,
                "url": f"{host}:{port}", "_error": str(e)}


def _ms_fetch_proxmox(server: dict) -> dict:
    """Métriques Proxmox VE via REST API — auth user/pass → ticket PVE."""
    import ssl as _ssl
    url      = server.get("url", "").rstrip("/")
    username = server.get("px_user", "root@pam")
    password = _ms_decrypt_token(server.get("px_pass", ""))
    name     = server.get("name", "")
    ctx      = _ssl._create_unverified_context()
    try:
        auth_data = urllib.parse.urlencode(
            {"username": username, "password": password}).encode()
        req = urllib.request.Request(
            f"{url}/api2/json/access/ticket", data=auth_data,
            headers={"Content-Type": "application/x-www-form-urlencoded"})
        with urllib.request.urlopen(req, context=ctx, timeout=8) as r:
            auth = json.loads(r.read())
        ticket = auth["data"]["ticket"]
        csrf   = auth["data"]["CSRFPreventionToken"]
        hdrs   = {"Cookie": f"PVEAuthCookie={ticket}",
                  "CSRFPreventionToken": csrf}
        # Nodes
        req2 = urllib.request.Request(f"{url}/api2/json/nodes", headers=hdrs)
        with urllib.request.urlopen(req2, context=ctx, timeout=6) as r:
            nodes_d = json.loads(r.read())
        nodes = nodes_d.get("data", [])
        total_cpu = total_mem = 0
        for node in nodes:
            total_cpu += node.get("cpu", 0) * 100
            mem = node.get("mem", 0); maxmem = node.get("maxmem", 1)
            total_mem += mem / max(maxmem, 1) * 100
        count = max(len(nodes), 1)
        return {
            "name": name, "type": "proxmox", "online": True, "url": url,
            "cpu":   round(total_cpu / count, 1),
            "ram":   round(total_mem / count, 1),
            "disk":  0,
            "nodes": len(nodes),
        }
    except Exception as e:
        return {"name": name, "type": "proxmox", "online": False,
                "url": url, "_error": f"{type(e).__name__}: {e}"}


def _ms_ssh_exec(server: dict, cmd: str, timeout: int = 30) -> tuple:
    """Exécute cmd via SSH sur server. Retourne (stdout, stderr, exit_code).
    Priorité : paramiko → subprocess ssh+sshpass."""
    host     = server.get("ssh_host", "")
    port     = int(server.get("ssh_port", 22))
    user     = server.get("ssh_user", "root")
    auth     = server.get("ssh_auth", "password")
    password = _ms_decrypt_token(server.get("ssh_pass", ""))
    key_data = _ms_decrypt_token(server.get("ssh_key", ""))
    if auth == "tailscale":
        # Aucune identité : c'est le nœud Tailscale qui signe (sonde de la flotte). Jamais paramiko ici,
        # qui n'a pas ce mode et rendrait « no authentication methods available ».
        try:
            r = subprocess.run(["ssh"] + _FLOTTE_SONDE_SSH + ["-p", str(port), "%s@%s" % (user, host), cmd],
                               capture_output=True, text=True, timeout=timeout)
            return r.stdout, r.stderr, r.returncode
        except subprocess.TimeoutExpired:
            return "", "délai dépassé (%d s)" % timeout, 124

    # ── Méthode 1 : paramiko ────────────────────────────────────────────────
    try:
        import paramiko as _pk
        client = _pk.SSHClient()
        client.set_missing_host_key_policy(_pk.AutoAddPolicy())
        kw = {"hostname": host, "port": port, "username": user,
              "timeout": 12, "banner_timeout": 12, "auth_timeout": 12}
        if auth == "key" and key_data:
            import io as _io
            # Essayer RSA, Ed25519, ECDSA, DSS
            for KeyClass in [_pk.RSAKey, _pk.Ed25519Key, _pk.ECDSAKey]:
                try:
                    kw["pkey"] = KeyClass.from_private_key(_io.StringIO(key_data))
                    kw["look_for_keys"] = False
                    break
                except Exception:
                    continue
        elif password:
            kw["password"] = password
            kw["look_for_keys"] = False
        else:
            kw["look_for_keys"] = True  # ~/.ssh/id_rsa fallback
        client.connect(**kw)
        _, stdout, stderr = client.exec_command(cmd, timeout=timeout)
        out = stdout.read().decode(errors="replace")
        err = stderr.read().decode(errors="replace")
        rc  = stdout.channel.recv_exit_status()
        client.close()
        return out, err, rc
    except ImportError:
        pass  # pas de paramiko, on tente subprocess
    except Exception as e:
        return "", str(e), 1

    # ── Méthode 2 : subprocess ssh / sshpass ────────────────────────────────
    import subprocess as _sp, tempfile as _tf, os as _os
    ssh_base = [
        "ssh",
        "-o", "StrictHostKeyChecking=no",
        "-o", "UserKnownHostsFile=/dev/null",
        "-o", f"ConnectTimeout=12",
        "-o", "ServerAliveInterval=10",
        "-p", str(port),
    ]
    if auth == "key" and key_data:
        with _tf.NamedTemporaryFile(mode="w", suffix=".pem", delete=False) as kf:
            kf.write(key_data)
            kpath = kf.name
        _os.chmod(kpath, 0o600)
        try:
            r = _sp.run(ssh_base + ["-i", kpath, f"{user}@{host}", cmd],
                        capture_output=True, text=True, timeout=timeout)
        finally:
            try: _os.unlink(kpath)
            except Exception: pass
        return r.stdout, r.stderr, r.returncode
    # Auth password → sshpass si dispo
    if password:
        ssp = _sp.run(["which", "sshpass"], capture_output=True).stdout.strip()
        if ssp:
            r = _sp.run(
                [ssp.decode(), "-p", password] + ssh_base + [f"{user}@{host}", cmd],
                capture_output=True, text=True, timeout=timeout)
            return r.stdout, r.stderr, r.returncode
    # Dernière chance : ssh sans mot de passe (clé par défaut)
    r = _sp.run(ssh_base + ["-o", "BatchMode=yes", f"{user}@{host}", cmd],
                capture_output=True, text=True, timeout=timeout)
    return r.stdout, r.stderr, r.returncode


# LE SYSTÈME D'UNE MACHINE SSH (journal des agents n°130). Le formulaire d'ajout ne posait jamais `os` :
# une machine Windows recevait les commandes Linux du collecteur, cmd.exe répondait « chemin introuvable »,
# et la Flotte la disait HORS LIGNE alors qu'elle répondait. Le système se détecte une fois et se retient.
def _flotte_os_detecter(server: dict) -> str:
    """« linux », « windows », ou « » si la machine ne répond pas assez pour trancher."""
    try:
        out, err, rc = _ms_ssh_exec(server, "uname -s", timeout=15)
        o = (out or "").strip()
        if rc == 0 and o and not re.search(r"not recognized|n'est pas reconnu|introuvable", o + (err or ""), re.I):
            return "linux"
        out, err, rc = _ms_ssh_exec(server, "cmd /c ver", timeout=15)
        if "windows" in ((out or "") + (err or "")).lower():
            return "windows"
    except Exception as e:
        logging.info("[FLOTTE] système de %s : %s", server.get("name"), e)
    return ""


def _flotte_os_retenir(nom: str, systeme: str) -> None:
    servers = _ms_load()
    for s in servers:
        if s.get("name") == nom:
            s["os"] = systeme
    _ms_save(servers)


def _ms_fetch_ssh(server: dict) -> dict:
    """Métriques système via SSH (CPU, RAM, DISK, hostname, uptime)."""
    name = server.get("name", "")
    if "os" not in server and server.get("ssh_auth") != "tailscale":
        # Une fois : détecté puis retenu (« inconnu » si la machine ne répond pas, la sonde
        # `flotte` retentera). Sans ça, une machine Windows passait pour hors ligne.
        _sys = _flotte_os_detecter(server)
        server["os"] = _sys or "inconnu"
        try:
            _flotte_os_retenir(name, server["os"])
        except Exception as e:
            logging.info("[FLOTTE] système de %s non retenu : %s", name, e)
    is_windows = str(server.get("os", "")).lower() == "windows"
    if is_windows:
        cmd = "powershell -EncodedCommand "
    else:
        cmd = (
            r"printf 'CPU:%s\n' $(top -bn1 2>/dev/null | awk '/Cpu/{gsub(/[^0-9.]/,\" \"); t+=$1+$2+$3; n++} END{printf \"%.1f\",t/n}') 2>/dev/null || printf 'CPU:?\n'; "
            r"printf 'RAM:%s\n' $(free 2>/dev/null | awk '/Mem/{printf \"%.1f\",$3/$2*100}') || printf 'RAM:?\n'; "
            r"printf 'DISK:%s\n' $(df / 2>/dev/null | awk 'NR==2{gsub(/%/,\"\");print $5}') || printf 'DISK:?\n'; "
            r"printf 'HOST:%s\n' $(hostname 2>/dev/null); "
            r"printf 'KERN:%s\n' $(uname -r 2>/dev/null); "
            r"printf 'UP:%s\n' $(uptime -p 2>/dev/null | head -c60 || uptime | head -c60)"
        )
    try:
        # Windows : l'ancien appel direct `ssh -o BatchMode=yes` n'incluait pas
        # la clé (auth=key) et n'avait pas de repli — les serveurs Windows en clé
        # échouaient. On passe par le même _ms_ssh_exec que Linux, qui gère la clé,
        # le mot de passe, tailscale et le repli BatchMode.
        out, err, rc = _ms_ssh_exec(server, cmd, timeout=15)
        if rc != 0 and not out:
            return {"_error": (err or "SSH exec failed").strip()[:120], "_server": name}

        # PERF: Initialiser result une seule fois, éviter les get() redondants
        server_host = server.get("ssh_host", "")
        server_user = server.get("ssh_user", "root")
        server_port = server.get("ssh_port", 22)
        result = {"type": "ssh", "online": True, "cpu": 0, "ram": 0, "disk": 0,
                  "url": f"ssh://{server_user}@{server_host}:{server_port}"}

        # PERF: Dictionnaire de mapping clé -> (fonction, clé_resultat) pour éviter les if/elif répétés
        # Les fonctions de parsing sont créées une fois en dehors de la boucle
        def _parse_cpu(v):
            try: return round(float(v), 1)
            except: return None
        def _parse_ram(v):
            try: return round(float(v), 1)
            except: return None
        def _parse_disk(v):
            try: return round(float(v.rstrip('%')), 1)
            except: return None

        handlers = {
            'CPU':  ('cpu', _parse_cpu),
            'RAM':  ('ram', _parse_ram),
            'DISK': ('disk', _parse_disk),
            'HOST': ('hostname', lambda v: v),
            'KERN': ('kernel',   lambda v: v),
            'UP':   ('uptime',   lambda v: v[:60])
        }

        # PERF: Utiliser une boucle simple sans splitlines redondant ; strip une seule fois
        for line in out.splitlines():
            if ":" not in line:
                continue
            k, _, v = line.partition(":")
            v = v.strip().replace(",", ".")  # Windows locale peut utiliser virgule
            handler = handlers.get(k)
            if handler:
                key, func = handler
                parsed = func(v)
                if parsed is not None:
                    result[key] = parsed

        return result
    except Exception as e:
        return {"_error": f"{type(e).__name__}: {e}", "_server": name}


def ms_add_device(data: dict) -> dict:
    # PERF: Cache helpers once via attributes to avoid re‑definition on every call
    if not getattr(ms_add_device, "_init_done", None):
        from functools import lru_cache
        from threading import Lock

        _lock = Lock()

        @lru_cache(maxsize=512)
        def _enc(v: str) -> str:
            return _ms_encrypt_token(v) if v else ""

        @lru_cache(maxsize=128)
        def _int(v, d):
            try:
                return int(v)
            except (ValueError, TypeError):
                return d

        def _save(e: dict, n: str) -> dict:
            with _lock:
                s = _ms_load()
                s = [x for x in s if x.get("name") != n]
                s.append(e)
                _ms_save(s)
            return {"ok": True, "action": "added", "name": n, "type": e.get("type", "cassandra")}

        # PERF: Compact handler definitions – removed redundant comments
        def _c(b, c):
            u = c.get("url", "").rstrip("/")
            t = c.get("token", "")
            if not u or not t:
                return {"ok": False, "error": "URL et token requis"}
            return ms_add(b["name"], u, t)

        def _s(b, c):
            h, q = c.get("host", ""), c.get("qc_id", "")
            if not h and not q:
                return {"ok": False, "error": "IP/hostname ou QuickConnect ID requis"}
            u, p = c.get("username", ""), _enc(c.get("password", ""))
            ssl, port = bool(c.get("ssl", False)), _int(c.get("port", 5000), 5000)
            if not u or not c.get("password"):
                return {"ok": False, "error": "Identifiants Synology requis"}
            return {**b, "syn_host": h, "syn_port": port, "syn_qc": q, "syn_user": u, "syn_pass": p, "syn_ssl": ssl}

        def _p(b, c):
            u = c.get("url", "").rstrip("/")
            pw = c.get("password", "")
            if not u or not pw:
                return {"ok": False, "error": "URL et mot de passe requis"}
            # `url` restait vide et la lecture Proxmox ne lisait que `url` : jamais joignable (audit flotte 2026-09-05)
            return {**b, "url": u, "px_url": u, "px_user": c.get("username", "root@pam"), "px_pass": _enc(pw)}

        def _pi(b, c):
            h = c.get("host", "")
            if not h:
                return {"ok": False, "error": "Host requis"}
            p = _int(c.get("port", 80), 80)
            return {**b, "url": f"{h}:{p}", "ping_host": h, "ping_port": p}

        def _sh(b, c):
            h, user = c.get("host", ""), c.get("username", "root")
            if not h or not user:
                return {"ok": False, "error": "Host / IP et utilisateur requis"}
            auth = c.get("auth", "password")
            pw, key = c.get("password", ""), c.get("key", "")
            if (auth == "password" and not pw) or (auth == "key" and not key):
                return {"ok": False, "error": "Mot de passe ou clé SSH requis"}
            p = _int(c.get("port", 22), 22)
            d = {**b, "url": f"ssh://{user}@{h}:{p}", "ssh_host": h, "ssh_port": p, "ssh_user": user, "ssh_auth": auth, "ssh_pass": _enc(pw), "ssh_key": _enc(key)}
            # n°130 : le système, s'il est donné ; sinon le collecteur le détecte au premier passage.
            if str(c.get("os") or "").lower() in ("linux", "windows"):
                d["os"] = str(c.get("os")).lower()
            return d

        ms_add_device._handlers = {
            "cassandra": _c, "synology": _s, "proxmox": _p, "ping": _pi, "ssh": _sh
        }
        ms_add_device._save = _save
        ms_add_device._init_done = True

    # PERF: Local references to avoid repeated attribute lookups
    handlers = ms_add_device._handlers
    save = ms_add_device._save

    # PERF: Efficient dictionary comprehension for stripping
    cleaned = {k: v.strip() if isinstance(v, str) else v for k, v in data.items()}
    name = cleaned.get("name", "")
    if not name:
        return {"ok": False, "error": "Nom requis"}

    dtype = cleaned.get("type", "cassandra")
    base = {"name": name, "url": "", "token": "", "type": dtype, "enabled": True}
    handler = handlers.get(dtype)
    if not handler:
        return {"ok": False, "error": f"Type '{dtype}' non supporté"}

    res = handler(base, cleaned)
    if not res.get("ok", True):
        return res
    return save(res, name)


def ms_status_all() -> list:
    import concurrent.futures
    servers = [s for s in _ms_load() if s.get("enabled", True)]
    if not servers:
        return []

    def fetch_one(s):
        dtype = s.get("type", "cassandra")
        name  = s["name"]
        if dtype == "synology":
            r = _ms_fetch_synology(s)
            online = "_error" not in r
            return {
                "name": name, "type": "synology",
                "url": r.get("url", s.get("syn_host") or s.get("syn_qc", "")),
                "online": online, "error": r.get("_error"),
                "cpu": r.get("cpu", 0), "ram": r.get("ram", 0), "disk": r.get("disk", 0),
                "model": r.get("model", ""), "dsm_version": r.get("dsm_version", ""),
                "volumes": r.get("volumes", 0),
                "disk_total_gb": r.get("disk_total_gb", 0),
                "disk_used_gb":  r.get("disk_used_gb", 0),
            }
        if dtype == "ping":
            r = _ms_fetch_ping(s)
            return {
                "name": name, "type": "ping",
                "url": r.get("url", ""),
                "online": r.get("online", False),
                "error": r.get("_error"),
                "cpu": 0, "ram": 0, "disk": 0,
            }
        if dtype == "ssh":
            r = _ms_fetch_ssh(s)
            online = "_error" not in r
            return {
                "name": name, "type": "ssh",
                "url": r.get("url", f"ssh://{s.get('ssh_user','root')}@{s.get('ssh_host','')}"),
                "online": online,
                "error": r.get("_error"),
                "cpu":  r.get("cpu",  0), "ram": r.get("ram", 0), "disk": r.get("disk", 0),
                "hostname": r.get("hostname", ""), "kernel": r.get("kernel", ""),
                "uptime":   r.get("uptime", ""),
            }
        if dtype == "proxmox":
            r = _ms_fetch_proxmox(s)
            return {
                "name": name, "type": "proxmox",
                "url": s.get("url", ""),
                "online": r.get("online", False),
                "error": r.get("_error"),
                "cpu": r.get("cpu", 0), "ram": r.get("ram", 0), "disk": 0,
                "nodes": r.get("nodes", 0),
            }
        # cassandra (défaut)
        dash    = _ms_fetch(s, "/api/dashboard")
        metrics = _ms_fetch(s, "/api/metrics")
        online  = "_error" not in (dash or {})
        m = metrics if metrics and "_error" not in metrics else {}
        return {
            "name": name, "type": "cassandra",
            "url": s.get("url", ""),
            "online": online,
            "dashboard": dash if online else None,
            "metrics":   m or None,
            "error": dash.get("_error") if dash and "_error" in dash else None,
            "cpu":  m.get("cpu", 0),  "ram": m.get("ram", 0),  "disk": m.get("disk", 0),
            "health_score":  (dash or {}).get("health_score", 0),
            "health_status": (dash or {}).get("health_status", "unknown"),
        }

    # DÉLAI GLOBAL. Sans lui, une seule machine injoignable retenait tout le
    # monde : la page attendait 15 s, et comme cette fonction sert aussi à
    # l'outil `recall_environment` des agents, un NAS éteint ralentissait les
    # réponses de Cassandra et d'Itare. Passé le délai, la machine est déclarée
    # « délai dépassé » — un fait, pas une absence de réponse.
    results = []
    limite = max(5, int(_mem_cfg("fleet_deadline_s", 20)))
    fin = time.time() + limite
    # Pas de `with` : à la sortie du bloc il attend TOUS les fils, ce qui
    # annulerait le délai qu'on vient de poser. On ferme sans attendre.
    pool = concurrent.futures.ThreadPoolExecutor(max_workers=10)
    try:
        futures = {pool.submit(fetch_one, s): s for s in servers}
        try:
            # as_completed lève à l'expiration en perdant la suite : on prend
            # ce qui est arrivé à temps et on s'arrête là.
            for fut in concurrent.futures.as_completed(futures,
                                                       timeout=max(0.1, fin - time.time())):
                try:
                    results.append(fut.result(timeout=1))
                except Exception as e:
                    s = futures[fut]
                    results.append({
                        "name": s["name"], "url": s.get("url", ""),
                        "type": s.get("type", "cassandra"),
                        "online": False, "error": str(e),
                        "cpu": 0, "ram": 0, "disk": 0,
                    })
        except concurrent.futures.TimeoutError:
            pass
    finally:
        # Les fils encore en vol finiront seuls ; on ne les attend plus.
        pool.shutdown(wait=False, cancel_futures=True)
    rendus = {r["name"] for r in results}
    for s in servers:
        if s["name"] in rendus:
            continue
        results.append({
            "name": s["name"], "url": s.get("url", ""),
            "type": s.get("type", "cassandra"), "online": False,
            "timeout": True,
            "error": "délai dépassé (%d s) — machine injoignable ou très lente" % limite,
            "cpu": 0, "ram": 0, "disk": 0,
        })
        # Le fil continue en arrière-plan ; on ne l'attend plus, c'est tout.
        logging.info("[FLOTTE] %s n'a pas répondu en %d s", s["name"], limite)
    results.sort(key=lambda x: x["name"])
    return results


def ms_aggregate_metrics() -> dict:
    # PERF: Initialisation paresseuse encapsulée dans une sous-fonction pour clarté
    if not hasattr(ms_aggregate_metrics, "_state"):
        from functools import lru_cache
        import time

        @lru_cache(maxsize=128)
        def _fast_round(x: float, d: int) -> float:
            return round(x, d)

        @lru_cache(maxsize=128)
        def _fast_avg(sum_: float, count: int) -> float:
            return _fast_round(sum_ / count, 1) if count > 0 else 0.0

        def _get_cached_safe(key, fetch_fn, ttl, cache_ref):
            try:
                if cache_ref[key] is None or time.time() - cache_ref["time"] > ttl:
                    cache_ref[key] = fetch_fn()
                    cache_ref["time"] = time.time()
                return cache_ref[key]
            except Exception as e:
                cache_ref.setdefault("errors", {})[key] = str(e)
                return None

        ms_aggregate_metrics._state = {
            "cache": {"statuses": None, "metrics": None, "health": None, "time": 0, "errors": {}},
            "error_template": {
                "total_servers": 0, "online_servers": 0, "offline_servers": 0,
                "avg_cpu": 0.0, "avg_ram": 0.0, "avg_disk": 0.0, "avg_health": 0.0,
                "nodes": [], "error": ""
            }
        }
        ms_aggregate_metrics._utils = {
            "round": _fast_round,
            "avg": _fast_avg,
            "get_cached": _get_cached_safe
        }

    _state = ms_aggregate_metrics._state
    _cache = _state["cache"]
    _utils = ms_aggregate_metrics._utils

    # Récupération des données via cache avec gestion des erreurs
    statuses = _utils["get_cached"]("statuses", ms_status_all, 5, _cache)
    local_metrics = _utils["get_cached"]("metrics", get_metrics, 5, _cache) or {}
    local_health = _utils["get_cached"]("health", get_health_score, 5, _cache) or {}

    error_msgs = {}
    if statuses is None:
        error_msgs["statuses"] = _cache.get("errors", {}).get("statuses", "Unknown error")
    if not isinstance(statuses, (list, tuple)):
        res = _state["error_template"].copy()
        res["error"] = error_msgs.get("statuses", "Invalid statuses type")
        res["fetch_errors"] = error_msgs or None
        return res

    # PERF: variables locales pour éviter les accès répétés aux dictionnaires
    local_cpu = local_metrics.get("cpu", 0)
    local_ram = local_metrics.get("ram", 0)
    local_disk = local_metrics.get("disk", 0)
    local_h_score = local_health.get("score", 0)

    # Initialisation des accumulateurs avec le nœud local
    online_count = 1
    sums = {"cpu": local_cpu, "ram": local_ram, "disk": local_disk, "health": local_h_score}
    # Combien de machines ont réellement alimenté chaque moyenne.
    compteurs = {k: (1 if (sums[k] or 0) > 0 else 0) for k in sums}
    all_nodes = [{
        "name": "local", "online": True,
        "cpu": local_cpu, "ram": local_ram, "disk": local_disk,
        "health_score": local_h_score,
        "health_status": local_health.get("status", "unknown")
    }]

    OPTIONAL_KEYS = ("model", "dsm_version", "volumes", "disk_total_gb", "disk_used_gb", "nodes")

    # PERF: boucle unique sur les statuts, pas de O(n²) car le nombre de clés optionnelles est fixe
    for s in statuses:
        if not isinstance(s, dict):
            continue

        online = s.get("online", False)
        node = {
            "name": s.get("name", "unknown"),
            "online": online,
            "error": s.get("error"),
            "type": s.get("type", "cassandra"),
            "url": s.get("url", "")
        }

        # Ajout en une seule passe des clés optionnelles
        node.update({k: s[k] for k in OPTIONAL_KEYS if k in s})

        if online:
            cpu_val = s.get("cpu", 0)
            ram_val = s.get("ram", 0)
            disk_val = s.get("disk", 0)
            hscore = s.get("health_score", 0)
            node.update({
                "cpu": cpu_val, "ram": ram_val, "disk": disk_val,
                "health_score": hscore, "health_status": s.get("health_status", "unknown")
            })
            # On ne compte QUE les machines qui rapportent vraiment la mesure.
            # Une sonde ping n'a pas de processeur à déclarer, un NAS n'a pas de
            # score de santé : les inclure à zéro divisait la moyenne par deux.
            # Constaté : 13 % affichés là où les deux machines dotées d'un CPU
            # tournaient à 26 %, et une santé de 23/100 pour un unique nœud à 92.
            for cle, val in (("cpu", cpu_val), ("ram", ram_val),
                             ("disk", disk_val), ("health", hscore)):
                if val is None:
                    continue
                try:
                    v = float(val)
                except (TypeError, ValueError):
                    continue
                if v <= 0:
                    continue
                sums[cle] += v
                compteurs[cle] += 1
            online_count += 1

        all_nodes.append(node)

    total = len(all_nodes)

    return {
        "total_servers": total,
        "online_servers": online_count,
        "offline_servers": total - online_count,
        "avg_cpu": _utils["avg"](sums["cpu"], compteurs["cpu"]),
        "avg_ram": _utils["avg"](sums["ram"], compteurs["ram"]),
        "avg_disk": _utils["avg"](sums["disk"], compteurs["disk"]),
        "avg_health": _utils["avg"](sums["health"], compteurs["health"]),
        # Le dénominateur accompagne la moyenne : « 26 % sur 2 machines » se
        # relit, « 26 % » tout court laisse croire que la flotte entière est là.
        "avg_basis": dict(compteurs),
        "nodes": all_nodes,
        "fetch_errors": error_msgs or None
    }


# ══════════════════════════════════════════════════════════════════════════
# SITES — HISTORISATION, VEILLE, RATTACHEMENTS
# L'onglet « Mes sites » montrait l'instant présent et rien d'autre. Un site
# pouvait rendre 500 pendant trois jours sans que personne l'apprenne, et rien
# ne permettait de dire « ce site est tombé quatre fois ce mois-ci ».
# Les tables `web_sites` et `cms_sites` du collecteur sont des INSTANTANÉS —
# une ligne par domaine, écrasée : elles ne racontent aucune histoire.
# ══════════════════════════════════════════════════════════════════════════
_SITE_SEEN = [False]

# Un temps de réponse au-delà duquel le visiteur considère le site en panne,
# même s'il finit par répondre 200.
_SITE_LENT_MS = 3000
_CMS_DERNIER = [0.0]


def _site_migrate():
    if _SITE_SEEN[0]:
        return
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        conn.executescript("""
        CREATE TABLE IF NOT EXISTS site_status (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            ts TEXT DEFAULT (datetime('now')), domain TEXT,
            http_code INTEGER, response_ms INTEGER, up INTEGER,
            ssl_days INTEGER, backend TEXT, running INTEGER, error TEXT);
        CREATE INDEX IF NOT EXISTS idx_site_status_ts ON site_status(ts);
        CREATE INDEX IF NOT EXISTS idx_site_status_dom ON site_status(domain, ts);
        CREATE TABLE IF NOT EXISTS site_events (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            ts TEXT DEFAULT (datetime('now')), domain TEXT, kind TEXT,
            detail TEXT, duration_min INTEGER);
        CREATE INDEX IF NOT EXISTS idx_site_events_ts ON site_events(ts);
        CREATE TABLE IF NOT EXISTS site_state_seen (
            domain TEXT PRIMARY KEY, up INTEGER, since TEXT,
            ts TEXT DEFAULT (datetime('now')));
        CREATE TABLE IF NOT EXISTS site_links (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            domain TEXT, kind TEXT, ref TEXT, note TEXT,
            ts TEXT DEFAULT (datetime('now')),
            UNIQUE(domain, kind, ref));
        """)
        conn.commit(); conn.close()
        _SITE_SEEN[0] = True
    except Exception as e:
        logging.warning("[SITES] migration : %s", e)


def _site_probe(domain: str, timeout: float = 8.0) -> tuple:
    """Interroge le site et CHRONOMÈTRE. Retourne (code, ms, erreur).

    Le code seul ne suffit pas : un site qui répond 200 en huit secondes est
    en panne pour ses visiteurs. C'est la mesure qui manquait — l'onglet
    reprenait le `status_code` de FastPanel sans jamais mesurer la durée."""
    url = "https://%s/" % _norm_domain(domain)
    t0 = time.time()
    try:
        req = urllib.request.Request(url, method="GET",
                                     headers={"User-Agent": "Cassandra/site-check"})
        # On suit les redirections : c'est ce que fait un visiteur.
        with urllib.request.urlopen(req, timeout=timeout) as r:
            r.read(2048)
            return r.getcode(), int((time.time() - t0) * 1000), ""
    except urllib.error.HTTPError as e:
        # 404, 500… sont des RÉPONSES : le serveur est joignable.
        return e.code, int((time.time() - t0) * 1000), ""
    except Exception as e:
        return None, int((time.time() - t0) * 1000), str(e)[:200]


def site_pass() -> dict:
    """Enregistre l'état de chaque site et signale les changements."""
    if not _mem_cfg("site_watch_enabled", True):
        return {"ok": True, "disabled": True}
    _site_migrate()
    # TOUS les sites, pas ceux d'un utilisateur : `_user_sites_overview(None)`
    # filtrerait sur les domaines du compte « None » — c'est-à-dire aucun, et
    # la veille ne verrait jamais rien.
    brut, err = _sites_list_cached(force=True)
    if brut is None:
        logging.warning("[SITES] liste indisponible : %s", err)
        return {"ok": False, "reason": err or "indisponible"}
    sites = []
    for s in brut:
        jours = _cert_days(s.get("certificate") or {})
        be = s.get("main_backend") or {}
        sites.append({"domain": s.get("domain"), "ssl_days": jours,
                      "backend": be.get("handler"), "running": bool(be.get("is_running"))})
    # LES SITES DÉCLARÉS À LA MAIN (20-09) : ils n'existent pas dans le panneau, la veille ne les
    # voyait jamais. Ils rejoignent la passe avec le certificat lu sur le port 443.
    try:
        _connus = {_norm_domain(x.get("domain") or "") for x in sites}
        for _dn in _all_user_domains():
            if _dn and _dn not in _connus:
                sites.append({"domain": _dn, "ssl_days": _cert_sonde_jours(_dn),
                              "backend": None, "running": None, "hors_panneau": True})
    except Exception as _e:
        logging.info("[SITES] sites déclarés non ajoutés à la veille : %s", _e)
    if not sites:
        return {"ok": True, "sites": 0, "vide": True}

    maintenant = _utcnow().strftime("%Y-%m-%d %H:%M:%S")
    transitions, alertes, taches, mails = [], 0, 0, 0
    lents = []
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=15)
        connus = {r[0]: (r[1], r[2]) for r in
                  conn.execute("SELECT domain, up, since FROM site_state_seen")}
        for s in sites:
            dn = _norm_domain(s.get("domain") or "")
            if not dn:
                continue
            code, ms, err = _site_probe(dn)
            # La sonde fait foi : elle mesure ce que voit un visiteur, là où
            # FastPanel rapporte ce qu'il a constaté à son dernier passage.
            up = 1 if (code is not None and 200 <= int(code) < 400) else 0
            if up and ms >= _SITE_LENT_MS:
                lents.append({"domain": dn, "ms": ms})
            conn.execute(
                "INSERT INTO site_status (ts,domain,http_code,response_ms,up,ssl_days,"
                "backend,running,error) VALUES (?,?,?,?,?,?,?,?,?)",
                (maintenant, dn, code, ms, up, s.get("ssl_days"),
                 str(s.get("backend") or ""), 1 if s.get("running") else 0, err))
            avant = connus.get(dn)
            if avant is None:
                conn.execute("INSERT OR REPLACE INTO site_state_seen (domain,up,since,ts) "
                             "VALUES (?,?,?,?)", (dn, up, maintenant, maintenant))
                conn.execute("INSERT INTO site_events (ts,domain,kind,detail) VALUES (?,?,?,?)",
                             (maintenant, dn, "decouverte",
                              "Première observation — %s (HTTP %s, %d ms)"
                              % ("en ligne" if up else "hors ligne", code, ms)))
                continue
            if avant[0] == up:
                continue
            duree = _fleet_minutes(avant[1], maintenant)
            transitions.append({"domain": dn, "up": bool(up), "duration_min": duree,
                                "code": code, "error": err, "ms": ms})
            conn.execute("INSERT OR REPLACE INTO site_state_seen (domain,up,since,ts) "
                         "VALUES (?,?,?,?)", (dn, up, maintenant, maintenant))
            conn.execute(
                "INSERT INTO site_events (ts,domain,kind,detail,duration_min) VALUES (?,?,?,?,?)",
                (maintenant, dn, "retour" if up else "panne",
                 ("De nouveau en ligne après %s (HTTP %s, %d ms)."
                  % (_fleet_duree(duree), code, ms)) if up
                 else ("Injoignable — %s" % (err or ("HTTP %s" % code))),
                 duree))
        jours = max(7, int(_mem_cfg("site_retention_days", 90)))
        limite = (_utcnow() - timedelta(days=jours)).strftime("%Y-%m-%d %H:%M:%S")
        conn.execute("DELETE FROM site_status WHERE ts < ?", (limite,))
        conn.commit(); conn.close()
    except Exception as e:
        logging.warning("[SITES] enregistrement : %s", e)
        return {"ok": False, "reason": str(e)}

    # Une détection antivirus ne doit pas attendre qu'on ouvre un onglet. Ces
    # rapports existaient depuis toujours et n'alertaient personne.
    try:
        for r in get_fp_scans()[:20]:
            if r.get("status") == "ok":
                continue
            cle = "scan:%s@%s" % (r.get("domain"), r.get("created_at", "")[:16])
            if _cron_seen(cle):
                continue
            _itare_proactive_add(
                "Analyse antivirus positive : %s" % (r.get("domain") or "site inconnu"),
                "FastPanel a signalé un fichier suspect le %s.\nAction : %s\nRapport : %s"
                % (r.get("created_at") or "?", r.get("action") or "?",
                   r.get("report") or "—"),
                source="site", nature="etat", niveau="critique", sujet=str(r.get("domain") or ""),
                cle="site:infecte:%s" % (r.get("domain") or "?"))
            itare_task_from_source("auto-scan", cle,
                                   "Vérifier la détection antivirus sur %s"
                                   % (r.get("domain") or "?"))
            # Le mail direct a disparu : une critique part par la politique du centre (B14).
    except Exception as e:
        logging.info("[SCAN] alerte : %s", e)

    # Le CMS bouge rarement : une fois par heure suffit, et le scan ne coûte
    # que quelques accès disque sur des racines déjà connues.
    try:
        if time.time() - _CMS_DERNIER[0] > 3600:
            _CMS_DERNIER[0] = time.time()
            cms_scan()
    except Exception as e:
        logging.info("[CMS] scan : %s", e)

    for t in transitions:
        cle = "site:%s:%s@%s" % (t["domain"], "up" if t["up"] else "down", maintenant[:16])
        if _cron_seen(cle):
            continue
        if t["up"]:
            titre = "Site rétabli : %s" % t["domain"]
            corps = "Indisponible pendant %s. Répond en %d ms." % (_fleet_duree(t["duration_min"]), t["ms"])
        else:
            titre = "Site hors ligne : %s" % t["domain"]
            corps = "Ne répond plus depuis %s.\n%s" % (
                maintenant, t["error"] or ("Code HTTP %s." % t["code"]))
        try:
            if t["up"]:
                notif_resoudre_cle("site:%s" % t["domain"], par="rétabli",
                                   detail="le site répond de nouveau (%d ms)" % t["ms"])
                _itare_proactive_add(titre, corps, source="veille", nature="rapport")
            else:
                # L'admin ET les propriétaires du site (« compte:… ») sont les destinataires de la même
                # ligne : plus un mail à part qui visait le centre.
                _itare_proactive_add(titre, corps, source="site", nature="etat", niveau="critique",
                                     sujet=str(t["domain"]), cle="site:%s" % t["domain"],
                                     sonde="site:%s" % t["domain"],
                                     dest=["admins"] + ["compte:%s" % o for o in (_site_owners(t["domain"]) or [])])
            alertes += 1
        except Exception as e:
            logging.info("[SITES] fil proactif : %s", e)
        if t["up"]:
            continue
        try:
            pid = _site_lien_projet(t["domain"])
            qui = _site_lien_contacts(t["domain"])
            txt = "Remettre en ligne le site « %s »" % t["domain"]
            if qui:
                txt += " — prévenir %s" % ", ".join(qui[:2])
            r = itare_task_from_source("auto-site", cle, txt[:300], project_id=pid)
            if r.get("created"):
                taches += 1
        except Exception as e:
            logging.info("[SITES] création de tâche : %s", e)
        # Le propriétaire du site est prévenu par sa propre voie ; l'admin par
        # la voie générale. Un site qui tombe ne peut pas attendre un onglet.
        try:
            notify_site_owners(t["domain"], "down")
        except Exception as e:
            logging.info("[SITES] avis au propriétaire : %s", e)
        # Le mail direct « site hors ligne » a disparu : la ligne est critique, la politique du centre
        # décide du canal, personne par personne (B14).

    # Lenteur : ce n'est pas une panne, donc pas de transition — mais un site
    # qui met plus de trois secondes mérite d'être signalé une fois par jour.
    for l in lents:
        cle = "site-lent:%s@%s" % (l["domain"], maintenant[:10])
        if _cron_seen(cle):
            continue
        try:
            _itare_proactive_add(
                "Site lent : %s" % l["domain"],
                "Répond en %d ms (seuil %d ms). Le code HTTP est bon, mais pour un "
                "visiteur c'est déjà une panne." % (l["ms"], _SITE_LENT_MS),
                source="site", nature="evenement", niveau="info", sujet=str(l["domain"]),
                cle="site:lent:%s" % l["domain"], sonde="lent:%s" % l["domain"])
            alertes += 1
        except Exception as e:
            logging.info("[SITES] alerte lenteur : %s", e)

    return {"ok": True, "sites": len(sites), "transitions": len(transitions),
            "alerts": alertes, "tasks": taches, "mails": mails, "slow": len(lents),
            "down": [t["domain"] for t in transitions if not t["up"]]}


def site_history(domain: str, hours: int = 24) -> dict:
    """Historique d'un site : disponibilité, temps de réponse, événements."""
    _site_migrate()
    dn = _norm_domain(domain)
    h = max(1, min(int(hours or 24), 24 * 90))
    depuis = (_utcnow() - timedelta(hours=h)).strftime("%Y-%m-%d %H:%M:%S")
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        lignes = conn.execute(
            "SELECT ts, http_code, response_ms, up, ssl_days, error FROM site_status "
            "WHERE domain=? AND ts >= ? ORDER BY ts", (dn, depuis)).fetchall()
        events = conn.execute(
            "SELECT ts, kind, detail, duration_min FROM site_events "
            "WHERE domain=? AND ts >= ? ORDER BY ts DESC LIMIT 100", (dn, depuis)).fetchall()
        conn.close()
    except Exception as e:
        return {"ok": False, "reason": str(e)}
    total = len(lignes)
    up = sum(1 for l in lignes if l[3])
    tps = [l[2] for l in lignes if l[2] is not None and l[3]]
    return {"ok": True, "domain": dn, "hours": h, "samples": total,
            "availability": round(100.0 * up / total, 2) if total else None,
            "response_avg_ms": int(sum(tps) / len(tps)) if tps else None,
            "response_max_ms": max(tps) if tps else None,
            "points": [{"ts": l[0], "code": l[1], "ms": l[2], "up": bool(l[3]),
                        "ssl_days": l[4], "error": l[5]} for l in lignes],
            "events": [{"ts": e[0], "kind": e[1], "detail": e[2], "duration_min": e[3]}
                       for e in events],
            "cms": site_cms(dn).get("cms"),
            "ssl_quota": ssl_quota_state(dn),
            "links": site_links_list(dn).get("links", [])}


def site_availability(days: int = 30) -> dict:
    """Disponibilité et temps de réponse par site."""
    _site_migrate()
    d = max(1, min(int(days or 30), 365))
    depuis = (_utcnow() - timedelta(days=d)).strftime("%Y-%m-%d %H:%M:%S")
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        rows = conn.execute(
            "SELECT domain, COUNT(*), SUM(up), AVG(CASE WHEN up=1 THEN response_ms END), "
            "MAX(CASE WHEN up=1 THEN response_ms END), MAX(ts) FROM site_status WHERE ts >= ? "
            "GROUP BY domain ORDER BY domain", (depuis,)).fetchall()
        pannes = {r[0]: (r[1], r[2]) for r in conn.execute(
            "SELECT domain, COUNT(*), COALESCE(SUM(duration_min),0) FROM site_events "
            "WHERE kind='retour' AND ts >= ? GROUP BY domain", (depuis,))}
        conn.close()
    except Exception as e:
        return {"ok": False, "reason": str(e)}
    out, plus_suivis = [], []
    # Un site plus relevé depuis deux jours n'est plus suivi (supprimé, déménagé) : son 0 % ne le met pas en tête.
    suivi_depuis = (_utcnow() - timedelta(days=2)).strftime("%Y-%m-%d %H:%M:%S")
    for dom, total, up, moy, mx, dernier in rows:
        if _ts_norm(dernier) < suivi_depuis:
            plus_suivis.append(dom)
            continue
        n, minutes = pannes.get(dom, (0, 0))
        out.append({"domain": dom, "samples": total,
                    "availability": round(100.0 * (up or 0) / total, 2) if total else None,
                    "response_avg_ms": int(moy) if moy is not None else None,
                    "response_max_ms": int(mx) if mx is not None else None,
                    "outages": n, "downtime_min": minutes, "downtime": _fleet_duree(minutes)})
    return {"ok": True, "days": d, "sites": out, "plus_suivis": plus_suivis,
            "reason": "" if out else "Aucune mesure enregistrée — la passe n'a pas encore tourné."}


# ── Détection de CMS ───────────────────────────────────────────────────────
# `CMS_DETECTORS` existait dans le collecteur depuis toujours… et n'était
# utilisé nulle part. La table `cms_sites` était créée puis laissée vide : la
# fiche annonçait « Aucun CMS détecté » pour un WordPress évident. Ce n'était
# pas une détection en échec, c'était une détection jamais écrite.
# L'ordre compte : Python parcourt le dictionnaire dans l'ordre d'insertion, et
# les signatures PRÉCISES doivent passer avant les génériques — sinon BookStack
# serait annoncé comme « Laravel », ce qui est vrai et inutile.
_CMS_SIGNATURES = {
    "WordPress":  ["wp-config.php", "wp-includes", "wp-content"],
    "Joomla":     ["configuration.php", "administrator/manifests"],
    "Drupal":     ["core/lib/Drupal.php", "sites/default/settings.php"],
    "PrestaShop": ["config/settings.inc.php", "classes/PrestaShopAutoload.php"],
    "Magento":    ["app/etc/env.php", "bin/magento"],
    "Typo3":      ["typo3conf", "typo3_src"],
    "Ghost":      ["content/themes", "current/index.js"],
    # `app/Entities` a changé de forme entre les versions (Book.php a été
    # déplacé dans Models/) : on vise le répertoire, pas le fichier.
    "BookStack":  ["app/Entities", "public/index.php", "version"],
    "Nextcloud":  ["occ", "lib/versioncheck.php", "config/config.php"],
    "Matomo":     ["core/Version.php", "matomo.php"],
    "MediaWiki":  ["includes/Defines.php", "LocalSettings.php"],
    "GLPI":       ["inc/define.php", "front/central.php"],
    "Grav":       ["system/defines.php", "user/config"],
    "Dolibarr":   ["htdocs/main.inc.php", "htdocs/core/lib/functions.lib.php"],
    "Laravel":    ["artisan", "app/Http/Kernel.php", "public/index.php"],
    "Symfony":    ["bin/console", "config/bundles.php", "public/index.php"],
}

_CMS_VERSION_LECTEURS = {
    # (fichier, motif) — la version se lit dans le code, pas dans la page :
    # beaucoup de sites masquent le générateur pour ne pas s'exposer.
    "WordPress":  ("wp-includes/version.php", r"\$wp_version\s*=\s*'([^']+)'"),
    "Joomla":     ("libraries/src/Version.php", r"MAJOR_VERSION\s*=\s*(\d+)"),
    "Drupal":     ("core/lib/Drupal.php", r"const VERSION\s*=\s*'([^']+)'"),
    "PrestaShop": ("config/settings.inc.php", r"_PS_VERSION_',\s*'([^']+)'"),
    # BookStack écrit sa version dans un fichier `version` à la racine (« v23.10.2 »).
    "BookStack":  ("version", r"^\s*v?([0-9][0-9A-Za-z.\-]*)"),
    "Nextcloud":  ("version.php", r"\$OC_VersionString\s*=\s*'([^']+)'"),
    "Matomo":     ("core/Version.php", r"VERSION\s*=\s*'([^']+)'"),
    "MediaWiki":  ("includes/Defines.php", r"MW_VERSION',\s*'([^']+)'"),
    "GLPI":       ("inc/define.php", r"GLPI_VERSION',\s*'([^']+)'"),
    "Grav":       ("system/defines.php", r"GRAV_VERSION',\s*'([^']+)'"),
}

# Répertoires qui SONT une racine web d'application : quand la racine déclarée
# porte un de ces noms, l'application vit un cran AU-DESSUS. C'est le cas de
# BookStack, Laravel et Symfony — leurs marqueurs sont dans le parent, et une
# recherche qui ne fait que descendre ne les trouve jamais.
_RACINES_WEB = ("public", "public_html", "html", "web", "httpdocs", "www", "htdocs")


# ── Applications sans racine sur le disque ─────────────────────────────────
# Vaultwarden est un binaire Rust derrière un reverse_proxy : son `index_dir`
# est un répertoire vide, et AUCUNE signature de fichier ne le trouvera jamais.
# Même chose pour Gitea, Grafana ou Jellyfin. Ces applications se nomment
# elles-mêmes sur HTTP — c'est là qu'il faut le leur demander.
#
# `signe` : ce qui doit apparaître dans la réponse pour valider l'identité.
# Sans lui, un point d'API qui renvoie `{"version": …}` ferait passer n'importe
# quoi pour l'application attendue.
_SONDES_HTTP = (
    {"nom": "Vaultwarden", "chemin": "/api/config",
     "signe": ("vaultwarden",), "version": ("version",)},
    {"nom": "Bitwarden", "chemin": "/api/config",
     "signe": ("bitwarden",), "version": ("version",)},
    {"nom": "Nextcloud", "chemin": "/status.php",
     "signe": ("nextcloud",), "version": ("versionstring", "version")},
    {"nom": "Gitea", "chemin": "/api/v1/version",
     "signe": (), "version": ("version",), "confirme": ("gitea",)},
    {"nom": "Forgejo", "chemin": "/api/v1/version",
     "signe": (), "version": ("version",), "confirme": ("forgejo",)},
    {"nom": "Grafana", "chemin": "/api/health",
     "signe": ("database",), "version": ("version",), "confirme": ("grafana",)},
    {"nom": "Jellyfin", "chemin": "/System/Info/Public",
     "signe": ("jellyfin", "servername"), "version": ("Version", "version")},
    # Cassandra sert sa propre page : le bandeau et la classe `logo-badge` ne
    # se trouvent nulle part ailleurs. Dernier filet si ni le vhost ni la
    # configuration ne l'ont désignée.
    {"nom": "Cassandra", "chemin": "/",
     "signe": ('class="logo">cassandra', "logo-badge"), "version": ()},
    {"nom": "Uptime Kuma", "chemin": "/", "signe": ("uptime kuma",), "version": ()},
    {"nom": "Portainer", "chemin": "/api/status",
     "signe": ("version",), "version": ("Version", "version"), "confirme": ("portainer",)},
)

_GENERATEUR_RE = re.compile(
    r"<meta[^>]+name\s*=\s*[\"']generator[\"'][^>]*content\s*=\s*[\"']([^\"']+)[\"']", re.I)
_TITRE_RE = re.compile(r"<title[^>]*>([^<]{1,120})</title>", re.I)


def _http_get(url: str, timeout: float = 8.0) -> str:
    try:
        req = urllib.request.Request(url, headers={"User-Agent": "Cassandra/app-detect",
                                                   "Accept": "application/json, text/html"})
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return r.read(120000).decode("utf-8", "replace")
    except Exception:
        return ""


def _sonde_version(texte: str, cles) -> str:
    try:
        d = json.loads(texte)
    except Exception:
        return ""
    piles = [d]
    while piles:
        cur = piles.pop()
        if isinstance(cur, dict):
            for k in cles:
                v = cur.get(k)
                if isinstance(v, (str, int, float)) and str(v).strip():
                    return str(v).strip()[:40]
            piles.extend(v for v in cur.values() if isinstance(v, (dict, list)))
        elif isinstance(cur, list):
            piles.extend(v for v in cur if isinstance(v, (dict, list)))
    return ""


# ── Remonter du site à ce qui l'exécute (08-10) ─────────────────────────────────────
# Les sondes HTTP ne connaissent qu'une douzaine d'applications, et un site protégé par le portier de
# Cassandra se présente… comme Cassandra (auth.cassandra.center). La vérité est dans la configuration :
# le vhost renvoie vers un port local, directement ou par un « upstream » (FastPanel nomme les siens
# d'après le domaine : `proxy_pass http://auth.cassandra.center6;`), et ce port est publié par un
# conteneur — dont l'IMAGE dit le nom et la version — ou ouvert par un processus.
_NGINX_DOSSIERS = ("/etc/nginx/fastpanel2-sites", "/etc/nginx/sites-enabled", "/etc/nginx/conf.d", "/etc/nginx/vhosts.d")
_IMAGES_NOMS = {"goauthentik": "Authentik", "authentik": "Authentik", "vaultwarden": "Vaultwarden", "searxng": "SearXNG",
                "gitea": "Gitea", "forgejo": "Forgejo", "nextcloud": "Nextcloud", "grafana": "Grafana", "portainer": "Portainer",
                "jellyfin": "Jellyfin", "immich": "Immich", "n8n": "n8n", "open-webui": "Open WebUI", "uptime-kuma": "Uptime Kuma",
                "homeassistant": "Home Assistant", "home-assistant": "Home Assistant", "paperless-ngx": "Paperless-ngx",
                "keycloak": "Keycloak", "gitlab": "GitLab", "mattermost": "Mattermost", "minio": "MinIO", "plex": "Plex",
                "bookstack": "BookStack", "wikijs": "Wiki.js", "outline": "Outline", "syncthing": "Syncthing",
                "adguardhome": "AdGuard Home", "pihole": "Pi-hole", "traefik": "Traefik", "metabase": "Metabase",
                "mealie": "Mealie", "vikunja": "Vikunja", "odoo": "Odoo", "wordpress": "WordPress", "ghost": "Ghost",
                "matomo": "Matomo", "kimai": "Kimai", "freshrss": "FreshRSS", "linkwarden": "Linkwarden", "ollama": "Ollama"}
_IMAGES_GENERIQUES = ("server", "app", "web", "api", "core", "backend", "frontend", "latest", "main")
_PROCESSUS_GENERIQUES = ("python", "python3", "node", "java", "php", "php-fpm", "ruby", "dotnet", "docker-proxy", "uwsgi",
                         "gunicorn", "deno", "bun", "beam.smp")
# Un serveur web derrière un proxy n'est pas l'APPLICATION : on ne s'arrête pas à lui (le disque ou la sonde HTTP la diront).
_SERVEURS_WEB = ("apache2", "httpd", "nginx", "caddy", "lighttpd", "openresty")


def _nom_application(brut: str) -> str:
    b = (brut or "").strip().lower()
    if b in _IMAGES_NOMS:
        return _IMAGES_NOMS[b]
    return b[:1].upper() + b[1:] if b else ""


def _image_vers_application(image: str):
    """« ghcr.io/goauthentik/server:2026.8.3 » → ("Authentik", "2026.8.3")."""
    nom, _, tag = (image or "").partition(":")
    morceaux = [m for m in nom.split("/") if m and "." not in m]           # sans le registre
    if not morceaux:
        return "", ""
    for m in reversed(morceaux):
        if m.lower() in _IMAGES_NOMS:
            return _IMAGES_NOMS[m.lower()], ("" if tag in ("", "latest", "stable", "main") else tag)
    dernier = morceaux[-1]
    if dernier.lower() in _IMAGES_GENERIQUES and len(morceaux) > 1:
        dernier = morceaux[-2]
    return _nom_application(dernier), ("" if tag in ("", "latest", "stable", "main") else tag)


def _vhost_textes(domain: str) -> list:
    """Le texte des fichiers nginx qui servent ce domaine (et ce qu'ils incluent à côté)."""
    out = []
    for d in _NGINX_DOSSIERS:
        base = Path(d)
        if not base.is_dir():
            continue
        for f in base.rglob("*"):
            try:
                if not f.is_file() or f.suffix in (".bak", ".bak2") or ".avant" in f.name or f.stat().st_size > 512 * 1024:
                    continue
                if f.name.startswith(domain + ".") or re.search(r"server_name[^;]*\b%s\b" % re.escape(domain), f.read_text(errors="replace")):
                    out.append(f.read_text(errors="replace"))
            except Exception:
                continue
    return out


def _ports_du_vhost(domain: str) -> list:
    textes = _vhost_textes(domain)
    tout = "\n".join(textes)
    ports = []
    for cible in re.findall(r"proxy_pass\s+https?://([^/;\s]+)", tout):
        m = re.match(r"^(?:127\.0\.0\.1|localhost|0\.0\.0\.0|\[::1\]|[\d.]+):(\d+)$", cible)
        if m:
            ports.append(int(m.group(1)))
            continue
        bloc = re.search(r"upstream\s+%s\s*\{([^}]*)\}" % re.escape(cible), tout)
        if bloc:
            ports += [int(x) for x in re.findall(r"server\s+[^;:\s]+:(\d+)", bloc.group(1))]
    # Le premier proxy_pass du vhost est l'application ; les suivants (« /outpost… », avant-postes) viennent après.
    vus, ordre = set(), []
    for p_ in ports:
        if p_ not in vus:
            vus.add(p_)
            ordre.append(p_)
    return ordre


def _cms_par_proxy(domain: str) -> dict:
    dn = _norm_domain(domain)
    if not dn:
        return {}
    try:
        ports = _ports_du_vhost(dn)
    except Exception:
        ports = []
    if not ports:
        return {}
    import shutil as _sh
    moteur = "docker" if _sh.which("docker") else ("podman" if _sh.which("podman") else "")
    conteneurs = []
    if moteur:
        try:
            sortie = subprocess.run([moteur, "ps", "--format", "{{.Image}}|{{.Ports}}"], capture_output=True, text=True, timeout=10).stdout
            conteneurs = [l.split("|", 1) for l in sortie.splitlines() if "|" in l]
        except Exception:
            conteneurs = []
    try:
        ss = subprocess.run(["ss", "-ltnpH"], capture_output=True, text=True, timeout=10).stdout
    except Exception:
        ss = ""
    for port in ports:
        for image, publies in conteneurs:
            if re.search(r"(?:^|[\s,])(?:[\d.]+|\[?::\]?):%d->" % port, publies):
                nom, version = _image_vers_application(image)
                if nom:
                    return {"type": nom, "version": version, "theme": "", "plugins": 0,
                            "path": "conteneur %s (port %d)" % (image, port)}
        for l in ss.splitlines():
            if re.search(r":%d\s" % port, l):
                m = re.search(r'users:\(\("([^"]+)"', l)
                proc = (m.group(1) if m else "").split(" (")[0].strip()
                if proc.lower() in _SERVEURS_WEB:
                    continue
                if not proc or proc.lower() in _PROCESSUS_GENERIQUES:
                    # « python », « node » ne disent pas quelle application : le titre de sa page, si elle en a un
                    titre = ""
                    try:
                        page = _http_get("http://127.0.0.1:%d/" % port, timeout=4)
                        mt = _TITRE_RE.search(page or "")
                        titre = re.split(r"\s+[—|·:-]\s+", mt.group(1).strip())[0] if mt else ""
                    except Exception:
                        titre = ""
                    if titre:
                        return {"type": titre[:40], "version": "", "theme": "", "plugins": 0,
                                "path": "processus %s (port %d, titre de la page)" % (proc or "?", port)}
                    continue
                nom = _nom_application(proc)
                try:      # la casse que l'application se donne (« OmniRoute ») si son titre la contient
                    mt = _TITRE_RE.search(_http_get("http://127.0.0.1:%d/" % port, timeout=4) or "")
                    mt2 = re.search(re.escape(proc), mt.group(1), re.I) if mt else None
                    if mt2:
                        nom = mt2.group(0)
                except Exception:
                    pass
                return {"type": nom, "version": "", "theme": "", "plugins": 0,
                        "path": "processus %s (port %d)" % (proc, port)}
    return {}


def _cms_sonde_http(domain: str) -> dict:
    """Interroge le site pour qu'il se nomme lui-même.

    Complément au disque, pas remplacement : on n'appelle ceci que si aucune
    signature de fichier n'a répondu. Uniquement le domaine du site, en GET,
    avec un délai court — jamais de service tiers."""
    dn = _norm_domain(domain)
    if not dn:
        return {}
    base = "https://%s" % dn
    _cache = {}

    def _page(chemin):
        if chemin not in _cache:
            _cache[chemin] = _http_get(base + chemin)
        return _cache[chemin]

    for s in _SONDES_HTTP:
        corps = _page(s["chemin"])
        if not corps:
            continue
        bas = corps.lower()
        if s["signe"] and not any(x in bas for x in s["signe"]):
            continue
        # `confirme` se cherche sur la PAGE D'ACCUEIL, pas dans la réponse de
        # l'API : Gitea et Forgejo partagent `/api/v1/version`, qui renvoie
        # `{"version": …}` sans jamais se nommer. L'identité est sur la page.
        if s.get("confirme"):
            acc = _page("/").lower()
            if not any(x in acc for x in s["confirme"]):
                continue
        v = _sonde_version(corps, s["version"]) if s["version"] else ""
        if s["nom"] == "Cassandra" and not v:
            v = CASSANDRA_VERSION.lstrip("v")
        return {"type": s["nom"], "version": v, "theme": "", "plugins": 0,
                "path": base + s["chemin"]}
    # Dernier recours : la balise `generator`, que beaucoup de CMS laissent.
    accueil = _page("/")
    if accueil:
        m = _GENERATEUR_RE.search(accueil)
        if m:
            gen = m.group(1).strip()[:60]
            mv = re.search(r"([0-9]+(?:\.[0-9]+)+)", gen)
            return {"type": gen.split()[0][:30] if gen else "", "version": mv.group(1) if mv else "",
                    "theme": "", "plugins": 0, "path": base + "/ (balise generator)"}
    return {}


_SERVER_NAME_RE = re.compile(r"^\s*server_name\s+([^;]+);", re.M)
_DOMAINES_SOI = {"v": None, "t": 0.0}


def _domaines_cassandra() -> set:
    """Domaines servis par Cassandra elle-même.

    TROIS sources, parce qu'aucune ne suffit seule — la première a échoué en
    production sans rien dire :
    1. les vhosts nginx qui proxifient vers NOTRE port (certain, mais suppose
       une arborescence nginx lisible et un `server_name` explicite) ;
    2. l'adresse publique déclarée en configuration ;
    3. l'adresse du panneau, quand elle est renseignée.
    Aucune n'émet de requête réseau."""
    if _DOMAINES_SOI["v"] is not None and time.time() - _DOMAINES_SOI["t"] < 300:
        return _DOMAINES_SOI["v"]
    noms, sources = set(), []
    try:
        for chemin in _ws_vhosts():
            with open(chemin, "r", errors="replace") as fh:
                txt = fh.read()
            for m in _SERVER_NAME_RE.finditer(txt):
                for n in m.group(1).split():
                    n = _norm_domain(n.strip())
                    if n and n not in ("_", "localhost") and "*" not in n:
                        noms.add(n)
                        sources.append("vhost:%s" % n)
    except Exception as e:
        logging.debug("[SOI] vhosts : %s", e)
    for cle, val in (("app_public_url", _app_public_url()),
                     ("hostname", socket.getfqdn() if hasattr(socket, "getfqdn") else "")):
        try:
            n = str(val or "").replace("https://", "").replace("http://", "")
            n = _norm_domain(n.split("/")[0].split(":")[0]).strip("/")
            if n and "." in n and n != "localhost":
                noms.add(n)
                sources.append("%s:%s" % (cle, n))
        except Exception as e:
            logging.debug("[SOI] %s : %s", cle, e)
    logging.info("[SOI] domaines propres : %s", ", ".join(sources) or "aucun")
    _DOMAINES_SOI.update({"v": noms, "t": time.time()})
    return noms


def _utilisateur_courant() -> str:
    try:
        import pwd
        return "%s" % pwd.getpwuid(os.geteuid()).pw_name
    except Exception:
        return "uid %s" % getattr(os, "geteuid", lambda: "?")()


def _cms_lire(chemin: str, motif: str, taille: int = 20000) -> str:
    try:
        with open(chemin, "r", errors="replace") as f:
            m = re.search(motif, f.read(taille))
        return m.group(1) if m else ""
    except Exception:
        return ""


def _cms_detecter(racine: str) -> dict:
    """Cherche un CMS à la racine, puis AU-DESSUS, puis en dessous.

    Trois dispositions existent en vrai :
    · l'application est à la racine déclarée (WordPress) ;
    · la racine déclarée est le `public/` d'une application dont les fichiers
      d'identification sont dans le PARENT (BookStack, Laravel, Symfony) ;
    · l'application est dans un sous-répertoire (`public_html`, `htdocs`).
    Ne regarder qu'en bas faisait manquer toute la deuxième famille."""
    r = _cms_detecter_racine(racine)
    if r:
        return r
    # Vers le haut, et SEULEMENT si le nom de la racine est celui d'une racine
    # web : sinon on remonterait dans le répertoire commun à tous les sites.
    if os.path.basename(racine.rstrip("/\\")).lower() in _RACINES_WEB:
        parent = os.path.dirname(racine.rstrip("/\\"))
        if parent and parent not in ("/", ""):
            r = _cms_detecter_racine(parent)
            if r and not r.get("_probleme"):
                return r
    try:
        sous = sorted(e for e in os.listdir(racine)
                      if os.path.isdir(os.path.join(racine, e)) and not e.startswith("."))[:12]
    except Exception:
        return {}
    for e in sous:
        r = _cms_detecter_racine(os.path.join(racine, e))
        if r and not r.get("_probleme"):
            return r
    return {}


def _cms_detecter_racine(racine: str) -> dict:
    """Identifie le CMS installé dans un répertoire, avec sa version.

    Rend un `{"_probleme": …}` quand le répertoire est introuvable ou illisible.
    Confondre « pas de CMS » avec « je n'ai pas pu regarder » a fait afficher
    « Aucun CMS détecté » sur un WordPress parfaitement installé, et chercher un
    défaut de détection là où il n'y en avait pas."""
    if not racine:
        return {}
    if not os.path.isdir(racine):
        return {"_probleme": "racine introuvable : %s" % racine, "path": racine}
    if not os.access(racine, os.R_OK | os.X_OK):
        return {"_probleme": "racine illisible par le service (%s) : %s"
                             % (_utilisateur_courant(), racine), "path": racine}
    for nom, marqueurs in _CMS_SIGNATURES.items():
        # Tous les marqueurs doivent être là : `administrator` seul se trouve
        # dans trop de projets pour valoir identification.
        if not all(os.path.exists(os.path.join(racine, m)) for m in marqueurs):
            continue
        info = {"type": nom, "version": "", "theme": "", "plugins": 0, "path": racine}
        lect = _CMS_VERSION_LECTEURS.get(nom)
        if lect:
            info["version"] = _cms_lire(os.path.join(racine, lect[0]), lect[1])
        if nom == "WordPress":
            try:
                ext = os.path.join(racine, "wp-content", "plugins")
                if os.path.isdir(ext):
                    info["plugins"] = sum(1 for e in os.listdir(ext)
                                          if os.path.isdir(os.path.join(ext, e)))
                # Le thème ACTIF est en base ; sans elle, on cite le plus récent.
                th = os.path.join(racine, "wp-content", "themes")
                if os.path.isdir(th):
                    noms = [e for e in os.listdir(th) if os.path.isdir(os.path.join(th, e))]
                    if noms:
                        info["theme"] = max(
                            noms, key=lambda e: os.path.getmtime(os.path.join(th, e)))
            except Exception as e:
                logging.debug("[CMS] %s : %s", racine, e)
        return info
    return {}


def cms_scan(force: bool = False, http: bool = True) -> dict:
    """Parcourt la racine de chaque site et remplit `cms_sites`.

    On part des racines déclarées par FastPanel plutôt que de balayer le
    disque : c'est exact, et ça ne coûte que quelques `os.path.exists`. Quand
    le disque ne dit rien — cas des applications en conteneur derrière un
    reverse_proxy — on interroge le site en HTTP."""
    brut, err = _sites_list_cached(force)
    if brut is None:
        return {"ok": False, "reason": err or "liste des sites indisponible", "found": 0}
    trouves, scannes, connus, problemes, inspectes = [], [], [], [], []
    soi = _domaines_cassandra()
    for s in brut:
        dom = _norm_domain(s.get("domain") or "")
        if not dom:
            continue
        connus.append(dom)
        # Cassandra se reconnaît elle-même. Elle n'est évidemment pas un CMS
        # déclaré, mais laisser son propre domaine en « contenu inconnu » sur
        # sa propre page serait la seule case vide du tableau.
        if dom in soi:
            scannes.append(dom)
            trouves.append({"domain": dom, "type": "Cassandra",
                            "version": CASSANDRA_VERSION.lstrip("v"),
                            "theme": "", "plugins": 0,
                            "path": "cette application (port %d)" % PORT})
            continue
        racine = s.get("index_dir") or s.get("document_root") or ""
        if not racine:
            problemes.append("%s : aucune racine déclarée" % dom)
            continue
        scannes.append(dom)
        info = _cms_detecter(racine)
        if info.get("_probleme"):
            problemes.append("%s : %s" % (dom, info["_probleme"]))
            # Racine illisible : on ne SAIT pas s'il y a un CMS. Retirer la
            # ligne existante reviendrait à effacer un fait sur un doute.
            scannes.remove(dom)
            continue
        if not info and http:
            # Rien sur le disque : l'application tourne peut-être en conteneur
            # derrière un reverse_proxy, auquel cas la racine déclarée est un
            # répertoire vide. On lui demande alors de se nommer elle-même.
            info = _cms_sonde_http(dom)
        if not info or not info.get("version"):
            # 08-10 : CE QUI ÉCOUTE DERRIÈRE. Le site est un reverse_proxy : on suit son proxy_pass jusqu'au port,
            # et le port jusqu'au conteneur (son image) ou au processus. Local, sans réseau. Il nomme ce que les
            # sondes HTTP ne connaissent pas (Authentik, OmniRoute…), et complète la version quand elles l'ignorent.
            par_proxy = _cms_par_proxy(dom)
            if par_proxy and not info:
                info = par_proxy
            elif par_proxy and info and par_proxy["type"].lower() == str(info.get("type", "")).lower() and par_proxy.get("version"):
                info["version"] = par_proxy["version"]
        if info:
            info["domain"] = dom
            trouves.append(info)
        else:
            # Le chemin examiné DOIT figurer dans le compte rendu : sans lui,
            # « aucun CMS » ne permet pas de savoir si on a cherché au bon
            # endroit, et le diagnostic tourne en rond.
            inspectes.append("%s → %s%s" % (dom, racine,
                                            " (et interrogation HTTP)" if http else ""))
    vus = len(scannes)
    try:
        conn = sqlite3.connect(DB_PATH, timeout=15)
        conn.execute("CREATE TABLE IF NOT EXISTS cms_sites (id INTEGER PRIMARY KEY AUTOINCREMENT, "
                     "domain TEXT, path TEXT, cms_type TEXT, version TEXT, theme TEXT, "
                     "plugins TEXT, plugins_count INTEGER, db_name TEXT, db_user TEXT, "
                     "last_check TEXT)")
        # Un site peut changer de CMS ou en perdre un : on remplace, on n'empile pas.
        for i in trouves:
            conn.execute("DELETE FROM cms_sites WHERE domain=?", (i["domain"],))
            conn.execute("INSERT INTO cms_sites (domain,path,cms_type,version,theme,"
                         "plugins_count,last_check) VALUES (?,?,?,?,?,?,datetime('now'))",
                         (i["domain"], i["path"], i["type"], i["version"],
                          i["theme"], i["plugins"]))
        # Deux nettoyages, et le second manquait : sans lui, un site dont on
        # retire le CMS gardait sa ligne pour toujours — et si PLUS AUCUN site
        # n'avait de CMS, la purge était sautée entièrement.
        trouves_noms = {i["domain"] for i in trouves}
        perdus = [d for d in scannes if d not in trouves_noms]
        if perdus:
            conn.execute("DELETE FROM cms_sites WHERE domain IN (%s)"
                         % ",".join("?" * len(perdus)), perdus)
        # Un site retiré de l'hébergement n'a plus de contenu à décrire.
        if connus:
            conn.execute("DELETE FROM cms_sites WHERE domain NOT IN (%s)"
                         % ",".join("?" * len(connus)), connus)
        conn.commit(); conn.close()
    except Exception as e:
        logging.warning("[CMS] enregistrement : %s", e)
        return {"ok": False, "reason": str(e), "found": len(trouves)}
    if problemes:
        logging.warning("[CMS] %d racine(s) inexploitable(s) : %s",
                        len(problemes), " | ".join(problemes[:5]))
    return {"ok": True, "scanned": vus, "found": len(trouves),
            "user": _utilisateur_courant(), "problems": problemes,
            "inspected": inspectes,
            "cms": [{"domain": i["domain"], "type": i["type"], "version": i["version"],
                     "path": i.get("path", "")} for i in trouves],
            "reason": "" if trouves else
                      (("%d racine(s) inexploitable(s) — %s"
                        % (len(problemes), problemes[0])) if problemes else
                       "Aucun CMS reconnu. Chemins examinés (service : %s) :\n%s"
                       % (_utilisateur_courant(), "\n".join(inspectes[:10])))}


def site_cms(domain: str = "") -> dict:
    """CMS détecté et version — table collectée depuis toujours, jamais lue.

    `cms_sites` était remplie par le collecteur et n'apparaissait nulle part :
    un WordPress trois versions en retard ne se voyait pas."""
    try:
        conn = sqlite3.connect(DB_PATH, timeout=10)
        if domain:
            rows = conn.execute(
                "SELECT domain, cms_type, version, theme, plugins_count, path, last_check "
                "FROM cms_sites WHERE domain=? ORDER BY last_check DESC LIMIT 5",
                (_norm_domain(domain),)).fetchall()
        else:
            rows = conn.execute(
                "SELECT domain, cms_type, version, theme, plugins_count, path, last_check "
                "FROM cms_sites ORDER BY domain").fetchall()
        conn.close()
    except Exception as e:
        return {"ok": False, "reason": str(e), "cms": []}
    return {"ok": True, "cms": [{"domain": r[0], "type": r[1], "version": r[2],
                                 "theme": r[3], "plugins": r[4], "path": r[5],
                                 "last_check": r[6]} for r in rows]}


# ── Vignette d'un site ─────────────────────────────────────────────────────
# Une liste de domaines ne dit pas à quoi ressemble un site. Deux voies, dans
# cet ordre : une VRAIE capture si un navigateur sans affichage est installé,
# sinon l'image que le site publie lui-même pour les réseaux sociaux
# (`og:image`), sinon son icône. Aucun service tiers : la souveraineté du
# serveur interdit d'envoyer la liste des domaines chez un prestataire.
_THUMB_DIR = CASSANDRA_DATA_DIR + "/site_thumbs"
_THUMB_TTL = 24 * 3600
_THUMB_MAX = 600 * 1024
# Plusieurs moteurs, parce qu'un serveur n'a pas forcément Chromium — et que
# se limiter à un seul revient à n'en avoir aucun. Chacun sait rendre une page
# hors écran ; l'ordre va du plus fidèle au plus léger.
_THUMB_MOTEURS = (
    ("chromium", ("chromium", "chromium-browser", "google-chrome",
                  "google-chrome-stable", "chrome")),
    ("firefox", ("firefox", "firefox-esr")),
    ("wkhtmltoimage", ("wkhtmltoimage",)),
)
_THUMB_NAV_CACHE = [None]           # None = pas encore cherché, () = aucun


_THUMB_ECARTES = []          # moteurs vus mais inutilisables, avec le motif


def _est_snap(chemin: str) -> bool:
    """Un binaire fourni par snap est confiné par AppArmor.

    Constaté en production : `chromium` résolvait vers `/usr/bin/snap`, se
    lançait, puis mourait sur « Failed to write file : Permission denied » —
    le confinement lui interdit d'écrire hors de son bac à sable, et AUCUNE
    option de ligne de commande ne lève cela. Le détecter d'avance évite de
    croire qu'on a un moteur alors qu'il échouera toujours."""
    try:
        reel = os.path.realpath(chemin)
    except Exception:
        return False
    return reel.startswith("/snap/") or os.path.basename(reel) == "snap"


def _thumb_moteur() -> tuple:
    """(chemin, famille) du premier moteur de rendu UTILISABLE, ou ("", "")."""
    if _THUMB_NAV_CACHE[0] is not None:
        return _THUMB_NAV_CACHE[0]
    trouve, ecartes = ("", ""), []
    for famille, binaires in _THUMB_MOTEURS:
        for n in binaires:
            try:
                p = subprocess.run(["which", n], capture_output=True, text=True, timeout=5)
            except Exception:
                continue
            chemin = (p.stdout or "").strip()
            if p.returncode != 0 or not chemin:
                continue
            if _est_snap(chemin):
                ecartes.append("%s est fourni par snap (%s) : confiné par "
                               "AppArmor, il ne peut écrire aucun fichier hors "
                               "de son bac à sable." % (n, os.path.realpath(chemin)))
                continue
            trouve = (chemin, famille)
            break
        if trouve[0]:
            break
    _THUMB_ECARTES[:] = ecartes
    _THUMB_NAV_CACHE[0] = trouve
    return trouve


def _thumb_navigateur() -> str:
    return _thumb_moteur()[0]


_XVFB_CACHE = [None]


def _a_xvfb() -> bool:
    if _XVFB_CACHE[0] is None:
        try:
            p = subprocess.run(["which", "xvfb-run"], capture_output=True,
                               text=True, timeout=5)
            _XVFB_CACHE[0] = bool(p.returncode == 0 and (p.stdout or "").strip())
        except Exception:
            _XVFB_CACHE[0] = False
    return _XVFB_CACHE[0]


def _thumb_profil(nom: str) -> str:
    """Répertoire de profil inscriptible pour le moteur."""
    p = os.path.join(_THUMB_DIR, nom)
    try:
        os.makedirs(p, exist_ok=True)
        return p
    except Exception:
        # `tempfile` n'est pas importé globalement dans ce fichier : l'appeler
        # ici sans l'importer aurait levé un NameError sur le chemin de repli,
        # c'est-à-dire exactement quand tout va déjà mal.
        import tempfile as _tf
        p = os.path.join(_tf.gettempdir(), "cassandra-thumb-" + nom.lstrip("."))
        try:
            os.makedirs(p, exist_ok=True)
        except Exception:
            pass
        return p


# Deux écritures du mode sans affichage, et il faut les essayer TOUTES.
# `--headless=new` n'existe qu'à partir de Chrome 112 : une version antérieure
# l'ignore, démarre en mode fenêtré, ne trouve aucun écran et meurt sur
# « Failed To Create Data Directory » — un message qui ne parle pas du tout du
# vrai problème. `--headless` seul fonctionne partout, y compris sur les
# versions récentes où il désigne le nouveau moteur.
_THUMB_HEADLESS = ("--headless", "--headless=new")


def _thumb_commande(binaire: str, famille: str, url: str, dest: str,
                    variante: str = "--headless", profil: str = "") -> list:
    """Commande de capture. `dest` est un NOM DE FICHIER, pas un chemin absolu.

    Le gestionnaire de commandes sans affichage écrit relativement au répertoire
    courant et rejette un chemin absolu — d'où le « Failed to write file »
    observé en production. On lance donc le processus DANS le répertoire cible
    et on ne lui passe que le nom. Les autres moteurs s'en accommodent."""
    if famille == "chromium":
        # `--user-data-dir` et `--disable-dev-shm-usage` ne sont pas du confort :
        # lancé par systemd, le processus n'a pas forcément de HOME utilisable,
        # et Chromium refuse de démarrer sans répertoire de profil inscriptible.
        # Sur un serveur, /dev/shm est souvent minuscule, ce qui le fait planter
        # au rendu. Deux causes classiques d'échec muet.
        profil = profil or _thumb_profil(".profil")
        return [binaire, variante, "--disable-gpu", "--no-sandbox",
                "--disable-dev-shm-usage", "--user-data-dir=" + profil,
                "--crash-dumps-dir=" + profil, "--no-first-run",
                "--no-default-browser-check", "--disable-extensions",
                "--ignore-certificate-errors", "--hide-scrollbars",
                "--window-size=1000,625", "--screenshot=" + dest,
                "--virtual-time-budget=8000",
                "--default-background-color=ffffff", url]
    if famille == "firefox":
        return [binaire, "--headless", "--screenshot", dest,
                "--window-size=1000,625",
                "--profile", profil or _thumb_profil(".profil-ff"), url]
    # wkhtmltoimage tel qu'empaqueté par Debian et Ubuntu est bâti sur un Qt
    # NON corrigé : il réclame un serveur d'affichage et refuse de démarrer sans.
    # `xvfb-run` lui en fournit un virtuel. S'il est absent on tente quand même,
    # au cas où le binaire serait une version corrigée.
    cmd = [binaire, "--width", "1000", "--height", "625", "--quality", "70",
           "--javascript-delay", "2500", "--load-error-handling", "ignore",
           "--no-stop-slow-scripts", url, dest]
    if _a_xvfb():
        return ["xvfb-run", "-a", "--server-args=-screen 0 1024x768x24"] + cmd
    return cmd


def _thumb_capture(domain: str, dest: str) -> tuple:
    """Capture d'écran réelle. Rend (réussi, motif d'échec lisible).

    Le motif compte : une capture qui échoue en silence laisse croire qu'aucun
    moteur n'est installé, alors que c'est peut-être une police manquante ou
    un bac à sable refusé."""
    binaire, famille = _thumb_moteur()
    if not binaire:
        if _THUMB_ECARTES:
            return False, ("aucun moteur utilisable — %s" % " ".join(_THUMB_ECARTES))
        return False, ("aucun moteur de rendu installé "
                       "(chromium, firefox ou wkhtmltoimage)")
    url = "https://%s/" % domain
    dossier = os.path.dirname(dest) or "."
    nom = os.path.basename(dest)
    # HOME explicite : lancé par systemd, le processus n'en a pas forcément, et
    # certains moteurs écrivent encore hors du profil qu'on leur désigne.
    env = dict(os.environ)
    env.setdefault("HOME", _thumb_profil(".home"))
    # PROFIL UNIQUE PAR CAPTURE. Un profil partagé porte un verrou : deux
    # captures qui se suivent d'assez près se le disputent, et la seconde meurt
    # sur « Failed To Create Data Directory » — message qui ne parle jamais de
    # verrou. Observé en production : deux sites sur quatre réussissaient, les
    # deux autres échouaient, avec le MÊME binaire.
    import shutil as _sh, tempfile as _tf
    try:
        profil = _tf.mkdtemp(prefix="cass-thumb-", dir=_THUMB_DIR)
    except Exception:
        profil = _thumb_profil(".profil")
    variantes = _THUMB_HEADLESS if famille == "chromium" else ("",)
    p, derniere = None, ""
    try:
        for v in variantes:
            try:
                p = subprocess.run(
                    _thumb_commande(binaire, famille, url, nom, v, profil),
                    capture_output=True, text=True, timeout=45,
                    cwd=dossier, env=env)
            except subprocess.TimeoutExpired:
                derniere = "%s n'a pas rendu la page en 45 s" % famille
                continue
            except Exception as e:
                derniere = "%s : %s" % (famille, e)
                continue
            if os.path.isfile(dest) and os.path.getsize(dest) > 0:
                break
            # Une variante non comprise fait démarrer le moteur en mode fenêtré :
            # il meurt sur son répertoire de données sans parler d'affichage.
            derniere = "%s refusé" % (v or famille)
    finally:
        if profil.startswith(_THUMB_DIR) and "cass-thumb-" in profil:
            _sh.rmtree(profil, ignore_errors=True)
    if p is None:
        return False, derniere or "%s n'a pas pu être lancé" % famille
    if os.path.isfile(dest):
        taille = os.path.getsize(dest)
        if 0 < taille <= _THUMB_MAX:
            return True, ""
        os.unlink(dest)
        if taille == 0:
            return False, "%s a produit une image vide" % famille
        # Une capture trop lourde n'a pas sa place dans une réponse JSON.
        return False, ("capture de %d ko, au-delà de la limite de %d ko"
                       % (taille // 1024, _THUMB_MAX // 1024))
    lignes = [l.strip() for l in
              ((p.stderr or "") + "\n" + (p.stdout or "")).splitlines() if l.strip()]
    # La ligne utile n'est pas forcément la dernière : Chromium bavarde après
    # l'erreur. On privilégie celle qui porte le défaut, et on tronque assez
    # tard pour ne pas couper le chemin en cause — c'est lui qu'on cherche.
    utile = next((l for l in lignes if "Failed" in l or "ERROR" in l or "error" in l),
                 lignes[-1] if lignes else "")
    return False, ("%s n'a produit aucun fichier — %s"
                   % (famille, utile[:400] if utile else "sans message"))


# ── Captures déjà produites par FastPanel ──────────────────────────────────
# FastPanel fabrique ces vignettes pour sa propre interface et les dépose sur
# le disque. Les reprendre est la meilleure voie sur tous les plans : rien ne
# sort du serveur (le coût a déjà été payé, une fois, par FastPanel), le rendu
# est immédiat, et l'image est exactement celle que l'utilisateur voit dans son
# panneau. Chercher un moteur de rendu alors que le fichier existe déjà était
# une dépense inutile — je ne l'avais pas vu.
_FP_THUMB_DIRS = ("/usr/local/fastpanel2/web/public/screenshot",
                  "/usr/local/fastpanel/web/public/screenshot")


def _thumb_fastpanel(domain: str, dest: str) -> tuple:
    """Reprend la vignette produite par FastPanel. Rend (réussi, motif, âge_j)."""
    if not _mem_cfg("thumb_use_fastpanel", True):
        return False, "reprise FastPanel désactivée", None
    dn = _norm_domain(domain)
    for base in _FP_THUMB_DIRS:
        for motif in ("thumb-%s.png" % dn, "%s.png" % dn,
                      "thumb-%s.jpg" % dn, "%s.jpg" % dn):
            src = os.path.join(base, motif)
            try:
                if not os.path.isfile(src):
                    continue
                taille = os.path.getsize(src)
                if taille <= 0 or taille > _THUMB_MAX:
                    continue
                with open(src, "rb") as f:
                    data = f.read()
                with open(dest, "wb") as f:
                    f.write(data)
                with open(dest + ".type", "w") as f:
                    f.write("image/png" if motif.endswith(".png") else "image/jpeg")
                age = int((time.time() - os.path.getmtime(src)) // 86400)
                return True, "", age
            except Exception as e:
                logging.info("[VIGNETTE] %s : reprise FastPanel (%s)", dn, e)
                continue
    return False, "aucune vignette FastPanel pour ce domaine", None


# ── Capture par un service distant ─────────────────────────────────────────
# C'est la méthode de FastPanel : ses symboles (`screenshot/client.MakeScreenShot`,
# `newRequest`, `unmarshalBody`, `ScreenShotConsumer`) sont ceux d'un client HTTP,
# et aucun moteur de rendu n'apparaît dans son binaire. Il envoie l'adresse à un
# service qui lui renvoie l'image.
#
# Choix ASSUMÉ et explicite : le nom de domaine sort du serveur. On le dit à
# l'écran, on nomme le service, et un réglage coupe la voie.
_THUMB_SERVICES = {
    # {url} = adresse encodée pour un paramètre ; {url_brut} = adresse telle quelle.
    "mshots": "https://s.wordpress.com/mshots/v1/{url}?w=1000&h=625",
    "thumio": "https://image.thum.io/get/width/1000/crop/625/{url_brut}",
}
_THUMB_SERVICE_HOTE = {"mshots": "s.wordpress.com", "thumio": "image.thum.io"}
# En dessous de cette taille, l'image rendue est une attente, pas une capture :
# mShots répond immédiatement par un visuel gris pendant qu'il fabrique la vraie.
_THUMB_MIN_UTILE = 6000


def _thumb_service() -> tuple:
    """(gabarit, nom lisible) du service distant, ou ("", "") s'il est coupé."""
    choix = str(_mem_cfg("thumb_service", "mshots") or "").strip()
    if not choix or choix in ("none", "aucun", "off"):
        return "", ""
    if choix in _THUMB_SERVICES:
        return _THUMB_SERVICES[choix], _THUMB_SERVICE_HOTE.get(choix, choix)
    if "{url" in choix:          # gabarit personnalisé fourni par l'utilisateur
        try:
            return choix, urllib.parse.urlparse(choix).hostname or "service défini"
        except Exception:
            return choix, "service défini"
    return "", ""


def _thumb_distant(domain: str, dest: str) -> tuple:
    """Demande la capture à un service distant. Rend (réussi, motif, service)."""
    gabarit, hote = _thumb_service()
    if not gabarit:
        return False, "service distant désactivé", ""
    cible = "https://%s/" % domain
    url = gabarit.replace("{url_brut}", cible).replace(
        "{url}", urllib.parse.quote(cible, safe=""))
    dernier = ""
    # Ces services fabriquent l'image à la demande : la première réponse est
    # souvent un visuel d'attente. On redemande, sans insister éternellement.
    for essai in range(3):
        if essai:
            time.sleep(4)
        try:
            req = urllib.request.Request(
                url, headers={"User-Agent": "Cassandra/site-thumb",
                              "Accept": "image/*"})
            with urllib.request.urlopen(req, timeout=25) as r:
                ct = (r.headers.get("Content-Type") or "").split(";")[0].strip().lower()
                data = r.read(_THUMB_MAX + 1)
        except Exception as e:
            dernier = "%s : %s" % (hote, str(e)[:150])
            continue
        if not ct.startswith("image/"):
            dernier = "%s a répondu autre chose qu'une image (%s)" % (hote, ct or "?")
            continue
        if len(data) > _THUMB_MAX:
            dernier = "%s : image trop lourde (%d ko)" % (hote, len(data) // 1024)
            break
        if len(data) < _THUMB_MIN_UTILE and essai < 2:
            dernier = "%s fabrique encore l'image" % hote
            continue
        try:
            with open(dest, "wb") as f:
                f.write(data)
            with open(dest + ".type", "w") as f:
                f.write(ct)
            return True, "", hote
        except Exception as e:
            return False, "écriture impossible : %s" % e, hote
    return False, dernier or "%s n'a pas fourni d'image" % hote, hote


_OG_RE = re.compile(
    r"<meta[^>]+(?:property|name)\s*=\s*[\"'](og:image|twitter:image)[\"'][^>]*>", re.I)
_CONTENT_RE = re.compile(r"content\s*=\s*[\"']([^\"']+)[\"']", re.I)
_ICON_RE = re.compile(
    r"<link[^>]+rel\s*=\s*[\"'][^\"']*icon[^\"']*[\"'][^>]*>", re.I)
_HREF_RE = re.compile(r"href\s*=\s*[\"']([^\"']+)[\"']", re.I)


def _thumb_depuis_page(domain: str, dest: str) -> bool:
    """À défaut de capture : l'image que le site publie pour être partagé."""
    base = "https://%s/" % domain
    try:
        req = urllib.request.Request(base, headers={"User-Agent": "Cassandra/site-thumb"})
        with urllib.request.urlopen(req, timeout=10) as r:
            html = r.read(200000).decode("utf-8", "replace")
    except Exception as e:
        logging.info("[VIGNETTE] %s : page illisible (%s)", domain, e)
        return False
    candidats = []
    for m in _OG_RE.finditer(html):
        c = _CONTENT_RE.search(m.group(0))
        if c:
            candidats.append(c.group(1))
    for m in _ICON_RE.finditer(html):
        h = _HREF_RE.search(m.group(0))
        if h:
            candidats.append(h.group(1))
    candidats.append("/favicon.ico")
    for url in candidats:
        try:
            plein = urllib.parse.urljoin(base, url)
            # On ne suit que le site lui-même : une vignette n'a pas à faire
            # émettre une requête vers un domaine tiers choisi par la page.
            hote = urllib.parse.urlparse(plein).hostname or ""
            if not (hote == domain or hote.endswith("." + domain)):
                continue
            req = urllib.request.Request(plein, headers={"User-Agent": "Cassandra/site-thumb"})
            with urllib.request.urlopen(req, timeout=10) as r:
                ct = (r.headers.get("Content-Type") or "").split(";")[0].strip().lower()
                if not ct.startswith("image/"):
                    continue
                data = r.read(_THUMB_MAX + 1)
            if not data or len(data) > _THUMB_MAX:
                continue
            with open(dest, "wb") as f:
                f.write(data)
            with open(dest + ".type", "w") as f:
                f.write(ct)
            return True
        except Exception:
            continue
    return False


def site_thumbnail(domain: str, force: bool = False) -> dict:
    """Vignette d'un site, en data-URI (la CSP autorise déjà `data:`).

    Servir un fichier par une URL supposerait que la balise `<img>` porte le
    jeton de session, ce qu'elle ne sait pas faire. Le data-URI évite le
    problème, au prix de quelques dizaines de kilo-octets."""
    dn = _norm_domain(domain)
    if not dn or "/" in dn:
        return {"ok": False, "reason": "domaine invalide"}
    try:
        os.makedirs(_THUMB_DIR, exist_ok=True)
    except Exception as e:
        return {"ok": False, "reason": "dossier de vignettes indisponible : %s" % e}
    base = os.path.join(_THUMB_DIR, re.sub(r"[^a-z0-9.\-]", "_", dn))
    dest = base + ".png"
    age = None
    if os.path.isfile(dest):
        age = time.time() - os.path.getmtime(dest)
    if force or age is None or age > _THUMB_TTL:
        # Ordre délibéré, du moins coûteux au plus coûteux :
        # 1. la vignette que FastPanel a DÉJÀ produite — instantanée, locale ;
        # 2. notre propre capture — gratuite, rien ne sort du serveur ;
        # 3. un service distant — le domaine sort, choix assumé ;
        # 4. l'image publiée par le site, faute de mieux.
        source, service, motif = "fastpanel", "", ""
        ok, motif, age_fp = _thumb_fastpanel(dn, dest)
        if not ok:
            ok, motif = _thumb_capture(dn, dest)
            source = "capture"
        if not ok:
            logging.info("[VIGNETTE] %s : capture locale — %s", dn, motif)
            ok, motif_d, service = _thumb_distant(dn, dest)
            source = "distant"
            if not ok:
                logging.info("[VIGNETTE] %s : service distant — %s", dn, motif_d)
                motif = "%s ; %s" % (motif, motif_d)
        if not ok:
            ok = _thumb_depuis_page(dn, dest)
            source = "og:image"
        if not ok:
            return {"ok": False, "domain": dn,
                    "reason": "Aucun aperçu. Capture : %s. Le site ne publie "
                              "ni og:image ni icône." % motif,
                    "capture_error": motif,
                    "browser": bool(_thumb_navigateur()),
                    "engine": _thumb_moteur()[1]}
        try:
            with open(base + ".src", "w") as f:
                # On garde le motif d'échec ET le service à côté de la source :
                # sinon une image affichée laisse croire que tout va bien, alors
                # qu'il manque peut-être un moteur — ou que le domaine est sorti
                # du serveur sans que ce soit dit.
                f.write("%s\n%s\n%s" % (
                    source,
                    motif if source not in ("capture", "fastpanel") else "",
                    service or (("il y a %d j" % age_fp)
                                if source == "fastpanel" and age_fp is not None else "")))
        except Exception:
            pass
    try:
        with open(dest, "rb") as f:
            data = f.read(_THUMB_MAX + 1)
        if len(data) > _THUMB_MAX:
            return {"ok": False, "reason": "aperçu trop lourd"}
        ct = "image/png"
        if os.path.isfile(base + ".type"):
            with open(base + ".type") as f:
                ct = (f.read().strip() or ct)
        src, err, srv = "", "", ""
        if os.path.isfile(base + ".src"):
            with open(base + ".src") as f:
                lignes = f.read().splitlines()
            src = (lignes[0] if lignes else "").strip()
            err = (lignes[1] if len(lignes) > 1 else "").strip()
            srv = (lignes[2] if len(lignes) > 2 else "").strip()
        return {"ok": True, "domain": dn, "source": src, "capture_error": err,
                "service": srv, "engine": _thumb_moteur()[1],
                "age_s": int(time.time() - os.path.getmtime(dest)),
                "data_uri": "data:%s;base64,%s"
                            % (ct, base64.b64encode(data).decode())}
    except Exception as e:
        return {"ok": False, "reason": str(e)}


def _fp_site_id(domain: str) -> str:
    """Identifiant FastPanel d'un domaine, ou "". Casse et point final ignorés."""
    dn = _norm_domain(domain)
    if not dn:
        return ""
    for r in _fp_db_query("SELECT id FROM site WHERE lower(domain)=? LIMIT 1", (dn,)):
        if r and r[0]:
            return str(r[0])
    return ""


def site_screenshot_refresh(domain: str, acteur: str = "") -> dict:
    """Demande à FastPanel de REFAIRE l'aperçu d'un site, puis le récupère.

    Jusqu'ici Cassandra se contentait de lire l'image que le panneau avait bien
    voulu produire — parfois vieille de plusieurs semaines. `PUT
    /api/sites/{id}/screenshot` la fait régénérer pour un seul site ; `mogwai
    sites make_screenshot` reste en repli mais les refait TOUS, ce qui est long
    et inutile quand un seul nous intéresse."""
    dn = _norm_domain(domain)
    if not dn:
        return {"ok": False, "reason": "domaine invalide"}
    sid = _fp_site_id(dn)
    if not sid:
        return {"ok": False, "reason": "site « %s » inconnu du panneau" % dn}
    r = fp_api_call("PUT", "/api/sites/%s/screenshot" % sid, {})
    via = "API (site %s)" % sid
    if not r.get("ok"):
        m = fp_action_run("apercus_refaire", "", confirm=True, acteur=acteur)
        if not m.get("ok"):
            return {"ok": False, "domain": dn,
                    "reason": "ni l'API ni mogwai n'ont pu relancer la capture",
                    "detail": "API : %s ; mogwai : %s"
                              % (r.get("reason") or r.get("status"),
                                 m.get("reason") or m.get("output") or "échec")}
        via = "mogwai (tous les sites)"
    # FastPanel écrit l'image de façon asynchrone : sans cette attente, on
    # relirait l'ancienne et on croirait la commande sans effet.
    avant = None
    base = os.path.join(_THUMB_DIR, re.sub(r"[^a-z0-9.\-]", "_", dn)) + ".png"
    fp_dest = base + ".fp"
    for _ in range(10):
        time.sleep(1.0)
        ok, _motif, age = _thumb_fastpanel(dn, fp_dest)
        if ok and (age is None or age < 1):
            avant = age
            break
    try:
        if os.path.isfile(fp_dest):
            os.replace(fp_dest, base)
    except Exception as e:
        logging.info("[VIGNETTE] remplacement pour %s : %s", dn, e)
    v = site_thumbnail(dn, force=not os.path.isfile(base))
    try:
        log_admin_action(acteur or "", "site_screenshot", "OK" if v.get("ok") else "FAIL",
                         "site=%s via=%s" % (dn, via))
    except Exception as e:
        logging.debug("[AUDIT] %s", e)
    return {"ok": True, "domain": dn, "via": via, "frais": avant is not None,
            "data_uri": v.get("data_uri", ""), "source": v.get("source", ""),
            "output": "Aperçu régénéré pour %s (%s)." % (dn, via)
                      + ("" if avant is not None else
                         " FastPanel ne l'a pas encore réécrit — il apparaîtra "
                         "au prochain affichage.")}


def site_thumbs_refresh(force: bool = True) -> dict:
    """Recapture TOUS les sites et rend le détail, site par site.

    Le cache de 24 h était un piège : installer un moteur de rendu ne changeait
    rien à l'écran, puisque les vignettes déjà enregistrées restaient valides.
    Il fallait une action qui purge et recommence, en disant ce qui échoue."""
    brut, err = _sites_list_cached(True)
    if brut is None:
        return {"ok": False, "reason": err or "liste des sites indisponible"}
    # FastPanel sait refaire ses propres aperçus : le lui demander évite tout
    # moteur de rendu local et tout service tiers. C'est la voie la plus propre,
    # et elle n'existait pas dans mon code — je ne l'avais pas cherchée.
    regen = {}
    if force and _mem_cfg("thumb_ask_fastpanel", True):
        try:
            regen = fp_action_run("apercus_refaire", confirm=True, acteur="vignettes")
        except Exception as e:
            logging.info("[VIGNETTE] régénération FastPanel : %s", e)
    binaire, famille = _thumb_moteur()
    detail, captures, icones = [], 0, 0
    for s in brut:
        dn = _norm_domain(s.get("domain") or "")
        if not dn:
            continue
        r = site_thumbnail(dn, force=force)
        if r.get("ok"):
            src = r.get("source") or "?"
            if src in ("capture", "distant"):
                captures += 1
            else:
                icones += 1
            detail.append({"domain": dn, "ok": True, "source": src,
                           "service": r.get("service", ""),
                           "reason": r.get("capture_error", "")})
        else:
            detail.append({"domain": dn, "ok": False, "source": "",
                           "reason": r.get("reason") or r.get("capture_error", "")})
    if binaire:
        conseil = ""
    elif _THUMB_ECARTES:
        # Un snap ne se règle pas en ligne de commande : il faut un vrai paquet.
        conseil = ("Un moteur est présent mais inutilisable : %s\n"
                   "Installez un paquet non confiné : "
                   "apt install -y wkhtmltopdf xvfb"
                   % " ".join(_THUMB_ECARTES))
    else:
        conseil = ("Aucun moteur de rendu n'est installé sur le serveur : "
                   "apt install -y wkhtmltopdf xvfb")
    return {"ok": True, "engine": famille, "engine_path": binaire,
            "captures": captures, "icons": icones, "rejected": list(_THUMB_ECARTES),
            "xvfb": _a_xvfb(), "total": len(detail), "sites": detail,
            "fastpanel_regen": bool(regen.get("ok")),
            "hint": conseil}


def site_links_list(domain: str = "") -> dict:
    _site_migrate()
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        if domain:
            rows = conn.execute("SELECT domain,kind,ref,note,ts FROM site_links WHERE domain=? "
                                "ORDER BY kind,ts", (_norm_domain(domain),)).fetchall()
        else:
            rows = conn.execute("SELECT domain,kind,ref,note,ts FROM site_links "
                                "ORDER BY domain,kind,ts").fetchall()
        conn.close()
    except Exception as e:
        return {"ok": False, "reason": str(e), "links": []}
    return {"ok": True, "links": [{"domain": r[0], "kind": r[1], "ref": r[2],
                                   "note": r[3], "ts": r[4]} for r in rows]}


# Un site tourne SUR une machine : le lien « machine » relie cet onglet à la
# flotte, et permet de dire « le site est tombé parce que la machine est tombée ».
_SITE_LINK_KINDS = ("project", "contact", "machine", "note")


def site_link_save(domain: str, kind: str, ref: str, note: str = "") -> dict:
    _site_migrate()
    dn, k, r = _norm_domain(domain), (kind or "").strip(), str(ref or "").strip()
    if not dn or not r:
        return {"ok": False, "reason": "domaine et référence obligatoires"}
    if k not in _SITE_LINK_KINDS:
        return {"ok": False, "reason": "type de lien inconnu (%s)" % ", ".join(_SITE_LINK_KINDS)}
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        conn.execute("INSERT OR REPLACE INTO site_links (domain,kind,ref,note,ts) "
                     "VALUES (?,?,?,?,datetime('now'))", (dn, k, r, (note or "")[:300]))
        conn.commit(); conn.close()
        return {"ok": True}
    except Exception as e:
        return {"ok": False, "reason": str(e)}


def site_link_delete(domain: str, kind: str, ref: str) -> dict:
    _site_migrate()
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        conn.execute("DELETE FROM site_links WHERE domain=? AND kind=? AND ref=?",
                     (_norm_domain(domain), (kind or "").strip(), str(ref or "").strip()))
        conn.commit(); conn.close()
        return {"ok": True}
    except Exception as e:
        return {"ok": False, "reason": str(e)}


def _site_lien_projet(domain: str):
    _site_migrate()
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        r = conn.execute("SELECT ref FROM site_links WHERE domain=? AND kind='project' "
                         "ORDER BY ts LIMIT 1", (_norm_domain(domain),)).fetchone()
        conn.close()
        return int(r[0]) if r and str(r[0]).isdigit() else None
    except Exception:
        return None


def _site_lien_contacts(domain: str) -> list:
    _site_migrate()
    try:
        conn = sqlite3.connect(MEMORY_DB_PATH, timeout=10)
        refs = [r[0] for r in conn.execute(
            "SELECT ref FROM site_links WHERE domain=? AND kind='contact' ORDER BY ts",
            (_norm_domain(domain),))]
        conn.close()
    except Exception:
        return []
    noms = []
    for ref in refs:
        try:
            c = contact_get(ref)
            if c and c.get("ok") is not False:
                noms.append((c.get("contact") or c).get("name") or str(ref))
        except Exception:
            noms.append(str(ref))
    return noms


