def self_unblacklist(func, raison: str = "", acteur: str = "humain"):
    """Dégèle une fonction : la retire de la blacklist persistée (et en mémoire). Une cible
    TOXIQUE (D15) ne se dégèle qu'avec une justification écrite ; le dégel est chaîné."""
    if not func:
        return {"ok": False, "error": "fonction non précisée"}
    try:
        conn = get_db()
        r = conn.execute("SELECT reason FROM evolution_blacklist WHERE func_name=?", (func,)).fetchone()
        if r and str(r["reason"] or "").startswith("toxique") and not (raison or "").strip():
            conn.close()
            return {"ok": False, "error": "une cible toxique ne se dégèle qu'avec une justification écrite"}
        conn.execute("DELETE FROM evolution_blacklist WHERE func_name=?", (func,))
        dernier = conn.execute("SELECT COALESCE(MAX(id),0) FROM evolution_log").fetchone()[0]
        _evo_chaine_evenement(conn, "degel", 0, {"cible": func, "raison": (raison or "")[:200], "acteur": acteur,
                                                  "etait": (str(r["reason"])[:80] if r else ""), "dernier_id": int(dernier)})
        conn.commit()
        conn.close()
        try:
            with _EVO_BLACKLIST_LOCK:
                _EVO_BLACKLIST.discard(func)
        except Exception:
            pass
        return {"ok": True}
    except Exception as e:
        return {"ok": False, "error": str(e)}

