                if path == "/api/notes/version":
                    r = note_version_lire(str(data.get("ref", "")), str(data.get("version", "")))
                    self.send_json(r, 200 if r.get("ok") else 404); return
                if path == "/api/notes/revenir":
                    r = note_revenir(str(data.get("ref", "")), str(data.get("version", "")),
                                     acteur=_nt_compte())
                    self.send_json(r, 200 if r.get("ok") else 400); return
                if path == "/api/notes/fusionner":
                    r = note_fusionner(data.get("refs") or [], str(data.get("titre", "")),
                                       acteur=_nt_compte())
                    self.send_json(r, 200 if r.get("ok") else 400); return
                if path == "/api/notes/exporter":
                    r = note_exporter(str(data.get("ref", "")), str(data.get("format", "md")))
                    self.send_json(r, 200 if r.get("ok") else 404); return
                if path == "/api/notes/archive":
                    _a = notes_archive(str(data.get("portee", "tout")),
                                       str(data.get("dossier", "")),
                                       data.get("refs") or [])
                    if not _a.get("ok"):
                        self.send_json(_a, 400); return
                    # UNE ARCHIVE EST UN FICHIER, pas du JSON : `send_binary`
                    # la sert en pièce jointe, et refuse d'annoncer un type
                    # exécutable.
                    self.send_binary(_a["contenu"], "application/zip", _a["nom"])
                    return
                if path == "/api/notes/taches":
                    self.send_json(notes_taches(
                        bool(data.get("ouvertes_seules")))); return
                if path == "/api/notes/tache/rappel":
                    r = note_tache_rappel(str(data.get("ref", "")),
                                          data.get("ligne"),
                                          str(data.get("due", "")))
                    self.send_json(r, 200 if r.get("ok") else 400); return
                if path == "/api/notes/tache/basculer":
                    r = note_tache_sync(str(data.get("ref", "")),
                                        data.get("ligne"),
                                        bool(data.get("faite")))
                    self.send_json(r, 200 if r.get("ok") else 400); return
                if path == "/api/notes/jour":
                    self.send_json(note_du_jour(bool(data.get("creer")),
                                                str(data.get("jour", "")))); return
                if path == "/api/notes/mentions":
                    self.send_json(notes_mentions(str(data.get("ref", "")))); return
                if path == "/api/notes/partage/creer":
                    r = note_partage_creer(str(data.get("ref", "")),
                                           str(data.get("format", "html")),
                                           data.get("jours"),
                                           str(data.get("mdp", "")))
                    self.send_json(r, 200 if r.get("ok") else 400); return
                if path == "/api/notes/partages":
                    self.send_json(note_partages()); return
                if path == "/api/notes/partage/retirer":
                    r = note_partage_retirer(str(data.get("jeton", "")))
                    self.send_json(r, 200 if r.get("ok") else 400); return
                if path == "/api/notes/cibles":
                    self.send_json(notes_cibles(str(data.get("q", "")),
                                                int(data.get("limite", 300) or 300)))
                    return
                # RESOUDRE `[[...]]` SUR UN TEXTE NU. Une note connait ses
                # renvois parce que sa fiche les calcule ; une tache, un
                # rappel, un message n'ont pas de fiche. Le texte n'est ni lu
                # ni conserve : on n'en rend que les cibles.
                if path == "/api/notes/liens":
                    # UN LOT, OU UN SEUL TEXTE. Une demande par ligne affichee,
                    # c'est quarante demandes pour un ecran de quarante taches
                    # — et un ecran qui se remplit par a-coups.
                    _l = data.get("textes")
                    if isinstance(_l, list):
                        _lots = [note_liens_resolus(str(x or "")[:20000])
                                 for x in _l[:400]]
                        self.send_json({"ok": True, "lots": _lots})
                        return
                    _t = str(data.get("texte", ""))[:20000]
                    self.send_json({"ok": True, "liens": note_liens_resolus(_t)})
                    return
                if path == "/api/notes/inventaire":
                    self.send_json(liens_inventaire())
                    return
                if path == "/api/notes/de":
                    r = notes_de(str(data.get("kind", "")), str(data.get("ref", "")))
                    self.send_json(r, 200 if r.get("ok") else 400); return
                if path == "/api/notes/dossiers":
                    self.send_json(notes_dossiers()); return
                if path == "/api/notes/dossier/creer":
                    r = note_dossier_creer(str(data.get("chemin", "")))
                    self.send_json(r, 200 if r.get("ok") else 400); return
                if path == "/api/notes/dossier/renommer":
                    r = note_dossier_renommer(str(data.get("chemin", "")),
                                              str(data.get("nom", "")))
                    self.send_json(r, 200 if r.get("ok") else 400); return
                if path == "/api/notes/dossier/supprimer":
                    r = note_dossier_supprimer(str(data.get("chemin", "")))
                    self.send_json(r, 200 if r.get("ok") else 400); return
                if path == "/api/notes/ranger":
                    r = note_ranger(str(data.get("ref", "")),
                                    str(data.get("dossier", "")))
                    self.send_json(r, 200 if r.get("ok") else 400); return
                if path == "/api/notes/menage":
                    self.send_json(notes_menage()); return
                if path == "/api/ranger":
                    self.send_json(ranger_etat()); return
                if path == "/api/notes/reprise":
                    self.send_json(notes_reprise_public()); return
                if path == "/api/notes/migration":
                    self.send_json(notes_migration()); return
                # ── Le carnet ────────────────────────────────────────────────────
                if path == "/api/carnet/groupes":
                    self.send_json(ca_groupes()); return
                if path == "/api/carnet/lister":
                    self.send_json(ca_lister(str(data.get("groupe", "*")),
                                             str(data.get("q", "")),
                                             str(data.get("tri", "recent")),
                                             str(data.get("filtre", "toutes")))); return
                if path == "/api/carnet/fiche":
                    r = ca_fiche(str(data.get("ref", "")))
                    self.send_json(r, 200 if r.get("ok") else 404); return
                if path == "/api/carnet/ranger":
                    r = ca_ranger(str(data.get("ref", "")),
                                  etiquettes=data.get("etiquettes"),
                                  projet=data.get("projet"), acteur=_nt_compte())
                    self.send_json(r, 200 if r.get("ok") else 400); return
                if path == "/api/carnet/rattacher":
                    r = ca_rattacher(str(data.get("ref", "")), str(data.get("nature", "")),
                                     str(data.get("cible", "")), acteur=_nt_compte())
                    self.send_json(r, 200 if r.get("ok") else 400); return
                if path == "/api/carnet/detacher":
                    r = ca_detacher(str(data.get("ref", "")), str(data.get("brut", "")),
                                    acteur=_nt_compte())
                    self.send_json(r, 200 if r.get("ok") else 400); return
                if path == "/api/carnet/etat":
                    r = ca_etat_poser(str(data.get("ref", "")), str(data.get("etat", "")),
                                      acteur=_nt_compte())
                    self.send_json(r, 200 if r.get("ok") else 400); return
                if path == "/api/carnet/relire":
                    r = ca_relire_poser(str(data.get("ref", "")), str(data.get("quand", "")),
                                        acteur=_nt_compte())
                    self.send_json(r, 200 if r.get("ok") else 400); return
                if path == "/api/carnet/tache":
                    r = ca_tache_basculer(str(data.get("ref", "")), data.get("ligne"),
                                          acteur=_nt_compte())
                    self.send_json(r, 200 if r.get("ok") else 400); return
                if path == "/api/carnet/taches":
                    r = ca_taches_etat(str(data.get("ref", "")))
                    self.send_json(r, 200 if r.get("ok") else 404); return
                if path == "/api/carnet/taches/projeter":
                    r = ca_taches_projeter(str(data.get("ref", "")), acteur=_nt_compte())
                    self.send_json(r, 200 if r.get("ok") else 400); return
                if path == "/api/carnet/taches/reprendre":
                    r = ca_taches_reprendre(str(data.get("ref", "")), acteur=_nt_compte())
                    self.send_json(r, 200 if r.get("ok") else 400); return
                if path == "/api/carnet/migrer":
                    self.send_json(ca_memos_migrer()); return

                if path == "/api/carnet/postit":
                    self.send_json(ca_memos_restants()); return
                if path == "/api/carnet/postit/reprendre":
                    r = ca_memo_reprendre(data.get("id"), str(data.get("titre", "")))
                    self.send_json(r, 200 if r.get("ok") else 400); return
                # ── Le canvas ────────────────────────────────────────────────────
                if path == "/api/canvas/registre":
                    self.send_json({"ok": True, "departs": cv_departs(),
                                    "gestes": cv_gestes(),
                                    "familles": list(_CV_FAMILLES),
                                    "marqueurs": [_CV_VIV_DEB, _CV_VIV_FIN]}); return
                if path in ("/api/canvas/amorcer", "/api/canvas/geste"):
                    # Le modèle du COMPTE prime, comme pour /api/lab/chat. Sans
                    # cette résolution, la Conversation d'un compte employait son
                    # modèle et son Canvas retombait sur celui de la maison :
                    # deux Itare, deux modèles, dans le même onglet — et une
                    # rédaction facturée au fournisseur du serveur.
                    _ctok = (self.headers.get("X-Session-Token", "")
                             or data.get("session", ""))
                    _cu = get_session_user(_ctok) or ""
                    _cadm = is_admin(_cu)
                    _cmod = str(data.get("modele", "")).strip()
                    if not _cmod or _cmod == _ITARE_PRINCIPAL:
                        _mien = it_modele_lire(_cu)
                        if _mien:
                            _cmod = _mien
                    _csrc = data.get("sources") if isinstance(data.get("sources"), list) else []
                    if path == "/api/canvas/amorcer":
                        _crg = data.get("reglages")
                        r = cv_amorcer(str(data.get("depart", "")), _csrc,
                                       modele=_cmod, titre=str(data.get("titre", "")),
                                       admin=_cadm,
                                       reglages=(_crg if isinstance(_crg, dict) else None))
                    else:
                        r = cv_geste(str(data.get("geste", "")), str(data.get("passage", "")),
                                     modele=_cmod, sources=_csrc, admin=_cadm,
                                     autour=str(data.get("autour", "")))
                    self.send_json(r, 200 if r.get("ok") else 400); return
                # LES GESTES D'ITARE passent par la MÊME résolution de modèle
                # que l'amorce : un compte qui a choisi son modèle doit le voir
                # servir ici aussi, sinon deux Itare cohabitent dans un onglet.
                if path == "/api/canvas/itare":
                    _itok = (self.headers.get("X-Session-Token", "")
                             or data.get("session", ""))
                    _iu = get_session_user(_itok) or ""
                    _iadm = is_admin(_iu)
                    _imod = str(data.get("modele", "")).strip()
                    if not _imod or _imod == _ITARE_PRINCIPAL:
                        _mien2 = it_modele_lire(_iu)
                        if _mien2:
                            _imod = _mien2
                    _isrc = data.get("sources") if isinstance(data.get("sources"),
                                                              list) else []
                    _ig = str(data.get("geste", ""))
                    _ica = data.get("cartes") if isinstance(data.get("cartes"),
                                                            list) else []
                    if _ig == "cartes":
                        r = cv_it_cartes(_isrc, str(data.get("sujet", "")),
                                         _imod, admin=_iadm)
                    elif _ig == "liens":
                        r = cv_it_liens(_ica, _imod, admin=_iadm)
                    elif _ig == "trous":
                        r = cv_it_trous(_ica, str(data.get("plan", "")),
                                        _imod, admin=_iadm)
                    elif _ig == "relire":
                        r = cv_it_relire(str(data.get("corps", "")), _imod,
                                         admin=_iadm)
                    elif _ig == "sourcer":
                        r = cv_it_sourcer(str(data.get("corps", "")), _isrc,
                                          _imod, admin=_iadm)
                    else:
                        r = {"ok": False, "reason": "geste inconnu : %s" % _ig}
                    self.send_json(r, 200 if r.get("ok") else 400); return
                if path == "/api/canva/etat":
                    self.send_json(canva_etat()); return
                if path == "/api/canva/brancher":
                    # Le jeton de session voyage jusqu'à l'attente : c'est lui
                    # qu'on revérifiera au retour, dix minutes plus tard.
                    _r = canva_brancher(
                        self.headers.get("X-Session-Token", "")
                        or str(data.get("session", "")))
                    self.send_json(_r, 200 if _r.get("ok") else 400); return
                if path == "/api/canva/debrancher":
                    self.send_json(canva_debrancher()); return
                if path == "/api/canva/sante":
                    self.send_json(canva_sante()); return
                if path == "/api/canva/reconcilier":
                    _r = canva_reconcilier(lot=int(data.get("lot", 0) or 0))
                    self.send_json(_r, 200 if _r.get("ok") else 400); return
                if path == "/api/canva/designs":
                    _r = canva_designs()
                    self.send_json(_r, 200 if _r.get("ok") else 400); return
                if path == "/api/canva/creer":
                    _r = canva_design_creer(
                        str(data.get("titre", "")), str(data.get("ref", "")),
                        str(data.get("corps", "")), data.get("rubriques"))
                    self.send_json(_r, 200 if _r.get("ok") else 400); return
                if path == "/api/canva/lire":
                    _r = canva_design_lire(str(data.get("id", "")))
                    self.send_json(_r, 200 if _r.get("ok") else 400); return
                if path == "/api/canva/titrer":
                    _r = canva_design_titrer(str(data.get("id", "")),
                                             str(data.get("titre", "")))
                    # UN REFUS DE PORTÉE N'EST PAS UNE PANNE : 403, pour qu'il
                    # se distingue d'un Canva injoignable.
                    self.send_json(_r, 200 if _r.get("ok")
                                   else (403 if _r.get("hors_portee") else 400))
                    return
                if path == "/api/canvas/ext/apercu":
                    self.send_json(cv_ext_apercu(str(data.get("corps", "")),
                                                 data.get("rubriques")))
                    return
                if path == "/api/canvas/ext/lister":
                    self.send_json(cv_ext_lister(str(data.get("ref", "")),
                                                 str(data.get("corps", ""))))
                    return
                if path == "/api/canvas/ext/etat":
                    r = cv_ext_etat(data.get("id"), str(data.get("etat", "")))
                    self.send_json(r, 200 if r.get("ok") else 400); return
                if path == "/api/canvas/sorties":
                    self.send_json(cv_sorties(str(data.get("ref", "")),
                                              str(data.get("corps", ""))))
                    return
                if path == "/api/canvas/sortir":
                    r = cv_sortir(str(data.get("ref", "")), str(data.get("quoi", "")),
                                  str(data.get("texte", "")),
                                  str(data.get("projet", "")),
                                  str(data.get("quand", "")), acteur=_nt_compte())
                    self.send_json(r, 200 if r.get("ok") else 400); return
                if path == "/api/canvas/portes":
                    # CE QUI EST PRÊT, ET CE QUI MANQUE. Une porte cachée fait
                    # croire qu'elle n'existe pas ; une porte muette fait
                    # chercher le défaut ailleurs.
                    _pt = []
                    for _k, _n2, _ic, _d2 in _CV_PORTES:
                        _ok, _pq = True, ""
                        if _k == "coffre":
                            _ok = bool(_cf_racines())
                            _pq = ("aucune racine à forme « coffre » ne vous est "
                                   "attribuée — Documents → source → ◈")
                        elif _k == "ged":
                            _ok = bool(_ged_racines())
                            _pq = "aucune source de documents ne vous est attribuée"
                        _pt.append({"cle": _k, "n": _n2, "ic": _ic, "d": _d2,
                                    "dispo": _ok, "pourquoi": "" if _ok else _pq})
                    self.send_json({"ok": True, "portes": _pt}); return
                if path == "/api/canvas/importer":
                    r = cv_importer(str(data.get("porte", "")),
                                    str(data.get("valeur", "")),
                                    str(data.get("titre", "")))
                    self.send_json(r, 200 if r.get("ok") else 400); return
                if path == "/api/canvas/plan/lire":
                    self.send_json(cv_plan_lire(str(data.get("ref", ""))))
                    return
                if path == "/api/canvas/plan/ecrire":
                    r = cv_plan_ecrire(str(data.get("ref", "")), data.get("plan"))
                    self.send_json(r, 200 if r.get("ok") else 400); return
                if path == "/api/canvas/relier":
                    self.send_json(cv_relier(str(data.get("corps", "")))); return
                if path == "/api/canvas/vivante/poser":
                    r = cv_vivante_poser(str(data.get("ref", "")),
                                         str(data.get("requete", "")), acteur=_nt_compte())
                    self.send_json(r, 200 if r.get("ok") else 400); return
                if path == "/api/canvas/vivante/rejouer":
                    r = cv_vivante_rejouer(str(data.get("ref", "")), acteur=_nt_compte())
                    self.send_json(r, 200 if r.get("ok") else 400); return
                if path == "/api/pj/cadrage/proposer":
                    r = pj_cadrage_proposer(data.get("id"), data.get("reponses") or {})
                    self.send_json(r, 200 if r.get("ok") else 404); return
                if path == "/api/pj/cadrage/appliquer":
                    r = pj_cadrage_appliquer(data.get("id"), data.get("propositions") or [],
                                             acteur=get_session_user(
                                                 self.headers.get("X-Session-Token", "")) or "")
                    self.send_json(r, 200 if r.get("ok") else 400); return
                # ── Tâches ──
                if path == "/api/itare/tasks":
                    self.send_json({"ok": True, "tasks": itare_task_list(
                        project_id=data.get("project_id"),
                        include_done=bool(data.get("include_done", False)),
                        limit=int(data.get("limit", 200) or 200),
                        racines_seules=bool(data.get("racines_seules", False))),
                        "projects": [{"id": p["id"], "name": p.get("name", "")}
                                     for p in (pj_projets() or [])]}); return
                if path == "/api/itare/task/save":
                # Un champ absent du corps vaut « inchangé », pas « vidé » :
                # la fiche envoie ce qu'on a touché, pas son écran entier.
                    def _opt(k):
                        return data[k] if k in data else None
                    # Le TITRE et les NOTES sont du texte ÉCRIT : on les lit dans le
                    # corps BRUT, pas dans la version assainie — `sanitize_data`
                    # échappe le HTML (« ' » → « &#x27; »), et le ré-échapper à
                    # chaque écriture corrompait le titre (« &amp;amp;#x27; »…).
                    _brut_t = _brut_req.get("text") if isinstance(_brut_req, dict) else None
                    _brut_n = _brut_req.get("notes") if isinstance(_brut_req, dict) else None
                    r = itare_task_save(str(_brut_t if _brut_t is not None else data.get("text", "")),
                                        project_id=data.get("project_id"),
                                        due=_opt("due"), status=data.get("status"),
                                        tid=data.get("id"),
                                        notes=(_brut_n if _brut_n is not None else _opt("notes")),
                                        priority=_opt("priority"), parent_id=_opt("parent_id"),
                                        recurrence=_opt("recurrence"), charge=_opt("charge"),
                                        alarm=_opt("alarm"), acteur=_ru,
                                        avancement=_opt("avancement"),
                                        raison=(_brut_req.get("raison") if isinstance(_brut_req, dict) and "raison" in _brut_req else None),
                                        responsable=_opt("responsable"), etape_id=_opt("etape_id"))
                    self.send_json(r, 200 if r.get("ok") else 400); return
                if path == "/api/itare/task/creneau":
                    r = itare_task_creneau(data.get("id"), str(data.get("date", "")), str(data.get("heure", "09:00")),
                                           int(data.get("minutes") or 60))
                    self.send_json(r, 200 if r.get("ok") else 400); return
                if path == "/api/itare/task/context":
                    r = itare_task_context(data.get("id"))
                    self.send_json(r, 200 if r.get("ok") else 404); return
                if path == "/api/itare/task/link":
                    r = itare_task_link(data.get("id"), data.get("kind", ""),
                                        data.get("ref", ""), data.get("label", ""))
                    self.send_json(r, 200 if r.get("ok") else 400); return
                if path == "/api/itare/task/unlink":
                    r = itare_task_unlink(data.get("id"), data.get("kind", ""), data.get("ref", ""))
                    self.send_json(r, 200 if r.get("ok") else 400); return
                if path == "/api/itare/task/delete":
                    r = itare_task_delete(data.get("id"))
                    self.send_json(r, 200 if r.get("ok") else 400); return
                # ── Itare branché sur le projet ──
                if path == "/api/itare/project/ask":
                    r = itare_project_ask(data.get("id"), str(data.get("question", "")))
                    self.send_json(r, 200 if r.get("ok") else 400); return
                if path == "/api/itare/project/suggest":
                    r = itare_project_suggest_tasks(data.get("id"))
                    self.send_json(r, 200 if r.get("ok") else 400); return
                if path == "/api/itare/project/search":
                    r = itare_project_search(data.get("id"), str(data.get("q", "")))
                    self.send_json(r, 200 if r.get("ok") else 400); return
                # ── Agenda local : saisie manuelle et import iCal ──
                if path == "/api/itare/events":
                # `items` = vue unifiée (événements + tâches datées + rappels).
                # `events` reste servi pour la compatibilité des appelants existants.
                    _f, _t = str(data.get("from", "")), str(data.get("to", ""))
                    self.send_json({"ok": True, "events": itare_event_list(_f, _t),
                                    "items": itare_calendar_items(_f, _t),
                                    # LOT 7 (B45) : l'écran doit dire si l'agenda distant est branché.
                                    "distant": bool((_caldav_creds() or ("",))[0])}); return
                if path == "/api/itare/event/save":
                    r = itare_event_save(str(data.get("summary", "")), str(data.get("start_at", "")),
                                         end_at=str(data.get("end_at", "")),
                                         description=str(data.get("description", "")),
                                         location=str(data.get("location", "")),
                                         all_day=data.get("all_day", 0), eid=data.get("id"),
                                         project_id=data.get("project_id"),
                                         recurrence=str(data.get("recurrence", "")),
                                         alarm=str(data.get("alarm", "")),
                                         url=str(data.get("url", "")),
                                         origine=str(data.get("origine", "")), acteur=_ru)
                    self.send_json(r, 200 if r.get("ok") else 400); return
                if path == "/api/itare/event/prep":
                    r = itare_event_prep_add(data.get("id"), str(data.get("text", "")),
                                             due=str(data.get("due", "")))
                    self.send_json(r, 200 if r.get("ok") else 400); return
                # ── GED : documents, règles de classement, distants ──
                # LA BOÎTE DU COMPTE, AVANT LES ROUTES DES DOCUMENTS (18-09). Elle était
                # posée plus bas, après que ce bloc a déjà répondu : la GED interrogeait
                # la boîte « ? », le diagnostic disait « aucune pièce pour le compte ? »
                # et rien ne s'extrayait jamais.
                if path.startswith("/api/ged"):
                    _mtok = self.headers.get("X-Session-Token", "") or data.get("session", "")
                    mail_utilisateur_courant(get_session_user(_mtok) or "")
                if path == "/api/ged/sources":
                    self.send_json(ged_sources()); return
