                if path == "/api/itare/contact/of":
                    self.send_json({"ok": True,
                                    "contacts": contacts_of(str(data.get("kind", "")),
                                                            str(data.get("ref", "")))}); return
                if path == "/api/itare/contact/merge":
                    # LES DEUX ORTHOGRAPHES : la scène Doublons envoyait `src_id`/`dst_id`, la
                    # route lisait `src`/`dst` — « identifiants invalides » à chaque clic.
                    _mr = contact_merge(data.get("src", data.get("src_id")),
                                        data.get("dst", data.get("dst_id")), compte=_ru)
                    self.send_json(_mr, 200 if _mr.get("ok") else 400); return
                if path == "/api/itare/contact/duplicates":
                    self.send_json(contact_duplicates()); return
                if path == "/api/itare/contact/vcard/import":
                    _vr = contact_vcard_import(str(data.get("text", "")))
                    self.send_json(_vr, 200 if _vr.get("ok") else 400); return
                if path == "/api/itare/contact/vcard/export":
                    self.send_binary(vcard_export(data.get("ids")).encode("utf-8"),
                                     "text/vcard", "contacts.vcf"); return
                if path == "/api/itare/contact/propositions":
                    self.send_json(contact_propositions(data.get("id"))); return
                if path == "/api/itare/contact/relance":
                    self.send_json(contact_stale_pass(int(data.get("days", 21) or 21))); return
                if path == "/api/itare/contact/autolink":
                    self.send_json(contact_autolink_pass()); return
                if path == "/api/itare/contact/privacy":
                    if "notes_to_remote" in (data or {}):
                        _c = get_cassandra_config()
                        _c["contact_notes_to_remote"] = bool(data.get("notes_to_remote"))
                        save_cassandra_config(_c)
                    self.send_json(contact_privacy_state()); return
                if path == "/api/itare/mail/tech":
                    self.send_json(mail_tech_pass()); return
                if path == "/api/itare/mail/rules":
                    self.send_json({"ok": True, "rules": mail_rules_list()}); return
